//! Python bindings for the Scrutate engines (PyO3, stable ABI).
//!
//! Rules this module follows (see docs/TRACEABILITY.md, section 13):
//! * every long-running engine call runs with the GIL released (`Python::detach`), so Python
//!   threads can drive the engines in parallel;
//! * Engine A results stream through a bounded channel from the search thread and are converted
//!   to Python objects one batch at a time: a search over millions of lines never materialises
//!   a giant list unless the caller builds one;
//! * no Python runtime is needed by the core crate: this crate is an optional workspace member.

use std::collections::VecDeque;
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{mpsc, Arc, Mutex, MutexGuard};
use std::time::Duration;

use pyo3::exceptions::{PyFileNotFoundError, PyOSError, PyRuntimeError, PyValueError};
use pyo3::prelude::*;
use pyo3::types::{PyDict, PyList, PyType};

use scrutate::instant::{self, Files, Output, Pattern, Query, Record};
use scrutate::ops::{Answer, Op};
use scrutate::session::{Every, Session};

fn err<E: std::fmt::Display>(e: E) -> PyErr {
    PyRuntimeError::new_err(e.to_string())
}

/// A lock, also after a panic in an earlier call, so one failed call does not make every later
/// call fail.
fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {
    m.lock().unwrap_or_else(|e| e.into_inner())
}

/// Wait for the next message without the GIL, checking for Ctrl-C every 100 ms.
/// -> None once the sender is gone.
fn wait<T: Send>(py: Python<'_>, rx: &Mutex<mpsc::Receiver<T>>) -> PyResult<Option<T>> {
    loop {
        match py.detach(|| lock(rx).recv_timeout(Duration::from_millis(100))) {
            Ok(v) => return Ok(Some(v)),
            Err(mpsc::RecvTimeoutError::Disconnected) => return Ok(None),
            Err(mpsc::RecvTimeoutError::Timeout) => py.check_signals()?,
        }
    }
}

/// One matching (or context) line from Engine A.
#[pyclass(frozen, get_all, module = "scrutate")]
#[derive(Clone)]
pub struct Match {
    pub path: String,
    pub line: u64,
    pub column: u64,
    pub text: String,
    pub spans: Vec<(usize, usize)>,
    pub context: bool,
}

#[pymethods]
impl Match {
    fn __repr__(&self) -> String {
        format!("Match({}:{}: {:?})", self.path, self.line, self.text)
    }
}

impl Match {
    /// A matching or context line; None for a note on a file.
    fn of(r: Record) -> Option<Match> {
        let (h, context) = match r {
            Record::Match(h) => (h, false),
            Record::Context(h) => (h, true),
            _ => return None,
        };
        Some(Match {
            path: h.path.to_string(),
            line: h.line,
            column: h.column,
            text: h.text,
            spans: h.spans,
            context,
        })
    }
}

/// One ranked result (a function, class, module header or text window) from Engine B.
#[pyclass(frozen, get_all, module = "scrutate")]
#[derive(Clone)]
pub struct Hit {
    pub path: String,
    pub start: i64,
    pub end: i64,
    pub name: String,
    pub qualname: String,
    pub kind: String,
    pub score: f64,
    pub text: String,
}

#[pymethods]
impl Hit {
    fn __repr__(&self) -> String {
        format!(
            "Hit({}:{}-{} [{}] {} score={:.3})",
            self.path, self.start, self.end, self.kind, self.qualname, self.score
        )
    }
}

impl From<scrutate::search::Hit> for Hit {
    fn from(h: scrutate::search::Hit) -> Hit {
        Hit {
            path: h.path,
            start: h.start,
            end: h.end,
            name: h.name,
            qualname: h.qualname,
            kind: h.kind,
            score: h.score,
            text: h.text,
        }
    }
}

fn value_err(e: anyhow::Error) -> PyErr {
    PyValueError::new_err(e.to_string())
}

/// A JSON value as the Python object `json.loads` makes of it.
fn to_py<'py>(py: Python<'py>, v: &serde_json::Value) -> PyResult<Bound<'py, PyAny>> {
    py.import("json")?.call_method1("loads", (v.to_string(),))
}

/// (path, text) of each file whose search a NUL byte stopped after a match.
type Notes = Vec<(String, String)>;

/// Streaming result of `grep`: a Python iterator over `Match` objects fed by a background search
/// thread. Dropping it (or calling `cancel()`) stops the search.
#[pyclass(module = "scrutate")]
pub struct GrepIter {
    /// behind a mutex only to satisfy `Sync` (a pyclass may be shared across Python threads);
    /// `__next__` takes `&mut self`, so the lock is never contended
    rx: Option<Mutex<mpsc::Receiver<Vec<Match>>>>,
    buf: VecDeque<Match>,
    cancel: Arc<AtomicBool>,
    handle: Option<std::thread::JoinHandle<anyhow::Result<(instant::Stats, Notes)>>>,
    stats: Option<instant::Stats>,
    /// files whose search a NUL byte stopped after a match: (path, what happened)
    notes: Vec<(String, String)>,
    error: Option<String>,
}

impl GrepIter {
    fn finish(&mut self) {
        if let Some(h) = self.handle.take() {
            match h.join() {
                Ok(Ok((st, notes))) => {
                    self.stats = Some(st);
                    self.notes = notes;
                }
                Ok(Err(e)) => self.error = Some(e.to_string()),
                Err(_) => self.error = Some("search thread panicked".into()),
            }
        }
    }
}

#[pymethods]
impl GrepIter {
    fn __iter__(slf: PyRef<'_, Self>) -> PyRef<'_, Self> {
        slf
    }

    fn __next__(mut slf: PyRefMut<'_, Self>, py: Python<'_>) -> PyResult<Option<Match>> {
        if let Some(h) = slf.buf.pop_front() {
            return Ok(Some(h));
        }
        let this = &mut *slf;
        let Some(rx) = this.rx.as_ref() else {
            return Ok(None);
        };
        let batch = wait(py, rx).inspect_err(|_| {
            this.cancel.store(true, Ordering::Relaxed);
            this.rx = None;
            this.buf.clear();
        })?;
        match batch {
            Some(b) => {
                this.buf.extend(b);
                Ok(this.buf.pop_front())
            }
            None => {
                this.rx = None;
                this.finish();
                if let Some(e) = this.error.take() {
                    return Err(err(e));
                }
                Ok(None)
            }
        }
    }

    /// Stop the search; remaining results are discarded.
    fn cancel(&mut self) {
        self.cancel.store(true, Ordering::Relaxed);
        self.rx = None;
        self.buf.clear();
        self.finish();
    }

    /// Statistics of a finished search (files searched/matched, matches, bytes, elapsed ms,
    /// cancelled), and `notes`: (path, text) of each file whose search a NUL byte stopped.
    fn stats<'py>(&mut self, py: Python<'py>) -> PyResult<Option<Bound<'py, PyDict>>> {
        if self.rx.is_some() {
            return Ok(None); // still running
        }
        self.finish();
        match &self.stats {
            None => Ok(None),
            Some(st) => {
                let d = PyDict::new(py);
                d.set_item("files_searched", st.files_searched)?;
                d.set_item("files_matched", st.files_matched)?;
                d.set_item("matches", st.matches)?;
                d.set_item("bytes_searched", st.bytes_searched)?;
                d.set_item("errors", st.errors)?;
                d.set_item("elapsed_ms", st.elapsed_ms)?;
                d.set_item("cancelled", st.cancelled)?;
                d.set_item("notes", self.notes.clone())?;
                Ok(Some(d))
            }
        }
    }
}

impl Drop for GrepIter {
    /// The search thread stops at its next cancel check; joining it here would hold up a
    /// Ctrl-C for as long as one line takes to match.
    fn drop(&mut self) {
        self.cancel.store(true, Ordering::Relaxed);
        self.rx = None;
    }
}

/// Engine A: search `paths` for `pattern` without any index.
///
/// mode: "regex" (default), "literal", "identifier" (every casing of an identifier) or "fuzzy"
/// (within `fuzzy_edits` edits). Returns an iterator of `Match`, in the order the files are
/// searched, or in path and line order with `sort=True` (the first match then waits for the
/// whole search).
#[pyfunction]
#[pyo3(signature = (pattern, paths=vec![".".to_string()], *, mode="regex", case="sensitive", word=false, multiline=false,
                    invert=false, hidden=false, no_ignore=false, follow_links=false, globs=vec![], types=vec![],
                    max_filesize=None, max_depth=None, max_count=None, max_results=None, before=0, after=0, threads=0, fuzzy_edits=1,
                    sort=false))]
#[allow(clippy::too_many_arguments)]
fn grep(
    pattern: String,
    paths: Vec<String>,
    mode: &str,
    case: &str,
    word: bool,
    multiline: bool,
    invert: bool,
    hidden: bool,
    no_ignore: bool,
    follow_links: bool,
    globs: Vec<String>,
    types: Vec<String>,
    max_filesize: Option<u64>,
    max_depth: Option<usize>,
    max_count: Option<u64>,
    max_results: Option<u64>,
    before: usize,
    after: usize,
    threads: usize,
    fuzzy_edits: u8,
    sort: bool,
) -> PyResult<GrepIter> {
    let q = Query {
        pattern: Pattern {
            text: pattern,
            mode: scrutate::ops::mode_named(mode, fuzzy_edits).map_err(value_err)?,
            case: scrutate::ops::case_named(case).map_err(value_err)?,
            word,
            multiline,
            ..Pattern::default()
        },
        invert,
        max_count,
        max_results,
        before,
        after,
        want_spans: true,
        text_spans: true,
        ..Query::default()
    };
    // errors surface at call time, not at the first `next()`
    instant::build_matcher(&q.pattern).map_err(|e| PyValueError::new_err(e.to_string()))?;
    let roots: Vec<PathBuf> = paths.iter().map(PathBuf::from).collect();
    let Some(first) = roots.first().cloned() else {
        return Err(PyValueError::new_err("no paths to search"));
    };
    let f = Files {
        hidden,
        no_ignore,
        follow_links,
        globs,
        types,
        max_filesize,
        max_depth,
        threads,
        ..Files::walk(roots)
    };
    instant::overrides(&first, &f).map_err(|e| PyValueError::new_err(format!("{e:#}")))?;
    // an unknown type is the call's error, not the first next()'s
    instant::file_types(&f).map_err(|e| PyValueError::new_err(format!("{e:#}")))?;
    if let instant::Paths::Walk(roots) = &f.paths {
        if let Some(r) = roots.iter().find(|r| std::fs::metadata(r).is_err()) {
            return Err(PyFileNotFoundError::new_err(format!(
                "no such file or directory: {}",
                r.display()
            )));
        }
    }
    let cancel = Arc::new(AtomicBool::new(false));
    let (tx, rx) = mpsc::sync_channel::<Vec<Match>>(64); // bounded: a slow consumer throttles the search
    let c2 = Arc::clone(&cancel);
    let handle = std::thread::Builder::new()
        .name("scrutate-grep".into())
        .spawn(move || {
            let mut batch: Vec<Match> = Vec::with_capacity(256);
            let mut notes = Vec::new();
            let tx2 = tx.clone();
            let c3 = Arc::clone(&c2);
            let st = instant::search(
                &q,
                &f,
                Arc::clone(&c2),
                Output::Records(&mut |r| {
                    if let Record::Note { path, text, .. } = &r {
                        notes.push((path.to_string(), text.clone()));
                    }
                    batch.extend(Match::of(r));
                    if !sort && batch.len() >= 256 && tx2.send(std::mem::take(&mut batch)).is_err()
                    {
                        c3.store(true, Ordering::Relaxed); // consumer gone
                    }
                }),
            );
            if sort {
                batch.sort_by(|a, b| a.path.cmp(&b.path).then(a.line.cmp(&b.line)));
                let mut it = batch.into_iter().peekable();
                while it.peek().is_some() {
                    if tx.send(it.by_ref().take(256).collect()).is_err() {
                        break;
                    }
                }
            } else if !batch.is_empty() {
                let _ = tx.send(batch);
            }
            st.map(|st| (st, notes))
        })
        .map_err(err)?;
    Ok(GrepIter {
        rx: Some(Mutex::new(rx)),
        buf: VecDeque::new(),
        cancel,
        handle: Some(handle),
        stats: None,
        notes: Vec::new(),
        error: None,
    })
}

/// Engine B: a repository's persistent code-intelligence index.
#[pyclass(module = "scrutate")]
pub struct Repo {
    root: PathBuf,
    /// shared with the thread of an `index()` call, which outlives a Ctrl-C
    session: Arc<Session>,
}

fn hits_py(hits: Vec<scrutate::search::Hit>) -> Vec<Hit> {
    hits.into_iter().map(Into::into).collect()
}

/// `items` as a `Results` list whose `stopped_at` is the limit the answer stopped at when there
/// were more, as the CLI and the MCP tools report it.
fn results<'py, T: IntoPyObject<'py>>(
    py: Python<'py>,
    items: Vec<T>,
    stopped: Option<scrutate::ops::Stop>,
) -> PyResult<Bound<'py, PyAny>> {
    let stopped_at = stopped.map(|s| s.at);
    let out = py
        .import("scrutate._native")?
        .getattr("Results")?
        .call1((items,))?;
    out.setattr("stopped_at", stopped_at)?;
    Ok(out)
}

impl Repo {
    /// Run one operation with the GIL released, on an index brought up to date at most once a
    /// second, as the MCP server runs a tool call (`Session::run`). Calls from several Python
    /// threads run side by side.
    fn run(&self, py: Python<'_>, op: Op) -> PyResult<Answer> {
        py.detach(move || self.session.run(&op, &Arc::default()))
            .map_err(err)
    }
}

/// An answer of another kind than its operation gives: a bug.
fn unexpected() -> PyErr {
    PyRuntimeError::new_err("internal failure: an operation gave an answer of another kind")
}

#[pymethods]
impl Repo {
    /// Open (creating if needed) the index of the repository at `root`.
    #[new]
    fn new(py: Python<'_>, root: &str) -> PyResult<Self> {
        let root = PathBuf::from(root);
        let r2 = root.clone();
        let s = py
            .detach(move || Session::open(&r2, Every::given(None)))
            .map_err(err)?;
        Ok(Repo {
            root,
            session: Arc::new(s),
        })
    }

    #[getter]
    fn root(&self) -> String {
        self.root.to_string_lossy().into_owned()
    }

    /// Bring the index up to date (incremental: only changed files are parsed). GIL released.
    /// Ctrl-C returns at once and stops the update at its next batch of files; the index stays
    /// as it was before the call.
    #[pyo3(signature = (force=false))]
    fn index<'py>(&self, py: Python<'py>, force: bool) -> PyResult<Bound<'py, PyDict>> {
        let (tx, rx) = mpsc::channel();
        let session = Arc::clone(&self.session);
        let cancel = Arc::new(AtomicBool::new(false));
        let c2 = Arc::clone(&cancel);
        std::thread::Builder::new()
            .name("scrutate-index".into())
            .spawn(move || {
                let _ = tx.send(session.write(|repo| {
                    repo.update_until(force, c2)
                        .map(|up| up.code.unwrap_or_default())
                }));
            })
            .map_err(err)?;
        let st = wait(py, &Mutex::new(rx))
            .inspect_err(|_| cancel.store(true, Ordering::Relaxed))?
            .unwrap_or_else(|| Err(anyhow::anyhow!("index update panicked")))
            .map_err(err)?;
        let d = PyDict::new(py);
        d.set_item("files_total", st.files_total)?;
        d.set_item("files_changed", st.files_changed)?;
        d.set_item("files_removed", st.files_removed)?;
        d.set_item("chunks", st.chunks)?;
        d.set_item("seconds", st.seconds)?;
        d.set_item("semantic", st.semantic)?;
        Ok(d)
    }

    /// Ranked search by meaning, name or identifier. `alt` are alternative phrasings whose results
    /// are fused with the main query. GIL released.
    #[pyo3(signature = (query, k=scrutate::ops::SEARCH_K, alt=None, with_text=true))]
    fn search(
        &self,
        py: Python<'_>,
        query: &str,
        k: usize,
        alt: Option<Vec<String>>,
        with_text: bool,
    ) -> PyResult<Vec<Hit>> {
        let op = Op::Search {
            query: query.to_string(),
            alt: alt.unwrap_or_default(),
            k,
            snippets: with_text,
        };
        match self.run(py, op)? {
            Answer::Hits { hits, .. } => Ok(hits_py(hits)),
            _ => Err(unexpected()),
        }
    }

    /// Where is this function/class/method defined? (`Class.method` works.) A `Results` list:
    /// `stopped_at` is `limit` when there were more.
    #[pyo3(signature = (name, limit=scrutate::ops::SYMBOL_LIMIT))]
    fn symbol<'py>(
        &self,
        py: Python<'py>,
        name: &str,
        limit: usize,
    ) -> PyResult<Bound<'py, PyAny>> {
        // a location (`path:start-end`) and a path spelling are read as the MCP tools read them
        let op = Op::Symbol {
            name: name.to_string(),
            limit,
        };
        match self.run(py, op)? {
            Answer::Hits { hits, stopped, .. } => results(py, hits_py(hits), stopped),
            _ => Err(unexpected()),
        }
    }

    /// Functions that call `name`. A `Results` list: `stopped_at` is `limit` when there were more,
    /// `undecided` counts the callers the resolver kept without knowing whether they call this
    /// definition or another of the same name.
    #[pyo3(signature = (name, limit=scrutate::ops::CALLERS_LIMIT))]
    fn callers<'py>(
        &self,
        py: Python<'py>,
        name: &str,
        limit: usize,
    ) -> PyResult<Bound<'py, PyAny>> {
        let op = Op::Callers {
            name: name.to_string(),
            limit,
        };
        match self.run(py, op)? {
            Answer::Callers {
                hits,
                undecided,
                stopped,
            } => {
                let out = results(py, hits_py(hits), stopped)?;
                out.setattr("undecided", undecided)?;
                Ok(out)
            }
            _ => Err(unexpected()),
        }
    }

    /// Functions `name` calls: (resolved hits, unresolved external names). The hits are a
    /// `Results` list: `stopped_at` is `limit` when there were more.
    #[pyo3(signature = (name, limit=scrutate::ops::CALLEES_LIMIT))]
    fn callees<'py>(
        &self,
        py: Python<'py>,
        name: &str,
        limit: usize,
    ) -> PyResult<(Bound<'py, PyAny>, Vec<String>)> {
        let op = Op::Callees {
            name: name.to_string(),
            limit,
        };
        match self.run(py, op)? {
            Answer::Callees {
                resolved,
                external,
                stopped,
                ..
            } => Ok((results(py, hits_py(resolved), stopped)?, external)),
            _ => Err(unexpected()),
        }
    }

    /// Symbols of a file in source order, as dicts (kind, name, qualname, start, end).
    fn outline<'py>(&self, py: Python<'py>, path: &str) -> PyResult<Vec<Bound<'py, PyDict>>> {
        let Answer::Outline { rows, .. } = self.run(
            py,
            Op::Outline {
                path: path.to_string(),
            },
        )?
        else {
            return Err(unexpected());
        };
        rows.iter()
            .map(|r| {
                let d = PyDict::new(py);
                d.set_item("kind", &r.kind)?;
                d.set_item("name", &r.name)?;
                d.set_item("qualname", &r.qualname)?;
                d.set_item("start", r.start)?;
                d.set_item("end", r.end)?;
                Ok(d)
            })
            .collect()
    }

    /// Modules a file imports: list of (line, module, resolved_path_or_None).
    fn dependencies(
        &self,
        py: Python<'_>,
        path: &str,
    ) -> PyResult<Vec<(i64, String, Option<String>)>> {
        let Answer::Deps { deps, .. } = self.run(
            py,
            Op::Deps {
                path: path.to_string(),
            },
        )?
        else {
            return Err(unexpected());
        };
        Ok(deps
            .into_iter()
            .map(|d| (d.line, d.module, d.resolved))
            .collect())
    }

    /// Files importing a module or repository file: list of (path, line, module as written).
    fn dependents(&self, py: Python<'_>, target: &str) -> PyResult<Vec<(String, i64, String)>> {
        match self.run(
            py,
            Op::Rdeps {
                target: target.to_string(),
            },
        )? {
            Answer::Rdeps { rows, .. } => Ok(rows),
            _ => Err(unexpected()),
        }
    }

    /// Code similar to a symbol or `path:line`: list of (hit, cosine, jaccard).
    #[pyo3(signature = (target, k=scrutate::ops::SIMILAR_K))]
    fn similar(&self, py: Python<'_>, target: &str, k: usize) -> PyResult<Vec<(Hit, f32, f32)>> {
        let op = Op::Similar {
            target: target.to_string(),
            k,
        };
        match self.run(py, op)? {
            Answer::Similar(out) => Ok(out.into_iter().map(|(h, c, j)| (h.into(), c, j)).collect()),
            _ => Err(unexpected()),
        }
    }

    /// Duplicate and near-duplicate functions, as a `Results` list of JSON-compatible dicts:
    /// `stopped_at` is `limit` when there were more.
    #[pyo3(signature = (min_tokens=scrutate::ops::DUPES_MIN_TOKENS, threshold=scrutate::ops::DUPES_THRESHOLD, limit=scrutate::ops::DUPES_LIMIT))]
    fn duplicates<'py>(
        &self,
        py: Python<'py>,
        min_tokens: usize,
        threshold: f32,
        limit: usize,
    ) -> PyResult<Bound<'py, PyAny>> {
        let op = Op::Dupes {
            min_tokens,
            threshold,
            limit,
        };
        let Answer::Dupes(groups, stopped) = self.run(py, op)? else {
            return Err(unexpected());
        };
        let dicts = groups
            .iter()
            .map(|g| {
                let d = PyDict::new(py);
                d.set_item("kind", g.kind)?;
                d.set_item("similarity", g.similarity)?;
                d.set_item("tokens", g.tokens)?;
                d.set_item("members", g.members.clone())?;
                Ok(d)
            })
            .collect::<PyResult<Vec<_>>>()?;
        results(py, dicts, stopped)
    }

    /// Every use of `name`, each resolved to the definition it refers to, as the `references`
    /// tool and `scrutate refs --json` give it (a dict: `definitions` with their `references`,
    /// `unresolved`, `truncated`). `textual`: every occurrence grouped by enclosing symbol
    /// instead; `definition` (`path` or `path:line`) keeps one definition.
    #[pyo3(signature = (name, max_results=scrutate::ops::REFS_MAX, textual=false, definition=None))]
    fn references<'py>(
        &self,
        py: Python<'py>,
        name: &str,
        max_results: u64,
        textual: bool,
        definition: Option<String>,
    ) -> PyResult<Bound<'py, PyAny>> {
        let op = Op::Refs {
            name: name.to_string(),
            max_results,
            textual,
            def: definition,
        };
        let answer = self.run(py, op)?;
        to_py(py, &answer.json())
    }

    /// Any operation by its MCP tool name (`grep_code`, `find_symbol`, `references`, ...) with
    /// that tool's arguments as a dict, answered as the tool answers: a dict with `schema`,
    /// `result` (the JSON form), `stopped_at` when the answer stopped at its limit, and `text`, the
    /// text form from item `offset` on within `max_bytes` (whole without it), concise when the
    /// arguments say `response_format: concise`.
    #[pyo3(signature = (tool, args=None, *, max_bytes=None, offset=0))]
    fn call<'py>(
        &self,
        py: Python<'py>,
        tool: &str,
        args: Option<Bound<'py, PyDict>>,
        max_bytes: Option<usize>,
        offset: usize,
    ) -> PyResult<Bound<'py, PyAny>> {
        let args: serde_json::Value = match args {
            Some(a) => {
                let text: String = py.import("json")?.call_method1("dumps", (a,))?.extract()?;
                serde_json::from_str(&text).map_err(|e| PyValueError::new_err(e.to_string()))?
            }
            None => serde_json::json!({}),
        };
        let op = Op::from_tool(tool, &args).map_err(value_err)?;
        let form = scrutate::ops::Form::from_tool(&args).map_err(value_err)?;
        let answer = self.run(py, op)?;
        let mut v = answer.envelope();
        v["text"] = answer
            .text_as(max_bytes.unwrap_or(usize::MAX), offset, form)
            .into();
        to_py(py, &v)
    }

    /// Index statistics as a dict. GIL released while it waits for the engine.
    fn stats<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyDict>> {
        let v = py
            .detach(|| self.session.read(&Arc::default(), false, |s| s.ix.stats()))
            .map_err(err)?;
        let d = PyDict::new(py);
        if let Some(m) = v.as_object() {
            for (k, val) in m {
                match val {
                    serde_json::Value::Number(n) if n.is_i64() => d.set_item(k, n.as_i64())?,
                    serde_json::Value::Bool(b) => d.set_item(k, *b)?,
                    other => d.set_item(k, other.to_string())?,
                }
            }
        }
        Ok(d)
    }

    /// Lines `start..=end` of a file inside the repository (never outside it), numbered.
    /// Raises FileNotFoundError for a missing file, ValueError for a path outside the repository.
    /// GIL released while it waits for the engine.
    #[pyo3(signature = (path, start=1, end=None, max_lines=scrutate::ops::READ_LINES))]
    fn read(
        &self,
        py: Python<'_>,
        path: &str,
        start: i64,
        end: Option<i64>,
        max_lines: i64,
    ) -> PyResult<String> {
        let end = end
            .unwrap_or(i64::MAX)
            .min(start.saturating_add(max_lines.saturating_sub(1)));
        let op = Op::Read {
            path: Some(path.to_string()),
            symbol: None,
            start,
            end: Some(end),
        };
        let r = py.detach(|| self.session.run(&op, &Arc::default()));
        let e = match r {
            Ok(Answer::Read { lines, .. }) => return Ok(lines.join("\n")),
            Ok(_) => return Err(unexpected()),
            Err(e) => e.to_string(),
        };
        // the engine's message already says which: no file is looked at here
        Err(if e == "path outside repo" {
            PyValueError::new_err(e)
        } else if e.starts_with("cannot read ") {
            PyFileNotFoundError::new_err(e)
        } else {
            PyOSError::new_err(e)
        })
    }
}

/// Engine version string.
#[pyfunction]
fn version() -> &'static str {
    scrutate::VERSION
}

/// Thread-safety review for free-threaded Python (`gil_used = false`):
/// * `Match` and `Hit` are frozen (immutable after construction);
/// * `Repo` holds a `Session`, which runs calls from several threads side by side, each on a
///   reader of its own, and its writes one at a time;
/// * `GrepIter` methods take `&mut self`: PyO3's borrow checker rejects concurrent mutable access
///   with an exception instead of racing; the channel receiver is additionally behind a `Mutex`;
/// * the module holds no other global mutable state.
#[pymodule(gil_used = false)]
fn _native(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add_class::<Match>()?;
    m.add_class::<Hit>()?;
    m.add_class::<GrepIter>()?;
    m.add_class::<Repo>()?;
    m.add_function(wrap_pyfunction!(grep, m)?)?;
    m.add_function(wrap_pyfunction!(version, m)?)?;
    m.add("__version__", scrutate::VERSION)?;
    // a plain list subclass, so a result works wherever a list did
    let py = m.py();
    let ns = PyDict::new(py);
    ns.set_item("__module__", "scrutate._native")?;
    ns.set_item("__doc__", "A list of results; `stopped_at` is the limit the answer stopped at when there were more, else None.")?;
    ns.set_item("stopped_at", py.None())?;
    ns.set_item("undecided", py.None())?;
    m.add(
        "Results",
        py.get_type::<PyType>()
            .call1(("Results", (py.get_type::<PyList>(),), ns))?,
    )?;
    Ok(())
}

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=startup.order");
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("macos") {
        // the standard library links libiconv and the executable calls none of it: one library
        // fewer for dyld to load (0.18 M instructions at every start)
        println!("cargo:rustc-link-arg-bins=-Wl,-dead_strip_dylibs");
        // the functions a small search runs, side by side (tools/order_file.py)
        let order = std::path::Path::new(&std::env::var("CARGO_MANIFEST_DIR").unwrap()).join("startup.order");
        if order.is_file() {
            println!("cargo:rustc-link-arg-bins=-Wl,-order_file,{}", order.display());
        }
    }
}

//! Stored resolution answers: what `Names` made of a name's occurrences in some lines of a file
//! (`Uses`) for one `callers` or `callees` request, kept under `.scrutate/answers/`, so the same
//! request on the same index and files resolves nothing again.
//!
//! One file per request kind and name. It holds the answers of one run and what that run read:
//! the code index's database (the file's identity and its data version, which every update that
//! changes a row moves), this executable, the root, and the `stat` of every file the resolver read
//! from disk (`noted`), absent ones included. A run uses a file only when all of those are the
//! same now and the stored run went as far (`limit`); it then walks the same call sites in the same
//! order on the same inputs, so every answer is the one the stored run made, which is the one a
//! fresh run makes. Anything else, a damaged file included, reads as no file. Files are written
//! from a read, whole, to a temporary name and renamed, so no lock is taken and a reader never sees
//! half of one; two writers lose one write, never mix them. The least recently used go first
//! beyond `MAX_BYTES`.

use std::cell::RefCell;
use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::time::SystemTime;

use anyhow::{bail, Result};

use crate::index::Stat;
use crate::names::Uses;
use crate::search::Searcher;

/// Total size of `.scrutate/answers/`.
pub const MAX_BYTES: u64 = 64 << 20;
const MAGIC: &[u8] = b"scrutate-answers 1\n";
const MAX_ITEMS: usize = 1 << 24;

/// A file's state on disk: a regular file and its stat, or anything else.
type Seen = Option<Stat>;

thread_local! {
    /// The files the resolvers of this thread read while a `Names` is open.
    static READS: RefCell<Reads> = RefCell::default();
}

#[derive(Default)]
struct Reads {
    open: usize,
    seen: HashMap<PathBuf, Seen>,
    /// a file read twice changed in between
    moved: bool,
}

fn seen(p: &Path) -> Seen {
    std::fs::symlink_metadata(p).ok().filter(|m| m.is_file()).map(|m| Stat::of(&m))
}

/// Called before the resolver reads `rel`: its stat joins what the open requests read.
pub(crate) fn noted(root: &Path, rel: &str) {
    READS.with(|r| {
        let mut r = r.borrow_mut();
        if r.open == 0 {
            return;
        }
        let p = root.join(rel);
        let now = seen(&p);
        match r.seen.get(&p) {
            Some(was) => r.moved |= *was != now,
            None => {
                r.seen.insert(p, now);
            }
        }
    })
}

/// While one is alive, the reads of the resolvers of this thread are noted.
pub(crate) struct Reading;

impl Reading {
    pub(crate) fn start() -> Reading {
        READS.with(|r| r.borrow_mut().open += 1);
        Reading
    }
}

impl Drop for Reading {
    fn drop(&mut self) {
        READS.with(|r| {
            let mut r = r.borrow_mut();
            r.open -= 1;
            if r.open == 0 {
                *r = Reads::default();
            }
        })
    }
}

/// (path, first line, last line, name)
pub(crate) type Site = (String, i64, i64, String);

/// The stored answers of one request and the ones this run adds.
pub(crate) struct Stored {
    dir: PathBuf,
    path: PathBuf,
    header: Vec<u8>,
    version: Option<String>,
    old: HashMap<Site, Uses>,
    new: HashMap<Site, Uses>,
    /// a site the stored run did not answer was asked: this run is not that run
    strayed: bool,
}

impl Stored {
    /// The answers a run of `kind name` that goes up to `limit` results may use.
    pub(crate) fn open(s: &Searcher, kind: &str, name: &str, limit: usize) -> Stored {
        let dir = s.ix.root.join(crate::files::INDEX_DIR).join("answers");
        let version = s.ix.meta("data_version");
        let db = database(&s.ix.root);
        let mut header = MAGIC.to_vec();
        for part in [crate::VERSION, &build(), &db, version.as_deref().unwrap_or(""), &s.ix.root.to_string_lossy(), kind, name] {
            put_str(&mut header, part);
        }
        // one file per request: the next state's run replaces it
        let path = dir.join(format!("{}.bin", hex(&crate::tscache::hash(&[kind.as_bytes(), name.as_bytes()]))));
        // without a database identity or a data version nothing is known to be the same
        let known = version.is_some() && !db.is_empty();
        let old = known.then(|| crate::files::read_regular(&path, MAX_BYTES)).flatten().and_then(|b| decode(&b, &header, limit).ok()).unwrap_or_default();
        Stored { dir, path, header, version: version.filter(|_| known), old, new: HashMap::new(), strayed: false }
    }

    pub(crate) fn get(&mut self, site: &Site) -> Option<&Uses> {
        let found = self.old.get(site).or_else(|| self.new.get(site));
        self.strayed |= found.is_none() && !self.old.is_empty();
        found
    }

    pub(crate) fn put(&mut self, site: Site, uses: Uses) {
        self.new.insert(site, uses);
    }

    /// Keep this run's answers when it read everything it answered from: a run that reached its
    /// end stands for any limit (`complete`), else for its own. Errors are ignored: the store only
    /// saves time.
    pub(crate) fn save(self, s: &Searcher, limit: usize, complete: bool) {
        if !self.old.is_empty() {
            touch(&self.path);
        }
        if self.new.is_empty() || self.strayed || self.version.is_none() || s.ix.meta("data_version") != self.version {
            return;
        }
        let Some(reads) = READS.with(|r| {
            let r = r.borrow();
            (!r.moved).then(|| r.seen.iter().map(|(p, s)| (p.clone(), *s)).collect::<Vec<_>>())
        }) else {
            return;
        };
        let _ = self.write(&reads, if complete { u64::MAX } else { limit as u64 });
    }

    fn write(&self, reads: &[(PathBuf, Seen)], limit: u64) -> Result<()> {
        let mut out = self.header.clone();
        out.extend(limit.to_le_bytes());
        put_n(&mut out, reads.len());
        for (p, s) in reads {
            put_str(&mut out, &p.to_string_lossy());
            match s {
                Some(s) => {
                    out.push(1);
                    for v in [s.size, s.mtime, s.ctime] {
                        out.extend(v.to_le_bytes());
                    }
                }
                None => out.push(0),
            }
        }
        put_n(&mut out, self.new.len());
        for ((path, start, end, name), u) in &self.new {
            put_str(&mut out, path);
            out.extend(start.to_le_bytes());
            out.extend(end.to_le_bytes());
            put_str(&mut out, name);
            for ids in [&u.got, &u.dispatched] {
                let mut ids: Vec<i64> = ids.iter().copied().collect();
                ids.sort_unstable();
                put_n(&mut out, ids.len());
                for id in ids {
                    out.extend(id.to_le_bytes());
                }
            }
            out.push(u.unsure as u8 | (u.unsure_free as u8) << 1 | (u.own_file as u8) << 2);
        }
        if out.len() as u64 > MAX_BYTES {
            bail!("too large to keep");
        }
        let scrutate = self.dir.parent().unwrap_or(&self.dir);
        crate::files::index_dir(scrutate.parent().unwrap_or(scrutate))?;
        std::fs::create_dir_all(&self.dir)?;
        crate::index::write_gitignore(scrutate)?;
        let nanos = SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).map(|d| d.as_nanos()).unwrap_or(0);
        let tmp = self.dir.join(format!(".tmp-{}-{:?}-{nanos}", std::process::id(), std::thread::current().id()).replace(['(', ')'], ""));
        crate::index::write_new(&tmp, &out)?;
        if let Err(e) = std::fs::rename(&tmp, &self.path) {
            let _ = std::fs::remove_file(&tmp);
            return Err(e.into());
        }
        evict(&self.dir, &self.path);
        Ok(())
    }
}

/// This executable, so a rebuilt binary (whose rules may differ) answers anew.
fn build() -> String {
    std::env::current_exe()
        .ok()
        .and_then(|p| std::fs::metadata(p).ok())
        .map(|m| format!("{} {} {}", identity(&m), m.len(), Stat::of(&m).mtime))
        .unwrap_or_default()
}

/// The code index's database file: a database deleted and built again is another one, whatever its
/// data version says. Empty where the file's creation time is not known.
fn database(root: &Path) -> String {
    let Ok(m) = std::fs::metadata(root.join(crate::files::INDEX_DIR).join("index.db")) else { return String::new() };
    if m.created().is_err() {
        return String::new();
    }
    identity(&m)
}

/// The file's device, number and creation time: none of them moves while it is written.
fn identity(m: &std::fs::Metadata) -> String {
    let born = m.created().ok().and_then(|t| t.duration_since(SystemTime::UNIX_EPOCH).ok()).map_or(0, |d| d.as_nanos());
    #[cfg(unix)]
    let (dev, ino) = {
        use std::os::unix::fs::MetadataExt;
        (m.dev(), m.ino())
    };
    #[cfg(not(unix))]
    let (dev, ino) = (0, 0);
    format!("{dev} {ino} {born}")
}

fn hex(k: &[u8]) -> String {
    k.iter().map(|b| format!("{b:02x}")).collect()
}

fn touch(path: &Path) {
    if let Ok(f) = std::fs::File::options().write(true).open(path) {
        let _ = f.set_modified(SystemTime::now());
    }
}

fn evict(dir: &Path, keep: &Path) {
    let Ok(rd) = std::fs::read_dir(dir) else { return };
    let mut files: Vec<(SystemTime, u64, PathBuf)> = rd
        .flatten()
        .filter_map(|e| {
            let md = e.metadata().ok()?;
            Some((md.modified().unwrap_or(SystemTime::UNIX_EPOCH), md.len(), e.path()))
        })
        .collect();
    files.sort_by_key(|f| std::cmp::Reverse(f.0));
    let mut total = 0u64;
    for (_, len, p) in files {
        total += len;
        if total > MAX_BYTES && p != keep {
            let _ = std::fs::remove_file(&p);
        }
    }
}

/// The answers of a stored run that went at least up to `limit` and read only files that are as
/// they were.
fn decode(b: &[u8], header: &[u8], limit: usize) -> Result<HashMap<Site, Uses>> {
    let mut r = Reader { b, pos: 0 };
    if r.take(header.len())? != header {
        bail!("another request, index or build");
    }
    if r.u64()? < limit as u64 {
        bail!("a run that stopped sooner");
    }
    for _ in 0..r.n()? {
        let p = PathBuf::from(r.string()?);
        let was = match r.take(1)?[0] {
            0 => None,
            _ => Some(Stat { size: r.i64()?, mtime: r.i64()?, ctime: r.i64()? }),
        };
        if seen(&p) != was {
            bail!("a file it read changed");
        }
    }
    let mut out = HashMap::new();
    for _ in 0..r.n()? {
        let site = (r.string()?, r.i64()?, r.i64()?, r.string()?);
        let mut ids = || -> Result<HashSet<i64>> { (0..r.n()?).map(|_| r.i64()).collect() };
        let (got, dispatched) = (ids()?, ids()?);
        let flags = r.take(1)?[0];
        out.insert(site, Uses { got, dispatched, unsure: flags & 1 != 0, unsure_free: flags & 2 != 0, own_file: flags & 4 != 0 });
    }
    if r.pos != b.len() {
        bail!("trailing bytes");
    }
    Ok(out)
}

fn put_n(w: &mut Vec<u8>, n: usize) {
    w.extend((n as u32).to_le_bytes());
}

fn put_str(w: &mut Vec<u8>, s: &str) {
    put_n(w, s.len());
    w.extend(s.as_bytes());
}

struct Reader<'a> {
    b: &'a [u8],
    pos: usize,
}

impl<'a> Reader<'a> {
    fn take(&mut self, n: usize) -> Result<&'a [u8]> {
        let Some(s) = self.b.get(self.pos..self.pos.saturating_add(n)) else { bail!("truncated") };
        self.pos += n;
        Ok(s)
    }
    fn u64(&mut self) -> Result<u64> {
        Ok(u64::from_le_bytes(self.take(8)?.try_into()?))
    }
    fn i64(&mut self) -> Result<i64> {
        Ok(i64::from_le_bytes(self.take(8)?.try_into()?))
    }
    fn n(&mut self) -> Result<usize> {
        let n = u32::from_le_bytes(self.take(4)?.try_into()?) as usize;
        if n > MAX_ITEMS {
            bail!("a count larger than any answer");
        }
        Ok(n)
    }
    fn string(&mut self) -> Result<String> {
        let n = self.n()?;
        Ok(String::from_utf8(self.take(n)?.to_vec())?)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn kept_answers_stand_while_the_files_read_are_as_they_were() {
        let root = std::env::temp_dir().join(format!("scrutate_answers_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).unwrap();
        std::fs::write(root.join("a.py"), "def helper():\n    return 1\n").unwrap();
        std::fs::write(root.join("b.py"), "from a import helper\n\n\ndef run():\n    return helper()\n").unwrap();
        let (s, _) = crate::open_updated(&root, false).unwrap();
        let s = s.into_searcher();
        let callers = || crate::names::Names::new(&s).unwrap().callers("helper", 10).unwrap();
        let kept = |limit| Stored::open(&s, "callers", "helper", limit).old.len();
        assert_eq!(kept(10), 0);
        let first = callers();
        assert_eq!(first.0.len(), 1);
        if database(&root).is_empty() {
            // a file system that does not say when the database was made keeps nothing
            assert_eq!(kept(10), 0);
            // Windows deletes no file the open index holds
            drop(s);
            return std::fs::remove_dir_all(&root).unwrap();
        }
        assert_eq!((kept(10), kept(11)), (1, 1), "a run that went through every site stands for any limit");
        assert_eq!(callers().0[0].qualname, first.0[0].qualname);
        // the index is not told: the resolver reads the file as it is now, so the kept answer goes
        // a virus scanner on a Windows runner can hold a file just written for a moment; a handle
        // the open index keeps would be a defect: it would stop an editor saving the file
        let edit = || std::fs::write(root.join("b.py"), "from a import helper as h\n\n\ndef run():\n    return h()\n");
        let mut tries = 0;
        while let Err(e) = edit() {
            tries += 1;
            if tries == 200 {
                drop(s);
                let after = edit();
                panic!("b.py stayed busy for 5 s ({e}); with the open index closed the write gives {after:?}");
            }
            assert_eq!(e.raw_os_error(), Some(32), "{e}");
            std::thread::sleep(std::time::Duration::from_millis(25));
        }
        assert_eq!(kept(10), 0);
        assert!(Stored::open(&s, "callers", "nothing", 10).old.is_empty(), "another request");
        drop(s);
        std::fs::remove_dir_all(&root).unwrap();
    }
}

//! What `grep -z` reads: the members of zip and tar archives, and the contents of compressed
//! files. gzip (alone or around a tar) is decompressed in process; bzip2, xz, zstd, lz4, brotli and
//! `.Z` by the system's own tools, as ripgrep's `-z` does.

use std::fs::File;
use std::io::Read;
use std::path::Path;

/// Decompressed bytes allowed per archive or compressed file: a small zip bomb must not fill memory
/// or keep a search busy for hours.
pub const MAX_EXPANDED: u64 = 8 << 30;
/// The longest line of an archive member or a compressed file that is searched.
pub const MAX_LINE: usize = 64 << 20;
/// Members searched per archive.
pub const MAX_MEMBERS: usize = 1_000_000;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    Zip,
    Tar,
    TarGz,
    /// a tar inside another compression format
    TarOther,
    Gz,
    /// one compressed file, decompressed by an external tool
    Other,
}

const OTHER: &[&str] = &[".bz2", ".tbz", ".tbz2", ".xz", ".txz", ".lzma", ".zst", ".zstd", ".tzst", ".lz4", ".br", ".z"];

impl Kind {
    /// an archive, not one compressed file
    pub fn has_members(self) -> bool {
        !matches!(self, Kind::Gz | Kind::Other)
    }

    pub fn of(path: &str) -> Option<Kind> {
        let l = path.to_ascii_lowercase();
        let tar_inside = |ext: &str| l.strip_suffix(ext).is_some_and(|s| s.ends_with(".tar"));
        Some(if l.ends_with(".zip") {
            Kind::Zip
        } else if l.ends_with(".tar") {
            Kind::Tar
        } else if l.ends_with(".tgz") || tar_inside(".gz") {
            Kind::TarGz
        } else if l.ends_with(".gz") {
            Kind::Gz
        } else if [".tbz", ".tbz2", ".txz", ".tzst"].iter().any(|e| l.ends_with(e)) || OTHER.iter().any(|e| tar_inside(e)) {
            Kind::TarOther
        } else if OTHER.iter().any(|e| l.ends_with(e)) && !(l.ends_with(".z") && !path.ends_with(".Z")) {
            Kind::Other
        } else {
            return None;
        })
    }
}

/// Counts what is read and fails past `MAX_EXPANDED`.
struct Capped<R> {
    inner: R,
    left: u64,
}

impl<R: Read> Read for Capped<R> {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        let n = self.inner.read(buf)?;
        self.left = self.left.checked_sub(n as u64).ok_or_else(|| std::io::Error::other(format!("expands beyond {} GiB; stopped", MAX_EXPANDED >> 30)))?;
        Ok(n)
    }
}

fn external(path: &Path) -> std::io::Result<Box<dyn Read>> {
    let r = grep_cli::DecompressionReaderBuilder::new().build(path).map_err(std::io::Error::other)?;
    Ok(Box::new(r))
}

/// Calls `each(member, reader)` for every regular file inside `path` (member None: the
/// decompressed file itself). `each` returns false to stop. Errors of one member are passed to
/// `failed` and the walk goes on; an error that ends the walk is returned.
pub fn walk(path: &Path, kind: Kind, each: &mut dyn FnMut(Option<&str>, &mut dyn Read) -> bool, failed: &mut dyn FnMut(String)) -> std::io::Result<()> {
    match kind {
        Kind::Gz => {
            let mut r = Capped { inner: flate2::read::MultiGzDecoder::new(File::open(path)?), left: MAX_EXPANDED };
            each(None, &mut r);
            Ok(())
        }
        Kind::Other => {
            let mut r = Capped { inner: external(path)?, left: MAX_EXPANDED };
            each(None, &mut r);
            Ok(())
        }
        Kind::Tar => tar(Capped { inner: Box::new(File::open(path)?) as Box<dyn Read>, left: MAX_EXPANDED }, each, failed),
        Kind::TarGz => tar(Capped { inner: Box::new(flate2::read::MultiGzDecoder::new(File::open(path)?)) as Box<dyn Read>, left: MAX_EXPANDED }, each, failed),
        Kind::TarOther => tar(Capped { inner: external(path)?, left: MAX_EXPANDED }, each, failed),
        Kind::Zip => {
            let mut z = zip::ZipArchive::new(File::open(path)?).map_err(std::io::Error::other)?;
            let mut left = MAX_EXPANDED;
            for i in 0..z.len().min(MAX_MEMBERS) {
                let mut e = match z.by_index(i) {
                    Ok(e) => e,
                    Err(err) => {
                        failed(format!("member {i}: {err}"));
                        continue;
                    }
                };
                if !e.is_file() {
                    continue;
                }
                let name = e.name().map(|n| n.into_owned()).unwrap_or_else(|_| format!("member {i}"));
                let mut r = Capped { inner: &mut e, left };
                if !each(Some(&name), &mut r) {
                    break;
                }
                left = r.left;
            }
            Ok(())
        }
    }
}

/// The longest member name kept from a GNU long-name or PAX header; a zip name is at most 64 KiB
/// by its format.
const MAX_NAME: u64 = 64 << 10;

/// A member name from an extension header (None: it gives none); Err: longer than `MAX_NAME`.
type Name = Result<Option<Vec<u8>>, ()>;

/// The tar crate reads a long-name or PAX header whole, up to gigabytes, so they are read here.
fn tar<R: Read>(r: R, each: &mut dyn FnMut(Option<&str>, &mut dyn Read) -> bool, failed: &mut dyn FnMut(String)) -> std::io::Result<()> {
    struct Shared<R>(std::rc::Rc<std::cell::RefCell<R>>);
    impl<R: Read> Read for Shared<R> {
        fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
            self.0.borrow_mut().read(buf)
        }
    }
    let r = std::rc::Rc::new(std::cell::RefCell::new(r));
    let mut a = tar::Archive::new(Shared(r.clone()));
    // the name and size the extension headers give the next member
    let mut name: Name = Ok(None);
    let mut size = None;
    for (n, entry) in a.entries()?.raw(true).enumerate() {
        if n >= MAX_MEMBERS {
            break;
        }
        let mut e = entry?;
        let t = e.header().entry_type();
        // the extension blocks of an old-GNU sparse member sit before its data and are not in its
        // size, so they are read past here where the raw walk does not count them
        if t.is_gnu_sparse() && e.header().as_gnu().is_some_and(|g| g.is_extended()) {
            let mut ext = tar::GnuExtSparseHeader::new();
            ext.set_is_extended(true);
            while ext.is_extended() {
                r.borrow_mut().read_exact(ext.as_mut_bytes())?;
            }
        }
        let known = e.header().as_gnu().is_some() || e.header().as_ustar().is_some();
        if known && t.is_gnu_longname() {
            let mut v = Vec::new();
            (&mut e).take(MAX_NAME + 1).read_to_end(&mut v)?;
            while v.last() == Some(&0) {
                v.pop();
            }
            name = if v.len() as u64 > MAX_NAME { Err(()) } else { Ok(Some(v)) };
            continue;
        }
        if known && t.is_pax_local_extensions() {
            let (path, s) = pax(&mut e)?;
            match path {
                Ok(Some(p)) => name = Ok(Some(p)),
                Err(()) => name = Err(()),
                Ok(None) => {}
            }
            size = size.or(s);
            continue;
        }
        if t.is_gnu_longlink() || t.is_pax_global_extensions() {
            continue;
        }
        let (name, size) = (std::mem::replace(&mut name, Ok(None)), size.take());
        if size.is_some_and(|s| s != e.size()) {
            return Err(std::io::Error::other("a member's size in its PAX header differs from its header; stopped"));
        }
        if !t.is_file() {
            continue;
        }
        let Ok(name) = name else {
            failed(format!("a member name longer than {} KiB; skipped", MAX_NAME >> 10));
            continue;
        };
        let name = match name {
            Some(v) => String::from_utf8_lossy(&v).into_owned(),
            None => String::from_utf8_lossy(&e.header().path_bytes()).into_owned(),
        };
        if !each(Some(&name), &mut e) {
            break;
        }
    }
    Ok(())
}

/// The `path` and `size` records of a PAX header, read record by
/// record so that other records, such as extended attributes, are skipped and not held.
fn pax(r: &mut dyn Read) -> std::io::Result<(Name, Option<u64>)> {
    fn byte(r: &mut dyn Read) -> std::io::Result<Option<u8>> {
        let mut b = [0];
        Ok((r.read(&mut b)? == 1).then_some(b[0]))
    }
    let (mut path, mut size) = (Ok(None), None);
    loop {
        // "<length> <key>=<value>\n", the length counting the whole record
        let (mut len, mut digits) = (0u64, 0u64);
        loop {
            match byte(r)? {
                Some(b @ b'0'..=b'9') if digits < 19 => {
                    len = len * 10 + u64::from(b - b'0');
                    digits += 1;
                }
                Some(b' ') if digits > 0 => break,
                _ => return Ok((path, size)),
            }
        }
        let mut left = len.saturating_sub(digits + 1);
        let mut key = Vec::new();
        while left > 0 {
            left -= 1;
            match byte(r)? {
                Some(b'=') => break,
                Some(b) if key.len() < 64 => key.push(b),
                Some(_) => {}
                None => return Ok((path, size)),
            }
        }
        // the value, then its newline
        let value = left.saturating_sub(1);
        if key == b"path" && value > MAX_NAME {
            path = Err(());
        } else if key == b"path" || (key == b"size" && value <= 20) {
            let mut v = Vec::new();
            (&mut *r).take(value).read_to_end(&mut v)?;
            left -= v.len() as u64;
            if key == b"path" {
                path = Ok(Some(v));
            } else {
                size = std::str::from_utf8(&v).ok().and_then(|s| s.parse().ok());
            }
        }
        std::io::copy(&mut (&mut *r).take(left), &mut std::io::sink())?;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn kinds_by_name() {
        for (name, kind) in [
            ("a.zip", Some(Kind::Zip)),
            ("a.tar", Some(Kind::Tar)),
            ("a.tar.gz", Some(Kind::TarGz)),
            ("A.TGZ", Some(Kind::TarGz)),
            ("a.gz", Some(Kind::Gz)),
            ("a.tar.xz", Some(Kind::TarOther)),
            ("a.tbz2", Some(Kind::TarOther)),
            ("a.log.zst", Some(Kind::Other)),
            ("a.Z", Some(Kind::Other)),
            ("a.z", None),
            ("a.txt", None),
            ("zip", None),
        ] {
            assert_eq!(Kind::of(name), kind, "{name}");
        }
    }

    #[test]
    fn capped_reader_stops() {
        let data = [b'a'; 100];
        let mut r = Capped { inner: &data[..], left: 10 };
        let mut buf = Vec::new();
        assert!(r.read_to_end(&mut buf).is_err());
    }
}

//! The artifact store: what parsing and tokenizing make of one file, keyed by the file's content
//! and the parts of its path the parser reads, so that the same bytes under any path, in this
//! checkout or in the main checkout of a linked git work tree, are not parsed again.
//!
//! An artifact holds a file's chunks (kind, names, lines, calls), its imports, and per chunk and
//! field the words with their counts: the subwords the vectors are made from and the whole
//! identifiers the postings add. Its chunk texts and vectors travel beside it (`Found`): while a
//! path names it they are the rows and segment rows of the code index, and when the last path
//! that named it drops it they move into the store (`kept`), bounded and least recently used
//! first. Everything a path decides (the path itself, the test flag, the path field) is made by
//! `derive`, the one function that turns an artifact into the rows and postings of a path.
//!
//! The store is a table of the code index's database (`index.rs` keeps it), so it commits in the
//! same transaction as the rows made from it.

use std::collections::HashMap;
use std::io::{Read, Write};

use anyhow::{bail, Result};

use crate::index::{ChunkRow, NewRow, TF_CAP};
use crate::lex::{tok_key, FileLex, QVecs, NF};
use crate::semantic::SemanticModel;
use crate::text::{is_test_path, name_key, tokenize2};

/// The layout of an encoded artifact; part of every key, so another layout is never read.
const FORMAT: u32 = 1;
const MAGIC: &[u8] = b"scrutate-artifact 1\n";
const TEXTS_MAGIC: &[u8] = b"scrutate-texts 1\n";
/// No artifact holds more chunks, words or bytes than this; a larger count is damage.
const MAX_ITEMS: usize = 1 << 24;

pub type Key = [u8; 16];

/// The key of the artifact of a file with this content hash at `rel`: besides the bytes, a parse
/// reads the file's name (the language, the module chunk's name, comment marks) and, for an
/// `index` file, its directory's name (an anonymous default export), under the parsing rules of
/// this `CONTENT_REVISION` and of the custom language that claims the file, if one does.
pub fn key(content_hash: &str, rel: &str) -> Key {
    let p = std::path::Path::new(rel);
    let base = rel.rsplit('/').next().unwrap_or(rel);
    let dir = match p.file_stem() {
        Some(s) if s == "index" => p.parent().and_then(|d| d.file_name()).map(|d| d.to_string_lossy().into_owned()).unwrap_or_default(),
        _ => String::new(),
    };
    let rev = format!("{FORMAT} {}", crate::index::CONTENT_REVISION);
    match crate::custom::current().for_path(rel) {
        Some(l) => crate::tscache::hash(&[b"artifact", rev.as_bytes(), content_hash.as_bytes(), base.as_bytes(), dir.as_bytes(), l.sig().as_bytes()]),
        None => crate::tscache::hash(&[b"artifact", rev.as_bytes(), content_hash.as_bytes(), base.as_bytes(), dir.as_bytes()]),
    }
}

/// The words of one field of a chunk with their counts, each list sorted by word.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Field {
    /// subwords, stemmed: what the vectors and the length of a doc or body count
    pub subs: Vec<(String, u32)>,
    /// whole identifiers
    pub wholes: Vec<(String, u32)>,
}

impl Field {
    pub fn of((subs, wholes): (Vec<String>, Vec<String>)) -> Field {
        Field { subs: counts(&subs), wholes: counts(&wholes) }
    }

    fn len(&self) -> i64 {
        self.subs.iter().map(|w| w.1 as i64).sum()
    }
}

fn counts(words: &[String]) -> Vec<(String, u32)> {
    let mut m: HashMap<&str, u32> = HashMap::with_capacity(words.len());
    for w in words {
        *m.entry(w.as_str()).or_insert(0) += 1;
    }
    let mut v: Vec<(String, u32)> = m.into_iter().map(|(w, c)| (w.to_string(), c)).collect();
    v.sort_unstable();
    v
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct Chunk {
    pub kind: String,
    pub name: String,
    pub qualname: String,
    pub start: i64,
    pub end: i64,
    /// the name's subwords, each once, in order
    pub name_tok: String,
    pub calls: Vec<String>,
    /// name, qualifier, signature, doc, body
    pub fields: [Field; 5],
}

impl Chunk {
    /// A constant is a symbol only: no postings, no vector.
    fn lexed(&self) -> bool {
        self.kind != "constant"
    }
}

/// What a parse makes of a file that depends on nothing but the inputs of its key.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Artifact {
    pub chunks: Vec<Chunk>,
    pub imports: Vec<(i64, String)>,
}

/// An artifact with the chunk texts (compressed as the index stores them) and, when a store had
/// them for the model in use, the vectors of its ranked chunks.
pub struct Found {
    pub art: Artifact,
    pub texts: Vec<Vec<u8>>,
    pub vecs: Option<QVecs>,
}

impl Artifact {
    /// The words of a parsed chunk's fields, and its name's subwords each once in order.
    pub fn tokenize(c: &crate::parse::Chunk) -> ([Field; 5], String) {
        let qual = c.qualname.rfind('.').map_or("", |i| &c.qualname[..i]);
        let name = tokenize2(&c.name, None);
        let mut seen = std::collections::HashSet::new();
        let name_tok: Vec<&str> = name.0.iter().map(String::as_str).filter(|s| seen.insert(*s)).collect();
        let name_tok = name_tok.join(" ");
        let fields = [
            Field::of(name),
            Field::of(tokenize2(qual, None)),
            Field::of(tokenize2(&c.sig, Some(80))),
            Field::of(tokenize2(&c.doc, Some(200))),
            Field::of(tokenize2(&c.body, Some(crate::text::BODY_CAP))),
        ];
        (fields, name_tok)
    }

    pub fn encode(&self) -> Vec<u8> {
        let mut w = Vec::with_capacity(256 + 64 * self.chunks.len());
        w.extend(MAGIC);
        put_n(&mut w, self.chunks.len());
        for c in &self.chunks {
            for s in [&c.kind, &c.name, &c.qualname, &c.name_tok] {
                put_str(&mut w, s);
            }
            w.extend(c.start.to_le_bytes());
            w.extend(c.end.to_le_bytes());
            put_n(&mut w, c.calls.len());
            for s in &c.calls {
                put_str(&mut w, s);
            }
            for f in &c.fields {
                for list in [&f.subs, &f.wholes] {
                    put_n(&mut w, list.len());
                    for (s, n) in list {
                        put_str(&mut w, s);
                        w.extend(n.to_le_bytes());
                    }
                }
            }
        }
        put_n(&mut w, self.imports.len());
        for (line, module) in &self.imports {
            w.extend(line.to_le_bytes());
            put_str(&mut w, module);
        }
        deflate(&w)
    }

    /// Read an encoded artifact; anything that is not one in full is an error.
    pub fn decode(bytes: &[u8]) -> Result<Artifact> {
        let raw = inflate(bytes)?;
        let mut r = Reader { b: &raw, pos: 0 };
        if r.take(MAGIC.len())? != MAGIC {
            bail!("not an artifact");
        }
        let mut chunks = Vec::new();
        for _ in 0..r.n()? {
            let (kind, name, qualname, name_tok) = (r.string()?, r.string()?, r.string()?, r.string()?);
            let (start, end) = (r.i64()?, r.i64()?);
            let calls = (0..r.n()?).map(|_| r.string()).collect::<Result<_>>()?;
            let mut fields: [Field; 5] = Default::default();
            for f in &mut fields {
                for list in [&mut f.subs, &mut f.wholes] {
                    for _ in 0..r.n()? {
                        list.push((r.string()?, r.u32()?));
                    }
                }
            }
            chunks.push(Chunk { kind, name, qualname, start, end, name_tok, calls, fields });
        }
        let imports = (0..r.n()?).map(|_| Ok((r.i64()?, r.string()?))).collect::<Result<_>>()?;
        if r.pos != raw.len() {
            bail!("trailing bytes");
        }
        Ok(Artifact { chunks, imports })
    }

    /// How many chunks have postings and vectors.
    pub fn lexed(&self) -> usize {
        self.chunks.iter().filter(|c| c.lexed()).count()
    }

    /// The vectors `m` makes of the ranked chunks, from the counts alone, as `derive` makes them.
    pub fn vectors(&self, m: &SemanticModel) -> QVecs {
        let mut v = QVecs::default();
        for c in self.chunks.iter().filter(|c| c.lexed()) {
            push_vectors(m, c, &mut v);
        }
        v
    }
}

/// The chunk texts of an artifact no path names, as the store keeps them.
pub fn encode_texts(texts: &[Vec<u8>]) -> Vec<u8> {
    let mut w = TEXTS_MAGIC.to_vec();
    put_n(&mut w, texts.len());
    for t in texts {
        put_n(&mut w, t.len());
        w.extend(t);
    }
    w
}

pub fn decode_texts(bytes: &[u8]) -> Result<Vec<Vec<u8>>> {
    let mut r = Reader { b: bytes, pos: 0 };
    if r.take(TEXTS_MAGIC.len())? != TEXTS_MAGIC {
        bail!("not the texts of an artifact");
    }
    let texts = (0..r.n()?).map(|_| r.n().and_then(|n| r.take(n)).map(<[u8]>::to_vec)).collect::<Result<_>>()?;
    if r.pos != bytes.len() {
        bail!("trailing bytes");
    }
    Ok(texts)
}

/// The rows and postings of the file at `rel` from its artifact: the path, the test flag and the
/// path field are this path's; the vectors are `vecs` when they fit, else made from the counts.
pub fn derive(rel: &str, found: Found, model: Option<&SemanticModel>) -> (Vec<NewRow>, FileLex, Vec<(i64, String)>) {
    let prof = crate::index::prof::enabled();
    let Found { art, texts, vecs } = found;
    let is_test = is_test_path(rel) as i64;
    let path_text = rel.replace(['/', '.', '_'], " ");
    let path_words = counts(&tokenize2(&path_text, None).0);
    let m = art.lexed();
    let vecs = match (model, vecs) {
        (Some(md), Some(v)) if v.q.len() == m * 2 * md.k && v.scale.len() == m * 2 => Some(v),
        _ => None,
    };
    let make = model.filter(|_| vecs.is_none());
    let mut made = QVecs::default();
    let mut lex = FileLex {
        dl: Vec::with_capacity(m),
        keys: (0..NF).map(|_| Vec::new()).collect(),
        tf: (0..NF).map(|_| Vec::new()).collect(),
        cnt: (0..NF).map(|_| Vec::with_capacity(m)).collect(),
        vec: None,
    };
    let mut rows = Vec::with_capacity(art.chunks.len());
    for (c, text) in art.chunks.into_iter().zip(texts) {
        let t = std::time::Instant::now();
        if c.lexed() {
            let mut total = 0u64;
            for (f, field) in c.fields.iter().enumerate() {
                let cap = (2..=4).contains(&f).then_some(TF_CAP);
                total += push_field(&mut lex, f, merged(&field.subs, &field.wholes), cap);
            }
            total += push_field(&mut lex, 5, path_words.iter().map(|(w, n)| (w.as_str(), *n)), None);
            lex.dl.push(total as f32);
        }
        if prof {
            crate::index::prof::add(&crate::index::prof::TOKENIZE, t);
        }
        let t = std::time::Instant::now();
        if let Some(md) = make.filter(|_| c.lexed()) {
            push_vectors(md, &c, &mut made);
        }
        if prof {
            crate::index::prof::add(&crate::index::prof::ENCODE, t);
        }
        let [_, _, _, doc, body] = &c.fields;
        let (ndoc, nbody) = (doc.len(), body.len());
        rows.push((
            ChunkRow {
                id: 0,
                path: rel.to_string(),
                name_key: name_key(&c.name),
                qual_key: name_key(&c.qualname),
                kind: c.kind,
                name: c.name,
                qualname: c.qualname,
                start: c.start,
                end: c.end,
                is_test,
                ndoc,
                nbody,
                text: String::new(),
                name_tok: c.name_tok,
            },
            c.calls,
            text,
        ));
    }
    if model.is_some() && !rows.is_empty() {
        lex.vec = Some(vecs.unwrap_or(made));
    }
    (rows, lex, art.imports)
}

/// A field's words onto the postings of one chunk, capped at `cap` each; -> their total count.
fn push_field<'a>(lex: &mut FileLex, f: usize, words: impl Iterator<Item = (&'a str, u32)>, cap: Option<u32>) -> u64 {
    let (mut total, mut n) = (0u64, 0i32);
    for (w, c) in words {
        let c = cap.map_or(c, |cap| c.min(cap));
        lex.keys[f].push(tok_key(w));
        lex.tf[f].push(c.min(255) as u8);
        total += c as u64;
        n += 1;
    }
    lex.cnt[f].push(n);
    total
}

/// Two sorted word lists as one, counts of a word in both added.
fn merged<'a>(a: &'a [(String, u32)], b: &'a [(String, u32)]) -> impl Iterator<Item = (&'a str, u32)> {
    let (mut i, mut j) = (0, 0);
    std::iter::from_fn(move || {
        let next = match (a.get(i), b.get(j)) {
            (Some(x), Some(y)) if x.0 == y.0 => {
                i += 1;
                j += 1;
                (x.0.as_str(), x.1 + y.1)
            }
            (Some(x), Some(y)) if x.0 < y.0 => {
                i += 1;
                (x.0.as_str(), x.1)
            }
            (_, Some(y)) => {
                j += 1;
                (y.0.as_str(), y.1)
            }
            (Some(x), None) => {
                i += 1;
                (x.0.as_str(), x.1)
            }
            (None, None) => return None,
        };
        Some(next)
    })
}

/// The (A view, B view) vector of one chunk from its word counts, quantized onto `vecs`.
fn push_vectors(m: &SemanticModel, c: &Chunk, vecs: &mut QVecs) {
    let k = m.k;
    let mut z = vec![0f32; 2 * k];
    let [name, qual, sig, doc, body] = &c.fields;
    if c.kind != "window" {
        let mut a: HashMap<&str, u32> = HashMap::new();
        for (w, n) in &name.subs {
            *a.entry(w.as_str()).or_insert(0) += 3 * n;
        }
        for (w, n) in qual.subs.iter().chain(&sig.subs).chain(&doc.subs) {
            *a.entry(w.as_str()).or_insert(0) += n;
        }
        if let Some(za) = m.encode_counts(&a, &HashMap::new()) {
            z[..k].copy_from_slice(&za);
        }
    }
    let b: HashMap<&str, u32> = body.subs.iter().map(|(w, n)| (w.as_str(), *n)).collect();
    if let Some(zb) = m.encode_counts(&HashMap::new(), &b) {
        z[k..].copy_from_slice(&zb);
    }
    let mut q = vec![0i8; 2 * k];
    let (qa, qb) = q.split_at_mut(k);
    vecs.scale.push(crate::lex::quantize(&z[..k], qa));
    vecs.scale.push(crate::lex::quantize(&z[k..], qb));
    vecs.q.extend(q);
}

fn put_n(w: &mut Vec<u8>, n: usize) {
    w.extend((n as u32).to_le_bytes());
}

fn put_str(w: &mut Vec<u8>, s: &str) {
    put_n(w, s.len());
    w.extend(s.as_bytes());
}

fn deflate(raw: &[u8]) -> Vec<u8> {
    let mut e = flate2::write::ZlibEncoder::new(Vec::with_capacity(raw.len() / 3 + 64), flate2::Compression::fast());
    e.write_all(raw).expect("in-memory deflate");
    e.finish().expect("in-memory deflate")
}

fn inflate(bytes: &[u8]) -> Result<Vec<u8>> {
    let mut out = Vec::new();
    flate2::read::ZlibDecoder::new(bytes).take(MAX_ITEMS as u64 * 8).read_to_end(&mut out)?;
    Ok(out)
}

struct Reader<'a> {
    b: &'a [u8],
    pos: usize,
}

impl<'a> Reader<'a> {
    fn take(&mut self, n: usize) -> Result<&'a [u8]> {
        let Some(s) = self.b.get(self.pos..self.pos.saturating_add(n)) else { bail!("truncated") };
        self.pos += n;
        Ok(s)
    }
    fn u32(&mut self) -> Result<u32> {
        Ok(u32::from_le_bytes(self.take(4)?.try_into()?))
    }
    fn i64(&mut self) -> Result<i64> {
        Ok(i64::from_le_bytes(self.take(8)?.try_into()?))
    }
    fn n(&mut self) -> Result<usize> {
        let n = self.u32()? as usize;
        if n > MAX_ITEMS || n > self.b.len() - self.pos.min(self.b.len()) {
            bail!("a count larger than what follows");
        }
        Ok(n)
    }
    fn string(&mut self) -> Result<String> {
        let n = self.n()?;
        Ok(String::from_utf8(self.take(n)?.to_vec())?)
    }
}

