        Cmd::Grep(GrepArgs {
            pattern,
            mut paths,
            regexp,
            index,
            update,
            fixed_strings,
            pcre2,
            fuzzy_regex,
            search_zip,
            ident,
            fuzzy,
            ignore_case,
            smart_case,
            word,
            multiline,
            invert_match,
            files_with_matches,
            count,
            with_filename,
            no_filename,
            line_number: _,
            no_line_number,
            after,
            before,
            context,
            max_count,
            max_results,
            globs,
            types,
            type_list,
            hidden,
            no_ignore,
            follow,
            max_filesize,
            max_depth,
            threads,
            sort,
            json,
            stats,
            symbols,
