                    println!("{}", serde_json::to_string_pretty(&crate::ops::envelope(r.json(), stopped))?)
                }
                ReviewFormat::Gitlab => println!("{}", serde_json::to_string_pretty(&r.gitlab())?),
            }
            Ok(i32::from(r.is_empty()))
