                if e.kind() != std::io::ErrorKind::BrokenPipe {
                    return Err(e.into());
                }
            }
            let _ = w.flush();
            left.iter().for_each(|s| diagnostic("warning", s));
            trouble |= !left.is_empty();
            Ok(if trouble {
                2
            } else if plan.files.is_empty() {
                1
            } else {
                0
            })
