//! Dead code: the definitions nothing in the repository names. This module reads the text: every
//! whole-word occurrence of each definition's name in every file of the repository, and the rules
//! that make a definition an entry point of its language (`main`, tests, exports, decorators).
//! What an occurrence refers to is asked of `Names` (`Names::dead`), which owns that question.

use std::collections::HashMap;
use std::path::Path;

use rayon::prelude::*;

use crate::index::Symbol;

/// The kinds a definition can be dead of: what a call or a type use names.
const KINDS: &[&str] = &["function", "method", "class", "struct", "trait", "interface", "type", "enum"];
/// Read with them: what holds a method and says what it implements.
const HOLDERS: &[&str] = &["impl"];
/// A file larger than this is not read: a definition it may name is not called dead.
const MAX_READ: u64 = 64 << 20;
/// Lines of a name the resolver is asked about at most, per definition.
pub(crate) const ASKED: usize = 16;

/// The answer: definitions nothing uses, and those the resolver could not decide, each with why.
#[derive(Debug, Default)]
pub struct Dead {
    pub dead: Vec<Symbol>,
    pub undecided: Vec<(Symbol, String)>,
}

/// What the text says of one definition that is not an entry point.
pub(crate) struct Candidate {
    pub sym: Symbol,
    /// how many lines outside it name it, and how many of those are in files the resolver does not read
    pub named: usize,
    pub unread: usize,
    /// the first `ASKED` of those in files the resolver reads, as (file, line): its own file first
    pub lines: Vec<(String, i64)>,
    /// with no line naming it, why it may still be used (its class extends another)
    pub base: Option<String>,
}

/// What the pass over one file found: (name, line) of each occurrence, the rule of each wanted
/// definition in it, and whether it was too large to read.
type Scanned = (Vec<(u32, i64)>, Vec<(i64, Rule)>, bool);

/// What a definition is to its language before any use is looked for.
enum Rule {
    Plain,
    /// an entry point: never dead
    Entry,
    /// used without being named when its base type's code calls it
    Base(String),
}

/// The definitions under `under` (a directory or file from the root, or all) that are not entry
/// points, each with the lines of the repository that name it, and the files too large to read.
pub(crate) fn candidates(ix: &crate::index::Index, under: Option<&str>) -> anyhow::Result<(Vec<Candidate>, Vec<String>)> {
    let root = ix.root.as_path();
    let all = ix.symbols_of_kinds(&[KINDS, HOLDERS].concat())?;
    let inside = |p: &str| under.is_none_or(|u| p == u || p.starts_with(&format!("{}/", u.trim_end_matches('/'))));
    let mut by_file: HashMap<&str, Vec<&Symbol>> = HashMap::new();
    for s in &all {
        by_file.entry(s.path.as_str()).or_default().push(s);
    }
    let wanted: Vec<&Symbol> = all.iter().filter(|s| KINDS.contains(&s.kind.as_str()) && !s.name.is_empty() && inside(&s.path)).collect();
    let mut name_ids: HashMap<&str, u32> = HashMap::new();
    for s in &wanted {
        let n = name_ids.len() as u32;
        name_ids.entry(s.name.as_str()).or_insert(n);
    }
    let odd: Vec<&str> = name_ids.keys().copied().filter(|n| !n.chars().all(word_char)).collect();
    let odd_finder = aho_corasick::AhoCorasick::new(&odd)?;
    let files = every_file(root);
    let scanned: Vec<Scanned> = files
        .par_iter()
        .map(|rel| {
            let Some(raw) = crate::files::read_regular(&root.join(rel), MAX_READ) else {
                let big = std::fs::metadata(root.join(rel)).is_ok_and(|m| m.len() > MAX_READ);
                return (Vec::new(), Vec::new(), big);
            };
            let Some(src) = crate::index::decode_source(&raw) else { return (Vec::new(), Vec::new(), false) };
            let found = occurrences(&src, &name_ids, &odd, &odd_finder);
            let mine: Vec<&Symbol> = by_file
                .get(rel.as_str())
                .map(|v| v.iter().copied().filter(|s| KINDS.contains(&s.kind.as_str()) && inside(&s.path)).collect())
                .unwrap_or_default();
            let rules = if mine.is_empty() { Vec::new() } else { file_rules(root, rel, &src, &mine, &by_file[rel.as_str()]) };
            (found, rules, false)
        })
        .collect();
    let too_large: Vec<String> = files.iter().zip(&scanned).filter(|(_, s)| s.2).map(|(f, _)| f.clone()).collect();
    let readable: Vec<bool> = files.iter().map(|f| crate::resolve::reads(f)).collect();
    let mut rules: HashMap<i64, Rule> = HashMap::new();
    let mut at: Vec<Vec<(u32, i64)>> = vec![Vec::new(); name_ids.len()];
    for (fi, (found, file_rules, _)) in scanned.into_iter().enumerate() {
        rules.extend(file_rules);
        for (n, line) in found {
            at[n as usize].push((fi as u32, line));
        }
    }
    let mut out = Vec::new();
    for s in wanted {
        let rule = rules.remove(&s.id).unwrap_or(Rule::Plain);
        if matches!(rule, Rule::Entry) {
            continue;
        }
        let mut found: Vec<(u32, i64)> = at[name_ids[s.name.as_str()] as usize]
            .iter()
            .copied()
            .filter(|&(f, line)| !(files[f as usize] == s.path && s.start <= line && line <= s.end))
            .collect();
        found.dedup();
        let unread = found.iter().filter(|o| !readable[o.0 as usize]).count();
        let mine = |o: &&(u32, i64)| files[o.0 as usize] == s.path;
        let read = |o: &&(u32, i64)| readable[o.0 as usize];
        let lines = found
            .iter()
            .filter(mine)
            .filter(read)
            .chain(found.iter().filter(|o| !mine(o)).filter(read))
            .take(ASKED)
            .map(|&(f, l)| (files[f as usize].clone(), l))
            .collect();
        let base = match rule {
            Rule::Base(why) => Some(why),
            _ => None,
        };
        out.push(Candidate { sym: s.clone(), named: found.len(), unread, lines, base });
    }
    Ok((out, too_large))
}

/// A character of a word as a whole-word search reads it: a combining mark included.
fn word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_' || unicode_normalization::char::is_combining_mark(c)
}

/// Every regular file of the repository the code index's walk reaches, binary or too large ones
/// included (their reading decides), from the root, sorted.
fn every_file(root: &Path) -> Vec<String> {
    let walk = crate::files::CodeWalk::new(root);
    let mut out: Vec<String> = walk
        .builder(root)
        .build()
        .flatten()
        .filter(|e| e.file_type().is_some_and(|t| t.is_file()) && e.file_name() != ".git")
        .filter_map(|e| Some(e.path().strip_prefix(root).ok()?.components().map(|c| c.as_os_str().to_string_lossy()).collect::<Vec<_>>().join("/")))
        .collect();
    out.sort();
    out
}

/// The (name, 1-based line) of every whole-word occurrence in `src` of a name of `names`.
fn occurrences(src: &str, names: &HashMap<&str, u32>, odd: &[&str], odd_finder: &aho_corasick::AhoCorasick) -> Vec<(u32, i64)> {
    use unicode_normalization::UnicodeNormalization;
    let mut out = Vec::new();
    let (mut line, mut start) = (1i64, None::<usize>);
    let flush = |from: usize, to: usize, line: i64, out: &mut Vec<(u32, i64)>| {
        let w = &src[from..to];
        let hit = if w.is_ascii() { names.get(w).copied() } else { names.get(w.nfc().collect::<String>().as_str()).copied() };
        if let Some(n) = hit {
            out.push((n, line));
        }
    };
    for (i, c) in src.char_indices() {
        if word_char(c) {
            start.get_or_insert(i);
            continue;
        }
        if let Some(s) = start.take() {
            flush(s, i, line, &mut out);
        }
        if c == '\n' {
            line += 1;
        }
    }
    if let Some(s) = start {
        flush(s, src.len(), line, &mut out);
    }
    if !odd.is_empty() {
        let ident = |c: Option<char>| c.is_some_and(word_char);
        for m in odd_finder.find_overlapping_iter(src) {
            if ident(src[..m.start()].chars().next_back()) || ident(src[m.end()..].chars().next()) {
                continue;
            }
            let line = 1 + src.as_bytes()[..m.start()].iter().filter(|&&b| b == b'\n').count() as i64;
            out.push((names[odd[m.pattern().as_usize()]], line));
        }
        out.sort_by_key(|o| o.1);
    }
    out
}

/// The byte where `name` first stands as a whole word in `line`.
fn word_at(line: &str, name: &str) -> Option<usize> {
    let ident = |c: Option<char>| c.is_some_and(word_char);
    line.match_indices(name).map(|(i, _)| i).find(|&i| !ident(line[..i].chars().next_back()) && !ident(line[i + name.len()..].chars().next()))
}

fn has_word(text: &str, word: &str) -> bool {
    word_at(text, word).is_some()
}

/// Attributes and decorators that change nothing about who calls a definition.
const INERT: &[&str] = &[
    // Rust
    "doc",
    "allow",
    "warn",
    "deny",
    "forbid",
    "expect",
    "inline",
    "must_use",
    "cold",
    "track_caller",
    "deprecated",
    "derive",
    "cfg",
    "rustfmt",
    "clippy",
    "non_exhaustive",
    "repr",
    // Python
    "property",
    "staticmethod",
    "classmethod",
    "cached_property",
    "abstractmethod",
    "override",
    "overload",
    "lru_cache",
    "cache",
    "setter",
    "getter",
    "deleter",
    "dataclass",
    "total_ordering",
    "final",
    "contextmanager",
    "asynccontextmanager",
    "wraps",
    // Java and Kotlin
    "Deprecated",
    "SuppressWarnings",
    "SafeVarargs",
    "Nullable",
    "NonNull",
    "NotNull",
    "CheckForNull",
    "CanIgnoreReturnValue",
    "CheckReturnValue",
    "VisibleForTesting",
    "GwtIncompatible",
    "GwtCompatible",
    "J2ktIncompatible",
    "J2ObjCIncompatible",
    "ParametricNullness",
    "Beta",
    "FunctionalInterface",
    "Contract",
    "Immutable",
    "ThreadSafe",
    "GuardedBy",
    "LazyInit",
    "Weak",
    "RetainedWith",
    "IgnoreJRERequirement",
    "ElementTypesAreNonnullByDefault",
];

/// Facts of one file the rules of its definitions read.
struct Facts<'a> {
    lang: &'a str,
    lines: Vec<&'a str>,
    /// Rust: the file belongs to a library crate
    rust_lib: bool,
    /// Go: the package the file declares
    go_package: Option<&'a str>,
    /// JavaScript and TypeScript: the lines that export something
    exports: Vec<&'a str>,
    /// Python: the file lists names in `__all__`
    py_all: bool,
    /// TypeScript: the file adds to a module or the global scope, whose interfaces merge with its own
    augments: bool,
    src: &'a str,
}

fn file_rules(root: &Path, rel: &str, src: &str, mine: &[&Symbol], all: &[&Symbol]) -> Vec<(i64, Rule)> {
    let lang = crate::langs::detect(rel, Some(src)).map_or("", |s| s.id);
    let lines: Vec<&str> = src.lines().collect();
    let facts = Facts {
        lang,
        rust_lib: lang == "rust" && rust_library(root, rel),
        go_package: (lang == "go").then(|| lines.iter().find_map(|l| l.trim().strip_prefix("package ")).map(|p| p.trim())).flatten(),
        exports: if matches!(lang, "javascript" | "typescript" | "tsx") {
            lines.iter().copied().filter(|l| has_word(l, "export") || has_word(l, "exports")).collect()
        } else {
            Vec::new()
        },
        py_all: lang == "python" && src.contains("__all__"),
        augments: matches!(lang, "typescript" | "tsx") && (src.contains("declare module") || src.contains("declare global")),
        lines,
        src,
    };
    mine.iter()
        .map(|d| {
            // the innermost holder: a class, a type or an impl around it
            let parent = all
                .iter()
                .filter(|p| p.id != d.id && p.start <= d.start && d.end <= p.end && (p.start, p.end) != (d.start, d.end))
                .min_by_key(|p| p.end - p.start);
            (d.id, rule(rel, &facts, d, parent.copied()))
        })
        .collect()
}

/// Whether `rel` is a source file of a Rust library crate: under the `src/` of the nearest
/// directory with a `Cargo.toml` that has a `src/lib.rs` or a `[lib]` table, not a binary.
fn rust_library(root: &Path, rel: &str) -> bool {
    let mut dir = rel.rsplit_once('/').map_or("", |(d, _)| d);
    loop {
        let base = if dir.is_empty() { root.to_path_buf() } else { root.join(dir) };
        if let Ok(toml) = std::fs::read_to_string(base.join("Cargo.toml")) {
            let below = if dir.is_empty() { rel } else { &rel[dir.len() + 1..] };
            let lib = base.join("src/lib.rs").is_file() || toml.lines().any(|l| l.trim() == "[lib]");
            return lib && below.starts_with("src/") && !below.starts_with("src/bin/") && below != "src/main.rs";
        }
        match dir.rsplit_once('/') {
            Some((up, _)) => dir = up,
            None if !dir.is_empty() => dir = "",
            None => return false,
        }
    }
}

/// The line of a definition that names it, from its first line on and past its attributes,
/// decorators and comments, as (0-based index, text).
fn named_line<'a>(f: &Facts<'a>, d: &Symbol) -> (usize, &'a str) {
    let first = (d.start.max(1) - 1) as usize;
    let last = (d.end.max(d.start) as usize).min(first + 40).min(f.lines.len());
    let aside =
        |l: &str| ["@", "#", "//", "/*", "*", "--"].iter().any(|m| l.trim_start().starts_with(m)) || (f.lang == "csharp" && l.trim_start().starts_with('['));
    (first..last)
        .find(|&i| !aside(f.lines[i]) && word_at(f.lines[i], &d.name).is_some())
        .map_or((first, f.lines.get(first).copied().unwrap_or("")), |i| (i, f.lines[i]))
}

/// Whether an attribute or decorator of `d` (above the line that names it, or on that line before
/// the name) may register it: any but the inert ones.
fn registered(f: &Facts, d: &Symbol) -> bool {
    let (at, decl) = named_line(f, d);
    let before = &decl[..word_at(decl, &d.name).unwrap_or(0)];
    let first = (d.start.max(1) - 1) as usize;
    let above = f.lines.get(first..at).unwrap_or(&[]);
    above.iter().map(|l| l.trim()).chain(before.split_whitespace()).any(|a| {
        let Some(body) = a.strip_prefix("#[").or_else(|| a.strip_prefix('@')).or_else(|| a.strip_prefix('[').filter(|_| f.lang == "csharp")) else {
            return false;
        };
        let head = body.split(['(', ']', ' ']).next().unwrap_or("");
        let last = head.rsplit(['.', ':']).next().unwrap_or(head);
        !(last.is_empty() || (last == "cfg" && !body.starts_with("cfg(test")) || INERT.contains(&last))
    })
}

fn rule(path: &str, f: &Facts, d: &Symbol, parent: Option<&Symbol>) -> Rule {
    let name = d.name.as_str();
    if crate::text::is_test_path(path) || name == "main" {
        return Rule::Entry;
    }
    let in_type = parent.filter(|p| p.kind != "function" && p.kind != "method");
    // an attribute on the type or impl around it registers its methods too (`#[pymethods]`)
    if registered(f, d) || in_type.is_some_and(|p| registered(f, p)) {
        return Rule::Entry;
    }
    let decl = named_line(f, d).1;
    let before = &decl[..word_at(decl, name).unwrap_or(0)];
    let words: Vec<&str> = before.split(|c: char| !word_char(c)).filter(|w| !w.is_empty()).collect();
    let word = |w: &str| words.contains(&w);
    if word("override") || matches!(name, "constructor" | "initialize") || parent.is_some_and(|p| p.name == name) {
        return Rule::Entry;
    }
    let header = |p: &Symbol| named_line(f, p).1;
    match f.lang {
        "python" => {
            let quoted = || f.src.contains(&format!("'{name}'")) || f.src.contains(&format!("\"{name}\""));
            // `__x__` and hooks such as `__lldb_init_module` are called by name by their host
            if name.starts_with("__") || name.starts_with("test") || (f.py_all && quoted()) {
                return Rule::Entry;
            }
        }
        "rust" => {
            let trait_impl = in_type.is_some_and(|p| {
                let first = (p.start.max(1) - 1) as usize;
                f.lines[first..f.lines.len().min(p.end as usize)].iter().find(|l| has_word(l, "impl")).is_some_and(|l| l.contains(" for "))
            });
            let public = |b: &str| b.split_whitespace().any(|w| w == "pub");
            let pub_trait = in_type.is_some_and(|p| p.kind == "trait" && public(header(p)));
            // `write!` calls a `write_fmt` method of its first argument without naming it
            if word("extern") || trait_impl || (f.rust_lib && (public(before) || pub_trait)) || name == "write_fmt" {
                return Rule::Entry;
            }
        }
        "go" => {
            let exported = name.chars().next().is_some_and(char::is_uppercase);
            if name == "init" || (exported && (f.go_package != Some("main") || d.qualname.contains('.'))) {
                return Rule::Entry;
            }
        }
        "javascript" | "typescript" | "tsx" => {
            let exported_class = in_type.is_some_and(|p| has_word(header(p), "export"));
            let merged = f.augments && matches!(d.kind.as_str(), "interface" | "type" | "class");
            if path.ends_with(".d.ts") || merged || word("export") || exported_class || f.exports.iter().any(|l| has_word(l, name)) {
                return Rule::Entry;
            }
        }
        "java" | "csharp" => {
            let serial = f.lang == "java" && matches!(name, "readObject" | "writeObject" | "readObjectNoData" | "readResolve" | "writeReplace");
            if word("public") || word("protected") || word("internal") || in_type.is_some_and(|p| p.kind == "interface") || serial {
                return Rule::Entry;
            }
        }
        // public unless marked otherwise
        "kotlin" | "scala" | "groovy" | "php" if !(word("private") || word("internal") || (f.lang == "php" && in_type.is_none())) => return Rule::Entry,
        "php" if name.starts_with("__") => return Rule::Entry,
        "swift" if word("public") || word("open") => return Rule::Entry,
        "dart" if !name.starts_with('_') => return Rule::Entry,
        // the engine calls `_ready`, `_process` and the other virtual functions
        "gdscript" if name.starts_with('_') => return Rule::Entry,
        // a target is run by its name from outside: `make check`
        "make" => return Rule::Entry,
        _ => {}
    }
    if [".vue", ".svelte", ".astro"].iter().any(|e| path.ends_with(e)) {
        return Rule::Base("nothing else names it, but the template of its component may use it".to_string());
    }
    let class = in_type.is_some_and(|p| matches!(p.kind.as_str(), "class" | "struct" | "interface" | "trait" | "impl" | "enum"));
    if matches!(f.lang, "javascript" | "typescript" | "tsx") && d.kind == "method" && !class {
        return Rule::Base("nothing else names it, but it is a property of an object, which code may call by its key".to_string());
    }
    if let Some(p) = in_type.filter(|p| extends(f.lang, header(p), &p.name)) {
        return Rule::Base(format!("nothing else names it, but its type {} extends another, whose code may call it", p.name));
    }
    if in_type.is_none() && matches!(d.kind.as_str(), "class" | "struct") && extends(f.lang, decl, name) {
        return Rule::Base("nothing else names it, but it extends another type, which may find it without its name".to_string());
    }
    Rule::Plain
}

/// Whether the line that names type `name` says it extends or implements another.
fn extends(lang: &str, header: &str, name: &str) -> bool {
    let Some(at) = word_at(header, name) else { return false };
    let after = header[at + name.len()..].trim().trim_end_matches(|c: char| c == '{' || c == ':' || c.is_whitespace());
    match lang {
        "python" => after.strip_prefix('(').and_then(|a| a.strip_suffix(')')).is_some_and(|bases| !matches!(bases.trim(), "" | "object")),
        "ruby" => after.starts_with('<'),
        _ => after.starts_with(':') || ["extends", "implements", "with", "inherits"].iter().any(|w| has_word(after, w)),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_name_counts_as_a_whole_word_in_any_spelling_of_its_letters() {
        let names: HashMap<&str, u32> = [("run", 0), ("café", 1)].into_iter().collect();
        let odd = ["valid?"];
        let mut all = names.clone();
        all.insert("valid?", 2);
        let finder = aho_corasick::AhoCorasick::new(odd).unwrap();
        let src = "run()\nrerun run_it $run\ncafe\u{301} x.valid? valid?x\n";
        assert_eq!(occurrences(src, &all, &odd, &finder), [(0, 1), (0, 2), (1, 3), (2, 3)]);
    }

    #[test]
    fn a_header_that_names_a_base_type_extends_it() {
        assert!(extends("python", "class Handler(BaseHandler):", "Handler"));
        assert!(!extends("python", "class Plain:", "Plain") && !extends("python", "class Plain(object):", "Plain"));
        assert!(extends("typescript", "export class A extends B {", "A") && extends("csharp", "class A : B", "A") && extends("ruby", "class A < B", "A"));
        assert!(!extends("java", "class A {", "A"));
    }
}

//! Which files belong to the repository, for each index. Engine A's default walk (which the text
//! index reuses) is `instant::build_walker`; the code index's set is `list_files`, walked by
//! `CodeWalk`; an Engine A search of the repository reads that walk's files
//! (`repository_files`); `Membership` asks that walk about one path.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use crate::index::Stat;
use crate::parse::is_indexable;

/// Where the indexes live under the repository root; no walk enters it.
pub const INDEX_DIR: &str = ".scrutate";

/// `root/.scrutate`, once `root` is an existing directory and nothing the indexes write into is
/// a symbolic link (which would put the index, and its deletions, outside the repository).
pub fn index_dir(root: &Path) -> anyhow::Result<PathBuf> {
    if !root.is_dir() {
        anyhow::bail!("{}: {}", root.display(), if root.exists() { "not a directory" } else { "no such directory" });
    }
    let dir = root.join(INDEX_DIR);
    let refuse = |p: &Path| anyhow::bail!("{} is a symbolic link; the index is only written inside the repository (remove it)", p.display());
    if std::fs::symlink_metadata(&dir).map(|m| m.file_type().is_symlink()).unwrap_or(false) {
        return refuse(&dir);
    }
    // every name the index writes is three levels deep at most (seg/s000001/ids.npy); entry types
    // come from the directory listing, so this costs no stat per file
    let mut todo = vec![(dir.clone(), 0)];
    while let Some((d, depth)) = todo.pop() {
        let Ok(rd) = std::fs::read_dir(&d) else { continue };
        for e in rd.flatten() {
            let Ok(ft) = e.file_type() else { continue };
            if ft.is_symlink() {
                return refuse(&e.path());
            }
            if ft.is_dir() && depth < 2 {
                todo.push((e.path(), depth + 1));
            }
        }
    }
    Ok(dir)
}

/// The main checkout of the linked git work tree whose top is `root`, read from git's own files
/// (no program is run): the `.git` file names `<common dir>/worktrees/<name>`, whose `gitdir`
/// file names this `.git` file back and whose `commondir` names the common directory, which is
/// the `.git` directory of the main checkout. None for anything else: a main checkout, a bare
/// repository, a link that is not confirmed both ways.
pub fn main_checkout(root: &Path) -> Option<PathBuf> {
    let dot = root.join(".git");
    let gitdir = PathBuf::from(small_file(&dot)?.strip_prefix("gitdir:")?.trim());
    let gitdir = std::fs::canonicalize(root.join(gitdir)).ok()?;
    let back = PathBuf::from(small_file(&gitdir.join("gitdir"))?);
    if std::fs::canonicalize(gitdir.join(back)).ok()? != std::fs::canonicalize(&dot).ok()? {
        return None;
    }
    let common = std::fs::canonicalize(gitdir.join(small_file(&gitdir.join("commondir"))?)).ok()?;
    let worktrees = gitdir.parent()?;
    if worktrees.file_name()? != "worktrees" || worktrees.parent()? != common || common.file_name()? != ".git" {
        return None;
    }
    let main = common.parent()?.to_path_buf();
    let is_dir = std::fs::symlink_metadata(main.join(".git")).ok()?.is_dir();
    (is_dir && main != std::fs::canonicalize(root).ok()?).then_some(main)
}

/// The bytes of `path` when it is a regular file of at most `max` bytes, not reached through a
/// symbolic link: a cache file planted in a repository's `.scrutate/` cannot make a read endless.
pub fn read_regular(path: &Path, max: u64) -> Option<Vec<u8>> {
    use std::io::Read;
    if !std::fs::symlink_metadata(path).ok()?.is_file() {
        return None;
    }
    let f = std::fs::File::open(path).ok()?;
    let md = f.metadata().ok()?;
    if !md.is_file() || md.len() > max {
        return None;
    }
    let mut out = Vec::with_capacity(md.len() as usize);
    f.take(max + 1).read_to_end(&mut out).ok()?;
    (out.len() as u64 <= max).then_some(out)
}

/// The first line of a regular file of at most 4 KiB, trimmed.
fn small_file(path: &Path) -> Option<String> {
    let md = std::fs::symlink_metadata(path).ok()?;
    if !md.is_file() || md.len() > 4096 {
        return None;
    }
    let text = std::fs::read_to_string(path).ok()?;
    Some(text.lines().next()?.trim().to_string())
}

const SKIP_DIRS: &[&str] = &[
    ".git",
    INDEX_DIR,
    "node_modules",
    "__pycache__",
    ".venv",
    "venv",
    "dist",
    "build",
    ".mypy_cache",
    ".pytest_cache",
    "target",
    ".next",
    ".tox",
    ".idea",
    ".vscode",
];

/// Build and environment directories some projects commit; inside a git repository the ignore
/// files decide for them.
const SKIP_UNLESS_GIT: &[&str] = &["build", "dist", "target", "venv"];

fn in_git(root: &Path) -> bool {
    root.ancestors().any(|a| a.join(".git").exists())
}

/// Most names `exclude_dirs` of a repository's `.scrutate.toml` adds; the rest are not read.
const MAX_CONFIG_EXCLUDES: usize = 1000;

/// Directory names the code index of `root` never enters: `SKIP_DIRS` (less `SKIP_UNLESS_GIT`
/// inside a git repository) plus those in `SCRUTATE_INDEX_EXCLUDE_DIRS`, or when it is not set,
/// in `[index] exclude_dirs` of `<root>/.scrutate.toml`. A name with a path separator or a
/// backslash, `.` and `..` name no directory and are dropped.
fn skip_dirs(root: &Path) -> Vec<String> {
    let git = in_git(root);
    let mut skip: Vec<String> = SKIP_DIRS.iter().filter(|d| !(git && SKIP_UNLESS_GIT.contains(d))).map(|s| s.to_string()).collect();
    match std::env::var("SCRUTATE_INDEX_EXCLUDE_DIRS") {
        Ok(v) => skip.extend(split_names(&v).into_iter().filter(|n| is_dir_name(n))),
        Err(_) => skip.extend(config_excludes(root)),
    }
    skip
}

/// A name `exclude_dirs` can use: a backslash is a separator on Windows and an escape in the
/// `!name` glob of `grep_code`.
fn is_dir_name(n: &str) -> bool {
    n != "." && n != ".." && !n.chars().any(|c| std::path::is_separator(c) || c == '\\')
}

/// `[index] exclude_dirs` of the root's own `.scrutate.toml` (`root_config_text`): the setting
/// belongs to the index, so every process that updates it reads the same list, wherever it
/// starts. Names that are no directory name are dropped.
pub(crate) fn config_excludes(root: &Path) -> Vec<String> {
    let Some(text) = root_config_text(root) else { return Vec::new() };
    let Ok(table) = text.parse::<toml::Table>() else { return Vec::new() };
    let names = table.get("index").and_then(|i| i.get("exclude_dirs")).and_then(|v| v.as_array());
    names
        .map(|a| {
            let names = a.iter().filter_map(|v| v.as_str()).map(|n| n.trim().to_string()).filter(|n| !n.is_empty());
            names.take(MAX_CONFIG_EXCLUDES).filter(|n| is_dir_name(n)).collect()
        })
        .unwrap_or_default()
}

/// The text of the root's own `.scrutate.toml`, read as other repository files are: after links
/// are resolved, a regular file inside the root of at most 1,000,000 bytes.
pub(crate) fn root_config_text(root: &Path) -> Option<String> {
    let root = std::fs::canonicalize(root).unwrap_or_else(|_| root.to_path_buf());
    let real = std::fs::canonicalize(root.join(".scrutate.toml")).ok()?;
    crate::resolve::repo_text(&root, real.strip_prefix(&root).ok()?.to_str()?)
}

/// A comma-separated list of names; `\,` is a comma inside a name.
pub fn split_names(v: &str) -> Vec<String> {
    let mut out = vec![String::new()];
    let mut chars = v.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '\\' if chars.peek() == Some(&',') => out.last_mut().unwrap().push(chars.next().unwrap()),
            ',' => out.push(String::new()),
            _ => out.last_mut().unwrap().push(c),
        }
    }
    out.into_iter().map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect()
}

/// The directory names the code index of `root` never enters.
pub fn skipped_dirs(root: &Path) -> Vec<String> {
    skip_dirs(root)
}

/// The files an Engine A search of the repository covers, walked by the code index's rules: the
/// ignore files, hidden files included, none of the skipped directories.
pub fn repository_files(root: &Path) -> crate::instant::Files {
    // a name, never a pattern: `*` in a repository's exclude_dirs must not hide every file
    let globs = skip_dirs(root).into_iter().map(|d| {
        d.chars().fold("!".to_string(), |mut g, c| {
            if "*?[]{}".contains(c) {
                g.extend(['[', c, ']']);
            } else {
                g.push(c);
            }
            g
        })
    });
    crate::instant::Files { hidden: true, globs: globs.collect(), ..crate::instant::Files::walk(vec![root.to_path_buf()]) }
}

/// Relative paths ('/' separated, sorted) of the files worth indexing: the same rules as ripgrep's
/// file listing (.gitignore, hidden files) plus the usual build/vendor directories.
pub fn list_files(root: &Path) -> Vec<String> {
    let walk = CodeWalk::new(root);
    let mut out: Vec<String> = walk.builder(root).build().flatten().filter_map(|e| walk.keeps(&e)).collect();
    out.sort();
    out
}

/// A file one look at the tree found.
#[derive(Clone, Debug, PartialEq)]
pub struct Found {
    /// from the root, '/' separated
    pub path: String,
    /// the file's `stat`, taken by the look when a store needs it (None when none does, or it failed)
    pub stat: Option<Stat>,
    /// a search of the repository covers it (`repository_files`)
    pub repo: bool,
    /// the code index holds it (`list_files`)
    pub code: bool,
    /// the text index's walk (Engine A's default walk) lists it
    pub text: bool,
    /// the name is not UTF-8, so `path` names it only in part
    pub lossy: bool,
}

/// The files of the tree at `root`, from one walk and one `stat` per file a store needs, sorted by
/// path: the files a search of the repository covers and the code index's set, and with `text`
/// the text index's set too. The walk enters every directory one of those walks enters.
pub fn look(root: &Path, text: bool) -> anyhow::Result<Vec<Found>> {
    let walk = CodeWalk::new(root);
    let rules = match text {
        true => Some(Arc::new(std::sync::Mutex::new(crate::instant::default_rules(root)?))),
        false => None,
    };
    let left_out = |rules: &std::sync::Mutex<ignore::IncrementalIgnore>, rel: &Path, is_dir: bool| {
        maybe_hidden(rel) && rules.lock().unwrap_or_else(|p| p.into_inner()).matched(rel, is_dir).is_ignore()
    };
    let (skip, base, held) = (walk.skip.clone(), root.to_path_buf(), rules.clone());
    let mut wb = CodeWalk::rules(root);
    // a directory the code index skips is still entered when the text index's walk enters it
    wb.filter_entry(move |e| {
        let skipped = e.file_type().is_some_and(|t| t.is_dir()) && skip.iter().any(|s| *s == *e.file_name().to_string_lossy());
        !skipped || held.as_ref().is_some_and(|r| !e.path().strip_prefix(&base).is_ok_and(|rel| left_out(r, rel, true)))
    });
    let mut out = Vec::new();
    for e in wb.build().flatten() {
        if !e.file_type().is_some_and(|t| t.is_file()) {
            continue;
        }
        let Ok(rel) = e.path().strip_prefix(root) else { continue };
        let path = slashed(rel);
        let repo = !path.split('/').any(|n| walk.skip.iter().any(|s| s == n));
        let code = repo && e.file_name() != ".git" && is_indexable(&path);
        let text = rules.as_ref().is_some_and(|r| !left_out(r, rel, false));
        if !(repo || text) {
            continue;
        }
        let stat = if code || text { e.metadata().ok().map(|m| Stat::of(&m)) } else { None };
        out.push(Found { lossy: rel.to_str().is_none(), path, stat, repo, code, text });
    }
    out.sort_by(|a, b| a.path.cmp(&b.path));
    Ok(out)
}

/// Whether the default walk can leave out a path the code index's walk lists: a name on the way
/// starts with a dot (on Windows, any name may carry the hidden attribute).
fn maybe_hidden(rel: &Path) -> bool {
    cfg!(windows) || rel.components().any(|c| c.as_os_str().as_encoded_bytes().starts_with(b"."))
}

/// The code index's walk of a root. Started at a directory the root's walk enters, it lists that
/// directory as the root's walk does: the ignore files of every directory above it apply.
pub struct CodeWalk {
    root: PathBuf,
    skip: Arc<Vec<String>>,
}

impl CodeWalk {
    pub fn new(root: &Path) -> CodeWalk {
        CodeWalk { root: root.to_path_buf(), skip: Arc::new(skip_dirs(root)) }
    }

    pub fn builder(&self, start: &Path) -> ignore::WalkBuilder {
        let skip = self.skip.clone();
        let mut wb = Self::rules(start);
        wb.filter_entry(move |e| !(e.file_type().is_some_and(|t| t.is_dir()) && skip.iter().any(|s| *s == *e.file_name().to_string_lossy())));
        wb
    }

    /// The walk's ignore rules, without the skipped directories.
    fn rules(start: &Path) -> ignore::WalkBuilder {
        // hidden files are indexed (.github/workflows/*.yml, .eslintrc.js, .env.example are code or
        // config people search for); SKIP_DIRS prunes VCS internals and caches
        let mut wb = ignore::WalkBuilder::new(start);
        wb.hidden(false)
            .git_ignore(true)
            .git_global(true)
            .git_exclude(true)
            .ignore(true)
            .parents(true)
            .add_custom_ignore_filename(crate::instant::RGIGNORE)
            .follow_links(false);
        wb
    }

    /// The path from the root of a file the walk yielded, when the code index holds that file.
    pub fn keeps(&self, e: &ignore::DirEntry) -> Option<String> {
        // a `.git` *file* (worktree or submodule pointer) is VCS metadata, not source
        if !e.file_type().is_some_and(|t| t.is_file()) || e.file_name() == ".git" {
            return None;
        }
        let rel = slashed(e.path().strip_prefix(&self.root).ok()?);
        self.indexable(&rel).then_some(rel)
    }

    fn indexable(&self, rel: &str) -> bool {
        is_indexable(rel) && !rel.split('/').any(|n| self.skip.iter().any(|s| s == n))
    }
}

pub(crate) fn slashed(rel: &Path) -> String {
    rel.components().map(|c| c.as_os_str().to_string_lossy().into_owned()).collect::<Vec<_>>().join("/")
}

/// Whether the code index's walk lists one path: each directory from the root down to it is listed
/// with the walk's own rules. A path that does not exist is judged by its directory.
pub struct Membership {
    walk: CodeWalk,
}

impl Membership {
    pub fn new(root: &Path) -> Membership {
        Membership { walk: CodeWalk::new(root) }
    }

    pub fn may_contain(&mut self, path: &Path) -> bool {
        let Ok(rel) = path.strip_prefix(&self.walk.root) else { return false };
        let names: Vec<_> = rel.components().map(|c| c.as_os_str().to_os_string()).collect();
        let mut dir = self.walk.root.clone();
        for (i, name) in names.iter().enumerate() {
            let next = dir.join(name);
            let last = i + 1 == names.len();
            if last && std::fs::symlink_metadata(&next).is_err() {
                return self.walk.indexable(&slashed(rel));
            }
            let Some(e) = self.walk.builder(&dir).max_depth(Some(1)).build().flatten().find(|e| e.depth() == 1 && e.path() == next) else {
                return false;
            };
            if last {
                return e.file_type().is_some_and(|t| t.is_dir()) || self.walk.keeps(&e).is_some();
            }
            dir = next;
        }
        false
    }
}

#[cfg(test)]
mod tests {

    #[test]
    fn a_cache_file_is_read_only_as_a_regular_file_within_its_limit() {
        let d = std::env::temp_dir().join(format!("scrutate_read_regular_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&d);
        std::fs::create_dir_all(&d).unwrap();
        std::fs::write(d.join("small"), b"12345").unwrap();
        assert_eq!(read_regular(&d.join("small"), 5).as_deref(), Some(&b"12345"[..]));
        assert_eq!(read_regular(&d.join("small"), 4), None, "over the limit");
        assert_eq!(read_regular(&d, 100), None, "a directory");
        assert_eq!(read_regular(&d.join("missing"), 100), None);
        #[cfg(unix)]
        {
            std::os::unix::fs::symlink(d.join("small"), d.join("link")).unwrap();
            assert_eq!(read_regular(&d.join("link"), 100), None, "a symbolic link");
            std::os::unix::fs::symlink("/dev/zero", d.join("zero")).unwrap();
            assert_eq!(read_regular(&d.join("zero"), 100), None, "a device behind a link");
        }
        let _ = std::fs::remove_dir_all(&d);
    }
    use super::*;

    /// A tree under the temporary directory; a name ending in `/` is a directory.
    fn tree(name: &str, entries: &[(&str, &str)]) -> PathBuf {
        let root = std::env::temp_dir().join(format!("scrutate_files_{name}_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        for (rel, text) in entries {
            let p = root.join(rel);
            if rel.ends_with('/') {
                std::fs::create_dir_all(&p).unwrap();
            } else {
                std::fs::create_dir_all(p.parent().unwrap()).unwrap();
                std::fs::write(&p, text).unwrap();
            }
        }
        std::fs::canonicalize(&root).unwrap()
    }

    fn every_file(dir: &Path, out: &mut Vec<PathBuf>) {
        for e in std::fs::read_dir(dir).unwrap().flatten() {
            if e.file_type().unwrap().is_dir() {
                every_file(&e.path(), out);
            } else {
                out.push(e.path());
            }
        }
    }

    /// For the index rooted at `root`: `Membership` answers every file of the tree as `list_files`
    /// lists it, and a walk started at each directory the root's walk enters lists that directory's
    /// files as the root's walk does. -> what `list_files` holds.
    fn agrees(root: &Path) -> Vec<String> {
        let walked = list_files(root);
        let mut m = Membership::new(root);
        let mut files = Vec::new();
        every_file(root, &mut files);
        for f in &files {
            let rel = slashed(f.strip_prefix(root).unwrap());
            assert_eq!(m.may_contain(f), walked.contains(&rel), "membership of {rel} ({walked:?})");
        }
        let walk = CodeWalk::new(root);
        for d in walk.builder(root).build().flatten().filter(|e| e.file_type().is_some_and(|t| t.is_dir())) {
            let mut here: Vec<String> = walk.builder(d.path()).max_depth(Some(1)).build().flatten().filter_map(|e| walk.keeps(&e)).collect();
            here.sort();
            let from_root: Vec<String> = walked.iter().filter(|p| root.join(p).parent() == Some(d.path())).cloned().collect();
            assert_eq!(here, from_root, "the walk started at {}", d.path().display());
        }
        looks_agree(root);
        walked
    }

    /// One look gives each store, path for path and stat for stat, what its own walk gives: the
    /// code index `list_files`, a search of the repository the walk of `repository_files`, the
    /// text index Engine A's default walk; a look without the text index the same first two.
    fn looks_agree(root: &Path) -> usize {
        let both = look(root, true).unwrap();
        let code: Vec<String> = both.iter().filter(|f| f.code).map(|f| f.path.clone()).collect();
        assert_eq!(code, list_files(root), "the code index's files of {}", root.display());
        let stat = |p: &str| std::fs::symlink_metadata(root.join(p)).ok().map(|m| Stat::of(&m));
        assert!(both.iter().filter(|f| f.code || f.text).all(|f| f.stat == stat(&f.path)), "a stat of each file");
        let text: Vec<(String, u64, i64, i64)> =
            both.iter().filter(|f| f.text).map(|f| f.stat.map_or((f.path.clone(), 0, 0, 0), |s| (f.path.clone(), s.size as u64, s.mtime, s.ctime))).collect();
        assert_eq!(text, crate::textindex::walk(root).unwrap(), "the text index's files of {}", root.display());
        let found = std::sync::Mutex::new(Vec::new());
        crate::instant::build_walker(&[root.to_path_buf()], &repository_files(root)).unwrap().run(|| {
            Box::new(|e| {
                if let Some(e) = e.ok().filter(|e| e.file_type().is_some_and(|t| t.is_file())) {
                    found.lock().unwrap().push(slashed(e.path().strip_prefix(root).unwrap()));
                }
                ignore::WalkState::Continue
            })
        });
        let mut repo = found.into_inner().unwrap();
        repo.sort();
        assert_eq!(both.iter().filter(|f| f.repo).map(|f| f.path.clone()).collect::<Vec<_>>(), repo, "a search's files of {}", root.display());
        let alone = look(root, false).unwrap();
        assert_eq!(alone.iter().filter(|f| f.code).map(|f| &f.path).collect::<Vec<_>>(), code.iter().collect::<Vec<_>>());
        assert_eq!(alone.iter().filter(|f| f.repo).map(|f| f.path.clone()).collect::<Vec<_>>(), repo);
        both.len()
    }

