        std::fs::write(&file, b"{not json").unwrap();
        let mut s = State::load(&file);
        assert!(s.roots.is_empty());
        s.visit("r", "a", 1.0);
        s.save(&file).unwrap();
        assert!((State::load(&file).frecency("r", "a", 1.0) - 1.0).abs() < 1e-9);
        assert_eq!(std::fs::read_dir(&dir).unwrap().count(), 1, "no temporary file is left");
        std::fs::remove_dir_all(&dir).unwrap();
    }
}

//! Plain-text rendering of hits.

use std::borrow::Cow;

use crate::search::Hit;

/// What `shown` wrote, read back: `\\n`, `\\r`, `\\t`, `\\xHH` and `\\u{H}` become the characters,
/// and `\\\\` one backslash.
pub fn unshown(s: &str) -> Cow<'_, str> {
    if !s.contains('\\') {
        return Cow::Borrowed(s);
    }
    let mut out = String::with_capacity(s.len());
    let mut rest = s;
    while let Some(i) = rest.find('\\') {
        out.push_str(&rest[..i]);
        let tail = &rest[i + 1..];
        let hex = |digits: Option<&str>| digits.and_then(|d| u32::from_str_radix(d, 16).ok()).and_then(char::from_u32);
        let (c, used) = match tail.as_bytes().first() {
            Some(b'\\') => (Some('\\'), 1),
            Some(b'n') => (Some('\n'), 1),
            Some(b'r') => (Some('\r'), 1),
            Some(b't') => (Some('\t'), 1),
            Some(b'x') => (hex(tail.get(1..3)), 3),
            Some(b'u') => match tail.find('}') {
                Some(end) if tail.starts_with("u{") => (hex(tail.get(2..end)), end + 1),
                _ => (None, 0),
            },
            _ => (None, 0),
        };
        match c {
            Some(c) => {
                out.push(c);
                rest = &tail[used..];
            }
            None => {
                out.push('\\');
                rest = tail;
            }
        }
    }
    out.push_str(rest);
    Cow::Owned(out)
}

/// Text as one line a terminal shows as it is: control characters written as escapes (`\n`,
/// `\x1b`), so a file name cannot start a line of its own or move the cursor, and a backslash
/// written as two, so an escape and a real backslash never print alike.
pub fn shown(s: &str) -> Cow<'_, str> {
    escaped(s, true)
}

fn escaped(s: &str, backslash: bool) -> Cow<'_, str> {
    if !s.chars().any(|c| c.is_control() || (backslash && c == '\\')) {
        return Cow::Borrowed(s);
    }
    let mut out = String::with_capacity(s.len() + 8);
    for c in s.chars() {
        match c {
            '\\' if backslash => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() && (c as u32) < 0x100 => out.push_str(&format!("\\x{:02x}", c as u32)),
            c if c.is_control() => out.push_str(&format!("\\u{{{:x}}}", c as u32)),
            c => out.push(c),
        }
    }
    Cow::Owned(out)
}

/// Characters of an argument an error message repeats.
const ECHO_CHARS: usize = 200;

/// An argument as an error message repeats it: control characters escaped as `shown` does (a
/// backslash stays one, as the caller wrote it), and cut to its first 200 characters.
pub fn echo(s: &str) -> String {
    let n = s.chars().count();
    if n <= ECHO_CHARS {
        return escaped(s, false).into_owned();
    }
    let head: String = s.chars().take(ECHO_CHARS).collect();
    format!("{}... (cut: {n} characters in all)", escaped(&head, false))
}

/// `path:start-end` of a hit, as text.
pub fn loc(h: &Hit) -> String {
    format!("{}:{}-{}", shown(&h.path), h.start, h.end)
}

pub fn fmt_hits(hits: &[Hit], words: &[String], snippet: bool, why: bool) -> String {
    if hits.is_empty() {
        return "(no results)".to_string();
    }
    hit_blocks(hits, words, snippet, why).join("\n")
}

/// One block of text per hit: its location line and, with `snippet`, the lines that matter.
pub fn hit_blocks(hits: &[Hit], words: &[String], snippet: bool, why: bool) -> Vec<String> {
    let mut out = Vec::with_capacity(hits.len());
    for h in hits {
        let name = if h.qualname.is_empty() { &h.name } else { &h.qualname };
        let mut head = format!("{}  [{}] {}", loc(h), h.kind, shown(name));
        if why && !h.why.is_empty() {
            head.push_str(&format!("  ({})", h.why.iter().map(|(k, _)| k.as_str()).collect::<Vec<_>>().join(", ")));
        }
        if snippet {
            let body = h.snippet(words, 8);
            head.push('\n');
            head.push_str(&body.split('\n').map(|l| format!("    {l}")).collect::<Vec<_>>().join("\n"));
        }
        out.push(head);
    }
    out
}

pub fn hits_json(hits: &[Hit]) -> serde_json::Value {
    serde_json::Value::Array(
        hits.iter()
            .map(|h| {
                let why: serde_json::Map<String, serde_json::Value> = h.why.iter().cloned().collect();
                serde_json::json!({
                    "id": h.loc(), "path": h.path, "start": h.start, "end": h.end,
                    "name": if h.qualname.is_empty() { &h.name } else { &h.qualname },
                    "kind": h.kind, "score": h.score, "why": why,
                })
            })
            .collect(),
    )
}

//! Candidate lines for a case-insensitive literal: two bytes of the needle, each in either case
//! form, at a fixed distance, then a check of the stretch of the needle around them.
//!
//! The needle is the regex engine's own view of the pattern (parsed with case folding), so each
//! position holds exactly the characters the regex accepts there. Offsets between positions are
//! fixed only across a run of positions whose every form has the same byte length: `k` matches
//! KELVIN SIGN (3 bytes) and `ß` matches U+1E9E (3 bytes), so a run ends before such a position.
//! The two scanned bytes lie in one run, each at an offset where the forms hold one byte value or
//! two that differ only in bit 0x20 (`a`/`A`, the last byte of `ö`/`Ö`); the candidate offset
//! reported is the run's start, which lies inside any match. A candidate is checked against the
//! first `CHECKED` bytes of the run only, so the scan stays linear on repetitive text; the
//! searcher confirms the whole line anyway.

use regex_syntax::hir::{Class, Hir, HirKind};

/// One position of the needle: the byte strings that match it, or `None` when they differ in length.
type Forms = Option<Vec<Vec<u8>>>;

#[derive(Clone, Debug)]
pub struct FoldFinder {
    /// the forms of each position of the run's first `CHECKED` bytes, all of one length per position
    run: Vec<Vec<Vec<u8>>>,
    len: usize,
    a: usize,
    b: usize,
    /// a byte `x` at a scanned offset fits when `x | mask == target`
    mask_a: u8,
    target_a: u8,
    mask_b: u8,
    target_b: u8,
}

/// How much of the run a candidate is checked against.
const CHECKED: usize = 16;

/// Bytes common in source code, the most common first; all others count as rare.
const COMMON: &[u8] = b" etianosrlcdu_()hp,mf;=g*b.yvwx/-0>1\"{}[]2#q&j!z<3:+%";

fn commonness(lower: u8) -> usize {
    COMMON.iter().position(|&c| c == lower).map_or(0, |p| COMMON.len() - p)
}

fn positions(hir: &Hir, out: &mut Vec<Forms>) -> Option<()> {
    match hir.kind() {
        HirKind::Literal(lit) => out.extend(lit.0.iter().map(|&b| Some(vec![vec![b]]))),
        HirKind::Class(Class::Unicode(c)) => {
            let chars: Vec<char> = c.iter().flat_map(|r| r.start()..=r.end()).take(5).collect();
            if chars.len() > 4 {
                out.push(None);
            } else {
                let forms: Vec<Vec<u8>> = chars.iter().map(|ch| ch.to_string().into_bytes()).collect();
                out.push(forms.iter().all(|f| f.len() == forms[0].len()).then_some(forms));
            }
        }
        HirKind::Class(Class::Bytes(c)) => {
            let bytes: Vec<u8> = c.iter().flat_map(|r| r.start()..=r.end()).take(5).collect();
            out.push((bytes.len() <= 4).then(|| bytes.iter().map(|&b| vec![b]).collect()));
        }
        HirKind::Concat(xs) => xs.iter().try_for_each(|x| positions(x, out))?,
        _ => return None,
    }
    Some(())
}

/// The scan test for byte `k` of a position's forms: a byte `x` fits when `x | mask == target`.
fn scan_test(forms: &[Vec<u8>], k: usize) -> Option<(u8, u8)> {
    let mut bytes: Vec<u8> = forms.iter().map(|f| f[k]).collect();
    bytes.sort_unstable();
    bytes.dedup();
    match bytes[..] {
        [x] => Some((0, x)),
        [x, y] if x ^ y == 0x20 => Some((0x20, y)),
        _ => None,
    }
}

impl FoldFinder {
    /// The finder for `pattern` searched case-insensitively, when it is a literal with two
    /// usable positions in one run.
    pub fn new(pattern: &str) -> Option<FoldFinder> {
        let hir = regex_syntax::ParserBuilder::new().case_insensitive(true).build().parse(pattern).ok()?;
        let mut pos = Vec::new();
        positions(&hir, &mut pos)?;
        if pos.iter().flatten().flatten().any(|f| f.contains(&b'\n')) {
            return None;
        }
        let mut best: Option<(usize, FoldFinder)> = None;
        for run in pos.split(Option::is_none) {
            let mut run: Vec<Vec<Vec<u8>>> = run.iter().flatten().cloned().collect();
            let mut at = 0;
            let mut cands = Vec::new();
            for forms in &run {
                for k in 0..forms[0].len() {
                    if let Some((mask, target)) = scan_test(forms, k) {
                        cands.push((commonness(target), at + k, mask, target));
                    }
                }
                at += forms[0].len();
            }
            if cands.len() < 2 {
                continue;
            }
            // the rarest byte, then the rarest other one, farther away on a tie
            cands.sort_by_key(|c| c.0);
            let first = cands[0];
            let second = *cands[1..].iter().min_by_key(|c| (c.0, usize::MAX - c.1.abs_diff(first.1))).unwrap();
            let score = first.0 + second.0;
            if best.as_ref().is_some_and(|(s, _)| *s <= score) {
                continue;
            }
            let (x, y) = if first.1 < second.1 { (first, second) } else { (second, first) };
            let mut off = 0;
            let checked = run
                .iter()
                .take_while(|f| {
                    off += f[0].len();
                    off - f[0].len() < CHECKED
                })
                .count();
            run.truncate(checked);
            let f = FoldFinder { run, len: at, a: x.1, b: y.1, mask_a: x.2, target_a: x.3, mask_b: y.2, target_b: y.3 };
            best = Some((score, f));
        }
        best.map(|(_, f)| f)
    }

    fn fits(&self, hay: &[u8], i: usize) -> bool {
        (hay[i + self.a] | self.mask_a) == self.target_a && (hay[i + self.b] | self.mask_b) == self.target_b
    }

    /// Whether the checked part of the run matches at `i`; `i + len <= hay.len()`.
    fn run_at(&self, hay: &[u8], i: usize) -> bool {
        let mut at = i;
        for forms in &self.run {
            if !forms.iter().any(|f| hay[at..].starts_with(f)) {
                return false;
            }
            at += forms[0].len();
        }
        true
    }

    /// The first offset where the run matches: no match of the pattern starts its run earlier.
    pub fn find(&self, hay: &[u8]) -> Option<usize> {
        #[cfg(target_arch = "x86_64")]
        if std::is_x86_feature_detected!("avx2") {
            // SAFETY: the CPU has AVX2
            return unsafe { self.find_avx2(hay) };
        }
        self.scan(hay)
    }

    #[cfg(target_arch = "x86_64")]
    #[target_feature(enable = "avx2")]
    unsafe fn find_avx2(&self, hay: &[u8]) -> Option<usize> {
        self.scan(hay)
    }

    /// Plain slice code that the compiler turns into vector compares (NEON, SSE2, AVX2).
    #[inline(always)]
    fn scan(&self, hay: &[u8]) -> Option<usize> {
        const W: usize = 64;
        let ends = hay.len().checked_sub(self.len)? + 1;
        let mut i = 0;
        while i + W <= ends {
            // in bounds: i + b + W <= ends - 1 + len = hay.len(), since b < len
            let x: &[u8; W] = hay[i + self.a..i + self.a + W].try_into().unwrap();
            let y: &[u8; W] = hay[i + self.b..i + self.b + W].try_into().unwrap();
            let mut any = 0u8;
            for k in 0..W {
                any |= (((x[k] | self.mask_a) == self.target_a) & ((y[k] | self.mask_b) == self.target_b)) as u8;
            }
            if any != 0 {
                let mut hits = 0u64;
                for k in 0..W {
                    hits |= ((((x[k] | self.mask_a) == self.target_a) & ((y[k] | self.mask_b) == self.target_b)) as u64) << k;
                }
                while hits != 0 {
                    let j = i + hits.trailing_zeros() as usize;
                    if self.run_at(hay, j) {
                        return Some(j);
                    }
                    hits &= hits - 1;
                }
            }
            i += W;
        }
        (i..ends).find(|&j| self.fits(hay, j) && self.run_at(hay, j))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn picks_positions_inside_one_run() {
        // K and the KELVIN SIGN differ in length, so the run is "ÖNIG"
        let f = FoldFinder::new("KÖNIG").unwrap();
        assert_eq!(f.len, 5);
        assert_eq!(f.find("der könig".as_bytes()), Some(5));
        assert_eq!(f.find("der K\u{212A}ÖNIG".as_bytes()), Some(8));
        assert_eq!(f.find(b"koenig"), None);
        assert!(FoldFinder::new("ks").is_none());
        assert!(FoldFinder::new("a+b").is_none());
        assert!(FoldFinder::new("ab").is_some());
    }
}

//! Approximate regular expressions (`grep --fuzzy-regex=N`): a line matches when some part of it is
//! within N insertions, deletions or substitutions of a string the pattern matches. The pattern
//! becomes a Glushkov automaton over characters (one state per character position, at most 64),
//! and the search runs it bit-parallel with one state set per number of errors (Navarro and
//! Raffinot, "Flexible Pattern Matching in Strings", section 6.5). An edit is one character: an
//! ASCII byte, a UTF-8 encoded character, or a byte of invalid UTF-8 (which no position matches).
//! Case folds as the regex engine folds it. Anchors and word boundaries are not supported.

use anyhow::{bail, Context, Result};
use grep_matcher::{LineTerminator, Match, Matcher, NoCaptures, NoError};
use regex_syntax::hir::{Class, Hir, HirKind};

pub const MAX_POSITIONS: usize = 64;

/// The characters of a position: inclusive code point ranges.
type Ranges = Vec<(u32, u32)>;

#[derive(Clone, Debug)]
pub struct FuzzyRegex {
    /// positions whose class holds the ASCII character
    ascii: [u64; 128],
    /// non-ASCII characters in ranges: `wide[i]` holds the positions of `cuts[i]..cuts[i + 1]`
    cuts: Vec<u32>,
    wide: Vec<u64>,
    /// follow sets by 8-bit chunk of a state set: chunk c, value v -> union of follow(i), i in v
    follow: Box<[[u64; 256]; 8]>,
    first: u64,
    last: u64,
    k: usize,
    /// state sets before any text byte, per number of errors (deletions from the start)
    init: Vec<u64>,
    /// bytes of the longest string the pattern matches, plus k inserted characters (bounds where a
    /// match can start)
    span: Option<usize>,
}

struct Build {
    classes: Vec<Ranges>,
    follow: Vec<u64>,
}

/// (nullable, first, last) of a sub-expression, positions added to `b`.
fn glushkov(h: &Hir, b: &mut Build) -> Result<(bool, u64, u64)> {
    let new_pos = |b: &mut Build, class: Ranges| -> Result<u64> {
        if b.classes.len() == MAX_POSITIONS {
            bail!("fuzzy regex patterns are limited to {MAX_POSITIONS} character positions");
        }
        b.classes.push(class);
        b.follow.push(0);
        Ok(1u64 << (b.classes.len() - 1))
    };
    let concat = |b: &mut Build, (n1, f1, l1): (bool, u64, u64), (n2, f2, l2): (bool, u64, u64)| {
        for i in 0..b.follow.len() {
            if l1 & (1 << i) != 0 {
                b.follow[i] |= f2;
            }
        }
        (n1 && n2, f1 | if n1 { f2 } else { 0 }, l2 | if n2 { l1 } else { 0 })
    };
    Ok(match h.kind() {
        HirKind::Empty => (true, 0, 0),
        HirKind::Literal(lit) => {
            let mut acc = (true, 0, 0);
            for c in std::str::from_utf8(&lit.0).context("a fuzzy regex matches text, not bytes of invalid UTF-8")?.chars() {
                let p = new_pos(b, vec![(c as u32, c as u32)])?;
                acc = concat(b, acc, (false, p, p));
            }
            acc
        }
        HirKind::Class(c) => {
            let class = match c {
                // the parser allows a byte class only where it stays within ASCII
                Class::Bytes(bc) => bc.iter().filter(|r| r.start() < 0x80).map(|r| (r.start() as u32, r.end().min(0x7F) as u32)).collect(),
                Class::Unicode(uc) => uc.iter().map(|r| (r.start() as u32, r.end() as u32)).collect(),
            };
            let p = new_pos(b, class)?;
            (false, p, p)
        }
        HirKind::Look(_) => bail!("anchors and word boundaries are not supported with --fuzzy-regex"),
        HirKind::Capture(cap) => glushkov(&cap.sub, b)?,
        HirKind::Concat(items) => {
            let mut acc = (true, 0, 0);
            for it in items {
                let x = glushkov(it, b)?;
                acc = concat(b, acc, x);
            }
            acc
        }
        HirKind::Alternation(items) => {
            let mut acc = (false, 0, 0);
            for it in items {
                let (n, f, l) = glushkov(it, b)?;
                acc = (acc.0 || n, acc.1 | f, acc.2 | l);
            }
            acc
        }
        HirKind::Repetition(rep) => {
            let mut acc = (true, 0, 0);
            for _ in 0..rep.min {
                let x = glushkov(&rep.sub, b)?;
                acc = concat(b, acc, x);
            }
            match rep.max {
                None => {
                    // a starred copy: its last positions loop back to its first
                    let (n, f, l) = glushkov(&rep.sub, b)?;
                    for i in 0..b.follow.len() {
                        if l & (1 << i) != 0 {
                            b.follow[i] |= f;
                        }
                    }
                    let _ = n;
                    acc = concat(b, acc, (true, f, l));
                }
                Some(max) => {
                    for _ in rep.min..max {
                        let (_, f, l) = glushkov(&rep.sub, b)?;
                        acc = concat(b, acc, (true, f, l));
                    }
                }
            }
            acc
        }
    })
}

impl FuzzyRegex {
    pub fn new(pattern: &str, max_edits: u8, case_insensitive: bool) -> Result<FuzzyRegex> {
        let hir = regex_syntax::ParserBuilder::new()
            .case_insensitive(case_insensitive)
            .build()
            .parse(pattern)
            .with_context(|| format!("invalid pattern {pattern:?}"))?;
        let mut b = Build { classes: Vec::new(), follow: Vec::new() };
        let (nullable, first, last) = glushkov(&hir, &mut b)?;
        if nullable {
            bail!("a fuzzy regex must not match the empty string (every line would match)");
        }
        let mut ascii = [0u64; 128];
        let mut cuts = vec![0x80u32, 0x110000];
        for &(lo, hi) in b.classes.iter().flatten().filter(|r| r.1 >= 0x80) {
            cuts.extend([lo.max(0x80), hi + 1]);
        }
        cuts.sort_unstable();
        cuts.dedup();
        cuts.pop();
        let mut wide = vec![0u64; cuts.len()];
        for (p, class) in b.classes.iter().enumerate() {
            for &(lo, hi) in class {
                for x in lo..=hi.min(0x7F) {
                    ascii[x as usize] |= 1 << p;
                }
                if hi >= 0x80 {
                    let (a, z) = (cuts.partition_point(|&s| s < lo.max(0x80)), cuts.partition_point(|&s| s <= hi));
                    wide[a..z].iter_mut().for_each(|w| *w |= 1 << p);
                }
            }
        }
        let mut follow = Box::new([[0u64; 256]; 8]);
        for (c, table) in follow.iter_mut().enumerate() {
            for (v, slot) in table.iter_mut().enumerate() {
                for bit in 0..8 {
                    let p = c * 8 + bit;
                    if v & (1 << bit) != 0 && p < b.follow.len() {
                        *slot |= b.follow[p];
                    }
                }
            }
        }
        let k = max_edits as usize;
        let span = hir.properties().maximum_len().map(|n| n + 4 * k);
        let mut m = FuzzyRegex { ascii, cuts, wide, follow, first, last, k, init: Vec::new(), span };
        // deleting j pattern characters before any text is read
        let mut d = 0u64;
        for _ in 0..=k {
            m.init.push(d);
            d = m.step(d);
        }
        // as with --fuzzy: k edits of a string of k characters or fewer match every line
        if m.init[k] & m.last != 0 {
            bail!("the number of edits ({k}) must be smaller than the length of the shortest string the pattern matches");
        }
        Ok(m)
    }

    /// The positions reachable in one move from `d`, or from the start (always active: search).
    fn step(&self, d: u64) -> u64 {
        let mut out = self.first;
        for c in 0..8 {
            out |= self.follow[c][((d >> (8 * c)) & 0xff) as usize];
        }
        out
    }

    /// End (exclusive) and number of errors of the first match in `hay[at..]`.
    fn first_end(&self, hay: &[u8], at: usize) -> Option<(usize, usize)> {
        let k = self.k;
        let mut r = self.init.clone();
        let mut next = vec![0u64; k + 1];
        let mut i = at;
        while i < hay.len() {
            let c = hay[i];
            let bc = if c < 0x80 {
                if c == b'\n' {
                    r.copy_from_slice(&self.init);
                    i += 1;
                    continue;
                }
                i += 1;
                self.ascii[c as usize]
            } else {
                let (c, n) = crate::instant::wide_char(hay, i);
                i += n;
                c.map_or(0, |c| self.wide[self.cuts.partition_point(|&s| s <= c as u32) - 1])
            };
            next[0] = self.step(r[0]) & bc;
            for j in 1..=k {
                // match, insertion (text byte skipped), substitution, deletion (pattern position skipped)
                next[j] = (self.step(r[j]) & bc) | r[j - 1] | self.step(r[j - 1]) | self.step(next[j - 1]);
            }
            std::mem::swap(&mut r, &mut next);
            if let Some(j) = r.iter().position(|&s| s & self.last != 0) {
                return Some((i, j));
            }
        }
        None
    }
}

impl Matcher for FuzzyRegex {
    type Captures = NoCaptures;
    type Error = NoError;

    fn find_at(&self, haystack: &[u8], at: usize) -> Result<Option<Match>, NoError> {
        let Some((end, _)) = self.first_end(haystack, at) else { return Ok(None) };
        let line_start = haystack[at..end].iter().rposition(|&b| b == b'\n').map(|i| at + i + 1).unwrap_or(at);
        let mut start = match self.span {
            Some(n) => end.saturating_sub(n).max(line_start),
            None => line_start,
        };
        // back to the first byte of a character
        for _ in 0..3 {
            if start > line_start && haystack[start] & 0xC0 == 0x80 {
                start -= 1;
            }
        }
        Ok(Some(Match::new(start, end)))
    }

    fn new_captures(&self) -> Result<NoCaptures, NoError> {
        Ok(NoCaptures::new())
    }

    fn line_terminator(&self) -> Option<LineTerminator> {
        Some(LineTerminator::default())
    }
}

