    }

    #[test]
    fn agrees_with_myers_on_literals_and_with_the_regex_engine_exactly() {
        let mut state = 0x9E3779B97F4A7C15u64;
        let mut next = |n: u64| {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            state % n
        };
        let mut text = String::new();
        for _ in 0..300 {
            let len = next(30);
            text.extend((0..len).map(|_| b"abcd_"[next(5) as usize] as char));
            text.push('\n');
        }
        for _ in 0..200 {
            let m = 2 + next(10) as usize;
            let pat: String = (0..m).map(|_| b"abcd"[next(4) as usize] as char).collect();
            let k = (next(3) as usize).min(m - 1);
            let fr = FuzzyRegex::new(&pat, k as u8, false).unwrap();
            let my = crate::instant::FuzzyMatcher::new(&pat, k as u8, false).unwrap();
            assert_eq!(lines(&fr, &text), lines(&my, &text), "{pat} k={k}");
        }
        for pat in ["ab(c|d)+a", "a[bc]{2,3}d", "(ab|cd)_?(ab)*c", "a.c", "[a-c]+d_b"] {
            let fr = FuzzyRegex::new(pat, 0, false).unwrap();
            let re = regex::Regex::new(pat).unwrap();
            let want: Vec<usize> = text.lines().enumerate().filter(|(_, l)| re.is_match(l)).map(|(i, _)| i).collect();
            assert_eq!(lines(&fr, &text), want, "{pat}");
        }
    }
}

//! `scrutate hook grep`: Claude Code's `PreToolUse` hook for its Grep tool. It answers the call
//! with Engine A's matches, the lines ripgrep gives for the same arguments, and denies the call
//! with that answer as the reason, which Claude Code hands to the model in place of Grep's
//! result. Anything it cannot answer exactly (an argument it does not map, an error, a timeout)
//! prints nothing and exits 0, so Grep runs as if there were no hook. `scrutate hook stats` sums
//! the bytes Grep would have returned against the bytes sent.

use std::io::{Read, Write};
use std::path::{Component, Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Duration;

use anyhow::{Context, Result};
use serde_json::{json, Value};

use crate::instant::{self, Case, Files, Mode, Output, Pattern, Query, Record, Report};

/// A search that takes longer lets Grep run instead.
const DEADLINE: Duration = Duration::from_secs(3);
/// Grep's own default `head_limit`.
const GREP_HEAD: usize = 250;
/// Grep shows a longer line as a note, as `rg --max-columns 500` does.
const GREP_COLUMNS: usize = 500;
/// The directories Grep leaves out (`--glob !.git` and so on).
const VCS: [&str; 6] = [".git", ".svn", ".hg", ".bzr", ".jj", ".sl"];
/// The `type` names whose files are the same in ripgrep and in scrutate's registry (a test holds
/// the list to `rg --type-list`).
pub const SAME_TYPES: [&str; 23] = [
    "asm", "cmake", "cs", "csharp", "dart", "elisp", "elm", "erlang", "fish", "gleam", "go", "julia", "kotlin", "lua", "nix", "py", "python", "racket", "rst",
    "rust", "solidity", "swift", "yaml",
];
const KEYS: [&str; 15] = ["pattern", "path", "glob", "type", "output_mode", "-B", "-A", "-C", "context", "-n", "-i", "-o", "head_limit", "offset", "multiline"];
/// The line before the result: short, as it is paid on every answer, and enough for the model
/// to read what follows as Grep's result (Claude Code says a hook denied the call).
pub const HEADER: &str = "Grep result:";

/// The answer to one Grep call.
#[derive(Debug)]
pub struct Answer {
    /// what the model gets: the header, then the result as Grep words it, bounded
    pub reason: String,
    /// the bytes of the result Grep would have returned
    pub grep_bytes: usize,
}

/// The hook: reads the call on standard input and prints the decision, or nothing. Always 0: an
/// exit code 2 would block the call.
pub fn grep_main() -> i32 {
    let answered = std::panic::catch_unwind(|| {
        let mut input = Vec::new();
        std::io::stdin().take(4 << 20).read_to_end(&mut input).ok()?;
        let input: Value = serde_json::from_slice(&input).ok()?;
        let budget =
            std::env::var("SCRUTATE_MAX_BYTES").ok().and_then(|v| v.parse::<usize>().ok()).map_or(crate::ops::AGENT_BYTES, |n| n.clamp(1_000, 1_000_000));
        let a = answer(&input, budget)?;
        Some((input.get("session_id").and_then(Value::as_str).unwrap_or("").to_string(), a))
    });
    if let Ok(Some((session, a))) = answered {
        let decision = json!({"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": a.reason}});
        let mut so = std::io::stdout().lock();
        if writeln!(so, "{decision}").and_then(|_| so.flush()).is_ok() {
            let _ = count(&session, a.grep_bytes, a.reason.len());
        }
    }
    0
}

#[derive(Clone, Copy, PartialEq)]
enum Shape {
    Content,
    Files,
    Count,
}

/// What a Grep call asks, as ripgrep would read it.
struct Ask {
    pattern: String,
    target: PathBuf,
    cwd: PathBuf,
    globs: Vec<String>,
    file_type: Option<String>,
    shape: Shape,
    before: usize,
    after: usize,
    breaks: bool,
    numbers: bool,
    insensitive: bool,
    multiline: bool,
    /// `None`: no limit
    head: Option<usize>,
    offset: usize,
}

/// The answer to `input` (Claude Code's hook input), or `None` when Grep must run.
pub fn answer(input: &Value, budget: usize) -> Option<Answer> {
    let ask = read_ask(input)?;
    let project = std::env::var_os("CLAUDE_PROJECT_DIR").map(PathBuf::from).unwrap_or_else(|| ask.cwd.clone());
    // Grep asks before it reads outside the project, and Claude Code's read rules filter it: the
    // hook answers neither case
    if !ask.target.starts_with(&project) || rules_limit_reads(&project) {
        return None;
    }
    let lines = search(&ask)?;
    Some(render(&ask, lines, budget))
}

fn read_ask(input: &Value) -> Option<Ask> {
    if input.get("hook_event_name")?.as_str()? != "PreToolUse" || input.get("tool_name")?.as_str()? != "Grep" {
        return None;
    }
    let t = input.get("tool_input")?.as_object()?;
    if t.keys().any(|k| !KEYS.contains(&k.as_str())) {
        return None;
    }
    let num = |k: &str| -> Option<Option<usize>> {
        match t.get(k) {
            None | Some(Value::Null) => Some(None),
            Some(v) => v.as_u64().and_then(|n| usize::try_from(n).ok()).map(Some),
        }
    };
    let flag = |k: &str, default: bool| -> Option<bool> {
        match t.get(k) {
            None | Some(Value::Null) => Some(default),
            Some(v) => v.as_bool(),
        }
    };
    let text = |k: &str| -> Option<Option<&str>> {
        match t.get(k) {
            None | Some(Value::Null) => Some(None),
            Some(v) => v.as_str().map(Some),
        }
    };
    let pattern = text("pattern")?.filter(|p| !p.is_empty())?.to_string();
    let shape = match text("output_mode")?.unwrap_or("files_with_matches") {
        "content" => Shape::Content,
        "files_with_matches" => Shape::Files,
        "count" => Shape::Count,
        _ => return None,
    };
    let (context, c, b, a) = (num("context")?, num("-C")?, num("-B")?, num("-A")?);
    if shape == Shape::Content && flag("-o", false)? {
        return None;
    }
    let (before, after) = match context.or(c) {
        Some(n) => (n, n),
        None => (b.unwrap_or(0), a.unwrap_or(0)),
    };
    let cwd = PathBuf::from(input.get("cwd")?.as_str()?);
    if !cwd.is_absolute() {
        return None;
    }
    let target = match text("path")? {
        Some(p) if p.starts_with('~') => return None,
        Some(p) => lexical(&cwd.join(p))?,
        None => lexical(&cwd)?,
    };
    let target = PathBuf::from(real_path(&std::fs::canonicalize(&target).ok()?.to_string_lossy(), target.to_str()?, cfg!(windows))?);
    let mut globs: Vec<String> = VCS.iter().map(|d| format!("!{d}")).collect();
    for g in split_glob(text("glob")?.unwrap_or("")) {
        // a glob with a slash matches from ripgrep's working directory, which the hook cannot see
        let bare = g.strip_prefix('!').unwrap_or(&g);
        if bare.strip_prefix("**/").unwrap_or(bare).contains('/') || (cfg!(windows) && g.contains('\\')) {
            return None;
        }
        globs.push(g);
    }
    let file_type = match text("type")?.filter(|t| !t.is_empty()) {
        Some(t) if SAME_TYPES.contains(&t) => Some(t.to_string()),
        Some(_) => return None,
        None => None,
    };
    Some(Ask {
        pattern,
        target,
        cwd,
        globs,
        file_type,
        shape,
        before: if shape == Shape::Content { before } else { 0 },
        after: if shape == Shape::Content { after } else { 0 },
        breaks: [context, c, b, a].iter().any(|n| n.is_some_and(|n| n > 0)),
        numbers: flag("-n", true)?,
        insensitive: flag("-i", false)?,
        multiline: flag("multiline", false)?,
        head: match num("head_limit")? {
            None => Some(GREP_HEAD),
            Some(0) => None,
            Some(n) => Some(n),
        },
        offset: num("offset")?.unwrap_or(0),
    })
}

/// `p` with `.` and `..` resolved by name, as Node's `path.resolve` does.
fn lexical(p: &Path) -> Option<PathBuf> {
    let mut out = PathBuf::new();
    for c in p.components() {
        match c {
            Component::CurDir => {}
            Component::ParentDir => {
                out.pop();
            }
            c => out.push(c),
        }
    }
    out.is_absolute().then_some(out)
}

/// The path Grep searches for `p`, from `real`, what `canonicalize` gave: Claude Code takes the
/// real path, and on Windows that may differ from `p` in the case of its letters only. Anything
/// else is a link on the way, which makes ripgrep's paths differ from the walk's, or a path not on
/// a drive letter, which Claude Code searches by another way (`fr(e)&&!Qd(e)||Ga(e)`).
fn real_path(real: &str, p: &str, windows: bool) -> Option<String> {
    if !windows {
        return (real == p).then(|| p.to_string());
    }
    let real = real.strip_prefix(r"\\?\").unwrap_or(real);
    let b = real.as_bytes();
    let drive = b.len() >= 3 && b[0].is_ascii_alphabetic() && &b[1..3] == b":\\";
    (drive && real.to_lowercase() == p.to_lowercase()).then(|| real.to_string())
}

/// What follows `base` in `p` when `p` is `base` or under it, as Node's `path.relative` finds it:
/// without case on Windows.
fn under<'a>(p: &'a str, base: &str, windows: bool) -> Option<&'a str> {
    let sep = if windows { '\\' } else { '/' };
    let base = base.trim_end_matches(sep);
    let head = p.get(..base.len())?;
    if head != base && !(windows && head.to_lowercase() == base.to_lowercase()) {
        return None;
    }
    let rest = &p[base.len()..];
    if rest.is_empty() {
        Some(rest)
    } else {
        rest.strip_prefix(sep)
    }
}

/// A path of Engine A's (`/` between its parts) as Grep prints it: `rat` of Claude Code, the
/// path from the session's directory when under it, else as ripgrep gave it, with `\` on Windows.
fn shown(path: &str, cwd: &str, windows: bool) -> String {
    let (p, cwd) = if windows { (path.replace('/', "\\"), cwd.replace('/', "\\")) } else { (path.to_string(), cwd.to_string()) };
    match under(&p, &cwd, windows) {
        Some(r) if !r.is_empty() => r.to_string(),
        _ => p,
    }
}

/// Grep's `glob` argument as it splits it: at whitespace, and at commas outside a word with braces.
fn split_glob(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    for w in s.split_whitespace() {
        if w.contains('{') && w.contains('}') {
            out.push(w.to_string());
        } else {
            out.extend(w.split(',').filter(|g| !g.is_empty()).map(String::from));
        }
    }
    out
}

/// Whether a settings file of Claude Code has a `deny` or `ask` rule for reads, which Grep's
/// answer would have to follow. A settings file that does not parse counts as one.
fn rules_limit_reads(project: &Path) -> bool {
    let home = std::env::var_os("CLAUDE_CONFIG_DIR")
        .map(PathBuf::from)
        .or_else(|| std::env::var_os(if cfg!(windows) { "USERPROFILE" } else { "HOME" }).map(|h| PathBuf::from(h).join(".claude")));
    let mut files = vec![project.join(".claude").join("settings.json"), project.join(".claude").join("settings.local.json")];
    files.extend(home.map(|h| h.join("settings.json")));
    let managed = PathBuf::from(if cfg!(target_os = "macos") {
        "/Library/Application Support/ClaudeCode/managed-settings.json"
    } else if cfg!(windows) {
        r"C:\Program Files\ClaudeCode\managed-settings.json"
    } else {
        "/etc/claude-code/managed-settings.json"
    });
    files.extend(drop_ins(&managed));
    files.push(managed);
    // policies the hook does not read (a macOS profile, Windows registry policies) may hold read
    // rules: where one exists, Grep runs and applies it itself
    if managed_policy_elsewhere() {
        return true;
    }
    files.iter().any(|f| match std::fs::read(f) {
        Err(_) => false,
        Ok(b) => match serde_json::from_slice::<Value>(&b) {
            Err(_) => true,
            Ok(v) => ["deny", "ask"].iter().any(|k| {
                v.pointer(&format!("/permissions/{k}"))
                    .and_then(Value::as_array)
                    .is_some_and(|rules| rules.iter().any(|r| r.as_str().is_none_or(|r| r.starts_with("Read") || r.starts_with("Grep"))))
            }),
        },
    })
}

/// Every `*.json` of the `managed-settings.d` directory beside the managed settings file, which
/// Claude Code reads as managed settings too, in name order.
fn drop_ins(managed: &Path) -> Vec<PathBuf> {
    let Some(Ok(rd)) = managed.parent().map(|d| std::fs::read_dir(d.join("managed-settings.d"))) else { return Vec::new() };
    let mut drops: Vec<PathBuf> = rd.flatten().map(|e| e.path()).filter(|p| p.extension().is_some_and(|x| x == "json")).collect();
    drops.sort();
    drops
}

/// Whether Claude Code has managed settings in a place the hook does not read: a configuration
/// profile's preferences on macOS, the policy keys of the registry on Windows.
fn managed_policy_elsewhere() -> bool {
    #[cfg(target_os = "macos")]
    {
        let user = std::env::var("USER").unwrap_or_default();
        let plist = "com.anthropic.claudecode.plist";
        let dir = Path::new("/Library/Managed Preferences");
        dir.join(plist).exists() || (!user.is_empty() && dir.join(&user).join(plist).exists())
    }
    #[cfg(windows)]
    {
        windows_policy::exists()
    }
    #[cfg(not(any(target_os = "macos", windows)))]
    {
        false
    }
}

#[cfg(windows)]
mod windows_policy {
    use std::ffi::c_void;

    const HKEY_CURRENT_USER: isize = 0x8000_0001u32 as i32 as isize;
    const HKEY_LOCAL_MACHINE: isize = 0x8000_0002u32 as i32 as isize;
    const KEY_READ: u32 = 0x2_0019;

    #[link(name = "advapi32")]
    extern "system" {
        fn RegOpenKeyExW(key: isize, sub: *const u16, options: u32, sam: u32, out: *mut *mut c_void) -> i32;
        fn RegCloseKey(key: *mut c_void) -> i32;
    }

    /// Whether `SOFTWARE\Policies\ClaudeCode` exists under HKLM or HKCU.
    pub fn exists() -> bool {
        let sub: Vec<u16> = r"SOFTWARE\Policies\ClaudeCode".encode_utf16().chain([0]).collect();
        [HKEY_LOCAL_MACHINE, HKEY_CURRENT_USER].iter().any(|&root| {
            let mut out = std::ptr::null_mut();
            // SAFETY: a nul-terminated UTF-16 string and a valid out pointer; the key is closed
            let found = unsafe { RegOpenKeyExW(root, sub.as_ptr(), 0, KEY_READ, &mut out) } == 0;
            if found {
                unsafe { RegCloseKey(out) };
            }
            found
        })
    }
}

/// One line of Grep's result list, before the paging.
struct Item {
    text: String,
    /// the matching lines of a `count` line
    count: u64,
}

/// Engine A's answer as Grep's lines, in path order (by modification time, newest first, for
/// `files_with_matches`, as Grep sorts them); `None` when it cannot stand for ripgrep's.
fn search(ask: &Ask) -> Option<Vec<Item>> {
    let q = Query {
        pattern: Pattern {
            text: if ask.multiline { format!("(?s){}", ask.pattern) } else { ask.pattern.clone() },
            mode: Mode::Regex,
            case: if ask.insensitive { Case::Insensitive } else { Case::Sensitive },
            multiline: ask.multiline,
            ..Pattern::default()
        },
        report: match ask.shape {
            Shape::Content => Report::Lines,
            Shape::Files => Report::Files,
            Shape::Count => Report::Counts,
        },
        before: ask.before,
        after: ask.after,
        first_in_path_order: true,
        ..Query::default()
    };
    let f = Files {
        hidden: true,
        globs: ask.globs.clone(),
        types: ask.file_type.iter().cloned().collect(),
        paths_as_given: true,
        ..Files::walk(vec![ask.target.clone()])
    };
    let cancel = Arc::new(AtomicBool::new(false));
    let timer = cancel.clone();
    std::thread::spawn(move || {
        std::thread::sleep(DEADLINE);
        timer.store(true, Ordering::Relaxed);
    });
    let mut records = Vec::new();
    let mut odd = false;
    let stats = instant::search(
        &q,
        &f,
        cancel,
        Output::Records(&mut |r| {
            odd |= r.path_bytes().is_some() || matches!(r, Record::Note { .. });
            records.push(r);
        }),
    )
    .ok()?;
    if odd || stats.cancelled || stats.errors > 0 || records.is_empty() {
        return None;
    }
    let dir = ask.target.is_dir();
    let cwd = ask.cwd.to_string_lossy();
    let shown = |p: &str| shown(p, &cwd, cfg!(windows));
    let mut items = Vec::new();
    match ask.shape {
        Shape::Content => {
            let mut last: Option<(std::sync::Arc<str>, u64)> = None;
            for r in &records {
                let (l, sep) = match r {
                    Record::Match(l) => (l, ':'),
                    Record::Context(l) => (l, '-'),
                    _ => return None,
                };
                if ask.breaks {
                    if let Some((p, n)) = &last {
                        if *p != l.path || l.line > n + 1 {
                            items.push(Item { text: "--".into(), count: 0 });
                        }
                    }
                }
                // a multi-line match is one record; Grep shows each of its lines with its number
                let parts: Vec<&str> = l.text.strip_suffix('\n').unwrap_or(&l.text).split('\n').collect();
                last = Some((l.path.clone(), l.line + parts.len() as u64 - 1));
                for (k, part) in parts.iter().enumerate() {
                    let part = part.trim_end_matches('\r');
                    let text = if part.encode_utf16().count() > GREP_COLUMNS {
                        if sep == ':' {
                            "[Omitted long matching line]"
                        } else {
                            "[Omitted long context line]"
                        }
                    } else {
                        part
                    };
                    let mut line = if dir { format!("{}{sep}", shown(&l.path)) } else { String::new() };
                    if ask.numbers {
                        line.push_str(&format!("{}{sep}", l.line + k as u64));
                    }
                    line.push_str(text);
                    items.push(Item { text: line, count: 0 });
                }
            }
        }
        Shape::Count => {
            for r in &records {
                let Record::Count { path, count, .. } = r else { return None };
                if *count > 0 {
                    items.push(Item { text: format!("{}:{count}", shown(path)), count: *count });
                }
            }
        }
        Shape::Files => {
            let mut files: Vec<(f64, String)> = Vec::new();
            for r in &records {
                let Record::File { path, .. } = r else { return None };
                let ms = std::fs::metadata(&**path)
                    .ok()
                    .and_then(|m| m.modified().ok())
                    .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                    .map_or(0.0, |d| d.as_secs_f64() * 1000.0);
                files.push((ms, shown(path)));
            }
            files.sort_by(|a, b| b.0.total_cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
            items.extend(files.into_iter().map(|(_, text)| Item { text, count: 0 }));
        }
    }
    Some(items)
}

/// The window Grep shows of `len` items: from `offset`, `head` of them; and the limit it names
/// when there are more.
fn window(len: usize, head: Option<usize>, offset: usize) -> (usize, usize, Option<usize>) {
    let start = offset.min(len);
    match head {
        None => (start, len, None),
        Some(h) => (start, (offset.saturating_add(h)).min(len), (len.saturating_sub(offset) > h).then_some(h)),
    }
}

/// Grep's words for its paging: `limit: 250, offset: 5`.
fn pagination(limit: Option<usize>, offset: usize) -> String {
    let mut parts = Vec::new();
    if let Some(l) = limit {
        parts.push(format!("limit: {l}"));
    }
    if offset > 0 {
        parts.push(format!("offset: {offset}"));
    }
    parts.join(", ")
}

fn plural(n: u64, one: &str, many: &str) -> String {
    format!("{n} {}", if n == 1 { one } else { many })
}

/// Grep's result for these items, and the bounded answer the model gets.
fn render(ask: &Ask, items: Vec<Item>, budget: usize) -> Answer {
    let (start, end, limit) = window(items.len(), ask.head, ask.offset);
    let pages = pagination(limit, ask.offset);
    let page: Vec<&str> = items[start..end].iter().map(|i| i.text.as_str()).collect();
    let (pre, empty, post, noun) = match ask.shape {
        Shape::Content => {
            let empty = if ask.offset > 0 && !items.is_empty() { "No entries at this offset" } else { "No matches found" };
            (String::new(), empty.to_string(), if pages.is_empty() { String::new() } else { format!("\n[Showing results with pagination = {pages}]") }, "lines")
        }
        Shape::Count => {
            let total: u64 = items.iter().map(|i| i.count).sum();
            let empty = if total > 0 { "No entries at this offset" } else { "No matches found" };
            let with = if pages.is_empty() { String::new() } else { format!(" with pagination = {pages}") };
            (
                String::new(),
                empty.to_string(),
                format!("\nFound {} across {}.{with}", plural(total, "total occurrence", "total occurrences"), plural(items.len() as u64, "file", "files")),
                "files",
            )
        }
        Shape::Files => {
            let n = page.len() as u64;
            let empty = if ask.offset > 0 && !items.is_empty() {
                format!("No entries at this offset. [Showing results with pagination = {pages}]")
            } else {
                "No files found".into()
            };
            (
                format!("Found {}{}\n", plural(n, "file", "files"), if pages.is_empty() { String::new() } else { format!(" {pages}") }),
                empty,
                String::new(),
                "files",
            )
        }
    };
    let grep = if page.is_empty() {
        if ask.shape == Shape::Count {
            format!("{empty}{post}")
        } else {
            empty.clone()
        }
    } else {
        format!("{pre}{}{post}", page.join("\n"))
    };
    let reason = if page.is_empty() {
        format!("{HEADER}\n{grep}")
    } else {
        let room = budget.saturating_sub(HEADER.len() + 1 + pre.len() + post.len());
        format!("{HEADER}\n{pre}{}{post}", bounded(&page, start, end, room, noun))
    };
    Answer { reason, grep_bytes: grep.len() }
}

/// The lines that fit `room` bytes, whole, then a line naming the `offset` that continues them.
fn bounded(page: &[&str], start: usize, end: usize, room: usize, noun: &str) -> String {
    let more = |next: usize| format!("\n({} more {noun} not shown: call Grep again with offset={next}, or narrow the request)", end - next);
    // the widest closing line: its numbers have the most digits
    let room_for_more = more(start).len().max(more(end).len());
    let mut out = String::new();
    for (i, l) in page.iter().enumerate() {
        let tail = if i + 1 == page.len() { 0 } else { room_for_more };
        if i > 0 && out.len() + 1 + l.len() + tail > room {
            out.push_str(&more(start + i));
            return out;
        }
        if i > 0 {
            out.push('\n');
        }
        out.push_str(l);
    }
    out
}

/// The file the counter appends to.
pub fn counter_path() -> Option<PathBuf> {
    let var = |k: &str| std::env::var_os(k).filter(|v| !v.is_empty()).map(PathBuf::from);
    let dir = if cfg!(windows) {
        var("LOCALAPPDATA")?.join("scrutate")
    } else {
        var("XDG_STATE_HOME").filter(|p| p.is_absolute()).unwrap_or(var("HOME")?.join(".local").join("state")).join("scrutate")
    };
    Some(dir.join("hook-grep.jsonl"))
}

/// One line per answered call: one write, so lines of hooks running at once do not mix.
fn count(session: &str, grep_bytes: usize, sent_bytes: usize) -> Result<()> {
    let path = counter_path().context("no state directory")?;
    std::fs::create_dir_all(path.parent().expect("a file in a directory"))?;
    let time = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.as_secs());
    let line = format!("{}\n", json!({"session": session, "grep_bytes": grep_bytes, "sent_bytes": sent_bytes, "time": time}));
    std::fs::OpenOptions::new().create(true).append(true).open(&path)?.write_all(line.as_bytes())?;
    Ok(())
}

#[derive(Default)]
struct Tally {
    calls: u64,
    grep: u64,
    sent: u64,
}

impl Tally {
    fn json(&self) -> Value {
        json!({"calls": self.calls, "grep_bytes": self.grep, "sent_bytes": self.sent, "saved_bytes": self.grep as i64 - self.sent as i64})
    }

    fn text(&self) -> String {
        format!(
            "{} calls, Grep would have returned {} bytes, scrutate sent {} ({} saved)",
            self.calls,
            self.grep,
            self.sent,
            self.grep as i64 - self.sent as i64
        )
    }
}

/// `scrutate hook stats`: the counter per session, in the order the sessions began, and in all.
pub fn stats(json_out: bool) -> Result<i32> {
    let path = counter_path().context("no state directory: set HOME or XDG_STATE_HOME")?;
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => String::new(),
        Err(e) => return Err(e).with_context(|| format!("read {}", path.display())),
    };
    let mut sessions: Vec<(String, Tally)> = Vec::new();
    let mut all = Tally::default();
    for v in text.lines().filter_map(|l| serde_json::from_str::<Value>(l).ok()) {
        let (Some(g), Some(s)) = (v.get("grep_bytes").and_then(Value::as_u64), v.get("sent_bytes").and_then(Value::as_u64)) else { continue };
        let id = v.get("session").and_then(Value::as_str).unwrap_or("").to_string();
        let i = sessions.iter().position(|(k, _)| *k == id).unwrap_or_else(|| {
            sessions.push((id, Tally::default()));
            sessions.len() - 1
        });
        for t in [&mut sessions[i].1, &mut all] {
            t.calls += 1;
            t.grep += g;
            t.sent += s;
        }
    }
    let mut so = std::io::stdout().lock();
    if json_out {
        let list: Vec<Value> = sessions
            .iter()
            .map(|(id, t)| {
                json!({"session": id})
                    .as_object()
                    .cloned()
                    .map(|mut o| {
                        o.extend(t.json().as_object().cloned().unwrap_or_default());
                        Value::Object(o)
                    })
                    .unwrap_or_default()
            })
            .collect();
        writeln!(so, "{}", json!({"counter": path.to_string_lossy(), "sessions": list, "total": all.json()}))?;
    } else if all.calls == 0 {
        eprintln!("no Grep call was answered yet (counter: {})", path.display());
    } else {
        for (id, t) in &sessions {
            writeln!(so, "session {}: {}", if id.is_empty() { "(none)" } else { id }, t.text())?;
        }
        writeln!(so, "all sessions: {}", all.text())?;
    }
    Ok(if all.calls == 0 { 1 } else { 0 })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn grep_splits_its_glob_argument_at_spaces_and_commas() {
        assert_eq!(split_glob("*.rs, *.toml"), ["*.rs", "*.toml"]);
        assert_eq!(split_glob("*.{ts,tsx} !x"), ["*.{ts,tsx}", "!x"]);
        assert_eq!(split_glob(""), Vec::<String>::new());
    }

    #[test]
    fn the_window_and_its_words_are_greps() {
        assert_eq!(window(300, Some(250), 0), (0, 250, Some(250)));
        assert_eq!(window(300, Some(250), 100), (100, 300, None));
        assert_eq!(window(10, None, 3), (3, 10, None));
        assert_eq!(window(2, Some(250), 5), (2, 2, None));
        assert_eq!(pagination(Some(250), 5), "limit: 250, offset: 5");
    }

    #[test]
    fn a_bounded_page_keeps_whole_lines_and_names_the_offset() {
        let page = ["aaaa", "bbbb", "cccc"];
        assert_eq!(bounded(&page, 0, 3, 100, "lines"), "aaaa\nbbbb\ncccc");
        let more = "\n(2 more lines not shown: call Grep again with offset=11, or narrow the request)";
        let room = 4 + more.len() + 2;
        assert_eq!(bounded(&page, 10, 13, room, "lines"), format!("aaaa{more}"));
    }

    #[test]
    fn paths_are_shown_as_claude_codes_path_relative_gives_them() {
        assert_eq!(shown("/r/src/a.rs", "/r", false), "src/a.rs");
        assert_eq!(shown("/r2/a.rs", "/r", false), "/r2/a.rs");
        assert_eq!(shown("/R/a.rs", "/r", false), "/R/a.rs");
        assert_eq!(shown("/a.rs", "/", false), "a.rs");
        // Windows: `\` between the parts, and the session's directory matched without case
        assert_eq!(shown("C:/Users/X/repo/src/a.rs", r"C:\Users\X\repo", true), r"src\a.rs");
        assert_eq!(shown("C:/Users/X/repo/src/a.rs", r"c:\users\x\REPO", true), r"src\a.rs");
        assert_eq!(shown("C:/Users/X/repo/src/a.rs", "C:/Users/X/repo/", true), r"src\a.rs");
        assert_eq!(shown("C:/Users/X/repo2/a.rs", r"C:\Users\X\repo", true), r"C:\Users\X\repo2\a.rs");
        assert_eq!(shown("D:/repo/a.rs", r"C:\repo", true), r"D:\repo\a.rs");
        assert_eq!(shown("C:/a.rs", r"C:\", true), "a.rs");
    }

    #[test]
    fn the_searched_path_is_the_real_one_and_differs_only_in_case_on_windows() {
        assert_eq!(real_path("/r/a", "/r/a", false).as_deref(), Some("/r/a"));
        assert_eq!(real_path("/r/A", "/r/a", false), None);
        assert_eq!(real_path(r"\\?\C:\Users\X\repo", r"c:\users\x\repo", true).as_deref(), Some(r"C:\Users\X\repo"));
        assert_eq!(real_path(r"C:\Users\X\repo", r"C:\Users\X\repo", true).as_deref(), Some(r"C:\Users\X\repo"));
        assert_eq!(real_path(r"\\?\C:\elsewhere", r"C:\Users\X\link", true), None);
        assert_eq!(real_path(r"\\?\UNC\server\share\x", r"\\server\share\x", true), None);
    }

    #[test]
    fn the_drop_in_directory_beside_the_managed_settings_is_read_in_name_order() {
        let dir = std::env::temp_dir().join(format!("scrutate_drop_ins_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("managed-settings.d")).unwrap();
        for f in ["b.json", "a.json", "notes.txt"] {
            std::fs::write(dir.join("managed-settings.d").join(f), "{}").unwrap();
        }
        let got = drop_ins(&dir.join("managed-settings.json"));
        assert_eq!(got, [dir.join("managed-settings.d/a.json"), dir.join("managed-settings.d/b.json")]);
        assert!(drop_ins(&dir.join("elsewhere/managed-settings.json")).is_empty());
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[cfg(unix)]
    #[test]
    fn lexical_paths_resolve_dots_by_name() {
        assert_eq!(lexical(Path::new("/a/./b/../c")), Some(PathBuf::from("/a/c")));
        assert_eq!(lexical(Path::new("x")), None);
    }
}

//! What a change touches: the definitions a git diff changes, the callers that reach them with
//! their distances, and the test files to run. The diff comes from the `git` program; the
//! definitions of the tree as it is from the index, those of the base from a parse of each file's
//! base version; the callers from `Names`, as `callers` gives them.

use std::collections::{BTreeMap, BTreeSet, HashSet};
use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use anyhow::{anyhow, bail, Result};
use serde_json::{json, Value};

use crate::fmt::{echo, shown};
use crate::names::Names;
use crate::search::{Hit, Searcher};

/// Steps of callers followed by default: past three, the callers of a much used function grow
/// toward most of the repository and say little about what to test.
pub const DEPTH: usize = 3;
pub const MAX_DEPTH: usize = 10;
/// Callers one step asks for, as `callers --limit 500`.
pub const STEP_CALLERS: usize = 500;
/// Callers one answer lists at most; the walk stops there.
pub const MAX_CALLERS: usize = 2000;

/// A definition the diff changed. `status`: `added`, `edited` or `deleted` (then named, with
/// its lines, as the base has it). Kind `file`: lines outside every definition, with no window.
pub struct Changed {
    pub hit: Hit,
    pub status: &'static str,
}

/// A definition that calls a changed one, `distance` steps away; `via` is the location of what it calls.
pub struct Caller {
    pub hit: Hit,
    pub distance: usize,
    pub via: String,
    /// the resolver could not tell whether it calls that definition or another of its name
    pub undecided: bool,
    /// it calls a definition the change deleted, by a name no other definition answers
    pub calls_deleted: bool,
}

/// A test file to run, and the symbol in it that reached a change (none: the diff changed the file).
pub struct Test {
    pub path: String,
    pub distance: usize,
    pub via: Option<Hit>,
}

pub struct Impact {
    /// the revision as given (`HEAD` by default) and the commit it names
    pub against: String,
    pub base: String,
    pub staged: bool,
    pub depth: usize,
    pub changed: Vec<Changed>,
    pub callers: Vec<Caller>,
    pub tests: Vec<Test>,
    /// (path, why it gives no symbol): a binary file, a submodule, a file the index leaves out
    pub notes: Vec<(String, String)>,
    pub stopped: bool,
    /// the head commit, when the change is between two commits
    pub head: Option<String>,
    /// (path, bytes) of the base copy of each changed file the index would hold
    pub(crate) base_copies: Vec<(String, Vec<u8>)>,
    /// the path each changed file has after the change
    pub(crate) head_paths: Vec<String>,
    /// every call the walk met
    pub(crate) edges: Vec<Edge>,
}

/// A call: the caller's chunk id and the location of the definition it calls.
pub(crate) type Edge = (i64, String);

/// Where the changed side of a diff comes from.
enum New {
    Tree,
    Staged,
    Commit(String),
}

/// What the working tree (with `staged`, the staged changes) changes against `base` (`HEAD`, a
/// revision, or `A...B` for the merge base of the two), on the index as it is.
pub fn impact(s: &Searcher, base: Option<&str>, staged: bool, depth: usize) -> Result<Impact> {
    compare(s, base.unwrap_or("HEAD"), if staged { New::Staged } else { New::Tree }, depth)
}

/// What commit `head` changes against `base` (a revision or `A...B`), read from git's copies and
/// named where the index, the working tree's, holds each definition.
pub fn between(s: &Searcher, base: &str, head: &str, depth: usize) -> Result<Impact> {
    compare(s, base, New::Commit(head.to_string()), depth)
}

fn compare(s: &Searcher, against: &str, new: New, depth: usize) -> Result<Impact> {
    let git = Git::new(&s.ix.root)?;
    let against = against.to_string();
    let base = git.base(&against)?;
    let new = match new {
        New::Commit(rev) => New::Commit(git.commit(&rev)?),
        other => other,
    };
    let entries = git.diff(&base, &new)?;
    let (staged, head) = match new {
        New::Tree => (false, None),
        New::Staged => (true, None),
        New::Commit(c) => (false, Some(c)),
    };
    let from_blobs = staged || head.is_some();
    let mut b = Builder {
        s,
        from_blobs,
        changed: Vec::new(),
        notes: Vec::new(),
        seen: HashSet::new(),
        files: Vec::new(),
        base_copies: Vec::new(),
        head_paths: Vec::new(),
    };
    let blobs = git.blobs(&entries.iter().flat_map(|e| b.blobs_wanted(e)).collect::<BTreeSet<_>>())?;
    for e in &entries {
        b.entry(e, &blobs)?;
    }
    let Builder { mut changed, mut notes, files, base_copies, head_paths, .. } = b;
    changed.sort_by(|a, b| {
        (&a.hit.path, a.hit.start, a.hit.end, &a.hit.kind, &a.hit.qualname).cmp(&(&b.hit.path, b.hit.start, b.hit.end, &b.hit.kind, &b.hit.qualname))
    });
    notes.sort();
    let (callers, edges, stopped) = walk(s, &changed, depth)?;
    let tests = test_files(&changed, &callers, &files);
    Ok(Impact { against, base, staged, depth, changed, callers, tests, notes, stopped, head, base_copies, head_paths, edges })
}

/// Kinds whose callers are not asked for: lines outside every definition, and a module.
fn walkable(h: &Hit) -> bool {
    h.id != 0 && !matches!(h.kind.as_str(), "window" | "module" | "file")
}

/// Callers breadth first, each at the smallest distance it is reached by, in (distance, path, line)
/// order, and every call met on the way.
fn walk(s: &Searcher, changed: &[Changed], depth: usize) -> Result<(Vec<Caller>, Vec<Edge>, bool)> {
    let mut seen: HashSet<i64> = changed.iter().map(|c| c.hit.id).filter(|id| *id != 0).collect();
    let mut frontier: Vec<Hit> = changed.iter().map(|c| c.hit.clone()).filter(walkable).collect();
    // a deleted definition has no index entry to ask `callers` about: its callers are found by its name
    let gone: Vec<&Hit> =
        changed.iter().filter(|c| c.status == "deleted" && !matches!(c.hit.kind.as_str(), "window" | "module" | "file")).map(|c| &c.hit).collect();
    let (mut callers, mut edges) = (Vec::new(), Vec::new());
    let mut names = Names::new(s)?;
    for distance in 1..=depth {
        let mut next = Vec::new();
        let deleted = if distance == 1 { gone.len() } else { 0 };
        for k in 0..deleted + frontier.len() {
            if s.cancel.load(std::sync::atomic::Ordering::Relaxed) {
                bail!("cancelled");
            }
            let (target, decided, hits) = match k.checked_sub(deleted) {
                None => {
                    let hits = names.callers_of_deleted(gone[k], STEP_CALLERS)?;
                    (gone[k], hits.len(), hits)
                }
                Some(j) => {
                    let (hits, undecided) = names.callers(&frontier[j].loc(), STEP_CALLERS)?;
                    (&frontier[j], hits.len() - undecided, hits)
                }
            };
            for (i, h) in hits.into_iter().enumerate() {
                edges.push((h.id, target.loc()));
                if !seen.insert(h.id) {
                    continue;
                }
                if callers.len() >= MAX_CALLERS {
                    return Ok((callers, edges, true));
                }
                if walkable(&h) {
                    next.push(h.clone());
                }
                callers.push(Caller { hit: h, distance, via: target.loc(), undecided: i >= decided, calls_deleted: k < deleted });
            }
        }
        next.sort_by(|a, b| (&a.path, a.start, a.end).cmp(&(&b.path, b.start, b.end)));
        frontier = next;
    }
    callers.sort_by(|a, b| (a.distance, &a.hit.path, a.hit.start, a.hit.end).cmp(&(b.distance, &b.hit.path, b.hit.start, b.hit.end)));
    Ok((callers, edges, false))
}

/// The test files (`is_test_path`, the index's test flag) that hold a changed symbol or a caller,
/// and those the diff changed, each once at its smallest distance.
fn test_files(changed: &[Changed], callers: &[Caller], files: &[String]) -> Vec<Test> {
    let mut out: BTreeMap<String, Test> = BTreeMap::new();
    let mut offer = |path: &str, distance: usize, via: Option<&Hit>| {
        if !crate::text::is_test_path(path) {
            return;
        }
        let t = out.entry(path.to_string()).or_insert(Test { path: path.to_string(), distance, via: via.cloned() });
        if distance < t.distance {
            *t = Test { path: path.to_string(), distance, via: via.cloned() };
        }
    };
    for c in changed {
        offer(&c.hit.path, 0, (c.hit.kind != "file").then_some(&c.hit));
    }
    for c in callers {
        offer(&c.hit.path, c.distance, Some(&c.hit));
    }
    for f in files {
        offer(f, 0, None);
    }
    let mut tests: Vec<Test> = out.into_values().collect();
    tests.sort_by(|a, b| (a.distance, &a.path).cmp(&(b.distance, &b.path)));
    tests
}

/// A definition of one side of a file.
#[derive(Clone)]
struct Def {
    kind: String,
    name: String,
    qualname: String,
    start: i64,
    end: i64,
    /// the index's chunk id; 0 for a definition parsed from git's copy
    id: i64,
}

impl Def {
    fn hit(&self, path: &str) -> Hit {
        Hit {
            id: self.id,
            path: path.to_string(),
            start: self.start,
            end: self.end,
            name: self.name.clone(),
            qualname: self.qualname.clone(),
            kind: self.kind.clone(),
            ..Hit::default()
        }
    }

    fn same(&self, other: &Def) -> bool {
        self.kind == other.kind && self.qualname == other.qualname
    }
}

/// The definitions of `src` as the index would hold them, windows aside.
fn parsed(path: &str, src: &[u8]) -> Vec<Def> {
    if src.len() as u64 > crate::index::MAX_FILE_BYTES || !crate::parse::is_indexable(path) {
        return Vec::new();
    }
    let src = String::from_utf8_lossy(src);
    crate::parse::parse_file(path, &src)
        .chunks
        .into_iter()
        .filter(|c| c.kind != "window")
        .map(|c| Def { kind: c.kind.to_string(), name: c.name, qualname: c.qualname, start: c.start, end: c.end, id: 0 })
        .collect()
}

/// Of `defs`, the innermost one around each line of `ranges` (first and last line), and the
/// lines no definition holds.
fn touched(defs: &[Def], ranges: &[(i64, i64)]) -> (BTreeSet<usize>, Vec<i64>) {
    let top = defs.iter().map(|d| d.end).max().unwrap_or(0).max(0) as usize;
    let mut owner = vec![usize::MAX; top + 1];
    let mut order: Vec<usize> = (0..defs.len()).collect();
    // larger first, so an inner definition paints over the one around it
    order.sort_by_key(|&i| std::cmp::Reverse(defs[i].end - defs[i].start));
    for i in order {
        for l in defs[i].start.max(1)..=defs[i].end {
            owner[l as usize] = i;
        }
    }
    let (mut hit, mut outside) = (BTreeSet::new(), Vec::new());
    for &(a, b) in ranges {
        for l in a.max(1)..=b {
            match owner.get(l as usize) {
                Some(&i) if i != usize::MAX => {
                    hit.insert(i);
                }
                _ => outside.push(l),
            }
        }
    }
    (hit, outside)
}

/// The one of `defs` that is `d` (same kind and qualified name), nearest its lines.
fn nearest<'a>(defs: &'a [Def], d: &Def) -> Option<&'a Def> {
    defs.iter().filter(|n| n.same(d)).min_by_key(|n| (n.start - d.start).abs())
}

struct Builder<'a> {
    s: &'a Searcher,
    /// the changed side is read from git's copies (staged, or a commit), not the working tree
    from_blobs: bool,
    changed: Vec<Changed>,
    notes: Vec<(String, String)>,
    /// chunk ids, and (path, start, kind, qualname) of what has no id, already listed
    seen: HashSet<(i64, String, i64, String, String)>,
    /// every path the diff changed
    files: Vec<String>,
    base_copies: Vec<(String, Vec<u8>)>,
    head_paths: Vec<String>,
}

impl Builder<'_> {
    fn blobs_wanted(&self, e: &Entry) -> Vec<String> {
        if e.submodule || e.binary {
            return Vec::new();
        }
        let mut v = Vec::new();
        if e.old.is_some() {
            v.push(e.old_blob.clone());
        }
        if self.from_blobs && e.new.is_some() && !e.untracked {
            v.push(e.new_blob.clone());
        }
        v
    }

    fn push(&mut self, hit: Hit, status: &'static str) {
        let key = if hit.id != 0 {
            (hit.id, String::new(), 0, String::new(), String::new())
        } else {
            (0, hit.path.clone(), hit.start, hit.kind.clone(), hit.qualname.clone())
        };
        if self.seen.insert(key) {
            self.changed.push(Changed { hit, status });
        }
    }

    fn entry(&mut self, e: &Entry, blobs: &BTreeMap<String, Vec<u8>>) -> Result<()> {
        let path = e.new.as_deref().or(e.old.as_deref()).unwrap_or_default().to_string();
        self.files.push(path.clone());
        self.head_paths.extend(e.new.clone());
        if let (Some(old), Some(new)) = (&e.old, &e.new) {
            if old != new {
                self.notes.push((new.clone(), format!("renamed from {}", shown(old))));
            }
        }
        if e.submodule {
            self.notes.push((path, "a submodule: its commits are not read".into()));
            return Ok(());
        }
        if e.binary {
            self.notes.push((path, "a binary file".into()));
            return Ok(());
        }
        if let Some(new) = e.new.as_deref().filter(|n| !self.s.ix.has_file(n)) {
            self.notes.push((new.to_string(), "not in the index: it has no definitions to name".into()));
            return Ok(());
        }
        let blob = |sha: &str| blobs.get(sha).map(Vec::as_slice).unwrap_or_default();
        if let Some(old) = &e.old {
            self.base_copies.push((old.clone(), blob(&e.old_blob).to_vec()));
        }
        let old_defs = match &e.old {
            Some(old) => parsed(old, blob(&e.old_blob)),
            None => Vec::new(),
        };
        let added = e.old.is_none();
        let ix = &self.s.ix;
        // the tree as it is: the index's definitions; the staged copy: a parse of it, matched to the index's
        let (new_defs, indexed): (Vec<Def>, Vec<Def>) = match &e.new {
            Some(new) => {
                let rows: Vec<Def> = ix
                    .outline(new)?
                    .into_iter()
                    .map(|r| Def { kind: r.kind, name: r.name, qualname: r.qualname, start: r.start, end: r.end, id: r.id })
                    .collect();
                if self.from_blobs && !e.untracked {
                    (parsed(new, blob(&e.new_blob)), rows)
                } else {
                    (rows.clone(), rows)
                }
            }
            None => (Vec::new(), Vec::new()),
        };
        let new_ranges = if e.untracked { vec![(1, line_count(&ix.root.join(&path)))] } else { e.new_lines.clone() };
        let (new_hit, new_outside) = touched(&new_defs, &new_ranges);
        let (old_hit, old_outside) = touched(&old_defs, &e.old_lines);
        let new_path = e.new.clone().unwrap_or_default();
        // a staged definition is named where the index holds it now, when it does
        let current = |d: &Def| -> Hit {
            match nearest(&indexed, d).filter(|_| d.id == 0) {
                Some(i) => i.hit(&new_path),
                None => d.hit(&new_path),
            }
        };
        for i in new_hit {
            let d = &new_defs[i];
            let status = if old_defs.iter().any(|o| o.same(d)) { "edited" } else { "added" };
            let h = current(d);
            self.push(h, status);
        }
        for i in old_hit {
            let d = &old_defs[i];
            match nearest(&new_defs, d) {
                Some(n) => {
                    let h = current(n);
                    self.push(h, "edited");
                }
                None => self.push(d.hit(e.old.as_deref().unwrap_or_default()), "deleted"),
            }
        }
        // lines outside every definition: the window that holds them, as callers names such a caller
        let mut bare = !old_outside.is_empty();
        let from_index = e.new.is_some() && (!self.from_blobs || e.untracked);
        let mut after = 0;
        for l in new_outside {
            if !from_index {
                bare = true;
                break;
            }
            if l <= after {
                continue;
            }
            match ix.window_at(&path, l)? {
                Some(w) => {
                    after = w.end;
                    self.push(Hit::from_row(&w, false), if added { "added" } else { "edited" });
                }
                None => bare = true,
            }
        }
        let named = self.changed.iter().any(|c| c.hit.path == path && matches!(c.hit.kind.as_str(), "window" | "module"));
        if bare && !named {
            let status = if e.new.is_none() {
                "deleted"
            } else if added {
                "added"
            } else {
                "edited"
            };
            self.push(Hit { path, kind: "file".into(), ..Hit::default() }, status);
        }
        Ok(())
    }
}

/// Lines of a file, the last one counted without its line break.
fn line_count(p: &Path) -> i64 {
    let b = std::fs::read(p).unwrap_or_default();
    let n = b.iter().filter(|&&c| c == b'\n').count();
    (n + usize::from(b.last().is_some_and(|&c| c != b'\n'))) as i64
}

/// One file of the diff: its paths on each side (None where it does not exist), git's blob ids,
/// and the changed lines of each side as (first, last).
#[derive(Default, Debug)]
struct Entry {
    old: Option<String>,
    new: Option<String>,
    old_blob: String,
    new_blob: String,
    submodule: bool,
    binary: bool,
    untracked: bool,
    old_lines: Vec<(i64, i64)>,
    new_lines: Vec<(i64, i64)>,
}

/// The `git` program run in the repository. Nothing it runs writes: no optional locks, no file
/// system monitor, no external diff or text conversion. A revision is checked before it is
/// passed, so it never reaches git as an option.
struct Git {
    dir: PathBuf,
}

impl Git {
    fn new(root: &Path) -> Result<Git> {
        let git = Git { dir: plain_dir(root) };
        let out = git.command(&["rev-parse", "--is-inside-work-tree"]).output().map_err(not_run)?;
        if !out.status.success() || out.stdout.trim_ascii() != b"true" {
            let why = first_line(&out.stderr);
            if why.is_empty() || why.contains("not a git repository") {
                bail!("{} is not in a git repository: impact reads the changes with git", root.display());
            }
            bail!("git: {why}");
        }
        Ok(git)
    }

    fn command(&self, args: &[&str]) -> Command {
        let mut c = Command::new("git");
        c.current_dir(&self.dir).args(["--no-optional-locks", "-c", "core.fsmonitor=false"]).args(args).stdin(Stdio::null());
        c
    }

    /// (exited with 0, standard output, standard error)
    fn output(&self, args: &[&str]) -> Result<(bool, Vec<u8>, String)> {
        let out = self.command(args).output().map_err(not_run)?;
        Ok((out.status.success(), out.stdout, first_line(&out.stderr)))
    }

    fn run(&self, args: &[&str]) -> Result<Vec<u8>> {
        match self.output(args)? {
            (true, out, _) => Ok(out),
            (false, _, why) => bail!("git {}: {why}", args[0]),
        }
    }

    /// The commit `rev` names; `A...B` is the merge base of the two (an empty side is `HEAD`).
    fn base(&self, rev: &str) -> Result<String> {
        let Some((a, b)) = rev.split_once("...") else { return self.commit(rev) };
        let (a, b) = (if a.is_empty() { "HEAD" } else { a }, if b.is_empty() { "HEAD" } else { b });
        let (x, y) = (self.commit(a)?, self.commit(b)?);
        match self.output(&["merge-base", &x, &y])? {
            (true, out, _) if !out.trim_ascii().is_empty() => Ok(String::from_utf8_lossy(out.trim_ascii()).into_owned()),
            _ => bail!("{} and {} have no merge base", echo(a), echo(b)),
        }
    }

    fn commit(&self, rev: &str) -> Result<String> {
        // a revision is one argument and never an option, so `--output=x` is refused here
        if rev.is_empty() || rev.starts_with('-') {
            bail!("not a revision: {}", echo(rev));
        }
        match self.output(&["rev-parse", "--verify", "--quiet", &format!("{rev}^{{commit}}")])? {
            (true, out, _) => Ok(String::from_utf8_lossy(out.trim_ascii()).into_owned()),
            _ if rev == "HEAD" => bail!("HEAD names no commit yet: commit once, or pass a base revision"),
            _ => bail!("not a revision of this repository: {}", echo(rev)),
        }
    }

    /// The files that differ from `base`, with their changed lines, and the untracked files.
    fn diff(&self, base: &str, new: &New) -> Result<Vec<Entry>> {
        let common = ["diff", "--no-color", "--no-ext-diff", "--no-textconv", "--relative", "-M", "--src-prefix=a/", "--dst-prefix=b/"];
        let with = |more: &[&str]| -> Vec<String> {
            let mut v: Vec<String> = common.iter().chain(more).map(|s| s.to_string()).collect();
            if matches!(new, New::Staged) {
                v.push("--cached".into());
            }
            v.push(base.to_string());
            if let New::Commit(head) = new {
                v.push(head.clone());
            }
            v.push("--".into());
            v
        };
        let raw = self.run(&with(&["--raw", "-z", "--no-abbrev"]).iter().map(String::as_str).collect::<Vec<_>>())?;
        let patch = self.run(&with(&["-U0", "--inter-hunk-context=0"]).iter().map(String::as_str).collect::<Vec<_>>())?;
        let mut entries = raw_entries(&raw)?;
        let sections = sections(&patch);
        // a file whose stat alone changed is in the raw list and has no section: nothing changed
        entries.retain_mut(|e| {
            let key = e.new.as_deref().or(e.old.as_deref()).unwrap_or_default();
            match sections.get(key) {
                Some(s) => {
                    e.binary = s.binary;
                    e.old_lines = s.old.clone();
                    e.new_lines = s.new.clone();
                    true
                }
                None => e.submodule || e.old != e.new,
            }
        });
        if matches!(new, New::Tree) {
            for p in self.run(&["ls-files", "--others", "--exclude-standard", "-z"])?.split(|&b| b == 0).filter(|p| !p.is_empty()) {
                entries.push(Entry { new: Some(String::from_utf8_lossy(p).into_owned()), untracked: true, ..Entry::default() });
            }
        }
        Ok(entries)
    }

    /// The contents of these blobs, by id, read by one `git cat-file --batch`.
    fn blobs(&self, ids: &BTreeSet<String>) -> Result<BTreeMap<String, Vec<u8>>> {
        let ids: Vec<&String> = ids.iter().filter(|id| !id.is_empty() && id.bytes().any(|b| b != b'0')).collect();
        let mut out = BTreeMap::new();
        if ids.is_empty() {
            return Ok(out);
        }
        let mut child = self.command(&["cat-file", "--batch"]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().map_err(not_run)?;
        let mut stdin = child.stdin.take().ok_or_else(|| anyhow!("git cat-file: no input"))?;
        let asked: String = ids.iter().map(|id| format!("{id}\n")).collect();
        // written beside the read, so a full pipe on either side does not stop both
        let writer = std::thread::spawn(move || stdin.write_all(asked.as_bytes()));
        let mut bytes = Vec::new();
        child.stdout.take().ok_or_else(|| anyhow!("git cat-file: no output"))?.read_to_end(&mut bytes)?;
        let _ = writer.join();
        child.wait()?;
        let mut rest = &bytes[..];
        for id in ids {
            let Some(nl) = rest.iter().position(|&b| b == b'\n') else { break };
            let head = String::from_utf8_lossy(&rest[..nl]).into_owned();
            rest = &rest[nl + 1..];
            let mut parts = head.split(' ');
            let (_, kind, size) = (parts.next(), parts.next(), parts.next().and_then(|n| n.parse::<usize>().ok()));
            if let (Some("blob"), Some(n)) = (kind, size) {
                let n = n.min(rest.len());
                out.insert(id.clone(), rest[..n].to_vec());
                rest = rest.get(n + 1..).unwrap_or_default();
            }
        }
        Ok(out)
    }
}

/// The entries of `git diff --raw -z`: `:mode mode blob blob status`, then one path, or two for a rename.
fn raw_entries(raw: &[u8]) -> Result<Vec<Entry>> {
    let mut fields = raw.split(|&b| b == 0).map(|f| String::from_utf8_lossy(f).into_owned());
    let mut out = Vec::new();
    while let Some(head) = fields.next() {
        let Some(head) = head.strip_prefix(':') else { continue };
        let parts: Vec<&str> = head.split(' ').collect();
        let [old_mode, new_mode, old_blob, new_blob, status] = parts[..] else { bail!("git diff --raw: cannot read {}", echo(head)) };
        let path = fields.next().unwrap_or_default();
        let mut e = Entry { old_blob: old_blob.into(), new_blob: new_blob.into(), submodule: old_mode == "160000" || new_mode == "160000", ..Entry::default() };
        match status.as_bytes().first() {
            Some(b'A') => e.new = Some(path),
            Some(b'D') => e.old = Some(path),
            Some(b'R' | b'C') => {
                e.new = fields.next();
                e.old = Some(path);
            }
            Some(b'U') => bail!("{} is unmerged: finish the merge before asking what it changes", echo(&path)),
            _ => {
                e.old = Some(path.clone());
                e.new = Some(path);
            }
        }
        out.push(e);
    }
    Ok(out)
}

#[derive(Default)]
struct Section {
    binary: bool,
    old: Vec<(i64, i64)>,
    new: Vec<(i64, i64)>,
}

/// The files of a `-U0` patch, by the path they have after the change (before it, when deleted):
/// their changed lines on each side and whether git found them binary.
fn sections(patch: &[u8]) -> BTreeMap<String, Section> {
    let mut out = BTreeMap::new();
    let mut cur: Option<(String, Section)> = None;
    let mut done = |cur: &mut Option<(String, Section)>| {
        if let Some((p, s)) = cur.take() {
            out.insert(p, s);
        }
    };
    for line in patch.split(|&b| b == b'\n') {
        if let Some(head) = line.strip_prefix(b"diff --git ") {
            done(&mut cur);
            cur = Some((header_path(head).unwrap_or_default(), Section::default()));
            continue;
        }
        let Some((path, s)) = cur.as_mut() else { continue };
        if let Some(p) = line.strip_prefix(b"rename to ") {
            *path = unquoted(p);
        } else if line.starts_with(b"Binary files ") || line == b"GIT binary patch" {
            s.binary = true;
        } else if let Some(h) = line.strip_prefix(b"@@ -") {
            let h = String::from_utf8_lossy(h);
            let mut sides = h.split(' ');
            let range = |t: Option<&str>| -> Option<(i64, i64)> {
                let t = t?.trim_start_matches(['-', '+']);
                let (first, n) = match t.split_once(',') {
                    Some((a, n)) => (a.parse().ok()?, n.parse::<i64>().ok()?),
                    None => (t.parse().ok()?, 1),
                };
                (n > 0).then_some((first, first + n - 1))
            };
            if let Some(r) = range(sides.next()) {
                s.old.push(r);
            }
            if let Some(r) = range(sides.next()) {
                s.new.push(r);
            }
        }
    }
    done(&mut cur);
    out
}

/// The path of a `diff --git a/P b/P` line: both halves name the same file unless it was renamed,
/// and then the `rename to` line names it.
fn header_path(head: &[u8]) -> Option<String> {
    if head.first() == Some(&b'"') {
        let (a, rest) = quoted(head)?;
        let b = rest.strip_prefix(b" ").and_then(|r| quoted(r).map(|q| q.0)).unwrap_or(a);
        return Some(String::from_utf8_lossy(b.strip_prefix(b"b/").unwrap_or(&b[..])).into_owned());
    }
    let n = head.len().checked_sub(5)? / 2;
    let (a, b) = (head.get(..n + 2)?, head.get(n + 3..)?);
    match (a.strip_prefix(b"a/"), b.strip_prefix(b"b/")) {
        (Some(x), Some(y)) if x == y => Some(String::from_utf8_lossy(y).into_owned()),
        _ => Some(String::from_utf8_lossy(b.strip_prefix(b"b/").unwrap_or(b)).into_owned()),
    }
}

/// A path git wrote as it is, or in C quotes when it holds special bytes.
fn unquoted(p: &[u8]) -> String {
    match quoted(p) {
        Some((q, _)) => String::from_utf8_lossy(&q).into_owned(),
        None => String::from_utf8_lossy(p).into_owned(),
    }
}

/// A C-quoted string at the start of `s` (`"a\tb\303\251"`), decoded, and what follows it.
fn quoted(s: &[u8]) -> Option<(Vec<u8>, &[u8])> {
    let mut i = 1;
    if s.first() != Some(&b'"') {
        return None;
    }
    let mut out = Vec::new();
    while i < s.len() {
        match s[i] {
            b'"' => return Some((out, &s[i + 1..])),
            b'\\' => {
                let c = *s.get(i + 1)?;
                i += 2;
                match c {
                    b'0'..=b'7' => {
                        let digits = s.get(i - 1..i + 2)?;
                        out.push(u8::from_str_radix(std::str::from_utf8(digits).ok()?, 8).ok()?);
                        i += 2;
                    }
                    b'a' => out.push(7),
                    b'b' => out.push(8),
                    b't' => out.push(b'\t'),
                    b'n' => out.push(b'\n'),
                    b'v' => out.push(11),
                    b'f' => out.push(12),
                    b'r' => out.push(b'\r'),
                    c => out.push(c),
                }
            }
            c => {
                out.push(c);
                i += 1;
            }
        }
    }
    None
}

fn not_run(e: std::io::Error) -> anyhow::Error {
    if e.kind() == std::io::ErrorKind::NotFound {
        anyhow!("git is not installed or not on PATH: impact reads the changes with git")
    } else {
        anyhow!("cannot run git: {e}")
    }
}

fn first_line(b: &[u8]) -> String {
    let s = String::from_utf8_lossy(b);
    let line = s.lines().find(|l| !l.trim().is_empty()).unwrap_or("").trim();
    line.strip_prefix("fatal: ").or_else(|| line.strip_prefix("error: ")).unwrap_or(line).to_string()
}

/// The root as a directory to start git in: on Windows a verbatim drive path (`\\?\C:\x`, what
/// `canonicalize` gives) in its plain form.
fn plain_dir(root: &Path) -> PathBuf {
    let s = root.to_string_lossy();
    match s.strip_prefix(r"\\?\") {
        Some(rest) if cfg!(windows) && rest.as_bytes().get(1) == Some(&b':') => PathBuf::from(rest),
        _ => root.to_path_buf(),
    }
}

impl Impact {
    /// The first line: what was compared with what.
    pub fn head(&self) -> String {
        let short = self.base.get(..12).unwrap_or(&self.base);
        format!("{} against {} ({short})", if self.staged { "staged changes" } else { "working tree" }, echo(&self.against))
    }

    pub fn is_empty(&self) -> bool {
        self.changed.is_empty() && self.notes.is_empty() && self.tests.is_empty()
    }

    /// The repository files whose indexed definitions this answer shows.
    pub fn cited(&self) -> Vec<&str> {
        let changed = self.changed.iter().filter(|c| c.status != "deleted").map(|c| c.hit.path.as_str());
        changed.chain(self.callers.iter().map(|c| c.hit.path.as_str())).collect()
    }

    /// One line per section head and per item, as the text pages them.
    pub fn lines(&self) -> Vec<String> {
        let symbol = |h: &Hit| {
            if h.kind == "file" {
                format!("{}  [file]", shown(&h.path))
            } else {
                format!("{}  [{}] {}", crate::fmt::loc(h), h.kind, shown(if h.qualname.is_empty() { &h.name } else { &h.qualname }))
            }
        };
        let mut out = vec![format!("changed: {}", self.changed.len())];
        out.extend(self.changed.iter().map(|c| {
            let at = if c.status == "deleted" && c.hit.kind != "file" { ", lines of the base" } else { "" };
            format!("{}  ({}{at})", symbol(&c.hit), c.status)
        }));
        out.push(format!("callers: {} (depth {})", self.callers.len(), self.depth));
        out.extend(self.callers.iter().map(|c| {
            let mark = if c.calls_deleted {
                "  (calls a deleted definition)"
            } else if c.undecided {
                "  (undecided)"
            } else {
                ""
            };
            format!("{:>2}  {}{mark}", c.distance, symbol(&c.hit))
        }));
        out.push(format!("tests: {}", self.tests.len()));
        out.extend(self.tests.iter().map(|t| match &t.via {
            Some(h) => format!("{}  (distance {}: {})", shown(&t.path), t.distance, symbol(h)),
            None => format!("{}  (changed)", shown(&t.path)),
        }));
        if !self.notes.is_empty() {
            out.push(format!("notes: {}", self.notes.len()));
            out.extend(self.notes.iter().map(|(p, n)| format!("{}  {n}", shown(p))));
        }
        out
    }

    pub fn stop_line(&self) -> String {
        if self.stopped {
            format!("(the walk stopped at {MAX_CALLERS} callers: pass a smaller depth)")
        } else {
            String::new()
        }
    }

    pub fn json(&self) -> Value {
        let symbol = |h: &Hit| {
            if h.kind == "file" {
                json!({"id": h.path, "path": h.path, "start": null, "end": null, "kind": "file", "qualname": ""})
            } else {
                json!({"id": h.loc(), "path": h.path, "start": h.start, "end": h.end, "kind": h.kind, "qualname": if h.qualname.is_empty() { &h.name } else { &h.qualname }})
            }
        };
        let with = |mut v: Value, k: &str, x: Value| {
            v[k] = x;
            v
        };
        json!({
            "against": self.against,
            "base": self.base,
            "staged": self.staged,
            "depth": self.depth,
            "changed": self.changed.iter().map(|c| with(symbol(&c.hit), "status", json!(c.status))).collect::<Vec<_>>(),
            "callers": self.callers.iter().map(|c| {
                let v = with(symbol(&c.hit), "distance", json!(c.distance));
                with(with(with(v, "via", json!(c.via)), "undecided", json!(c.undecided)), "calls_deleted", json!(c.calls_deleted))
            }).collect::<Vec<_>>(),
            "tests": self.tests.iter().map(|t| json!({"path": t.path, "distance": t.distance, "via": t.via.as_ref().map(symbol)})).collect::<Vec<_>>(),
            "notes": self.notes.iter().map(|(p, n)| json!({"path": p, "note": n})).collect::<Vec<_>>(),
            "stopped": self.stopped,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_patch_gives_each_file_its_changed_lines_by_the_path_it_has_now() {
        let patch = b"diff --git a/a.py b/a.py\nindex 1..2 100644\n--- a/a.py\n+++ b/a.py\n@@ -3 +3,2 @@ def f\n-x\n+y\n+z\n@@ -9,2 +10,0 @@\n-p\n-q\n\
diff --git a/old.py b/new.py\nsimilarity index 90%\nrename from old.py\nrename to new.py\n@@ -0,0 +1 @@\n+diff --git a/x b/x\n\
diff --git \"a/t\\tab.py\" \"b/t\\tab.py\"\n@@ -1 +1 @@\n-a\n+b\n\
diff --git a/img.png b/img.png\nBinary files a/img.png and b/img.png differ\n";
        let s = sections(patch);
        assert_eq!(s.keys().map(String::as_str).collect::<Vec<_>>(), ["a.py", "img.png", "new.py", "t\tab.py"]);
        assert_eq!((s["a.py"].old.clone(), s["a.py"].new.clone()), (vec![(3, 3), (9, 10)], vec![(3, 4)]));
        assert_eq!(s["new.py"].new, vec![(1, 1)]);
        assert!(s["img.png"].binary && !s["a.py"].binary);
        assert_eq!(s["t\tab.py"].new, vec![(1, 1)]);
    }

    #[test]
    fn a_line_belongs_to_the_innermost_definition_around_it() {
        let d = |kind: &str, start, end| Def { kind: kind.into(), name: kind.into(), qualname: kind.into(), start, end, id: 0 };
        let defs = [d("class", 1, 10), d("method", 3, 5)];
        let (hit, outside) = touched(&defs, &[(4, 4), (8, 8), (12, 13)]);
        assert_eq!(hit.into_iter().collect::<Vec<_>>(), [0, 1]);
        assert_eq!(outside, [12, 13]);
    }

    #[test]
    fn a_c_quoted_path_is_decoded() {
        assert_eq!(
            quoted(b"\"a\\303\\251\\\"b\" rest").map(|(q, r)| (String::from_utf8(q).unwrap(), r.to_vec())),
            Some(("a\u{e9}\"b".into(), b" rest".to_vec()))
        );
    }
}

//! Incremental on-disk index: SQLite (chunks, call refs, manifest) + memory-mapped segments
//! (BM25 postings, vectors).

use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::{Duration, Instant, SystemTime};

use anyhow::{bail, Context, Result};
use rayon::prelude::*;
use rusqlite::{params, params_from_iter, Connection, OptionalExtension};
use sha1::{Digest, Sha1};

use crate::artifacts::{Artifact, Found, Key};
use crate::lex::{merge_segments, FileLex, LexStore, QVecs, SegmentBuilder};
use crate::models::ModelSet;
use crate::parse::{parse_file_with, PrevParse};
use crate::semantic::SemanticModel;
use crate::text::name_key;

pub const SCHEMA_VERSION: u32 = 14;
/// What the parser and tokenizer make of a file. Bump it with every change of the rules in
/// `langs.rs`, `parse.rs` or `text.rs`:
/// an index of an older revision reads every file again on its next update, and one of a newer
/// revision is read as it is and never updated.
pub const CONTENT_REVISION: u32 = 2;
pub use crate::models::REVISION as MODEL_REVISION;
pub const MAX_SEGMENTS: usize = 6; // more live segments than this triggers a merge of the small ones
pub const SMALL_INDEX_ROWS: usize = 8000; // an index this small is kept as ONE segment
/// Rows per segment flushed during one update: bounds the memory of building the inverted index
/// (the postings of a whole monorepository would not fit) at the price of more, smaller segments,
/// which compaction merges later.
pub const SEGMENT_ROWS: usize = 100_000;
/// Compaction never builds a segment larger than this, so a merge's memory is bounded too.
pub const MAX_MERGE_ROWS: usize = 300_000;
/// Databases up to this size get a full `PRAGMA quick_check` on every open (milliseconds); larger
/// ones are checked on demand (`scrutate check`) and recovered when an operation reports corruption.
pub const QUICK_CHECK_MAX_BYTES: u64 = 64 * 1024 * 1024;
pub const GC_AGE_S: u64 = 600; // unreferenced segment directories younger than this may be in flight
pub const MAX_FILE_BYTES: u64 = 1_000_000;
/// Source bytes of the syntax trees an open index keeps for incremental reparsing (the trees
/// themselves take several times this in memory).
pub const TREE_CACHE_BYTES: usize = 2 << 20;
pub const TF_CAP: u32 = 4; // a token counts at most this many times per field

const SCHEMA: &str = "
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS files(path TEXT PRIMARY KEY, size INTEGER, mtime_ns INTEGER, hash TEXT, ctime_ns INTEGER, art BLOB);
CREATE TABLE IF NOT EXISTS chunks(
  id INTEGER PRIMARY KEY, path TEXT NOT NULL, kind TEXT, name TEXT, qualname TEXT,
  name_key TEXT, qual_key TEXT, start INTEGER, end INTEGER, is_test INTEGER,
  ndoc INTEGER, nbody INTEGER, text BLOB, name_tok TEXT);
CREATE INDEX IF NOT EXISTS chunks_path ON chunks(path, start);
CREATE INDEX IF NOT EXISTS chunks_name ON chunks(name_key);
CREATE INDEX IF NOT EXISTS chunks_qual ON chunks(qual_key);
CREATE TABLE IF NOT EXISTS refs(chunk_id INTEGER NOT NULL, callee TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS refs_callee ON refs(callee);
CREATE INDEX IF NOT EXISTS refs_chunk ON refs(chunk_id);
CREATE TABLE IF NOT EXISTS imports(path TEXT NOT NULL, module TEXT NOT NULL, line INTEGER);
CREATE INDEX IF NOT EXISTS imports_path ON imports(path);
CREATE INDEX IF NOT EXISTS imports_module ON imports(module);
CREATE TABLE IF NOT EXISTS artifacts(key BLOB PRIMARY KEY, body BLOB NOT NULL, kept BLOB, bytes INTEGER NOT NULL, used INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS artifacts_kept ON artifacts(used) WHERE kept IS NOT NULL;
";
/// Made once the `files` table has the `art` column, which an index of an older schema lacks.
const ART_INDEX: &str = "CREATE INDEX IF NOT EXISTS files_art ON files(art) WHERE art IS NOT NULL;";
/// Artifacts no file names are kept up to a quarter of the database's size, and at least this.
pub const KEPT_MIN_BYTES: i64 = 4 << 20;

