impl Default for CheckReport {
    fn default() -> Self {
        CheckReport {
            database_ok: true,
            segments: 0,
            segments_ok: true,
            chunks_db: 0,
            chunks_alive: 0,
            files_indexed: 0,
            files_changed: 0,
            files_missing: 0,
