//! MCP server over stdio (JSON-RPC 2.0, newline-delimited), exposing the search tools to Claude Code
//! and other MCP clients. No SDK: the protocol surface a tools-only server needs is small, and a
//! dependency-free implementation is one less thing to break over the years.
//!
//! Two eras of the protocol are served on the same pipe. A client that opens with `initialize`
//! gets the handshake revisions. A request that names its protocol version in `_meta` is served
//! by revision 2026-07-28, which has no handshake: every result then carries `resultType`, and
//! lists say how long they may be cached.

use std::collections::HashMap;
use std::io::{BufRead, Write};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};

use anyhow::Result;
use serde_json::{json, Value};

use crate::ops;
use crate::session::{Panicked, Session, BUILD_WAIT};

/// Revisions that open with the `initialize` handshake.
const HANDSHAKE_VERSIONS: &[&str] = &["2024-11-05", "2025-03-26", "2025-06-18", "2025-11-25"];
/// The revision without a handshake.
const STATELESS_VERSION: &str = "2026-07-28";
const VERSION_KEY: &str = "io.modelcontextprotocol/protocolVersion";
const SERVER_INFO_KEY: &str = "io.modelcontextprotocol/serverInfo";
/// How long a client may keep a list, in milliseconds: the tools change only with the binary.
const LIST_TTL_MS: u64 = 3_600_000;

/// What a client shows its model before any tool is loaded; the first sentences stand alone.
const INSTRUCTIONS: &str = "scrutate searches the code of this repository from a local index. \
Start with search_code for a question in words or a name, or repo_map for the important files of a repository you do not know; \
use grep_code for an exact pattern, find_symbol for a definition, find_files for a file by a part of its name, \
references for every use of a name, callers and callees to follow calls, call_path for how one function reaches another, \
outline and read_code to read a file in pieces or one whole definition, and impact for what a git diff changes, who calls it \
and which tests to run. \
Every tool only reads, except reindex, which refreshes the index (a cache under .scrutate/). \
Results are capped; a tool says when it stopped early and which argument raises the limit. \
Each result begins with its location (path:start-end). Pass that location wherever a tool takes a symbol name \
to mean that one definition: read_code symbol, find_symbol, callers, callees, call_path, similar_code, references def. \
A result of kind window is a stretch of lines outside every definition: callees and similar_code take its location, \
and read_code reads it by path and lines; find_symbol, callers and references def answer that no symbol is there. \
response_format concise gives the locations and names without code: there a line that ends with / names the directory \
of the paths below it written without one, and a location written :start-end is in the file of the one before it.";

/// The tools, each with the hints clients use to decide whether a call needs approval and, with
/// `structured`, the schema of the JSON its results carry. `short`: the short descriptions and
/// no argument descriptions, for clients that send the list to their model in every session;
/// names, argument types, defaults and what is required stay the same.
pub fn tools(structured: bool, max_bytes: usize, short: bool) -> Value {
    let mut tools = tool_table();
    for tool in tools.as_array_mut().into_iter().flatten() {
        let name = tool["name"].as_str().unwrap_or("").to_string();
        let read_only = ops::read_only(&name);
        let brief = tool.as_object_mut().and_then(|t| t.remove("short")).unwrap_or(Value::Null);
        tool["annotations"] = if short && read_only {
            // the other two hints mean something only for a tool that writes
            json!({"readOnlyHint": true, "openWorldHint": false})
        } else {
            json!({"readOnlyHint": read_only, "destructiveHint": false, "idempotentHint": true, "openWorldHint": false})
        };
        if structured {
            tool["outputSchema"] = ops::output_schema(&name);
        }
        let properties = &mut tool["inputSchema"]["properties"];
        if short {
            // the arguments every tool shares are named once, in the instructions (`instructions`)
            tool["description"] = brief;
            for schema in ["inputSchema", "outputSchema"] {
                tool.get_mut(schema).into_iter().for_each(drop_descriptions);
            }
            continue;
        }
        if read_only {
            properties["max_bytes"] = json!({"type": "integer", "default": max_bytes, "description": "size limit of the answer"});
            properties["offset"] =
                json!({"type": "integer", "default": 0, "description": "items to skip, to continue an answer that said more were not shown"});
        }
        properties["response_format"] = json!({"type": "string", "enum": ["detailed", "concise"], "default": "detailed",
            "description": "concise: locations and names, no code"});
    }
    tools
}

/// What the server tells a client at the start; with the short tool list, the arguments every
/// tool shares, which its schemas then leave out (the server checks them as before).
fn instructions(short: bool, max_bytes: usize) -> String {
    if !short {
        return INSTRUCTIONS.to_string();
    }
    format!(
        "{INSTRUCTIONS} Every tool also takes response_format (\"detailed\", the default, or \"concise\"), and every tool but \
reindex takes max_bytes (an integer, default {max_bytes}) and offset (an integer, default 0)."
    )
}

/// `schema` without the `description` of any property.
fn drop_descriptions(schema: &mut Value) {
    match schema {
        Value::Object(map) => {
            if map.get("description").is_some_and(Value::is_string) {
                map.remove("description");
            }
            map.values_mut().for_each(drop_descriptions);
        }
        Value::Array(items) => items.iter_mut().for_each(drop_descriptions),
        _ => {}
    }
}

fn tool_table() -> Value {
    json!([
        {"name": "search_code", "short": "Search code by meaning or name.",
         "description": "Search the codebase by meaning or by name. Returns the best matching functions/classes with file:line and a snippet. `query` may be natural language (\"where do we refresh expired tokens\") or identifiers (`ClientSession.call_tool`). To improve recall put synonyms and likely identifier names in `alt_queries` (e.g. [\"renew credentials\", \"refresh_token\"], at most 10); results of all phrasings are fused.",
         "inputSchema": {"type": "object", "properties": {
             "query": {"type": "string"},
             "alt_queries": {"type": ["array", "null"], "items": {"type": "string"}, "default": null},
             "k": {"type": "integer", "default": ops::SEARCH_K}}, "required": ["query"]}},
        {"name": "grep_code", "short": "Exact or regex search, lines grouped by symbol.", "description": "Exact search of the files the index holds: hidden ones such as .github/ included; ignored files, .git/ and dependency or cache directories such as node_modules/ not. Matching lines are grouped by the enclosing function/class. `mode` identifier finds every casing of a name (refreshToken, refresh_token, REFRESH_TOKEN); fuzzy allows `max_edits` typos; `path` keeps one file or directory and `globs` keep files by name (`!` excludes).",
         "inputSchema": {"type": "object", "properties": {
             "pattern": {"type": "string"},
             "mode": {"type": "string", "enum": ["regex", "literal", "identifier", "fuzzy", "fuzzy_regex", "pcre2"], "default": "regex"},
             "case": {"type": "string", "enum": ["sensitive", "insensitive", "smart"], "default": "sensitive"},
             "word": {"type": "boolean", "default": false, "description": "whole words only"},
             "max_edits": {"type": "integer", "default": 1, "description": "edits a fuzzy match may need"},
             "path": {"type": ["string", "null"], "default": null, "description": "a file or directory of the repository to search under"},
             "globs": {"type": ["array", "null"], "items": {"type": "string"}, "default": null, "description": "keep the files these globs match, as grep -g (`!` excludes)"},
             "max_results": {"type": "integer", "default": ops::GREP_MAX}}, "required": ["pattern"]}},
        {"name": "find_symbol", "short": "Where a name is defined.", "description": "Where is this function/class/method defined? (`Class.method` works, as do `Class::method`, `Class#method` and a location from another answer).",
         "inputSchema": {"type": "object", "properties": {"name": {"type": "string"}, "limit": {"type": "integer", "default": ops::SYMBOL_LIMIT}}, "required": ["name"]}},
        {"name": "callers", "short": "Who calls a function.", "description": "Which functions call this function?",
         "inputSchema": {"type": "object", "properties": {"name": {"type": "string"}, "limit": {"type": "integer", "default": ops::CALLERS_LIMIT}}, "required": ["name"]}},
        {"name": "callees", "short": "What a function calls.", "description": "Which functions does this function call?",
         "inputSchema": {"type": "object", "properties": {"name": {"type": "string"}, "limit": {"type": "integer", "default": ops::CALLEES_LIMIT}}, "required": ["name"]}},
        {"name": "call_path", "short": "The call chain from one function to another.", "description": "How does `from` reach `to`? The shortest chain of calls between two functions (names, `Class.method` or locations), each step a call site and the function it calls; a name with several definitions lists them to pick one by location.",
         "inputSchema": {"type": "object", "properties": {"from": {"type": "string"}, "to": {"type": "string"}, "depth": {"type": "integer", "default": ops::PATH_DEPTH, "description": "calls to follow at most"}}, "required": ["from", "to"]}},
        {"name": "repo_map", "short": "The most used files and their top definitions.", "description": "The important files of the repository first: files ranked by how much the others call and import them (PageRank), each with its most called definitions. A first call in a repository you do not know.",
         "inputSchema": {"type": "object", "properties": {"path": {"type": ["string", "null"], "default": null, "description": "keep the files under this directory"}}}},
        {"name": "read_code", "short": "Read lines of a file or a whole definition.", "description": "Read a line range of a file (`path`, `start`, `end`), or one whole definition: `symbol` is a name, `Class.method`, or a location from another answer (`src/a.py:12-40`). A name with several definitions returns each; `path` then keeps the ones in that file.",
         "inputSchema": {"type": "object", "properties": {
             "path": {"type": ["string", "null"], "default": null}, "symbol": {"type": ["string", "null"], "default": null},
             "start": {"type": "integer", "default": 1}, "end": {"type": ["integer", "null"], "default": null}}}},
        {"name": "outline", "short": "Symbols of a file.", "description": "Symbols of a file in source order (kind, name, line range).",
         "inputSchema": {"type": "object", "properties": {"path": {"type": "string"}}, "required": ["path"]}},
        {"name": "dependencies", "short": "Imports of a file.", "description": "Modules a file imports, resolved to repository files where possible.",
         "inputSchema": {"type": "object", "properties": {"path": {"type": "string"}}, "required": ["path"]}},
        {"name": "dependents", "short": "Files that import a module or file.", "description": "Files that import a module or repository file (reverse dependencies).",
         "inputSchema": {"type": "object", "properties": {"target": {"type": "string", "description": "module name as imported, or a repository file path"}}, "required": ["target"]}},
        {"name": "references", "short": "Every use of a name.", "description": "Every use of a name, each resolved to the definition it refers to (same-named definitions in other modules are kept apart). `def` (`path` or `path:line`) keeps one definition; `textual` lists every occurrence of the name grouped by the enclosing function/class instead.",
         "inputSchema": {"type": "object", "properties": {"name": {"type": "string"}, "max_results": {"type": "integer", "default": ops::REFS_MAX},
             "def": {"type": ["string", "null"], "default": null}, "textual": {"type": "boolean", "default": false}}, "required": ["name"]}},
        {"name": "similar_code", "short": "Functions like this one.", "description": "Functions similar to a given symbol or location (`name`, `Class.method` or `path:line`): find duplicated logic or existing implementations.",
         "inputSchema": {"type": "object", "properties": {"target": {"type": "string"}, "k": {"type": "integer", "default": ops::SIMILAR_K}}, "required": ["target"]}},
        {"name": "duplicates", "short": "Duplicated functions.", "description": "Duplicate and near-duplicate functions across the repository.",
         "inputSchema": {"type": "object", "properties": {"min_tokens": {"type": "integer", "default": ops::DUPES_MIN_TOKENS}, "threshold": {"type": "number", "default": ops::DUPES_THRESHOLD}, "limit": {"type": "integer", "default": ops::DUPES_LIMIT}}}},
        {"name": "structural_search", "short": "A tree-sitter query over one language.", "description": "Run a tree-sitter query (S-expression pattern with @captures) over all files of one language, e.g. lang=python query=\"(class_definition name: (identifier) @cls)\".",
         "inputSchema": {"type": "object", "properties": {"lang": {"type": "string"}, "query": {"type": "string"}, "limit": {"type": "integer", "default": ops::TSQUERY_LIMIT}}, "required": ["lang", "query"]}},
        {"name": "impact", "short": "Definitions, callers and tests a git diff touches.", "description": "What does my change touch? From the git diff (the working tree and untracked files against HEAD; `base` a revision, `main...` for the merge base with main; `staged` the staged changes) to the changed definitions, their callers with distances up to `depth` steps, and the test files to run.",
         "inputSchema": {"type": "object", "properties": {
             "base": {"type": ["string", "null"], "default": null, "description": "revision to compare with (default HEAD)"},
             "staged": {"type": "boolean", "default": false},
             "depth": {"type": "integer", "default": crate::impact::DEPTH, "description": "steps of callers to follow (at most 10)"}}}},
        {"name": "find_files", "short": "Find a file by part of its name.", "description": "Find a file by part of its name or path, misspelt or with letters left out (`srch.rs` finds search.rs): an exact basename first, then basename matches, then path matches; among equals the files read lately through read_code first. A query that is exactly one path counts as choosing that file. Needs no index.",
         "inputSchema": {"type": "object", "properties": {"query": {"type": "string"}, "limit": {"type": "integer", "default": crate::finder::LIMIT}}, "required": ["query"]}},
        {"name": "dead_code", "short": "Definitions nothing uses.", "description": "Functions, methods, classes and types nothing in the repository uses: no line outside one names it. Entry points (main, tests, exports, public items of a library, decorated or attribute-registered ones) are left out. Ones whose name some line holds that the resolver ties to nothing (a string, a comment, a use it cannot place) are listed as undecided, with why. `path` keeps the definitions under one directory or file.",
         "inputSchema": {"type": "object", "properties": {"path": {"type": ["string", "null"], "default": null, "description": "a directory or file of the repository"}}}},
        {"name": "reindex", "short": "Rescan changed files.", "description": "Re-scan for changed files (searches already do this automatically). `force` reads every file again, also one whose size, modification time and change time did not change.",
         "inputSchema": {"type": "object", "properties": {"force": {"type": "boolean", "default": false}}}}
    ])
}

/// What a tool call returns: text for the model, the same answer as JSON for a client that
/// reads structured results, and whether it failed.
pub struct Called {
    pub text: String,
    pub structured: Value,
    pub is_error: bool,
}

impl Called {
    /// A sentence in place of an answer.
    fn note(text: String, is_error: bool) -> Called {
        let structured = json!({"schema": ops::ANSWER_SCHEMA, "complete": false, "result": null, "text": text});
        Called { text, structured, is_error }
    }
}

/// Run one tool; errors become text for the model.
pub fn call_tool(session: &Session, name: &str, args: &Value, settings: &Settings, cancel: &Arc<AtomicBool>) -> Called {
    let max_bytes = args.get("max_bytes").and_then(Value::as_u64).map_or(settings.max_bytes, |n| clamp_bytes(n as usize));
    let offset = args.get("offset").and_then(Value::as_u64).unwrap_or(0) as usize;
    // a wrong value is refused with the other arguments
    let form = ops::Form::from_tool(args).unwrap_or_default();
    match ops::Op::from_tool(name, args).and_then(|op| session.run(&op, cancel)) {
        Ok(answer) => {
            let text = answer.text_as(max_bytes, offset, form);
            let mut structured = answer.structured(text.len(), max_bytes, offset);
            if structured["result"].is_null() {
                // a client that shows only the structured form still gets the part that fits
                structured["text"] = json!(text);
            }
            Called { text, structured, is_error: false }
        }
        Err(e) if e.is::<crate::index::BeingBuilt>() => Called::note(STILL_BUILDING.to_string(), false),
        Err(e) if e.is::<Panicked>() => {
            let text = if session.build_failed() {
                "error: the index could not be built: internal failure while indexing (a bug: please report it, with the server's stderr); `scrutate index --force` in the repository may clear it, and the server keeps running".to_string()
            } else {
                format!("error: internal failure while running {name} (a bug: please report it); the server keeps running")
            };
            Called::note(text, true)
        }
        Err(e) => Called::note(format!("error: {e}"), true),
    }
}

/// The answer to a call that came before the first index of the repository is ready.
const STILL_BUILDING: &str =
    "scrutate is still building its index of this repository (first use, or many files changed). Call the tool again in a little while.";

/// Where messages go: stdout in the server, a list in its tests.
type Wire<'a> = dyn Fn(Value) + Sync + 'a;

/// One line on stdout: a message leaves whole whichever thread writes it.
fn to_stdout(msg: Value) {
    let mut out = std::io::stdout().lock();
    let _ = writeln!(out, "{msg}");
    let _ = out.flush();
}

/// `stateless`: the request came under the revision whose results all say what kind they are.
fn respond(send: &Wire, id: &Value, stateless: bool, mut result: Value) {
    if stateless {
        result["resultType"] = json!("complete");
    }
    send(json!({"jsonrpc": "2.0", "id": id, "result": result}));
}

fn respond_err(send: &Wire, id: &Value, code: i64, message: &str, data: Option<Value>) {
    let mut error = json!({"code": code, "message": message});
    if let Some(data) = data {
        error["data"] = data;
    }
    send(json!({"jsonrpc": "2.0", "id": id, "error": error}));
}

/// Tool calls in flight, by request id, each with the flag `notifications/cancelled` sets.
#[derive(Default)]
struct Calls(Mutex<HashMap<String, Arc<AtomicBool>>>);

impl Calls {
    fn map(&self) -> std::sync::MutexGuard<'_, HashMap<String, Arc<AtomicBool>>> {
        self.0.lock().unwrap_or_else(|p| p.into_inner())
    }
    fn begin(&self, id: &Value) -> Arc<AtomicBool> {
        let cancelled = Arc::new(AtomicBool::new(false));
        self.map().insert(id.to_string(), Arc::clone(&cancelled));
        cancelled
    }
    fn cancel(&self, id: &Value) {
        if let Some(cancelled) = self.map().get(&id.to_string()) {
            cancelled.store(true, Ordering::Relaxed);
        }
    }
}

struct Call {
    id: Value,
    name: String,
    args: Value,
    stateless: bool,
    /// send the answer as JSON too (`serve --structured`)
    structured: bool,
    /// the client's token for progress reports; null when it did not ask for any
    progress: Value,
    cancelled: Arc<AtomicBool>,
}

/// A tool call waits up to `BUILD_WAIT` for an index that is still being built before it answers
/// that it is. A client that sent a progress token hears every `PROGRESS_SECONDS` that the build
/// goes on, and gets the real answer.
const PROGRESS_SECONDS: u64 = 2;
/// Calls beyond this many in flight run on the thread that reads requests.
const MAX_CALLS: usize = 32;

/// One tool call from its first wait to its answer. A cancelled call sends nothing more: it
/// stops waiting for the index or for its turn, and an answer already being computed is dropped.
fn run_call(send: &Wire, session: &Session, calls: &Calls, settings: &Settings, call: Call) {
    let Call { id, name, args, stateless, structured, progress, cancelled } = call;
    let mut reported = 0;
    let gone = || cancelled.load(Ordering::Relaxed);
    let limit = progress.is_null().then_some(BUILD_WAIT);
    let built = session.wait_built(&cancelled, limit, |waited| {
        let seconds = waited.as_secs();
        if !progress.is_null() && seconds >= reported + PROGRESS_SECONDS {
            reported = seconds;
            let params = json!({"progressToken": progress, "progress": seconds, "message": "building the index of this repository"});
            send(json!({"jsonrpc": "2.0", "method": "notifications/progress", "params": params}));
        }
    });
    let called = if gone() {
        None
    } else if !built {
        Some(Called::note(STILL_BUILDING.to_string(), false))
    } else {
        Some(call_tool(session, &name, &args, settings, &cancelled))
    };
    calls.map().remove(&id.to_string());
    if let Some(c) = called.filter(|_| !gone()) {
        let mut result = json!({"content": [{"type": "text", "text": c.text}], "isError": c.is_error});
        if structured {
            result["structuredContent"] = c.structured;
        }
        respond(send, &id, stateless, result);
    }
}

/// Serve until stdin closes. The first indexing runs in the background so a client is answered
/// at once; tool calls that arrive meanwhile wait for it (`BUILD_WAIT`). Each call runs on a
/// thread of its own, so the reader still sees a `notifications/cancelled` for it.
///
/// `structured`: every tool declares an `outputSchema` and every result carries the answer as
/// JSON beside its text. Off unless asked for: Claude Code (2.1.322) shows its model that JSON in
/// place of the text, which has the snippets and says how to page. `short`: `tools/list` sends
/// the short form of `tools`.
pub fn serve(session: Arc<Session>, settings: Settings, version: &str, structured: bool, short: bool) -> Result<()> {
    session.building();
    {
        let session = Arc::clone(&session);
        std::thread::Builder::new().name("scrutate-index".into()).spawn(move || match session.build() {
            Err(e) if e.is::<Panicked>() => eprintln!("[scrutate] indexing failed: internal failure (a bug: please report it); each tool call tries again"),
            Err(e) => eprintln!("[scrutate] indexing failed: {e:#}"),
            Ok(_) => {}
        })?;
    }
    let calls = Calls::default();
    let server = Server { session: &session, calls: &calls, settings: &settings, version, structured, short };
    let (server, send) = (&server, &to_stdout as &Wire);
    std::thread::scope(|scope| -> Result<()> {
        let mut stdin = std::io::stdin().lock();
        let mut buf = Vec::new();
        loop {
            buf.clear();
            if stdin.read_until(b'\n', &mut buf)? == 0 {
                break;
            }
            let Ok(line) = std::str::from_utf8(&buf) else {
                respond_err(send, &Value::Null, -32700, "parse error: not UTF-8", None);
                continue;
            };
            if line.trim().is_empty() {
                continue;
            }
            match serde_json::from_str(line) {
                Ok(Value::Array(batch)) if !batch.is_empty() => {
                    scope.spawn(move || {
                        let replies = Mutex::new(Vec::new());
                        // progress notifications go out at once; the batch's answers go out together
                        let sink = |m: Value| {
                            if m.get("method").is_some() {
                                send(m)
                            } else {
                                replies.lock().unwrap_or_else(|p| p.into_inner()).push(m)
                            }
                        };
                        std::thread::scope(|inner| batch.into_iter().for_each(|m| server.handle(inner, &sink, m)));
                        let replies = replies.into_inner().unwrap_or_else(|p| p.into_inner());
                        if !replies.is_empty() {
                            send(Value::Array(replies));
                        }
                    });
                }
                Ok(msg) => server.handle(scope, send, msg),
                Err(_) => respond_err(send, &Value::Null, -32700, "parse error", None),
            }
        }
        Ok(())
    })?;
    session.hold_writes();
    Ok(())
}

/// The answer size `serve` was started with.
pub struct Settings {
    /// answer size of a call that gives no `max_bytes`
    max_bytes: usize,
}

impl Settings {
    pub fn new(max_bytes: Option<usize>) -> Settings {
        Settings { max_bytes: max_bytes.map_or(ops::AGENT_BYTES, clamp_bytes) }
    }
}

fn clamp_bytes(n: usize) -> usize {
    n.clamp(1_000, 1_000_000)
}

/// What every message is handled with.
struct Server<'a> {
    session: &'a Session,
    calls: &'a Calls,
    settings: &'a Settings,
    version: &'a str,
    structured: bool,
    short: bool,
}

impl Server<'_> {
    /// Answer one message, alone or a member of a batch, through `send`.
    fn handle<'s, 'e>(&'e self, scope: &'s std::thread::Scope<'s, 'e>, send: &'e Wire<'e>, msg: Value) {
        if !msg.is_object() {
            return respond_err(send, &Value::Null, -32600, "invalid request: not a JSON object", None);
        }
        let id = msg.get("id").cloned().unwrap_or(Value::Null);
        let Some(method) = msg.get("method").and_then(Value::as_str) else {
            // a client's response to a request is not answered
            if msg.get("method").is_none() && (msg.get("result").is_some() || msg.get("error").is_some()) {
                return;
            }
            return respond_err(send, &id, -32600, "invalid request: no method", None);
        };
        let params = msg.get("params").cloned().unwrap_or(json!({}));
        if msg.get("id").is_none() {
            if method == "notifications/cancelled" {
                self.calls.cancel(&params["requestId"]);
            }
            return;
        }
        let asked = params.get("_meta").and_then(|m| m.get(VERSION_KEY)).and_then(Value::as_str);
        if let Some(other) = asked.filter(|v| *v != STATELESS_VERSION) {
            return respond_err(send, &id, -32022, "Unsupported protocol version", Some(json!({"supported": [STATELESS_VERSION], "requested": other})));
        }
        let stateless = asked.is_some();
        // a list a client may cache, under the revision that asks every list to say so
        let list = |mut result: Value| {
            if stateless {
                result["ttlMs"] = json!(LIST_TTL_MS);
                result["cacheScope"] = json!("public");
            }
            respond(send, &id, stateless, result);
        };
        match method {
            "server/discover" if stateless => list(json!({
                "supportedVersions": [STATELESS_VERSION],
                "capabilities": {"tools": {}},
                "instructions": instructions(self.short, self.settings.max_bytes),
                "_meta": {SERVER_INFO_KEY: {"name": "scrutate", "version": self.version}},
            })),
            "server/discover" => respond_err(send, &id, -32602, &format!("_meta has no {VERSION_KEY}"), None),
            "initialize" => {
                let latest = HANDSHAKE_VERSIONS[HANDSHAKE_VERSIONS.len() - 1];
                let asked = params.get("protocolVersion").and_then(|v| v.as_str()).unwrap_or(latest);
                let ver = if HANDSHAKE_VERSIONS.contains(&asked) { asked } else { latest };
                respond(
                    send,
                    &id,
                    false,
                    json!({
                        "protocolVersion": ver,
                        "capabilities": {"tools": {"listChanged": false}},
                        "serverInfo": {"name": "scrutate", "version": self.version},
                        "instructions": instructions(self.short, self.settings.max_bytes),
                    }),
                );
            }
            "ping" => respond(send, &id, stateless, json!({})),
            "tools/list" => list(json!({"tools": tools(self.structured, self.settings.max_bytes, self.short)})),
            "resources/list" => list(json!({"resources": []})),
            "resources/templates/list" => list(json!({"resourceTemplates": []})),
            "prompts/list" => list(json!({"prompts": []})),
            "tools/call" => {
                let Some(name) = params.get("name").and_then(Value::as_str) else {
                    return respond_err(send, &id, -32602, "tools/call has no params.name", None);
                };
                if !tool_table().as_array().into_iter().flatten().any(|t| t["name"] == name) {
                    return respond_err(send, &id, -32602, &format!("unknown tool: {name}"), None);
                }
                let call = Call {
                    name: name.to_string(),
                    args: params.get("arguments").cloned().unwrap_or(json!({})),
                    stateless,
                    structured: self.structured,
                    progress: params.get("_meta").and_then(|m| m.get("progressToken")).cloned().unwrap_or(Value::Null),
                    cancelled: self.calls.begin(&id),
                    id,
                };
                let (session, calls, settings) = (self.session, self.calls, self.settings);
                let run = move || run_call(send, session, calls, settings, call);
                if calls.map().len() > MAX_CALLS {
                    run();
                } else {
                    scope.spawn(run);
                }
            }
            _ => respond_err(send, &id, -32601, &format!("method not found: {method}"), None),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::session::Every;
    use std::time::Duration;

    /// A repository with one function, its session with the first build done, and the messages a
    /// call sends.
    fn fixture(name: &str) -> (std::path::PathBuf, Session, Mutex<Vec<Value>>) {
        let root = std::env::temp_dir().join(format!("scrutate_mcp_{name}_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(root.join("src/geo.py"), "def make_point():\n    return 1\n").unwrap();
        let session = Session::open(&root, Every::given(Some(0.0))).unwrap();
        session.build().unwrap();
        (root, session, Mutex::new(Vec::new()))
    }

    fn call(calls: &Calls, id: i64, progress: Value) -> Call {
        let id = json!(id);
        Call { name: "find_symbol".into(), args: json!({"name": "make_point"}), stateless: true, structured: true, progress, cancelled: calls.begin(&id), id }
    }

    #[test]
    fn a_cancelled_call_stops_the_reindex_it_runs() {
        let (root, session, _) = fixture("cancel_reindex");
        let settings = Settings::new(None);
        // what `notifications/cancelled` sets for the call in flight
        let called = call_tool(&session, "reindex", &json!({"force": true}), &settings, &Arc::new(AtomicBool::new(true)));
        assert!(called.is_error && called.text.contains("cancelled"), "{}", called.text);
        let called = call_tool(&session, "find_symbol", &json!({"name": "make_point"}), &settings, &Arc::default());
        assert!(called.text.contains("src/geo.py"), "the index is as it was: {}", called.text);
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn a_call_that_panics_is_a_tool_error_and_only_a_call_that_updates_clears_the_failed_first_build() {
        let (root, session, sent) = fixture("build_failed_reset");
        // the state a first build that panicked leaves
        session.build_failing_for_test();
        assert!(session.build_failed());
        let calls = Calls::default();
        let send = |m: Value| sent.lock().unwrap().push(m);
        let settings = Settings::new(None);
        // neither a call with a bad argument nor a read of a file by its path looks at the index
        let read = Call { name: "read_code".into(), args: json!({"path": "src/geo.py"}), ..call(&calls, 5, Value::Null) };
        let bad = Call { args: json!({"name": 7}), ..call(&calls, 6, Value::Null) };
        for c in [read, bad] {
            run_call(&send, &session, &calls, &settings, c);
            assert!(session.build_failed());
        }
        std::fs::write(root.join("src/geo.py"), "def make_point():\n    return 2\n").unwrap();
        run_call(&send, &session, &calls, &settings, call(&calls, 7, Value::Null));
        let sent = sent.lock().unwrap();
        assert_eq!((&sent[0]["result"]["isError"], &sent[1]["result"]["isError"], &sent[2]["result"]["isError"]), (&json!(false), &json!(true), &json!(false)));
        assert!(!session.build_failed());
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn a_call_with_a_progress_token_reports_while_the_index_is_built_and_then_answers() {
        let (root, session, sent) = fixture("progress");
        let calls = Calls::default();
        let send = |m: Value| sent.lock().unwrap().push(m);
        session.building();
        std::thread::scope(|s| {
            let job = s.spawn(|| run_call(&send, &session, &calls, &Settings::new(None), call(&calls, 7, json!("tok"))));
            std::thread::sleep(Duration::from_millis(2300));
            assert!(!job.is_finished(), "the call waits for the index as long as it reports progress");
            session.build().unwrap();
        });
        let sent = sent.lock().unwrap().clone();
        let (last, progress) = sent.split_last().unwrap();
        assert!(!progress.is_empty(), "{sent:?}");
        for p in progress {
            assert_eq!(p["method"], "notifications/progress");
            assert_eq!(p["params"]["progressToken"], "tok");
            assert!(p["params"]["progress"].as_u64().unwrap() >= PROGRESS_SECONDS);
        }
        assert_eq!(last["id"], 7);
        assert_eq!(last["result"]["resultType"], "complete");
        assert!(last["result"]["content"][0]["text"].as_str().unwrap().starts_with("src/geo.py:1-2"), "{last}");
        assert_eq!(last["result"]["structuredContent"]["result"][0]["id"], "src/geo.py:1-2");
        assert!(calls.map().is_empty());
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn a_cancelled_call_sends_nothing() {
        let (root, session, sent) = fixture("cancel");
        let calls = Calls::default();
        let send = |m: Value| sent.lock().unwrap().push(m);
        session.building();
        std::thread::scope(|s| {
            // waiting for the index: the notice ends the wait
            let waiting = call(&calls, 1, Value::Null);
            let job = s.spawn(|| run_call(&send, &session, &calls, &Settings::new(None), waiting));
            calls.cancel(&json!(1));
            job.join().unwrap();
            calls.cancel(&json!(99)); // a notice for a request that is not there is ignored
        });
        session.build().unwrap();
        // cancelled before its answer: the answer is dropped
        let done = call(&calls, 2, Value::Null);
        calls.cancel(&json!(2));
        run_call(&send, &session, &calls, &Settings::new(None), done);
        assert_eq!(*sent.lock().unwrap(), Vec::<Value>::new());
        assert!(calls.map().is_empty());
        let _ = std::fs::remove_dir_all(root);
    }
}

//! The model set: the vector model, the learned ranker and the feature list the ranker was fitted
//! on, with one revision. Each part loads on its first use, once per process, so an operation that
//! reads no vector and ranks nothing never unpacks either file. A ranker whose features are not
//! this engine's is an error when something ranks with it.

use std::path::{Path, PathBuf};
use std::sync::{Arc, OnceLock};

use anyhow::{anyhow, Result};

use crate::rank::TreeEnsemble;
use crate::semantic::SemanticModel;

/// The vector model the stored vectors are made with. Bump it with every change of the embedded
/// model (its signature changes then too): an index of a higher revision is refused, since its
/// vectors do not match the queries this binary encodes.
pub const REVISION: u32 = 1;

/// The ranking features, in the order the ranker reads them.
pub const FEATURES: [&str; 48] = [
    "lex_log",
    "lex_ratio",
    "lex_rank",
    "lex_z",
    "name_log",
    "name_ratio",
    "qual_log",
    "qual_ratio",
    "sig_log",
    "sig_ratio",
    "doc_log",
    "doc_ratio",
    "body_log",
    "body_ratio",
    "path_log",
    "path_ratio",
    "sem_a",
    "sem_b",
    "sem_mix",
    "sem_a_z",
    "sem_b_z",
    "sem_mix_z",
    "sem_rank",
    "exact_name",
    "exact_qual",
    "name_overlap",
    "name_cover",
    "name_same_set",
    "lit_hits",
    "lit_def",
    "k_function",
    "k_method",
    "k_class",
    "k_module",
    "k_other",
    "is_test",
    "log_nbody",
    "has_doc",
    "log_ndoc",
    "qual_depth",
    "is_private",
    "log_ncallers",
    "n_terms",
    "n_lits",
    "n_words",
    "has_ident",
    "file_frac",
    "exact_case",
];

static SEMANTIC_NPZ: &[u8] = include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../models/semantic.npz"));
static RANKER_NPZ: &[u8] = include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../models/ranker.npz"));
/// The signature of the bundled vector model, so no process hashes 14.6 MB; a test prints the new
/// value when the file changes (a hashing build dependency would rename the order file's symbols).
pub const BUNDLED_SIGNATURE: &str = "blake2b:17861b39b366298cebb1640cdbb7784e";

enum Source {
    Bundled,
    File(PathBuf),
}

impl Source {
    /// The bundled part, or the file a variable names; `none` or empty turns the part off.
    fn from_var(var: &str) -> Option<Source> {
        match std::env::var_os(var) {
            None => Some(Source::Bundled),
            Some(v) if v.is_empty() || v == "none" => None,
            Some(v) => Some(Source::File(PathBuf::from(v))),
        }
    }
}

struct Part<T> {
    source: Source,
    loaded: OnceLock<std::result::Result<T, String>>,
}

impl<T> Part<T> {
    fn new(source: Source) -> Part<T> {
        Part { source, loaded: OnceLock::new() }
    }

    fn get(&self, load: impl FnOnce(&Source) -> Result<T>) -> Result<&T> {
        self.loaded.get_or_init(|| load(&self.source).map_err(|e| format!("{e:#}"))).as_ref().map_err(|e| anyhow!("{e}"))
    }
}

pub struct ModelSet {
    semantic: Option<Part<SemanticModel>>,
    ranker: Option<Part<TreeEnsemble>>,
}

impl ModelSet {
    /// The bundled parts, or the files `SCRUTATE_SEMANTIC` and `SCRUTATE_RANKER` name (`none`
    /// turns a part off). Nothing is read here.
    pub fn from_env() -> Arc<ModelSet> {
        Arc::new(ModelSet { semantic: Source::from_var("SCRUTATE_SEMANTIC").map(Part::new), ranker: Source::from_var("SCRUTATE_RANKER").map(Part::new) })
    }

    /// No vector model and no ranker: lexical search and the linear blend.
    pub fn none() -> Arc<ModelSet> {
        Arc::new(ModelSet { semantic: None, ranker: None })
    }

    /// Whether the index keeps vectors, without loading the model.
    pub fn semantic_enabled(&self) -> bool {
        self.semantic.is_some()
    }

    /// The signature the index stores for its vectors (`none` without a vector model). A model
    /// named at run time is hashed once and the hash
    /// kept in `cache_dir` beside the file's size and times.
    pub fn signature(&self, cache_dir: &Path) -> Result<String> {
        match self.semantic.as_ref().map(|p| &p.source) {
            None => Ok("none".into()),
            Some(Source::Bundled) => Ok(BUNDLED_SIGNATURE.into()),
            Some(Source::File(path)) => cached_signature(path, &cache_dir.join("model.sig")),
        }
    }

    /// The vector model, loaded on the first call.
    pub fn semantic(&self) -> Result<Option<&SemanticModel>> {
        let Some(part) = &self.semantic else { return Ok(None) };
        part.get(|s| match s {
            Source::Bundled => SemanticModel::from_bytes(SEMANTIC_NPZ),
            Source::File(p) => SemanticModel::load(p),
        })
        .map(Some)
    }

    /// The ranker, loaded and checked against `FEATURES` on the first call.
    pub fn ranker(&self) -> Result<Option<&TreeEnsemble>> {
        let Some(part) = &self.ranker else { return Ok(None) };
        part.get(|s| {
            let (r, name) = match s {
                Source::Bundled => (TreeEnsemble::from_bytes(RANKER_NPZ)?, "the bundled ranker".to_string()),
                Source::File(p) => (TreeEnsemble::load(p)?, format!("ranker {}", p.display())),
            };
            fits(&r.feature_names).map_err(|why| anyhow!("{name} does not fit this scrutate: {why}; set SCRUTATE_RANKER=none to rank without it"))?;
            Ok(r)
        })
        .map(Some)
    }
}

/// Why a ranker fitted on `names` cannot score this engine's feature rows.
fn fits(names: &[String]) -> std::result::Result<(), String> {
    if let Some(i) = (0..names.len().min(FEATURES.len())).find(|&i| names[i] != FEATURES[i]) {
        return Err(format!("its feature {} is \"{}\" where this scrutate computes \"{}\"", i + 1, names[i], FEATURES[i]));
    }
    if names.len() != FEATURES.len() {
        return Err(format!("it reads {} features and this scrutate computes {}", names.len(), FEATURES.len()));
    }
    Ok(())
}

/// The signature of a model file: a hash of its bytes.
pub fn file_signature(bytes: &[u8]) -> String {
    use blake2::digest::{Update, VariableOutput};
    let mut h = blake2::Blake2bVar::new(16).expect("blake2b-128");
    h.update(bytes);
    let mut out = [0u8; 16];
    h.finalize_variable(&mut out).expect("blake2b finalize");
    format!("blake2b:{}", out.iter().map(|b| format!("{b:02x}")).collect::<String>())
}

/// The signature of the model file at `path`, from `cache` when its path, size and times match.
/// shortcut: on a system without a status change time (Windows), a file rewritten with its old size and modification time keeps its old signature
fn cached_signature(path: &Path, cache: &Path) -> Result<String> {
    let full = std::fs::canonicalize(path).map_err(|e| anyhow!("load semantic model {}: {e}", path.display()))?;
    let stat = crate::index::Stat::of(&std::fs::metadata(&full)?);
    let key = format!("{}\t{}\t{}\t{}", full.display(), stat.size, stat.mtime, stat.ctime);
    if let Some(sig) = std::fs::read_to_string(cache).ok().and_then(|t| t.strip_prefix(&format!("{key}\t")).map(|s| s.trim_end().to_string())) {
        return Ok(sig);
    }
    let sig = file_signature(&std::fs::read(&full).map_err(|e| anyhow!("load semantic model {}: {e}", path.display()))?);
    let _ = std::fs::write(cache, format!("{key}\t{sig}\n")); // a read-only index directory hashes again next time
    Ok(sig)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_bundled_signature_is_the_hash_of_the_bundled_model() {
        assert_eq!(BUNDLED_SIGNATURE, file_signature(SEMANTIC_NPZ));
    }

    #[test]
    fn the_bundled_ranker_fits() {
        assert!(fits(&TreeEnsemble::from_bytes(RANKER_NPZ).unwrap().feature_names).is_ok());
    }

    #[test]
    fn a_ranker_with_other_features_says_which() {
        let mut names: Vec<String> = FEATURES.iter().map(|s| s.to_string()).collect();
        names[0] = "Zex_log".into();
        assert_eq!(fits(&names).unwrap_err(), "its feature 1 is \"Zex_log\" where this scrutate computes \"lex_log\"");
        names[0] = "lex_log".into();
        names.pop();
        assert!(fits(&names).unwrap_err().contains("47 features"));
    }

    #[test]
    fn a_model_file_is_hashed_once_and_again_when_it_changes() {
        let dir = std::env::temp_dir().join(format!("scrutate_model_sig_{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let (model, cache) = (dir.join("m.npz"), dir.join("model.sig"));
        std::fs::write(&model, b"one").unwrap();
        assert_eq!(cached_signature(&model, &cache).unwrap(), file_signature(b"one"));
        assert!(std::fs::read_to_string(&cache).unwrap().ends_with(&format!("{}\n", file_signature(b"one"))));
        std::fs::write(&model, b"two!").unwrap();
        assert_eq!(cached_signature(&model, &cache).unwrap(), file_signature(b"two!"));
        let _ = std::fs::remove_dir_all(&dir);
    }
}

//! What a name refers to. Every question about a use of a name asks `Names`: callers, callees,
//! references, the language server's definition, imports and importers. The rules that decide
//! live in `resolve/`; this module owns who asks them, once per request, with each file read and
//! parsed once. What `callers` and `callees` learn of a call site is kept (`answers.rs`), so the
//! same request on the same index and files asks the rules nothing. The caller count ranking
//! reads is the index's (`Index::call_counts`).

use std::collections::{BTreeSet, HashMap, HashSet};
use std::path::Path;

use anyhow::Result;

use crate::answers::{Reading, Stored};
use crate::index::{ChunkRow, Symbol};
use crate::resolve::{join, Occurrence, Resolution, Resolved, Resolver};
use crate::search::{Hit, Searcher};

#[derive(Debug, Clone, serde::Serialize)]
pub struct Dependency {
    pub line: i64,
    pub module: String,
    /// repository file the module resolves to, when it can be found
    pub resolved: Option<String>,
}

/// (importing file, line, module as written)
pub type Importer = (String, i64, String);

/// One request's view of what the names of the repository refer to.
pub struct Names<'a> {
    s: &'a Searcher,
    rv: Resolver<'a>,
    /// by file: the byte each line starts at
    line_starts: HashMap<String, Vec<usize>>,
    /// the kept answers of the request running, and the ones it adds
    stored: Option<Stored>,
    _reading: Reading,
}

impl<'a> Names<'a> {
    pub fn new(s: &'a Searcher) -> Result<Names<'a>> {
        // started first: the store keeps what every read of the request saw
        let reading = Reading::start();
        Ok(Names { s, rv: Resolver::new(&s.ix)?, line_starts: HashMap::new(), stored: None, _reading: reading })
    }

    /// The definition the occurrence of `name` at 1-based `line`, 0-based byte `col` of `path`
    /// refers to and how that was found, or why none was.
    pub fn at(&mut self, path: &str, line: u64, col: usize, name: &str) -> Resolution {
        self.rv.resolve_at(path, line, col, name)
    }

    /// Every whole-word occurrence of `name` (Engine A), each resolved to the definition it refers to.
    pub fn references(&mut self, name: &str, max_results: u64) -> Result<Resolved> {
        let s = self.s;
        let bare = &crate::intel::bare_name(s, name)?;
        let q = crate::instant::Query { want_spans: true, ..crate::resolve::name_search(bare, max_results) };
        let walk = crate::files::repository_files(&s.ix.root);
        // the text index, when it holds the files as the last look found them, says which can match
        let files = crate::stores::grep_files(&s.ix, &q, &walk);
        let (found, mut truncated) = crate::intel::occurrences_in(&s.ix.root, files.as_ref().unwrap_or(&walk), &q, &s.cancel)?;
        let mut notes = Vec::new();
        let mut hits = Vec::new();
        for r in found {
            match r {
                crate::instant::Record::Match(l) => hits.push(l),
                crate::instant::Record::Note { path, text, .. } => notes.push((path.to_string(), text)),
                _ => {}
            }
        }
        let mut occurrences = Vec::new();
        // Engine A stops at `max_results` lines; one long line can hold more uses than that
        let total: usize = hits.iter().map(|h| h.spans.len()).sum();
        truncated |= total as u64 > max_results;
        for h in hits {
            let line_text: std::sync::Arc<str> = h.text.trim_end_matches(['\n', '\r']).into();
            for &(a, b) in h.spans.iter().take(max_results.saturating_sub(occurrences.len() as u64) as usize) {
                let ((da, db), col) = self.rv.decoded_span(&h.path, h.line, (a, b));
                // the occurrence as this file spells it
                let resolution = self.rv.resolve_at(&h.path, h.line, col, h.text.get(da..db).unwrap_or(bare));
                occurrences.push(Occurrence { path: h.path.to_string(), line: h.line, column: a as u64 + 1, text: line_text.clone(), at: da, resolution });
            }
        }
        let mut definitions: Vec<ChunkRow> = s.ix.definitions(bare)?.into_iter().filter(|d| crate::resolve::same_name(&d.name, bare)).collect();
        let mut known: HashSet<i64> = definitions.iter().map(|d| d.id).collect();
        for o in &occurrences {
            if let Ok((id, _)) = o.resolution {
                if known.insert(id) {
                    definitions.extend(s.ix.chunk(id)?);
                }
            }
        }
        let mut first_overload = HashMap::new();
        if occurrences.iter().any(|o| matches!(o.resolution, Ok((_, "overload")))) {
            for d in &definitions {
                if let [first, _, ..] = self.rv.overloads(d.id)[..] {
                    first_overload.insert(d.id, first);
                }
            }
        }
        Ok(Resolved { definitions, occurrences, truncated, notes, first_overload })
    }

    /// What the resolver makes of the occurrences of `name` in lines `start..=end` of `path`.
    fn uses(&mut self, path: &str, lines: (i64, i64), name: &str) -> Uses {
        let site = (path.to_string(), lines.0, lines.1, name.to_string());
        if let Some(u) = self.stored.as_mut().and_then(|st| st.get(&site)) {
            return u.clone();
        }
        let u = self.resolve_uses(path, lines, name);
        if let Some(st) = &mut self.stored {
            st.put(site, u.clone());
        }
        u
    }

    fn resolve_uses(&mut self, path: &str, (start, end): (i64, i64), name: &str) -> Uses {
        let fi = self.rv.file(path);
        let src = &fi.src;
        // a file of thousands of call sites is not walked from its top for each one
        let starts = self
            .line_starts
            .entry(path.to_string())
            .or_insert_with(|| std::iter::once(0).chain(src.bytes().enumerate().filter(|&(_, c)| c == b'\n').map(|(i, _)| i + 1)).collect());
        let first = (start.max(1) - 1) as usize;
        let from = starts.get(first).copied().unwrap_or(src.len());
        let ident = |c: Option<char>| c.is_some_and(|c| c.is_alphanumeric() || c == '_');
        let methods = crate::resolve::methods_only(path);
        let mut uses = Uses { got: HashSet::new(), dispatched: HashSet::new(), unsure: true, unsure_free: true, own_file: false };
        let (mut unsure, mut unsure_free, mut seen, mut elsewhere) = (false, false, false, false);
        for (i, line) in src[from..].lines().enumerate().map(|(i, l)| (i + first, l)).take((end - start + 1).max(0) as usize) {
            for (col, _) in line.match_indices(name) {
                if ident(line[..col].chars().next_back()) || ident(line[col + name.len()..].chars().next()) {
                    continue;
                }
                match self.rv.resolve_at(path, i as u64 + 1, col, name) {
                    // the name of a definition is not a call of it
                    Ok((_, "definition")) => {}
                    Ok((id, why)) => {
                        seen = true;
                        let all = if why == "overload" { self.rv.overloads(id) } else { vec![id] };
                        if why != "super" {
                            uses.dispatched.extend(&all);
                        }
                        // a use the arguments do not tie to one overload stands for all of them
                        uses.got.extend(all);
                    }
                    // an import from outside, a local, a field or a string is decided: not this definition
                    Err(why) => {
                        seen = true;
                        let unread = matches!(why, "no grammar" | crate::resolve::UNREAD | crate::resolve::TOO_DEEP);
                        if unread || matches!(why, "receiver" | "not found") {
                            unsure = true;
                            unsure_free |= !(methods && line[..col].trim_end().ends_with('.'));
                            let receiver = [".", "->", "::"].iter().any(|r| line[..col].trim_end().ends_with(r));
                            elsewhere |= receiver || !unread;
                        }
                    }
                }
            }
        }
        uses.unsure = unsure || !seen;
        uses.unsure_free = unsure_free || !seen;
        uses.own_file = unsure && !elsewhere;
        uses
    }

    /// The definitions whose code calls what `name` stands for, and how many of them were kept only
    /// because the resolver could not tell which same-named definition they call. Those come after
    /// the decided ones, first the ones whose code names the target's type, then the ones in its package.
    /// -> (callers: decided, then undecided; how many are undecided)
    pub fn callers(&mut self, name: &str, limit: usize) -> Result<(Vec<Hit>, usize)> {
        self.stored = Some(Stored::open(self.s, "callers", name, limit));
        let r = self.callers_kept(name, limit);
        if let (Some(st), Ok((_, _, complete))) = (self.stored.take(), &r) {
            st.save(self.s, limit, *complete);
        }
        r.map(|(out, undecided, _)| (out, undecided))
    }

    /// `callers`, and whether it went through every call site
    fn callers_kept(&mut self, name: &str, limit: usize) -> Result<(Vec<Hit>, usize, bool)> {
        let s = self.s;
        let langs = Langs { root: &s.ix.root, seen: Default::default() };
        let mut targets = crate::ops::targets(s, name, 500, false)?;
        // a call of a class runs its constructor: `Point(1)`, `new Widget()`, Ruby `Invoice.new`
        let (classes, made_by_new) = constructed(s, &langs, &targets)?;
        targets.extend(classes);
        let ids: HashSet<i64> = targets.iter().map(|t| t.id).collect();
        let mut names: BTreeSet<&str> = targets.iter().map(|t| t.name.as_str()).collect();
        if !made_by_new.is_empty() {
            names.insert("new");
        }
        let owners: HashSet<&str> =
            targets.iter().filter_map(|t| t.qualname.rsplit_once('.').map(|(o, _)| o.rsplit('.').next().unwrap_or(o))).filter(|o| !o.is_empty()).collect();
        let packages: HashSet<&str> = targets.iter().map(|t| package(&t.path)).collect();
        let fits = |path: &str| targets.iter().any(|t| langs.same_family(&t.path, path));
        let (mut out, mut unsure_rows, mut seen) = (Vec::new(), Vec::new(), HashSet::new());
        // a call of a method a target overrides or implements may run the target
        let overridden: HashSet<i64> = targets.iter().flat_map(|t| self.rv.overridden(t.id)).filter(|id| !ids.contains(id)).collect();
        let names_owner = |text: &str| owners.iter().any(|o| has_word(text, o));
        let likely = |r: &ChunkRow| (!names_owner(&r.text), !packages.contains(package(&r.path)), r.path.clone(), r.start);
        let all_free = |n: &str| targets.iter().filter(|t| t.name == n).all(|t| free(&t.kind, &t.qualname));
        for n in names {
            let rows: Vec<Symbol> = s.ix.named(n)?.into_iter().filter(|r| r.kind != "window").collect();
            // with another definition of the name about, the likeliest call sites are asked first
            let rivals = rows.iter().any(|r| !ids.contains(&r.id) && fits(&r.path));
            let mut sites = s.ix.callers_of(n)?;
            sites.retain(|r| fits(&r.path) && seen.insert(r.id));
            if n == "new" && !targets.iter().any(|t| t.name == "new") {
                sites.retain(|r| made_by_new.iter().any(|class| has_word(&r.text, &format!("{class}.new"))));
            }
            if rivals {
                sites.sort_by_cached_key(&likely);
            }
            for row in sites {
                let uses = self.uses(&row.path, (row.start, row.end), n);
                let unsure = (if all_free(n) { uses.unsure_free } else { uses.unsure }) || !uses.dispatched.is_disjoint(&overridden);
                if uses.got.is_disjoint(&ids) {
                    // with no other definition of the name, a call the resolver cannot place is this one's
                    if unsure && rivals {
                        let mine = |r: &&Symbol| own((&row.path, &row.qualname), &r.path, &r.kind, &r.qualname);
                        let mine: Vec<i64> = rows.iter().filter(|r| uses.own_file && mine(r)).map(|r| r.id).collect();
                        if mine.is_empty() {
                            unsure_rows.push(row);
                            continue;
                        }
                        if mine.iter().all(|id| !ids.contains(id)) {
                            continue;
                        }
                    } else if !unsure {
                        continue;
                    }
                }
                out.push(Hit::from_row(&row, true));
                if out.len() >= limit {
                    return Ok((out, 0, false));
                }
            }
        }
        unsure_rows.sort_by_cached_key(&likely);
        let undecided = unsure_rows.len().min(limit - out.len());
        out.extend(unsure_rows.iter().take(undecided).map(|r| Hit::from_row(r, true)));
        Ok((out, undecided, true))
    }

    /// The definitions whose code calls the name of `gone`, a definition the tree no longer has,
    /// where the resolver ties the call to no definition that exists: a namesake the call
    /// resolves to, a local or an import from outside takes it.
    pub fn callers_of_deleted(&mut self, gone: &Hit, limit: usize) -> Result<Vec<Hit>> {
        let s = self.s;
        let langs = Langs { root: &s.ix.root, seen: Default::default() };
        let is_free = free(&gone.kind, &gone.qualname);
        let mut out = Vec::new();
        for row in s.ix.callers_of(&gone.name)? {
            if !langs.same_family(&gone.path, &row.path) {
                continue;
            }
            let uses = self.uses(&row.path, (row.start, row.end), &gone.name);
            if uses.got.is_empty() && (if is_free { uses.unsure_free } else { uses.unsure }) {
                out.push(Hit::from_row(&row, true));
                if out.len() >= limit {
                    break;
                }
            }
        }
        Ok(out)
    }

    /// What the code of the definitions `name` stands for calls: definitions of the repository in
    /// the same language family, and the names it calls that have none.
    /// -> (resolved definitions, external names, the files of the definitions whose calls these are)
    pub fn callees(&mut self, name: &str, limit: usize) -> Result<(Vec<Hit>, Vec<String>, Vec<String>)> {
        // every call site is asked whatever the limit, which only cuts the list at the end
        self.stored = Some(Stored::open(self.s, "callees", name, 0));
        let r = self.callees_kept(name, limit);
        if let (Some(st), Ok(_)) = (self.stored.take(), &r) {
            st.save(self.s, 0, true);
        }
        r
    }

    fn callees_kept(&mut self, name: &str, limit: usize) -> Result<(Vec<Hit>, Vec<String>, Vec<String>)> {
        let s = self.s;
        let langs = Langs { root: &s.ix.root, seen: Default::default() };
        let (mut resolved, mut external, mut seen) = (Vec::new(), Vec::new(), HashSet::new());
        let defs = crate::ops::targets(s, name, 5, true)?;
        let from = defs.iter().map(|d| d.path.clone()).collect();
        for d in defs {
            for (n, picked, _) in self.calls(&d, &langs)? {
                if picked.is_empty() && !external.contains(&n) {
                    external.push(n);
                    continue;
                }
                resolved.extend(picked.into_iter().filter(|r| seen.insert(r.id)).map(|r| Hit::from_row(&r, true)));
            }
        }
        external.sort();
        resolved.truncate(limit);
        Ok((resolved, external, from))
    }

    /// What the code of definition `d` calls, name by name: the definitions of the repository each
    /// name reaches, none for a name that reaches none, and whether the resolver tied the calls to
    /// them (else they are the likeliest of the name's definitions).
    fn calls(&mut self, d: &Hit, langs: &Langs) -> Result<Vec<(String, Vec<ChunkRow>, bool)>> {
        let s = self.s;
        let kinds: Vec<&str> = crate::search::CODE_KINDS.iter().copied().chain(["key", "macro"]).collect();
        // a key is what a call runs only in the caller's own language (Nix, whose functions are keys)
        let callable = |from: &str, r: &ChunkRow| langs.same_family(from, &r.path) && (r.kind != "key" || langs.id(from) == langs.id(&r.path));
        let mut out = Vec::new();
        for n in s.ix.callees_of(d.id)? {
            let rows: Vec<ChunkRow> = s.ix.named_of_kinds(&n, &kinds)?.into_iter().filter(|r| callable(&d.path, r)).collect();
            if rows.is_empty() {
                out.push((n, Vec::new(), false));
                continue;
            }
            let uses = self.uses(&d.path, (d.start, d.end), &n);
            let tied: Vec<&ChunkRow> = rows.iter().filter(|r| uses.got.contains(&r.id)).collect();
            let is_tied = !tied.is_empty();
            let picked: Vec<&ChunkRow> = if is_tied {
                tied
            } else if uses.unsure {
                let mut near: Vec<&ChunkRow> = rows.iter().filter(|r| uses.unsure_free || !free(&r.kind, &r.qualname)).collect();
                let mine = |r: &&ChunkRow| own((&d.path, &d.qualname), &r.path, &r.kind, &r.qualname);
                if uses.own_file && near.iter().any(mine) {
                    near.retain(mine);
                }
                // the nearest three: the caller's file, then its directory
                let dir = |p: &str| p.rsplit_once('/').map_or(String::new(), |(d, _)| d.to_string());
                near.sort_by_key(|r| (r.path != d.path, dir(&r.path) != dir(&d.path)));
                near.truncate(3);
                near
            } else {
                Vec::new()
            };
            let picked = picked.into_iter().cloned().collect();
            out.push((n, picked, is_tied));
        }
        Ok(out)
    }

    /// The definitions under `under` (a directory or file, or all) that nothing in the repository
    /// uses: no line outside one names it (`dead`). One that some line names, none of which the
    /// resolver ties to it, is undecided, with why: a string, a comment, another definition of the
    /// name or a use the resolver cannot place may each still be a use. Entry points are neither.
    pub fn dead(&mut self, under: Option<&str>) -> Result<crate::dead::Dead> {
        self.stored = Some(Stored::open(self.s, "dead", under.unwrap_or(""), 0));
        let r = self.dead_kept(under);
        if let (Some(st), Ok(_)) = (self.stored.take(), &r) {
            st.save(self.s, 0, true);
        }
        r
    }

    fn dead_kept(&mut self, under: Option<&str>) -> Result<crate::dead::Dead> {
        let (candidates, too_large) = crate::dead::candidates(&self.s.ix, under)?;
        let mut out = crate::dead::Dead::default();
        for c in candidates {
            if c.named == 0 {
                match (c.base, too_large.first()) {
                    (Some(why), _) => out.undecided.push((c.sym, why)),
                    (None, Some(f)) => out.undecided.push((c.sym, format!("nothing else names it, but {f} is too large to read"))),
                    (None, None) => out.dead.push(c.sym),
                }
                continue;
            }
            let (mut used, mut other, mut unplaced) = (false, 0, 0);
            for (path, line) in &c.lines {
                let u = self.uses(path, (*line, *line), &c.sym.name);
                if u.got.contains(&c.sym.id) {
                    used = true;
                    break;
                }
                if u.unsure {
                    unplaced += 1;
                } else {
                    other += 1;
                }
            }
            if used {
                continue;
            }
            let n = c.named;
            let parts: Vec<String> = [
                (other, "tied to something else (another definition, a local, a comment or a string)"),
                (unplaced, "the resolver cannot place"),
                (c.unread, "in files the resolver does not read"),
                (n - c.unread - c.lines.len(), "not asked"),
            ]
            .iter()
            .filter(|(k, _)| *k > 0)
            .map(|(k, what)| format!("{k} {what}"))
            .collect();
            out.undecided.push((c.sym, format!("named on {n} other line{}: {}", if n == 1 { "" } else { "s" }, parts.join(", "))));
        }
        Ok(out)
    }

    /// The shortest chain of calls from the definition `from` names to the one `to` names, each
    /// call one that `callees` gives, at most `depth` calls long: over the calls the resolver ties
    /// first, and only when they give none, over every call `callees` lists. Ties go to the
    /// definition first by path and line, then to the call on the first line.
    pub fn path(&mut self, from: &str, to: &str, depth: usize) -> Result<CallPath> {
        let s = self.s;
        let (start, goal) = (one_definition(s, from)?, one_definition(s, to)?);
        let langs = Langs { root: &s.ix.root, seen: Default::default() };
        let mut known = HashMap::new();
        let mut walked = self.walk(&start, &goal, depth, true, &langs, &mut known)?;
        if walked.0.is_none() {
            walked = self.walk(&start, &goal, depth, false, &langs, &mut known)?;
        }
        let (steps, stopped) = walked;
        Ok(CallPath { found: steps.is_some(), steps: steps.unwrap_or_default(), from: start, to: goal, depth, stopped })
    }

    /// One breadth-first walk of `path`, through untied calls too unless `tied_only`.
    /// -> (the steps when it reached `goal`, whether `depth` stopped it with definitions left)
    #[allow(clippy::type_complexity)]
    fn walk(
        &mut self,
        start: &Hit,
        goal: &Hit,
        depth: usize,
        tied_only: bool,
        langs: &Langs,
        known: &mut HashMap<i64, Vec<(String, Vec<ChunkRow>, bool)>>,
    ) -> Result<(Option<Vec<Step>>, bool)> {
        let s = self.s;
        // each definition reached, and the call that reached it first
        let mut came: HashMap<i64, Option<(i64, Step)>> = HashMap::from([(start.id, None)]);
        let (mut level, mut taken, mut found) = (vec![start.clone()], 0, start.id == goal.id);
        while !found && !level.is_empty() && taken < depth {
            taken += 1;
            let mut next = Vec::new();
            for d in &level {
                if s.cancel.load(std::sync::atomic::Ordering::Relaxed) {
                    anyhow::bail!("cancelled");
                }
                if let std::collections::hash_map::Entry::Vacant(e) = known.entry(d.id) {
                    e.insert(self.calls(d, langs)?);
                }
                let mut edges = Vec::new();
                for (n, picked, tied) in &known[&d.id] {
                    for r in picked.iter().filter(|r| (*tied || !tied_only) && !came.contains_key(&r.id)) {
                        edges.push((self.call_line(&d.path, (d.start, d.end), n, r.id), r.clone(), *tied));
                    }
                }
                edges.sort_by(|a, b| (a.0, &a.1.path, a.1.start).cmp(&(b.0, &b.1.path, b.1.start)));
                for (line, r, tied) in edges {
                    if came.contains_key(&r.id) {
                        continue;
                    }
                    let to = Hit::from_row(&r, false);
                    found |= r.id == goal.id;
                    came.insert(r.id, Some((d.id, Step { path: d.path.clone(), line, to: to.clone(), tied })));
                    next.push(to);
                }
                if found {
                    break;
                }
            }
            next.sort_by(|a, b| (&a.path, a.start, a.end).cmp(&(&b.path, b.start, b.end)));
            level = next;
        }
        if !found {
            return Ok((None, taken == depth && !level.is_empty()));
        }
        let mut steps = Vec::new();
        let mut at = goal.id;
        while let Some(Some((parent, step))) = came.get(&at) {
            steps.push(step.clone());
            at = *parent;
        }
        steps.reverse();
        Ok((Some(steps), false))
    }

    /// The first line in `lines` of `path` where `name` is called and the resolver ties the call to
    /// definition `id`, else the first where `name` is called (a pick the resolver could not tie).
    fn call_line(&mut self, path: &str, (start, end): (i64, i64), name: &str, id: i64) -> i64 {
        let fi = self.rv.file(path);
        let ident = |c: Option<char>| c.is_some_and(|c| c.is_alphanumeric() || c == '_');
        let mut first = None;
        let first_line = start.max(1);
        for (i, line) in fi.src.lines().enumerate().skip(first_line as usize - 1).take((end - first_line + 1).max(0) as usize) {
            let n = i as i64 + 1;
            for (col, _) in line.match_indices(name) {
                if ident(line[..col].chars().next_back()) || ident(line[col + name.len()..].chars().next()) {
                    continue;
                }
                match self.rv.resolve_at(path, n as u64, col, name) {
                    Ok((_, "definition")) => continue,
                    Ok((got, why)) if got == id || (why == "overload" && self.rv.overloads(got).contains(&id)) => return n,
                    _ => {}
                }
                first.get_or_insert(n);
            }
        }
        first.unwrap_or(start)
    }

    /// The weighted edges between `files` (sorted) that the index's names give, without resolving
    /// a call site: a call of a name goes to every other file of the caller's language family
    /// that defines it, its weight split among them, unless the caller's own file defines it; an
    /// import goes to the file its module path maps onto. -> (from, to, weight) by index into `files`
    pub fn file_edges(&mut self, files: &[String]) -> Result<Vec<(usize, usize, f64)>> {
        let s = self.s;
        let langs = Langs { root: &s.ix.root, seen: Default::default() };
        let at = |p: &str| files.binary_search_by(|f| f.as_str().cmp(p)).ok();
        let kinds: Vec<&str> = crate::search::CODE_KINDS.iter().copied().chain(["macro"]).collect();
        let mut definers: HashMap<String, Vec<usize>> = HashMap::new();
        for (name, path) in s.ix.definers(&kinds)? {
            if let Some(i) = at(&path) {
                definers.entry(name).or_default().push(i);
            }
        }
        let fam: Vec<Option<&str>> = files.iter().map(|f| langs.id(f).map(family)).collect();
        let same = |a: usize, b: usize| fam[a].is_none() || fam[b].is_none() || fam[a] == fam[b];
        // by file, the files it calls into and imports, with their weights
        let mut out: Vec<HashMap<usize, f64>> = vec![HashMap::new(); files.len()];
        // rows come by path and name: the calls of one name from one file are counted together
        let calls = s.ix.call_edges()?;
        for run in calls.chunk_by(|a, b| a == b) {
            let (path, callee) = &run[0];
            let (Some(from), Some(defs)) = (at(path), definers.get(callee)) else { continue };
            if defs.contains(&from) {
                continue;
            }
            let to: Vec<usize> = defs.iter().copied().filter(|&t| same(from, t)).collect();
            for &t in &to {
                *out[from].entry(t).or_default() += run.len() as f64 / to.len() as f64;
            }
        }
        // a module is mapped once per directory it is imported from
        let mut mapped: HashMap<(String, String), Option<usize>> = HashMap::new();
        for (path, _, module) in s.ix.imports()? {
            let Some(from) = at(&path) else { continue };
            let dir = path.rsplit_once('/').map_or("", |(d, _)| d).to_string();
            let to =
                *mapped.entry((module, dir)).or_insert_with_key(|(module, _)| module_file(module, &path, self.rv.files(), &s.ix.root).and_then(|f| at(&f)));
            if let Some(to) = to.filter(|&t| t != from) {
                *out[from].entry(to).or_default() += 1.0;
            }
        }
        let mut edges = Vec::new();
        for (from, to) in out.into_iter().enumerate() {
            let mut to: Vec<(usize, f64)> = to.into_iter().collect();
            to.sort_by_key(|e| e.0);
            edges.extend(to.into_iter().map(|(t, w)| (from, t, w)));
        }
        Ok(edges)
    }

    /// Modules a file imports, resolved to repository files where the module path maps onto one.
    /// A statement naming several files (`from . import a, b`) is listed once per file.
    pub fn imports(&mut self, path: &str) -> Result<Vec<Dependency>> {
        let rows = self.s.ix.imports_of(path)?;
        let mut out = Vec::new();
        for (line, module) in rows {
            let mut found = self.import_files(&module, path, line);
            if path.ends_with(".go") && found.len() > 1 {
                // a Go import names a package directory: the file named after it stands for it
                let dir = found[0].rsplit_once('/').map_or("", |(d, _)| d);
                let named = format!("{}/{}.go", dir, dir.rsplit('/').next().unwrap_or(dir));
                let pick = found.iter().find(|f| **f == named).or_else(|| found.iter().find(|f| !f.ends_with("_test.go"))).unwrap_or(&found[0]).clone();
                found = vec![pick];
            }
            if found.is_empty() {
                out.push(Dependency { line, module: module.clone(), resolved: None });
            }
            out.extend(found.into_iter().map(|f| Dependency { line, module: module.clone(), resolved: Some(f) }));
        }
        for (line, name, file) in self.rv.rust_mods(path) {
            out.push(Dependency { line, module: name, resolved: file });
        }
        out.sort_by_key(|d| d.line);
        Ok(out)
    }

    /// The files one recorded import names: through the resolver `refs` uses for the languages it
    /// reads, else by mapping the module path onto the repository's files.
    fn import_files(&mut self, module: &str, from: &str, line: i64) -> Vec<String> {
        match self.rv.import_files(from, line, module) {
            Some(found) => found,
            None => module_file(module, from, self.rv.files(), &self.s.ix.root).into_iter().collect(),
        }
    }

    /// Files that import `target`: a module name as written, or a repository file (every file
    /// whose imports resolve to it, plus modules spelled like its path), and how many imports
    /// resolved to no file although they may import `target`: a relative one whose path is the
    /// target's, or a bare one that names the target's module.
    pub fn importers(&mut self, target: &str) -> Result<(Vec<Importer>, usize)> {
        let rows = self.s.ix.imports()?;
        let is_file = self.rv.files().contains(target);
        let stem = target.rsplit_once('.').map(|(s, _)| s).unwrap_or(target);
        let stem = stem.strip_suffix(".d").unwrap_or(stem);
        let dotted: String = stem.replace('/', ".");
        let dotted_pkg =
            dotted.strip_suffix(".__init__").or_else(|| dotted.strip_suffix(".index")).or_else(|| dotted.strip_suffix(".mod")).map(|s| s.to_string());
        // the last name of the module the file is: `a/b.py` -> `b`, `a/b/__init__.py` -> `b`
        let own = {
            let mut parts = stem.rsplit('/');
            let last = parts.next().unwrap_or(stem);
            if matches!(last, "__init__" | "index" | "mod" | "lib" | "main") {
                parts.next().unwrap_or(last)
            } else {
                last
            }
        };
        let target_dir = target.rsplit_once('/').map_or("", |(d, _)| d);
        let (mut out, mut unsure) = (Vec::new(), 0);
        let mut prev = String::new();
        for (path, line, module) in rows {
            // rows come by path: an importer is dropped once read, so memory does not grow with their number
            if path != prev {
                self.rv.forget(&prev);
                prev.clone_from(&path);
            }
            if path == target {
                continue;
            }
            let hit = if is_file {
                let found = self.import_files(&module, &path, line);
                let hit = found.iter().any(|f| f == target)
                    || module == dotted
                    || module.replace("::", ".") == dotted
                    || dotted_pkg.as_deref().map(|p| module == p || module.replace("::", ".") == p).unwrap_or(false)
                    // an include found through a search path the index does not know
                    || (found.is_empty() && module.rsplit('/').next() == Some(target.rsplit('/').next().unwrap_or(target)));
                let may_name = match relative_path(&module, &path).filter(|_| module.starts_with('.')) {
                    // a relative import names one path: the file without its extension, or its directory
                    Some(p) => p == stem || p == target || p == target_dir,
                    // a bare name in JavaScript or TypeScript that the resolver did not map is a package
                    None => {
                        !JS_EXTS.iter().any(|e| path.ends_with(e))
                            && module.split(|c: char| !(c.is_alphanumeric() || c == '_' || c == '-')).any(|seg| seg == own)
                    }
                };
                if !hit && found.is_empty() && may_name {
                    unsure += 1;
                }
                hit
            } else {
                module == target
                    || module.starts_with(&format!("{target}."))
                    || module.starts_with(&format!("{target}::"))
                    || module.starts_with(&format!("{target}/"))
                    || module.ends_with(&format!(".{target}"))
                    || module.ends_with(&format!("::{target}"))
                    || module.ends_with(&format!("/{target}"))
            };
            if hit {
                out.push((path, line, module));
            }
        }
        if is_file && target.ends_with(".rs") {
            for parent in self.rv.rust_mod_parents(target) {
                for (line, name, file) in self.rv.rust_mods(&parent) {
                    if file.as_deref() == Some(target) {
                        out.push((parent.clone(), line, name));
                    }
                }
            }
            out.sort();
            out.dedup();
        }
        Ok((out, unsure))
    }
}

/// A chain of calls between two definitions; `found` false: none within `depth` calls, and
/// `stopped`: the search stopped there with definitions left to follow.
#[derive(Clone, Debug)]
pub struct CallPath {
    pub from: Hit,
    pub to: Hit,
    pub steps: Vec<Step>,
    pub found: bool,
    pub depth: usize,
    pub stopped: bool,
}

/// One call of a chain: the call site, the definition it reaches, and whether the resolver tied
/// the call to it (else it is one of the likeliest definitions of the name, as `callees` lists).
#[derive(Clone, Debug)]
pub struct Step {
    pub path: String,
    pub line: i64,
    pub to: Hit,
    pub tied: bool,
}

/// The one definition `name` (a name or a location) stands for; several are an error that lists them.
fn one_definition(s: &Searcher, name: &str) -> Result<Hit> {
    const SHOWN: usize = 20;
    let mut found = crate::ops::targets(s, name, SHOWN + 1, false)?;
    // a file's module chunk takes the file's name: `def main` in main.py is the one meant
    if found.iter().any(|h| h.kind != "module") {
        found.retain(|h| h.kind != "module");
    }
    match found.len() {
        0 => anyhow::bail!("no definition of {}", crate::fmt::echo(name)),
        1 => Ok(found.remove(0)),
        n => {
            let count = if n > SHOWN { format!("more than {SHOWN}") } else { n.to_string() };
            found.truncate(SHOWN);
            let listed = crate::fmt::hit_blocks(&found, &[], false, false).join("\n  ");
            anyhow::bail!("{} names {count} definitions: pass one as a location (path:line)\n  {listed}", crate::fmt::echo(name))
        }
    }
}

/// Languages whose code calls each other's definitions directly.
fn family(id: &'static str) -> &'static str {
    match id {
        "javascript" | "typescript" | "tsx" => "js",
        "c" | "cpp" | "cuda" | "objc" => "c",
        "java" | "kotlin" | "scala" | "groovy" => "jvm",
        "erlang" | "elixir" | "gleam" => "beam",
        "ocaml" | "ocaml_interface" => "ocaml",
        "csharp" | "fsharp" => "dotnet",
        id => id,
    }
}

/// The language of each file an answer asks about, by its text where the extension names two.
struct Langs<'a> {
    root: &'a Path,
    seen: std::cell::RefCell<HashMap<String, Option<&'static str>>>,
}

impl Langs<'_> {
    fn id(&self, path: &str) -> Option<&'static str> {
        if let Some(id) = self.seen.borrow().get(path) {
            return *id;
        }
        let lower = path.to_lowercase();
        let shared = crate::langs::BY_CONTENT.iter().any(|(e, _)| lower.ends_with(e));
        let text = shared.then(|| crate::resolve::repo_text(self.root, path)).flatten();
        let id = crate::langs::detect(path, text.as_deref()).map(|s| s.id);
        self.seen.borrow_mut().insert(path.to_string(), id);
        id
    }

    /// A file of no known language may call or be called by any.
    fn same_family(&self, a: &str, b: &str) -> bool {
        match (self.id(a), self.id(b)) {
            (Some(x), Some(y)) => family(x) == family(y),
            _ => true,
        }
    }
}

/// What the resolver makes of the occurrences of a name in some lines of a file.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct Uses {
    /// the definitions they resolve to
    pub(crate) got: HashSet<i64>,
    /// the ones of `got` a call reaches other than through `super`, where an override may run instead
    pub(crate) dispatched: HashSet<i64>,
    /// one stayed unresolved (or none was found)
    pub(crate) unsure: bool,
    /// one stayed unresolved that may call a free function: not `x.name(..)` where a method
    /// call never reaches a free function
    pub(crate) unsure_free: bool,
    /// every unresolved one is a call without a receiver in a language the resolver does not
    /// read: it runs the definition in its own file when there is one (`own`)
    pub(crate) own_file: bool,
}

/// Whether the definition (`path`, `kind`, `qualname`) is what a call without a receiver in the
/// caller (its path and qualified name) runs: a free function of the caller's file, or a method
/// of the caller's own type.
fn own((from, caller): (&str, &str), path: &str, kind: &str, qualname: &str) -> bool {
    let owner = |q: &str| q.rsplit_once('.').map(|(o, _)| o.to_string());
    path == from && (free(kind, qualname) || owner(qualname) == owner(caller))
}

/// A definition outside any class or type: `x.f()` does not call it where `methods_only` holds.
/// A method of an object literal has no owner in its name and is still called through one.
fn free(kind: &str, qualname: &str) -> bool {
    kind != "method" && !qualname.contains('.')
}

/// The directory a file's package starts at: what comes before its `src/`, else its top directory.
fn package(path: &str) -> &str {
    match path.strip_prefix("src/").map(|_| 0).or_else(|| path.find("/src/")) {
        Some(i) => &path[..i],
        None => path.split_once('/').map_or("", |(top, _)| top),
    }
}

/// Whether `word` is in `text` where it is not part of a longer identifier.
fn has_word(text: &str, word: &str) -> bool {
    let ident = |c: Option<char>| c.is_some_and(|c| c.is_alphanumeric() || c == '_');
    text.match_indices(word).any(|(i, _)| !ident(text[..i].chars().next_back()) && !ident(text[i + word.len()..].chars().next()))
}

/// The classes whose constructor is among `targets`, and the names of the Ruby ones, which a
/// call of `new` on the class makes.
fn constructed(s: &Searcher, langs: &Langs, targets: &[Hit]) -> Result<(Vec<Hit>, Vec<String>)> {
    let (mut classes, mut made_by_new) = (Vec::<Hit>::new(), Vec::new());
    for t in targets {
        let Some((owner, name)) = t.qualname.rsplit_once('.') else { continue };
        let lang = langs.id(&t.path).unwrap_or("");
        let constructor = match lang {
            "python" => name == "__init__",
            "javascript" | "typescript" | "tsx" => name == "constructor",
            "ruby" => name == "initialize",
            "php" => name == "__construct",
            "swift" => name == "init",
            // Java, C#, C++, Dart: the method named as its class
            _ => name == owner.rsplit('.').next().unwrap_or(owner),
        };
        if !constructor {
            continue;
        }
        let class = s.ix.class_at(&t.path, owner)?;
        let Some(class) = class.filter(|c| !targets.iter().chain(&classes).any(|x| x.id == c.id)) else { continue };
        if lang == "ruby" {
            made_by_new.push(class.name.clone());
        }
        classes.push(Hit::from_row(&class, true));
    }
    Ok((classes, made_by_new))
}

const SOURCE_EXTS: &[&str] = &[
    ".py", ".js", ".mjs", ".cjs", ".jsx", ".ts", ".tsx", ".go", ".rs", ".java", ".rb", ".php", ".kt", ".swift", ".scala", ".dart", ".ex", ".exs", ".hs",
    ".lua", ".c", ".h", ".cc", ".cpp", ".hpp", ".cs", ".jl", ".r", ".R", ".sh", ".zig", ".elm",
];

const JS_EXTS: &[&str] = &[".js", ".mjs", ".cjs", ".jsx", ".ts", ".mts", ".cts", ".tsx"];

/// The repository path a relative import of `from` names before an extension or an index file
/// is tried (`./x`, `../x`, Python's `.x`, `..pkg.mod` and `.`); None for any other module.
fn relative_path(module: &str, from: &str) -> Option<String> {
    let dir = from.rsplit_once('/').map(|(d, _)| d).unwrap_or("");
    if module.starts_with("./") || module.starts_with("../") {
        Some(join(dir, module))
    } else if module.starts_with('.') {
        Some(crate::resolve::py_relative(from, module))
    } else {
        None
    }
}

/// For the languages the resolver does not read: a best-effort mapping of an import string onto a
/// file of the repository. Handles dotted/`::`-separated module paths, relative paths (`./x`,
/// `../x`, `from . import`), `crate::` roots and index files.
fn module_file(module: &str, from: &str, files: &HashSet<String>, root: &Path) -> Option<String> {
    let dir = from.rsplit_once('/').map(|(d, _)| d).unwrap_or("");
    let mut candidates: Vec<String> = Vec::new();
    if let Some(path) = relative_path(module, from) {
        candidates.push(path);
    } else {
        let m = module.strip_prefix("crate::").map(|m| format!("src/{m}")).unwrap_or_else(|| module.to_string());
        let slashed = m.replace("::", "/").replace('.', "/");
        candidates.push(slashed.clone());
        // java-style: the last segment may be a class inside the file of the previous segment
        if let Some((head, _)) = slashed.rsplit_once('/') {
            candidates.push(head.to_string());
        }
        // same directory first (C includes, sibling modules)
        if !dir.is_empty() {
            candidates.insert(0, join(dir, &slashed));
            candidates.insert(0, join(dir, &m));
        }
        candidates.push(m);
    }
    let try_one = |c: &str| -> Option<String> {
        let c = c.trim_matches('/');
        if files.contains(c) {
            return Some(c.to_string());
        }
        for ext in SOURCE_EXTS {
            let p = format!("{c}{ext}");
            if files.contains(&p) {
                return Some(p);
            }
        }
        for idx in ["__init__.py", "index.js", "index.ts", "index.tsx", "mod.rs", "lib.rs", "index.mjs"] {
            let p = if c.is_empty() { idx.to_string() } else { format!("{c}/{idx}") };
            if files.contains(&p) {
                return Some(p);
            }
        }
        None
    };
    for c in &candidates {
        if let Some(p) = try_one(c) {
            return Some(p);
        }
    }
    if module.starts_with('.') {
        return None;
    }
    let slashed = module.replace("::", "/").replace('.', "/");
    let segs: Vec<&str> = slashed.split('/').filter(|s| !s.is_empty()).collect();
    crate::resolve::below_own_package(root, &segs).and_then(|rest| try_one(&rest.join("/")))
}

//! Minimal reader/writer for NumPy `.npy` files (memory-mapped or in memory) and `.npz` archives.
//!
//! The segments and the model files are in numpy's own layout, so the training scripts read and
//! write them as they are. Only the dtypes the
//! engine uses are supported: i64, i32, u64, u32, u8, i8, f32, f64, f16, bool and fixed-width unicode strings.

use std::fs::File;
use std::io::{Read, Write};
use std::path::Path;

use anyhow::{anyhow, bail, Context, Result};
use half::f16;
use memmap2::Mmap;

const MAGIC: &[u8] = b"\x93NUMPY";
const ALIGN: usize = 64;

#[cfg(not(target_endian = "little"))]
compile_error!("the on-disk format is little-endian; big-endian targets are not supported");

enum Backing {
    Mmap(Mmap),
    Owned(Vec<u8>),
}

pub struct Npy {
    pub descr: String,
    pub shape: Vec<usize>,
    pub fortran: bool, // column-major data (only accepted for in-memory arrays; see to_vec)
    offset: usize,
    backing: Backing,
}

/// Plain-old-data element types that can be viewed directly in the file bytes.
///
/// # Safety
/// Implementors must be `repr(C)`/primitive types for which every bit pattern of `size_of::<Self>()`
/// bytes is a valid value, and `DESCR` must list exactly the numpy dtype strings of that layout.
pub unsafe trait Pod: Copy + 'static {
    const DESCR: &'static [&'static str];
}
unsafe impl Pod for i64 {
    const DESCR: &'static [&'static str] = &["<i8"];
}
unsafe impl Pod for i32 {
    const DESCR: &'static [&'static str] = &["<i4"];
}
unsafe impl Pod for u32 {
    const DESCR: &'static [&'static str] = &["<u4"];
}
unsafe impl Pod for u64 {
    const DESCR: &'static [&'static str] = &["<u8"];
}
unsafe impl Pod for u8 {
    const DESCR: &'static [&'static str] = &["|u1"];
}
unsafe impl Pod for i8 {
    const DESCR: &'static [&'static str] = &["|i1"];
}
unsafe impl Pod for f32 {
    const DESCR: &'static [&'static str] = &["<f4"];
}
unsafe impl Pod for f64 {
    const DESCR: &'static [&'static str] = &["<f8"];
}
unsafe impl Pod for f16 {
    const DESCR: &'static [&'static str] = &["<f2"];
}

fn parse_header(bytes: &[u8]) -> Result<(String, Vec<usize>, bool, usize)> {
    if bytes.len() < 10 || &bytes[..6] != MAGIC {
        bail!("not an .npy file");
    }
    let (major, minor) = (bytes[6], bytes[7]);
    let (hlen, start) = match major {
        1 => (u16::from_le_bytes([bytes[8], bytes[9]]) as usize, 10usize),
        2 | 3 => {
            if bytes.len() < 12 {
                bail!("truncated .npy header");
            }
            (u32::from_le_bytes([bytes[8], bytes[9], bytes[10], bytes[11]]) as usize, 12usize)
        }
        _ => bail!("unsupported .npy version {major}.{minor}"),
    };
    let end = start + hlen;
    if bytes.len() < end {
        bail!("truncated .npy header");
    }
    let header = std::str::from_utf8(&bytes[start..end]).context("header is not utf8")?;
    let descr = extract(header, "'descr'").ok_or_else(|| anyhow!("no descr in header"))?;
    let descr = descr.trim().trim_matches(|c| c == '\'' || c == '"').to_string();
    let fortran = extract(header, "'fortran_order'").map(|v| v.trim() == "True").unwrap_or(false);
    let shape_s = extract(header, "'shape'").ok_or_else(|| anyhow!("no shape in header"))?;
    let shape_s = shape_s.trim().trim_start_matches('(').trim_end_matches(')');
    let shape: Vec<usize> = shape_s
        .split(',')
        .map(|s| s.trim())
        .filter(|s| !s.is_empty())
        .map(|s| s.parse::<usize>().map_err(|e| anyhow!("bad shape {s}: {e}")))
        .collect::<Result<_>>()?;
    Ok((descr, shape, fortran, end))
}

/// Value text after `key:` up to the next top-level comma (shapes contain their own commas).
fn extract(header: &str, key: &str) -> Option<String> {
    let i = header.find(key)? + key.len();
    let rest = &header[i..];
    let rest = &rest[rest.find(':')? + 1..];
    let mut depth = 0i32;
    let mut out = String::new();
    for c in rest.chars() {
        match c {
            '(' | '[' => {
                depth += 1;
                out.push(c);
            }
            ')' | ']' => {
                depth -= 1;
                out.push(c);
            }
            ',' | '}' if depth <= 0 => break,
            _ => out.push(c),
        }
    }
    Some(out)
}

impl Npy {
    pub fn open(path: &Path) -> Result<Npy> {
        let file = File::open(path).with_context(|| format!("open {}", path.display()))?;
        let mmap = unsafe { Mmap::map(&file) }.with_context(|| format!("mmap {}", path.display()))?;
        let (descr, shape, fortran, offset) = parse_header(&mmap)?;
        if fortran {
            bail!("fortran-ordered arrays cannot be memory-mapped: {}", path.display());
        }
        Ok(Npy { descr, shape, fortran, offset, backing: Backing::Mmap(mmap) })
    }

    pub fn from_bytes(bytes: Vec<u8>) -> Result<Npy> {
        let (descr, shape, fortran, offset) = parse_header(&bytes)?;
        if fortran && shape.len() > 2 {
            bail!("fortran-ordered arrays with more than two dimensions are not supported");
        }
        Ok(Npy { descr, shape, fortran, offset, backing: Backing::Owned(bytes) })
    }

    /// Number of elements; a shape whose product overflows (a damaged header) saturates, so every
    /// size check against the data fails instead of wrapping.
    pub fn len(&self) -> usize {
        self.shape.iter().try_fold(1usize, |a, &d| a.checked_mul(d)).unwrap_or(usize::MAX)
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    fn bytes(&self) -> &[u8] {
        let all = match &self.backing {
            Backing::Mmap(m) => &m[..],
            Backing::Owned(v) => &v[..],
        };
        &all[self.offset..]
    }

    /// Zero-copy typed view (file data is 64-byte aligned, so this is always sound for mmaps).
    pub fn view<T: Pod>(&self) -> Result<&[T]> {
        if !T::DESCR.contains(&self.descr.as_str()) {
            bail!("dtype {} does not match requested type", self.descr);
        }
        if self.fortran {
            bail!("fortran-ordered array cannot be viewed in place");
        }
        let n = self.len();
        let bytes = self.bytes();
        let need = n.saturating_mul(std::mem::size_of::<T>());
        if bytes.len() < need {
            bail!("array data truncated");
        }
        let ptr = bytes.as_ptr();
        if !(ptr as usize).is_multiple_of(std::mem::align_of::<T>()) {
            bail!("unaligned array data");
        }
        Ok(unsafe { std::slice::from_raw_parts(ptr as *const T, n) })
    }

    /// Owned copy in row-major order (works for unaligned in-memory buffers and Fortran-ordered 2-D arrays).
    pub fn to_vec<T: Pod>(&self) -> Result<Vec<T>> {
        if !T::DESCR.contains(&self.descr.as_str()) {
            bail!("dtype {} does not match requested type", self.descr);
        }
        let n = self.len();
        let size = std::mem::size_of::<T>();
        let bytes = self.bytes();
        if bytes.len() < n.saturating_mul(size) {
            bail!("array data truncated");
        }
        let mut out: Vec<T> = Vec::with_capacity(n);
        unsafe {
            std::ptr::copy_nonoverlapping(bytes.as_ptr(), out.as_mut_ptr() as *mut u8, n * size);
            out.set_len(n);
        }
        if self.fortran && self.shape.len() == 2 {
            let (rows, cols) = (self.shape[0], self.shape[1]);
            let mut t: Vec<T> = Vec::with_capacity(n);
            for r in 0..rows {
                for c in 0..cols {
                    t.push(out[c * rows + r]); // column-major (r, c) lives at c * rows + r
                }
            }
            return Ok(t);
        }
        Ok(out)
    }

    /// Fixed-width little-endian UCS-4 strings (`<U{n}`), zero padding stripped.
    pub fn to_strings(&self) -> Result<Vec<String>> {
        let width: usize = self.descr.strip_prefix("<U").and_then(|w| w.parse().ok()).ok_or_else(|| anyhow!("not a unicode array: {}", self.descr))?;
        let n = self.len();
        let bytes = self.bytes();
        if n.checked_mul(width).and_then(|x| x.checked_mul(4)).is_none_or(|need| bytes.len() < need) {
            bail!("string array data truncated");
        }
        if width == 0 && n > 0 {
            // zero-width strings take no bytes, so the shape alone would size the allocation
            bail!("zero-width string array");
        }
        let mut out = Vec::with_capacity(n);
        for i in 0..n {
            let mut s = String::new();
            for j in 0..width {
                let p = (i * width + j) * 4;
                let cp = u32::from_le_bytes([bytes[p], bytes[p + 1], bytes[p + 2], bytes[p + 3]]);
                if cp == 0 {
                    break;
                }
                s.push(char::from_u32(cp).unwrap_or('\u{fffd}'));
            }
            out.push(s);
        }
        Ok(out)
    }

    pub fn is_bool(&self) -> bool {
        self.descr == "|b1"
    }
}

fn header_bytes(descr: &str, shape: &[usize]) -> Vec<u8> {
    let shape_s = match shape.len() {
        0 => "()".to_string(),
        1 => format!("({},)", shape[0]),
        _ => format!("({})", shape.iter().map(|s| s.to_string()).collect::<Vec<_>>().join(", ")),
    };
    let mut dict = format!("{{'descr': '{descr}', 'fortran_order': False, 'shape': {shape_s}, }}");
    let base = 10 + dict.len() + 1;
    let pad = (ALIGN - base % ALIGN) % ALIGN;
    dict.push_str(&" ".repeat(pad));
    dict.push('\n');
    let mut out = Vec::with_capacity(10 + dict.len());
    out.extend_from_slice(MAGIC);
    out.extend_from_slice(&[1, 0]);
    out.extend_from_slice(&(dict.len() as u16).to_le_bytes());
    out.extend_from_slice(dict.as_bytes());
    out
}

pub fn save<T: Pod>(path: &Path, data: &[T], shape: &[usize]) -> Result<()> {
    debug_assert_eq!(shape.iter().product::<usize>(), data.len());
    let mut f = File::create(path).with_context(|| format!("create {}", path.display()))?;
    f.write_all(&header_bytes(T::DESCR[0], shape))?;
    let bytes = unsafe { std::slice::from_raw_parts(data.as_ptr() as *const u8, std::mem::size_of_val(data)) };
    f.write_all(bytes)?;
    Ok(())
}

/// Arrays of an `.npz` archive, by entry name (without the `.npy`).
pub fn load_npz(path: &Path) -> Result<Vec<(String, Npy)>> {
    let bytes = std::fs::read(path).with_context(|| format!("open {}", path.display()))?;
    load_npz_bytes(&bytes).with_context(|| format!("read zip {}", path.display()))
}

pub fn load_npz_bytes(bytes: &[u8]) -> Result<Vec<(String, Npy)>> {
    let mut out = Vec::new();
    for (name, data) in zip_entries(bytes)? {
        out.push((name.trim_end_matches(".npy").to_string(), Npy::from_bytes(data)?));
    }
    Ok(out)
}

/// Minimal ZIP reader for `.npz` archives (what `numpy.savez` / `savez_compressed` write): entries
/// are read from the central directory and are either stored or deflated. Nothing is ever written
/// to disk, no file names are interpreted as paths, and ZIP64 or encrypted archives are rejected.
fn zip_entries(bytes: &[u8]) -> Result<Vec<(String, Vec<u8>)>> {
    let u16_at = |i: usize| -> Result<usize> { bytes.get(i..i + 2).map(|b| u16::from_le_bytes([b[0], b[1]]) as usize).ok_or_else(|| anyhow!("truncated zip")) };
    let u32_at = |i: usize| -> Result<usize> {
        bytes.get(i..i + 4).map(|b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]) as usize).ok_or_else(|| anyhow!("truncated zip"))
    };
    // end of central directory record: signature 0x06054b50, searched backwards over the comment
    let min_eocd = 22;
    if bytes.len() < min_eocd {
        bail!("not a zip archive");
    }
    let mut eocd = None;
    let lo = bytes.len().saturating_sub(min_eocd + 65_535);
    let mut i = bytes.len() - min_eocd;
    loop {
        if &bytes[i..i + 4] == b"PK\x05\x06" {
            eocd = Some(i);
            break;
        }
        if i == lo {
            break;
        }
        i -= 1;
    }
    let eocd = eocd.ok_or_else(|| anyhow!("zip: no end-of-central-directory record"))?;
    let entries = u16_at(eocd + 10)?;
    let cd_size = u32_at(eocd + 12)?;
    let cd_off = u32_at(eocd + 16)?;
    if entries == 0xFFFF || cd_size == 0xFFFF_FFFF || cd_off == 0xFFFF_FFFF {
        bail!("zip64 archives are not supported");
    }
    let mut out = Vec::with_capacity(entries);
    let mut p = cd_off;
    for _ in 0..entries {
        if u32_at(p)? != 0x0201_4b50 {
            bail!("zip: bad central directory entry");
        }
        let flags = u16_at(p + 8)?;
        let method = u16_at(p + 10)?;
        let csize = u32_at(p + 20)?;
        let usize_ = u32_at(p + 24)?;
        let name_len = u16_at(p + 28)?;
        let extra_len = u16_at(p + 30)?;
        let comment_len = u16_at(p + 32)?;
        let local = u32_at(p + 42)?;
        let name = String::from_utf8_lossy(bytes.get(p + 46..p + 46 + name_len).ok_or_else(|| anyhow!("truncated zip"))?).into_owned();
        if flags & 0x1 != 0 {
            bail!("zip: encrypted entry {name}");
        }
        // local header: signature, then the name and extra field lengths at 26 and 28
        if u32_at(local)? != 0x0403_4b50 {
            bail!("zip: bad local header for {name}");
        }
        let lname = u16_at(local + 26)?;
        let lextra = u16_at(local + 28)?;
        let start = local + 30 + lname + lextra;
        let comp = bytes.get(start..start + csize).ok_or_else(|| anyhow!("zip: truncated data for {name}"))?;
        let data = match method {
            0 => comp.to_vec(),
            8 => {
                let mut d = Vec::with_capacity(usize_);
                flate2::read::DeflateDecoder::new(comp).read_to_end(&mut d).with_context(|| format!("zip: inflate {name}"))?;
                d
            }
            m => bail!("zip: unsupported compression method {m} for {name}"),
        };
        if data.len() != usize_ {
            bail!("zip: size mismatch for {name}");
        }
        out.push((name, data));
        p += 46 + name_len + extra_len + comment_len;
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn roundtrip_matches_numpy_layout() {
        let dir = std::env::temp_dir().join(format!("npy_test_{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let p = dir.join("a.npy");
        let data: Vec<i64> = (0..10).collect();
        save(&p, &data, &[10]).unwrap();
        let bytes = std::fs::read(&p).unwrap();
        assert_eq!(&bytes[..6], MAGIC);
        assert_eq!(bytes.len() % 64, 80 % 64); // 64-byte header + 80 data bytes
        let n = Npy::open(&p).unwrap();
        assert_eq!(n.shape, vec![10]);
        assert_eq!(n.view::<i64>().unwrap(), &data[..]);
        let p2 = dir.join("b.npy");
        let f: Vec<f16> = vec![f16::from_f32(1.5); 6];
        save(&p2, &f, &[3, 2]).unwrap();
        let m = Npy::open(&p2).unwrap();
        assert_eq!(m.shape, vec![3, 2]);
        assert_eq!(m.view::<f16>().unwrap()[5].to_f32(), 1.5);
        let p3 = dir.join("e.npy");
        save::<i32>(&p3, &[], &[0]).unwrap();
        assert_eq!(Npy::open(&p3).unwrap().view::<i32>().unwrap().len(), 0);
        std::fs::remove_dir_all(&dir).unwrap();
    }
}

#[cfg(test)]
mod header_tests {
    use super::*;

    #[test]
    fn parses_numpy_headers() {
        let h = "{'descr': '<f2', 'fortran_order': False, 'shape': (11127, 256), }      \n";
        assert_eq!(extract(h, "'descr'").unwrap().trim(), "'<f2'");
        assert_eq!(extract(h, "'fortran_order'").unwrap().trim(), "False");
        assert_eq!(extract(h, "'shape'").unwrap().trim(), "(11127, 256)");
        let h2 = "{'descr': '<U102', 'fortran_order': False, 'shape': (), }\n";
        assert_eq!(extract(h2, "'shape'").unwrap().trim(), "()");
    }

    #[test]
    fn damaged_headers_are_errors_not_panics() {
        // found by fuzzing: a string array shorter than its shape claims
        let mut bytes = header_bytes("<U13", &[47]);
        bytes.extend_from_slice(&[0u8; 88]);
        assert!(Npy::from_bytes(bytes).unwrap().to_strings().is_err());
        // a shape whose element count overflows must not wrap into a small one
        let mut bytes = header_bytes("<i8", &[1 << 62, 8]);
        bytes.extend_from_slice(&[0u8; 64]);
        let a = Npy::from_bytes(bytes).unwrap();
        assert_eq!(a.len(), usize::MAX);
        assert!(a.view::<i64>().is_err() && a.to_vec::<i64>().is_err());
        // zero-width strings with a huge shape: an error, not an allocation of the shape's size
        let mut bytes = header_bytes("<U0", &[1 << 40]);
        bytes.extend_from_slice(&[0u8; 8]);
        assert!(Npy::from_bytes(bytes).unwrap().to_strings().is_err());
    }
}

//! Every question a front end can ask of the index: its arguments with their defaults and limits,
//! when the index is refreshed first, and a typed answer with one text form and one JSON form.
//! The CLI, the MCP server, `batch`, the Python bindings and the language server parse into `Op`
//! and render `Answer`; none of them holds a default, a limit or an output format of its own.

use anyhow::{anyhow, bail, Result};
use serde_json::{json, Value};

use crate::fmt::{hit_blocks, hits_json};
use crate::index::{ChunkRow, UpdateStats};
use crate::intel::{Capture, DupGroup, RefGroup, References};
use crate::names::{Dependency, Names};

use crate::fmt::{echo, shown};
use crate::instant::{Case, Files, Mode, Pattern};
use crate::resolve::Resolved;
use crate::search::{Hit, Searcher};
use crate::text::query_words;

/// Version of Engine A's JSON Lines and of the error records.
pub const SCHEMA: u32 = 1;
/// Version of the one JSON envelope every answer leaves in (`Answer::envelope`): the CLI's
/// `--json` of an index command, a `batch` record and the MCP server's structured result.
pub const ANSWER_SCHEMA: u32 = 2;

pub const SEARCH_K: usize = 8;
/// Alternative phrasings one search fuses at most: each costs a full search, and fusion gains
/// little past a handful.
pub const ALT_QUERIES: usize = 10;
pub const SYMBOL_LIMIT: usize = 20;
pub const CALLERS_LIMIT: usize = 30;
pub const CALLEES_LIMIT: usize = 40;
/// Names of callees outside the repository that an answer lists.
pub const EXTERNAL_CALLEES: usize = 50;
pub const GREP_MAX: u64 = 100;
pub const REFS_MAX: u64 = 200;
pub const SIMILAR_K: usize = 10;
pub const DUPES_MIN_TOKENS: usize = 30;
pub const DUPES_THRESHOLD: f32 = 0.75;
pub const DUPES_LIMIT: usize = 50;
pub const TSQUERY_LIMIT: usize = 1000;
/// Calls a call path follows at most.
pub const PATH_DEPTH: usize = 10;
/// Lines one `read` returns at most.
pub const READ_LINES: i64 = 400;
/// Bytes of line text one `read_code` of a line range collects at most; a longer line is cut.
pub const READ_BYTES: usize = 1_000_000;
/// Definitions one `read` of a name returns at most.
pub const READ_DEFINITIONS: usize = 20;
/// Bytes of text an agent gets from one call unless it asks for more: about 6,000 tokens, under
/// the 10,000 at which Codex cuts a tool result and Claude Code warns.
pub const AGENT_BYTES: usize = 24_000;

/// Serialized as a command line sends it to a session; a grep never goes that way.
#[derive(serde::Serialize, serde::Deserialize)]
pub enum Op {
    /// `snippets`: each hit carries its text (off for a caller that reads locations only).
    Search {
        query: String,
        alt: Vec<String>,
        k: usize,
        snippets: bool,
    },
    /// An Engine A search of the repository's files, its lines grouped by enclosing symbol.
    #[serde(skip)]
    Grep {
        pattern: Pattern,
        scope: Scope,
        max_results: u64,
    },
    Symbol {
        name: String,
        limit: usize,
    },
    Callers {
        name: String,
        limit: usize,
    },
    Callees {
        name: String,
        limit: usize,
    },
    /// A line range of `path`, or with `symbol` (a name or a location) every definition it names,
    /// whole; `path` then keeps the definitions in that file.
    Read {
        path: Option<String>,
        symbol: Option<String>,
        start: i64,
        end: Option<i64>,
    },
    Outline {
        path: String,
    },
    Deps {
        path: String,
    },
    Rdeps {
        target: String,
    },
    /// `textual`: every occurrence of the name grouped by enclosing symbol, instead of each one
    /// resolved to the definition it refers to. `def` (`path` or `path:line`) keeps one definition.
    Refs {
        name: String,
        max_results: u64,
        textual: bool,
        def: Option<String>,
    },
    Similar {
        target: String,
        k: usize,
    },
    Dupes {
        min_tokens: usize,
        threshold: f32,
        limit: usize,
    },
    Tsquery {
        lang: String,
        query: String,
        limit: usize,
    },
    /// The files ranked by how the others call and import them, each with its top definitions;
    /// `path` keeps the files under one directory.
    Map {
        path: Option<String>,
    },
    /// The shortest chain of calls from one definition (a name or a location) to another.
    Path {
        from: String,
        to: String,
        depth: usize,
    },
    /// Definitions nothing in the repository uses, those under `path` (a directory or file) alone.
    Dead {
        path: Option<String>,
    },
    /// `force`: read every file again, also one whose size, modification and change times are unchanged.
    Reindex {
        force: bool,
    },
    /// What the working tree (`staged`: the staged changes) changes against `base` (`HEAD` when
    /// none): the changed definitions, their callers up to `depth` steps away and the tests to run.
    Impact {
        base: Option<String>,
        staged: bool,
        depth: usize,
    },
    /// The paths of the repository ranked for a short, possibly misspelt `query` (`finder::find`).
    Files {
        query: String,
        limit: usize,
    },
}

impl Op {
    /// The operation an MCP tool call or a `batch` line names, defaults filled in and limits
    /// clamped (the caller is a program: an absurd limit is cut, not refused).
    pub fn from_tool(name: &str, args: &Value) -> Result<Op> {
        // a JSON null is an argument left out; any other value of the wrong type is an error
        let arg = |k: &str| args.get(k).filter(|v| !v.is_null());
        let wrong = |k: &str, ty: &str| anyhow!("{k} must be {ty}");
        let opt_text = |k: &str| arg(k).map(|v| v.as_str().map(str::to_string).ok_or_else(|| wrong(k, "a string"))).transpose();
        let text = |k: &str| opt_text(k)?.ok_or_else(|| anyhow!("missing {k}"));
        let natural = |k: &str| arg(k).map(|v| v.as_u64().ok_or_else(|| wrong(k, "a non-negative integer"))).transpose();
        let count = |k: &str, default: u64, max: u64| natural(k).map(|n| n.unwrap_or(default).clamp(1, max));
        let line = |k: &str| arg(k).map(|v| v.as_i64().ok_or_else(|| wrong(k, "an integer (a line number)"))).transpose();
        let flag = |k: &str| arg(k).map(|v| v.as_bool().ok_or_else(|| wrong(k, "a boolean (true or false)"))).transpose().map(|b| b.unwrap_or(false));
        // read by the server, not here, but checked with the rest
        natural("max_bytes")?;
        natural("offset")?;
        Form::from_tool(args)?;
        Ok(match name {
            "search_code" => Op::Search {
                query: text("query")?,
                alt: match arg("alt_queries") {
                    None => Vec::new(),
                    Some(v) => v
                        .as_array()
                        .and_then(|a| a.iter().map(|x| x.as_str().map(str::to_string)).collect::<Option<Vec<_>>>())
                        .ok_or_else(|| wrong("alt_queries", "an array of strings"))?
                        .into_iter()
                        .take(ALT_QUERIES)
                        .collect(),
                },
                k: count("k", SEARCH_K as u64, 100)? as usize,
                snippets: true,
            },
            "grep_code" => Op::Grep {
                pattern: Pattern {
                    text: text("pattern")?,
                    mode: mode_named(opt_text("mode")?.as_deref().unwrap_or("regex"), natural("max_edits")?.unwrap_or(1).min(u8::MAX as u64) as u8)?,
                    case: case_named(opt_text("case")?.as_deref().unwrap_or("sensitive"))?,
                    word: flag("word")?,
                    ..Pattern::default()
                },
                scope: Scope {
                    path: opt_text("path")?,
                    globs: match arg("globs") {
                        None => Vec::new(),
                        Some(v) => v
                            .as_array()
                            .and_then(|a| a.iter().map(|x| x.as_str().map(str::to_string)).collect::<Option<Vec<_>>>())
                            .ok_or_else(|| wrong("globs", "an array of strings"))?,
                    },
                },
                max_results: count("max_results", GREP_MAX, 5000)?,
            },
            "find_symbol" => Op::Symbol { name: text("name")?, limit: count("limit", SYMBOL_LIMIT as u64, 500)? as usize },
            "callers" => Op::Callers { name: text("name")?, limit: count("limit", CALLERS_LIMIT as u64, 500)? as usize },
            "callees" => Op::Callees { name: text("name")?, limit: count("limit", CALLEES_LIMIT as u64, 500)? as usize },
            "read_code" => {
                let (path, symbol) = (opt_text("path")?, opt_text("symbol")?);
                if path.is_none() && symbol.is_none() {
                    bail!("missing path or symbol");
                }
                let (start, end) = (line("start")?.unwrap_or(1), line("end")?);
                if let Some(end) = end.filter(|e| *e < start) {
                    bail!("end ({end}) is before start ({start})");
                }
                Op::Read { path, symbol, start, end }
            }
            "outline" => Op::Outline { path: text("path")? },
            "dependencies" => Op::Deps { path: text("path")? },
            "dependents" => Op::Rdeps { target: text("target")? },
            "references" => {
                let name = text("name")?;
                if name.trim().is_empty() {
                    bail!("name is empty");
                }
                Op::Refs { name, max_results: count("max_results", REFS_MAX, 5000)?, textual: flag("textual")?, def: opt_text("def")? }
            }
            "similar_code" => Op::Similar { target: text("target")?, k: count("k", SIMILAR_K as u64, 50)? as usize },
            "duplicates" => Op::Dupes {
                min_tokens: count("min_tokens", DUPES_MIN_TOKENS as u64, 100_000)? as usize,
                threshold: arg("threshold")
                    .map(|v| v.as_f64().ok_or_else(|| wrong("threshold", "a number")))
                    .transpose()?
                    .map_or(DUPES_THRESHOLD, |t| t as f32),
                limit: count("limit", DUPES_LIMIT as u64, 500)? as usize,
            },
            "structural_search" => Op::Tsquery { lang: text("lang")?, query: text("query")?, limit: count("limit", TSQUERY_LIMIT as u64, 5000)? as usize },
            "repo_map" => Op::Map { path: opt_text("path")? },
            "call_path" => Op::Path { from: text("from")?, to: text("to")?, depth: count("depth", PATH_DEPTH as u64, 100)? as usize },
            "dead_code" => Op::Dead { path: opt_text("path")? },
            "reindex" => Op::Reindex { force: flag("force")? },
            "impact" => Op::Impact {
                base: opt_text("base")?,
                staged: flag("staged")?,
                depth: natural("depth")?.map_or(crate::impact::DEPTH, |d| d.min(crate::impact::MAX_DEPTH as u64) as usize),
            },
            "find_files" => Op::Files { query: text("query")?, limit: count("limit", crate::finder::LIMIT as u64, crate::finder::MAX_LIMIT)? as usize },
            _ => bail!("unknown tool {}", echo(name)),
        })
    }
}

impl Op {
    /// Whether the index is brought up to date before this operation: a line range of a file
    /// reads the file alone, and a reindex is the update.
    pub fn reads_index(&self) -> bool {
        !matches!(self, Op::Read { symbol: None, .. } | Op::Reindex { .. } | Op::Files { .. })
    }

    /// Repository files the arguments name (a path, or the file of a location), whose index
    /// entries an answer depends on even when it cites nothing.
    pub fn named_paths(&self) -> Vec<String> {
        let loc = |n: &str| crate::intel::location(n).map(|(p, _)| p.to_string());
        let plain = |p: &str| p.trim_start_matches("./").to_string();
        match self {
            Op::Symbol { name, .. } | Op::Callers { name, .. } | Op::Callees { name, .. } => loc(name).into_iter().collect(),
            Op::Similar { target, .. } => loc(target).into_iter().collect(),
            Op::Path { from, to, .. } => loc(from).into_iter().chain(loc(to)).collect(),
            Op::Read { path, symbol: Some(symbol), .. } => loc(symbol).into_iter().chain(path.as_deref().map(plain)).collect(),
            Op::Outline { path } | Op::Deps { path } => vec![plain(path)],
            Op::Refs { def: Some(def), .. } => vec![loc(def).unwrap_or_else(|| plain(def))],
            _ => Vec::new(),
        }
    }
}

/// The matching mode a front end names: `regex`, `literal`, `identifier`, `fuzzy` and
/// `fuzzy_regex` (within `max_edits` edits) or `pcre2`.
pub fn mode_named(name: &str, max_edits: u8) -> Result<Mode> {
    Ok(match name {
        "regex" => Mode::Regex,
        "literal" => Mode::Literal,
        "identifier" => Mode::Identifier,
        "pcre2" => Mode::Pcre2,
        "fuzzy" => Mode::Fuzzy { max_edits },
        "fuzzy_regex" => Mode::FuzzyRegex { max_edits },
        other => bail!("unknown mode {}: regex, literal, identifier, pcre2, fuzzy or fuzzy_regex", echo(other)),
    })
}

/// The case rule a front end names: `sensitive`, `insensitive` or `smart`.
pub fn case_named(name: &str) -> Result<Case> {
    Ok(match name {
        "sensitive" => Case::Sensitive,
        "insensitive" => Case::Insensitive,
        "smart" => Case::Smart,
        other => bail!("unknown case {}: sensitive, insensitive or smart", echo(other)),
    })
}

/// Which files of the repository a grep reads: the ones a search of the repository covers
/// (`files::repository_files`), under `path` (a file or directory, from the root) and kept by
/// `globs` (as `grep -g`: `!` excludes).
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Scope {
    pub path: Option<String>,
    pub globs: Vec<String>,
}

impl Scope {
    fn files(&self, root: &std::path::Path) -> Result<Files> {
        let mut f = crate::files::repository_files(root);
        // the repository's own exclusions come last, where a later glob wins, so no glob of the caller brings them back
        let skip = std::mem::take(&mut f.globs);
        f.globs = self.globs.iter().cloned().chain(skip).collect();
        let path = self.path.as_deref().map(|p| p.trim_start_matches("./")).filter(|p| !p.is_empty() && *p != ".");
        if let Some(p) = path {
            let p = crate::fmt::unshown(p);
            if !inside(root, &p) {
                bail!("path outside repo");
            }
            // a link that leaves the repository reads as a missing path, as read_code answers it
            match std::fs::canonicalize(root.join(&*p)) {
                Ok(c) if c.starts_with(root) => f.paths = crate::instant::Paths::Walk(vec![root.join(&*p)]),
                _ => bail!("no such file or directory in the repository: {}", echo(&p)),
            }
            f.paths_as_given = true;
        }
        Ok(f)
    }
}

/// Whether the tool leaves everything as it was (`reindex` rewrites the index, a cache).
pub fn read_only(tool: &str) -> bool {
    tool != "reindex"
}

/// The JSON Schema of what `Answer::structured` returns for one tool: the answer's JSON form in
/// `result`, or `null` there when the answer is too large to send whole.
pub fn output_schema(tool: &str) -> Value {
    let ty = |t: &str| json!({"type": t});
    let obj = |properties: Value, required: &[&str]| json!({"type": "object", "properties": properties, "required": required});
    let list = |items: Value| json!({"type": "array", "items": items});
    // a symbol: where it is, and its name under the key this answer uses
    let span = |name: &str| {
        let mut properties = json!({"id": ty("string"), "path": ty("string"), "start": ty("integer"), "end": ty("integer"), "kind": ty("string")});
        properties[name] = ty("string");
        obj(properties, &["path", "start", "end", "kind", name])
    };
    let result = match tool {
        "search_code" | "find_symbol" | "callers" => list(span("name")),
        "callees" => obj(json!({"resolved": list(span("name")), "external": list(ty("string"))}), &["resolved", "external"]),
        "grep_code" => {
            let line = obj(json!({"line": ty("integer"), "text": ty("string")}), &["line", "text"]);
            let group = obj(
                json!({"symbol": {"anyOf": [span("name"), ty("null")]}, "path": ty("string"), "lines": list(line), "note": ty("string")}),
                &["symbol", "path", "lines"],
            );
            obj(json!({"groups": list(group), "stopped_at": {"type": ["integer", "null"]}}), &["groups", "stopped_at"])
        }
        "read_code" => obj(
            json!({"text": ty("string"), "start": ty("integer"), "end": ty("integer"), "file_lines": {"type": ["integer", "null"]}, "definitions": list(span("qualname"))}),
            &[],
        ),
        "outline" => list(obj(
            json!({"kind": ty("string"), "name": ty("string"), "qualname": ty("string"), "start": ty("integer"), "end": ty("integer")}),
            &["kind", "name", "qualname", "start", "end"],
        )),
        "dependencies" => list(obj(json!({"line": ty("integer"), "module": ty("string"), "resolved": {"type": ["string", "null"]}}), &["line", "module"])),
        "dependents" => list(obj(json!({"path": ty("string"), "line": ty("integer"), "module": ty("string")}), &["path", "line", "module"])),
        "references" => {
            let note = obj(json!({"path": ty("string"), "note": ty("string")}), &["path", "note"]);
            obj(
                json!({"name": ty("string"), "definitions": list(span("qualname")), "truncated": ty("boolean"), "notes": list(note)}),
                &["name", "definitions", "truncated"],
            )
        }
        "similar_code" => {
            let mut hit = span("qualname");
            hit["properties"]["cosine"] = ty("number");
            hit["properties"]["jaccard"] = ty("number");
            list(hit)
        }
        "duplicates" => list(obj(
            json!({"kind": ty("string"), "similarity": ty("number"), "tokens": ty("integer"), "members": ty("array")}),
            &["kind", "similarity", "tokens", "members"],
        )),
        "impact" => {
            let item = |more: &[(&str, Value)]| {
                let mut v = span("qualname");
                for (k, t) in more {
                    v["properties"][*k] = t.clone();
                }
                v["properties"]["start"] = json!({"type": ["integer", "null"]});
                v["properties"]["end"] = json!({"type": ["integer", "null"]});
                v
            };
            let test = obj(json!({"path": ty("string"), "distance": ty("integer"), "via": {"anyOf": [item(&[]), ty("null")]}}), &["path", "distance", "via"]);
            let note = obj(json!({"path": ty("string"), "note": ty("string")}), &["path", "note"]);
            obj(
                json!({
                    "against": ty("string"), "base": ty("string"), "staged": ty("boolean"), "depth": ty("integer"),
                    "changed": list(item(&[("status", json!({"type": "string", "enum": ["added", "edited", "deleted"]}))])),
                    "callers": list(item(&[("distance", ty("integer")), ("via", ty("string")), ("undecided", ty("boolean"))])),
                    "tests": list(test), "notes": list(note), "stopped": ty("boolean"),
                }),
                &["against", "base", "staged", "depth", "changed", "callers", "tests", "notes", "stopped"],
            )
        }
        "find_files" => list(obj(
            json!({"path": ty("string"), "match": {"type": "string", "enum": ["exact", "basename", "path"]}, "edits": ty("integer"), "frecency": ty("number")}),
            &["path", "match", "edits", "frecency"],
        )),
        "structural_search" => list(obj(
            json!({"path": ty("string"), "line": ty("integer"), "column": ty("integer"), "capture": ty("string"), "kind": ty("string"), "text": ty("string")}),
            &["path", "line", "column", "capture", "kind", "text"],
        )),
        "repo_map" => {
            let mut def = span("qualname");
            def["properties"]["calls"] = ty("integer");
            list(obj(
                json!({"path": ty("string"), "rank": ty("integer"), "score": ty("number"), "definitions": list(def)}),
                &["path", "rank", "score", "definitions"],
            ))
        }
        "call_path" => {
            let step = obj(
                json!({"path": ty("string"), "line": ty("integer"), "definition": span("name"), "tied": ty("boolean")}),
                &["path", "line", "definition", "tied"],
            );
            obj(
                json!({"from": span("name"), "to": span("name"), "found": ty("boolean"), "depth": ty("integer"), "stopped": ty("boolean"), "steps": list(step)}),
                &["from", "to", "found", "depth", "stopped", "steps"],
            )
        }
        "dead_code" => {
            let mut why = span("qualname");
            why["properties"]["reason"] = ty("string");
            obj(json!({"dead": list(span("qualname")), "undecided": list(why)}), &["dead", "undecided"])
        }
        _ => {
            obj(json!({"files_changed": ty("integer"), "files_removed": ty("integer"), "chunks": ty("integer")}), &["files_changed", "files_removed", "chunks"])
        }
    };
    let stopped = json!({"type": "integer", "description": "present when the answer stopped at this limit and more exist: the text's last line says which argument raises it"});
    let complete =
        json!({"type": "boolean", "description": "false when the answer is larger than max_bytes: result is then null and text holds the part that fits"});
    obj(
        json!({"schema": ty("integer"), "complete": complete, "result": {"anyOf": [result, ty("null")]}, "text": ty("string"), "stopped_at": stopped}),
        &["schema", "complete", "result"],
    )
}

/// An answer's JSON form in the envelope every front end prints.
pub fn envelope(result: Value, stopped: Option<Stop>) -> Value {
    let mut v = json!({"schema": ANSWER_SCHEMA, "result": result});
    if let Some(stop) = stopped {
        v["stopped_at"] = json!(stop.at);
    }
    v
}

/// Where an answer stopped because it reached its limit, and what to pass to see more.
#[derive(Clone, Copy, Debug)]
pub struct Stop {
    pub at: usize,
    pub how: &'static str,
}

pub const RAISE_LIMIT: &str = "raise limit to see more";

/// `items` cut to `limit`, and where they stopped when there were more (ask for `limit + 1`).
fn cut<T>(mut items: Vec<T>, limit: usize, how: &'static str) -> (Vec<T>, Option<Stop>) {
    if items.len() <= limit {
        return (items, None);
    }
    items.truncate(limit);
    (items, Some(Stop { at: limit, how }))
}

pub enum Answer {
    /// `stopped`: the limit the answer stopped at, when there were more.
    Hits {
        hits: Vec<Hit>,
        words: Vec<String>,
        snippet: bool,
        stopped: Option<Stop>,
    },
    /// `undecided`: callers kept although the resolver could not tell whether they call this
    /// definition or another of the same name.
    Callers {
        hits: Vec<Hit>,
        undecided: usize,
        stopped: Option<Stop>,
    },
    /// `from`: the files of the definitions whose calls these are.
    Callees {
        resolved: Vec<Hit>,
        external: Vec<String>,
        from: Vec<String>,
        stopped: Option<Stop>,
    },
    /// `stopped_at`: the limit the search stopped at, when it did.
    Grep {
        groups: Vec<RefGroup>,
        stopped_at: Option<u64>,
    },
    /// Numbered lines of `path` from line `start` on, and how many lines the file has (None
    /// for a large file read only up to the lines asked for: more lines follow).
    /// `defs`: the definitions the index has in the file, which the concise form lists.
    Read {
        path: String,
        lines: Vec<String>,
        start: i64,
        total: Option<i64>,
        defs: Vec<crate::index::Symbol>,
    },
    /// Whole definitions, each with its numbered lines and the definitions inside it.
    Definitions(Vec<(ChunkRow, String, Vec<crate::index::Symbol>)>, Option<Stop>),
    Outline {
        path: String,
        rows: Vec<ChunkRow>,
    },
    Deps {
        path: String,
        deps: Vec<Dependency>,
    },
    /// `unresolved`: imports that resolved to no file and may name `target`.
    Rdeps {
        target: String,
        rows: Vec<(String, i64, String)>,
        unresolved: usize,
    },
    Refs {
        name: String,
        refs: References,
        max_results: u64,
    },
    /// `only`: the one definition asked for with `def`.
    Resolved {
        name: String,
        refs: Resolved,
        only: Option<i64>,
        max_results: u64,
    },
    Similar(Vec<(Hit, f32, f32)>),
    Dupes(Vec<DupGroup>, Option<Stop>),
    Captures(Vec<Capture>, Option<Stop>),
    Map(Vec<crate::repomap::MapFile>),
    Path(Box<crate::names::CallPath>),
    Dead(crate::dead::Dead),
    Reindexed(UpdateStats),
    Impact(crate::impact::Impact),
    Files(Vec<crate::finder::FileHit>, Option<Stop>),
}

/// The `files` answer, which reads no index: a front end runs it without opening one.
pub fn files(root: &std::path::Path, query: &str, limit: usize) -> Result<Answer> {
    let (hits, more) = crate::finder::find(root, query, limit)?;
    Ok(Answer::Files(hits, more.then_some(Stop { at: limit, how: RAISE_LIMIT })))
}

/// Run one operation on the index as it is; `Repo::run` brings the index up to date first.
pub fn run(s: &mut Searcher, op: &Op) -> Result<Answer> {
    Ok(match op {
        Op::Search { query, alt, k, snippets } => {
            let mut qs = vec![query.clone()];
            qs.extend(alt.iter().filter(|a| !a.is_empty() && *a != query).cloned());
            let hits = if qs.len() == 1 { s.search(query, *k, *snippets)? } else { s.search_many(&qs, *k, *snippets)? };
            Answer::Hits { hits, words: qs.iter().flat_map(|q| query_words(q)).collect(), snippet: true, stopped: None }
        }
        Op::Grep { pattern, scope, max_results } => {
            let q = crate::instant::Query {
                pattern: pattern.clone(),
                max_results: Some(*max_results),
                // a capped answer is the same on every call, so paging does not repeat or skip lines
                first_in_path_order: true,
                ..Default::default()
            };
            let files = scope.files(&s.ix.root)?;
            let (groups, stopped) = crate::intel::grouped_grep(s, &q, &files)?;
            Answer::Grep { groups, stopped_at: stopped.then_some(*max_results) }
        }
        Op::Symbol { name, limit } => {
            let (hits, stopped) = cut(targets(s, name, limit.saturating_add(1), false)?, *limit, RAISE_LIMIT);
            Answer::Hits { hits, words: Vec::new(), snippet: true, stopped }
        }
        Op::Callers { name, limit } => {
            let (hits, mut undecided) = Names::new(s)?.callers(name, limit.saturating_add(1))?;
            let (hits, stopped) = cut(hits, *limit, RAISE_LIMIT);
            // the undecided ones come last, so the one cut off was one of them
            if stopped.is_some() {
                undecided = undecided.saturating_sub(1);
            }
            Answer::Callers { hits, undecided, stopped }
        }
        Op::Callees { name, limit } => {
            let (resolved, external, from) = Names::new(s)?.callees(name, limit.saturating_add(1))?;
            let (resolved, stopped) = cut(resolved, *limit, RAISE_LIMIT);
            Answer::Callees { resolved, external, from, stopped }
        }
        Op::Read { path, symbol: Some(symbol), .. } => {
            let mut rows = match crate::intel::location(symbol) {
                Some((path, line)) => s.ix.chunk_at(&repo_path(s, path), line)?.into_iter().collect(),
                None => {
                    let hits = s.find_symbol(symbol, READ_DEFINITIONS + 1)?;
                    hits.iter().filter_map(|h| s.ix.chunk(h.id).transpose()).collect::<Result<Vec<_>>>()?
                }
            };
            if let Some(path) = path {
                let path = repo_path(s, path);
                rows.retain(|r| r.path == path);
            }
            if rows.is_empty() {
                bail!("no definition matches {}", echo(symbol));
            }
            let read = |r: ChunkRow| -> Result<(ChunkRow, String, Vec<crate::index::Symbol>)> {
                let mut text = read_range(s, &r.path, r.start, r.end.min(r.start.saturating_add(READ_LINES - 1)))?.0.join("\n");
                if r.end - r.start + 1 > READ_LINES {
                    text.push_str(&format!("\n(the definition goes on to line {}: read_code path={} start={})", r.end, r.path, r.start + READ_LINES));
                }
                let mut inner = s.ix.symbols_in(&r.path).unwrap_or_default();
                inner.retain(|m| m.id != r.id && r.start <= m.start && m.end <= r.end);
                Ok((r, text, inner))
            };
            let (rows, stopped) = cut(rows, READ_DEFINITIONS, "pass path to keep the ones of one file, or a location (path:start-end) for one");
            let read = rows.into_iter().map(read).collect::<Result<Vec<_>>>()?;
            crate::finder::visited(
                &s.ix.root,
                &read.iter().map(|(r, ..)| r.path.as_str()).collect::<std::collections::BTreeSet<_>>().into_iter().collect::<Vec<_>>(),
            );
            Answer::Definitions(read, stopped)
        }
        Op::Read { path, start, end, .. } => {
            let path = path.as_deref().unwrap_or("");
            // a path copied from an answer has its control characters written as escapes
            let read_back = crate::fmt::unshown(path);
            // a path that leaves the repository by its own parts is not looked at
            let exists = |p: &str| inside(&s.ix.root, p) && s.ix.root.join(p).exists();
            let printed = read_back != path && crate::fmt::shown(&read_back) == path && exists(&read_back);
            let path = if printed || (read_back != path && !exists(path)) { read_back.as_ref() } else { path };
            let start = (*start).max(1);
            let (lines, total) = read_range(s, path, start, end.unwrap_or(start.saturating_add(READ_LINES - 1)))?;
            let path = path.trim_start_matches("./").to_string();
            crate::finder::visited(&s.ix.root, &[&path]);
            let last = start + lines.len() as i64 - 1;
            let mut defs = s.ix.symbols_in(&path).unwrap_or_default();
            defs.retain(|d| start <= d.start && d.start <= last);
            Answer::Read { path, lines, start, total, defs }
        }
        Op::Outline { path } => {
            let path = repo_path(s, path);
            Answer::Outline { rows: s.ix.outline(&path)?, path }
        }
        Op::Deps { path } => {
            let path = repo_path(s, path);
            Answer::Deps { deps: Names::new(s)?.imports(&path)?, path }
        }
        Op::Rdeps { target } => {
            let target = repo_path(s, target);
            let (rows, unresolved) = Names::new(s)?.importers(&target)?;
            Answer::Rdeps { rows, target, unresolved }
        }
        Op::Refs { name, max_results, textual: true, .. } => {
            let name = &name.trim().to_string();
            Answer::Refs { name: name.clone(), refs: crate::intel::references(s, name, *max_results)?, max_results: *max_results }
        }
        Op::Refs { name, max_results, def, .. } => {
            let name = &name.trim().to_string();
            let refs = Names::new(s)?.references(name, *max_results)?;
            let only = match def {
                Some(spec) => Some(definition_at(s, &refs, name, spec)?),
                None => None,
            };
            Answer::Resolved { name: name.clone(), refs, only, max_results: *max_results }
        }
        Op::Similar { target, k } => Answer::Similar(crate::intel::similar(s, target, *k)?),
        Op::Dupes { min_tokens, threshold, limit } => {
            let (groups, stopped) = cut(crate::intel::dupes(&s.ix, *min_tokens, *threshold, limit.saturating_add(1))?, *limit, RAISE_LIMIT);
            Answer::Dupes(groups, stopped)
        }
        Op::Tsquery { lang, query, limit } => {
            let caps = crate::intel::tsquery(lang, query, std::slice::from_ref(&s.ix.root), limit.saturating_add(1), Some(&s.ix.root))?;
            let (caps, stopped) = cut(caps, *limit, RAISE_LIMIT);
            Answer::Captures(caps, stopped)
        }
        Op::Map { path } => Answer::Map(crate::repomap::map(s, path.as_deref().map(|p| repo_path(s, p)).as_deref())?),
        Op::Path { from, to, depth } => Answer::Path(Box::new(Names::new(s)?.path(from, to, *depth)?)),
        Op::Dead { path } => {
            let path = path.as_deref().map(|p| repo_path(s, p)).filter(|p| !p.is_empty() && p != ".");
            if let Some(p) = &path {
                if !inside(&s.ix.root, p) || !s.ix.root.join(p).exists() {
                    bail!("no such file or directory in the repository: {}", echo(p));
                }
            }
            Answer::Dead(Names::new(s)?.dead(path.as_deref())?)
        }
        Op::Reindex { .. } => bail!("reindex keeps every store current: run it through Repo"),
        Op::Impact { base, staged, depth } => Answer::Impact(crate::impact::impact(s, base.as_deref(), *staged, *depth)?),
        Op::Files { query, limit } => files(&s.ix.root, query, *limit)?,
    })
}

/// Whether `root` joined with `path` stays under `root` by their parts alone (`.` dropped and
/// `..` taking a part away), with no file looked at.
fn inside(root: &std::path::Path, path: &str) -> bool {
    let mut out = std::path::PathBuf::new();
    for c in root.join(path).components() {
        match c {
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir => {
                out.pop();
            }
            c => out.push(c),
        }
    }
    if cfg!(windows) {
        under(&out.to_string_lossy(), &root.to_string_lossy())
    } else {
        out.starts_with(root)
    }
}

/// On Windows one folder has several spellings (`\\?\C:\x` from `canonicalize`, `C:\x`, `c:/X`)
/// and the prefix parts of two paths compare by kind, so the two are compared as text.
fn under(path: &str, root: &str) -> bool {
    fn plain(p: &str) -> String {
        let s = p.replace('\\', "/");
        let s = match s.strip_prefix("//?/") {
            Some(rest) if rest.get(..4).is_some_and(|h| h.eq_ignore_ascii_case("UNC/")) => format!("//{}", &rest[4..]),
            Some(rest) => rest.to_string(),
            None => s,
        };
        s.to_lowercase()
    }
    let (path, root) = (plain(path), plain(root));
    path.strip_prefix(root.trim_end_matches('/')).is_some_and(|rest| rest.is_empty() || rest.starts_with('/'))
}

/// Lines `start..=end` of a repository file, numbered, read only as far as they go and at most
/// `READ_BYTES` of them; and how many lines the file has, when the read reached its end or the
/// file is small enough to count them.
pub fn read_range(s: &Searcher, path: &str, start: i64, end: i64) -> Result<(Vec<String>, Option<i64>)> {
    use std::io::BufRead;
    let shown = echo(path);
    // the answer for a path outside the repository must not tell whether a file is there: one
    // that leaves by its own parts is outside, with nothing looked at (on Windows a share on
    // another machine would be connected to, and offered the user's login), and a link that
    // leaves reads as a missing file
    if !inside(&s.ix.root, path) {
        bail!("path outside repo");
    }
    let canon = match std::fs::canonicalize(s.ix.root.join(path)) {
        Ok(c) if c.starts_with(&s.ix.root) => c,
        _ => bail!("cannot read {shown}"),
    };
    if !canon.is_file() {
        bail!("{shown} is not a regular file");
    }
    let file = std::fs::File::open(&canon).map_err(|_| anyhow!("cannot read {shown}"))?;
    let small = file.metadata()?.len() <= crate::index::MAX_FILE_BYTES;
    let mut r = std::io::BufReader::with_capacity(64 * 1024, file);
    // a NUL byte in the first 8 KB, the test grep tools use
    if r.fill_buf().map(|b| b[..b.len().min(8192)].contains(&0))? {
        bail!("{shown} is not a text file (it holds a NUL byte): read_code shows text only");
    }
    // one line into `line`, up to its first `keep` bytes, where the read stops when `keep` is
    // not 0 -> (anything read, the line goes on past what was read)
    let mut next_line = |line: &mut Vec<u8>, keep: usize| -> std::io::Result<(bool, bool)> {
        let mut any = false;
        loop {
            let buf = r.fill_buf()?;
            if buf.is_empty() {
                return Ok((any, false));
            }
            any = true;
            let (body, done) = match buf.iter().position(|&b| b == b'\n') {
                Some(i) => (i, i + 1),
                None => (buf.len(), buf.len()),
            };
            let room = keep.saturating_sub(line.len());
            if keep > 0 && body > room {
                line.extend_from_slice(&buf[..room]);
                r.consume(room);
                return Ok((any, true));
            }
            line.extend_from_slice(&buf[..body.min(room)]);
            let newline = done > body;
            r.consume(done);
            if newline {
                return Ok((any, false));
            }
        }
    };
    let (mut out, mut used, mut n, mut line, mut mid_line) = (Vec::new(), 0usize, 0i64, Vec::new(), false);
    loop {
        if n >= end || (n + 1 >= start && used >= READ_BYTES) {
            break;
        }
        let wanted = n + 1 >= start;
        line.clear();
        let (any, cut) = next_line(&mut line, if wanted { READ_BYTES - used } else { 0 })?;
        if !any {
            return Ok((out, Some(n)));
        }
        n += 1;
        if wanted {
            if !cut && line.last() == Some(&b'\r') {
                line.pop();
            }
            used += line.len().max(1);
            let mut text = format!("{n:>5}  {}", String::from_utf8_lossy(&line));
            if cut {
                text.push_str(&format!("  (line cut at {} bytes)", line.len()));
                mid_line = true;
            }
            out.push(text);
        }
    }
    if !small {
        return Ok((out, (!mid_line && r.fill_buf()?.is_empty()).then_some(n)));
    }
    if mid_line {
        next_line(&mut line, 0)?;
    }
    loop {
        line.clear();
        if !next_line(&mut line, 0)?.0 {
            return Ok((out, Some(n)));
        }
        n += 1;
    }
}

/// One line for a structural match: where, the capture, and its text (the first line of the
/// node, with control characters written as escapes).
pub fn capture_line(c: &Capture) -> String {
    format!("{}:{}:{}  @{} ({})  {}", shown(&c.path), c.line, c.column, c.capture, c.kind, shown(&c.text))
}

/// `path` as the index spells it, when it names a repository file in a spelling `read_code`
/// accepts (`./a.py`, `pkg/../a.py`, another case on a case-insensitive file system); else as given.
pub fn repo_path(s: &Searcher, path: &str) -> String {
    // a path that leaves the repository names no file of it (`/a.py` is not `a.py`), and is not looked at
    if !inside(&s.ix.root, path) {
        return path.to_string();
    }
    let mut parts: Vec<&str> = Vec::new();
    for seg in path.split('/') {
        match seg {
            "" | "." => {}
            // above the root: no repository file, and the answer names the path as given
            ".." if parts.pop().is_none() => return path.to_string(),
            ".." => {}
            seg => parts.push(seg),
        }
    }
    let plain = parts.join("/");
    let indexed = |p: &str| s.ix.has_file(p);
    // a path copied from an answer has its control characters and backslashes written as
    // escapes; the text an answer prints for a file names that file, whatever else exists
    let read_back = crate::fmt::unshown(&plain);
    let escaped = read_back != plain;
    if escaped && crate::fmt::shown(&read_back) == plain && indexed(&read_back) {
        return read_back.into_owned();
    }
    if path.is_empty() || indexed(&plain) {
        return plain;
    }
    if escaped && indexed(&read_back) {
        return read_back.into_owned();
    }
    // another spelling of a file of the repository
    std::fs::canonicalize(s.ix.root.join(path))
        .ok()
        .filter(|p| p.is_file())
        .and_then(|p| p.strip_prefix(&s.ix.root).ok().map(|r| crate::instant::slashed(r.to_string_lossy())))
        .filter(|p| indexed(p))
        .unwrap_or(plain)
}

/// The definitions `name` stands for: the one at a location (the `path:start-end` an earlier
/// answer printed), else every one `find_symbol` finds. With `windows`, a line outside every
/// definition stands for the first window that holds it, which holds that line's calls.
pub fn targets(s: &Searcher, name: &str, limit: usize, windows: bool) -> Result<Vec<Hit>> {
    let Some((path, line)) = crate::intel::location(name) else { return s.find_symbol(name, limit) };
    let path = repo_path(s, path);
    let mut at = s.ix.chunk_at(&path, line)?;
    if windows && at.as_ref().is_some_and(|c| c.kind == "window") {
        at = s.ix.window_at(&path, line)?;
    }
    match at {
        Some(c) if windows || c.kind != "window" => Ok(vec![Hit::from_row(&c, true)]),
        // a search result can be a window: say what the location is, and which commands take it
        Some(_) => bail!("no symbol at {}: these lines are outside every definition (callees and similar take such a location)", echo(name)),
        None => bail!("no symbol at {}", echo(name)),
    }
}

/// The definition of `name` that `spec` (a path or a location) points at: the innermost one
/// around the line, or the first in the file.
fn definition_at(s: &Searcher, refs: &Resolved, name: &str, spec: &str) -> Result<i64> {
    let (path, line) = match crate::intel::location(spec) {
        Some((path, line)) => (repo_path(s, path), Some(line)),
        None => (repo_path(s, spec), None),
    };
    refs.definitions
        .iter()
        .filter(|d| d.path == path && line.is_none_or(|l| d.start <= l && l <= d.end))
        .min_by_key(|d| (line.is_some().then_some(d.end - d.start), d.start))
        .map(|d| d.id)
        .ok_or_else(|| anyhow!("no definition of {} in {}", echo(name), echo(spec)))
}

/// The closing line of an answer that stopped at its limit.
pub fn stop_line(stopped: Option<Stop>, noun: &str) -> String {
    stopped.map(|s| format!("(stopped at {} {noun}: {})", s.at, s.how)).unwrap_or_default()
}

/// Two closing lines, either of them possibly empty.
fn joined(a: String, b: String) -> String {
    match (a.is_empty(), b.is_empty()) {
        (true, _) => b,
        (_, true) => a,
        _ => format!("{a}\n{b}"),
    }
}

/// The closing line of a `references` answer whose occurrence search stopped at `max_results`.
fn stopped_at(truncated: bool, max_results: u64) -> String {
    if truncated {
        format!("(the search stopped at max_results={max_results} occurrences, so these counts cover only those: raise max_results to see all)")
    } else {
        String::new()
    }
}

/// A group's JSON with its note on the file, when it has one.
fn with_note(mut v: Value, g: &RefGroup) -> Value {
    if let Some(note) = &g.note {
        v["note"] = note.as_str().into();
    }
    v
}

/// A definition as one line: `path:start-end  [kind] name`.
fn hit_line(h: &Hit) -> String {
    hit_blocks(std::slice::from_ref(h), &[], false, false).remove(0)
}

fn symbol_name(c: &ChunkRow) -> &str {
    if c.qualname.is_empty() {
        &c.name
    } else {
        &c.qualname
    }
}

fn sym_name(s: &crate::index::Symbol) -> &str {
    if s.qualname.is_empty() {
        &s.name
    } else {
        &s.qualname
    }
}

fn hit_name(h: &Hit) -> &str {
    if h.qualname.is_empty() {
        &h.name
    } else {
        &h.qualname
    }
}

/// A definition's own name, without the names it is inside (`Answer.text` is `text`), as text shows it.
fn named(qualname: &str) -> std::borrow::Cow<'_, str> {
    shown(qualname.rsplit('.').next().filter(|n| !n.is_empty()).unwrap_or(qualname))
}

/// The code of a numbered line of `read_range`, without its number and indentation.
fn code_of(line: &str) -> &str {
    line.trim_start().split_once("  ").map_or("", |(_, code)| code).trim()
}

/// A group of matching lines in concise form: where its symbol is and the numbers of the lines.
fn group_brief(g: &RefGroup, indent: &str) -> Vec<Brief> {
    let lines = g.lines.iter().map(|h| h.line.to_string()).collect::<Vec<_>>().join(" ");
    let mut out = vec![match &g.symbol {
        Some(c) => Brief::text(indent).then_at(&c.path, c.start, c.end).then(format!(" {}: {lines}", named(symbol_name(c)))),
        None => Brief::text(indent).then_path(&g.path).then(format!(": {lines}")),
    }];
    out.extend(g.note.as_ref().map(|note| Brief::text(format!("{indent}  note: {note}"))));
    out
}

/// The concise lines of `intel::references_render`, one entry per line of it.
fn refs_brief(r: &References) -> Vec<Vec<Brief>> {
    let mut out = Vec::new();
    let mut section = |title: &str, defs: Vec<Brief>| {
        if !defs.is_empty() {
            out.push(vec![Brief::text(title)]);
            out.extend(defs.into_iter().map(|d| vec![d]));
        }
    };
    let at = |path: &str, start: i64, end: i64, name: &str| Brief::text("  ").then_at(path, start, end).then(format!(" {}", named(name)));
    section("definitions:", r.definitions.iter().map(|d| at(&d.path, d.start, d.end, &d.qualname)).collect());
    section("callers:", r.callers.iter().map(|h| at(&h.path, h.start, h.end, &h.qualname)).collect());
    out.push(vec![Brief::text(format!("references ({} lines in {} symbols):", r.total_lines(), r.groups.len()))]);
    for g in &r.groups {
        let mut lines = group_brief(g, "  ").into_iter();
        out.push(lines.next().into_iter().collect());
        out.extend(g.lines.iter().map(|_| Vec::new()));
        out.extend(lines.map(|note| vec![note]));
    }
    out
}

/// The concise lines of `resolve::resolved_text`, one entry per line of it.
fn resolved_brief(r: &Resolved, only: Option<i64>) -> Vec<Vec<Brief>> {
    let occurrence = |o: &crate::resolve::Occurrence| vec![Brief::text("  ").then_line(&o.path, format!(":{}:{}", o.line, o.column))];
    let mut out = Vec::new();
    for d in r.definitions.iter().filter(|d| only.is_none_or(|id| d.id == id)) {
        let occ: Vec<_> = r.of(d.id).collect();
        out.push(vec![Brief::at(&d.path, d.start, d.end, &format!("{} ({} references)", named(&d.qualname), occ.len()))]);
        out.extend(occ.into_iter().map(occurrence));
    }
    let unresolved: Vec<_> = r.unresolved().collect();
    match only {
        Some(id) => {
            let elsewhere = r.occurrences.len() - unresolved.len() - r.of(id).count();
            out.push(vec![Brief::text(format!("({elsewhere} other occurrences resolve to other definitions, {} are unresolved)", unresolved.len()))]);
        }
        None => {
            out.push(vec![Brief::text(format!("unresolved ({}):", unresolved.len()))]);
            out.extend(unresolved.into_iter().map(occurrence));
        }
    }
    out.extend(r.notes.iter().map(|(path, note)| vec![Brief::text("note: ").then_path(path).then(format!(": {note}"))]));
    out
}

/// The concise lines of `Impact::lines`, one entry per line of it.
fn impact_brief(i: &crate::impact::Impact) -> Vec<Vec<Brief>> {
    let symbol = |h: &Hit, mark: &str| {
        if h.kind == "file" {
            Brief::path(&h.path).then(format!(" [file]{mark}"))
        } else {
            Brief::at(&h.path, h.start, h.end, &format!("{}{mark}", named(hit_name(h))))
        }
    };
    let mut out = vec![vec![Brief::text(format!("changed: {}", i.changed.len()))]];
    out.extend(i.changed.iter().map(|c| vec![symbol(&c.hit, &format!(" ({})", c.status))]));
    out.push(vec![Brief::text(format!("callers: {} (depth {})", i.callers.len(), i.depth))]);
    out.extend(i.callers.iter().map(|c| {
        let mark = if c.calls_deleted {
            " (calls deleted)"
        } else if c.undecided {
            "?"
        } else {
            ""
        };
        vec![Brief::text(format!("{} ", c.distance)).and(symbol(&c.hit, mark))]
    }));
    out.push(vec![Brief::text(format!("tests: {}", i.tests.len()))]);
    out.extend(i.tests.iter().map(|t| {
        vec![match &t.via {
            // the definition that reaches the change names the test file when it is in it
            Some(h) if h.path == t.path && h.kind != "file" => symbol(h, &format!(" (test, {})", t.distance)),
            Some(h) => Brief::path(&t.path).then(format!(" ({} via ", t.distance)).and(symbol(h, ")")),
            None => Brief::path(&t.path).then(" (changed)"),
        }]
    }));
    if !i.notes.is_empty() {
        out.push(vec![Brief::text(format!("notes: {}", i.notes.len()))]);
        out.extend(i.notes.iter().map(|(p, n)| vec![Brief::path(p).then(format!(" {n}"))]));
    }
    out
}

fn chunk_json(c: &ChunkRow) -> Value {
    json!({"id": format!("{}:{}-{}", c.path, c.start, c.end), "path": c.path, "start": c.start, "end": c.end, "kind": c.kind, "qualname": c.qualname})
}

/// How an answer's text is written. `Concise` keeps every location and name and drops what an
/// agent can ask for again: code, snippets, scores, kinds and explanations.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Form {
    #[default]
    Detailed,
    Concise,
}

impl Form {
    /// The `response_format` argument of a tool call; left out or null is `detailed`.
    pub fn from_tool(args: &Value) -> Result<Form> {
        match args.get("response_format").filter(|v| !v.is_null()) {
            None => Ok(Form::Detailed),
            Some(v) => match v.as_str() {
                Some("detailed") => Ok(Form::Detailed),
                Some("concise") => Ok(Form::Concise),
                _ => bail!("response_format must be \"detailed\" or \"concise\""),
            },
        }
    }
}

/// One line of a concise answer: text, paths and locations. A line that ends with `/` names a
/// directory, and a path without `/` after it is in that directory (`./` is the root); a
/// location without a path (`:start-end`, `:line`, `:line:column`) is in the file of the location
/// before it. A directory
/// line comes before a line whose first path is in another directory; another path of that line
/// in another directory is written whole, and a file at the root as `./name`.
#[derive(Default)]
struct Brief(Vec<Piece>);

enum Piece {
    Text(String),
    Path(String),
    /// a path and what follows it: `:start-end`, `:line` or `:line:column`
    At(String, String),
}

/// The directory of the last directory line and the file of the last location of a page.
#[derive(Default)]
struct Written {
    dir: String,
    file: String,
}

impl Brief {
    fn text(text: impl Into<String>) -> Brief {
        Brief(vec![Piece::Text(text.into())])
    }
    fn path(path: &str) -> Brief {
        Brief::default().then_path(path)
    }
    fn then(mut self, text: impl Into<String>) -> Brief {
        self.0.push(Piece::Text(text.into()));
        self
    }
    fn and(mut self, more: Brief) -> Brief {
        self.0.extend(more.0);
        self
    }
    fn then_path(mut self, path: &str) -> Brief {
        self.0.push(Piece::Path(shown(path).into_owned()));
        self
    }
    fn then_at(self, path: &str, start: i64, end: i64) -> Brief {
        self.then_line(path, format!(":{start}-{end}"))
    }
    fn then_line(mut self, path: &str, place: String) -> Brief {
        self.0.push(Piece::At(shown(path).into_owned(), place));
        self
    }
    /// `path:start-end rest`
    fn at(path: &str, start: i64, end: i64, rest: &str) -> Brief {
        Brief::default().then_at(path, start, end).then(format!(" {rest}"))
    }
    /// The directory of the first path of the line.
    fn dir(&self) -> Option<&str> {
        self.0.iter().find_map(|p| match p {
            Piece::Path(path) | Piece::At(path, _) => Some(split_dir(path).0),
            Piece::Text(_) => None,
        })
    }
    /// The line after `out`, below a directory line when its first path is not in the last one.
    fn write(&self, page: &mut Written, out: &mut String) {
        let first = self.0.iter().find_map(|p| match p {
            Piece::Path(path) => Some(path),
            Piece::At(path, ..) if *path != page.file => Some(path),
            _ => None,
        });
        if let Some((d, _)) = first.map(|f| split_dir(f)).filter(|(d, _)| *d != page.dir) {
            push_line(out, &if d.is_empty() { "./".to_string() } else { format!("{d}/") });
            page.dir = d.to_string();
        }
        let mut line = String::new();
        let path = |line: &mut String, page: &Written, path: &str| match split_dir(path) {
            (d, name) if d == page.dir => line.push_str(name),
            ("", _) => line.push_str(&format!("./{path}")),
            _ => line.push_str(path),
        };
        for piece in &self.0 {
            match piece {
                Piece::Text(text) => line.push_str(text),
                Piece::Path(p) => path(&mut line, page, p),
                Piece::At(p, place) => {
                    if *p != page.file {
                        path(&mut line, page, p);
                        page.file = p.clone();
                    }
                    line.push_str(place);
                }
            }
        }
        push_line(out, &line);
    }
}

/// A path's directory (empty at the root) and file name.
fn split_dir(path: &str) -> (&str, &str) {
    path.rsplit_once('/').unwrap_or(("", path))
}

/// An answer as text: a first line, the items that can be counted and cut, and a last line.
#[derive(Default)]
struct Parts {
    head: String,
    items: Vec<String>,
    tail: String,
    noun: &'static str,
    /// items after `items` that were counted and not kept
    rest: usize,
    /// the items are lines of a file: its path, the number of the first, and the file's length
    /// (None: unknown, more lines follow)
    file: Option<(String, i64, Option<i64>)>,
    /// the concise form: the lines of each item (none hides it), and a last line in place of
    /// `tail`; without it the concise text is the detailed one
    brief: Option<Vec<Vec<Brief>>>,
    brief_tail: Option<String>,
    /// the concise page lists its lines by directory, in the order each directory first appears
    by_directory: bool,
}

const CUT_ITEM: &str = "(this item is cut: pass a larger max_bytes to see all of it)";

/// `items` (one result each, possibly of several lines) as `Answer::text_within` pages them.
pub fn paged(items: Vec<String>, noun: &'static str, max_bytes: usize, offset: usize) -> String {
    paged_counted(items, 0, noun, max_bytes, offset)
}

/// `paged` for a caller that kept the items up to what can be shown and counted the `rest`.
pub fn paged_counted(items: Vec<String>, rest: usize, noun: &'static str, max_bytes: usize, offset: usize) -> String {
    Parts { items, rest, noun, ..Parts::default() }.within(max_bytes, offset, Form::Detailed)
}

impl Parts {
    /// The page from item `offset` on that fits `max_bytes`. A concise page holds the items the
    /// detailed one holds, so an offset means the same items in both forms.
    fn within(&self, max_bytes: usize, offset: usize, form: Form) -> String {
        let mut room = max_bytes;
        loop {
            let (out, shown, cut) = self.render(max_bytes, room, offset);
            if out.len() <= max_bytes || room == 0 || (shown <= 1 && !cut) {
                return match &self.brief {
                    Some(brief) if form == Form::Concise => self.render_brief(brief, max_bytes, offset, shown),
                    _ => out,
                };
            }
            room = room.saturating_sub(out.len() - max_bytes);
        }
    }

    fn render_brief(&self, brief: &[Vec<Brief>], max_bytes: usize, offset: usize, count: usize) -> String {
        let mut out = self.head.clone();
        let mut page = Written::default();
        let mut lines: Vec<&Brief> = brief.iter().skip(offset).take(count).flatten().collect();
        if self.by_directory {
            let mut dirs: Vec<&str> = Vec::new();
            for b in &lines {
                let d = b.dir().unwrap_or("");
                if !dirs.contains(&d) {
                    dirs.push(d);
                }
            }
            lines.sort_by_key(|b| dirs.iter().position(|d| *d == b.dir().unwrap_or("")));
        }
        let any = !lines.is_empty();
        for line in lines {
            line.write(&mut page, &mut out);
        }
        if let (false, Some((_, first, _))) = (any, &self.file) {
            let last = first + (offset + count) as i64 - 1;
            push_line(&mut out, &format!("(no definition starts in lines {}-{last}: response_format detailed shows them)", first + offset as i64));
        }
        if out.len() > max_bytes {
            let mut at = max_bytes.saturating_sub(CUT_ITEM.len() + 1);
            while !out.is_char_boundary(at) {
                at -= 1;
            }
            out.truncate(at);
            push_line(&mut out, CUT_ITEM);
            return out;
        }
        self.close(&mut out, offset, count, self.brief_tail.as_deref().unwrap_or(&self.tail));
        out
    }

    /// The closing lines of a page of `count` items from `offset`: how to see more, or the last line.
    fn close(&self, out: &mut String, offset: usize, count: usize, tail: &str) {
        let all = self.items.len() + self.rest;
        let next = offset.min(all) + count;
        if let Some((path, first, total)) = &self.file {
            let last = first + next as i64 - 1;
            if count > 0 && total.is_none_or(|t| last < t) {
                let path = shown(path);
                let of = match total {
                    Some(t) => format!("of {t} in {path}"),
                    None => format!("of {path}, more lines follow"),
                };
                push_line(out, &format!("(lines {}-{last} {of}: read_code path={path} start={} for more)", first + offset as i64, last + 1));
            }
        } else if next < all {
            push_line(out, &format!("({} more {} not shown: call again with offset={next}, or narrow the request)", all - next, self.noun));
        }
        if next >= all {
            if offset > 0 && count == 0 {
                push_line(out, &format!("(no more {}: {all} in all)", self.noun));
            }
            push_line(out, tail);
        }
    }

    /// The text with the items from `offset` on that fit `room` bytes (at least one; one longer
    /// than `max_bytes` is cut to fit `room`), how many were shown, and whether one was cut.
    fn render(&self, max_bytes: usize, room: usize, offset: usize) -> (String, usize, bool) {
        let mut out = self.head.clone();
        let push = push_line;
        let (mut count, mut cut) = (0, false);
        for item in self.items.iter().skip(offset) {
            if count > 0 && out.len() + item.len() + 1 > room {
                break;
            }
            let before = out.len();
            push(&mut out, item);
            count += 1;
            if out.len() > max_bytes {
                let mut at = room.saturating_sub(CUT_ITEM.len() + 1).max(before);
                while !out.is_char_boundary(at) {
                    at -= 1;
                }
                out.truncate(at);
                push(&mut out, CUT_ITEM);
                cut = true;
                break;
            }
        }
        self.close(&mut out, offset, count, &self.tail);
        (out, count, cut)
    }
}

/// `part` on a line of its own after `out`; an empty part adds nothing.
fn push_line(out: &mut String, part: &str) {
    if !out.is_empty() && !part.is_empty() {
        out.push('\n');
    }
    out.push_str(part);
}

impl Answer {
    /// The repository files whose indexed content or positions this answer shows. A line range
    /// and a structural search read the files themselves and cite none.
    pub fn cited(&self) -> Vec<&str> {
        fn rows(rows: &[ChunkRow]) -> Vec<&str> {
            rows.iter().map(|r| r.path.as_str()).collect()
        }
        match self {
            Answer::Hits { hits, .. } | Answer::Callers { hits, .. } => hits.iter().map(|h| h.path.as_str()).collect(),
            Answer::Callees { resolved, from, .. } => resolved.iter().map(|h| h.path.as_str()).chain(from.iter().map(String::as_str)).collect(),
            Answer::Grep { groups, .. } => groups.iter().map(|g| g.path.as_str()).collect(),
            Answer::Definitions(defs, _) => defs.iter().map(|(c, ..)| c.path.as_str()).collect(),
            Answer::Outline { path, .. } | Answer::Deps { path, .. } => vec![path.as_str()],
            Answer::Rdeps { rows, .. } => rows.iter().map(|r| r.0.as_str()).collect(),
            Answer::Refs { refs, .. } => rows(&refs.definitions).into_iter().chain(refs.groups.iter().map(|g| g.path.as_str())).collect(),
            Answer::Resolved { refs, .. } => rows(&refs.definitions).into_iter().chain(refs.occurrences.iter().map(|o| o.path.as_str())).collect(),
            Answer::Similar(v) => v.iter().map(|h| h.0.path.as_str()).collect(),
            Answer::Dupes(groups, _) => groups.iter().flat_map(|g| g.members.iter().map(|m| m.0.as_str())).collect(),
            Answer::Impact(i) => i.cited(),
            Answer::Map(files) => files.iter().map(|f| f.path.as_str()).collect(),
            Answer::Path(p) => [&p.from, &p.to].into_iter().chain(p.steps.iter().map(|s| &s.to)).map(|h| h.path.as_str()).collect(),
            Answer::Dead(d) => d.dead.iter().chain(d.undecided.iter().map(|u| &u.0)).map(|s| s.path.as_str()).collect(),
            Answer::Read { .. } | Answer::Captures(..) | Answer::Reindexed(_) | Answer::Files(..) => Vec::new(),
        }
    }

    /// Nothing was found (the CLI's exit code 1).
    pub fn is_empty(&self) -> bool {
        match self {
            Answer::Hits { hits, .. } | Answer::Callers { hits, .. } => hits.is_empty(),
            Answer::Callees { resolved, external, .. } => resolved.is_empty() && external.is_empty(),
            Answer::Grep { groups, .. } => groups.is_empty(),
            Answer::Read { lines, .. } => lines.is_empty(),
            Answer::Definitions(defs, _) => defs.is_empty(),
            Answer::Outline { rows, .. } => rows.is_empty(),
            Answer::Deps { deps, .. } => deps.is_empty(),
            Answer::Rdeps { rows, .. } => rows.is_empty(),
            Answer::Refs { refs, .. } => refs.is_empty(),
            Answer::Resolved { refs, only, .. } => match only {
                Some(_) => false,
                None => refs.definitions.is_empty() && refs.occurrences.is_empty() && refs.notes.is_empty(),
            },
            Answer::Similar(v) => v.is_empty(),
            Answer::Dupes(v, _) => v.is_empty(),
            Answer::Captures(v, _) => v.is_empty(),
            Answer::Map(files) => files.is_empty(),
            Answer::Path(p) => !p.found,
            Answer::Dead(d) => d.dead.is_empty() && d.undecided.is_empty(),
            Answer::Reindexed(_) => false,
            Answer::Impact(i) => i.is_empty(),
            Answer::Files(v, _) => v.is_empty(),
        }
    }

    /// The answer as text: one item per line or block, and a sentence when there is nothing.
    pub fn text(&self) -> String {
        self.text_within(usize::MAX, 0)
    }

    /// The answer as text of `max_bytes` at most: whole items from item `offset` on, then a line
    /// saying how many are left and how to ask for them. A harness cuts a tool result that is
    /// too long for it (Codex at 10,000 tokens, from the middle); cutting here keeps whole items
    /// and tells the agent what to do next. Only a budget smaller than one item and that line
    /// together is exceeded.
    pub fn text_within(&self, max_bytes: usize, offset: usize) -> String {
        self.text_as(max_bytes, offset, Form::Detailed)
    }

    /// `text_within` in either form.
    pub fn text_as(&self, max_bytes: usize, offset: usize, form: Form) -> String {
        let mut parts = self.parts();
        let briefs = parts.brief.as_ref().map(Vec::len);
        // a concise form that does not line up with the items would page other items
        debug_assert!(briefs.is_none_or(|n| n == parts.items.len()), "the concise form has another number of items");
        if briefs.is_some_and(|n| n != parts.items.len()) {
            parts.brief = None;
        }
        parts.within(max_bytes, offset, form)
    }

    fn parts(&self) -> Parts {
        let lines = |text: String, noun: &'static str| Parts { items: text.lines().map(str::to_string).collect(), noun, ..Parts::default() };
        let nothing = |sentence: String| Parts { head: sentence, ..Parts::default() };
        let hits_brief = |hits: &[Hit]| Some(hits.iter().map(|h| vec![Brief::at(&h.path, h.start, h.end, &named(hit_name(h)))]).collect());
        match self {
            Answer::Hits { hits, .. } if hits.is_empty() => nothing("(no results)".to_string()),
            Answer::Hits { hits, words, snippet, stopped } => Parts {
                items: hit_blocks(hits, words, *snippet, false),
                tail: stop_line(*stopped, "results"),
                noun: "results",
                brief: hits_brief(hits),
                ..Parts::default()
            },
            Answer::Callers { hits, .. } if hits.is_empty() => nothing("(no results)".to_string()),
            Answer::Callers { hits, undecided, stopped } => Parts {
                brief: hits_brief(hits),
                items: hit_blocks(hits, &[], false, false),
                tail: joined(
                    match *undecided {
                        0 => String::new(),
                        n if n == hits.len() => {
                            "(the resolver could not tell whether any of these calls this definition or another of the same name)".to_string()
                        }
                        n => format!("({n} of these call a definition of that name the resolver could not identify: it may be another one)"),
                    },
                    stop_line(*stopped, "results"),
                ),
                noun: "results",
                ..Parts::default()
            },
            Answer::Callees { resolved, external, stopped, .. } => Parts {
                head: if resolved.is_empty() { "(no results)".to_string() } else { String::new() },
                brief: hits_brief(resolved),
                brief_tail: Some(joined(
                    match external.len() {
                        0 => String::new(),
                        n => format!("({n} external {}: response_format detailed names them)", if n == 1 { "callee" } else { "callees" }),
                    },
                    stop_line(*stopped, "callees"),
                )),
                items: hit_blocks(resolved, &[], false, false),
                tail: joined(
                    if external.is_empty() {
                        String::new()
                    } else {
                        let more = external.len().saturating_sub(EXTERNAL_CALLEES);
                        let listed = external.iter().take(EXTERNAL_CALLEES).map(|e| shown(e)).collect::<Vec<_>>().join(", ");
                        format!("external: {listed}{}", if more > 0 { format!(" (and {more} more)") } else { String::new() })
                    },
                    stop_line(*stopped, "callees"),
                ),
                noun: "callees",
                ..Parts::default()
            },
            Answer::Grep { groups, stopped_at } => {
                let lines: usize = groups.iter().map(|g| g.lines.len()).sum();
                let stopped = stopped_at.map(|max| format!(" (stopped at {max} matching lines: narrow the pattern or raise max_results)")).unwrap_or_default();
                Parts {
                    head: format!("{lines} matching lines in {} symbols{stopped}", groups.len()),
                    items: groups.iter().map(crate::intel::group_text).collect(),
                    noun: "symbols",
                    brief: Some(groups.iter().map(|g| group_brief(g, "")).collect()),
                    ..Parts::default()
                }
            }
            Answer::Read { path, total: Some(0), .. } => nothing(format!("{} is empty", shown(path))),
            Answer::Read { path, lines, start, total: Some(total), .. } if lines.is_empty() => {
                nothing(format!("{} has {total} lines: start={start} is past the end", shown(path)))
            }
            Answer::Read { path, lines, start, total: None, .. } if lines.is_empty() => nothing(format!("{}: no lines from start={start}", shown(path))),
            Answer::Read { path, lines, start, total, defs } => Parts {
                items: lines.clone(),
                noun: "lines",
                file: Some((path.clone(), *start, *total)),
                brief: Some(
                    (*start..)
                        .zip(lines)
                        .map(|(n, line)| {
                            defs.iter().find(|d| d.start == n).map(|d| Brief::text(format!("{}-{}  {}", d.start, d.end, code_of(line)))).into_iter().collect()
                        })
                        .collect(),
                ),
                ..Parts::default()
            },
            Answer::Definitions(defs, stopped) => Parts {
                items: defs
                    .iter()
                    .map(|(c, text, _)| format!("{}:{}-{}  [{}] {}\n{text}", shown(&c.path), c.start, c.end, c.kind, shown(symbol_name(c))))
                    .collect(),
                tail: stop_line(*stopped, "definitions"),
                noun: "definitions",
                brief: Some(
                    defs.iter()
                        .map(|(c, text, members)| {
                            let line = |n: i64| text.lines().nth((n - c.start) as usize).filter(|_| n >= c.start).map(code_of);
                            let mut out = vec![Brief::at(&c.path, c.start, c.end, &named(symbol_name(c)))];
                            out.extend(line(c.start).map(|l| Brief::text(format!("  {l}"))));
                            out.extend(members.iter().map(|m| {
                                let code = line(m.start).map_or_else(|| named(sym_name(m)).into_owned(), str::to_string);
                                Brief::text(format!("  {}-{}  {code}", m.start, m.end))
                            }));
                            out
                        })
                        .collect(),
                ),
                ..Parts::default()
            },
            Answer::Outline { path, rows } if rows.is_empty() => nothing(format!("no symbols in {} (not indexed or no definitions)", echo(path))),
            Answer::Outline { rows, .. } => Parts {
                items: rows
                    .iter()
                    .map(|r| format!("{:>5}-{:<5} {}{:<9} {}", r.start, r.end, "  ".repeat(r.qualname.matches('.').count()), r.kind, shown(&r.qualname)))
                    .collect(),
                noun: "symbols",
                brief: Some(
                    rows.iter()
                        .map(|r| {
                            let depth = r.qualname.matches('.').count();
                            let name = r.qualname.rsplit('.').next().filter(|n| !n.is_empty()).unwrap_or(&r.name);
                            vec![Brief::text(format!("{}{} {}", " ".repeat(depth), r.start, shown(name)))]
                        })
                        .collect(),
                ),
                ..Parts::default()
            },
            Answer::Deps { path, deps } if deps.is_empty() => nothing(format!("no imports recorded for {}", echo(path))),
            Answer::Deps { path, deps } => Parts {
                items: deps
                    .iter()
                    .map(|d| {
                        format!(
                            "{}:{}  {}{}",
                            shown(path),
                            d.line,
                            shown(&d.module),
                            d.resolved.as_ref().map(|r| format!("  -> {}", shown(r))).unwrap_or_default()
                        )
                    })
                    .collect(),
                noun: "imports",
                brief: {
                    let mut seen = std::collections::HashSet::new();
                    Some(
                        deps.iter()
                            .map(|d| match &d.resolved {
                                Some(r) if seen.insert(r.as_str()) => vec![Brief::path(r)],
                                None if seen.insert(d.module.as_str()) => vec![Brief::text(shown(&d.module))],
                                _ => Vec::new(),
                            })
                            .collect(),
                    )
                },
                ..Parts::default()
            },
            Answer::Rdeps { target, rows, unresolved: 0 } if rows.is_empty() => nothing(format!("nothing imports {}", echo(target))),
            Answer::Rdeps { target, rows, unresolved } if rows.is_empty() => nothing(format!(
                "no import resolves to {}, but {unresolved} {} could not be resolved and may name it",
                echo(target),
                if *unresolved == 1 { "import" } else { "imports" }
            )),
            Answer::Rdeps { rows, unresolved, .. } => Parts {
                items: rows.iter().map(|(p, l, m)| format!("{}:{l}  {}", shown(p), shown(m))).collect(),
                tail: match unresolved {
                    0 => String::new(),
                    n => format!("({n} more {} could not be resolved and may name it)", if *n == 1 { "import" } else { "imports" }),
                },
                noun: "importers",
                brief: {
                    let mut seen = std::collections::HashSet::new();
                    Some(rows.iter().map(|(p, ..)| if seen.insert(p.as_str()) { vec![Brief::path(p)] } else { Vec::new() }).collect())
                },
                ..Parts::default()
            },
            Answer::Refs { refs, max_results, .. } => {
                if refs.is_empty() {
                    nothing("(no results)".to_string())
                } else {
                    Parts {
                        tail: stopped_at(refs.truncated, *max_results),
                        brief: Some(refs_brief(refs)),
                        ..lines(crate::intel::references_render(refs), "lines")
                    }
                }
            }
            Answer::Resolved { .. } if self.is_empty() => nothing("(no results)".to_string()),
            Answer::Resolved { refs, only, max_results, .. } => Parts {
                tail: stopped_at(refs.truncated, *max_results),
                brief: Some(resolved_brief(refs, *only)),
                ..lines(crate::resolve::resolved_text(refs, *only), "lines")
            },
            Answer::Similar(v) if v.is_empty() => nothing("(no results)".to_string()),
            Answer::Similar(v) => Parts {
                items: v
                    .iter()
                    .map(|(h, cos, jac)| format!("{:.3} cos  {:.2} jaccard  {}  [{}] {}", cos, jac, crate::fmt::loc(h), h.kind, shown(&h.qualname)))
                    .collect(),
                noun: "results",
                brief: Some(v.iter().map(|(h, ..)| vec![Brief::at(&h.path, h.start, h.end, &named(hit_name(h)))]).collect()),
                ..Parts::default()
            },
            Answer::Dupes(groups, _) if groups.is_empty() => nothing("no duplicates found".to_string()),
            Answer::Dupes(groups, stopped) => Parts {
                items: groups
                    .iter()
                    .map(|g| {
                        let mut out = format!("{} ({} tokens, similarity {:.2})", g.kind, g.tokens, g.similarity);
                        for (p, q, a, b) in &g.members {
                            out.push_str(&format!("\n    {}:{a}-{b}  {}", shown(p), shown(q)));
                        }
                        out
                    })
                    .collect(),
                tail: stop_line(*stopped, "groups"),
                noun: "groups",
                brief: Some(
                    groups
                        .iter()
                        .map(|g| {
                            // one name for members that all have it
                            let one = g.members.windows(2).all(|w| w[0].1 == w[1].1);
                            let mut line = Brief::text(format!("{:.2}", g.similarity));
                            for (p, q, a, b) in &g.members {
                                line = line.then(" ").then_at(p, *a, *b);
                                if !one {
                                    line = line.then(format!(" {}", named(q)));
                                }
                            }
                            if let Some((_, q, ..)) = g.members.first().filter(|_| one) {
                                line = line.then(format!(" {}", named(q)));
                            }
                            vec![line]
                        })
                        .collect(),
                ),
                ..Parts::default()
            },
            Answer::Captures(caps, _) if caps.is_empty() => nothing("no matches".to_string()),
            Answer::Captures(caps, stopped) => Parts {
                tail: stop_line(*stopped, "matches"),
                items: caps.iter().map(capture_line).collect(),
                noun: "matches",
                brief: Some(
                    caps.iter()
                        .map(|c| {
                            vec![Brief::default().then_line(&c.path, format!(":{}:{}", c.line, c.column)).then(format!(" @{} {}", c.capture, shown(&c.text)))]
                        })
                        .collect(),
                ),
                ..Parts::default()
            },
            Answer::Map(files) if files.is_empty() => nothing("(no file with a definition)".to_string()),
            Answer::Map(files) => Parts {
                items: files
                    .iter()
                    .enumerate()
                    .map(|(i, f)| {
                        let mut out = format!("{}  (rank {}, score {:.4})", shown(&f.path), i + 1, f.score);
                        for (d, calls) in &f.definitions {
                            let calls = match calls {
                                0 => String::new(),
                                1 => "  (1 call)".to_string(),
                                n => format!("  ({n} calls)"),
                            };
                            let name = if d.qualname.is_empty() { &d.name } else { &d.qualname };
                            out.push_str(&format!("\n  {}-{}  [{}] {}{calls}", d.start, d.end, d.kind, shown(name)));
                        }
                        out
                    })
                    .collect(),
                noun: "files",
                brief: Some(
                    files
                        .iter()
                        .map(|f| {
                            let mut out = vec![Brief::path(&f.path)];
                            out.extend(f.definitions.iter().map(|(d, _)| Brief::text(format!("  {}-{} {}", d.start, d.end, named(sym_name(d))))));
                            out
                        })
                        .collect(),
                ),
                ..Parts::default()
            },
            Answer::Path(p) if !p.found => {
                let ends = format!("from {} to {}", hit_line(&p.from), hit_line(&p.to));
                nothing(if p.stopped {
                    format!("(no call path {ends} within {} {}: raise depth to search further)", p.depth, if p.depth == 1 { "call" } else { "calls" })
                } else {
                    format!("(no call path {ends})")
                })
            }
            Answer::Path(p) => Parts {
                items: std::iter::once(hit_line(&p.from))
                    .chain(p.steps.iter().map(|s| {
                        let guess = if s.tied { "" } else { "  (by name: the resolver did not tie this call)" };
                        format!("  {}:{}  calls {}{guess}", shown(&s.path), s.line, hit_line(&s.to))
                    }))
                    .collect(),
                noun: "steps",
                brief: Some(
                    std::iter::once(vec![Brief::at(&p.from.path, p.from.start, p.from.end, &named(hit_name(&p.from)))])
                        .chain(p.steps.iter().map(|s| {
                            let to = &s.to;
                            let guess = if s.tied { "" } else { " (by name)" };
                            vec![Brief::text("  ")
                                .then_line(&s.path, format!(":{}", s.line))
                                .then(" -> ")
                                .then_at(&to.path, to.start, to.end)
                                .then(format!(" {}{guess}", named(hit_name(to))))]
                        }))
                        .collect(),
                ),
                ..Parts::default()
            },
            Answer::Dead(_) if self.is_empty() => nothing("(no dead code found)".to_string()),
            Answer::Dead(d) => {
                let line = |s: &crate::index::Symbol| format!("{}:{}-{}  [{}] {}", shown(&s.path), s.start, s.end, s.kind, shown(sym_name(s)));
                let brief = |s: &crate::index::Symbol, mark: &str| vec![Brief::at(&s.path, s.start, s.end, &format!("{}{mark}", named(sym_name(s))))];
                Parts {
                    items: d.dead.iter().map(line).chain(d.undecided.iter().map(|(s, why)| format!("{}  (undecided: {why})", line(s)))).collect(),
                    tail: format!("({} dead, {} undecided)", d.dead.len(), d.undecided.len()),
                    noun: "definitions",
                    brief: Some(d.dead.iter().map(|s| brief(s, "")).chain(d.undecided.iter().map(|(s, _)| brief(s, "?"))).collect()),
                    ..Parts::default()
                }
            }
            Answer::Reindexed(st) => nothing(format!("{} files changed, {} removed, {} chunks", st.files_changed, st.files_removed, st.chunks)),
            Answer::Impact(i) if i.is_empty() => nothing(format!("no changes: {}", i.head())),
            Answer::Impact(i) => {
                Parts { head: i.head(), items: i.lines(), tail: i.stop_line(), noun: "lines", brief: Some(impact_brief(i)), ..Parts::default() }
            }
            Answer::Files(v, _) if v.is_empty() => nothing("no file matches".to_string()),
            Answer::Files(v, stopped) => Parts {
                items: v.iter().map(|h| shown(&h.path).into_owned()).collect(),
                tail: stop_line(*stopped, "files"),
                noun: "files",
                brief: Some(v.iter().map(|h| vec![Brief::path(&h.path)]).collect()),
                by_directory: true,
                ..Parts::default()
            },
        }
    }

    /// The answer for a client that reads structured results, sent beside a text of `text_len`
    /// bytes that starts at item `offset`: the whole JSON form when both together fit one and a
    /// half times `max_bytes`, else `null` (the text then pages through the answer).
    pub fn structured(&self, text_len: usize, max_bytes: usize, offset: usize) -> Value {
        let mut v = self.envelope();
        let complete = offset == 0 && text_len + v["result"].to_string().len() <= max_bytes.saturating_add(max_bytes / 2);
        v["complete"] = json!(complete);
        if !complete {
            v["result"] = Value::Null;
        }
        v
    }

    /// The one JSON form every front end gives: `{"schema", "result"}`, and `stopped_at` when
    /// the answer stopped at its limit with more left.
    pub fn envelope(&self) -> Value {
        envelope(self.json(), self.stopped())
    }

    /// The limit the answer stopped at, when there were more.
    pub fn stopped(&self) -> Option<Stop> {
        match self {
            Answer::Hits { stopped, .. } | Answer::Callers { stopped, .. } | Answer::Callees { stopped, .. } => *stopped,
            Answer::Definitions(_, stopped) | Answer::Captures(_, stopped) | Answer::Dupes(_, stopped) | Answer::Files(_, stopped) => *stopped,
            Answer::Impact(i) if i.stopped => Some(Stop { at: crate::impact::MAX_CALLERS, how: "pass a smaller depth" }),
            _ => None,
        }
    }

    /// The line the text ends with when the answer stopped at its limit, else empty.
    pub fn stop_note(&self) -> String {
        match self {
            Answer::Refs { refs, max_results, .. } => stopped_at(refs.truncated, *max_results),
            Answer::Resolved { refs, max_results, .. } => stopped_at(refs.truncated, *max_results),
            Answer::Impact(i) => i.stop_line(),
            _ => self.stopped().map(|s| stop_line(Some(s), self.parts().noun)).unwrap_or_default(),
        }
    }

    /// The answer as JSON, the shape `--json` prints.
    pub fn json(&self) -> Value {
        match self {
            Answer::Hits { hits, .. } | Answer::Callers { hits, .. } => hits_json(hits),
            Answer::Callees { resolved, external, .. } => json!({"resolved": hits_json(resolved), "external": external}),
            Answer::Grep { groups, stopped_at } => json!({
                "groups": groups.iter().map(|g| with_note(json!({
                    "symbol": g.symbol.as_ref().map(|c| json!({"path": c.path, "start": c.start, "end": c.end, "kind": c.kind, "name": symbol_name(c)})),
                    "path": g.path,
                    "lines": g.lines.iter().map(|h| json!({"line": h.line, "text": h.text})).collect::<Vec<_>>(),
                }), g)).collect::<Vec<_>>(),
                "stopped_at": stopped_at,
            }),
            Answer::Read { lines, start, total, .. } => {
                json!({"text": lines.join("\n"), "start": start, "end": start + lines.len() as i64 - 1, "file_lines": total})
            }
            Answer::Definitions(defs, _) => json!({
                "definitions": defs.iter().map(|(c, text, _)| {
                    let mut v = chunk_json(c);
                    v["text"] = json!(text);
                    v
                }).collect::<Vec<_>>(),
            }),
            Answer::Outline { rows, .. } => {
                rows.iter().map(|r| json!({"kind": r.kind, "name": r.name, "qualname": r.qualname, "start": r.start, "end": r.end})).collect()
            }
            Answer::Deps { deps, .. } => serde_json::to_value(deps).unwrap_or_default(),
            Answer::Rdeps { rows, .. } => rows.iter().map(|(p, l, m)| json!({"path": p, "line": l, "module": m})).collect(),
            Answer::Refs { name, refs, .. } => json!({
                "name": name,
                "definitions": refs.definitions.iter().map(chunk_json).collect::<Vec<_>>(),
                "callers": hits_json(&refs.callers),
                "references": refs.groups.iter().map(|g| with_note(json!({
                    "symbol": g.symbol.as_ref().map(chunk_json),
                    "path": g.path,
                    "lines": g.lines.iter().map(|h| json!({"line": h.line, "column": h.column, "text": h.text})).collect::<Vec<_>>(),
                }), g)).collect::<Vec<_>>(),
                "truncated": refs.truncated,
            }),
            Answer::Resolved { name, refs, only, .. } => {
                // a use on a long line carries the part of the line around it, and says so
                let line_of = |o: &crate::resolve::Occurrence, mut v: Value| {
                    let (text, cut) = o.shown_line();
                    v["text"] = json!(if cut { text.as_ref() } else { &*o.text });
                    if cut {
                        v["cut"] = json!(true);
                    }
                    v
                };
                let occurrence =
                    |o: &crate::resolve::Occurrence| line_of(o, json!({"path": o.path, "line": o.line, "column": o.column, "via": o.resolution.ok().map(|x| x.1)}));
                let mut v = json!({
                    "name": name,
                    "definitions": refs.definitions.iter().filter(|d| only.is_none_or(|id| d.id == id)).map(|c| json!({
                        "path": c.path, "start": c.start, "end": c.end, "kind": c.kind, "qualname": c.qualname,
                        "references": refs.of(c.id).map(occurrence).collect::<Vec<_>>(),
                    })).collect::<Vec<_>>(),
                    "truncated": refs.truncated,
                });
                if only.is_none() {
                    v["unresolved"] = refs
                        .unresolved()
                        .map(|o| line_of(o, json!({"path": o.path, "line": o.line, "column": o.column, "reason": o.resolution.err()})))
                        .collect();
                }
                if !refs.notes.is_empty() {
                    v["notes"] = refs.notes.iter().map(|(path, note)| json!({"path": path, "note": note})).collect();
                }
                v
            }
            Answer::Similar(v) => v
                .iter()
                .map(|(h, cos, jac)| json!({"path": h.path, "start": h.start, "end": h.end, "kind": h.kind, "qualname": h.qualname, "cosine": cos, "jaccard": jac}))
                .collect(),
            Answer::Dupes(groups, _) => serde_json::to_value(groups).unwrap_or_default(),
            Answer::Captures(caps, _) => serde_json::to_value(caps).unwrap_or_default(),
            Answer::Map(files) => files
                .iter()
                .enumerate()
                .map(|(i, f)| {
                    let defs: Vec<Value> = f
                        .definitions
                        .iter()
                        .map(|(d, calls)| {
                            json!({"id": format!("{}:{}-{}", d.path, d.start, d.end), "path": d.path, "start": d.start, "end": d.end, "kind": d.kind, "qualname": d.qualname, "calls": calls})
                        })
                        .collect();
                    json!({"path": f.path, "rank": i + 1, "score": f.score, "definitions": defs})
                })
                .collect(),
            Answer::Path(p) => {
                let hit = |h: &Hit| hits_json(std::slice::from_ref(h))[0].clone();
                json!({
                    "from": hit(&p.from), "to": hit(&p.to), "found": p.found, "depth": p.depth, "stopped": p.stopped,
                    "steps": p.steps.iter().map(|s| json!({"path": s.path, "line": s.line, "definition": hit(&s.to), "tied": s.tied})).collect::<Vec<_>>(),
                })
            }
            Answer::Dead(d) => {
                let one = |s: &crate::index::Symbol| {
                    json!({"id": format!("{}:{}-{}", s.path, s.start, s.end), "path": s.path, "start": s.start, "end": s.end, "kind": s.kind, "name": s.name, "qualname": sym_name(s)})
                };
                json!({
                    "dead": d.dead.iter().map(one).collect::<Vec<_>>(),
                    "undecided": d.undecided.iter().map(|(s, why)| {
                        let mut v = one(s);
                        v["reason"] = json!(why);
                        v
                    }).collect::<Vec<_>>(),
                })
            }
            Answer::Reindexed(st) => json!({"files_changed": st.files_changed, "files_removed": st.files_removed, "chunks": st.chunks}),
            Answer::Impact(i) => i.json(),
            Answer::Files(v, _) => serde_json::to_value(v).unwrap_or_default(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn on_windows_a_plain_path_is_under_the_root_canonicalize_gave() {
        let root = r"\\?\C:\proj";
        for (path, is_under) in [
            (r"C:\proj\a.py", true),
            ("c:/PROJ/sub/a.py", true),
            (r"\\?\C:\proj\a.py", true),
            (r"C:\proj", true),
            (r"C:\proj2\a.py", false),
            (r"C:\a.py", false),
            (r"D:\proj\a.py", false),
            (r"\\server\share\proj\a.py", false),
        ] {
            assert_eq!(under(path, root), is_under, "{path}");
        }
        let share = r"\\?\UNC\server\share\repo";
        assert!(under(r"\\server\share\repo\a.py", share));
        assert!(under(r"\\?\UNC\server\share\repo\a.py", share));
        assert!(!under(r"\\other\share\repo\a.py", share));
        // a repository at the root of a drive
        assert!(under(r"C:\a.py", r"\\?\C:\"));
    }

    #[test]
