        let src = "\"\"\"Mod doc.\"\"\"\nimport os\n\n\nclass A:\n    \"\"\"Doc A.\"\"\"\n\n    def m(self, x):\n        '''Do m.\n\n        more'''\n        return os.path.join(x)\n\n\ndef f():\n    return A().m(1)\n";
