                ("t.ts", "a.size()", "size", "t.ts Big.size"),
                ("t.ts", "b.size()", "size", "t.ts Base.size"),
                ("t.ts", "c.size()", "size", "t.ts Base.size"),
                ("p.py", "a.size()", "size", "p.py Big.size"),
                ("p.py", "c.size()", "size", "p.py Base.size"),
                ("g/g.go", "a.Size()", "Size", "g/g.go Big.Size"),
