    #[test]
    fn java_rules() {
        let (shapes, app) = ("src/main/java/com/acme/shapes", "src/main/java/com/acme/app");
        let files: Vec<(String, &str)> = vec![
            (format!("{shapes}/Shape.java"), JAVA_SHAPE),
            (format!("{shapes}/Circle.java"), JAVA_CIRCLE),
            (format!("{shapes}/Square.java"), "package com.acme.shapes;\n\npublic class Square implements Shape {\n    public double area() {\n        return 4;\n    }\n\n    public String toString() {\n        return label();\n    }\n}\n"),
            (format!("{shapes}/Report.java"), "package com.acme.shapes;\n\npublic record Report(double value) {\n    public boolean ok() {\n        return value > 0;\n    }\n}\n"),
            (format!("{app}/Util.java"), "package com.acme.app;\n\npublic class Util {\n    public static int scale(int x) {\n        return x * 2;\n    }\n\n    public static int scale(int x, int y) {\n        return x * y;\n    }\n\n    public static void log(String s) {}\n}\n"),
            (format!("{app}/Base.java"), "package com.acme.app;\n\npublic class Base {\n    void inherited() {}\n}\n"),
            (format!("{app}/Main.java"), JAVA_MAIN),
        ];
        let files: Vec<(&str, &str)> = files.iter().map(|(p, b)| (p.as_str(), *b)).collect();
        let (root, s) = indexed("java", &files);
        let mut rv = Resolver::new(&s.ix).unwrap();
        // (file, text the name is in, name, "file:line qualname (how)" or why there is none)
        let checks: &[(&str, &str, &str, &str)] = &[
            ("Main", "import com.acme.shapes.Circle;", "Circle", "Circle:5 Circle (import)"),
            ("Main", "Util.scale;", "scale", "Util:4 Util.scale (overload)"),
            ("Main", "import java.util.List;", "List", "external"),
            ("Main", "import com.acme.shapes.Shape;", "acme", "package"),
            ("Main", "extends Base", "Base", "Base:3 Base (type)"),
            ("Main", "private Circle held", "Circle", "Circle:5 Circle (type)"),
            ("Main", "s.area()", "area", "Shape:4 Shape.area (member)"),
            ("Main", "given.label()", "label", "Shape:6 Shape.label (member)"),
            ("Main", "given.hashCode()", "hashCode", "external"),
            ("Main", "new Circle(2)", "Circle", "Circle:5 Circle (type)"),
            ("Main", "c.area()", "area", "Circle:13 Circle.area (member)"),
            ("Main", "held.area()", "area", "Circle:13 Circle.area (member)"),
            ("Main", "this.held.summary()", "summary", "Circle:21 Circle.summary (member)"),
            ("Main", "summary().ok()", "ok", "Report:4 Report.ok (member)"),
            ("Main", "new Square().area()", "area", "Square:4 Square.area (member)"),
            ("Main", "note(\"a\");", "note", "Main:14 Main.note (member)"),
            ("Main", "note(\"a\", 1)", "note", "Main:16 Main.note (member)"),
            ("Main", "this.note(\"b\")", "note", "Main:14 Main.note (member)"),
            ("Main", "this::note", "note", "Main:14 Main.note (overload)"),
            ("Main", "scale(2);", "scale", "Util:4 Util.scale (import)"),
            ("Main", "scale(2, 3)", "scale", "Util:8 Util.scale (import)"),
            ("Main", "log(\"x\")", "log", "Util:12 Util.log (import)"),
            ("Main", "x.area()", "area", "receiver"),
            ("Main", "shapes.size()", "size", "external"),
            ("Main", "each.area()", "area", "Shape:4 Shape.area (member)"),
            ("Main", "Circle::unit", "unit", "Circle:17 Circle.unit (member)"),
            ("Main", "note(\"x\")", "note", "Main:14 Main.note (member)"),
            ("Main", "helper();", "helper", "Main:70 Main.helper (member)"),
            ("Main", "    inherited();", "inherited", "Base:4 Base.inherited (member)"),
            ("Main", "e.getMessage()", "getMessage", "external"),
            ("Main", "k.area()", "area", "Circle:13 Circle.area (member)"),
            ("Main", "Circle.Inner()", "Inner", "Circle:30 Circle.Inner (qualified)"),
            ("Main", "Inner().depth()", "depth", "Circle:31 Circle.Inner.depth (member)"),
            ("Main", "SMALL.big()", "big", "Circle:37 Circle.Kind.big (member)"),
            ("Main", "SMALL.big()", "SMALL", "field or key"),
            ("Main", "int area = 3", "area", "local variable"),
            ("Main", "t.length()", "length", "external"),
            ("Main", "super.inherited()", "inherited", "Base:4 Base.inherited (super)"),
            ("Main", "shapes.Circle.unit()", "unit", "Circle:17 Circle.unit (member)"),
            ("Main", "shapes.Circle.unit()", "Circle", "Circle:5 Circle (qualified)"),
            ("Main", "T pick(T x)", "T", "type parameter"),
            ("Main", "return x;", "x", "local variable"),
            ("Circle", "names.add(label())", "add", "external"),
            ("Circle", "names.add(label())", "label", "Shape:6 Shape.label (member)"),
            ("Circle", "last.ok()", "ok", "Report:4 Report.ok (member)"),
            ("Circle", "Math.PI", "PI", "external"),
            ("Circle", "new Report(area())", "area", "Circle:13 Circle.area (member)"),
            ("Circle", "this == LARGE", "LARGE", "field or key"),
            ("Circle", "this.r = r", "r", "field or key"),
            ("Circle", "= r;", "r", "local variable"),
            ("Square", "return label();", "label", "Shape:6 Shape.label (member)"),
            ("Shape", "+ area()", "area", "Shape:4 Shape.area (member)"),
            ("Report", "value > 0", "value", "field or key"),
        ];
        let mut wrong = Vec::new();
        let file_of = |short: &str| files.iter().find(|(p, _)| p.ends_with(&format!("/{short}.java"))).unwrap();
        for (short, needle, name, want) in checks {
            let (path, src) = file_of(short);
            let (row, l) = src.lines().enumerate().find(|(_, l)| l.contains(needle)).unwrap_or_else(|| panic!("{needle:?} not in {short}"));
            let col = l.find(needle).unwrap() + needle.find(name).unwrap();
            let got = match rv.resolve_at(path, row as u64 + 1, col, name) {
                Ok((id, how)) => {
                    let c = s.ix.chunk(id).unwrap().unwrap();
                    let file = c.path.rsplit('/').next().unwrap().trim_end_matches(".java").to_string();
                    format!("{file}:{} {} ({how})", c.start, c.qualname)
                }
                Err(e) => e.to_string(),
            };
            if got != *want {
                wrong.push(format!("{short}: {needle} -> {got}, want {want}"));
            }
        }
        drop(s);
        let _ = std::fs::remove_dir_all(&root);
        assert!(wrong.is_empty(), "{}", wrong.join("\n"));
    }

    #[test]
    fn java_package_declarations() {
        assert_eq!(java_package("// c\n/* d */\n@Generated(\"x(y)\")\npackage a.b ;\nimport c;"), "a.b");
        assert_eq!(java_package("import c;\nclass K {}"), "");
    }

    #[test]
    fn helpers() {
        assert_eq!(strip_generics("Foo<'a, T>.new"), "Foo.new");
        assert_eq!(join("a/b", "../c/./d"), "a/c/d");
        assert_eq!(join("src", "../../lib"), "../lib");
        assert_eq!(
            (py_relative("src/b.py", "..x.y"), py_relative("src/b.py", "...x"), py_relative("src/b.py", ".")),
            ("x/y".into(), "../x".into(), "src".into())
        );
        assert_eq!(Resolver::rust_mod_dir("src/a/b.rs"), "src/a/b");
        assert_eq!(Resolver::rust_mod_dir("src/a/mod.rs"), "src/a");
        assert_eq!(cargo_package_name("[workspace]\nname = \"no\"\n[package]\nname = \"grep-matcher\"\n"), Some("grep-matcher".into()));
    }
}

//! PHP: `namespace` and `use`, classes, traits and their methods, `new` and typed locals and
//! parameters, typed properties, `$this`, `self::`, `static::` and `parent::`, the return type a
//! method declares. A class is looked up by its name in the index and kept when the file that
//! defines it declares the namespace the reference names.

use super::*;

pub(super) struct Php;

impl Rules for Php {
    const GRAMMARS: &'static [&'static str] = &["php"];
    // `.` joins strings: `$a . f()` may call a free function
    const METHODS_ONLY: bool = false;

    fn bindings(n: Node, _path: &str, src: &str, out: &mut Vec<Binding>) -> bool {
        if n.kind() != "namespace_use_declaration" {
            return false;
        }
        let mut prefix = "";
        let mut cur = n.walk();
        for ch in n.named_children(&mut cur) {
            match ch.kind() {
                "namespace_name" => prefix = text(ch, src),
                "namespace_use_clause" => php_use_clause(ch, prefix, src, out),
                "namespace_use_group" => {
                    let mut c2 = ch.walk();
                    for cl in ch.named_children(&mut c2).filter(|c| c.kind() == "namespace_use_clause") {
                        php_use_clause(cl, prefix, src, out);
                    }
                }
                _ => {}
            }
        }
        true
    }

    fn import_site(r: &mut Resolver, _path: &str, _lang: Lang, b: &Binding) -> Resolution {
        r.php_used(&php_full(b)).map(|id| (id, "import"))
    }

    fn occurrence(r: &mut Resolver, _path: &str, fi: &FileInfo, node: Node, name: &str, _line: i64) -> Option<Resolution> {
        Some(r.php_resolve(fi, node, name))
    }

    fn bases(r: &mut Resolver, id: i64, _path: &str, fi: &FileInfo, _d: &Def, _lang: Lang) -> Vec<std::result::Result<i64, &'static str>> {
        r.php_bases(fi, id)
    }

    fn module_files(r: &mut Resolver, _from: &str, module: &str) -> Option<Vec<String>> {
        let id = r.php_used(module.trim_start_matches('\\')).ok()?;
        r.def_row(id).map(|(path, _)| vec![path])
    }

    // a `require` of a path is left to the mapping of paths onto files
    fn reads_import(module: &str) -> bool {
        let name = module.trim_start_matches('\\');
        !name.is_empty() && name.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '\\')
    }

    fn import_files(r: &mut Resolver, from: &str, _fi: &FileInfo, _line: i64, module: &str) -> Option<Vec<String>> {
        Some(Self::module_files(r, from, module).unwrap_or_default())
    }
}

/// The functions whose variables are their own: an arrow function sees the ones around it.
const PHP_FUNCTIONS: &[&str] = &["function_definition", "method_declaration", "anonymous_function"];

fn php_use_clause(cl: Node, prefix: &str, src: &str, out: &mut Vec<Binding>) {
    let mut cur = cl.walk();
    let Some(path) = cl.named_children(&mut cur).find(|c| matches!(c.kind(), "qualified_name" | "name")) else { return };
    let rel = text(path, src);
    let full = if prefix.is_empty() { rel.to_string() } else { format!("{prefix}\\{rel}") };
    let full = full.trim_start_matches('\\');
    let (module, item) = full.rsplit_once('\\').unwrap_or(("", full));
    let last = path.named_child(path.named_child_count().saturating_sub(1) as u32).unwrap_or(path);
    let alias = cl.child_by_field_name("alias");
    let mut sites = vec![last.start_byte()];
    sites.extend(alias.map(|a| a.start_byte()));
    out.push(Binding { local: alias.map_or(item, |a| text(a, src)).to_string(), module: module.to_string(), item: Some(item.to_string()), sites });
}

/// The class names `n` lists (`extends A`, `implements B, C`, `use T;`).
fn php_names<'t>(n: Node<'t>) -> Vec<Node<'t>> {
    let mut cur = n.walk();
    n.named_children(&mut cur).filter(|c| matches!(c.kind(), "name" | "qualified_name" | "relative_name")).collect()
}

/// The full name a `use` binding names.
fn php_full(b: &Binding) -> String {
    let item = b.item.as_deref().unwrap_or("");
    if b.module.is_empty() {
        item.to_string()
    } else {
        format!("{}\\{item}", b.module)
    }
}

/// The namespace that holds 0-based line `row` of the file: the braced `namespace` block around
/// it, else the last `namespace X;` above it, else the global one ("").
fn php_namespace(fi: &FileInfo, row: usize) -> String {
    let Some(tree) = fi.tree.as_ref() else { return String::new() };
    let root = tree.root_node();
    let mut cur = root.walk();
    let mut ns = String::new();
    for c in root.named_children(&mut cur) {
        if c.start_position().row > row {
            break;
        }
        if c.kind() != "namespace_definition" {
            continue;
        }
        let name = c.child_by_field_name("name").map_or("", |n| text(n, &fi.src)).to_string();
        match c.child_by_field_name("body") {
            Some(_) if c.end_position().row >= row => return name,
            Some(_) => ns = String::new(),
            None => ns = name,
        }
    }
    ns
}

/// The full name a class or function name written at `at` stands for: through a `use` that binds
/// its first part, else in the namespace around.
fn php_qualify(fi: &FileInfo, at: Node, written: &str) -> String {
    if let Some(full) = written.strip_prefix('\\') {
        return full.to_string();
    }
    let (first, rest) = match written.split_once('\\') {
        Some((f, r)) => (f, Some(r)),
        None => (written, None),
    };
    if let Some(b) = fi.bindings.iter().find(|b| b.local == first) {
        let base = php_full(b);
        return rest.map_or(base.clone(), |r| format!("{base}\\{r}"));
    }
    let rel = written.strip_prefix("namespace\\").unwrap_or(written);
    let ns = php_namespace(fi, at.start_position().row);
    if ns.is_empty() {
        rel.to_string()
    } else {
        format!("{ns}\\{rel}")
    }
}

/// The variables named `var` in `scope` that are bound before a use sees them: an assignment
/// (its whole span), a `foreach` target or a caught exception (the variable). Not in a nested
/// function or class.
fn php_binders(scope: Node, var: &str, src: &str) -> Vec<(usize, usize)> {
    let (mut out, mut stack) = (Vec::new(), vec![scope]);
    while let Some(n) = stack.pop() {
        match n.kind() {
            "assignment_expression" if n.child_by_field_name("left").is_some_and(|l| l.kind() == "variable_name" && text(l, src) == var) => {
                out.push((n.start_byte(), n.end_byte()));
            }
            // the value of `foreach ($xs as $k => $v)`, after the list it walks
            "variable_name"
                if text(n, src) == var
                    && n.parent().is_some_and(|p| match p.kind() {
                        "foreach_statement" => n.prev_named_sibling().is_some(),
                        "pair" => p.parent().is_some_and(|g| g.kind() == "foreach_statement"),
                        k => k == "catch_clause",
                    }) =>
            {
                out.push((n.start_byte(), n.end_byte()));
            }
            k if n.id() != scope.id() && (PHP_FUNCTIONS.contains(&k) || matches!(k, "arrow_function" | "class_declaration")) => continue,
            _ => {}
        }
        let mut cur = n.walk();
        stack.extend(n.named_children(&mut cur));
    }
    out.sort_unstable_by_key(|&(_, end)| end);
    out
}

impl Resolver<'_> {
    /// The occurrence of `name` at `node`, a `name` node of a PHP file.
    fn php_resolve(&mut self, fi: &FileInfo, node: Node, name: &str) -> Resolution {
        if node.kind() != "name" {
            return Err("keyword");
        }
        let Some(p) = node.parent() else { return Err("not found") };
        match p.kind() {
            // `public $name;` declares a property
            "variable_name" if p.parent().is_some_and(|g| matches!(g.kind(), "property_element" | "property_promotion_parameter")) => {
                return Err("field or key")
            }
            "variable_name" => return Err("local variable"),
            "namespace_name" | "namespace_definition" => return Err("namespace"),
            _ => {}
        }
        // the last part of `A\B\C` stands for the whole name
        let (whole, around) = if matches!(p.kind(), "qualified_name" | "relative_name") { (p, p.parent()) } else { (node, Some(p)) };
        let Some(a) = around else { return Err("not found") };
        let is = |f: &str| a.child_by_field_name(f).map(|c| c.id()) == Some(whole.id());
        match a.kind() {
            "member_call_expression" | "nullsafe_member_call_expression" if is("name") => {
                let obj = a.child_by_field_name("object").ok_or("receiver")?;
                let how = if text(obj, &fi.src) == "$this" { "member" } else { "variable" };
                let owner = self.php_value(fi, obj)?;
                self.php_member(owner, name, how)
            }
            "member_access_expression" | "nullsafe_member_access_expression" if is("name") => Err("field or key"),
            "scoped_call_expression" if is("name") => {
                let scope = a.child_by_field_name("scope").ok_or("receiver")?;
                self.php_static_call(fi, scope, name)
            }
            "class_constant_access_expression" if a.named_child(0).map(|c| c.id()) != Some(whole.id()) => Err("field or key"),
            "function_call_expression" if is("function") => self.php_function(fi, whole),
            "binary_expression" if !is("right") || a.child_by_field_name("operator").is_none_or(|o| o.kind() != "instanceof") => Err("constant"),
            "named_type"
            | "object_creation_expression"
            | "base_clause"
            | "class_interface_clause"
            | "scoped_call_expression"
            | "class_constant_access_expression"
            | "scoped_property_access_expression"
            | "use_declaration"
            | "binary_expression"
            | "attribute" => self.php_type(fi, whole).map(|id| (id, "type")),
            _ => Err("constant"),
        }
    }

    /// `S::name(..)`: a method of the class `S` names, of the class around for `self` and
    /// `static`, of its parent for `parent`, or of the class of the value `S` is.
    fn php_static_call(&mut self, fi: &FileInfo, scope: Node, name: &str) -> Resolution {
        match text(scope, &fi.src).trim() {
            "parent" => {
                let c = self.php_around(fi, scope)?;
                let base = self.php_parent(c)?;
                self.php_member(base, name, "super")
            }
            "self" | "static" => {
                let c = self.php_around(fi, scope)?;
                self.php_member(c, name, "member")
            }
            _ if matches!(scope.kind(), "name" | "qualified_name" | "relative_name") => {
                let c = self.php_type(fi, scope)?;
                self.php_member(c, name, "qualified")
            }
            _ => {
                let c = self.php_value(fi, scope)?;
                self.php_member(c, name, "variable")
            }
        }
    }

    /// Method `name` of class `c`, its traits and bases included; "external" when a base from
    /// outside may declare it.
    fn php_member(&mut self, c: i64, name: &str, how: &'static str) -> Resolution {
        if let Some(m) = self.member(c, name, 0) {
            return Ok((m, how));
        }
        let (_, outside, unknown) = self.linearized(c, 0, &mut HashMap::new());
        Err(if outside && !unknown { "external" } else { "not found" })
    }

    /// A function called by the name `whole`: in the namespace it names, then a global function
    /// of that name, as PHP falls back for an unqualified call.
    fn php_function(&mut self, fi: &FileInfo, whole: Node) -> Resolution {
        let written = text(whole, &fi.src).trim();
        let full = php_qualify(fi, whole, written);
        match self.php_path(&full, &["function"]) {
            Ok(id) => Ok((id, "namespace")),
            Err(_) if !written.contains('\\') && full != written && !fi.bindings.iter().any(|b| b.local == written) => {
                self.php_path(written, &["function"]).map(|id| (id, "namespace"))
            }
            Err(e) => Err(e),
        }
    }

    /// The class a name written at `n` stands for (`User`, `\App\User`, `self`, `parent`).
    fn php_type(&mut self, fi: &FileInfo, n: Node) -> std::result::Result<i64, &'static str> {
        let written = text(n, &fi.src).trim();
        match written {
            "self" | "static" => return self.php_around(fi, n),
            "parent" => {
                let c = self.php_around(fi, n)?;
                return self.php_parent(c);
            }
            _ => {}
        }
        let full = php_qualify(fi, n, written);
        self.php_path(&full, CONTAINER_KINDS)
    }

    /// The class, interface, trait or enum a `use` names, else the function.
    fn php_used(&mut self, full: &str) -> std::result::Result<i64, &'static str> {
        match self.php_path(full, CONTAINER_KINDS) {
            Ok(id) => Ok(id),
            Err(e) => self.php_path(full, &["function"]).map_err(|_| e),
        }
    }

    /// The definition of one of `kinds` the full name `A\B\C` stands for: one named `C` at the
    /// top of a PHP file whose namespace there is `A\B`. "external" when the repository defines
    /// no such name anywhere.
    fn php_path(&mut self, full: &str, kinds: &[&str]) -> std::result::Result<i64, &'static str> {
        let key = format!("{full}\n{}", kinds.join(","));
        if let Some(r) = self.php_paths.get(&key) {
            return *r;
        }
        let (ns, name) = full.rsplit_once('\\').unwrap_or(("", full));
        let mut rows: Vec<Symbol> = self.ix.named(name).unwrap_or_default();
        rows.retain(|r| r.qualname == name && kinds.contains(&r.kind.as_str()) && path_lang(&r.path) == Some(Lang::Php));
        rows.sort_by(|a, b| (&a.path, a.start).cmp(&(&b.path, b.start)));
        let mut found = if rows.is_empty() { Err("external") } else { Err("not found") };
        for r in rows {
            let f = self.file(&r.path);
            if php_namespace(&f, (r.start - 1).max(0) as usize) == ns {
                found = Ok(r.id);
                break;
            }
        }
        self.php_paths.insert(key, found);
        found
    }

    /// The innermost class around `n`.
    fn php_around(&self, fi: &FileInfo, n: Node) -> std::result::Result<i64, &'static str> {
        match self.container_at(fi, n.start_position().row as i64 + 1) {
            Some(Ty::Local(c)) => Ok(c),
            _ => Err("receiver"),
        }
    }

    /// The class class `c` extends.
    fn php_parent(&mut self, c: i64) -> std::result::Result<i64, &'static str> {
        let (path, _) = self.def_row(c).ok_or("not found")?;
        let fi = self.file(&path);
        let node = def_node(&fi, c).ok_or("not found")?;
        let mut cur = node.walk();
        let base = node.named_children(&mut cur).find(|n| n.kind() == "base_clause").and_then(|b| b.named_child(0)).ok_or("not found")?;
        // `extends parent` would name this class's parent again
        if matches!(text(base, &fi.src), "self" | "static" | "parent") {
            return Err("not found");
        }
        self.php_type(&fi, base)
    }

    /// The traits class `id` uses, then the class it extends, then the interfaces it implements.
    fn php_bases(&mut self, fi: &FileInfo, id: i64) -> Vec<std::result::Result<i64, &'static str>> {
        let Some(node) = def_node(fi, id) else { return Vec::new() };
        let mut named = Vec::new();
        if let Some(body) = node.child_by_field_name("body") {
            let mut cur = body.walk();
            for u in body.named_children(&mut cur).filter(|c| c.kind() == "use_declaration") {
                named.extend(php_names(u));
            }
        }
        let mut cur = node.walk();
        for c in node.named_children(&mut cur).filter(|c| matches!(c.kind(), "base_clause" | "class_interface_clause")) {
            named.extend(php_names(c));
        }
        named.into_iter().map(|n| self.php_type(fi, n)).filter(|b| *b != Ok(id)).collect()
    }

    /// The class of the value `e` is: `$this`, a variable, `new C`, what a call returns, a typed
    /// property.
    fn php_value(&mut self, fi: &FileInfo, e: Node) -> std::result::Result<i64, &'static str> {
        if self.nest > 32 {
            return Err("receiver");
        }
        self.nest += 1;
        let r = self.php_value_inner(fi, e);
        self.nest -= 1;
        r
    }

    fn php_value_inner(&mut self, fi: &FileInfo, e: Node) -> std::result::Result<i64, &'static str> {
        let src = fi.src.as_str();
        match e.kind() {
            "variable_name" if text(e, src) == "$this" => self.php_around(fi, e),
            "variable_name" => self.php_variable(fi, e),
            "object_creation_expression" => {
                let mut cur = e.walk();
                let class = e.named_children(&mut cur).find(|c| matches!(c.kind(), "name" | "qualified_name" | "relative_name"));
                self.php_type(fi, class.ok_or("receiver")?)
            }
            "parenthesized_expression" => self.php_value(fi, e.named_child(0).ok_or("receiver")?),
            "member_call_expression" | "nullsafe_member_call_expression" | "scoped_call_expression" | "function_call_expression" => {
                let callee = e.child_by_field_name(if e.kind() == "function_call_expression" { "function" } else { "name" }).ok_or("receiver")?;
                let leaf = if callee.kind() == "qualified_name" {
                    callee.named_child(callee.named_child_count().saturating_sub(1) as u32).ok_or("receiver")?
                } else {
                    callee
                };
                let (id, _) = self.php_resolve(fi, leaf, text(leaf, src)).map_err(|_| "receiver")?;
                self.php_returns(id)
            }
            "member_access_expression" | "nullsafe_member_access_expression" => {
                let (obj, prop) = (e.child_by_field_name("object").ok_or("receiver")?, e.child_by_field_name("name").ok_or("receiver")?);
                let c = self.php_value(fi, obj)?;
                self.php_property(c, &format!("${}", text(prop, src)))
            }
            _ => Err("receiver"),
        }
    }

    /// The class of variable `e`: the value of its latest assignment before the use, else the
    /// type its parameter declares.
    fn php_variable(&mut self, fi: &FileInfo, e: Node) -> std::result::Result<i64, &'static str> {
        let src = fi.src.as_str();
        let var = text(e, src);
        let scope = std::iter::successors(e.parent(), |n| n.parent()).find(|n| PHP_FUNCTIONS.contains(&n.kind()) || n.parent().is_none()).ok_or("receiver")?;
        let at = e.start_byte();
        let binders = self.found_in(scope, "php binders", var, || php_binders(scope, var, src));
        let latest = binders[..binders.partition_point(|&(_, end)| end <= at)].last().copied();
        if let Some((s, end)) = latest {
            let b = scope.descendant_for_byte_range(s, end).ok_or("receiver")?;
            return match b.kind() {
                "assignment_expression" => self.php_value(fi, b.child_by_field_name("right").ok_or("receiver")?),
                _ => Err("receiver"),
            };
        }
        let mut cur = scope.walk();
        let param = scope
            .child_by_field_name("parameters")
            .and_then(|ps| ps.named_children(&mut cur).find(|p| p.child_by_field_name("name").is_some_and(|n| text(n, src) == var)));
        let t = param.and_then(|p| p.child_by_field_name("type")).ok_or("receiver")?;
        self.php_hint(fi, t)
    }

    /// The class a type declaration names (`User`, `?User`, `self`); None for a primitive or a union.
    fn php_hint(&mut self, fi: &FileInfo, t: Node) -> std::result::Result<i64, &'static str> {
        match t.kind() {
            "named_type" | "optional_type" => self.php_hint(fi, t.named_child(0).ok_or("receiver")?),
            "name" | "qualified_name" | "relative_name" => self.php_type(fi, t),
            _ if matches!(text(t, &fi.src).trim(), "self" | "static") => self.php_around(fi, t),
            _ => Err("receiver"),
        }
    }

    /// The class the function or method `id` declares it returns.
    fn php_returns(&mut self, id: i64) -> std::result::Result<i64, &'static str> {
        let (path, _) = self.def_row(id).ok_or("receiver")?;
        let fi = self.file(&path);
        let t = def_node(&fi, id).and_then(|n| n.child_by_field_name("return_type")).ok_or("receiver")?;
        self.php_hint(&fi, t)
    }

    /// The class of property `prop` (`$name`) of class `c` or a class it inherits from: the type
    /// its declaration or constructor parameter states.
    fn php_property(&mut self, c: i64, prop: &str) -> std::result::Result<i64, &'static str> {
        let (order, _, _) = self.linearized(c, 0, &mut HashMap::new());
        for k in order.into_iter().filter(|&k| k >= 0) {
            let Some((path, _)) = self.def_row(k) else { continue };
            let fi = self.file(&path);
            let Some(body) = def_node(&fi, k).and_then(|n| n.child_by_field_name("body")) else { continue };
            let src = fi.src.as_str();
            let mut stack = vec![body];
            while let Some(n) = stack.pop() {
                let declared = match n.kind() {
                    "property_declaration" => {
                        let mut cur = n.walk();
                        let named = n
                            .named_children(&mut cur)
                            .any(|p| p.kind() == "property_element" && p.child_by_field_name("name").is_some_and(|x| text(x, src) == prop));
                        named.then(|| n.child_by_field_name("type"))
                    }
                    "property_promotion_parameter" if n.child_by_field_name("name").is_some_and(|x| text(x, src) == prop) => {
                        Some(n.child_by_field_name("type"))
                    }
                    "compound_statement" => continue,
                    _ => None,
                };
                if let Some(t) = declared {
                    return self.php_hint(&fi, t.ok_or("receiver")?);
                }
                let mut cur = n.walk();
                stack.extend(n.named_children(&mut cur));
            }
        }
        Err("receiver")
    }
}

//! Python: `import` and `from .. import` bindings, `self` and `cls`, `super()`, comprehension
//! scopes, the method resolution order with bases from outside, modules as files on `sys.path`.

use super::*;

pub(super) struct Python;

impl Rules for Python {
    const GRAMMARS: &'static [&'static str] = &["python"];
    // `x` of `x.f()` may be a module
    const METHODS_ONLY: bool = false;
    const SELF_NAMES: &'static [&'static str] = &["self", "cls"];
    const BLOCKS: &'static [&'static str] = &["list_comprehension", "set_comprehension", "dictionary_comprehension", "generator_expression"];
    const COMPREHENSIONS: bool = true;

    fn bindings(n: Node, _path: &str, src: &str, out: &mut Vec<Binding>) -> bool {
        py_bindings(n, src, out)
    }

    fn is_super(q: Node, src: &str) -> bool {
        q.kind() == "call" && q.child_by_field_name("function").is_some_and(|f| f.kind() == "identifier" && text(f, src) == "super")
    }

    fn is_receiver(_q: Node, qt: &str, _node: Node) -> bool {
        qt == "self" || qt == "cls"
    }

    fn constructed_call(r: &mut Resolver, path: &str, fi: &FileInfo, v: Node, f: Node) -> Option<Ty> {
        let (src, line) = (fi.src.as_str(), v.start_position().row as i64 + 1);
        let leaf = member_parts(f).map(|(_, m)| m).unwrap_or(f);
        let found = match qualifier(leaf) {
            Some(q) => r.resolve_qualified(path, fi, Lang::Python, q, leaf, text(leaf, src), line),
            None => r.resolve_bare(path, fi, Lang::Python, leaf, text(leaf, src), line),
        };
        found.ok().map(|(id, _)| id).filter(|&id| r.def_kind(id).is_some_and(|k| concrete(&k))).map(Ty::Local)
    }

    fn unwraps(name: &str) -> bool {
        name == "Optional"
    }

    fn type_alias(fi: &FileInfo, name: &str) -> bool {
        top_level_binder(fi, name)
    }

    // every class ends with `object`: it keeps no place before an in-repo base
    fn outside_base(name: &str) -> bool {
        name != "object"
    }

    fn module_of_chain(r: &mut Resolver, path: &str, fi: &FileInfo, segs: &[&str]) -> Option<Vec<String>> {
        let b = fi.bindings.iter().find(|b| b.local == segs[0])?;
        let mut m = match &b.item {
            Some(it) if b.module.ends_with('.') => format!("{}{it}", b.module),
            Some(it) => format!("{}.{it}", b.module),
            None => b.module.clone(),
        };
        for s in &segs[1..] {
            m = format!("{m}.{s}");
        }
        r.module_files(path, Lang::Python, &m)
    }

    fn module_files(r: &mut Resolver, from: &str, module: &str) -> Option<Vec<String>> {
        r.py_module(from, module).map(|f| vec![f])
    }

    fn import_files(r: &mut Resolver, from: &str, fi: &FileInfo, line: i64, module: &str) -> Option<Vec<String>> {
        let mut out = Vec::new();
        for b in statement_bindings(fi, line, &["import_from_statement"]) {
            // `from m import x` names the submodule `m.x` when there is one, else `m`
            let Some(item) = &b.item else { continue };
            let sub = if b.module.ends_with('.') { format!("{}{item}", b.module) } else { format!("{}.{item}", b.module) };
            out.extend(
                r.py_rooted(from, &sub).or_else(|| r.py_rooted(from, &b.module)).or_else(|| r.py_beside(from, &sub)).or_else(|| r.py_beside(from, &b.module)),
            );
        }
        if out.is_empty() {
            out.extend(r.py_module(from, module));
        }
        Some(out)
    }
}

fn py_bindings(n: Node, src: &str, out: &mut Vec<Binding>) -> bool {
    match n.kind() {
        "import_statement" => {
            let mut cur = n.walk();
            for ch in n.children_by_field_name("name", &mut cur) {
                if ch.kind() == "aliased_import" {
                    let (Some(name), Some(alias)) = (ch.child_by_field_name("name"), ch.child_by_field_name("alias")) else { continue };
                    out.push(Binding { local: text(alias, src).into(), module: text(name, src).into(), item: None, sites: vec![alias.start_byte()] });
                } else if let Some(first) = ch.named_child(0) {
                    // `import a.b.c` binds `a`
                    let head = text(first, src).to_string();
                    out.push(Binding { local: head.clone(), module: head, item: None, sites: vec![first.start_byte()] });
                }
            }
            true
        }
        "import_from_statement" => {
            let Some(m) = n.child_by_field_name("module_name") else { return true };
            let module: String = text(m, src).chars().filter(|c| !c.is_whitespace()).collect();
            let mut cur = n.walk();
            for ch in n.named_children(&mut cur) {
                if ch.kind() == "wildcard_import" {
                    out.push(Binding { local: "*".into(), module: module.clone(), item: None, sites: vec![] });
                }
            }
            let mut cur = n.walk();
            for ch in n.children_by_field_name("name", &mut cur) {
                let (name, alias) =
                    if ch.kind() == "aliased_import" { (ch.child_by_field_name("name"), ch.child_by_field_name("alias")) } else { (Some(ch), None) };
                let Some(name) = name else { continue };
                let item = text(name, src).to_string();
                let mut sites = vec![name.start_byte()];
                sites.extend(alias.map(|a| a.start_byte()));
                out.push(Binding {
                    local: alias.map(|a| text(a, src).to_string()).unwrap_or_else(|| item.clone()),
                    module: module.clone(),
                    item: Some(item),
                    sites,
                });
            }
            true
        }
        _ => false,
    }
}

impl Resolver<'_> {
    fn py_module(&self, from: &str, module: &str) -> Option<String> {
        self.py_rooted(from, module).or_else(|| self.py_beside(from, module))
    }

    fn py_try_base(&self, base: &str) -> Option<String> {
        self.first_file(&[format!("{base}.py"), format!("{base}/__init__.py"), format!("{base}.pyi"), format!("{base}/__init__.pyi")])
    }

    /// An absolute import in the directory of `from`: Python puts a script's own directory first
    /// on `sys.path`, and pytest a test's, so a sibling wins even over a standard library module.
    /// A package's directory is never on `sys.path`, so a file in one gets no such answer.
    fn py_beside(&self, from: &str, module: &str) -> Option<String> {
        let dir = dir_of(from);
        let in_package = || ["py", "pyi"].iter().any(|e| self.files.contains(format!("{dir}/__init__.{e}").as_str()));
        if dir.is_empty() || module.starts_with('.') || in_package() {
            return None;
        }
        self.py_try_base(&format!("{dir}/{}", module.replace('.', "/")))
    }

    fn py_rooted(&self, from: &str, module: &str) -> Option<String> {
        let try_base = |base: &str| self.py_try_base(base);
        if module.starts_with('.') {
            let target = py_relative(from, module);
            return if target.is_empty() { self.first_file(&["__init__.py".to_string()]) } else { try_base(&target) };
        }
        let slashed = module.replace('.', "/");
        if let Some(f) = try_base(&slashed).or_else(|| try_base(&format!("src/{slashed}"))) {
            return Some(f);
        }
        let segs: Vec<&str> = slashed.split('/').collect();
        below_own_package(&self.ix.root, &segs).and_then(|rest| try_base(&rest.join("/")))
    }
}

/// Whether the file assigns `name` at its top level (a Python `T = TypeVar("T")` or alias).
fn top_level_binder(fi: &FileInfo, name: &str) -> bool {
    let Some(tree) = fi.tree.as_ref() else { return false };
    let root = tree.root_node();
    let mut cur = root.walk();
    let found = root.named_children(&mut cur).any(|s| {
        s.kind() == "expression_statement"
            && s.named_child(0).is_some_and(|a| a.kind() == "assignment" && a.child_by_field_name("left").is_some_and(|l| text(l, &fi.src) == name))
    });
    found
}

//! Rust: `use` trees, raw identifiers, names in macro arguments, `self` and `Self`, unit structs
//! and `Deref` holders, methods of `impl` blocks anywhere in the crate, modules by `mod` and
//! crate roots.

use super::*;

pub(super) struct Rust;

impl Rules for Rust {
    const GRAMMARS: &'static [&'static str] = &["rust"];
    const PATH_SEP: &'static str = "::";
    const SELF_NAMES: &'static [&'static str] = &["self"];
    const SELF_TYPE: Option<&'static str> = Some("Self");

    fn bindings(n: Node, _path: &str, src: &str, out: &mut Vec<Binding>) -> bool {
        if n.kind() == "use_declaration" {
            if let Some(a) = n.child_by_field_name("argument") {
                rust_use(a, "", src, out);
            }
            true
        } else {
            false
        }
    }

    // a raw identifier `r#type` is the name `type`
    fn raw(spelled: &str, name: &str) -> bool {
        spelled.strip_prefix("r#") == Some(name)
    }

    fn occurrence(_r: &mut Resolver, _path: &str, fi: &FileInfo, node: Node, _name: &str, _line: i64) -> Option<Resolution> {
        if node.parent().is_some_and(|p| p.kind() == "token_tree") {
            return macro_token(node, &fi.src).map(Err);
        }
        None
    }

    fn is_receiver(_q: Node, qt: &str, node: Node) -> bool {
        qt == "Self" || (qt == "self" && node.parent().is_some_and(|p| p.kind() == "field_expression"))
    }

    fn constructed_call(r: &mut Resolver, path: &str, fi: &FileInfo, v: Node, f: Node) -> Option<Ty> {
        let src = fi.src.as_str();
        let holder = f.kind() == "scoped_identifier"
            && f.child_by_field_name("name").is_some_and(|n| text(n, src) == "new")
            && f.child_by_field_name("path").is_some_and(|p| RUST_DEREF.contains(&text(p, src)));
        if holder {
            r.constructed(path, fi, Lang::Rust, v.child_by_field_name("arguments")?.named_child(0)?)
        } else {
            None
        }
    }

    fn constructed_name(r: &mut Resolver, path: &str, fi: &FileInfo, v: Node) -> Option<Ty> {
        let line = v.start_position().row as i64 + 1;
        let id = r.resolve_bare(path, fi, Lang::Rust, v, text(v, &fi.src), line).ok()?.0;
        r.def_kind(id).filter(|k| k == "struct").map(|_| Ty::Local(id))
    }

    fn unwraps(name: &str) -> bool {
        RUST_DEREF.contains(&name)
    }

    // impl blocks may live in another file of the crate
    fn inherited(r: &mut Resolver, _id: i64, name: &str, _depth: usize, path: &str, qualname: &str) -> Option<i64> {
        let want = format!("{}.{name}", strip_generics(qualname));
        let rows = r.ix.named(name).ok()?;
        let common = |p: &str| p.split('/').zip(path.split('/')).take_while(|(a, b)| a == b).count();
        rows.into_iter().filter(|r| strip_generics(&r.qualname) == want).max_by_key(|r| common(&r.path)).map(|r| r.id)
    }

    fn module_of_chain(r: &mut Resolver, path: &str, fi: &FileInfo, segs: &[&str]) -> Option<Vec<String>> {
        let b = fi.bindings.iter().find(|b| b.local == segs[0]);
        let mut full: Vec<String> = Vec::new();
        match b {
            Some(b) if !matches!(segs[0], "crate" | "self" | "super") => {
                full.extend(b.module.split("::").filter(|s| !s.is_empty()).map(String::from));
                full.extend(b.item.clone());
            }
            _ => full.push(segs[0].to_string()),
        }
        full.extend(segs[1..].iter().map(|s| s.to_string()));
        r.rust_module(path, &full.iter().map(|s| s.as_str()).collect::<Vec<_>>())
    }

    fn module_files(r: &mut Resolver, from: &str, module: &str) -> Option<Vec<String>> {
        let segs: Vec<&str> = module.split("::").filter(|s| !s.is_empty()).collect();
        r.rust_module(from, &segs)
    }

    fn import_files(r: &mut Resolver, from: &str, fi: &FileInfo, line: i64, module: &str) -> Option<Vec<String>> {
        let mut out = Vec::new();
        for b in statement_bindings(fi, line, &["use_declaration"]) {
            let full = match &b.item {
                Some(item) if b.module.is_empty() => item.clone(),
                Some(item) => format!("{}::{item}", b.module),
                None => b.module.clone(),
            };
            let segs: Vec<&str> = full.split("::").filter(|s| !s.is_empty()).collect();
            // the longest prefix that is a module: `crate::a::thing` is in `crate::a`
            out.extend((1..=segs.len()).rev().find_map(|n| r.rust_module(from, &segs[..n])).and_then(|v| v.into_iter().next()));
        }
        if out.is_empty() {
            out.extend(Self::module_files(r, from, module).and_then(|v| v.into_iter().next()));
        }
        Some(out)
    }
}

/// Standard Rust types whose methods a call reaches through `Deref` to the type they hold.
const RUST_DEREF: &[&str] = &["Box", "Rc", "Arc", "Ref", "RefMut", "Cow", "MutexGuard", "RwLockReadGuard", "RwLockWriteGuard", "Pin", "ManuallyDrop"];

fn rust_push(full: &str, local: &str, sites: Vec<usize>, out: &mut Vec<Binding>) {
    let (module, item) = full.rsplit_once("::").unwrap_or(("", full));
    out.push(Binding { local: local.to_string(), module: module.to_string(), item: Some(item.to_string()), sites });
}

fn rust_use(n: Node, prefix: &str, src: &str, out: &mut Vec<Binding>) {
    let cat = |p: &str, t: &str| {
        if p.is_empty() {
            t.to_string()
        } else if t.is_empty() {
            p.to_string()
        } else {
            format!("{p}::{t}")
        }
    };
    match n.kind() {
        "self" => {
            let last = prefix.rsplit("::").next().unwrap_or(prefix);
            rust_push(prefix, last, vec![n.start_byte()], out);
        }
        "identifier" | "crate" | "super" | "metavariable" => rust_push(&cat(prefix, text(n, src)), text(n, src), vec![n.start_byte()], out),
        "scoped_identifier" => {
            let name = n.child_by_field_name("name");
            let local = name.map(|x| text(x, src)).unwrap_or("");
            rust_push(&cat(prefix, text(n, src)), local, name.map(|x| vec![x.start_byte()]).unwrap_or_default(), out);
        }
        "use_as_clause" => {
            let (Some(path), Some(alias)) = (n.child_by_field_name("path"), n.child_by_field_name("alias")) else { return };
            let mut sites = vec![alias.start_byte()];
            sites.extend(path.child_by_field_name("name").or(Some(path)).map(|x| x.start_byte()));
            rust_push(&cat(prefix, text(path, src)), text(alias, src), sites, out);
        }
        "scoped_use_list" => {
            let p = n.child_by_field_name("path").map(|x| text(x, src)).unwrap_or("");
            if let Some(list) = n.child_by_field_name("list") {
                rust_use(list, &cat(prefix, p), src, out);
            }
        }
        "use_list" => {
            let mut cur = n.walk();
            for ch in n.named_children(&mut cur) {
                rust_use(ch, prefix, src, out);
            }
        }
        "use_wildcard" => {
            let p = n.named_child(0).map(|x| text(x, src)).unwrap_or("");
            out.push(Binding { local: "*".into(), module: cat(prefix, p), item: None, sites: vec![] });
        }
        _ => {}
    }
}

impl Resolver<'_> {
    /// The `mod name;` declarations of a Rust file: (line, name, the file of that module).
    pub fn rust_mods(&mut self, from: &str) -> Vec<(i64, String, Option<String>)> {
        let fi = self.file(from);
        let (Some(Lang::Rust), Some(tree)) = (fi.lang, &fi.tree) else { return Vec::new() };
        let mut out = Vec::new();
        let mut stack = vec![(tree.root_node(), self.rust_own_dir(from))];
        while let Some((n, dir)) = stack.pop() {
            let mut cur = n.walk();
            for ch in n.named_children(&mut cur) {
                if ch.kind() != "mod_item" {
                    continue;
                }
                let Some(name) = ch.child_by_field_name("name").map(|x| text(x, &fi.src).to_string()) else { continue };
                let sub = join(&dir, &name);
                match ch.child_by_field_name("body") {
                    Some(body) => stack.push((body, sub)),
                    None => out.push((ch.start_position().row as i64 + 1, name, self.rust_mod_file(&sub))),
                }
            }
        }
        out.sort();
        out
    }

    /// The Rust files that may declare `mod` for `path`: the module files of its parent directory.
    pub fn rust_mod_parents(&self, path: &str) -> Vec<String> {
        let d = dir_of(&Self::rust_mod_dir(path)).to_string();
        let mut cands = vec![format!("{d}/mod.rs"), format!("{d}/lib.rs"), format!("{d}/main.rs"), format!("{d}.rs")];
        if d.is_empty() {
            cands = vec!["lib.rs".into(), "main.rs".into()];
        }
        cands.push(join(&d, "build.rs"));
        if self.rust_target_dir(&d) {
            let mut roots: Vec<String> = self.files.iter().filter(|f| f.ends_with(".rs") && dir_of(f) == d).cloned().collect();
            roots.sort();
            cands.extend(roots);
        }
        cands.retain(|c| self.files.contains(c) && c != path && (!c.ends_with("/build.rs") && c != "build.rs" || self.rust_root_file(c)));
        cands.dedup();
        cands
    }
}

impl Resolver<'_> {
    fn rust_mod_file(&self, dir: &str) -> Option<String> {
        if dir.is_empty() {
            return self.first_file(&["lib.rs".into(), "main.rs".into()]);
        }
        self.first_file(&[format!("{dir}.rs"), format!("{dir}/mod.rs"), format!("{dir}/lib.rs"), format!("{dir}/main.rs")])
    }

    /// Directory that stands for the module of a Rust file (`a/b.rs` and `a/b/mod.rs` -> `a/b`).
    pub(super) fn rust_mod_dir(path: &str) -> String {
        let base = path.rsplit('/').next().unwrap_or(path);
        if matches!(base, "mod.rs" | "lib.rs" | "main.rs") {
            dir_of(path).to_string()
        } else {
            join(dir_of(path), base.trim_end_matches(".rs"))
        }
    }

    /// The directory a Rust file's own `mod` and `self::` start at: its module's, or its own
    /// directory when it is a crate root.
    fn rust_own_dir(&self, path: &str) -> String {
        if self.rust_root_file(path) {
            dir_of(path).to_string()
        } else {
            Self::rust_mod_dir(path)
        }
    }

    /// `build.rs` beside a `Cargo.toml`, or a file directly in a target folder: a crate root.
    fn rust_root_file(&self, path: &str) -> bool {
        match path.rsplit_once('/').unwrap_or(("", path)) {
            (dir, "build.rs") => self.files.contains(&join(dir, "Cargo.toml")),
            (dir, base) => base.ends_with(".rs") && self.rust_target_dir(dir),
        }
    }

    /// A package's `src/bin`, `tests`, `examples` or `benches`, where Cargo takes each file for a crate.
    fn rust_target_dir(&self, dir: &str) -> bool {
        let (up, last) = dir.rsplit_once('/').unwrap_or(("", dir));
        let package = match last {
            "bin" => match up.rsplit_once('/').unwrap_or(("", up)) {
                (p, "src") => p,
                _ => return false,
            },
            "tests" | "examples" | "benches" => up,
            _ => return false,
        };
        self.files.contains(&join(package, "Cargo.toml"))
    }

    fn rust_crate_root(&self, path: &str) -> Option<String> {
        if self.rust_root_file(path) {
            return Some(dir_of(path).to_string());
        }
        let mut d = dir_of(path).to_string();
        loop {
            let c = |f: &str| if d.is_empty() { f.to_string() } else { format!("{d}/{f}") };
            // a module below a target folder belongs to the crates of the files there
            if self.files.contains(&c("lib.rs")) || self.files.contains(&c("main.rs")) || self.rust_target_dir(&d) {
                return Some(d);
            }
            if d.is_empty() {
                return None;
            }
            d = dir_of(&d).to_string();
        }
    }

    /// Workspace crates by their `use` name (`grep-matcher` -> `grep_matcher`) -> crate root directory.
    fn crates(&mut self) -> &HashMap<String, String> {
        if self.crates.is_none() {
            let mut m = HashMap::new();
            let mut roots: Vec<&String> = self.files.iter().filter(|f| f.ends_with("/lib.rs") || *f == "lib.rs").collect();
            roots.sort();
            for f in roots {
                let dir = dir_of(f);
                let pkg = if dir == "src" { "" } else { dir.strip_suffix("/src").unwrap_or(dir) };
                let toml = if pkg.is_empty() { "Cargo.toml".to_string() } else { format!("{pkg}/Cargo.toml") };
                let Some(t) = repo_text(&self.ix.root, &toml) else { continue };
                if let Some(name) = cargo_package_name(&t) {
                    m.entry(name.replace('-', "_")).or_insert_with(|| dir.to_string());
                }
            }
            self.crates = Some(m);
        }
        self.crates.as_ref().unwrap()
    }

    fn rust_module(&mut self, from: &str, segs: &[&str]) -> Option<Vec<String>> {
        let first = *segs.first()?;
        let (mut dir, mut i) = match first {
            "crate" => (self.rust_crate_root(from)?, 1),
            "self" => (self.rust_own_dir(from), 1),
            "super" => {
                let mut d = self.rust_own_dir(from);
                let mut i = 0;
                while segs.get(i) == Some(&"super") {
                    d = dir_of(&d).to_string();
                    i += 1;
                }
                (d, i)
            }
            other => {
                // a file beside a crate root such as `tests/it.rs` is its module only when it declares it
                let root = self.rust_root_file(from);
                let declared = !root || self.rust_mods(from).iter().any(|(_, n, _)| n == other);
                if let Some(d) = self.crates().get(other).cloned() {
                    (d, 1)
                } else if declared && self.rust_mod_file(&join(&self.rust_own_dir(from), other)).is_some() {
                    (self.rust_own_dir(from), 0)
                } else if root {
                    return None;
                } else {
                    (self.rust_crate_root(from)?, 0) // 2015-edition paths start at the crate root
                }
            }
        };
        while i < segs.len() {
            dir = join(&dir, segs[i]);
            self.rust_mod_file(&dir)?;
            i += 1;
        }
        if self.rust_root_file(from) && dir == dir_of(from) {
            return Some(vec![from.to_string()]);
        }
        if let Some(f) = self.rust_mod_file(&dir) {
            return Some(vec![f]);
        }
        // the root of a module below a target folder: any of the crates there
        let mut roots: Vec<String> = self.files.iter().filter(|f| f.ends_with(".rs") && dir_of(f) == dir && self.rust_target_dir(&dir)).cloned().collect();
        roots.sort();
        (!roots.is_empty()).then_some(roots)
    }
}

/// What the tokens around a name in a Rust macro argument, which the grammar leaves without
/// syntax, say it is: a field or a method after `.`, a field name in `{ name: value }`.
fn macro_token(n: Node, src: &str) -> Option<&'static str> {
    let next = n.next_sibling();
    if n.prev_sibling().is_some_and(|p| p.kind() == ".") {
        let call = next.is_some_and(|x| x.kind() == "::" || (x.kind() == "token_tree" && text(x, src).starts_with('(')));
        return Some(if call { "receiver" } else { "field or key" });
    }
    if macro_local(n, src) {
        return Some("local variable");
    }
    let braced = n.parent().is_some_and(|p| text(p, src).starts_with('{'));
    (braced && next.is_some_and(|x| x.kind() == ":")).then_some("field or key")
}

/// Whether a name in a Rust macro argument is bound in the tokens before it: a parameter of a
/// closure (`|(a, name)| ..`) or a `let`, in its own token tree or one around it.
fn macro_local(n: Node, src: &str) -> bool {
    let name = text(n, src);
    let binds = |tokens: &[Node]| {
        let mut names = Vec::new();
        for t in tokens {
            token_idents(*t, src, &mut names);
        }
        names.contains(&name)
    };
    let mut child = n;
    while let Some(tt) = child.parent().filter(|p| p.kind() == "token_tree") {
        let mut cur = tt.walk();
        let kids: Vec<Node> = tt.children(&mut cur).collect();
        let at = kids.iter().position(|k| k.id() == child.id()).unwrap_or(kids.len());
        let mut open: Option<usize> = None;
        for (i, k) in kids.iter().enumerate().take(at) {
            match k.kind() {
                "|" => match open.take() {
                    Some(o) if binds(&kids[o + 1..i]) => return true,
                    Some(_) => {}
                    None => open = Some(i),
                },
                "let" => {
                    let bound = i + 1 + usize::from(kids.get(i + 1).is_some_and(|m| m.kind() == "mut"));
                    if bound == at || (bound < at && binds(&kids[bound..bound + 1])) {
                        return true;
                    }
                }
                _ => {}
            }
        }
        // between the bars of a closure: one of its parameters
        if open.is_some() {
            return true;
        }
        child = tt;
    }
    false
}

fn token_idents<'s>(n: Node, src: &'s str, out: &mut Vec<&'s str>) {
    if n.kind() == "identifier" {
        out.push(text(n, src));
    }
    let mut cur = n.walk();
    for c in n.named_children(&mut cur) {
        token_idents(c, src, out);
    }
}

pub(super) fn cargo_package_name(toml: &str) -> Option<String> {
    let mut in_pkg = false;
    for line in toml.lines() {
        let l = line.trim();
        if l.starts_with('[') {
            in_pkg = l == "[package]";
        } else if in_pkg {
            if let Some(v) = l.strip_prefix("name").map(str::trim_start).and_then(|v| v.strip_prefix('=')) {
                return Some(v.trim().trim_matches('"').to_string());
            }
        }
    }
    None
}

//! A pull request report: what `impact` finds between a base and a head commit, and the
//! duplicates the head adds that the base did not have. It renders as the Markdown of a PR
//! comment, as JSON, and as a GitLab Code Quality report.

use std::collections::{BTreeSet, HashMap, HashSet, VecDeque};

use anyhow::Result;
use serde_json::{json, Value};

use crate::fmt::shown;
use crate::impact::Impact;
use crate::index::Body;
use crate::intel::DupGroup;
use crate::search::{Hit, Searcher, CODE_KINDS};

/// The first line of the comment: the GitHub Action finds its earlier comment by it.
pub const MARKER: &str = "<!-- scrutate-review -->";
/// The longest comment body GitHub takes, in characters.
pub const MAX_COMMENT: usize = 65_536;
/// Duplicate groups a report lists at most.
pub const MAX_DUPLICATES: usize = 50;

pub struct Review {
    pub impact: Impact,
    /// the head as given (`HEAD` by default)
    pub head: String,
    /// the new duplicate groups, largest first, as `dupes` sorts them
    pub duplicates: Vec<DupGroup>,
    /// more groups than `MAX_DUPLICATES` were new
    pub more_duplicates: bool,
    /// indexes into `impact.changed` of the definitions no test reaches within the walk
    pub untested: Vec<usize>,
}

/// The report of `head` (a revision; `HEAD` by default) against `base`, on the index of the
/// working tree, which should be the head checked out.
pub fn review(s: &Searcher, base: &str, head: Option<&str>, depth: usize) -> Result<Review> {
    let head = head.unwrap_or("HEAD").to_string();
    let impact = crate::impact::between(s, base, &head, depth)?;
    let (mut duplicates, untested) = (new_duplicates(s, &impact)?, untested(&impact));
    let more_duplicates = duplicates.len() > MAX_DUPLICATES;
    duplicates.truncate(MAX_DUPLICATES);
    Ok(Review { impact, head, duplicates, more_duplicates, untested })
}

/// The duplicate groups of the head that the base did not have. Only a group with a member in a
/// file the diff changed can be new; the base's groups come from the same search over the head's
/// definitions with the changed files replaced by a parse of their base copies. A head group is
/// old when one base group holds a match for each of its members, each base member used once:
/// the same definition (path and qualified name), or the same body text up to whitespace.
fn new_duplicates(s: &Searcher, i: &Impact) -> Result<Vec<DupGroup>> {
    let (min, threshold) = (crate::ops::DUPES_MIN_TOKENS, crate::ops::DUPES_THRESHOLD);
    let changed: HashSet<&str> = i.head_paths.iter().chain(i.base_copies.iter().map(|c| &c.0)).map(String::as_str).collect();
    if changed.is_empty() {
        return Ok(Vec::new());
    }
    let rows = s.ix.bodies(CODE_KINDS, min)?;
    let head: Vec<DupGroup> = crate::intel::dupes_in(&rows.iter().collect::<Vec<_>>(), min, threshold, usize::MAX)
        .into_iter()
        .filter(|g| g.members.iter().any(|m| changed.contains(m.0.as_str())))
        .collect();
    if head.is_empty() {
        return Ok(head);
    }
    let parsed: Vec<Body> = i.base_copies.iter().flat_map(|(path, src)| bodies_of(path, src, min)).collect();
    let base_rows: Vec<&Body> = rows.iter().filter(|r| !changed.contains(r.1.as_str())).chain(&parsed).collect();
    let base = crate::intel::dupes_in(&base_rows, min, threshold, usize::MAX);
    // a changed file has a definition at the same place on both sides: one map per side
    let keys = |rs: &[&Body]| -> HashMap<(String, String, i64, i64), u64> {
        rs.iter().map(|r| ((r.1.clone(), r.2.clone(), r.3, r.4), crate::intel::body_key(&r.5))).collect()
    };
    let (head_keys, base_keys) = (keys(&rows.iter().collect::<Vec<_>>()), keys(&base_rows));
    let old = |g: &DupGroup| {
        base.iter().filter(|b| b.members.len() >= g.members.len()).any(|b| {
            let mut used = vec![false; b.members.len()];
            let mut left: Vec<&(String, String, i64, i64)> = Vec::new();
            for m in &g.members {
                match (0..b.members.len()).find(|&j| !used[j] && b.members[j].0 == m.0 && b.members[j].1 == m.1) {
                    Some(j) => used[j] = true,
                    None => left.push(m),
                }
            }
            left.into_iter().all(|m| {
                let found = head_keys.get(m).and_then(|k| (0..b.members.len()).find(|&j| !used[j] && base_keys.get(&b.members[j]) == Some(k)));
                found.map(|j| used[j] = true).is_some()
            })
        })
    };
    Ok(head.into_iter().filter(|g| !old(g)).collect())
}

/// The definitions of a base copy as the index would hold them for `dupes`.
fn bodies_of(path: &str, src: &[u8], min_tokens: usize) -> Vec<Body> {
    if src.len() as u64 > crate::index::MAX_FILE_BYTES || !crate::parse::is_indexable(path) {
        return Vec::new();
    }
    crate::parse::parse_file(path, &String::from_utf8_lossy(src))
        .chunks
        .into_iter()
        .filter(|c| CODE_KINDS.contains(&c.kind) && crate::text::tokenize2(&c.body, Some(crate::text::BODY_CAP)).0.len() >= min_tokens)
        .map(|c| (0, path.to_string(), c.qualname, c.start, c.end, c.text))
        .collect()
}

/// The changed definitions (added or edited, outside test files) from which no test file is
/// reached through the calls the walk found.
fn untested(i: &Impact) -> Vec<usize> {
    let mut up: HashMap<&str, Vec<&Hit>> = HashMap::new();
    let by_id: HashMap<i64, &Hit> = i.changed.iter().map(|c| &c.hit).chain(i.callers.iter().map(|c| &c.hit)).map(|h| (h.id, h)).collect();
    for (id, target) in &i.edges {
        if let Some(h) = by_id.get(id) {
            up.entry(target.as_str()).or_default().push(h);
        }
    }
    let reaches_test = |start: &Hit| {
        let mut seen = HashSet::from([start.loc()]);
        let mut queue = VecDeque::from([start]);
        while let Some(h) = queue.pop_front() {
            if crate::text::is_test_path(&h.path) {
                return true;
            }
            for c in up.get(h.loc().as_str()).into_iter().flatten() {
                if seen.insert(c.loc()) {
                    queue.push_back(c);
                }
            }
        }
        false
    };
    (0..i.changed.len())
        .filter(|&k| {
            let c = &i.changed[k];
            c.status != "deleted" && c.hit.id != 0 && !matches!(c.hit.kind.as_str(), "window" | "module" | "file") && !reaches_test(&c.hit)
        })
        .collect()
}

fn plural(n: usize, one: &str, many: &str) -> String {
    format!("{n} {}", if n == 1 { one } else { many })
}

/// `s` as a Markdown code span, fenced with more backticks than it holds in a row.
fn code(s: &str) -> String {
    let s = shown(s);
    let run = s.split(|c| c != '`').map(str::len).max().unwrap_or(0);
    let fence = "`".repeat(run + 1);
    let pad = if run > 0 { " " } else { "" };
    format!("{fence}{pad}{s}{pad}{fence}")
}

/// A path percent-encoded for a URL, `/` kept.
fn url_path(p: &str) -> String {
    p.bytes()
        .map(|b| match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' | b'/' => (b as char).to_string(),
            _ => format!("%{b:02X}"),
        })
        .collect()
}

impl Review {
    pub fn is_empty(&self) -> bool {
        self.impact.is_empty() && self.duplicates.is_empty()
    }

    /// The comment body: the marker, a line of counts, then each section that has items. With
    /// `link` (a URL that ends where a path follows, such as `https://github.com/o/r/blob/SHA`),
    /// each location links to its lines. Cut at `MAX_COMMENT` bytes with a line that says so.
    pub fn markdown(&self, link: Option<&str>) -> String {
        let i = &self.impact;
        let at = |path: &str, lines: Option<(i64, i64)>| {
            let text = match lines {
                Some((a, b)) => format!("{path}:{a}-{b}"),
                None => path.to_string(),
            };
            match link {
                Some(base) => {
                    let anchor = lines.map(|(a, b)| format!("#L{a}-L{b}")).unwrap_or_default();
                    format!("[{}]({}/{}{anchor})", code(&text), base.trim_end_matches('/'), url_path(path))
                }
                None => code(&text),
            }
        };
        let def = |h: &Hit| {
            if h.kind == "file" {
                at(&h.path, None)
            } else {
                format!("{} {} {}", at(&h.path, Some((h.start, h.end))), h.kind, code(if h.qualname.is_empty() { &h.name } else { &h.qualname }))
            }
        };
        let short = |c: &str| c.get(..12).unwrap_or(c).to_string();
        // a revision given as its commit id is named once, by its short form
        let named = |rev: &str, commit: &str| if commit.starts_with(rev) { code(&short(commit)) } else { format!("{} ({})", code(rev), short(commit)) };
        let mut counts = vec![
            plural(i.changed.len(), "changed definition", "changed definitions"),
            plural(i.callers.len(), "caller", "callers"),
            plural(i.tests.len(), "test file to run", "test files to run"),
            plural(self.duplicates.len(), "new duplicate", "new duplicates"),
        ];
        if !self.untested.is_empty() {
            counts.push(format!("{} no test reaches", self.untested.len()));
        }
        let head_commit = i.head.as_deref().unwrap_or_default();
        let mut lines = vec![
            MARKER.to_string(),
            format!("**scrutate review** of {} against {}", named(&self.head, head_commit), named(&i.against, &i.base)),
            String::new(),
            if self.is_empty() { "No changed definitions and no new duplicates.".to_string() } else { format!("{}.", counts.join(", ")) },
        ];
        let mut section = |title: String, items: Vec<String>| {
            if !items.is_empty() {
                lines.push(String::new());
                lines.push(format!("#### {title}"));
                lines.push(String::new());
                lines.extend(items);
            }
        };
        let untested: BTreeSet<usize> = self.untested.iter().copied().collect();
        section(
            "Changed definitions".into(),
            i.changed
                .iter()
                .enumerate()
                .map(|(k, c)| {
                    let mark = if untested.contains(&k) { ", no test reaches it" } else { "" };
                    let base_lines = if c.status == "deleted" && c.hit.kind != "file" { ", lines of the base" } else { "" };
                    format!("- {} ({}{base_lines}{mark})", def(&c.hit), c.status)
                })
                .collect(),
        );
        section(
            format!("Callers, up to {} away", plural(i.depth, "step", "steps")),
            i.callers
                .iter()
                .map(|c| {
                    let mark = if c.calls_deleted {
                        ", calls a deleted definition"
                    } else if c.undecided {
                        ", undecided"
                    } else {
                        ""
                    };
                    format!("- {} (distance {}{mark})", def(&c.hit), c.distance)
                })
                .collect(),
        );
        section(
            "Tests to run".into(),
            i.tests
                .iter()
                .map(|t| match &t.via {
                    Some(h) => format!(
                        "- {} (distance {}, through {})",
                        at(&t.path, None),
                        t.distance,
                        code(if h.qualname.is_empty() { &h.name } else { &h.qualname })
                    ),
                    None => format!("- {} (changed)", at(&t.path, None)),
                })
                .collect(),
        );
        let mut dupes: Vec<String> = self
            .duplicates
            .iter()
            .map(|g| {
                let members: Vec<String> = g.members.iter().map(|m| format!("{} {}", at(&m.0, Some((m.2, m.3))), code(&m.1))).collect();
                let how = if g.kind == "exact" { "exact".to_string() } else { format!("near, similarity {:.2}", g.similarity) };
                format!("- {how}, {} tokens: {}", g.tokens, members.join(", "))
            })
            .collect();
        if self.more_duplicates {
            dupes.push(format!("- (more than {MAX_DUPLICATES}: `scrutate review` lists the first {MAX_DUPLICATES})"));
        }
        section("New duplicates".into(), dupes);
        section("Notes".into(), i.notes.iter().map(|(p, n)| format!("- {}: {n}", at(p, None))).collect());
        if i.stopped {
            lines.push(String::new());
            lines.push(format!("_The walk stopped at {} callers._", crate::impact::MAX_CALLERS));
        }
        cap(lines, &i.against)
    }

    pub fn json(&self) -> Value {
        let mut v = self.impact.json();
        v["head"] = json!(self.head);
        v["head_commit"] = json!(self.impact.head);
        v["new_duplicates"] = serde_json::to_value(&self.duplicates).unwrap_or_default();
        v["untested"] = json!(self.untested.iter().map(|&k| self.impact.changed[k].hit.loc()).collect::<Vec<_>>());
        v
    }

    /// GitLab's Code Quality report: a list of issues, one per new duplicate group at the member
    /// the diff changed (`minor`), and one per changed definition no test reaches (`info`).
    pub fn gitlab(&self) -> Value {
        let i = &self.impact;
        let changed: HashSet<&str> = i.head_paths.iter().map(String::as_str).collect();
        let issue = |check: &str, description: String, severity: &str, path: &str, line: i64, identity: &str| {
            let fingerprint = crate::index::content_hash(format!("{check}\0{identity}").as_bytes());
            json!({"description": description, "check_name": check, "fingerprint": fingerprint, "severity": severity,
                "location": {"path": path, "lines": {"begin": line.max(1)}}})
        };
        let mut out = Vec::new();
        for g in &self.duplicates {
            let edited = |m: &&(String, String, i64, i64)| {
                i.changed.iter().any(|c| c.status != "deleted" && c.hit.path == m.0 && c.hit.start <= m.3 && m.2 <= c.hit.end)
            };
            let at = g.members.iter().find(edited).or_else(|| g.members.iter().find(|m| changed.contains(m.0.as_str()))).unwrap_or(&g.members[0]);
            let others: Vec<String> = g.members.iter().filter(|m| *m != at).map(|m| format!("{} at {}:{}-{}", m.1, m.0, m.2, m.3)).collect();
            let how = if g.kind == "exact" { "an exact duplicate".to_string() } else { format!("a near duplicate (similarity {:.2})", g.similarity) };
            let mut identity: Vec<String> = g.members.iter().map(|m| format!("{}\0{}", m.0, m.1)).collect();
            identity.sort();
            out.push(issue("scrutate-duplicate", format!("{} is {how} of {}", at.1, others.join(", ")), "minor", &at.0, at.2, &identity.join("\0")));
        }
        for &k in &self.untested {
            let h = &i.changed[k].hit;
            let name = if h.qualname.is_empty() { &h.name } else { &h.qualname };
            let why = format!("{name} changed ({}) and no test file reaches it within {} of callers", i.changed[k].status, plural(i.depth, "step", "steps"));
            out.push(issue("scrutate-untested-change", why, "info", &h.path, h.start, &format!("{}\0{name}", h.path)));
        }
        Value::Array(out)
    }
}

/// The lines joined, cut before the line that would pass `MAX_COMMENT` with the note that says so.
fn cap(lines: Vec<String>, base: &str) -> String {
    let note = format!("\n_Cut at {MAX_COMMENT} characters: `scrutate review --base {}` prints the whole report._\n", shown(base));
    let mut out = String::new();
    for l in &lines {
        if out.len() + l.len() + 1 + note.len() > MAX_COMMENT {
            out.push_str(&note);
            return out;
        }
        out.push_str(l);
        out.push('\n');
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_code_span_outfences_the_backticks_inside() {
        assert_eq!(code("f"), "`f`");
        assert_eq!(code("a`b"), "`` a`b ``");
    }

    #[test]
    fn a_long_report_is_cut_with_a_note_under_the_limit() {
        let lines: Vec<String> = (0..20_000).map(|n| format!("- line {n}")).collect();
        let out = cap(lines, "main");
        assert!(out.len() <= MAX_COMMENT && out.ends_with("prints the whole report._\n"), "{}", out.len());
        assert_eq!(cap(vec!["a".into()], "main"), "a\n");
    }

    #[test]
    fn a_path_in_a_link_is_percent_encoded() {
        assert_eq!(url_path("src/a b#c.py"), "src/a%20b%23c.py");
    }
}

//! Structural rewrite: each match of a tree-sitter query replaced with a template of its
//! captures, shown as a unified diff or written file by file, whole, by rename.

use std::path::{Path, PathBuf};

use anyhow::{bail, Result};

/// One file the rewrite changes.
pub struct FileChange {
    pub path: PathBuf,
    /// the path as `tsquery` prints it
    pub shown: String,
    /// the bytes read, which must still be on disk when the file is written
    pub read: Vec<u8>,
    pub new: Vec<u8>,
    /// matches replaced
    pub replaced: usize,
    /// each replaced range: (old start, old end, new start, new end) in bytes
    spans: Vec<(usize, usize, usize, usize)>,
}

/// What a rewrite would do: the files it changes, in path order, and why it leaves the others
/// and some matches alone.
pub struct Plan {
    pub files: Vec<FileChange>,
    /// a file left alone, as `PATH: why`
    pub left: Vec<String>,
    /// a match inside another one, as `PATH:LINE:COLUMN: why`
    pub skipped: Vec<String>,
}

enum Piece {
    Text(String),
    Capture(usize),
}

/// The template's pieces: `$NAME` and `${NAME}` the text of capture `@NAME`, `$$` a dollar.
fn template(t: &str, names: &[&str]) -> Result<Vec<Piece>> {
    let mut out = Vec::new();
    let mut text = String::new();
    let mut rest = t;
    while let Some(i) = rest.find('$') {
        text.push_str(&rest[..i]);
        rest = &rest[i + 1..];
        if let Some(r) = rest.strip_prefix('$') {
            text.push('$');
            rest = r;
            continue;
        }
        let (name, after) = if let Some(r) = rest.strip_prefix('{') {
            let Some(end) = r.find('}') else { bail!("the template has a ${{ without its }}") };
            (&r[..end], &r[end + 1..])
        } else {
            let end = rest.find(|c: char| !(c.is_ascii_alphanumeric() || c == '_')).unwrap_or(rest.len());
            (&rest[..end], &rest[end..])
        };
        if name.is_empty() {
            bail!("the template has a $ without a capture name: write $$ for a dollar");
        }
        let Some(k) = names.iter().position(|n| *n == name) else {
            bail!("the template names ${name}, but the query has no @{name} (it has {})", names.iter().map(|n| format!("@{n}")).collect::<Vec<_>>().join(", "));
        };
        out.push(Piece::Text(std::mem::take(&mut text)));
        out.push(Piece::Capture(k));
        rest = after;
    }
    text.push_str(rest);
    out.push(Piece::Text(text));
    Ok(out)
}

/// Whether an error or missing node of the tree touches `start..end`.
fn broken(root: tree_sitter::Node, start: usize, end: usize) -> bool {
    let mut stack = vec![root];
    while let Some(n) = stack.pop() {
        if !n.has_error() || n.end_byte() < start || n.start_byte() > end {
            continue;
        }
        if n.is_error() || n.is_missing() {
            return true;
        }
        let mut c = n.walk();
        stack.extend(n.children(&mut c));
    }
    false
}

/// The rewrite of each file of `lang` under `paths` with `template`, read and parsed now (the
/// capture cache is not used). Files outside `root`, and links, are left alone.
pub fn plan(lang: &str, query: &str, template_text: &str, paths: &[PathBuf], root: &Path) -> Result<Plan> {
    use rayon::prelude::*;
    let (spec, language, q) = crate::intel::compile_query(lang, query)?;
    let names = q.capture_names();
    let pieces = template(template_text, names)?;
    let outer = names.iter().position(|n| *n == "match");
    let top = std::fs::canonicalize(root)?;
    let files = crate::intel::query_files(spec, paths, true);
    let results: Vec<(Option<FileChange>, Option<String>, Vec<String>)> = files
        .par_iter()
        .map_init(
            || {
                let mut p = tree_sitter::Parser::new();
                let ok = p.set_language(&language).is_ok();
                (p, ok)
            },
            |(parser, ok), f| {
                let mut skipped = Vec::new();
                let alone = |why: &str, skipped: Vec<String>| (None, Some(format!("{}: {why}, left alone", f.shown)), skipped);
                if !*ok {
                    return alone("the parser did not load", skipped);
                }
                if !std::fs::canonicalize(&f.path).is_ok_and(|p| p.starts_with(&top)) {
                    return alone("outside the root", skipped);
                }
                if !std::fs::symlink_metadata(&f.path).is_ok_and(|m| m.file_type().is_file()) {
                    return alone("not a regular file", skipped);
                }
                let Ok(raw) = std::fs::read(&f.path) else { return alone("could not be read", skipped) };
                let ours = |src: &str| crate::parse::spec_for(&f.rel, src).map(|s| s.id) == Some(spec.id);
                let src = match crate::index::decode_source(&raw) {
                    Some(std::borrow::Cow::Borrowed(s)) if ours(s) => s,
                    // UTF-16, or bytes that are not UTF-8: the parsed text is not the file
                    Some(std::borrow::Cow::Owned(s)) if ours(&s) => return alone("not UTF-8 text", skipped),
                    _ => return (None, None, skipped),
                };
                let Some(tree) = parser.parse(src, None) else { return alone("did not parse", skipped) };
                // (start, end, replacement, pattern)
                let mut edits: Vec<(usize, usize, String, usize)> = Vec::new();
                let mut cursor = tree_sitter::QueryCursor::new();
                cursor.set_match_limit(1 << 16);
                let mut matches = cursor.matches(&q, tree.root_node(), src.as_bytes());
                use tree_sitter::StreamingIterator;
                while let Some(m) = matches.next() {
                    // a capture's text runs from its first node to its last
                    let span = |k: usize| {
                        let nodes = m.captures.iter().filter(|c| c.index as usize == k).map(|c| c.node.byte_range());
                        nodes.fold(None, |acc: Option<(usize, usize)>, r| Some(acc.map_or((r.start, r.end), |(s, e)| (s.min(r.start), e.max(r.end)))))
                    };
                    // without @match the widest capture, the first written on a tie
                    let target = outer.and_then(span).or_else(|| (0..names.len()).filter_map(span).min_by_key(|&(s, e)| (s, std::cmp::Reverse(e))));
                    let Some((start, end)) = target else { continue };
                    let mut repl = String::new();
                    for p in &pieces {
                        match p {
                            Piece::Text(t) => repl.push_str(t),
                            Piece::Capture(k) => repl.push_str(span(*k).map_or("", |(s, e)| &src[s..e])),
                        }
                    }
                    if repl != src[start..end] {
                        edits.push((start, end, repl, m.pattern_index));
                    }
                }
                // outermost first; a match that starts inside a kept one is not rewritten
                edits.sort_by_key(|e| (e.0, std::cmp::Reverse(e.1), e.3));
                let mut kept: Vec<(usize, usize, String)> = Vec::new();
                for (start, end, repl, _) in edits {
                    if let Some(last) = kept.last().filter(|k| start < k.1 || (start, end) == (k.0, k.1)) {
                        let at = |b: usize| (src[..b].matches('\n').count() + 1, b - src[..b].rfind('\n').map_or(0, |i| i + 1) + 1);
                        let ((l, c), (ol, oc)) = (at(start), at(last.0));
                        skipped.push(format!("{}:{l}:{c}: inside the match at {ol}:{oc}, not rewritten", f.shown));
                        continue;
                    }
                    kept.push((start, end, repl));
                }
                if kept.is_empty() {
                    return (None, None, skipped);
                }
                if kept.iter().any(|k| broken(tree.root_node(), k.0, k.1)) {
                    return alone("a match holds text that does not parse", skipped);
                }
                let mut new = String::with_capacity(src.len());
                let mut at = 0;
                let mut spans = Vec::with_capacity(kept.len());
                for (start, end, repl) in &kept {
                    new.push_str(&src[at..*start]);
                    spans.push((*start, *end, new.len(), new.len() + repl.len()));
                    new.push_str(repl);
                    at = *end;
                }
                new.push_str(&src[at..]);
                let parsed = parser.parse(&new, None);
                if !parsed.is_some_and(|t| !spans.iter().any(|s| broken(t.root_node(), s.2, s.3))) {
                    return alone("the rewritten text does not parse", skipped);
                }
                let change = FileChange { path: f.path.clone(), shown: f.shown.clone(), replaced: kept.len(), new: new.into_bytes(), read: raw, spans };
                (Some(change), None, skipped)
            },
        )
        .collect();
    let mut plan = Plan { files: Vec::new(), left: Vec::new(), skipped: Vec::new() };
    for (change, left, skipped) in results {
        plan.files.extend(change);
        plan.left.extend(left);
        plan.skipped.extend(skipped);
    }
    Ok(plan)
}

impl Plan {
    /// A unified diff of every change, three lines of context, paths as shown (`patch -p0` applies it).
    pub fn diff(&self) -> String {
        let mut out = String::new();
        for f in &self.files {
            // both sides are UTF-8: the plan takes no other file
            out.push_str(&unified(&f.shown, &String::from_utf8_lossy(&f.read), &String::from_utf8_lossy(&f.new), &f.spans));
        }
        out
    }

    /// Write each changed file whole by rename, only while its bytes on disk are those read.
    /// Returns, per file in order, why it was left alone (`PATH: why, left alone`) or nothing.
    pub fn write(&self) -> Vec<Option<String>> {
        self.files.iter().map(|f| write_one(f).err().map(|why| format!("{}: {why}, left alone", f.shown))).collect()
    }
}

fn write_one(f: &FileChange) -> Result<(), String> {
    use std::io::Write;
    let md = std::fs::symlink_metadata(&f.path).map_err(|e| e.to_string())?;
    if !md.file_type().is_file() {
        return Err("not a regular file".into());
    }
    let name = f.path.file_name().ok_or("no file name")?.to_string_lossy();
    let tmp = f.path.with_file_name(format!(".{name}.scrutate-{}.tmp", std::process::id()));
    let written = (|| -> std::io::Result<bool> {
        let mut out = std::fs::OpenOptions::new().write(true).create_new(true).open(&tmp)?;
        out.write_all(&f.new)?;
        out.sync_all()?;
        drop(out);
        std::fs::set_permissions(&tmp, md.permissions())?;
        if std::fs::read(&f.path)? != f.read {
            return Ok(false);
        }
        std::fs::rename(&tmp, &f.path)?;
        Ok(true)
    })();
    match written {
        Ok(true) => Ok(()),
        Ok(false) => {
            let _ = std::fs::remove_file(&tmp);
            Err("changed since it was read".into())
        }
        Err(e) => {
            let _ = std::fs::remove_file(&tmp);
            Err(e.to_string())
        }
    }
}

/// `diff -u` of a file whose edits are known: `spans` are (old start, old end, new start, new
/// end) byte ranges in order, and the text between them is the same on both sides.
fn unified(path: &str, old: &str, new: &str, spans: &[(usize, usize, usize, usize)]) -> String {
    let a: Vec<&str> = old.split_inclusive('\n').collect();
    let b: Vec<&str> = new.split_inclusive('\n').collect();
    let line = |t: &str, at: usize| t[..at].matches('\n').count();
    // per run of edits on the same or neighbouring lines: (old first line, old end line, new first line, new end line)
    let mut runs: Vec<(usize, usize, usize, usize)> = Vec::new();
    for &(os, oe, ns, ne) in spans {
        let r = (line(old, os), line(old, oe) + 1, line(new, ns), line(new, ne) + 1);
        match runs.last_mut() {
            Some(last) if r.0 <= last.1 => (last.1, last.3) = (r.1, r.3),
            _ => runs.push(r),
        }
    }
    // lines a run holds alike on both sides are context
    for r in &mut runs {
        (r.1, r.3) = (r.1.min(a.len()), r.3.min(b.len()));
        while r.0 < r.1 && r.2 < r.3 && a[r.0] == b[r.2] {
            (r.0, r.2) = (r.0 + 1, r.2 + 1);
        }
        while r.0 < r.1 && r.2 < r.3 && a[r.1 - 1] == b[r.3 - 1] {
            (r.1, r.3) = (r.1 - 1, r.3 - 1);
        }
    }
    let mut out = format!("--- {path}\n+++ {path}\n");
    let push = |out: &mut String, mark: char, l: &str| {
        out.push(mark);
        out.push_str(l);
        if !l.ends_with('\n') {
            out.push_str("\n\\ No newline at end of file\n");
        }
    };
    let mut r = 0;
    while r < runs.len() {
        let mut last = r;
        while last + 1 < runs.len() && runs[last + 1].0 <= runs[last].1 + 6 {
            last += 1;
        }
        let o0 = runs[r].0.saturating_sub(3);
        let n0 = runs[r].2 - (runs[r].0 - o0);
        let o1 = (runs[last].1 + 3).min(a.len());
        let n1 = runs[last].3 + (o1 - runs[last].1);
        let start = |s: usize, n: usize| if n == 0 { s } else { s + 1 };
        out.push_str(&format!("@@ -{},{} +{},{} @@\n", start(o0, o1 - o0), o1 - o0, start(n0, n1 - n0), n1 - n0));
        let mut at = o0;
        for run in &runs[r..=last] {
            a[at..run.0].iter().for_each(|l| push(&mut out, ' ', l));
            a[run.0..run.1].iter().for_each(|l| push(&mut out, '-', l));
            b[run.2..run.3].iter().for_each(|l| push(&mut out, '+', l));
            at = run.1;
        }
        a[at..o1].iter().for_each(|l| push(&mut out, ' ', l));
        r = last + 1;
    }
    out
}

//! How many big searches (a walk of directories, a list of many files) this user runs at once,
//! across processes, so that each takes its share of threads (`instant::policy`). The count is a
//! System V semaphore: a search adds 1 with `SEM_UNDO`, so the kernel
//! takes it back when the process dies, however it dies. Anything that fails (no System V IPC, a
//! set with that key made by another user, a limit) leaves the count unknown and the search runs
//! as it would alone. Only on macOS: on Linux the cores are the limit, and splitting them never
//! beat each search taking them all (py-big on 5 CPUs, 4 at once: 53 ms on 5 threads each, 60 ms
//! on 1, 53 ms on 2).

use std::io::Write;
use std::sync::atomic::{AtomicBool, AtomicI32, AtomicUsize, Ordering};

/// What this process does to the count: `HELD` searches, none while a write to stdout may block
/// (a reader that stopped reading must not slow the others) or while the process is stopped from
/// its terminal. All changed under `LOCK`, a flag and no mutex so that the signal handler can try
/// it without waiting.
static LOCK: AtomicBool = AtomicBool::new(false);
static HELD: AtomicUsize = AtomicUsize::new(0);
static WRITING: AtomicUsize = AtomicUsize::new(0);
static STOPPING: AtomicUsize = AtomicUsize::new(0);
/// what the process has in the count now
static COUNTED: AtomicUsize = AtomicUsize::new(0);
/// the set, once a search has asked for it
static SET: AtomicI32 = AtomicI32::new(-1);
/// SIGTSTP is ours to handle while a search is held
static WATCHING: AtomicBool = AtomicBool::new(false);
/// SIGTSTP came while the lock was held: its holder stops the process when it lets go
static STOP_ASKED: AtomicBool = AtomicBool::new(false);

fn lock() {
    while LOCK.swap(true, Ordering::Acquire) {
        std::hint::spin_loop();
    }
}

fn locked<T>(f: impl FnOnce() -> T) -> T {
    lock();
    let r = f();
    LOCK.store(false, Ordering::Release);
    if STOP_ASKED.swap(false, Ordering::Relaxed) {
        lock();
        stop();
    }
    r
}

/// Brings the count to what the state asks for; `false` when the system refused.
fn settle() -> bool {
    let out = WRITING.load(Ordering::Relaxed) > 0 || STOPPING.load(Ordering::Relaxed) > 0;
    let want = if out { 0 } else { HELD.load(Ordering::Relaxed) };
    let have = COUNTED.load(Ordering::Relaxed);
    if want != have {
        if !sys::add(SET.load(Ordering::Relaxed), want as i32 - have as i32) {
            return false;
        }
        COUNTED.store(want, Ordering::Relaxed);
    }
    true
}

/// Ctrl-Z while a search is counted. A stopped search must not keep threads from the others, so
/// it leaves the count, stops as it would have, and joins again when it is continued. SIGSTOP
/// cannot be caught: a search stopped that way stays counted.
extern "C" fn on_stop(_: std::ffi::c_int) {
    if LOCK.swap(true, Ordering::Acquire) {
        // the thread this interrupted may be the holder: no waiting here
        STOP_ASKED.store(true, Ordering::Relaxed);
        return;
    }
    stop();
}

/// Called with the lock held; lets it go. Only atomics and system calls: it runs in the handler.
fn stop() {
    loop {
        STOPPING.fetch_add(1, Ordering::Relaxed);
        settle();
        LOCK.store(false, Ordering::Release);
        // a stop asked for until here is this one
        STOP_ASKED.store(false, Ordering::Relaxed);
        sys::stop_self();
        lock();
        STOPPING.fetch_sub(1, Ordering::Relaxed);
        if HELD.load(Ordering::Relaxed) > 0 && WATCHING.load(Ordering::Relaxed) {
            sys::watch_stop(on_stop);
        }
        settle();
        LOCK.store(false, Ordering::Release);
        if !STOP_ASKED.swap(false, Ordering::Relaxed) {
            return;
        }
        lock();
    }
}

/// One big search, counted while this lives.
pub struct Counted(());

impl Counted {
    pub fn start() -> Option<Counted> {
        let id = sys::id()?;
        locked(|| {
            // a set made again after someone removed it: what was counted went with the old one
            if SET.swap(id, Ordering::Relaxed) != id {
                COUNTED.store(0, Ordering::Relaxed);
            }
            HELD.fetch_add(1, Ordering::Relaxed);
            if !settle() {
                HELD.fetch_sub(1, Ordering::Relaxed);
                return None;
            }
            if HELD.load(Ordering::Relaxed) == 1 {
                WATCHING.store(sys::watch_stop(on_stop), Ordering::Relaxed);
            }
            Some(Counted(()))
        })
    }

    /// The big searches running now, this one included.
    pub fn running(&self) -> Option<usize> {
        sys::value(SET.load(Ordering::Relaxed)).map(|n| n.max(1))
    }
}

impl Drop for Counted {
    fn drop(&mut self) {
        locked(|| {
            if HELD.fetch_sub(1, Ordering::Relaxed) == 1 && WATCHING.swap(false, Ordering::Relaxed) {
                sys::unwatch_stop(on_stop);
            }
            settle();
        });
    }
}

/// Stdout that takes this process's searches out of the count while a write to it may block.
pub struct GivesWay(pub std::io::Stdout);

impl GivesWay {
    fn around<T>(&mut self, f: impl FnOnce(&mut std::io::Stdout) -> T) -> T {
        if HELD.load(Ordering::Relaxed) == 0 || !sys::stdout_may_block() {
            return f(&mut self.0);
        }
        locked(|| {
            WRITING.fetch_add(1, Ordering::Relaxed);
            settle();
        });
        let r = f(&mut self.0);
        locked(|| {
            WRITING.fetch_sub(1, Ordering::Relaxed);
            settle();
        });
        r
    }
}

impl Write for GivesWay {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        self.around(|o| o.write(buf))
    }
    fn flush(&mut self) -> std::io::Result<()> {
        self.around(|o| o.flush())
    }
}

#[cfg(target_os = "macos")]
mod sys {
    use std::ffi::c_int;

    pub type Id = c_int;

    // as `struct sembuf` in <sys/sem.h>
    #[repr(C)]
    struct Sembuf {
        num: u16,
        op: i16,
        flg: i16,
    }

    // as `struct sigaction` in <sys/signal.h>
    #[repr(C)]
    struct Sigaction {
        handler: usize,
        mask: u32,
        flags: c_int,
    }

    extern "C" {
        fn semget(key: c_int, nsems: c_int, flags: c_int) -> c_int;
        fn semop(id: c_int, ops: *mut Sembuf, n: usize) -> c_int;
        fn semctl(id: c_int, num: c_int, cmd: c_int, ...) -> c_int;
        fn getuid() -> u32;
        fn sigaction(sig: c_int, act: *const Sigaction, old: *mut Sigaction) -> c_int;
        fn raise(sig: c_int) -> c_int;
        fn pthread_sigmask(how: c_int, set: *const u32, old: *mut u32) -> c_int;
    }

    const IPC_CREAT: c_int = 0o1000;
    const IPC_STAT: c_int = 2;
    const IPC_NOWAIT: i16 = 0o4000;
    const SEM_UNDO: i16 = 0o10000;
    const GETVAL: c_int = 5;
    /// Byte offset of `sem_perm.cuid` in `struct semid_ds`
    const CUID_AT: usize = 8;
    const SIGTSTP: c_int = 18;
    const SIG_DFL: usize = 0;
    const SIG_UNBLOCK: c_int = 2;
    const SA_RESTART: c_int = 2;
    const DEFAULT: Sigaction = Sigaction { handler: SIG_DFL, mask: 0, flags: 0 };

    /// The set, made when it is not there: one semaphore, read and written by this user only.
    /// Asked for by every big search (two system calls), so a process that lives long finds a
    /// set made again after its first one was removed.
    pub fn id() -> Option<Id> {
        // SAFETY: no arguments
        let uid = unsafe { getuid() };
        // 0 is IPC_PRIVATE, a new set on every call
        let key = (0x5343_5254 ^ uid) as c_int;
        if key == 0 {
            return None;
        }
        // SAFETY: plain integers
        let id = unsafe { semget(key, 1, IPC_CREAT | 0o600) };
        if id < 0 {
            return None;
        }
        // a set another user made with this key and opened to others is not ours to count in
        let mut ds = [0u64; 64];
        // SAFETY: larger than `struct semid_ds` (72 bytes); IPC_STAT takes a pointer to it as
        // the fourth argument
        if unsafe { semctl(id, 0, IPC_STAT, ds.as_mut_ptr()) } != 0 {
            return None;
        }
        let bytes: &[u8] = unsafe { std::slice::from_raw_parts(ds.as_ptr().cast(), 16) };
        let cuid = u32::from_ne_bytes(bytes[CUID_AT..CUID_AT + 4].try_into().ok()?);
        (cuid == uid).then_some(id)
    }

    #[cfg(test)]
    pub fn remove(id: Id) {
        const IPC_RMID: c_int = 0;
        // SAFETY: IPC_RMID takes no fourth argument
        unsafe { semctl(id, 0, IPC_RMID) };
    }

    /// Adds `n` to the count, undone by the kernel when the process ends; never waits.
    pub fn add(id: Id, n: i32) -> bool {
        let mut op = Sembuf { num: 0, op: n as i16, flg: SEM_UNDO | IPC_NOWAIT };
        // SAFETY: one operation, in a struct laid out as `struct sembuf`
        unsafe { semop(id, &mut op, 1) == 0 }
    }

    pub fn value(id: Id) -> Option<usize> {
        // SAFETY: GETVAL takes no fourth argument
        let v = unsafe { semctl(id, 0, GETVAL) };
        (v >= 0).then_some(v as usize)
    }

    /// Takes SIGTSTP when nothing else handles it; `false` leaves the signal as it was.
    pub fn watch_stop(handler: extern "C" fn(c_int)) -> bool {
        // system calls the signal interrupts start again, as they do without a handler
        let ours = Sigaction { handler: handler as usize, mask: 0, flags: SA_RESTART };
        let mut old = DEFAULT;
        // SAFETY: both point to structs laid out as `struct sigaction`
        if unsafe { sigaction(SIGTSTP, &ours, &mut old) } != 0 {
            return false;
        }
        if old.handler == SIG_DFL || old.handler == ours.handler {
            return true;
        }
        // ignored, or the program this runs in has its own handler
        // SAFETY: what `sigaction` filled in
        unsafe { sigaction(SIGTSTP, &old, std::ptr::null_mut()) };
        false
    }

    /// Gives SIGTSTP back, unless the program has set a handler of its own since.
    pub fn unwatch_stop(handler: extern "C" fn(c_int)) {
        let mut now = DEFAULT;
        // SAFETY: structs laid out as `struct sigaction`
        unsafe {
            if sigaction(SIGTSTP, std::ptr::null(), &mut now) == 0 && now.handler == handler as usize {
                sigaction(SIGTSTP, &DEFAULT, std::ptr::null_mut());
            }
        }
    }

    /// Stops the process as SIGTSTP does when nothing handles it; returns once it is continued.
    pub fn stop_self() {
        let set: u32 = 1 << (SIGTSTP - 1);
        // SAFETY: pointers to a constant and a local; sent to this thread with the signal open,
        // so the stop comes before `raise` returns
        unsafe {
            sigaction(SIGTSTP, &DEFAULT, std::ptr::null_mut());
            pthread_sigmask(SIG_UNBLOCK, &set, std::ptr::null_mut());
            raise(SIGTSTP);
        }
    }

    /// Stdout is a pipe, a socket or a terminal, where a write waits for the reader; a file never
    /// makes it wait.
    pub fn stdout_may_block() -> bool {
        static MAY: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
        *MAY.get_or_init(|| {
            use std::io::IsTerminal;
            use std::os::fd::FromRawFd;
            use std::os::unix::fs::FileTypeExt;
            // SAFETY: borrowed for one `fstat`, never closed
            let out = std::mem::ManuallyDrop::new(unsafe { std::fs::File::from_raw_fd(1) });
            out.metadata().is_ok_and(|m| m.file_type().is_fifo() || m.file_type().is_socket()) || std::io::stdout().is_terminal()
        })
    }
}

#[cfg(not(target_os = "macos"))]
mod sys {
    pub type Id = i32;
    pub fn id() -> Option<Id> {
        None
    }
    pub fn add(_: Id, _: i32) -> bool {
        false
    }
    pub fn value(_: Id) -> Option<usize> {
        None
    }
    pub fn stdout_may_block() -> bool {
