#[cfg(all(test, target_os = "macos"))]
mod tests {
    use super::*;

    #[test]
    fn a_set_removed_under_a_running_process_is_made_again() {
        let a = Counted::start().expect("System V semaphores");
        assert!(a.running().is_some());
        sys::remove(SET.load(Ordering::Relaxed));
        assert!(a.running().is_none(), "the set is gone");
        let b = Counted::start().expect("a new set");
        let n = b.running().expect("the new set answers");
        assert!(n >= 2, "both searches of this process are in the new set, {n} counted");
        drop(b);
        assert!(a.running().is_some_and(|n| n >= 1));
    }
}

//! Hybrid retrieval.
//!
//! Candidates come from three sources: field-weighted BM25 over the segment store, semantic vectors,
//! and exact name / qualified-name lookup. Each candidate gets 48 features (per-field BM25, semantic
//! similarities, exactness, literal occurrences, structure, query shape) and the learned ranker
//! orders the best 200 by a linear blend. Without a ranker the linear blend itself is used.

use std::collections::{HashMap, HashSet};
use std::sync::Arc;

use anyhow::Result;
use regex::Regex;
use unicode_normalization::UnicodeNormalization;

use crate::index::{ChunkRow, Index};
use crate::lex::tok_key;
use crate::text::{literal_candidates, name_key, query_terms, query_wholes, Words, QUERY_STOP};

pub const PRUNE: usize = 200; // the learned ranker sees (at most) this many candidates
pub const LEX_LIMIT: usize = 100;
pub const SEM_LIMIT: usize = 100;
pub const CODE_KINDS: &[&str] = &["function", "method", "class", "struct", "trait", "interface", "type", "enum", "impl"];

pub use crate::models::FEATURES;
pub const NFEAT: usize = FEATURES.len();

pub const fn fi(name: &str) -> usize {
    let mut i = 0;
    while i < NFEAT {
        if const_eq(FEATURES[i], name) {
            return i;
        }
        i += 1;
    }
    panic!("unknown feature")
}

const fn const_eq(a: &str, b: &str) -> bool {
    let (a, b) = (a.as_bytes(), b.as_bytes());
    if a.len() != b.len() {
        return false;
    }
    let mut i = 0;
    while i < a.len() {
        if a[i] != b[i] {
            return false;
        }
        i += 1;
    }
    true
}

pub type Features = [f32; NFEAT];

#[derive(Debug, Clone, Default, serde::Serialize)]
pub struct Hit {
    pub id: i64,
    pub path: String,
    pub start: i64,
    pub end: i64,
    pub name: String,
    pub qualname: String,
    pub kind: String,
    #[serde(skip)]
    pub text: String,
    pub score: f64,
    pub why: Vec<(String, serde_json::Value)>,
}

impl Hit {
    pub fn loc(&self) -> String {
        format!("{}:{}-{}", self.path, self.start, self.end)
    }

    pub fn from_row(r: &ChunkRow, with_text: bool) -> Hit {
        Hit {
            id: r.id,
            path: r.path.clone(),
            start: r.start,
            end: r.end,
            name: r.name.clone(),
            qualname: r.qualname.clone(),
            kind: r.kind.clone(),
            text: if with_text { r.text.clone() } else { String::new() },
            score: 0.0,
            why: Vec::new(),
        }
    }

    /// Up to `max_lines` lines of the chunk, starting just above the first line mentioning a query word.
    pub fn snippet(&self, words: &[String], max_lines: usize) -> String {
        let lines: Vec<&str> = self.text.split('\n').collect();
        let mut at = 0usize;
        if !words.is_empty() {
            let low: Vec<String> = words.iter().map(|w| w.to_lowercase()).collect();
            for (i, ln) in lines.iter().enumerate() {
                let l = ln.to_lowercase();
                if low.iter().any(|w| l.contains(w.as_str())) {
                    at = i.saturating_sub(1);
                    break;
                }
            }
        }
        lines[at..(at + max_lines).min(lines.len())].join("\n")
    }
}

#[derive(Debug, Clone)]
pub struct QueryInfo {
    pub text: String,
    pub terms: Vec<String>,
    pub wholes: Vec<String>,
    pub lits: Vec<String>,
    pub words: Vec<String>,  // raw lowercase words
    pub keys: Vec<String>,   // underscore-insensitive keys for exact name lookup
    pub dotted: Vec<String>, // Class.method style keys
}

/// The query cut at blanks only, so a name keeps its punctuation.
fn typed_tokens(text: &str) -> impl Iterator<Item = &str> {
    text.split([' ', '\t', '\n', '\r', '\x0b', '\x0c']).filter(|t| !t.is_empty())
}

/// The last part of a dotted token (`Rec.valid?`, `Shape::~Shape`, `Rec#valid?`); the token itself
/// when it has no such part.
fn typed_tail(token: &str) -> &str {
    token.rsplit(['.', ':', '#']).next().filter(|t| !t.is_empty()).unwrap_or(token)
}

/// Whether a token holds an ASCII character that is no letter, digit or underscore.
fn punctuated(token: &str) -> bool {
    token.bytes().any(|b| b.is_ascii() && !b.is_ascii_alphanumeric() && b != b'_')
}

impl QueryInfo {
    pub fn parse(text: &str) -> QueryInfo {
        let words: Vec<String> = Words::new(text).map(|w| w.to_lowercase()).collect();
        let mut keys = Vec::new();
        let mut seen = HashSet::new();
        for w in &words {
            if w.chars().count() >= 3 && !QUERY_STOP.contains(w.as_str()) {
                let k = name_key(w);
                if seen.insert(k.clone()) {
                    keys.push(k);
                }
            }
        }
        // one word, or stop words alone, is most likely a name: `find`, `get`, `id`
        if keys.is_empty() || words.len() == 1 {
            keys.extend(words.iter().map(|w| name_key(w)).filter(|k| !k.is_empty() && seen.insert(k.clone())));
        }
        // a name written with punctuation is stored whole: `valid?`, `Get-Greeting`, `list->vector`
        let tokens: Vec<&str> = typed_tokens(text).collect();
        for t in &tokens {
            for name in [*t, typed_tail(t)] {
                if punctuated(name) && (name.chars().count() >= 3 || tokens.len() == 1) {
                    let k = name_key(name);
                    if seen.insert(k.clone()) {
                        keys.push(k);
                    }
                }
            }
        }
        let dotted_re = Regex::new(r"[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+").unwrap();
        let mut dotted = Vec::new();
        let mut dseen = HashSet::new();
        for m in dotted_re.find_iter(text) {
            let d: Vec<String> = m.as_str().split('.').map(name_key).collect();
            let d = d.join(".");
            if dseen.insert(d.clone()) {
                dotted.push(d);
            }
        }
        QueryInfo { text: text.to_string(), terms: query_terms(text), wholes: query_wholes(text), lits: literal_candidates(text), words, keys, dotted }
    }
}

pub fn lex_keys(q: &QueryInfo) -> Vec<i64> {
    let mut seen = HashSet::new();
    q.terms.iter().chain(&q.wholes).filter(|t| seen.insert((*t).clone())).filter(|t| !t.is_empty()).map(|t| tok_key(t)).collect()
}

pub struct Searcher {
    pub ix: Index,
    ver: Option<String>,
    callers_cache: HashMap<String, i64>,
    /// set when the call being answered was cancelled: `search_many` stops between queries
    pub cancel: Arc<std::sync::atomic::AtomicBool>,
}

/// A source of candidates. The candidates are the union of the sources' ids in `Source::ALL`
/// order; a source with a rank feature sets it to 1 / (1 + rank) for each candidate it found.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Source {
    /// definitions whose name or qualified name the query has (`QueryInfo::keys`, `dotted`)
    Exact,
    /// field-weighted BM25 over the segment store
    Lexical,
    /// the vector model's nearest chunks
    Semantic,
}

impl Source {
    pub const ALL: [Source; 3] = [Source::Exact, Source::Lexical, Source::Semantic];

    pub fn name(self) -> &'static str {
        match self {
            Source::Exact => "exact",
            Source::Lexical => "lex",
            Source::Semantic => "sem",
        }
    }

    fn rank_feature(self) -> Option<usize> {
        match self {
            Source::Exact => None,
            Source::Lexical => Some(fi("lex_rank")),
            Source::Semantic => Some(fi("sem_rank")),
        }
    }
}

/// The BM25 fields as `field_scores` returns them (all fields first), each with its two features.
const LEX_FIELDS: [(usize, usize); 7] = [
    (fi("lex_log"), fi("lex_ratio")),
    (fi("name_log"), fi("name_ratio")),
    (fi("qual_log"), fi("qual_ratio")),
    (fi("sig_log"), fi("sig_ratio")),
    (fi("doc_log"), fi("doc_ratio")),
    (fi("body_log"), fi("body_ratio")),
    (fi("path_log"), fi("path_ratio")),
];

type RowFeature = fn(&ChunkRow) -> f32;
type QueryFeature = fn(&QueryInfo) -> f32;

/// Features of a candidate's own row.
const ROW_FEATURES: [(usize, RowFeature); 11] = [
    (fi("k_function"), |r| (r.kind == "function") as i32 as f32),
    (fi("k_method"), |r| (r.kind == "method") as i32 as f32),
    (fi("k_class"), |r| matches!(r.kind.as_str(), "class" | "struct" | "trait" | "interface" | "type" | "enum" | "impl") as i32 as f32),
    (fi("k_module"), |r| (r.kind == "module") as i32 as f32),
    (fi("k_other"), |r| (r.kind == "window") as i32 as f32),
    (fi("is_test"), |r| r.is_test as f32),
    (fi("log_nbody"), |r| (r.nbody as f64).ln_1p() as f32),
    (fi("has_doc"), |r| (r.ndoc > 0) as i32 as f32),
    (fi("log_ndoc"), |r| (r.ndoc as f64).ln_1p() as f32),
    (fi("qual_depth"), |r| r.qualname.matches('.').count() as f32),
    (fi("is_private"), |r| (r.name.starts_with('_') && !r.name.starts_with("__")) as i32 as f32),
];

/// Features of the query alone, the same for every candidate.
const QUERY_FEATURES: [(usize, QueryFeature); 4] = [
    (fi("n_terms"), |q| q.terms.len() as f32),
    (fi("n_lits"), |q| q.lits.len() as f32),
    (fi("n_words"), |q| q.words.len() as f32),
    (fi("has_ident"), |q| (!q.keys.is_empty() && (!q.dotted.is_empty() || q.text.contains('_') || !q.wholes.is_empty())) as i32 as f32),
];

pub struct Candidates {
    pub q: QueryInfo,
    pub rows: Vec<ChunkRow>,
    pub x: Vec<Features>,
    /// the ids each source found, best first, in `Source::ALL` order
    pub found: [Vec<i64>; 3],
}

impl Candidates {
    pub fn ids(&self, source: Source) -> &[i64] {
        &self.found[source as usize]
    }
}

/// A symbol name with every separator a language writes (`::`, `->`, `#`) as a dot. A separator
/// stands between two names, so the arrow of `operator->` stays.
pub(crate) fn dotted(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    let mut rest = name;
    while let Some(c) = rest.chars().next() {
        let sep = ["::", "->", "#"].into_iter().find(|s| rest.starts_with(s));
        let follows = |s: &str| rest[s.len()..].chars().next().is_some_and(|n| n.is_alphanumeric() || n == '_' || n == '~');
        match sep {
            Some(s) if !out.ends_with("operator") && follows(s) => {
                // a leading separator (`::make`) names the top level: nothing before the name
                if !out.is_empty() {
                    out.push('.');
                }
                rest = &rest[s.len()..];
            }
            _ => {
                out.push(c);
                rest = &rest[c.len_utf8()..];
            }
        }
    }
    out
}

/// A dotted name with a PHP namespace's `\` as a dot and generic arguments (`<T>`, `<'a, T>`)
/// dropped, so `Stack<T>.push` and `App\Models\User.find` compare with `Stack.push`, `User.find`.
fn plain(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    let mut depth = 0usize;
    for (i, c) in name.char_indices() {
        match c {
            '<' if depth > 0 || (!out.ends_with("operator") && out.ends_with(|p: char| p.is_alphanumeric() || p == '_') && name[i..].contains('>')) => {
                depth += 1
            }
            '>' if depth > 0 => depth -= 1,
            _ if depth > 0 => {}
            '\\' => out.push('.'),
            _ => out.push(c),
        }
    }
    out
}

impl Searcher {
    pub fn new(ix: Index) -> Searcher {
        Searcher { ix, ver: None, callers_cache: HashMap::new(), cancel: Arc::default() }
    }

    fn sync(&mut self) -> Result<()> {
        self.ix.lex()?;
        // the database's identity too: one built again in its place can reach the same version
        let ver = Some(format!("{:?} {:?}", self.ix.db_id(), self.ix.meta("data_version")));
        if ver != self.ver {
            self.ver = ver;
            self.callers_cache.clear();
        }
        Ok(())
    }

    fn exact(&self, q: &QueryInfo, limit: usize) -> Result<Vec<i64>> {
        let mut out: Vec<i64> = Vec::new();
        if !q.keys.is_empty() {
            out = self.ix.ids_named(&q.keys, limit)?;
        }
        for d in &q.dotted {
            let last = d.rsplit('.').next().unwrap_or(d);
            for (id, qk) in self.ix.qual_keys_named(last)? {
                if qk == *d || qk.ends_with(&format!(".{d}")) {
                    out.push(id);
                }
            }
        }
        let mut seen = HashSet::new();
        out.retain(|i| seen.insert(*i));
        Ok(out)
    }

    /// chunk id -> (lines mentioning an identifier-like query token, is that token the chunk's name)
    fn literal_hits(lits: &[String], rows: &[ChunkRow]) -> HashMap<i64, (i64, i64)> {
        let pats: Vec<(String, String)> = lits.iter().take(3).map(|l| (l.to_lowercase(), name_key(l))).collect();
        let mut out = HashMap::new();
        for row in rows {
            let low = row.text.to_lowercase();
            let hits: i64 = low.split('\n').map(|ln| pats.iter().filter(|(p, _)| ln.contains(p.as_str())).count() as i64).sum();
            let is_def = pats.iter().any(|(_, k)| row.name_key == *k) as i64;
            if hits > 0 || is_def > 0 {
                out.insert(row.id, (hits, is_def));
            }
        }
        out
    }

    fn ncallers(&mut self, names: &[String]) -> Result<()> {
        let mut need: Vec<&String> = names.iter().filter(|n| !n.is_empty() && !self.callers_cache.contains_key(*n)).collect();
        need.sort();
        need.dedup();
        let got = self.ix.call_counts(&need)?;
        for n in need {
            self.callers_cache.insert(n.clone(), got.get(n).copied().unwrap_or(0));
        }
        Ok(())
    }

    // ------------------------------------------------------------ candidates + features
    pub fn candidates(&mut self, query: &str, use_literal: bool) -> Result<Candidates> {
        let q = QueryInfo::parse(query);
        self.sync()?;
        let keys = lex_keys(&q);
        let models = Arc::clone(&self.ix.models);
        let model = if q.terms.is_empty() || !self.ix.vectors_fit() { None } else { models.semantic()? };
        let qz: Option<Vec<f32>> = model.and_then(|m| m.encode_query(&q.terms));
        let mut found: [Vec<i64>; 3] = Default::default();
        for s in Source::ALL {
            found[s as usize] = self.find(s, &q, &keys, qz.as_deref())?;
        }
        let want_lit = use_literal && !q.lits.is_empty();
        let mut ids: Vec<i64> = Vec::new();
        let mut seen = HashSet::new();
        for &i in found.iter().flatten() {
            if seen.insert(i) {
                ids.push(i);
            }
        }
        if ids.is_empty() {
            return Ok(Candidates { q, rows: Vec::new(), x: Vec::new(), found });
        }
        let by_id = self.ix.chunks(&ids)?;
        ids.retain(|i| by_id.contains_key(i));
        let rows: Vec<ChunkRow> = ids.iter().map(|i| by_id[i].clone()).collect();
        let n = ids.len();
        let lit = if want_lit { Self::literal_hits(&q.lits, &rows) } else { HashMap::new() };

        let mut x: Vec<Features> = vec![[0f32; NFEAT]; n];
        for s in Source::ALL {
            let Some(f) = s.rank_feature() else { continue };
            let rank: HashMap<i64, usize> = found[s as usize].iter().enumerate().map(|(r, &c)| (c, r + 1)).collect();
            for r in 0..n {
                x[r][f] = rank.get(&ids[r]).map(|&k| 1.0 / (1.0 + k as f32)).unwrap_or(0.0);
            }
        }
        // --- lexical
        let s = self.ix.lex()?.field_scores(&keys, &ids)?;
        for (j, &(lg, ra)) in LEX_FIELDS.iter().enumerate() {
            let mx = s.iter().map(|r| r[j]).fold(f32::NEG_INFINITY, f32::max).max(1e-9);
            for (r, row) in s.iter().enumerate() {
                let col = row[j].max(0.0);
                x[r][lg] = (col as f64).ln_1p() as f32;
                x[r][ra] = col / mx;
            }
        }
        let lx: Vec<f32> = s.iter().map(|r| r[0]).collect();
        let (mean, std) = mean_std(&lx);
        for r in 0..n {
            x[r][fi("lex_z")] = (lx[r] - mean) / (std + 1e-9);
        }
        // --- semantic
        if let Some(z) = &qz {
            let (sa, sb) = self.ix.lex()?.sem_pair(&ids, z)?;
            let mix: Vec<f32> = sa.iter().zip(&sb).map(|(a, b)| 0.5 * (a + b)).collect();
            for (src, dst, zdst) in [(&sa, "sem_a", "sem_a_z"), (&sb, "sem_b", "sem_b_z"), (&mix, "sem_mix", "sem_mix_z")] {
                let (m, sd) = mean_std(src);
                for r in 0..n {
                    x[r][fi(dst)] = src[r];
                    x[r][fi(zdst)] = (src[r] - m) / (sd + 1e-9);
                }
            }
        }
        // --- exactness / name overlap / structure
        let tset: HashSet<&str> = q.terms.iter().map(|s| s.as_str()).collect();
        let exact_set: HashSet<i64> = found[Source::Exact as usize].iter().copied().collect();
        let names: Vec<String> = rows.iter().map(|r| r.name.clone()).collect();
        for (r, row) in rows.iter().enumerate() {
            let cid = ids[r];
            let nt: HashSet<&str> = row.name_tok.split_whitespace().collect();
            let inter = nt.intersection(&tset).count();
            let f = &mut x[r];
            f[fi("exact_name")] = (exact_set.contains(&cid) && q.keys.contains(&row.name_key)) as i32 as f32;
            f[fi("exact_qual")] = (exact_set.contains(&cid) && !q.dotted.is_empty()) as i32 as f32;
            f[fi("name_overlap")] = if tset.is_empty() { 0.0 } else { inter as f32 / tset.len() as f32 };
            f[fi("name_cover")] = if nt.is_empty() { 0.0 } else { inter as f32 / nt.len() as f32 };
            f[fi("name_same_set")] = (!nt.is_empty() && nt == tset) as i32 as f32;
            if let Some(&(hits, is_def)) = lit.get(&cid) {
                f[fi("lit_hits")] = (hits as f64).ln_1p() as f32;
                f[fi("lit_def")] = is_def as f32;
            }
            for (i, feature) in ROW_FEATURES {
                f[i] = feature(row);
            }
        }
        // a name the query has as typed, in one Unicode form: a whole token first, punctuation and
        // case included (`valid?` is not `valid`, `BurstFiles` not `burst_files`), then the last
        // part of a dotted token, then a word of letters and digits; when no candidate is spelled
        // as typed, every exact name is as near as it gets
        let nfc = |s: &str| s.nfc().collect::<String>();
        let named: Vec<String> = names.iter().map(|nm| nfc(nm)).collect();
        let spelled = |typed: HashSet<String>| {
            let hits: Vec<bool> = named.iter().map(|nm| !nm.is_empty() && typed.contains(nm)).collect();
            hits.contains(&true).then_some(hits)
        };
        let as_typed = spelled(typed_tokens(&q.text).map(nfc).collect())
            .or_else(|| spelled(typed_tokens(&q.text).map(|t| nfc(typed_tail(t))).collect()))
            .or_else(|| spelled(Words::new(&q.text).map(nfc).collect()));
        for r in 0..names.len() {
            x[r][fi("exact_case")] = match &as_typed {
                Some(hits) => hits[r] as i32 as f32,
                None => x[r][fi("exact_name")],
            };
        }
        self.ncallers(&names)?;
        for (r, nm) in names.iter().enumerate() {
            let c = self.callers_cache.get(nm).copied().unwrap_or(0);
            x[r][fi("log_ncallers")] = (c as f64).ln_1p() as f32;
        }
        // --- query level + file cohesion
        let query_level = QUERY_FEATURES.map(|(i, feature)| (i, feature(&q)));
        let mut top_paths: HashMap<&str, usize> = HashMap::new();
        for cid in found[Source::Lexical as usize].iter().take(30) {
            if let Some(r) = by_id.get(cid) {
                *top_paths.entry(r.path.as_str()).or_insert(0) += 1;
            }
        }
        for (r, row) in rows.iter().enumerate() {
            let f = &mut x[r];
            for (i, v) in query_level {
                f[i] = v;
            }
            f[fi("file_frac")] = top_paths.get(row.path.as_str()).copied().unwrap_or(0) as f32 / 30.0;
        }
        Ok(Candidates { q, rows, x, found })
    }

    /// The ids `source` finds for the query, best first.
    fn find(&mut self, source: Source, q: &QueryInfo, keys: &[i64], qz: Option<&[f32]>) -> Result<Vec<i64>> {
        Ok(match (source, qz) {
            (Source::Exact, _) => self.exact(q, 60)?,
            (Source::Lexical, _) => self.ix.lex()?.search(keys, LEX_LIMIT)?.0,
            (Source::Semantic, Some(z)) => self.ix.lex()?.semantic_top(z, SEM_LIMIT, None)?,
            (Source::Semantic, None) => Vec::new(),
        })
    }

    // ---------------------------------------------------------------------- scoring
    /// Scores of candidate feature rows: the ranker's, or the linear blend without one. A ranker
    /// that does not fit this engine's features is an error.
    pub fn score(&self, x: &[Features]) -> Result<Vec<f64>> {
        let n = x.len();
        if n == 0 {
            return Ok(Vec::new());
        }
        let lin: Vec<f32> = x.iter().map(linear_score).collect();
        let Some(ranker) = self.ix.models.ranker()? else {
            return Ok(lin.iter().map(|&v| v as f64).collect());
        };
        let keep = prune_indices(&lin, PRUNE);
        let mut out = vec![-1e9f64; n];
        for &i in &keep {
            let row: Vec<f64> = x[i].iter().map(|&v| v as f64).collect();
            out[i] = ranker.predict_row(&row);
        }
        Ok(out)
    }

    pub fn hits(&self, c: &Candidates, scores: &[f64], k: usize, with_text: bool) -> Result<Vec<Hit>> {
        // a name typed with its punctuation (`valid?`, `Get-Greeting`, `list->vector`, the last
        // part of `Rec.valid?`) comes first: no name the ranker was fitted on is written so
        let typed: HashSet<String> = typed_tokens(&c.q.text).flat_map(|t| [t, typed_tail(t)]).filter(|t| punctuated(t)).map(|t| t.nfc().collect()).collect();
        let first: Vec<bool> = c.rows.iter().map(|r| !typed.is_empty() && r.kind != "window" && typed.contains(&r.name.nfc().collect::<String>())).collect();
        let mut order: Vec<usize> = (0..c.rows.len()).collect();
        order.sort_by(|&a, &b| {
            first[b].cmp(&first[a]).then(scores[b].partial_cmp(&scores[a]).unwrap_or(std::cmp::Ordering::Equal)).then(c.rows[a].id.cmp(&c.rows[b].id))
        });
        let mut picked: Vec<Hit> = Vec::new();
        let mut best_by_key: HashMap<(String, String, bool), usize> = HashMap::new();
        for r in order {
            let row = &c.rows[r];
            let mut h = Hit::from_row(row, false);
            h.score = scores[r];
            h.why = why(&c.x[r]);
            // a struct and its impl block are two hits
            let key = (h.path.clone(), h.qualname.clone(), h.kind == "impl");
            // a window is a part of the definition it names: one hit per definition, its best part
            let grouped = !h.qualname.is_empty() && (CODE_KINDS.contains(&h.kind.as_str()) || h.kind == "window");
            if grouped {
                if let Some(&pi) = best_by_key.get(&key) {
                    // overload / redefinition: keep the longer body
                    if h.kind != "window" && picked[pi].kind != "window" && (h.end - h.start) > (picked[pi].end - picked[pi].start) {
                        picked[pi] = h;
                    }
                    continue;
                }
            }
            if matches!(h.kind.as_str(), "module" | "window") && picked.iter().any(|p| p.path == h.path && !(h.end < p.start || h.start > p.end)) {
                continue;
            }
            if grouped {
                best_by_key.insert(key, picked.len());
            }
            picked.push(h);
            if picked.len() >= k {
                break;
            }
        }
        if with_text {
            self.fill_text(&mut picked)?;
        }
        Ok(picked)
    }

    fn fill_text(&self, hits: &mut [Hit]) -> Result<()> {
        if hits.is_empty() {
            return Ok(());
        }
        let ids: Vec<i64> = hits.iter().map(|h| h.id).collect();
        let mut texts = self.ix.texts(&ids)?;
        for h in hits {
            h.text = texts.remove(&h.id).unwrap_or_default();
        }
        Ok(())
    }

    pub fn search(&mut self, query: &str, k: usize, with_text: bool) -> Result<Vec<Hit>> {
        let c = self.candidates(query, true)?;
        let scores = self.score(&c.x)?;
        self.hits(&c, &scores, k, with_text)
    }

    /// Several phrasings of one need (synonyms, guessed identifiers): rank-fuse the results.
    pub fn search_many(&mut self, queries: &[String], k: usize, with_text: bool) -> Result<Vec<Hit>> {
        let mut fused: HashMap<i64, f64> = HashMap::new();
        let mut meta: HashMap<i64, Hit> = HashMap::new();
        let mut first_seen: Vec<i64> = Vec::new();
        for q in queries {
            if self.cancel.load(std::sync::atomic::Ordering::Relaxed) {
                anyhow::bail!("cancelled");
            }
            for (r, h) in self.search(q, 30, false)?.into_iter().enumerate() {
                *fused.entry(h.id).or_insert(0.0) += 1.0 / (60.0 + (r + 1) as f64);
                meta.entry(h.id).or_insert_with(|| {
                    first_seen.push(h.id);
                    h
                });
            }
        }
        let mut ids: Vec<i64> = first_seen;
        ids.sort_by(|a, b| fused[b].partial_cmp(&fused[a]).unwrap());
        ids.truncate(k);
        let mut out: Vec<Hit> = ids
            .iter()
            .map(|i| {
                let mut h = meta.remove(i).unwrap();
                h.score = fused[i];
                h
            })
            .collect();
        if with_text {
            self.fill_text(&mut out)?;
        }
        Ok(out)
    }

    // ----------------------------------------------------------------- navigation
    /// The definitions `name` names. Tried in order, the first that finds any wins: the name as
    /// typed (whole stored name, qualified name, or a tail of one); its dotted form (`::`, `->`
    /// and `#` as dots); the same compared with stored qualified names whose owner loses its
    /// generics and path (`Stack<T>.push`, `crate::Thing.run`), either side a tail of the other;
    /// last, for a name written as a path, a top-level definition of its last part
    /// (`crate::util::helper` finds `helper`).
    pub fn find_symbol(&self, name: &str, limit: usize) -> Result<Vec<Hit>> {
        // a Rust raw identifier `r#type` is indexed as `type`
        let name = name.trim();
        let unraw = name.strip_prefix("r#").unwrap_or(name).replace("::r#", "::").replace(".r#", ".");
        let typed = unraw.as_str();
        let d = dotted(typed);
        let d = d.trim_start_matches('.');
        let mut out = self.symbol_rows(typed, limit)?;
        if out.is_empty() && d != typed {
            out = self.symbol_rows(d, limit)?;
        }
        let q = name_key(&plain(d));
        let Some((_, last)) = q.rsplit_once('.') else { return Ok(out) };
        let typed_last = plain(d).rsplit('.').next().unwrap_or_default().to_string();
        let cands = self.ix.qualnames_named(last, &typed_last)?;
        let stored: Vec<(i64, String)> = cands.into_iter().map(|(id, qn)| (id, name_key(&plain(&dotted(&qn))))).collect();
        let tail = |a: &str, b: &str| a == b || a.ends_with(&format!(".{b}"));
        let ids: Vec<i64> = if !out.is_empty() {
            // an out-of-line `Box<T>::put` beside the `Box.put` declaration the lookup found
            stored.iter().filter(|(id, s)| *s == q && !out.iter().any(|h| h.id == *id)).map(|c| c.0).collect()
        } else {
            let owned: Vec<i64> = stored.iter().filter(|(_, s)| s.contains('.') && (tail(s, &q) || tail(&q, s))).map(|c| c.0).collect();
            // only a path (`::`, `\`) can name a module; `obj.helper` says nothing of a free `helper`
            if owned.is_empty() && (typed.contains("::") || typed.contains('\\')) {
                stored.iter().filter(|(_, s)| !s.contains('.')).map(|c| c.0).collect()
            } else {
                owned
            }
        };
        for id in ids.into_iter().take(limit.saturating_sub(out.len())) {
            if let Some(r) = self.ix.chunk(id)? {
                out.push(Hit::from_row(&r, true));
            }
        }
        Ok(out)
    }

    /// Chunks whose stored name or qualified name is `name`, or whose qualified name ends in it.
    pub(crate) fn symbol_rows(&self, name: &str, limit: usize) -> Result<Vec<Hit>> {
        Ok(self.ix.symbols_named(name, limit)?.iter().map(|r| Hit::from_row(r, true)).collect())
    }

    /// The definitions that call what `name` stands for, as the `callers` tool answers.
    pub fn callers(&self, name: &str, limit: usize) -> Result<Vec<Hit>> {
        Ok(crate::names::Names::new(self)?.callers(name, limit)?.0)
    }

    /// -> (resolved definitions, unresolved external names), as the `callees` tool answers.
    pub fn callees(&self, name: &str, limit: usize) -> Result<(Vec<Hit>, Vec<String>)> {
        crate::names::Names::new(self)?.callees(name, limit).map(|(resolved, external, _)| (resolved, external))
    }
}

fn mean_std(v: &[f32]) -> (f32, f32) {
    if v.is_empty() {
        return (0.0, 0.0);
    }
    let n = v.len() as f64;
    let mean = v.iter().map(|&x| x as f64).sum::<f64>() / n;
    let var = v.iter().map(|&x| (x as f64 - mean).powi(2)).sum::<f64>() / n;
    (mean as f32, var.sqrt() as f32)
}

/// Human-readable evidence for a hit, from its feature vector.
pub fn why(x: &Features) -> Vec<(String, serde_json::Value)> {
    let f = |n: &str| x[fi(n)];
    let r2 = |v: f32| serde_json::json!(((v as f64) * 100.0).round() / 100.0);
    let mut out = Vec::new();
    if f("exact_name") > 0.0 || f("exact_qual") > 0.0 {
        out.push(("exact name".to_string(), serde_json::json!(1)));
    }
    for (label, key) in [("name", "name_ratio"), ("signature", "sig_ratio"), ("docs", "doc_ratio"), ("body", "body_ratio"), ("path", "path_ratio")] {
        if f(key) >= 0.5 {
            out.push((format!("{label} keywords"), r2(f(key))));
        }
    }
    if f("sem_mix") >= 0.25 {
        out.push(("semantic".to_string(), r2(f("sem_mix"))));
    }
    if f("lit_hits") > 0.0 {
        out.push(("literal match".to_string(), serde_json::json!(((f("lit_hits") as f64).exp_m1()).round() as i64)));
    }
    out
}

pub fn prune_indices(lin: &[f32], n: usize) -> Vec<usize> {
    let mut idx: Vec<usize> = (0..lin.len()).collect();
    if idx.len() > n {
        idx.select_nth_unstable_by(n - 1, |&a, &b| lin[b].partial_cmp(&lin[a]).unwrap_or(std::cmp::Ordering::Equal).then(a.cmp(&b)));
        idx.truncate(n);
    }
    idx
}

/// Hand-set blend used to pick the ranker's candidates (and as the score without a ranker).
pub fn linear_score(x: &Features) -> f32 {
    let f = |n: &str| x[fi(n)];
    f("lex_z") + 0.9 * f("sem_mix_z") + 2.5 * f("exact_name") + 1.5 * f("exact_qual") + 1.2 * f("lit_def") + 0.3 * f("lit_hits") + 1.0 * f("name_overlap")
        - 0.4 * f("is_test")
}

//! Code-word semantic model, inference only (`bench/train_semantic.py` fits it).
//!
//! Two embedding tables: view A (words that *describe* a function: name, enclosing class, signature,
//! docstring) and view B (identifiers that *implement* it). A text is embedded as the L2-normalised,
//! idf-weighted, sublinear-tf-weighted sum of its word vectors. Training lives in the Python toolkit.

use std::collections::HashMap;
use std::path::Path;
use std::sync::OnceLock;

use anyhow::{anyhow, Context, Result};
use half::f16;

use crate::npy::load_npz_bytes;

pub struct SemanticModel {
    pub va: HashMap<String, usize>,
    pub vb: HashMap<String, usize>,
    idf_a: Vec<f32>,
    idf_b: Vec<f32>,
    u16: Vec<f16>, // [|VA|, k] as stored
    v16: Vec<f16>, // [|VB|, k]
    w: Vec<f32>,   // (s / s[0]) ^ gamma, multiplies every dimension
    pub k: usize,
    pub wa: f32,
    pub cfg: serde_json::Value,
    pub n_pairs: Option<i64>,
    u32: OnceLock<Vec<f32>>,
    v32: OnceLock<Vec<f32>>,
}

fn sublog(c: u32) -> f64 {
    1.0 + (c as f64).ln()
}

impl SemanticModel {
    pub fn load(path: &Path) -> Result<SemanticModel> {
        let bytes = std::fs::read(path).with_context(|| format!("load semantic model {}", path.display()))?;
        Self::from_arrays(load_npz_bytes(&bytes).with_context(|| format!("load semantic model {}", path.display()))?)
    }

    pub fn from_bytes(bytes: &[u8]) -> Result<SemanticModel> {
        Self::from_arrays(load_npz_bytes(bytes).context("load embedded semantic model")?)
    }

    fn from_arrays(arrays: Vec<(String, crate::npy::Npy)>) -> Result<SemanticModel> {
        let mut map: HashMap<String, crate::npy::Npy> = arrays.into_iter().collect();
        let mut take = |name: &str| map.remove(name).ok_or_else(|| anyhow!("model lacks {name}"));
        let va = take("va")?.to_strings()?;
        let vb = take("vb")?.to_strings()?;
        let idf_a = take("idf_a")?.to_vec::<f32>()?;
        let idf_b = take("idf_b")?.to_vec::<f32>()?;
        let u = take("U")?;
        let k = u.shape[1];
        let u16 = u.to_vec::<f16>()?;
        let v16 = take("V")?.to_vec::<f16>()?;
        let s = take("s")?.to_vec::<f32>()?;
        let cfg_s = take("cfg")?.to_strings()?.into_iter().next().unwrap_or_else(|| "{}".into());
        let cfg: serde_json::Value = serde_json::from_str(&cfg_s).unwrap_or(serde_json::Value::Null);
        let gamma = cfg.get("gamma").and_then(|v| v.as_f64()).unwrap_or(0.5) as f32;
        let wa = cfg.get("wa").and_then(|v| v.as_f64()).unwrap_or(0.5) as f32;
        let n_pairs = cfg.get("n_pairs").and_then(|v| v.as_i64());
        let w: Vec<f32> = s.iter().map(|&x| (x / s[0]).powf(gamma)).collect();
        Ok(SemanticModel {
            va: va.into_iter().enumerate().map(|(i, t)| (t, i)).collect(),
            vb: vb.into_iter().enumerate().map(|(i, t)| (t, i)).collect(),
            idf_a,
            idf_b,
            u16,
            v16,
            w,
            k,
            wa,
            cfg,
            n_pairs,
            u32: OnceLock::new(),
            v32: OnceLock::new(),
        })
    }

    /// Build the weighted float32 tables (worth it before embedding many chunks).
    pub fn warm(&self) {
        self.u32.get_or_init(|| self.expand(&self.u16));
        self.v32.get_or_init(|| self.expand(&self.v16));
    }

    fn expand(&self, t: &[f16]) -> Vec<f32> {
        let k = self.k;
        t.iter().enumerate().map(|(i, v)| v.to_f32() * self.w[i % k]).collect()
    }

    fn row_into(&self, table: &[f16], warmed: &OnceLock<Vec<f32>>, i: usize, out: &mut [f32]) {
        let k = self.k;
        if let Some(full) = warmed.get() {
            out.copy_from_slice(&full[i * k..(i + 1) * k]);
        } else {
            for j in 0..k {
                out[j] = table[i * k + j].to_f32() * self.w[j];
            }
        }
    }

    /// Weighted sum of word vectors, accumulated in float64, as the trainer pools them
    /// (`python/scrutate_ref/semantic.py`).
    fn proj(&self, counts: &[(usize, u32)], idf: &[f32], table: &[f16], warmed: &OnceLock<Vec<f32>>) -> Option<Vec<f64>> {
        if counts.is_empty() {
            return None;
        }
        let ws: Vec<f64> = counts.iter().map(|&(i, c)| sublog(c) * idf[i] as f64).collect();
        let n = ws.iter().map(|w| w * w).sum::<f64>().sqrt();
        if n == 0.0 {
            return None;
        }
        let mut z = vec![0f64; self.k];
        let mut row = vec![0f32; self.k];
        for (&(i, _), w) in counts.iter().zip(&ws) {
            let wn = w / n;
            self.row_into(table, warmed, i, &mut row);
            for j in 0..self.k {
                z[j] += wn * row[j] as f64;
            }
        }
        Some(z)
    }

    fn lookup(counts: &HashMap<&str, u32>, vocab: &HashMap<String, usize>) -> Vec<(usize, u32)> {
        let mut out: Vec<(usize, u32)> = counts.iter().filter_map(|(t, &c)| vocab.get(*t).map(|&i| (i, c))).collect();
        out.sort_unstable();
        out
    }

    fn normalize(z: Vec<f64>) -> Option<Vec<f32>> {
        let n = z.iter().map(|v| v * v).sum::<f64>().sqrt();
        if n > 0.0 {
            Some(z.iter().map(|v| (v / n) as f32).collect())
        } else {
            None
        }
    }

    /// Unit vector of a chunk from the word counts of its two views (either may be empty): view A
    /// counts a name word three times and a qualifier, signature or doc word once, view B counts
    /// the body words, as `encode_chunk` of the Python reference does.
    pub fn encode_counts(&self, a: &HashMap<&str, u32>, b: &HashMap<&str, u32>) -> Option<Vec<f32>> {
        let za = self.proj(&Self::lookup(a, &self.va), &self.idf_a, &self.u16, &self.u32);
        let zb = self.proj(&Self::lookup(b, &self.vb), &self.idf_b, &self.v16, &self.v32);
        if za.is_none() && zb.is_none() {
            return None;
        }
        let mut z = vec![0f64; self.k];
        let wa = self.wa as f64;
        if let Some(za) = za {
            for j in 0..self.k {
                z[j] += wa * za[j];
            }
        }
        if let Some(zb) = zb {
            for j in 0..self.k {
                z[j] += (1.0 - wa) * zb[j];
            }
        }
        Self::normalize(z)
    }

    /// Unit vector of a query from its (unique) stemmed terms.
    pub fn encode_query(&self, terms: &[String]) -> Option<Vec<f32>> {
        let mut a: HashMap<&str, u32> = HashMap::new();
        for t in terms {
            *a.entry(t.as_str()).or_insert(0) += 1;
        }
        let z = self.proj(&Self::lookup(&a, &self.va), &self.idf_a, &self.u16, &self.u32)?;
        Self::normalize(z)
    }
}

//! A session holds one repository open for many calls. The long-lived front ends (the MCP
//! server, the language server, the Python bindings, `watch`) are its adapters: they keep no
//! repository of their own, and say only what their protocol needs to say.
//!
//! What a session does for every call: it waits for the first build of the index, scans the tree
//! at most once per refresh interval, gives each call a cancel flag of its own, keeps a panic
//! inside the call that made it, and has a damaged index built again (`stores.rs`). Reads run
//! side by side, each on a repository of its own (`Repo::another`: a SQLite connection, its
//! statement cache and its segment maps); up to `max_readers` are opened, when calls need them,
//! and kept. Writes (the first build, a watch burst, a save, the scan before a read) take the
//! writer lock the repositories share, so they run one at a time; a read beside a write sees
//! the index as of its last commit, never half of one (SQLite's write-ahead log, one transaction
//! per update, a segment manifest swapped in that transaction).
//!
//! A command line call may use the session `serve` runs, through a socket under the
//! repository's `.scrutate/` (`listen`, `ask`; Unix only). The session is a cache of work there:
//! anything it cannot vouch for makes the command line do the work itself.

use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::time::{Duration, Instant};

use anyhow::Result;

use crate::index::{self, UpdateStats};
use crate::ops::{Answer, Op};
use crate::search::Searcher;
use crate::Repo;

/// How long a call waits for an index another process is building before it gives that answer
/// (well under the 60 s after which Codex gives a call up).
pub const BUILD_WAIT: Duration = Duration::from_secs(20);

/// A call that panicked; the session goes on.
#[derive(Debug)]
pub struct Panicked;

impl std::fmt::Display for Panicked {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("internal failure (a bug: please report it)")
    }
}

impl std::error::Error for Panicked {}

/// When a read looks at every file of the tree first.
#[derive(Clone, Copy, Debug)]
pub struct Every {
    pub seconds: f64,
    /// `seconds` is a floor: no scan sooner, however cheap scans are; without it a scan comes
    /// once ten scans' time has passed, if that is sooner
    pub floor: bool,
}

impl Every {
    /// A refresh interval given (`serve --refresh-interval`), or the default of one second.
    pub fn given(seconds: Option<f64>) -> Every {
        Every { seconds: seconds.unwrap_or(1.0), floor: seconds.is_some() }
    }
}

#[derive(Clone, Copy, PartialEq)]
enum Build {
    /// not asked for: the first call's scan builds the index
    None,
    Building,
    Built,
    /// the first build panicked and no update went through since
    Failed,
}

#[derive(Default)]
struct Pool {
    idle: Vec<Repo>,
    open: usize,
}

#[derive(Default)]
struct Clock {
    last: Option<Instant>,
    cost: f64,
}

pub struct Session {
    root: PathBuf,
    every: Every,
    max_readers: usize,
    /// writes, and the repository the readers are opened from
    seed: Mutex<Repo>,
    writer: Arc<Mutex<()>>,
    pool: Mutex<Pool>,
    freed: Condvar,
    build: Mutex<Build>,
    built: Condvar,
    clock: Mutex<Clock>,
    /// one scan decision at a time: a call that waited for another's scan does not scan again
    scanning: Mutex<()>,
    writing: AtomicUsize,
}

fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {
    m.lock().unwrap_or_else(|p| p.into_inner())
}

fn caught<T>(f: impl FnOnce() -> Result<T>) -> Result<T> {
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)).unwrap_or_else(|_| Err(Panicked.into()))
}

impl Session {
    /// Open (or create) the index of `root`, without updating it.
    pub fn open(root: &Path, every: Every) -> Result<Session> {
        let seed = Repo::open(root)?;
        let max_readers = std::thread::available_parallelism().map_or(4, |n| n.get()).clamp(2, 8);
        Ok(Session {
            root: seed.ix.root.clone(),
            every,
            max_readers,
            writer: seed.writer(),
            seed: Mutex::new(seed),
            pool: Mutex::default(),
            freed: Condvar::new(),
            build: Mutex::new(Build::None),
            built: Condvar::new(),
            clock: Mutex::default(),
            scanning: Mutex::new(()),
            writing: AtomicUsize::new(0),
        })
    }

    /// The canonical root.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Readers opened at most.
    pub fn max_readers(&self) -> usize {
        self.max_readers
    }

    /// Mark the first build as started, before the thread that runs `build` is: a call that
    /// arrives meanwhile waits for it.
    pub fn building(&self) {
        *lock(&self.build) = Build::Building;
    }

    /// The first build: every file, waiting for another writer. A panic in it is an error, and
    /// `build_failed` says so until an update goes through.
    pub fn build(&self) -> Result<UpdateStats> {
        self.build_with(|repo| repo.update(false))
    }

    #[cfg(test)]
    pub(crate) fn build_failing_for_test(&self) {
        let _ = self.build_with(|_| panic!("a first build that panics"));
    }

    fn build_with(&self, f: impl FnOnce(&mut Repo) -> Result<UpdateStats>) -> Result<UpdateStats> {
        self.building();
        let r = self.write(f);
        let state = if r.as_ref().is_err_and(|e| e.is::<Panicked>()) { Build::Failed } else { Build::Built };
        *lock(&self.build) = state;
        self.built.notify_all();
        r
    }

    /// Whether the first build is running.
    pub fn is_building(&self) -> bool {
        *lock(&self.build) == Build::Building
    }

    /// Whether the first build panicked and no update went through since.
    pub fn build_failed(&self) -> bool {
        *lock(&self.build) == Build::Failed
    }

    /// Wait while the first build runs, at most `limit`, until `cancel` is set; `tick` runs
    /// every 20 ms with the time waited. -> whether the build is over.
    pub fn wait_built(&self, cancel: &AtomicBool, limit: Option<Duration>, mut tick: impl FnMut(Duration)) -> bool {
        let started = Instant::now();
        let mut state = lock(&self.build);
        while *state == Build::Building {
            if cancel.load(Ordering::Relaxed) || limit.is_some_and(|l| started.elapsed() >= l) {
                return false;
            }
            state = self.built.wait_timeout(state, Duration::from_millis(20)).unwrap_or_else(|p| p.into_inner()).0;
            tick(started.elapsed());
        }
        true
    }

    /// Run `f` on the repository writes use, with its panic kept inside this call.
    pub fn write<T>(&self, f: impl FnOnce(&mut Repo) -> Result<T>) -> Result<T> {
        self.writing.fetch_add(1, Ordering::AcqRel);
        let mut seed = lock(&self.seed);
        let r = caught(|| f(&mut seed));
        let updated = seed.take_updated();
        drop(seed);
        self.writing.fetch_sub(1, Ordering::AcqRel);
        self.note_update(updated);
        r
    }

    /// Run one operation on an index scanned at most once per refresh interval (one that does
    /// not read the index is not scanned for), waiting up to `BUILD_WAIT` for another process's
    /// first build. A panic is the error `Panicked`.
    pub fn run(&self, op: &Op, cancel: &Arc<AtomicBool>) -> Result<Answer> {
        self.waiting_for_others(cancel, || {
            self.call(cancel, None, |repo| {
                if op.reads_index() {
                    self.scan_if_due(repo)?;
                }
                repo.run_as_is(op)
            })
        })
    }

    /// Run `f` on the searcher, as `run` runs an operation: with `refresh` the index is scanned
    /// as for an operation; a damaged index is built again and `f` run once more.
    pub fn read<T>(&self, cancel: &Arc<AtomicBool>, refresh: bool, mut f: impl FnMut(&mut Searcher) -> Result<T>) -> Result<T> {
        self.waiting_for_others(cancel, || {
            self.call(cancel, None, |repo| {
                if refresh {
                    self.scan_if_due(repo)?;
                }
                repo.recovering(&mut f)
            })
        })
    }

    /// A command line call: every file is looked at first, as a fresh process does, then `op`
    /// runs. None when the session cannot answer now without waiting (a write running, every
    /// reader busy, another process holding the write lock) or a panic: the caller does the work.
    pub fn run_scanned(&self, op: &Op) -> Option<(UpdateStats, Result<Answer>)> {
        const WAIT: Duration = Duration::from_millis(50);
        if self.writing.load(Ordering::Acquire) > 0 || self.is_building() {
            return None;
        }
        let cancel = Arc::default();
        let r = self.call(&cancel, Some(WAIT), |repo| {
            let mut st = UpdateStats::default();
            if op.reads_index() {
                let t0 = Instant::now();
                let scanning = loop {
                    match self.scanning.try_lock() {
                        Ok(g) => break g,
                        Err(std::sync::TryLockError::Poisoned(p)) => break p.into_inner(),
                        Err(_) if t0.elapsed() < WAIT => std::thread::sleep(Duration::from_micros(500)),
                        Err(_) => return Ok(None),
                    }
                };
                let t = Instant::now();
                st = repo.refresh(0.0)?.unwrap_or_default();
                if repo.is_stale() {
                    return Ok(None);
                }
                self.scanned(t, true);
                drop(scanning);
            }
            Ok(Some((st, repo.run_as_is(op))))
        });
        r.ok().flatten()
    }

    /// Call `f` again while it meets another process's first build, up to `BUILD_WAIT`.
    fn waiting_for_others<T>(&self, cancel: &AtomicBool, mut f: impl FnMut() -> Result<T>) -> Result<T> {
        let started = Instant::now();
        loop {
            match f() {
                Err(e) if e.is::<index::BeingBuilt>() && started.elapsed() < BUILD_WAIT && !cancel.load(Ordering::Relaxed) => {
                    std::thread::sleep(Duration::from_millis(200))
                }
                r => return r,
            }
        }
    }

    /// Run `f` on a reader of its own with `cancel` as its cancel flag. A reader whose call
    /// panicked is closed, not used again. `wait`: how long to wait for a reader when all are
    /// busy (None: as long as it takes, unless `cancel` is set).
    fn call<T>(&self, cancel: &Arc<AtomicBool>, wait: Option<Duration>, f: impl FnOnce(&mut Repo) -> Result<T>) -> Result<T> {
        let Some(mut repo) = self.reader(cancel, wait)? else { return Err(anyhow::anyhow!("every reader is busy")) };
        repo.set_cancel(Arc::clone(cancel));
        match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| f(&mut repo))) {
            Ok(r) => {
                repo.set_cancel(Arc::default());
                let updated = repo.take_updated();
                self.give_back(Some(repo));
                self.note_update(updated);
                r
            }
            Err(_) => {
                drop(repo);
                self.give_back(None);
                Err(Panicked.into())
            }
        }
    }

    fn reader(&self, cancel: &AtomicBool, wait: Option<Duration>) -> Result<Option<Repo>> {
        let started = Instant::now();
        let mut pool = lock(&self.pool);
        loop {
            if let Some(repo) = pool.idle.pop() {
                return Ok(Some(repo));
            }
            if pool.open < self.max_readers {
                pool.open += 1;
                drop(pool);
                let opened = caught(|| lock(&self.seed).another());
                if opened.is_err() {
                    self.give_back(None);
                }
                return opened.map(Some);
            }
            if cancel.load(Ordering::Relaxed) || wait.is_some_and(|w| started.elapsed() >= w) {
                return Ok(None);
            }
            pool = self.freed.wait_timeout(pool, Duration::from_millis(20)).unwrap_or_else(|p| p.into_inner()).0;
        }
    }

    /// A reader back to the pool, or None for one that was closed.
    fn give_back(&self, repo: Option<Repo>) {
        let mut pool = lock(&self.pool);
        match repo {
            Some(r) => pool.idle.push(r),
            None => pool.open -= 1,
        }
        drop(pool);
        self.freed.notify_one();
    }

    fn note_update(&self, updated: bool) {
        if updated {
            let mut b = lock(&self.build);
            if *b == Build::Failed {
                *b = Build::Built;
            }
        }
    }

    /// The scan before a read, when the refresh interval has passed since the last one.
    fn scan_if_due(&self, repo: &mut Repo) -> Result<()> {
        if !self.due() {
            return Ok(());
        }
        let _scanning = lock(&self.scanning);
        if !self.due() {
            return Ok(());
        }
        let t = Instant::now();
        let r = repo.refresh(0.0);
        // a scan that could not run does not start a floor's interval: the next call tries again
        self.scanned(t, r.is_ok() && !repo.is_stale() || !self.every.floor);
        r.map(|_| ())
    }

    fn due(&self) -> bool {
        let c = lock(&self.clock);
        let wait = if self.every.floor { self.every.seconds } else { self.every.seconds.min(10.0 * c.cost) };
        c.last.is_none_or(|t| t.elapsed().as_secs_f64() >= wait)
    }

    fn scanned(&self, started: Instant, starts_interval: bool) {
        let mut c = lock(&self.clock);
        c.cost = started.elapsed().as_secs_f64();
        if starts_interval {
            c.last = Some(Instant::now());
        }
    }

    /// No write starts after this, until the process exits: the first build is waited for, then
    /// the writer lock is taken and kept, so an exit cuts no transaction.
    pub fn hold_writes(&self) {
        self.wait_built(&AtomicBool::new(false), None, |_| {});
        std::mem::forget(lock(&self.writer));
    }
}

/// Whether the command line may use a running session (`SCRUTATE_NO_SESSION` turns it off).
pub fn wanted() -> bool {
    std::env::var_os("SCRUTATE_NO_SESSION").is_none_or(|v| v.is_empty() || v == "0")
}

#[cfg(unix)]
fn debug(what: &str) {
    if std::env::var_os("SCRUTATE_SESSION_DEBUG").is_some_and(|v| !v.is_empty() && v != "0") {
        eprintln!("[scrutate] session: {what}");
    }
}

/// What a command line call asks a session: its operation and how to print the answer.
#[derive(serde::Serialize, serde::Deserialize)]
pub struct Request {
    pub op: Op,
    pub json: bool,
    pub max_bytes: usize,
    pub offset: usize,
    pub outside: Option<String>,
    /// a ranked search's `--why`
    pub why: bool,
}

/// The printed answer: standard output, standard error and the exit code, as the command line
/// prints them; `scan` is what the scan before it updated.
#[derive(serde::Serialize, serde::Deserialize, Clone, Debug, Default, PartialEq)]
pub struct Printed {
    pub out: String,
    pub err: String,
    pub code: i32,
}

#[cfg(unix)]
#[derive(serde::Serialize, serde::Deserialize, Debug)]
struct Reply {
    printed: Option<Printed>,
    changed: usize,
    removed: usize,
    chunks: i64,
    seconds: f64,
}

#[cfg(unix)]
/// Everything an answer depends on besides the files and the request: a session answers only a
/// command line whose identity is the same.
#[derive(serde::Serialize, serde::Deserialize, Debug, PartialEq)]
struct Identity {
    version: String,
    /// the executable file: device, inode, size, modification time
    build: String,
    schema: u32,
    content: u32,
    models: String,
    env: Vec<(String, String)>,
    root: String,
}

#[cfg(unix)]
/// Variables that do not change an answer through a session: the root is compared on its own, the
/// size of an answer travels with each request, and these switches are the command line's own.
const NOT_ANSWERS: &[&str] =
    &["SCRUTATE_ROOT", "SCRUTATE_NO_SESSION", "SCRUTATE_SESSION_DEBUG", "SCRUTATE_SESSION_WAIT_MS", "SCRUTATE_MAX_BYTES", "SCRUTATE_REFRESH_INTERVAL"];

#[cfg(unix)]
impl Identity {
    fn here(root: &Path) -> Option<Identity> {
        let file_id = |p: &Path| -> Option<String> {
            let m = std::fs::metadata(p).ok()?;
            let s = index::Stat::of(&m);
            use std::os::unix::fs::MetadataExt;
            let (dev, ino) = (m.dev(), m.ino());
            Some(format!("{dev} {ino} {} {} {}", s.size, s.mtime, s.ctime))
        };
        let models = crate::models::ModelSet::from_env().signature(&root.join(crate::files::INDEX_DIR)).ok()?;
        let ranker = match std::env::var_os("SCRUTATE_RANKER") {
            Some(p) if !p.is_empty() && p != "none" => file_id(Path::new(&p))?,
            _ => String::new(),
        };
        let mut env: Vec<(String, String)> = std::env::vars_os()
            .filter_map(|(k, v)| Some((k.into_string().ok()?, v.to_string_lossy().into_owned())))
            .filter(|(k, _)| k.starts_with("SCRUTATE_") && !NOT_ANSWERS.contains(&k.as_str()))
            .collect();
        env.sort();
        Some(Identity {
            version: crate::VERSION.to_string(),
            build: file_id(&std::env::current_exe().ok()?)?,
            schema: index::SCHEMA_VERSION,
            content: index::CONTENT_REVISION,
            models: format!("{models} {ranker}"),
            env,
            root: root.to_string_lossy().into_owned(),
        })
    }
}

/// The socket of a session of `root` (canonical).
pub fn socket_path(root: &Path) -> PathBuf {
    root.join(crate::files::INDEX_DIR).join("session.sock")
}

#[cfg(unix)]
pub use unix::{ask, listen, Listening};

/// No session use on Windows: a command line call does the work itself.
#[cfg(not(unix))]
pub fn ask(_root: &Path, _request: &Request) -> Result<Option<(Printed, UpdateStats)>> {
    Ok(None)
}

#[cfg(not(unix))]
pub struct Listening;

#[cfg(not(unix))]
pub fn listen(_session: &Arc<Session>, _answer: fn(Answer, &Request) -> Result<Printed>) -> Option<Listening> {
    None
}

#[cfg(unix)]
mod unix {
    use super::*;
    use std::io::{BufRead, BufReader, Write};
    use std::os::unix::fs::{FileTypeExt, MetadataExt, PermissionsExt};
    use std::os::unix::io::AsRawFd;
    use std::os::unix::net::{UnixListener, UnixStream};

    /// How long the command line waits for a session's greeting.
    const HELLO: Duration = Duration::from_millis(20);

    /// `HELLO`, or `SCRUTATE_SESSION_WAIT_MS` for a machine too busy to greet that fast.
    fn hello() -> Duration {
        std::env::var("SCRUTATE_SESSION_WAIT_MS").ok().and_then(|v| v.parse().ok()).map_or(HELLO, Duration::from_millis)
    }
    /// How long the command line waits for an answer before it does the work itself.
    const ANSWER: Duration = Duration::from_secs(60);
    /// How long a session waits for a request after its greeting.
    const REQUEST: Duration = Duration::from_secs(2);
    const MAX_REQUEST: u64 = 1 << 20;
    /// Connections served at once; one more is closed, and its command line does the work.
    const MAX_CONNECTIONS: usize = 16;

    extern "C" {
        fn geteuid() -> u32;
        fn fchdir(fd: i32) -> i32;
        #[cfg(not(any(target_os = "linux", target_os = "android")))]
        fn getpeereid(fd: i32, uid: *mut u32, gid: *mut u32) -> i32;
        #[cfg(any(target_os = "linux", target_os = "android"))]
        fn getsockopt(fd: i32, level: i32, name: i32, value: *mut std::ffi::c_void, len: *mut u32) -> i32;
    }

    /// The user at the other end of a connected socket, as the system knows it.
    fn peer_uid(s: &UnixStream) -> Option<u32> {
        let fd = s.as_raw_fd();
        #[cfg(not(any(target_os = "linux", target_os = "android")))]
        {
            let (mut uid, mut gid) = (u32::MAX, u32::MAX);
            (unsafe { getpeereid(fd, &mut uid, &mut gid) } == 0).then_some(uid)
        }
        #[cfg(any(target_os = "linux", target_os = "android"))]
        {
            // struct ucred { pid_t pid; uid_t uid; gid_t gid; }; SOL_SOCKET 1, SO_PEERCRED 17
            let mut cred = [0u32; 3];
            let mut len = std::mem::size_of_val(&cred) as u32;
            (unsafe { getsockopt(fd, 1, 17, cred.as_mut_ptr().cast(), &mut len) } == 0 && len as usize == std::mem::size_of_val(&cred)).then_some(cred[1])
        }
    }

    /// The process could not go back to the working directory `short` left.
    #[derive(Debug)]
    pub(super) struct NotBack(std::io::Error);

    impl std::fmt::Display for NotBack {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "cannot go back to the working directory after reaching the session socket: {}", self.0)
        }
    }

    impl std::error::Error for NotBack {}

    fn not_back(e: &std::io::Error) -> bool {
        e.get_ref().is_some_and(|i| i.is::<NotBack>())
    }

    /// `f` of the socket at `path`. A path too long for a socket address (103 bytes on macOS, 107
    /// on Linux) is named from its directory, which this process enters for the call and leaves
    /// through a descriptor of the directory it was in, so a renamed or unreachable path does not
    /// matter: so only while it runs no other thread (a command line call, a server before it
    /// starts any). An error that holds `NotBack`: the process is still in the socket's directory.
    pub(super) fn short<T>(path: &Path, f: impl FnOnce(&Path) -> std::io::Result<T>) -> std::io::Result<T> {
        const ROOM: usize = if cfg!(any(target_os = "linux", target_os = "android")) { 107 } else { 103 };
        if path.as_os_str().len() <= ROOM {
            return f(path);
        }
        let (Some(dir), Some(name)) = (path.parent(), path.file_name()) else { return f(path) };
        let here = std::fs::File::open(".")?;
        std::env::set_current_dir(dir)?;
        let r = f(Path::new(name));
        if unsafe { fchdir(here.as_raw_fd()) } != 0 {
            return Err(std::io::Error::other(NotBack(std::io::Error::last_os_error())));
        }
        r
    }

    fn same_user(s: &UnixStream) -> bool {
        peer_uid(s) == Some(unsafe { geteuid() })
    }

    /// A socket file this user owns, not a link and not reached through one in `.scrutate`.
    fn ours(path: &Path) -> bool {
        let me = unsafe { geteuid() };
        let dir = path.parent().and_then(|d| std::fs::symlink_metadata(d).ok());
        let sock = std::fs::symlink_metadata(path).ok();
        dir.is_some_and(|d| d.is_dir() && d.uid() == me) && sock.is_some_and(|s| s.file_type().is_socket() && s.uid() == me)
    }

    /// The session's end: the socket file is removed when this is dropped, if it is still the one
    /// this session made.
    pub struct Listening {
        path: PathBuf,
        id: (u64, u64),
    }

    impl Drop for Listening {
        fn drop(&mut self) {
            if std::fs::symlink_metadata(&self.path).is_ok_and(|m| (m.dev(), m.ino()) == self.id) {
                let _ = std::fs::remove_file(&self.path);
            }
        }
    }

    /// Offer `session` to command line calls of the same user, until the process exits. None when
    /// it cannot (the socket path is too long, another session of this root is running, the
    /// index directory holds something else there): command line calls then do their own work.
    /// `answer` prints an answer as the command line does.
    pub fn listen(session: &Arc<Session>, answer: fn(Answer, &Request) -> Result<Printed>) -> Option<Listening> {
        let path = socket_path(session.root());
        let Some(me) = Identity::here(session.root()) else {
            debug("no identity to offer");
            return None;
        };
        if std::fs::symlink_metadata(&path).is_ok() {
            if !ours(&path) {
                debug(&format!("{} is not a socket of this user; not listening", path.display()));
                return None;
            }
            match short(&path, |p| UnixStream::connect(p)) {
                Ok(_) => {
                    debug("another session of this root is listening");
                    return None;
                }
                Err(e) if not_back(&e) => {
                    debug(&e.to_string());
                    return None;
                }
                Err(_) => {}
            }
            let _ = std::fs::remove_file(&path); // left by a session that ended without removing it
        }
        let listener = match short(&path, |p| UnixListener::bind(p)) {
            Ok(l) => l,
            Err(e) => {
                if not_back(&e) {
                    // bound, maybe, but a server in the wrong directory offers nothing
                    let _ = std::fs::remove_file(&path);
                }
                debug(&format!("cannot listen at {}: {e}", path.display()));
                return None;
            }
        };
        let md = std::fs::symlink_metadata(&path).ok()?;
        let _ = std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600));
        let hello = serde_json::to_string(&me).ok()?;
        let session = Arc::clone(session);
        let open = Arc::new(AtomicUsize::new(0));
        std::thread::Builder::new()
            .name("scrutate-session".into())
            .spawn(move || {
                for conn in listener.incoming() {
                    let Ok(conn) = conn else { continue };
                    // another user's process gets nothing, not even the greeting
                    if !same_user(&conn) || open.load(Ordering::Acquire) >= MAX_CONNECTIONS {
                        continue;
                    }
                    open.fetch_add(1, Ordering::AcqRel);
                    let (session, hello, done) = (Arc::clone(&session), hello.clone(), Arc::clone(&open));
                    let served = std::thread::Builder::new().name("scrutate-session-call".into()).spawn(move || {
                        let _ = serve_one(&session, conn, &hello, answer);
                        done.fetch_sub(1, Ordering::AcqRel);
                    });
                    if served.is_err() {
                        open.fetch_sub(1, Ordering::AcqRel);
                    }
                }
            })
            .ok()?;
        Some(Listening { path, id: (md.dev(), md.ino()) })
    }

    fn serve_one(session: &Session, conn: UnixStream, hello: &str, answer: fn(Answer, &Request) -> Result<Printed>) -> Result<()> {
        let mut w = conn.try_clone()?;
        writeln!(w, "{hello}")?;
        conn.set_read_timeout(Some(REQUEST))?;
        let mut line = Vec::new();
        BufReader::new(std::io::Read::take(&conn, MAX_REQUEST)).read_until(b'\n', &mut line)?;
        let request: Request = serde_json::from_slice(&line)?;
        let printed = session.run_scanned(&request.op).and_then(|(st, a)| Some((st, answer(a.ok()?, &request).ok()?)));
        let reply = match printed {
            Some((st, p)) => Reply { printed: Some(p), changed: st.files_changed, removed: st.files_removed, chunks: st.chunks, seconds: st.seconds },
            None => Reply { printed: None, changed: 0, removed: 0, chunks: 0, seconds: 0.0 },
        };
        writeln!(w, "{}", serde_json::to_string(&reply)?)?;
        Ok(())
    }

    /// The answer of the session running on `root` (canonical) to `request`, printed as the
    /// command line prints it, with what the scan before it updated. None, quietly, when there is
    /// no session or anything about it is not as this process would do the work. An error only
    /// when this process could not go back to its working directory: it must stop.
    pub fn ask(root: &Path, request: &Request) -> Result<Option<(Printed, UpdateStats)>> {
        let path = socket_path(root);
        if std::fs::symlink_metadata(&path).is_err() {
            return Ok(None);
        }
        let mut lost = None;
        let r = asked(&path, root, request, &mut lost);
        if let Some(e) = lost {
            return Err(e.into());
        }
        if let Err(why) = &r {
            debug(why);
        }
        Ok(r.ok())
    }

    fn asked(path: &Path, root: &Path, request: &Request, lost: &mut Option<std::io::Error>) -> std::result::Result<(Printed, UpdateStats), String> {
        if !ours(path) {
            return Err(format!("{} is not a socket of this user", path.display()));
        }
        let conn = short(path, |p| UnixStream::connect(p)).map_err(|e| {
            let why = format!("no session at {}: {e}", path.display());
            if not_back(&e) {
                *lost = Some(e);
            }
            why
        })?;
        if !same_user(&conn) {
            return Err("the session runs as another user".into());
        }
        conn.set_read_timeout(Some(hello())).map_err(|e| e.to_string())?;
        let mut r = BufReader::new(&conn);
        let mut line = String::new();
        r.read_line(&mut line).map_err(|e| format!("no greeting: {e}"))?;
        let theirs: Identity = serde_json::from_str(&line).map_err(|e| format!("greeting: {e}"))?;
        let me = Identity::here(root).ok_or("no identity here")?;
        if theirs != me {
            return Err(format!("the session differs: {theirs:?} where this is {me:?}"));
        }
        let mut w = &conn;
        writeln!(w, "{}", serde_json::to_string(request).map_err(|e| e.to_string())?).map_err(|e| e.to_string())?;
        conn.set_read_timeout(Some(ANSWER)).map_err(|e| e.to_string())?;
        line.clear();
        r.read_line(&mut line).map_err(|e| format!("no answer: {e}"))?;
        let reply: Reply = serde_json::from_str(&line).map_err(|e| format!("answer: {e}"))?;
        let printed = reply.printed.ok_or("the session did not answer this call")?;
        debug("answered by the session");
        let st = UpdateStats { files_changed: reply.changed, files_removed: reply.removed, chunks: reply.chunks, seconds: reply.seconds, ..Default::default() };
        Ok((printed, st))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A repository of one function, its session, and its first build done.
    fn fixture(name: &str) -> (PathBuf, Session) {
        let root = std::env::temp_dir().join(format!("scrutate_session_{name}_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(root.join("src/geo.py"), "def make_point():\n    return 1\n").unwrap();
        let s = Session::open(&root, Every::given(Some(3600.0))).unwrap();
        s.build().unwrap();
        (root, s)
    }

    /// Run `f` in `n` calls at once; each waits until all `n` are inside, or ten seconds.
    /// -> how many were inside together at most, and each call's result.
    fn together<T: Send>(s: &Session, n: usize, f: impl Fn(usize, &mut Searcher) -> Result<T> + Sync) -> (usize, Vec<Result<T>>) {
        let inside = AtomicUsize::new(0);
        let most = AtomicUsize::new(0);
        let out = std::thread::scope(|sc| {
            let calls: Vec<_> = (0..n)
                .map(|i| {
                    let (inside, most, f) = (&inside, &most, &f);
                    sc.spawn(move || {
                        s.read(&Arc::default(), false, |searcher| {
                            let now = inside.fetch_add(1, Ordering::SeqCst) + 1;
                            most.fetch_max(now, Ordering::SeqCst);
                            let t0 = Instant::now();
                            while most.load(Ordering::SeqCst) < n.min(s.max_readers()) && t0.elapsed() < Duration::from_secs(10) {
                                std::thread::sleep(Duration::from_millis(1));
                            }
                            let r = f(i, searcher);
                            inside.fetch_sub(1, Ordering::SeqCst);
                            r
                        })
                    })
                })
                .collect();
            calls.into_iter().map(|c| c.join().unwrap()).collect()
        });
        (most.into_inner(), out)
    }

    #[test]
    fn reads_run_side_by_side_each_on_a_reader_of_its_own() {
        let (root, s) = fixture("side_by_side");
        let n = s.max_readers().min(4);
        let (most, out) = together(&s, n, |_, searcher| searcher.find_symbol("make_point", 5).map(|h| h.len()));
        assert_eq!(most, n, "the reads waited for one another");
        assert!(out.iter().all(|r| matches!(r, Ok(1))), "{out:?}");
        // more calls than readers wait for a reader and are all answered
        let (most, out) = together(&s, s.max_readers() + 2, |_, searcher| searcher.find_symbol("make_point", 5).map(|h| h.len()));
        assert_eq!(most, s.max_readers());
        assert!(out.iter().all(|r| matches!(r, Ok(1))));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn a_panic_inside_one_call_is_that_calls_error_and_the_session_goes_on() {
        let (root, s) = fixture("panic");
        let (_, out) = together(&s, 2, |i, searcher| {
            if i == 0 {
                panic!("a call that panics");
            }
            searcher.find_symbol("make_point", 5).map(|h| h.len())
        });
        assert!(out[0].as_ref().is_err_and(|e| e.is::<Panicked>()));
        assert!(matches!(out[1], Ok(1)));
        let op = Op::Symbol { name: "make_point".into(), limit: 5 };
        for _ in 0..3 {
            assert!(matches!(s.run(&op, &Arc::default()), Ok(Answer::Hits { ref hits, .. }) if hits.len() == 1));
        }
        assert!(s.write(|_| -> Result<()> { panic!("a write that panics") }).is_err_and(|e| e.is::<Panicked>()));
        assert!(s.write(|repo| repo.update(false)).is_ok(), "the writer goes on too");
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn a_cancel_stops_its_own_call_and_no_other() {
        let (root, s) = fixture("cancel");
        let flags: Vec<Arc<AtomicBool>> = (0..3).map(|i| Arc::new(AtomicBool::new(i == 1))).collect();
        let seen = std::thread::scope(|sc| {
            let calls: Vec<_> = flags.iter().map(|f| sc.spawn(|| s.read(f, false, |searcher| Ok(searcher.cancel.load(Ordering::Relaxed))).unwrap())).collect();
            calls.into_iter().map(|c| c.join().unwrap()).collect::<Vec<_>>()
        });
        assert_eq!(seen, [false, true, false]);
        // a cancelled reindex stops and leaves the index as it was
        let reindex = s.run(&Op::Reindex { force: true }, &Arc::new(AtomicBool::new(true)));
        assert!(reindex.is_err_and(|e| format!("{e:#}").contains("cancelled")));
        let op = Op::Symbol { name: "make_point".into(), limit: 5 };
        assert!(matches!(s.run(&op, &Arc::default()), Ok(Answer::Hits { ref hits, .. }) if hits.len() == 1));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn a_write_runs_beside_reads_and_a_read_sees_the_index_before_it_or_after_it() {
        let (root, s) = fixture("write");
        let reading = AtomicBool::new(false);
        let written = AtomicBool::new(false);
        std::thread::scope(|sc| {
            let read = sc.spawn(|| {
                s.read(&Arc::default(), false, |searcher| {
                    let before = searcher.find_symbol("added_later", 5)?.len();
                    reading.store(true, Ordering::SeqCst);
                    let t0 = Instant::now();
                    while !written.load(Ordering::SeqCst) && t0.elapsed() < Duration::from_secs(20) {
                        std::thread::sleep(Duration::from_millis(5));
                    }
                    Ok((before, searcher.find_symbol("added_later", 5)?.len()))
                })
            });
            while !reading.load(Ordering::SeqCst) {
                std::thread::sleep(Duration::from_millis(1));
            }
            std::fs::write(root.join("src/later.py"), "def added_later():\n    return 2\n").unwrap();
            let st = s.write(|repo| repo.update(false)).unwrap();
            assert_eq!(st.files_changed, 1, "the write did not wait for the read");
            written.store(true, Ordering::SeqCst);
            assert_eq!(read.join().unwrap().unwrap(), (0, 1));
        });
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn a_call_waits_for_the_first_build_and_a_limit_ends_the_wait() {
        let root = std::env::temp_dir().join(format!("scrutate_session_first_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).unwrap();
        std::fs::write(root.join("a.py"), "def first():\n    return 1\n").unwrap();
        let s = Session::open(&root, Every::given(None)).unwrap();
        let never = AtomicBool::new(false);
        assert!(s.wait_built(&never, Some(Duration::ZERO), |_| {}), "no build asked for: nothing to wait for");
        s.building();
        assert!(!s.wait_built(&never, Some(Duration::from_millis(50)), |_| {}), "the limit ends the wait");
        assert!(!s.wait_built(&AtomicBool::new(true), None, |_| {}), "a cancel ends the wait");
        assert!(s.run_scanned(&Op::Symbol { name: "first".into(), limit: 5 }).is_none(), "a command line call does not wait");
        std::thread::scope(|sc| {
            let waiter = sc.spawn(|| s.wait_built(&never, None, |_| {}));
            std::thread::sleep(Duration::from_millis(100));
            assert!(!waiter.is_finished());
            s.build().unwrap();
            assert!(waiter.join().unwrap());
        });
        assert!(s.run_scanned(&Op::Symbol { name: "first".into(), limit: 5 }).is_some_and(|(_, a)| a.is_ok_and(|a| !a.is_empty())));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn a_call_waits_for_another_process_that_builds_the_first_index() {
        let root = std::env::temp_dir().join(format!("scrutate_session_other_build_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(root.join("src/geo.py"), "def make_point():\n    return 1\n").unwrap();
        let s = Session::open(&root, Every::given(Some(3600.0))).unwrap();
        // what another process holds while it builds the first index
        let other = rusqlite::Connection::open(root.join(crate::files::INDEX_DIR).join("index.db")).unwrap();
        other.execute_batch("BEGIN IMMEDIATE").unwrap();
        let release = std::thread::spawn(move || {
            std::thread::sleep(Duration::from_millis(600));
            other.execute_batch("ROLLBACK").unwrap();
        });
        let op = Op::Symbol { name: "make_point".into(), limit: 5 };
        assert!(s.run_scanned(&op).is_none(), "a command line call does not wait: it does the work itself");
        let a = s.run(&op, &Arc::default());
        release.join().unwrap();
        assert!(matches!(a, Ok(Answer::Hits { ref hits, .. }) if hits.len() == 1), "{:?}", a.err());
        let _ = std::fs::remove_dir_all(&root);
    }

    #[cfg(unix)]
    #[test]
    fn a_long_socket_path_comes_back_to_the_callers_directory_even_after_it_was_renamed() {
        const NAME: &str = "session::tests::a_long_socket_path_comes_back_to_the_callers_directory_even_after_it_was_renamed";
        // the working directory belongs to the whole process, so this runs alone in one of its own
        if std::env::var_os("SCRUTATE_TEST_SHORT").is_none() {
            let out = std::process::Command::new(std::env::current_exe().unwrap())
                .args(["--exact", NAME, "--test-threads=1"])
                .env("SCRUTATE_TEST_SHORT", "1")
                .output()
                .unwrap();
            let said = String::from_utf8_lossy(&out.stdout);
            assert!(out.status.success() && said.contains("1 passed"), "{said}{}", String::from_utf8_lossy(&out.stderr));
            return;
        }
        let base = std::env::temp_dir().join(format!("scrutate_session_short_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&base);
        let (caller, moved, deep) = (base.join("caller"), base.join("moved"), base.join("d".repeat(60)).join("e".repeat(60)));
        std::fs::create_dir_all(&caller).unwrap();
        std::fs::create_dir_all(&deep).unwrap();
        let (base, deep) = (base.canonicalize().unwrap(), deep.canonicalize().unwrap());
        std::env::set_current_dir(&caller).unwrap();
        let sock = deep.join("session.sock");
        assert!(sock.as_os_str().len() > 110);
        let r = unix::short(&sock, |p| {
            assert_eq!(p, Path::new("session.sock"));
            assert_eq!(std::env::current_dir()?.canonicalize()?, deep);
            // the path the caller's directory had is gone by the time the call comes back
            std::fs::rename(base.join("caller"), base.join("moved"))
        });
        assert!(r.is_ok(), "{r:?}");
        assert_eq!(std::env::current_dir().unwrap().canonicalize().unwrap(), moved.canonicalize().unwrap());
        std::env::set_current_dir(std::env::temp_dir()).unwrap();
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn a_command_line_call_scans_every_file_first() {
        let (root, s) = fixture("scanned");
        let op = Op::Symbol { name: "brand_new".into(), limit: 5 };
        assert!(s.run(&op, &Arc::default()).is_ok_and(|a| a.is_empty()));
        std::fs::write(root.join("src/new.py"), "def brand_new():\n    return 3\n").unwrap();
        assert!(s.run(&op, &Arc::default()).is_ok_and(|a| a.is_empty()), "inside the interval a call reads the index as it is");
        let (st, a) = s.run_scanned(&op).unwrap();
        assert_eq!(st.files_changed, 1);
        assert!(a.is_ok_and(|a| !a.is_empty()));
        let _ = std::fs::remove_dir_all(root);
    }
}

//! `scrutate setup <agent>`: one MCP server entry that runs this binary, written into an agent's
//! configuration (and, when asked, the Grep hook and a block of instructions), edited in place so
//! that every other byte of the file stays and `--uninstall` takes back exactly what was added.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use anyhow::{anyhow, bail, Context, Result};
use serde_json::Value;

/// The agents `setup` knows.
#[derive(Clone, Copy, Debug, PartialEq, Eq, clap::ValueEnum)]
pub enum Agent {
    Claude,
    Codex,
    Opencode,
    Cursor,
    Gemini,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct Options {
    /// the agent's file in the repository of the current directory, not the user's
    pub project: bool,
    pub uninstall: bool,
    pub dry_run: bool,
    /// also the Grep hook (Claude Code only); `uninstall` takes it out whether asked or not
    pub hook: bool,
    /// also a block in the agent's instruction file; `uninstall` takes it out whether asked or not
    pub instructions: bool,
}

/// The name of the server entry and of the markers around the instruction block.
pub const NAME: &str = "scrutate";
const BEGIN: &str = "<!-- scrutate:begin -->";
const END: &str = "<!-- scrutate:end -->";
const HOOK_TIMEOUT_S: u64 = 10;

/// Runs `setup` and prints what it did (or, with `dry_run`, what it would do). Nothing is written
/// unless every file it would change parses.
pub fn run(agent: Agent, o: Options) -> Result<i32> {
    let env = Env::from_process()?;
    let steps = plan(agent, o, &env)?;
    let mut out = String::new();
    for s in &steps {
        if o.dry_run {
            s.preview(&mut out);
        } else {
            s.apply(&mut out)?;
        }
    }
    print!("{out}");
    Ok(0)
}

/// Where the agents keep their files, and what the entry runs.
struct Env {
    home: PathBuf,
    claude_dir: PathBuf,
    claude_json: PathBuf,
    codex_home: PathBuf,
    config_home: PathBuf,
    /// the top of the repository the current directory is in (the directory with `.git`), else it
    top: PathBuf,
    bin: String,
    claude: Option<PathBuf>,
}

impl Env {
    fn from_process() -> Result<Env> {
        let var = |k: &str| std::env::var_os(k).filter(|v| !v.is_empty()).map(PathBuf::from);
        let home = var(if cfg!(windows) { "USERPROFILE" } else { "HOME" }).context("no home directory: set HOME")?;
        let claude_config = var("CLAUDE_CONFIG_DIR");
        let cwd = std::env::current_dir().context("no current directory")?;
        let top = cwd.ancestors().find(|d| d.join(".git").exists()).unwrap_or(&cwd).to_path_buf();
        let exe = std::env::current_exe().context("cannot find this program's path")?;
        let exe = std::fs::canonicalize(&exe).unwrap_or(exe);
        let bin = exe.to_str().context("this program's path is not UTF-8")?.trim_start_matches(r"\\?\").to_string();
        Ok(Env {
            claude_dir: claude_config.clone().unwrap_or_else(|| home.join(".claude")),
            claude_json: claude_config.map_or_else(|| home.join(".claude.json"), |d| d.join(".claude.json")),
            codex_home: var("CODEX_HOME").unwrap_or_else(|| home.join(".codex")),
            config_home: var("XDG_CONFIG_HOME").filter(|p| p.is_absolute()).unwrap_or_else(|| home.join(".config")),
            top: std::fs::canonicalize(&top).map(|p| PathBuf::from(p.to_string_lossy().trim_start_matches(r"\\?\"))).unwrap_or(top),
            claude: on_path("claude"),
            home,
            bin,
        })
    }
}

/// The first `name` on `PATH` that is a file.
fn on_path(name: &str) -> Option<PathBuf> {
    let names: Vec<String> = if cfg!(windows) { ["exe", "cmd", "bat"].iter().map(|e| format!("{name}.{e}")).collect() } else { vec![name.to_string()] };
    std::env::split_paths(&std::env::var_os("PATH")?).flat_map(|d| names.iter().map(move |n| d.join(n)).collect::<Vec<_>>()).find(|p| p.is_file())
}

/// One thing `setup` does.
enum Step {
    /// `path` goes from `before` to `after` (`None`: no file)
    File {
        path: PathBuf,
        before: Option<String>,
        after: Option<String>,
        what: String,
    },
    /// the agent's own command
    Run {
        argv: Vec<String>,
        what: String,
    },
    Note(String),
}

impl Step {
    fn preview(&self, out: &mut String) {
        match self {
            Step::File { path, before, after, what } => {
                let _ = writeln!(out, "would {what}: {}", path.display());
                diff(out, before.as_deref().unwrap_or(""), after.as_deref().unwrap_or(""));
                if after.is_none() {
                    let _ = writeln!(out, "  (the file is deleted: nothing else is left in it)");
                }
            }
            Step::Run { argv, what } => {
                let _ = writeln!(out, "would {what}: {}", shown_command(argv));
            }
            Step::Note(n) => {
                let _ = writeln!(out, "note: {n}");
            }
        }
    }

    fn apply(&self, out: &mut String) -> Result<()> {
        match self {
            Step::File { path, before, after, what } => {
                let now = read(path)?;
                if now != *before {
                    bail!("{} changed while setup ran: nothing written to it, run setup again", path.display());
                }
                match after {
                    Some(text) => write_atomic(path, text)?,
                    None => std::fs::remove_file(path).with_context(|| format!("delete {}", path.display()))?,
                }
                let _ = writeln!(out, "{what}: {}", path.display());
            }
            Step::Run { argv, what } => {
                let o = std::process::Command::new(&argv[0])
                    .args(&argv[1..])
                    .stdin(std::process::Stdio::null())
                    .output()
                    .with_context(|| format!("run {}", argv[0]))?;
                if !o.status.success() {
                    bail!("{} failed: {}", shown_command(argv), String::from_utf8_lossy(&o.stderr).trim());
                }
                let _ = writeln!(out, "{what}: {}", shown_command(argv));
            }
            Step::Note(n) => {
                let _ = writeln!(out, "note: {n}");
            }
        }
        Ok(())
    }
}

fn shown_command(argv: &[String]) -> String {
    argv.iter().map(|a| shell_word(a)).collect::<Vec<_>>().join(" ")
}

/// `s` as one word of a shell: a POSIX shell, or on Windows cmd, PowerShell or Git Bash, where
/// double quotes hold a path in all three.
fn shell_word(s: &str) -> String {
    if cfg!(windows) {
        format!("\"{s}\"")
    } else if !s.is_empty() && s.bytes().all(|b| b.is_ascii_alphanumeric() || b"/._-:=+,@%".contains(&b)) {
        s.to_string()
    } else {
        format!("'{}'", s.replace('\'', r"'\''"))
    }
}

/// The lines that differ between `a` and `b`, as `- ` and `+ ` lines.
fn diff(out: &mut String, a: &str, b: &str) {
    let (a, b): (Vec<&str>, Vec<&str>) = (a.lines().collect(), b.lines().collect());
    let pre = a.iter().zip(&b).take_while(|(x, y)| x == y).count();
    let suf = a[pre..].iter().rev().zip(b[pre..].iter().rev()).take_while(|(x, y)| x == y).count();
    for (sign, lines) in [('-', &a[pre..a.len() - suf]), ('+', &b[pre..b.len() - suf])] {
        for line in lines {
            let _ = writeln!(out, "  {sign} {line}");
        }
    }
}

fn read(path: &Path) -> Result<Option<String>> {
    match std::fs::read(path) {
        Ok(b) => Ok(Some(String::from_utf8(b).map_err(|_| anyhow!("{} is not UTF-8: left as it is", path.display()))?)),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(e) => Err(e).with_context(|| format!("read {}", path.display())),
    }
}

/// Writes `text` to a temporary file beside `path` and renames it over `path`, keeping its
/// permissions; a link is followed, so the file it names is replaced and the link stays.
fn write_atomic(path: &Path, text: &str) -> Result<()> {
    let target = std::fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
    let dir = target.parent().filter(|d| !d.as_os_str().is_empty()).unwrap_or(Path::new("."));
    std::fs::create_dir_all(dir).with_context(|| format!("create {}", dir.display()))?;
    let name = target.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_default();
    let tmp = dir.join(format!(".{name}.scrutate-{}.tmp", std::process::id()));
    let written = (|| -> std::io::Result<()> {
        use std::io::Write;
        let mut f = std::fs::File::create(&tmp)?;
        f.write_all(text.as_bytes())?;
        f.sync_all()?;
        if let Ok(m) = std::fs::metadata(&target) {
            std::fs::set_permissions(&tmp, m.permissions())?;
        }
        std::fs::rename(&tmp, &target)
    })();
    if written.is_err() {
        let _ = std::fs::remove_file(&tmp);
    }
    written.with_context(|| format!("write {}", target.display()))
}

// ------------------------------------------------------------------------- what each agent gets

/// The arguments of the entry: the user's entry serves the repository the agent runs in, a
/// project's entry names its repository.
fn serve_args(o: Options, env: &Env) -> Vec<String> {
    if o.project {
        vec!["--root".into(), env.top.to_string_lossy().into_owned(), "serve".into()]
    } else {
        vec!["serve".into()]
    }
}

fn strings(v: &[String]) -> J {
    J::A(v.iter().cloned().map(J::S).collect())
}

fn plan(agent: Agent, o: Options, env: &Env) -> Result<Vec<Step>> {
    let args = serve_args(o, env);
    let bin = env.bin.clone();
    let mut steps = Vec::new();
    match agent {
        Agent::Claude => {
            let entry = obj(vec![("type", J::S("stdio".into())), ("command", J::S(bin.clone())), ("args", strings(&args))]);
            match (&env.claude, o.project) {
                (Some(claude), false) => steps.extend(claude_program(claude, &env.claude_json, &entry, o)?),
                _ => {
                    let path = if o.project { env.top.join(".mcp.json") } else { env.claude_json.clone() };
                    steps.extend(json_entry(&path, &["mcpServers", NAME], &entry, o)?);
                }
            }
            if o.project && !o.uninstall {
                steps.push(Step::Note("Claude Code asks once before it starts a server of a project's .mcp.json".into()));
            }
            if o.hook || o.uninstall {
                let settings = if o.project { env.top.join(".claude").join("settings.json") } else { env.claude_dir.join("settings.json") };
                steps.extend(asked(o.hook, claude_hook(&settings, &bin, o)?));
            }
        }
        Agent::Codex => {
            if o.project {
                bail!("Codex has no project configuration file: run `scrutate setup codex` for the user's {}", env.codex_home.join("config.toml").display());
            }
            steps.extend(toml_entry(&env.codex_home.join("config.toml"), &bin, &args, o)?);
            if o.hook {
                steps.push(Step::Note("Codex has PreToolUse hooks but searches by running rg in its shell, not through a search tool of its own; scrutate's hook answers Claude Code's Grep only, so no hook was installed".into()));
            }
        }
        Agent::Opencode => {
            let dir = if o.project { env.top.clone() } else { env.config_home.join("opencode") };
            let path = ["opencode.jsonc", "opencode.json"].iter().map(|n| dir.join(n)).find(|p| p.is_file()).unwrap_or_else(|| dir.join("opencode.json"));
            let text = read(&path)?;
            let v2 = match text.as_deref().filter(|t| !t.trim().is_empty()) {
                Some(t) => parse(t)
                    .map(|n| n.value(t))
                    .map_err(|e| anyhow!("{} does not parse ({e}): left as it is", path.display()))?
                    .pointer("/mcp/servers")
                    .is_some_and(Value::is_object),
                None => false,
            };
            let command = J::A(std::iter::once(J::S(bin.clone())).chain(args.iter().cloned().map(J::S)).collect());
            let (keys, entry): (&[&str], J) = if v2 {
                (&["mcp", "servers", NAME], obj(vec![("type", J::S("local".into())), ("command", command)]))
            } else {
                (&["mcp", NAME], obj(vec![("type", J::S("local".into())), ("command", command), ("enabled", J::B(true))]))
            };
            steps.extend(json_entry(&path, keys, &entry, o)?);
            if o.hook {
                steps.push(Step::Note("opencode's hooks are JavaScript plugins (tool.execute.before), not commands; scrutate's hook answers Claude Code's Grep only, so no hook was installed".into()));
            }
        }
        Agent::Cursor => {
            let path = if o.project { env.top.join(".cursor").join("mcp.json") } else { env.home.join(".cursor").join("mcp.json") };
            let entry = obj(vec![("command", J::S(bin.clone())), ("args", strings(&args))]);
            steps.extend(json_entry(&path, &["mcpServers", NAME], &entry, o)?);
            if o.hook {
                steps.push(Step::Note("cursor-agent has a preToolUse hook, but its search tool takes other arguments and answers in another form; scrutate's hook answers Claude Code's Grep only, so no hook was installed".into()));
            }
        }
        Agent::Gemini => {
            let path = if o.project { env.top.join(".gemini").join("settings.json") } else { env.home.join(".gemini").join("settings.json") };
            let entry = obj(vec![("command", J::S(bin.clone())), ("args", strings(&args))]);
            steps.extend(json_entry(&path, &["mcpServers", NAME], &entry, o)?);
            if !o.uninstall {
                steps.push(Step::Note(
                    "Gemini CLI starts a stdio server only in a folder it trusts (`gemini trust`, or ~/.gemini/trustedFolders.json); setup leaves trust to you"
                        .into(),
                ));
            }
            if o.hook {
                steps.push(Step::Note("Gemini CLI has a BeforeTool hook, but its search tool takes other arguments and answers in another form; scrutate's hook answers Claude Code's Grep only, so no hook was installed".into()));
            }
        }
    }
    // an uninstall takes out everything setup adds, so a removed binary leaves no hook behind
    if o.instructions || o.uninstall {
        let file = match (agent, o.project) {
            (Agent::Claude, false) => Some(env.claude_dir.join("CLAUDE.md")),
            (Agent::Claude, true) => Some(env.top.join("CLAUDE.md")),
            (Agent::Codex, _) => Some(env.codex_home.join("AGENTS.md")),
            (Agent::Opencode, false) => Some(env.config_home.join("opencode").join("AGENTS.md")),
            (Agent::Opencode | Agent::Cursor, true) => Some(env.top.join("AGENTS.md")),
            (Agent::Cursor, false) => None,
            (Agent::Gemini, false) => Some(env.home.join(".gemini").join("GEMINI.md")),
            (Agent::Gemini, true) => Some(env.top.join("GEMINI.md")),
        };
        match file {
            Some(f) => steps.extend(asked(o.instructions, block_entry(&f, o)?)),
            None if !o.instructions => {}
            None => steps.push(Step::Note(
                "Cursor keeps a user's rules in its settings, not in a file: no instructions were written (with --project they go into AGENTS.md)".into(),
            )),
        }
    }
    Ok(steps)
}

/// `steps`, without the notes (`has no scrutate hook`) of a part the command line did not name.
fn asked(named: bool, steps: Vec<Step>) -> Vec<Step> {
    steps.into_iter().filter(|s| named || !matches!(s, Step::Note(_))).collect()
}

/// The user scope of Claude Code through its own `claude mcp`, which many running Claude Code
/// processes share `~/.claude.json` with.
fn claude_program(claude: &Path, file: &Path, entry: &J, o: Options) -> Result<Vec<Step>> {
    let current = match read(file)? {
        Some(t) if !t.trim().is_empty() => parse(&t)
            .map(|n| n.value(&t))
            .map_err(|e| anyhow!("{} does not parse ({e}): left as it is", file.display()))?
            .pointer(&format!("/mcpServers/{NAME}"))
            .cloned(),
        _ => None,
    };
    let claude = claude.to_string_lossy().into_owned();
    let remove = Step::Run {
        argv: vec![claude.clone(), "mcp".into(), "remove".into(), NAME.into(), "--scope".into(), "user".into()],
        what: "removed the scrutate server".into(),
    };
    let add = Step::Run {
        argv: vec![claude, "mcp".into(), "add-json".into(), NAME.into(), entry.value().to_string(), "--scope".into(), "user".into()],
        what: "added the scrutate server".into(),
    };
    Ok(match (o.uninstall, current) {
        (true, Some(_)) => vec![remove],
        (true, None) => vec![Step::Note(format!("{} has no scrutate server", file.display()))],
        (false, Some(v)) if v == entry.value() => vec![Step::Note(format!("{} already has the scrutate server", file.display()))],
        (false, Some(_)) => vec![remove, add],
        (false, None) => vec![add],
    })
}

fn file_step(path: &Path, before: Option<String>, after: Option<String>, what: &str) -> Step {
    Step::File { path: path.to_path_buf(), before, after, what: what.into() }
}

/// The member at `keys` of a JSON (or JSONC) file set to `entry`, or removed.
fn json_entry(path: &Path, keys: &[&str], entry: &J, o: Options) -> Result<Vec<Step>> {
    let before = read(path)?;
    let refused = |e: anyhow::Error| anyhow!("{} does not parse ({e:#}): left as it is", path.display());
    let label = keys.join(".");
    if o.uninstall {
        return Ok(match before.as_deref().filter(|t| !t.trim().is_empty()) {
            None => vec![Step::Note(format!("{} has no {label}", path.display()))],
            Some(t) => match unset(t, keys).map_err(refused)? {
                None => vec![Step::Note(format!("{} has no {label}", path.display()))],
                Some(after) => vec![file_step(path, before.clone(), after, &format!("removed {label} from"))],
            },
        });
    }
    let after = set(before.as_deref().filter(|t| !t.trim().is_empty()), keys, entry).map_err(refused)?;
    Ok(match after {
        None => vec![Step::Note(format!("{} already has {label}", path.display()))],
        Some(a) => vec![file_step(path, before, Some(a), &format!("added {label} to"))],
    })
}

/// The hook entry of Claude Code's settings: a `PreToolUse` group with matcher `Grep`.
fn claude_hook(path: &Path, bin: &str, o: Options) -> Result<Vec<Step>> {
    let mut hook = vec![("type", J::S("command".into()))];
    hook.extend(hook_run(bin, cfg!(windows)));
    hook.push(("timeout", J::N(HOOK_TIMEOUT_S)));
    let group = obj(vec![("matcher", J::S("Grep".into())), ("hooks", J::A(vec![obj(hook)]))]);
    let before = read(path)?;
    let refused = |e: anyhow::Error| anyhow!("{} does not parse ({e:#}): left as it is", path.display());
    let keys = ["hooks", "PreToolUse"];
    let text = before.as_deref().filter(|t| !t.trim().is_empty());
    if o.uninstall {
        let after = match text {
            Some(t) => pull(t, &keys, is_our_hook).map_err(refused)?,
            None => None,
        };
        return Ok(match after {
            None => vec![Step::Note(format!("{} has no scrutate hook", path.display()))],
            Some(a) => vec![file_step(path, before.clone(), a, "removed the scrutate Grep hook from")],
        });
    }
    Ok(match push(text, &keys, &group, is_our_hook).map_err(refused)? {
        None => vec![Step::Note(format!("{} already has the scrutate Grep hook", path.display()))],
        Some(a) => vec![file_step(path, before, Some(a), "added the scrutate Grep hook to")],
    })
}

/// How Claude Code runs the hook. On Windows it runs a command in Git Bash, or in PowerShell
/// when there is no Git Bash (`Sn=e.shell??ij()`): a path with `/` and no character either shell
/// reads runs the same in both; another path goes as the program and its arguments, which
/// Claude Code starts with no shell (`B$e(wo[0],wo[1],...)`).
fn hook_run(bin: &str, windows: bool) -> Vec<(&'static str, J)> {
    if !windows {
        return vec![("command", J::S(format!("{} hook grep", shell_word(bin))))];
    }
    if bin.chars().all(|c| c.is_alphanumeric() || r"\/._-:".contains(c)) {
        vec![("command", J::S(format!("{} hook grep", bin.replace('\\', "/"))))]
    } else {
        vec![("command", J::S(bin.into())), ("args", strings(&["hook".into(), "grep".into()]))]
    }
}

fn is_our_hook(v: &Value) -> bool {
    let ours = |h: &Value| {
        let command = h.get("command").and_then(Value::as_str).unwrap_or("");
        match h.get("args") {
            None => command.ends_with(" hook grep") && command.contains("scrutate"),
            Some(a) => command.contains("scrutate") && *a == serde_json::json!(["hook", "grep"]),
        }
    };
    v.get("matcher").and_then(Value::as_str) == Some("Grep") && v.get("hooks").and_then(Value::as_array).is_some_and(|h| h.len() == 1 && ours(&h[0]))
}

/// `[mcp_servers.scrutate]` of Codex's `config.toml`, appended as one table, or removed.
fn toml_entry(path: &Path, bin: &str, args: &[String], o: Options) -> Result<Vec<Step>> {
    let before = read(path)?;
    let old: toml::Table = match before.as_deref() {
        Some(t) => t.parse().map_err(|e| anyhow!("{} does not parse ({e}): left as it is", path.display()))?,
        None => toml::Table::new(),
    };
    let current = old.get("mcp_servers").and_then(|t| t.get(NAME)).cloned();
    if o.uninstall {
        let Some(text) = before.as_deref().filter(|_| current.is_some()) else {
            return Ok(vec![Step::Note(format!("{} has no mcp_servers.scrutate", path.display()))]);
        };
        let after = toml_unset(text, &old).with_context(|| format!("{}", path.display()))?;
        return Ok(vec![file_step(path, before.clone(), (!after.is_empty()).then_some(after), "removed mcp_servers.scrutate from")]);
    }
    let block = format!("[mcp_servers.{NAME}]\ncommand = {}\nargs = [{}]\n", toml_str(bin), args.iter().map(|a| toml_str(a)).collect::<Vec<_>>().join(", "));
    let want: toml::Table = block.parse().expect("the block setup writes");
    let want_entry = want["mcp_servers"][NAME].clone();
    if current.as_ref() == Some(&want_entry) {
        return Ok(vec![Step::Note(format!("{} already has mcp_servers.scrutate", path.display()))]);
    }
    let base = match (&current, before.as_deref()) {
        (Some(_), Some(t)) => toml_unset(t, &old).with_context(|| format!("{}", path.display()))?,
        (_, t) => t.unwrap_or("").to_string(),
    };
    let after = if base.is_empty() { block } else { format!("{base}\n{block}") };
    let mut expected = old.clone();
    expected
        .entry("mcp_servers")
        .or_insert_with(|| toml::Value::Table(toml::Table::new()))
        .as_table_mut()
        .context("mcp_servers is not a table")?
        .insert(NAME.into(), want_entry);
    if after.parse::<toml::Table>().ok() != Some(expected) {
        bail!("{}: the scrutate table cannot be added as a table of its own here (an inline mcp_servers?): edit it by hand", path.display());
    }
    Ok(vec![file_step(path, before, Some(after), "added mcp_servers.scrutate to")])
}

/// A TOML basic string.
fn toml_str(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            c if (c as u32) < 0x20 || c == '\u{7f}' => {
                let _ = write!(out, "\\u{:04X}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// `text` without its `[mcp_servers.scrutate]` table (and its subtables), and the newline setup
/// put before it.
fn toml_unset(text: &str, old: &toml::Table) -> Result<String> {
    let header = format!("[mcp_servers.{NAME}]");
    let sub = format!("[mcp_servers.{NAME}.");
    let mut starts = vec![0];
    starts.extend(text.match_indices('\n').map(|(i, _)| i + 1).filter(|&i| i < text.len()));
    let line = |i: usize| text[starts[i]..starts.get(i + 1).copied().unwrap_or(text.len())].trim();
    let first = (0..starts.len()).find(|&i| line(i) == header).ok_or_else(|| anyhow!("mcp_servers.scrutate is not a table of its own: edit it by hand"))?;
    let mut last = first;
    for i in first + 1..starts.len() {
        let l = line(i);
        if l.starts_with('[') && !l.starts_with(&sub) {
            break;
        }
        last = i;
    }
    // blank lines and comments before the next table belong to it
    while last > first && (line(last).is_empty() || line(last).starts_with('#')) {
        last -= 1;
    }
    let end = starts.get(last + 1).copied().unwrap_or(text.len());
    let start = starts[first].saturating_sub(usize::from(starts[first] > 0));
    let after = format!("{}{}", &text[..start], &text[end..]);
    let mut expected = old.clone();
    if let Some(t) = expected.get_mut("mcp_servers").and_then(toml::Value::as_table_mut) {
        t.remove(NAME);
    }
    let empty = |t: &mut toml::Table| {
        if t.get("mcp_servers").and_then(toml::Value::as_table).is_some_and(toml::Table::is_empty) {
            t.remove("mcp_servers");
        }
    };
    empty(&mut expected);
    let mut got: toml::Table = after.parse().map_err(|_| anyhow!("mcp_servers.scrutate cannot be cut out cleanly: edit it by hand"))?;
    empty(&mut got);
    if got != expected {
        bail!("mcp_servers.scrutate cannot be cut out cleanly: edit it by hand");
    }
    Ok(after)
}

/// The instruction block, appended to the agent's instruction file, or removed.
fn block_entry(path: &Path, o: Options) -> Result<Vec<Step>> {
    let block = format!(
        "{BEGIN}\nUse the scrutate MCP tools to search code: `search_code` for a question in words or a name, `grep_code` for an exact pattern, `find_symbol` for a definition, `references`, `callers` and `callees` to follow a name, and `outline` and `read_code` to read a file in pieces instead of whole.\n{END}\n"
    );
    let before = read(path)?;
    let text = before.as_deref().unwrap_or("");
    let found = text.find(BEGIN).and_then(|b| text[b..].find(END).map(|e| (b, b + e + END.len() + usize::from(text[b + e + END.len()..].starts_with('\n')))));
    if o.uninstall {
        let Some((b, e)) = found else {
            return Ok(vec![Step::Note(format!("{} has no scrutate block", path.display()))]);
        };
        let start = b.saturating_sub(usize::from(b > 0 && text.as_bytes()[b - 1] == b'\n'));
        let after = format!("{}{}", &text[..start], &text[e..]);
        return Ok(vec![file_step(path, before.clone(), (!after.is_empty()).then_some(after), "removed the scrutate block from")]);
    }
    let after = match found {
        Some((b, e)) if text[b..e] == block => return Ok(vec![Step::Note(format!("{} already has the scrutate block", path.display()))]),
        Some((b, e)) => format!("{}{block}{}", &text[..b], &text[e..]),
        None if text.is_empty() => block,
        None => format!("{text}\n{block}"),
    };
    Ok(vec![file_step(path, before, Some(after), "added the scrutate block to")])
}

// ------------------------------------------------------------------------- JSON values written

/// A JSON value with its keys in the order they are written.
#[derive(Clone)]
enum J {
    S(String),
    B(bool),
    N(u64),
    A(Vec<J>),
    O(Vec<(String, J)>),
}

fn obj(pairs: Vec<(&str, J)>) -> J {
    J::O(pairs.into_iter().map(|(k, v)| (k.to_string(), v)).collect())
}

impl J {
    fn value(&self) -> Value {
        match self {
            J::S(s) => Value::String(s.clone()),
            J::B(b) => Value::Bool(*b),
            J::N(n) => Value::from(*n),
            J::A(a) => Value::Array(a.iter().map(J::value).collect()),
            J::O(o) => Value::Object(o.iter().map(|(k, v)| (k.clone(), v.value())).collect()),
        }
    }

    /// Pretty, `unit` per level, the first line at the caller's position and the rest at `depth`.
    fn render(&self, unit: &str, depth: usize) -> String {
        let pad = |d: usize| unit.repeat(d);
        match self {
            J::A(a) if !a.is_empty() => {
                format!("[\n{}\n{}]", a.iter().map(|v| format!("{}{}", pad(depth + 1), v.render(unit, depth + 1))).collect::<Vec<_>>().join(",\n"), pad(depth))
            }
            J::O(o) if !o.is_empty() => format!(
                "{{\n{}\n{}}}",
                o.iter().map(|(k, v)| format!("{}{}: {}", pad(depth + 1), Value::from(k.as_str()), v.render(unit, depth + 1))).collect::<Vec<_>>().join(",\n"),
                pad(depth)
            ),
            other => other.value().to_string(),
        }
    }
}

// ------------------------------------------------------------------------- JSONC text edits

/// A value of a JSON text, with comments and trailing commas allowed (JSONC), by byte span.
#[derive(Debug)]
struct Node {
    start: usize,
    end: usize,
    kind: Kind,
}

#[derive(Debug)]
enum Kind {
    /// members: the key's start, the key, the value
    Object(Vec<(usize, String, Node)>),
    Array(Vec<Node>),
    Scalar,
}

impl Node {
    fn value(&self, text: &str) -> Value {
        match &self.kind {
            Kind::Object(m) => Value::Object(m.iter().map(|(_, k, v)| (k.clone(), v.value(text))).collect()),
            Kind::Array(a) => Value::Array(a.iter().map(|v| v.value(text)).collect()),
            Kind::Scalar => serde_json::from_str(&text[self.start..self.end]).unwrap_or(Value::Null),
        }
    }

    fn member(&self, key: &str) -> Option<(usize, &Node)> {
        match &self.kind {
            // the last of two equal keys is the one a reader keeps
            Kind::Object(m) => m.iter().rposition(|(_, k, _)| k == key).map(|i| (i, &m[i].2)),
            _ => None,
        }
    }

    /// Where each entry starts (a member's key, an item) and ends.
    fn entries(&self) -> Vec<(usize, usize)> {
        match &self.kind {
            Kind::Object(m) => m.iter().map(|(s, _, v)| (*s, v.end)).collect(),
            Kind::Array(a) => a.iter().map(|v| (v.start, v.end)).collect(),
            Kind::Scalar => Vec::new(),
        }
    }
}

struct Parser<'a> {
    s: &'a [u8],
    i: usize,
}

fn parse(text: &str) -> Result<Node> {
    let mut p = Parser { s: text.as_bytes(), i: 0 };
    p.ws()?;
    let n = p.value(0)?;
    p.ws()?;
    if p.i != p.s.len() {
        bail!("unexpected text at byte {}", p.i);
    }
    Ok(n)
}

impl Parser<'_> {
    fn ws(&mut self) -> Result<()> {
        loop {
            match self.s.get(self.i) {
                Some(b' ' | b'\t' | b'\n' | b'\r') => self.i += 1,
                Some(b'/') if self.s.get(self.i + 1) == Some(&b'/') => {
                    while self.i < self.s.len() && self.s[self.i] != b'\n' {
                        self.i += 1;
                    }
                }
                Some(b'/') if self.s.get(self.i + 1) == Some(&b'*') => {
                    let close = self.s[self.i + 2..].windows(2).position(|w| w == b"*/").ok_or_else(|| anyhow!("unclosed comment at byte {}", self.i))?;
                    self.i += close + 4;
                }
                _ => return Ok(()),
            }
        }
    }

    fn value(&mut self, depth: usize) -> Result<Node> {
        if depth > 256 {
            bail!("nested too deeply");
        }
        let start = self.i;
        let kind = match self.s.get(self.i) {
            Some(b'{') => {
                self.i += 1;
                let mut members = Vec::new();
                loop {
                    self.ws()?;
                    if self.s.get(self.i) == Some(&b'}') {
                        break;
                    }
                    let key_start = self.i;
                    let key = match self.string()? {
                        Value::String(k) => k,
                        _ => unreachable!(),
                    };
                    self.ws()?;
                    self.expect(b':')?;
                    self.ws()?;
                    let v = self.value(depth + 1)?;
                    members.push((key_start, key, v));
                    self.ws()?;
                    match self.s.get(self.i) {
                        Some(b',') => self.i += 1,
                        Some(b'}') => break,
                        _ => bail!("expected , or }} at byte {}", self.i),
                    }
                }
                self.i += 1;
                Kind::Object(members)
            }
            Some(b'[') => {
                self.i += 1;
                let mut items = Vec::new();
                loop {
                    self.ws()?;
                    if self.s.get(self.i) == Some(&b']') {
                        break;
                    }
                    items.push(self.value(depth + 1)?);
                    self.ws()?;
                    match self.s.get(self.i) {
                        Some(b',') => self.i += 1,
                        Some(b']') => break,
                        _ => bail!("expected , or ] at byte {}", self.i),
                    }
                }
                self.i += 1;
                Kind::Array(items)
            }
            Some(b'"') => {
                self.string()?;
                Kind::Scalar
            }
            Some(_) => {
                let n = self.s[self.i..].iter().position(|b| !(b.is_ascii_alphanumeric() || b"+-.".contains(b))).unwrap_or(self.s.len() - self.i);
                serde_json::from_slice::<Value>(&self.s[self.i..self.i + n]).map_err(|_| anyhow!("unexpected text at byte {}", self.i))?;
                self.i += n;
                Kind::Scalar
            }
            None => bail!("unexpected end"),
        };
        Ok(Node { start, end: self.i, kind })
    }

    fn string(&mut self) -> Result<Value> {
        let start = self.i;
        self.expect(b'"')?;
        while let Some(&b) = self.s.get(self.i) {
            self.i += 1;
            match b {
                b'\\' => self.i += 1,
                b'"' => return serde_json::from_slice(&self.s[start..self.i]).map_err(|_| anyhow!("bad string at byte {start}")),
                _ => {}
            }
        }
        bail!("unclosed string at byte {start}")
    }

    fn expect(&mut self, b: u8) -> Result<()> {
        if self.s.get(self.i) != Some(&b) {
            bail!("expected {} at byte {}", b as char, self.i);
        }
        self.i += 1;
        Ok(())
    }
}

/// The indentation the file uses per level: the least of its indented lines, else two spaces.
fn indent_unit(text: &str) -> String {
    text.lines()
        .skip(1)
        .filter_map(|l| {
            let pad = l.len() - l.trim_start_matches([' ', '\t']).len();
            (pad > 0 && pad < l.len()).then(|| &l[..pad])
        })
        .min_by_key(|p| p.len())
        .unwrap_or("  ")
        .to_string()
}

/// What lies on the way down to an entry, outermost first: a member, or an array's item.
#[derive(Clone)]
enum Hop<'a> {
    Key(&'a str),
    Item,
}

/// The text setup writes for containers that hold only the next hop, `inner` inside them.
fn chain(hops: &[Hop], inner: &str, unit: &str, depth: usize) -> String {
    let pad = |d: usize| unit.repeat(d);
    match hops.first() {
        None => inner.to_string(),
        Some(Hop::Key(k)) => format!("{{\n{}{}: {}\n{}}}", pad(depth + 1), Value::from(*k), chain(&hops[1..], inner, unit, depth + 1), pad(depth)),
        Some(Hop::Item) => format!("[\n{}{}\n{}]", pad(depth + 1), chain(&hops[1..], inner, unit, depth + 1), pad(depth)),
    }
}

fn splice(text: &str, at: usize, to: usize, with: &str) -> String {
    format!("{}{with}{}", &text[..at], &text[to..])
}

/// `entry` (a member's `"key": value`, or an item) added as the last entry of `c`, at `depth`.
fn insert(text: &str, c: &Node, depth: usize, entry: &str, unit: &str) -> String {
    match c.entries().last() {
        Some(&(_, end)) => splice(text, end, end, &format!(",\n{}{entry}", unit.repeat(depth + 1))),
        // right after the brace: what setup makes itself is laid out otherwise (`chain`), so the
        // two never read the same and `--uninstall` knows which to take back
        None => splice(text, c.start + 1, c.start + 1, entry),
    }
}

/// The entry `idx` of `c` taken out, as `insert` put it in.
fn remove(text: &str, c: &Node, idx: usize) -> String {
    let e = c.entries();
    if e.len() == 1 {
        splice(text, c.start + 1, e[0].1, "")
    } else if idx > 0 {
        splice(text, e[idx - 1].1, e[idx].1, "")
    } else {
        splice(text, e[0].0, e[1].0, "")
    }
}

/// The containers on the way down `keys`, root first, as far as they exist.
fn walk<'n>(root: &'n Node, keys: &[&str]) -> Result<Vec<&'n Node>> {
    let mut nodes = vec![root];
    for k in keys {
        let n = *nodes.last().expect("the root");
        if !matches!(n.kind, Kind::Object(_)) {
            bail!("{} is not an object", if nodes.len() == 1 { "the file".to_string() } else { keys[..nodes.len() - 1].join(".") });
        }
        match n.member(k) {
            Some((_, v)) => nodes.push(v),
            None => break,
        }
    }
    Ok(nodes)
}

/// The text after an edit, if it reads as `expected`.
fn checked(text: String, expected: &Value) -> Result<String> {
    let got = parse(&text).map(|n| n.value(&text)).ok();
    if got.as_ref() != Some(expected) {
        bail!("the edit would change more than the entry, so nothing is written");
    }
    Ok(text)
}

fn set_value(v: &mut Value, keys: &[&str], new: Value) {
    let mut at = v;
    for k in &keys[..keys.len() - 1] {
        at = at.as_object_mut().expect("checked to be an object").entry(k.to_string()).or_insert_with(|| Value::Object(Default::default()));
    }
    at.as_object_mut().expect("checked to be an object").insert(keys[keys.len() - 1].to_string(), new);
}

fn nested(keys: &[&str], inner: J) -> J {
    keys.iter().rev().fold(inner, |v, k| J::O(vec![(k.to_string(), v)]))
}

/// `text` with the member at `keys` set to `v` (the objects on the way made when missing); `None`
/// when it already holds `v`. A missing file (`None`) becomes one that holds only that member,
/// ending in a newline.
fn set(text: Option<&str>, keys: &[&str], v: &J) -> Result<Option<String>> {
    let Some(text) = text else {
        return Ok(Some(format!("{}\n", nested(keys, v.clone()).render("  ", 0))));
    };
    let root = parse(text)?;
    let unit = indent_unit(text);
    let nodes = walk(&root, keys)?;
    let mut expected = root.value(text);
    if !expected.is_object() {
        bail!("the file is not an object");
    }
    set_value(&mut expected, keys, v.value());
    let depth = nodes.len() - 1;
    let after = if depth == keys.len() {
        let old = nodes[depth];
        if old.value(text) == v.value() {
            return Ok(None);
        }
        splice(text, old.start, old.end, &v.render(&unit, depth))
    } else {
        let parent = nodes[depth];
        if !matches!(parent.kind, Kind::Object(_)) {
            bail!("{} is not an object", keys[..depth].join("."));
        }
        let rest = nested(&keys[depth + 1..], v.clone());
        insert(text, parent, depth, &format!("{}: {}", Value::from(keys[depth]), rest.render(&unit, depth + 1)), &unit)
    };
    checked(after, &expected).map(Some)
}

/// The outermost container on the way to the entry that holds nothing else, in the form setup
/// writes it: removing that container's own entry takes back exactly what setup added.
/// `nodes[0]` is the root; `hops[i]` leads from `nodes[i]` down. `None`: the whole file.
fn outermost_made(text: &str, nodes: &[&Node], hops: &[Hop], inner: &str, unit: &str) -> Option<Option<usize>> {
    let single = |n: &Node| n.entries().len() == 1;
    if nodes.iter().all(|n| single(n)) && text == format!("{}\n", chain(hops, inner, unit, 0)) {
        return Some(None);
    }
    (1..nodes.len()).find(|&i| nodes[i..].iter().all(|n| single(n)) && text[nodes[i].start..nodes[i].end] == chain(&hops[i..], inner, unit, i)).map(Some)
}

/// `text` without the member at `keys`, and without the objects setup made for it: `None` when
/// there is no such member, `Some(None)` when the file held nothing else.
fn unset(text: &str, keys: &[&str]) -> Result<Option<Option<String>>> {
    let root = parse(text)?;
    let unit = indent_unit(text);
    let nodes = walk(&root, keys)?;
    if nodes.len() != keys.len() + 1 {
        return Ok(None);
    }
    let containers = &nodes[..keys.len()];
    let entry = nodes[keys.len()];
    let hops: Vec<Hop> = keys.iter().map(|k| Hop::Key(k)).collect();
    cut(text, &root, containers, &hops, &text[entry.start..entry.end], &unit, |c, i| c.member(keys[i]).map(|m| m.0).expect("walked"))
}

/// Removes the entry under `containers` (the last one holds it at the last hop), or the
/// outermost container setup made for it.
fn cut(
    text: &str,
    root: &Node,
    containers: &[&Node],
    hops: &[Hop],
    inner: &str,
    unit: &str,
    index: impl Fn(&Node, usize) -> usize,
) -> Result<Option<Option<String>>> {
    let mut expected = root.value(text);
    let at = match outermost_made(text, containers, hops, inner, unit) {
        Some(None) => return Ok(Some(None)),
        Some(Some(i)) => i - 1,
        None => containers.len() - 1,
    };
    let c = containers[at];
    let idx = index(c, at);
    // the expected value: the same entry removed from the parsed value
    let mut v = &mut expected;
    for (i, h) in hops[..at].iter().enumerate() {
        v = match h {
            Hop::Key(k) => v.get_mut(*k).expect("walked"),
            Hop::Item => v.get_mut(index(containers[i], i)).expect("walked"),
        };
    }
    match &hops[at] {
        Hop::Key(k) => {
            v.as_object_mut().expect("an object").remove(*k);
        }
        Hop::Item => {
            v.as_array_mut().expect("an array").remove(idx);
        }
    }
    checked(remove(text, c, idx), &expected).map(|t| Some(Some(t)))
}

/// `text` with `item` in the array at `keys` (made when missing), in place of the item `ours`
/// says is setup's; `None` when that item is already `item`.
fn push(text: Option<&str>, keys: &[&str], item: &J, ours: fn(&Value) -> bool) -> Result<Option<String>> {
    let Some(t) = text else {
        return set(None, keys, &J::A(vec![item.clone()]));
    };
    let root = parse(t)?;
    let unit = indent_unit(t);
    let nodes = walk(&root, keys)?;
    if nodes.len() != keys.len() + 1 {
        return set(Some(t), keys, &J::A(vec![item.clone()]));
    }
    let arr = nodes[keys.len()];
    let Kind::Array(items) = &arr.kind else { bail!("{} is not a list", keys.join(".")) };
    let mut expected = root.value(t);
    let mut list: Vec<Value> = items.iter().map(|n| n.value(t)).collect();
    let after = match list.iter().position(ours) {
        Some(i) if list[i] == item.value() => return Ok(None),
        Some(i) => {
            list[i] = item.value();
            splice(t, items[i].start, items[i].end, &item.render(&unit, keys.len() + 1))
        }
        None => {
            list.push(item.value());
            insert(t, arr, keys.len(), &item.render(&unit, keys.len() + 1), &unit)
        }
    };
    set_value(&mut expected, keys, Value::Array(list));
    checked(after, &expected).map(Some)
}

/// `text` without the item of the array at `keys` that `ours` says is setup's (and the
/// containers setup made for it): `None` when there is none, `Some(None)` when nothing else is left.
fn pull(text: &str, keys: &[&str], ours: fn(&Value) -> bool) -> Result<Option<Option<String>>> {
    let root = parse(text)?;
    let unit = indent_unit(text);
    let nodes = walk(&root, keys)?;
    if nodes.len() != keys.len() + 1 {
        return Ok(None);
    }
    let Kind::Array(items) = &nodes[keys.len()].kind else { return Ok(None) };
    let Some(idx) = items.iter().position(|n| ours(&n.value(text))) else { return Ok(None) };
    let item = &items[idx];
    let mut hops: Vec<Hop> = keys.iter().map(|k| Hop::Key(k)).collect();
    hops.push(Hop::Item);
    cut(
        text,
        &root,
        &nodes,
        &hops,
        &text[item.start..item.end],
        &unit,
        |c, i| if i == keys.len() { idx } else { c.member(keys[i]).map(|m| m.0).expect("walked") },
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    fn run(bin: &str) -> Value {
        obj(hook_run(bin, true)).value()
    }

    #[test]
    fn on_windows_the_hook_runs_in_git_bash_and_powershell_alike() {
        let plain = run(r"C:\Users\cris\.cargo\bin\scrutate.exe");
        assert_eq!(plain, serde_json::json!({"command": "C:/Users/cris/.cargo/bin/scrutate.exe hook grep"}));
        let spaced = run(r"C:\Program Files\scrutate\scrutate.exe");
        assert_eq!(spaced, serde_json::json!({"command": r"C:\Program Files\scrutate\scrutate.exe", "args": ["hook", "grep"]}));
        for h in [plain, spaced] {
            assert!(is_our_hook(&serde_json::json!({"matcher": "Grep", "hooks": [h]})));
        }
        assert!(is_our_hook(&serde_json::json!({"matcher": "Grep", "hooks": [{"command": r#""C:\x\scrutate.exe" hook grep"#}]})));
        assert!(!is_our_hook(&serde_json::json!({"matcher": "Grep", "hooks": [{"command": "scrutate.exe", "args": ["serve"]}]})));
    }

    fn entry() -> J {
        obj(vec![("command", J::S("/bin/scrutate".into())), ("args", J::A(vec![J::S("serve".into())]))])
    }

    fn round_trip(before: &str) {
        let keys = ["mcpServers", NAME];
        let after = set(Some(before), &keys, &entry()).unwrap().expect("a change");
        assert_eq!(set(Some(&after), &keys, &entry()).unwrap(), None, "a second run changes nothing");
        assert_eq!(unset(&after, &keys).unwrap(), Some(Some(before.to_string())), "after:\n{after}");
    }

    #[test]
    fn a_member_goes_in_and_comes_out_byte_for_byte() {
        round_trip("{}\n");
        round_trip("{\n}\n");
        round_trip("{\"a\":1}");
        round_trip("{\n  \"a\": 1\n}\n");
        round_trip("{\n  \"a\": 1,\n}\n");
        round_trip("{\n\t\"mcpServers\": {\n\t\t\"other\": {\"command\": \"x\"}\n\t}\n}\n");
        round_trip("{\n  \"mcpServers\": {}\n}\n");
        round_trip("// comment\n{\n  /* keep */ \"a\": [1, 2], // tail\n  \"b\": {\"c\": null}\n}\n");
    }

    #[test]
    fn a_file_setup_made_is_deleted_and_a_bad_one_refused() {
        let made = set(None, &["mcpServers", NAME], &entry()).unwrap().unwrap();
        assert_eq!(made, "{\n  \"mcpServers\": {\n    \"scrutate\": {\n      \"command\": \"/bin/scrutate\",\n      \"args\": [\n        \"serve\"\n      ]\n    }\n  }\n}\n");
        assert_eq!(unset(&made, &["mcpServers", NAME]).unwrap(), Some(None));
        assert!(set(Some("{\"a\": }"), &["mcpServers", NAME], &entry()).is_err());
        assert!(set(Some("{\"mcpServers\": 3}"), &["mcpServers", NAME], &entry()).is_err());
    }

    #[test]
    fn a_hook_item_goes_into_a_list_and_comes_out() {
        let item = obj(vec![
            ("matcher", J::S("Grep".into())),
            ("hooks", J::A(vec![obj(vec![("type", J::S("command".into())), ("command", J::S("/x/scrutate hook grep".into()))])])),
        ]);
        let keys = ["hooks", "PreToolUse"];
        for before in
            ["{}\n", "{\n  \"hooks\": {\n    \"PreToolUse\": [\n      {\"matcher\": \"Bash\", \"hooks\": []}\n    ]\n  }\n}\n", "{\n  \"hooks\": {}\n}\n"]
        {
            let after = push(Some(before), &keys, &item, is_our_hook).unwrap().unwrap();
            assert_eq!(push(Some(&after), &keys, &item, is_our_hook).unwrap(), None);
            assert_eq!(pull(&after, &keys, is_our_hook).unwrap(), Some(Some(before.to_string())), "after:\n{after}");
        }
    }

    #[test]
    fn a_toml_table_goes_in_and_comes_out_with_the_comments() {
        for before in ["", "model = \"x\" # mine\n", "# top\n[mcp_servers.other]\ncommand = \"y\"\n", "a = 1"] {
            let old: toml::Table = before.parse().unwrap();
            let block = "[mcp_servers.scrutate]\ncommand = \"/bin/s\"\nargs = [\"serve\"]\n";
            let after = if before.is_empty() { block.to_string() } else { format!("{before}\n{block}") };
            let mid: toml::Table = after.parse().unwrap();
            assert_ne!(mid, old);
            assert_eq!(toml_unset(&after, &mid).unwrap(), before);
        }
        assert_eq!(toml_str("C:\\a \"b\""), "\"C:\\\\a \\\"b\\\"\"");
    }

    #[test]
    fn a_diff_shows_the_changed_lines() {
        let mut out = String::new();
        diff(&mut out, "a\nb\nc\n", "a\nb\nX\nc\n");
        assert_eq!(out, "  + X\n");
    }
}

//! How Engine A reads one byte source: the first read, the byte-order mark, the NUL byte, the size
//! thresholds, the split of a large file, the long line and the searcher's setup. A source is a
//! file on disk, standard input, an archive member or text held in memory; the rules ask it for
//! its size, positioned reads and one sequential read, and nothing else.

use super::*;
use std::fs::File;
use std::io::Read;

/// Reads at an offset, without moving the position a sequential read starts from.
pub(super) trait ReadAt {
    fn read_at(&self, buf: &mut [u8], off: u64) -> std::io::Result<usize>;
}

impl ReadAt for File {
    #[cfg(unix)]
    fn read_at(&self, buf: &mut [u8], off: u64) -> std::io::Result<usize> {
        std::os::unix::fs::FileExt::read_at(self, buf, off)
    }
    #[cfg(windows)]
    fn read_at(&self, buf: &mut [u8], off: u64) -> std::io::Result<usize> {
        std::os::windows::fs::FileExt::seek_read(self, buf, off)
    }
    #[cfg(not(any(unix, windows)))]
    fn read_at(&self, _buf: &mut [u8], _off: u64) -> std::io::Result<usize> {
        Err(std::io::Error::other("positional reads unavailable"))
    }
}

/// What the read rules ask of a source.
pub(super) trait Source {
    type At: ReadAt + Sync;
    /// Its positioned reads, when it gives them.
    fn at(&self) -> Option<&Self::At>;
    /// Its size when it is known without asking the system.
    fn known_size(&self) -> Option<u64> {
        None
    }
    /// Its size, asked of the system when it is not known.
    fn size(&self) -> Option<u64> {
        self.known_size()
    }
    /// When it was opened: a small source that took long to read came from the disk.
    fn opened(&self) -> Option<Instant> {
        None
    }
    /// Its bytes come out of a decompressor, so one line may be gigabytes.
    fn expands(&self) -> bool {
        false
    }
    /// Search it as one stream from its start.
    fn stream<K: Sink>(&mut self, m: &AnyMatcher, s: &mut Searcher, sink: K) -> Result<(), K::Error>;
}

/// A file on disk.
pub(super) struct Disk {
    file: File,
    size: Option<u64>,
    positioned: bool,
    opened: Instant,
}

impl Disk {
    /// `size`: the walk's, when it has one. `positioned`: reads at an offset see the whole file,
    /// which they do not on a pseudo filesystem.
    pub(super) fn open(path: &Path, size: Option<u64>, positioned: bool) -> std::io::Result<Disk> {
        let opened = Instant::now();
        Ok(Disk { file: File::open(path)?, size, positioned, opened })
    }
}

impl Source for Disk {
    type At = File;
    fn at(&self) -> Option<&File> {
        self.positioned.then_some(&self.file)
    }
    fn known_size(&self) -> Option<u64> {
        self.size
    }
    fn size(&self) -> Option<u64> {
        self.size.or_else(|| self.file.metadata().ok().map(|m| m.len()))
    }
    fn opened(&self) -> Option<Instant> {
        Some(self.opened)
    }
    fn stream<K: Sink>(&mut self, m: &AnyMatcher, s: &mut Searcher, sink: K) -> Result<(), K::Error> {
        // a positioned read on Windows moves the file's cursor, and this search reads from it
        #[cfg(windows)]
        let _ = std::io::Seek::seek(&mut &self.file, std::io::SeekFrom::Start(0));
        m.search_file(s, &self.file, sink)
    }
}

/// Text held in memory.
#[derive(Clone, Copy)]
pub(super) struct Bytes<'b>(pub &'b [u8]);

impl ReadAt for Bytes<'_> {
    fn read_at(&self, buf: &mut [u8], off: u64) -> std::io::Result<usize> {
        let rest = usize::try_from(off).ok().and_then(|o| self.0.get(o..)).unwrap_or_default();
        let n = rest.len().min(buf.len());
        buf[..n].copy_from_slice(&rest[..n]);
        Ok(n)
    }
}

impl Source for Bytes<'_> {
    type At = Self;
    fn at(&self) -> Option<&Self> {
        Some(self)
    }
    fn known_size(&self) -> Option<u64> {
        Some(self.0.len() as u64)
    }
    fn stream<K: Sink>(&mut self, m: &AnyMatcher, s: &mut Searcher, sink: K) -> Result<(), K::Error> {
        m.search_reader(s, self.0, sink)
    }
}

/// The positioned reads of a source that has none.
pub(super) enum NoReads {}

impl ReadAt for NoReads {
    fn read_at(&self, _buf: &mut [u8], _off: u64) -> std::io::Result<usize> {
        match *self {}
    }
}

/// Standard input.
pub(super) struct Stdin;

impl Source for Stdin {
    type At = NoReads;
    fn at(&self) -> Option<&NoReads> {
        None
    }
    fn stream<K: Sink>(&mut self, m: &AnyMatcher, s: &mut Searcher, sink: K) -> Result<(), K::Error> {
        m.search_reader(s, std::io::stdin().lock(), sink)
    }
}

/// A member of an archive, or a decompressed file.
pub(super) struct Member<'r>(pub &'r mut dyn Read);

impl Source for Member<'_> {
    type At = NoReads;
    fn at(&self) -> Option<&NoReads> {
        None
    }
    fn expands(&self) -> bool {
        true
    }
    fn stream<K: Sink>(&mut self, m: &AnyMatcher, s: &mut Searcher, sink: K) -> Result<(), K::Error> {
        m.search_reader(s, &mut *self.0, sink)
    }
}

/// What one search thread keeps from source to source: its searchers and the buffer small files are
/// read into (a new zeroed buffer per file cost about 4% of the CPU of a Linux-tree search on Linux).
pub(super) struct FileWorker {
    searcher: Searcher,
    /// for files named on the command line, made on the first one
    named: Option<Searcher>,
    /// for the members of one archive, made on its first member
    pub(super) member: Option<Searcher>,
    pub(super) small: Vec<u8>,
    /// the plain output of a file before it is written
    out: Vec<u8>,
}

pub(super) fn file_worker(q: &Query) -> FileWorker {
    FileWorker { searcher: make_searcher(q, BinaryDetection::quit(0), None, true), named: None, member: None, small: Vec::new(), out: Vec::new() }
}

/// `heap`: the most bytes the searcher may hold, a line and its context (all of the input with -U).
/// `bom`: a byte-order mark at the start is transcoded, which only the start of a stream has.
pub(super) fn make_searcher(q: &Query, binary: BinaryDetection, heap: Option<usize>, bom: bool) -> Searcher {
    SearcherBuilder::new()
        .binary_detection(binary)
        .bom_sniffing(bom)
        .heap_limit(heap)
        .line_number(q.report == Report::Lines) // line numbers cost a pass over the buffer
        .multi_line(q.pattern.multiline)
        .before_context(q.before)
        .after_context(q.after)
        .invert_match(q.invert)
        .max_matches(q.max_count)
        .build()
}

/// Files up to this size are read with one call (`first`) instead of reading until a zero-length
/// read; within it the searcher's binary check covers the whole file.
pub(super) const SMALL_FILE: u64 = 64 << 10;
/// Files up to this size are streamed by a searcher made for the file, larger ones by the
/// thread's. Reading them whole instead cost each thread a buffer the size of the largest such
/// file it met (py-big: 12.6 MB peak resident on 5 threads, 8.2 MB streamed) for 1% fewer
/// instructions at most (py-big and Linux).
const MID_FILE: u64 = 1 << 20;

/// Line-at-a-time searches whose results do not depend on neighbouring lines or on a running count.
/// `-l` stays sequential: it stops at the first match. On one thread a file is never split, but a
/// file of one long line is still read into a buffer of its size (`split`).
fn splittable(o: &Query) -> bool {
    !o.pattern.multiline && o.before == 0 && o.after == 0 && o.max_count.is_none() && o.max_results.is_none() && o.report != Report::Files
}

/// UTF-8 and UTF-16 byte-order marks: only the stream reader transcodes them.
fn starts_with_bom(b: &[u8]) -> bool {
    b.starts_with(&[0xEF, 0xBB, 0xBF]) || b.starts_with(&[0xFF, 0xFE]) || b.starts_with(&[0xFE, 0xFF])
}

/// Search `src`, reported as `rel`, and send what it finds. `named`: a root that is a file, or
/// standard input (`Files::paths_as_given`).
pub(super) fn search<S: Source>(w: &mut FileWorker, r: &Run, src: &mut S, rel: Arc<str>, named: bool) {
    let (o, f, c) = (r.q, r.f, r.c);
    // -U holds the whole member, so a limit would refuse large members that are fine
    let limit = (src.expands() && !o.pattern.multiline).then_some(crate::archive::MAX_LINE);
    let mut searcher = if src.expands() {
        w.member.get_or_insert_with(|| make_searcher(o, BinaryDetection::quit(0), limit, true))
    } else if named {
        w.named.get_or_insert_with(|| make_searcher(o, BinaryDetection::convert(0), None, true))
    } else {
        &mut w.searcher
    };
    let mut fresh = None;
    let mut owned = None;
    let mut small = None;
    if let Some(at) = src.at().filter(|_| splittable(o)) {
        // most files are small: one read of up to SMALL_FILE + 1 bytes takes such a file whole and
        // tells a larger one apart, with no call for the size (a `statx` per file otherwise: 96,000
        // of them on the Linux tree)
        let first = if src.known_size().is_none_or(|n| n <= SMALL_FILE) { first(at, &mut w.small) } else { First::Larger };
        if let (First::Whole(_) | First::Other, Some(opened)) = (&first, src.opened()) {
            c.small_reads.fetch_add(1, Ordering::Relaxed);
            if r.p.slow(opened.elapsed().as_nanos() as u64) {
                c.slow_reads.fetch_add(1, Ordering::Relaxed);
            }
        }
        match first {
            First::Whole(n) => small = Some(n),
            First::Other => {}
            First::Larger => {
                let len = src.size().unwrap_or(0);
                let min = f.split_file_bytes;
                if len >= min {
                    match split(r, at, len, (min / 8).max(1), &rel) {
                        Outcome::Done => return,
                        Outcome::Stream => {}
                        Outcome::Buffer(b) => owned = Some(b),
                    }
                } else if len <= MID_FILE && r.p.range_threads() > 1 {
                    // a searcher of its own, so the thread's keeps the buffer size it had: where a
                    // NUL byte after the first fill stops the output depends on that size. One
                    // thread meets the files in a fixed order and keeps its one searcher
                    searcher = fresh.insert(make_searcher(o, if named { BinaryDetection::convert(0) } else { BinaryDetection::quit(0) }, None, true));
                }
            }
        }
    }
    let whole: Option<&[u8]> = owned.as_deref().or(small.map(|n| &w.small[..n]));
    let mut sink = Collector { convert: named, out: std::mem::take(&mut w.out), ..r.collector(Arc::clone(&rel)) };
    let res = match whole {
        // only the stream reader turns NUL bytes into line breaks
        Some(b) if named && memchr::memchr(0, b).is_some() => r.matcher.search_reader(searcher, b, &mut sink),
        Some(b) => r.matcher.search_slice(searcher, b, &mut sink),
        None => src.stream(r.matcher, searcher, &mut sink),
    };
    match res {
        // grep-searcher's own words for the limit name no line
        Err(e) if limit.is_some() && e.to_string().starts_with("configured allocation limit") => {
            c.failed(format!("{rel}: a line longer than {} MiB; stopped", crate::archive::MAX_LINE >> 20))
        }
        Err(e) => c.failed(format!("{rel}: {e}")),
        Ok(()) => {}
    }
    w.out = report(r, sink, rel, named);
}

/// Bytes `pos..end` of a source, read without moving a shared position.
struct Range<'f, A> {
    at: &'f A,
    pos: u64,
    end: u64,
}

impl<A: ReadAt> Read for Range<'_, A> {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        if self.pos >= self.end {
            return Ok(0);
        }
        let want = buf.len().min((self.end - self.pos) as usize);
        let n = self.at.read_at(&mut buf[..want], self.pos)?;
        self.pos += n as u64;
        Ok(n)
    }
}

/// The start of the first line beginning in `x..x + 64 KiB` (just past a newline), if any: a
/// longer line is left whole inside a bigger range rather than read twice to find its end.
fn line_start<A: ReadAt>(at: &A, x: u64, buf: &mut [u8]) -> std::io::Result<Option<u64>> {
    let n = at.read_at(buf, x - 1)?;
    Ok(memchr::memchr(b'\n', &buf[..n]).map(|i| x + i as u64))
}

/// Newlines in `a..b`; None when the range holds a NUL byte, a read fails or `stop` is set.
fn newlines<A: ReadAt>(at: &A, a: u64, b: u64, buf: &mut [u8], stop: &AtomicBool) -> Option<u64> {
    let mut r = Range { at, pos: a, end: b };
    let mut n = 0u64;
    loop {
        let got = r.read(buf).ok()?;
        if got == 0 {
            return Some(n);
        }
        if stop.load(Ordering::Relaxed) || memchr::memchr(0, &buf[..got]).is_some() {
            stop.store(true, Ordering::Relaxed);
            return None;
        }
        n += memchr::memchr_iter(b'\n', &buf[..got]).count() as u64;
    }
}

pub(super) enum Outcome {
    /// searched and reported
    Done,
    /// nothing reported: search the source as one stream
    Stream,
    /// nothing reported: the source has no line breaks to split at and no NUL byte, so here it is
    /// in one buffer of its exact size (a stream would grow its buffer by doubling, copying each time)
    Buffer(Vec<u8>),
}

/// What one read of a source's first `SMALL_FILE + 1` bytes found.
enum First {
    /// the whole source, this many bytes, in the buffer
    Whole(usize),
    /// more than `SMALL_FILE` bytes
    Larger,
    /// a small source for the stream reader: it starts with a byte-order mark, or the read failed
    Other,
}

/// Reads into `buf`, kept by the thread across files (sized once, never zeroed again).
fn first<A: ReadAt>(at: &A, buf: &mut Vec<u8>) -> First {
    let max = SMALL_FILE as usize;
    if buf.len() <= max {
        *buf = vec![0; max + 1];
    }
    match at.read_at(&mut buf[..max + 1], 0) {
        Ok(n) if n > max => First::Larger,
        Ok(n) if starts_with_bom(&buf[..n]) => First::Other,
        Ok(n) => First::Whole(n),
        Err(_) => First::Other,
    }
}

/// The whole source when it holds no NUL byte (a slice search checks only its start for binary
/// data), no line break but its last byte (lines too long for the probes to see go to the
/// stream, which holds a few times the longest line) and is still `size` bytes long. The threads
/// take 1 MiB pieces in order, so a line break stops them about one line plus a piece each
/// into the source. The time goes to the kernel copying pages into fresh memory, and that work
/// spreads as far as opening files does (100 MB on macOS: 12.6 ms on one thread, 4.0 ms on 5,
/// 6.7 ms on 11).
pub(super) fn whole<A: ReadAt + Sync>(at: &A, size: u64, threads: usize) -> Option<Vec<u8>> {
    const PIECE: usize = 1 << 20;
    let mut buf = vec![0u8; usize::try_from(size).ok()?];
    let stop = AtomicBool::new(false);
    {
        let pieces = std::sync::Mutex::new(buf.chunks_mut(PIECE).enumerate());
        let work = || {
            while !stop.load(Ordering::Relaxed) {
                let Some((i, b)) = pieces.lock().ok().and_then(|mut p| p.next()) else { return };
                if !fill(at, b, (i * PIECE) as u64, size) {
                    stop.store(true, Ordering::Relaxed);
                }
            }
        };
        std::thread::scope(|s| {
            // an empty source has no piece, and clamp panics on a bound below 1
            for _ in 1..threads.clamp(1, size.div_ceil(PIECE as u64).max(1) as usize) {
                s.spawn(work);
            }
            work();
        });
    }
    (!stop.into_inner()).then_some(buf)
}

/// Fills `buf` from `off` in the source; false on a NUL byte, a line break before the source's
/// last byte, a failed read or a shorter source.
fn fill<A: ReadAt>(at: &A, buf: &mut [u8], off: u64, size: u64) -> bool {
    let mut done = 0;
    while done < buf.len() {
        match at.read_at(&mut buf[done..], off + done as u64) {
            Ok(n) if n > 0 => match memchr::memchr2(0, b'\n', &buf[done..done + n]) {
                Some(i) if buf[done + i] == 0 || off + (done + i) as u64 + 1 != size => return false,
                _ => done += n,
            },
            _ => return false,
        }
    }
    true
}

/// `whole`'s source searched for a plain literal when all the output needs is whether the line
/// matches and its text: a first pass reads it through a small buffer per thread, and a
/// matching line is read again as it is written. None when that does not apply; Stream when
/// the source is not of one line after all, with nothing reported.
fn one_line<A: ReadAt + Sync>(r: &Run, at: &A, size: u64, rel: &Arc<str>) -> Option<Outcome> {
    let (o, AnyMatcher::Literal(lit)) = (r.q, r.matcher) else { return None };
    // a shorter line goes to the collector's buffer, which needs it in memory
    if o.invert || !(r.plain.is_some() || o.report == Report::Counts) || size < (1 << 16) + 2 {
        return None;
    }
    #[cfg(test)]
    if tests::NO_ONE_LINE.with(|c| c.get()) {
        return None;
    }
    let Some(found) = literal_in(at, size, &lit.0, r.p.threads()) else { return Some(Outcome::Stream) };
    #[cfg(test)]
    tests::ONE_LINE.with(|n| n.set(n.get() + 1));
    if found {
        let mut end = [0u8; 2];
        let len = match at.read_at(&mut end, size - 2) {
            Ok(2) => match end {
                [b'\r', b'\n'] => size - 2,
                [_, b'\n'] => size - 1,
                _ => size,
            },
            _ => return Some(Outcome::Stream),
        };
        let mut sink = r.collector(Arc::clone(rel));
        if let Err(e) = sink.take_match(b"", Text::At(at, len), Some(1)) {
            r.c.failed(format!("{rel}: {e}"));
        }
        report(r, sink, Arc::clone(rel), false);
    }
    Some(Outcome::Done)
}

/// Whether `finder`'s needle is in a source that holds no NUL byte, no line break but its last
/// byte and is still `size` bytes long; None when it is not such a source or a read failed. The
/// threads take pieces in order, each read with the needle's length less one bytes of the
/// next, so a needle across two pieces is found. 100 MB on macOS, 5 threads: 256 KiB pieces
/// took 5.1 ms and 12.8 ms of CPU, 1 MiB pieces 8.0 and 20.0 (one fresh buffer: 14.5 and 32.2).
/// At most 8 threads: more read no faster, and `-j 64` held 22 MB.
fn literal_in<A: ReadAt + Sync>(at: &A, size: u64, finder: &memchr::memmem::Finder, threads: usize) -> Option<bool> {
    literal_in_pieces(at, size, finder, threads.min(8), 256 << 10)
}

pub(super) fn literal_in_pieces<A: ReadAt + Sync>(at: &A, size: u64, finder: &memchr::memmem::Finder, threads: usize, piece: usize) -> Option<bool> {
    let over = finder.needle().len() - 1;
    let pieces = size.div_ceil(piece as u64);
    let (next, stop, found) = (AtomicU64::new(0), AtomicBool::new(false), AtomicBool::new(false));
    let work = || {
        let mut buf = vec![0u8; piece + over];
        while !stop.load(Ordering::Relaxed) {
            let off = next.fetch_add(1, Ordering::Relaxed) * piece as u64;
            if off >= size {
                return;
            }
            let b = &mut buf[..(size - off).min((piece + over) as u64) as usize];
            if !fill(at, b, off, size) {
                stop.store(true, Ordering::Relaxed);
            } else if !found.load(Ordering::Relaxed) && finder.find(b).is_some() {
                found.store(true, Ordering::Relaxed);
            }
        }
    };
    std::thread::scope(|s| {
        for _ in 1..threads.clamp(1, pieces.max(1) as usize) {
            s.spawn(work);
        }
        work();
    });
    (!stop.into_inner()).then(|| found.into_inner())
}

struct Part {
    out: Vec<u8>,
    hits: Vec<Record>,
    matched: bool,
    count: u64,
    /// the search reached the end of the range
    ok: bool,
}

/// Search a source of `size` bytes as ranges of whole lines, `chunk` bytes or so each, on several
/// threads, and report the results in order exactly as one sequential pass would. A first pass
/// counts the newlines of every range (for the line numbers). Reports nothing when the source
/// must be searched sequentially after all: it starts with a byte-order mark (transcoded as one
/// stream), holds a NUL byte (binary detection), a read failed, or it has no line breaks to split at.
pub(super) fn split<A: ReadAt + Sync>(r: &Run, at: &A, size: u64, chunk: u64, rel: &Arc<str>) -> Outcome {
    let Run { q: o, p, c, stop, tx, plain, .. } = *r;
    let mut head = [0u8; 3];
    match at.read_at(&mut head, 0) {
        Ok(n) if starts_with_bom(&head[..n]) => return Outcome::Stream,
        Ok(_) => {}
        Err(_) => return Outcome::Stream,
    }
    // one thread only asks whether the source has a line break to split at: the stream holds 3^k
    // times 64 KiB for a long line (141.6 MB peak resident for one 100 MB line, 103.9 whole)
    let one = p.range_threads() == 1;
    let mut bounds = vec![0u64];
    let mut probe = vec![0u8; 64 << 10];
    let mut x = chunk;
    while x < size && !(one && bounds.len() > 1) {
        match line_start(at, x, &mut probe) {
            Ok(Some(b)) if b < size => {
                bounds.push(b);
                x = b + chunk;
            }
            Ok(_) => x += chunk,
            Err(_) => return Outcome::Stream,
        }
    }
    bounds.push(size);
    if bounds.len() < 3 {
        if let Some(done) = one_line(r, at, size, rel) {
            return done;
        }
        return whole(at, size, p.threads()).map_or(Outcome::Stream, Outcome::Buffer);
    }
    if one {
        return Outcome::Stream;
    }
    let ranges: Vec<(u64, u64)> = bounds.windows(2).map(|w| (w[0], w[1])).collect();
    let threads = p.range_threads().min(ranges.len());

    let next = AtomicUsize::new(0);
    let failed = AtomicBool::new(false);
    let counted: Vec<Option<Vec<(usize, u64)>>> = std::thread::scope(|s| {
        let hs: Vec<_> = (0..threads)
            .map(|_| {
                s.spawn(|| {
                    // 1 MiB a thread held 15.2 MB peak resident on a 740 MB file (6.9 MB
                    // now), for 0.4% fewer instructions
                    let mut buf = vec![0u8; 256 << 10];
                    let mut mine = Vec::new();
                    loop {
                        let i = next.fetch_add(1, Ordering::Relaxed);
                        let Some(&(a, b)) = ranges.get(i) else { return Some(mine) };
                        mine.push((i, newlines(at, a, b, &mut buf, &failed)?));
                    }
                })
            })
            .collect();
        hs.into_iter().map(|h| h.join().ok().flatten()).collect()
    });
    // a NUL byte (binary handling stays sequential) or a read error: no line numbers to trust
    let Ok(per_thread) = counted.into_iter().map(|w| w.ok_or(())).collect::<Result<Vec<_>, ()>>() else {
        return Outcome::Stream;
    };
    let mut lines = vec![0u64; ranges.len()];
    for (i, n) in per_thread.concat() {
        lines[i] = n;
    }
    let mut bases = Vec::with_capacity(ranges.len());
    let mut acc = 0u64;
    for n in &lines {
        bases.push(acc);
        acc += n;
    }

    // one window of ranges at a time, so the output held back for ordering stays bounded
    let mut matched = false;
    let mut count = 0u64;
    'windows: for (rs, bs) in ranges.chunks(threads).zip(bases.chunks(threads)) {
        let parts: Vec<Part> = std::thread::scope(|s| {
            let hs: Vec<_> = rs.iter().zip(bs).map(|(&(a, b), &base)| s.spawn(move || search_range(r, at, a, b, base, rel))).collect();
            hs.into_iter().map(|h| h.join().unwrap_or(Part { out: Vec::new(), hits: Vec::new(), matched: false, count: 0, ok: false })).collect()
        });
        for part in parts {
            matched |= part.matched;
            count += part.count;
            if let Some(p) = plain {
                p.write(&part.out, false, stop);
            } else {
                let mut hits = part.hits.into_iter().peekable();
                while hits.peek().is_some() {
                    send(c, tx, hits.by_ref().take(512).collect());
                }
            }
            if !part.ok {
                // the source changed after the first pass, or a read failed: what was found so far stands
                c.failed(format!("{rel}: changed while it was searched, or a read failed"));
                break 'windows;
            }
        }
        if let Some(p) = plain {
            p.tick(stop);
        }
        if stop.is_set() {
            break;
        }
    }
    if matched {
        c.files_matched.fetch_add(1, Ordering::Relaxed);
        if o.report == Report::Counts {
            send(c, tx, vec![Record::Count { path: Arc::clone(rel), path_bytes: r.raw.cloned(), count }]);
        }
    }
    Outcome::Done
}

fn search_range<A: ReadAt>(r: &Run, at: &A, a: u64, b: u64, base: u64, rel: &Arc<str>) -> Part {
    let stop = r.stop;
    // its own matcher (its own regex cache pool) and its own searcher, without transcoding: the
    // middle of a source is not the start of a stream
    let matcher = r.matcher.clone();
    let mut searcher = make_searcher(r.q, BinaryDetection::quit(0), None, false);
    // with `hold` the plain text is formatted into `out` and never written to this sink
    let sink_plain = PlainSink::new(Box::new(std::io::sink()));
    let range_run = Run { matcher: &matcher, plain: if r.plain.is_some() { Some(&sink_plain) } else { None }, ..*r };
    // the records wait in `batch` for the range's turn: a bounded channel would wait for a reader
    let mut sink = Collector {
        tx: None,
        max_results: None,
        line_base: base,
        hold: true,
        multiline: false, // never split in multiline mode
        ..range_run.collector(Arc::clone(rel))
    };
    let mut range = Range { at, pos: a, end: b };
    let res = matcher.search_reader(&mut searcher, &mut range, &mut sink);
    sink.flush();
    let ok = res.is_ok() && !sink.binary && (range.pos >= b || stop.is_set());
    Part { out: std::mem::take(&mut sink.out), hits: std::mem::take(&mut sink.batch), matched: sink.matched, count: sink.file_count, ok }
}

//! Keeps every store under `.scrutate/` current: the code index (`index.rs`), the text index
//! (`textindex.rs`), the `tsquery` cache (`tscache.rs`) and the answers `callers` and `callees`
//! keep (`answers.rs`). A caller names what it is doing (a
//! `Writer`, or a read through `Repo`) and what changed (`Changes`); this module decides which
//! stores that touches, when it looks for changes, and what happens when a store is damaged.
//!
//! When each operation looks for changes, and what it keeps current:
//!
//! | Operation | Looks for changes | Keeps current |
//! |---|---|---|
//! | `index` | every file; waits for another writer | code index, text index (built when missing) |
//! | `index --no-text` | every file; waits | code index |
//! | `index --text` | every file; waits | text index (built when missing) |
//! | `grep --index --update` | every file; waits | text index (built when missing) |
//! | `grep --index` | does not look: answers from the last text index build | nothing |
//! | `watch`, `serve --watch` | the files a burst names, else every file; waits | code index, text index when one exists |
//! | `reindex` (MCP, `batch`), bindings `index()` | every file; waits | code index, text index when one exists |
//! | an index command, `batch` | every file before the first operation; never waits | code index |
//! | an MCP tool call, a bindings call, a language server request | every file, at most once per refresh interval of the session; never waits | code index |
//! | an index command a running `serve` answers | every file, in that session, before the operation; never waits (else the command does the work itself) | code index |
//! | any operation on `Repo` | the files its answer cites and its arguments name, one `stat` each | code index |
//! | `serve` and `lsp` start, an `lsp` save | every file; waits | code index |
//! | `tsquery` | its own walk, one `stat` per file against the code index's record | `tsquery` cache |
//! | `callers`, `callees` | as any index command, then one `stat` per file the kept run read | its answers |
//!
//! Recovery: a store found damaged is built again from the sources, once, by the process that
//! found it, which says so on stderr; an operation that met the damage then runs again. The code
//! index's files are deleted first (`Repo::recover`); the text index is rebuilt in place, its
//! manifest swapped last. `grep --index` without `--update` reports a damaged text index instead,
//! since it promises not to walk the tree.
//!
//! Locking: each store has its own writer lock (the code index a SQLite write transaction, the
//! text index `.scrutate/text/lock`, the `tsquery` cache and the kept answers none: their files
//! are written by readers and replaced by rename),
//! and each commits in one step (a transaction; a manifest rename; a file rename), so a reader of
//! one store sees its last commit and never half of one. Writers that keep both indexes take the
//! two locks one after the other, code index first, and never hold both; no answer reads both.
//! The artifact store is a table of the code index and commits with it; the main checkout's
//! index a linked work tree reads is read in read transactions only.
//! Inside one process the repositories of one root that `Repo::another` opened share one more
//! lock, held by every write any of them makes (an update, the scan before a read, the update of
//! the files an answer cites, a rebuild), so they write one at a time and a rebuild one of them
//! makes is not made again by the next; their reads take no lock and run side by side.

use std::path::{Path, PathBuf};
use std::sync::atomic::AtomicBool;
use std::sync::{Arc, Mutex, MutexGuard};

use anyhow::Result;

use crate::files::{self, Found};
use crate::index::{self, UpdateStats};
use crate::models::ModelSet;
use crate::ops;
use crate::search::Searcher;
use crate::textindex::{self, TextStats};

/// What changed since the stores were last brought up to date.
#[derive(Clone, Debug, PartialEq)]
pub enum Changes {
    /// any file of the tree: walk it
    All,
    /// these files alone (a watch burst that named files only)
    Named(Named),
}

/// Files relative to the root, as each index's walk lists them in their directories; a file that
/// is gone is in both.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Named {
    pub code: Vec<String>,
    pub text: Vec<String>,
}

/// An operation that writes the stores (the rows of the table above that keep more than the code
/// index before a read).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Writer {
    /// `scrutate index`
    Index,
    /// `scrutate index --no-text`
    IndexCode,
    /// `scrutate index --text`
    IndexText,
    /// `grep --index --update`
    GrepUpdate,
    /// a watch burst, `scrutate watch` or `serve --watch`
    Watch,
    /// MCP and `batch` `reindex`, bindings `index()`
    Reindex,
}

impl Writer {
    fn code(self) -> bool {
        !matches!(self, Writer::IndexText | Writer::GrepUpdate)
    }

    /// The one place that decides whether the text index is kept: `index` (unless `--no-text`) and
    /// `grep --index --update` build it, the other writers keep one that exists and never make one.
    fn text(self, root: &Path) -> bool {
        match self {
            Writer::IndexCode => false,
            Writer::Index | Writer::IndexText | Writer::GrepUpdate => true,
            Writer::Watch | Writer::Reindex => textindex::exists(root),
        }
    }

    /// Progress lines on a terminal: the `index` command's alone.
    fn progress(self) -> bool {
        matches!(self, Writer::Index | Writer::IndexCode | Writer::IndexText) && std::io::IsTerminal::is_terminal(&std::io::stderr())
    }
}

/// What an update did, store by store; None for a store it did not keep.
#[derive(Debug, Default)]
pub struct Updated {
    pub code: Option<UpdateStats>,
    pub text: Option<TextStats>,
}

/// Bring the stores `w` keeps up to date with every file of the tree at `root`. The code index is
/// opened only when `w` keeps it; with `force` every file is read again, and a code index of a
/// newer scrutate that this one cannot read is replaced.
pub fn update(root: &Path, w: Writer, force: bool) -> Result<Updated> {
    if w.code() {
        let mut repo = Repo::open_to_update(root, force)?;
        return repo.update_stores(w, &Changes::All, force);
    }
    let root = std::fs::canonicalize(root).unwrap_or_else(|_| root.to_path_buf());
    Ok(Updated { code: None, text: Some(update_text(&root, &Changes::All, force, w.progress(), None)?) })
}

/// The text index brought up to date, from what a look found when one did; a damaged one is
/// built again.
fn update_text(root: &Path, changes: &Changes, force: bool, progress: bool, found: Option<&[Found]>) -> Result<TextStats> {
    let r = match (changes, found) {
        (Changes::Named(n), _) if !force => textindex::update_paths(root, &n.text),
        (_, Some(found)) => textindex::update_found(root, force, progress, found),
        _ => textindex::update(root, force, progress),
    };
    match r {
        Err(e) if e.is::<textindex::Damaged>() => {
            eprintln!("[scrutate] text index damaged ({e:#}); rebuilding");
            textindex::update(root, true, progress)
        }
        r => r,
    }
}

/// An open repository: the searcher on its code index, which it derefs to, and the stores kept
/// current around it.
pub struct Repo {
    /// `None` while a damaged index is being replaced, and after a rebuild that could not reopen it
    searcher: Option<Searcher>,
    root: PathBuf,
    /// the last refresh failed and stderr said why
    stale: bool,
    /// an update of the index went through since `take_updated` was last asked
    updated: bool,
    models: Arc<ModelSet>,
    /// held by every write this repository makes; shared with the ones `another` opened
    writer: Arc<Mutex<()>>,
}

/// The writer lock, also after a panic in a write that held it: the stores commit whole or not at all.
fn hold(writer: &Mutex<()>) -> MutexGuard<'_, ()> {
    writer.lock().unwrap_or_else(|p| p.into_inner())
}

impl Repo {
    /// Open (or create) the index of `root`, without updating it.
    pub fn open(root: &Path) -> Result<Repo> {
        Ok(Repo::around(crate::open(root)?, Arc::default()))
    }

    fn around(searcher: Searcher, writer: Arc<Mutex<()>>) -> Repo {
        let (root, models) = (searcher.ix.root.clone(), Arc::clone(&searcher.ix.models));
        Repo { root, searcher: Some(searcher), stale: false, updated: false, models, writer }
    }

    /// Another open repository on the same index, to read beside this one: a connection of its
    /// own, the same model set, and this one's writer lock.
    pub fn another(&self) -> Result<Repo> {
        let ix = match &self.searcher {
            Some(s) => s.ix.another()?,
            None => index::Index::open(&self.root, Arc::clone(&self.models))?,
        };
        Ok(Repo::around(Searcher::new(ix), Arc::clone(&self.writer)))
    }

    /// `open` for an update; with `force`, an index of a newer scrutate that this one cannot read
    /// is deleted, to be built again by this one.
    pub fn open_to_update(root: &Path, force: bool) -> Result<Repo> {
        match Repo::open(root) {
            Err(e) if force && e.is::<index::Newer>() => {
                index::wipe_index(root);
                Repo::open(root)
            }
            r => r,
        }
    }

    /// The lock every write of this repository holds, shared with the ones `another` opened.
    pub fn writer(&self) -> Arc<Mutex<()>> {
        Arc::clone(&self.writer)
    }

    pub fn into_searcher(self) -> Searcher {
        self.searcher.expect("the index was not reopened after a rebuild")
    }

    /// Whether the last refresh could not update the index, so answers come from it as it was.
    pub fn is_stale(&self) -> bool {
        self.stale
    }

    /// Whether an update of the index went through since this was last asked.
    pub fn take_updated(&mut self) -> bool {
        std::mem::take(&mut self.updated)
    }

    /// The cancel flag of the next operation; nothing to set while the index is closed.
    pub fn set_cancel(&mut self, cancel: Arc<AtomicBool>) {
        if let Some(s) = &mut self.searcher {
            // an update the operation runs (a reindex, the scan before a read) stops at its next batch
            s.ix.cancel = Arc::clone(&cancel);
            s.cancel = cancel;
        }
    }

    /// An index a failed rebuild left closed is opened and built again before anything reads it.
    /// An index a newer scrutate took over since it was opened, in a form this one cannot read,
    /// is an error for every operation until the process is restarted with that scrutate, or
    /// `index --force` builds a new database in its place.
    fn reopened(&mut self) -> Result<()> {
        match &mut self.searcher {
            None => {
                self.reopen(false)?;
            }
            Some(s) => {
                s.ix.reopen_if_replaced()?;
                if let Some(n) = s.ix.newer().filter(|n| !n.readable) {
                    return Err(n.into());
                }
            }
        }
        Ok(())
    }

    /// Bring the code index up to date with every file, as a read that waits for another writer
    /// does (`serve` and `lsp` start).
    pub fn update(&mut self, force: bool) -> Result<UpdateStats> {
        self.update_code(&Changes::All, force, false, false).map(|(st, _)| st)
    }

    /// The code index brought up to date with `changes`; a damaged one is built again. With
    /// `text`, a look at every file finds the text index's files too, and comes back with them.
    fn update_code(&mut self, changes: &Changes, force: bool, progress: bool, text: bool) -> Result<(UpdateStats, Option<Vec<Found>>)> {
        let writer = Arc::clone(&self.writer);
        let _w = hold(&writer);
        self.reopened()?;
        self.ix.progress |= progress;
        let mut found = None;
        let r = match changes {
            Changes::Named(n) if !force => self.ix.update_paths(&n.code, true),
            _ if text => {
                let f = found.insert(files::look(&self.root, true)?);
                self.ix.update_found(force, f)
            }
            _ => self.ix.update(force),
        };
        let r = match r {
            Err(e) if index::error_is_corruption(&e) => self.rebuild(&e),
            other => other,
        };
        self.updated |= r.is_ok();
        r.map(|st| (st, found))
    }

    /// Bring the stores `w` keeps up to date with `changes`: the code index first, then the text
    /// index, each under its own writer lock. When both look at every file, one walk and one
    /// `stat` per file serve both.
    pub fn update_stores(&mut self, w: Writer, changes: &Changes, force: bool) -> Result<Updated> {
        let text = w.text(&self.root);
        let (code, found) = match w.code() {
            true => self.update_code(changes, force, w.progress(), text).map(|(st, f)| (Some(st), f))?,
            false => (None, None),
        };
        let text = if text { Some(update_text(&self.root, changes, force, w.progress(), found.as_deref())?) } else { None };
        Ok(Updated { code, text })
    }

    /// `update_stores` for a `reindex` that stops between batches of files once `cancel` is set,
    /// and then leaves the code index as it was.
    // shortcut: a rebuild after damage and the text index do not see the flag, give them the flag if that matters
    pub fn update_until(&mut self, force: bool, cancel: Arc<AtomicBool>) -> Result<Updated> {
        self.reopened()?;
        self.ix.cancel = cancel;
        let r = self.update_stores(Writer::Reindex, &Changes::All, force);
        if let Some(s) = &mut self.searcher {
            s.ix.cancel = Default::default();
        }
        r
    }

    /// `update` before a read, unless the index was checked less than `min_interval` seconds
    /// ago. When it cannot run (another process holds the write lock, the index directory is
    /// read-only) the read answers from the last committed index, and stderr says why once. A
    /// lock held while the committed index has no file is a first build: `index::BeingBuilt`.
    pub fn refresh(&mut self, min_interval: f64) -> Result<Option<UpdateStats>> {
        let writer = Arc::clone(&self.writer);
        let _w = hold(&writer);
        self.reopened()?;
        match self.ix.refresh_or_fail(min_interval) {
            Err(e) if index::error_is_corruption(&e) => self.rebuild(&e).map(Some),
            Err(e) if e.is::<index::Busy>() && !self.ix.has_files()? => Err(index::BeingBuilt.into()),
            Err(e) if e.is::<index::Newer>() => Err(e),
            Err(e) => {
                if !self.stale {
                    eprintln!("[scrutate] index not updated ({e:#}); answering from it as it is");
                    self.stale = true;
                }
                Ok(None)
            }
            Ok(st) => {
                self.stale &= st.is_none();
                self.updated |= st.is_some();
                Ok(st)
            }
        }
    }

    /// Run one operation on an index refreshed as `refresh` does (operations that do not read
    /// the index skip that). A `reindex` keeps the text index too, when there is one.
    pub fn run(&mut self, op: &ops::Op, min_interval: f64) -> Result<ops::Answer> {
        if op.reads_index() {
            self.refresh(min_interval)?;
        }
        self.run_as_is(op)
    }

    /// Run one operation on the index without a scan of the tree. The files the answer cites
    /// (and the ones its arguments name) are checked against the index, one `stat` each: when
    /// one changed or is gone, or a named one is new and a scan would index it, those files
    /// alone are updated and the answer computed again, once. A file no answer cites or names
    /// waits for the next scan. A damaged database is rebuilt and the operation run again. A
    /// `reindex` brings every store up to date (`Writer::Reindex`).
    pub fn run_as_is(&mut self, op: &ops::Op) -> Result<ops::Answer> {
        if let ops::Op::Reindex { force } = op {
            let up = self.update_stores(Writer::Reindex, &Changes::All, *force)?;
            return Ok(ops::Answer::Reindexed(up.code.unwrap_or_default()));
        }
        let first = self.recovering(|s| ops::run(s, op));
        if self.searcher.is_none() {
            return first;
        }
        let named = op.named_paths();
        let mut paths = named.clone();
        if let Ok(a) = &first {
            paths.extend(a.cited().into_iter().map(str::to_string));
        }
        let paths: Vec<&str> = paths.iter().map(String::as_str).collect();
        let stale = match self.ix.stale(&paths) {
            Ok(mut s) => {
                s.extend(self.ix.unindexed(&named));
                s
            }
            Err(_) => return first,
        };
        if stale.is_empty() {
            return first;
        }
        let updated = {
            let writer = Arc::clone(&self.writer);
            let _w = hold(&writer);
            match self.ix.update_paths(&stale, false) {
                Err(e) if index::error_is_corruption(&e) => self.rebuild_unless_rebuilt(&e).map(|_| true),
                // another writer holds the lock, or the index cannot be written: answer as it is
                r => Ok(r.is_ok()),
            }
        };
        match updated {
            Ok(true) => self.recovering(|s| ops::run(s, op)),
            Ok(false) => first,
            Err(e) => Err(e),
        }
    }

    /// Run `f` on the searcher; when it meets a damaged code index, the index is built again and
    /// `f` runs once more.
    pub fn recovering<T>(&mut self, mut f: impl FnMut(&mut Searcher) -> Result<T>) -> Result<T> {
        {
            // a closed index is built again before the read: a write
            let writer = Arc::clone(&self.writer);
            let _w = self.searcher.is_none().then(|| hold(&writer));
            self.reopened()?;
        }
        match f(self) {
            Err(e) if index::error_is_corruption(&e) => {
                let writer = Arc::clone(&self.writer);
                let w = hold(&writer);
                self.rebuild_unless_rebuilt(&e)?;
                drop(w);
                f(self)
            }
            other => other,
        }
    }

    /// The recovery of a damaged code index: its files are deleted (the index is a cache, the
    /// sources are the truth) and it is built again from every file.
    pub fn recover(&mut self, why: &anyhow::Error) -> Result<UpdateStats> {
        let writer = Arc::clone(&self.writer);
        let _w = hold(&writer);
        self.rebuild(why)
    }

    /// `rebuild`, unless a repository sharing this one's writer lock built the index again since
    /// this one opened it: then this one opens the new index. Called with the writer lock held.
    fn rebuild_unless_rebuilt(&mut self, why: &anyhow::Error) -> Result<()> {
        if let Some(s) = &mut self.searcher {
            let before = s.ix.db_id();
            if before.is_some() && s.ix.reopen_if_replaced().is_ok() && s.ix.db_id() != before {
                return Ok(());
            }
        }
        self.rebuild(why).map(|_| ())
    }

    /// `recover` with the writer lock already held.
    fn rebuild(&mut self, why: &anyhow::Error) -> Result<UpdateStats> {
        eprintln!("[scrutate] index damaged ({why:#}); rebuilding");
        let progress = self.searcher.as_ref().is_some_and(|s| s.ix.progress);
        self.searcher = None; // the database is closed before its files are deleted
        let gone = index::wipe_index(&self.root);
        let mut s = Searcher::new(index::Index::open(&self.root, Arc::clone(&self.models))?);
        if !gone {
            // another handle holds the files (Windows does not delete an open file): no old row or
            // segment may answer, so the database is emptied where it is
            s.ix.clear_in_place()?;
        }
        s.ix.progress = progress;
        let st = s.ix.update(true);
        self.searcher = Some(s);
        st
    }

    fn reopen(&mut self, progress: bool) -> Result<UpdateStats> {
        let mut s = Searcher::new(index::Index::open(&self.root, Arc::clone(&self.models))?);
        s.ix.progress = progress;
        let st = s.ix.update(true);
        self.searcher = Some(s);
        st
    }
}

impl std::ops::Deref for Repo {
    type Target = Searcher;
    fn deref(&self) -> &Searcher {
        self.searcher.as_ref().expect("the index was not reopened after a rebuild")
    }
}

impl std::ops::DerefMut for Repo {
    fn deref_mut(&mut self) -> &mut Searcher {
        self.searcher.as_mut().expect("the index was not reopened after a rebuild")
    }
}

/// The files a search of the repository at `root` reads in place of the walk `walk` (one
/// `files::repository_files` gave, perhaps under a directory and with globs that exclude), when
/// the text index can say which of them hold no match: of the files a look made now finds there,
/// those the text index holds as they are now and that can match, and every other one. None
/// when the walk must run: no text index, a pattern its trigrams do not narrow, a glob that brings
/// files in, a scope that is no directory of the tree, a name that is not UTF-8.
pub fn grep_files(ix: &index::Index, q: &crate::instant::Query, walk: &crate::instant::Files) -> Option<crate::instant::Files> {
    use crate::instant::Paths;
    let Paths::Walk(roots) = &walk.paths else { return None };
    let plain = walk.hidden && !walk.no_ignore && !walk.follow_links && walk.max_filesize.is_none() && walk.max_depth.is_none();
    let plain = plain && walk.types.is_empty() && walk.scoped_globs.is_none() && !walk.search_zip && walk.globs.iter().all(|g| g.starts_with('!'));
    let ([at], true) = (&roots[..], plain) else { return None };
    let under = match walk.paths_as_given {
        false if *at == ix.root => String::new(),
        // a directory named as it is, so the walk's names and these agree
        true => {
            let rel = at.strip_prefix(&ix.root).ok()?;
            let normal = rel.components().all(|c| matches!(c, std::path::Component::Normal(_)) && c.as_os_str().to_str().is_some());
            if !normal || rel.as_os_str().is_empty() || std::fs::canonicalize(at).ok()? != *at {
                return None;
            }
            format!("{}/", slashed_rel(rel))
        }
        false => return None,
    };
    let cond = textindex::query_for(q).ok().filter(|c| *c != textindex::Q::All)?;
    let ti = textindex::TextIndex::open(&ix.root).ok()??;
    // a look of this call's own, so a file written just before it is read (a kept look missed it)
    let found = files::look(&ix.root, false).ok()?;
    if found.iter().any(|f| f.repo && f.lossy) {
        return None;
    }
    let mut there = found.iter().filter(|f| f.repo && f.path.starts_with(under.as_str())).map(|f| (f.path.as_str(), f.stat)).peekable();
    // a directory the look did not enter is searched as the walk searches it
    there.peek()?;
    let read = ti.to_read(&cond, q.pattern.multiline, there).ok()?;
    // named from the directory searched, as its walk names them
    let files = read.into_iter().map(|p| p[under.len()..].to_string()).collect();
    Some(crate::instant::Files { paths: Paths::List { root: at.clone(), files }, paths_as_given: false, ..walk.clone() })
}

fn slashed_rel(rel: &Path) -> String {
    rel.components().map(|c| c.as_os_str().to_string_lossy()).collect::<Vec<_>>().join("/")
}

/// The code index's record of each file it holds, for the `tsquery` cache: the stat and content
/// hash by path from the root. Empty when there is no code index: this never creates one.
pub fn recorded(root: &Path) -> std::collections::HashMap<String, (index::Stat, String)> {
    index::recorded(root)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_rebuild_that_could_not_reopen_the_index_is_an_error_until_it_can() {
        let root = std::env::temp_dir().join(format!("scrutate_reopen_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let mut repo = Repo { searcher: None, root: root.clone(), stale: false, updated: false, models: ModelSet::from_env(), writer: Arc::default() };
        let op = ops::Op::Symbol { name: "f".into(), limit: 5 };
        repo.set_cancel(Arc::default());
        assert!(repo.update(false).is_err());
        assert!(repo.refresh(0.0).is_err());
        assert!(repo.run(&op, 0.0).is_err());
        assert!(repo.run_as_is(&op).is_err());
        std::fs::create_dir_all(&root).unwrap();
        std::fs::write(root.join("a.py"), "def f():\n    return 1\n").unwrap();
        assert!(matches!(repo.run_as_is(&op), Ok(ops::Answer::Hits { ref hits, .. }) if hits.len() == 1));
        drop(repo);
        let _ = std::fs::remove_dir_all(&root);
    }

    /// The grep Operation's answer through `repo` (which reads the text index when there is one)
    /// and through a walk (the text index set aside), as text and JSON.
    fn both_ways(repo: &mut Repo, op: &ops::Op) -> (String, String) {
        let shown = |a: Result<ops::Answer>| a.map(|a| (a.text(), a.json().to_string())).unwrap_or_else(|e| (format!("{e:#}"), String::new()));
        let a = shown(repo.run(op, 0.0));
        let (dir, aside) = (textindex::dir_of(&repo.root), repo.root.join(".scrutate/text.aside"));
        let had = dir.exists();
        if had {
            std::fs::rename(&dir, &aside).unwrap();
        }
        let walked = shown(repo.run_as_is(op));
        if had {
            std::fs::rename(&aside, &dir).unwrap();
        }
        assert_eq!(a, walked);
        a
    }

    #[test]
    fn the_grep_operation_reads_the_text_index_for_the_files_it_holds_as_they_are_and_answers_as_the_walk() {
        use crate::instant::{Case, Mode, Pattern};
        let root = std::env::temp_dir().join(format!("scrutate_grep_ti_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let put = |p: &str, t: &str| {
            std::fs::create_dir_all(root.join(p).parent().unwrap()).unwrap();
            std::fs::write(root.join(p), t).unwrap();
        };
        put(".git/HEAD", "ref: refs/heads/main\n");
        put(".gitignore", "*.log\n");
        for i in 0..40 {
            put(&format!("src/m{i:02}.py"), &format!("def fn_{i}():\n    return {i}\n"));
        }
        put("src/rare.py", "def needle_token():\n    return 1\n\nclass Holder:\n    def go(self):\n        return needle_token()\n");
        put("lib/other.rs", "fn needle_token() {}\nfn main() { needle_token(); }\n");
        put(".github/ci.yml", "run: needle_token\n");
        put("node_modules/x/i.js", "needle_token\n");
        put("data.bin", "needle_token\0\x01\x02needle_token\n");
        put("notes.log", "needle_token\n");
        update(&root, Writer::Index, false).unwrap();
        let mut repo = Repo::open(&root).unwrap();
        let grep = |text: &str, mode: Mode, case: Case, word: bool, path: Option<&str>, globs: &[&str]| ops::Op::Grep {
            pattern: Pattern { text: text.into(), mode, case, word, ..Pattern::default() },
            scope: ops::Scope { path: path.map(String::from), globs: globs.iter().map(|g| g.to_string()).collect() },
            max_results: 1000,
        };
        let cases = |repo: &mut Repo| {
            let mut out = Vec::new();
            for (text, mode) in [
                ("needle_token", Mode::Literal),
                ("needle_[a-z]+", Mode::Regex),
                ("needleToken", Mode::Identifier),
                ("needle_tokan", Mode::Fuzzy { max_edits: 1 }),
                ("fn_3", Mode::Regex),
                ("ab", Mode::Literal),
            ] {
                for case in [Case::Sensitive, Case::Insensitive, Case::Smart] {
                    for (path, globs) in [
                        (None, &[][..]),
                        (Some("src"), &[][..]),
                        (Some("src/"), &["!rare.py"][..]),
                        (None, &["!*.rs"][..]),
                        (None, &["*.rs"][..]),
                        (Some("lib/other.rs"), &[][..]),
                    ] {
                        out.push(both_ways(repo, &grep(text, mode, case, false, path, globs)));
                    }
                    out.push(both_ways(repo, &grep(text, mode, case, true, None, &[])));
                }
            }
            out
        };
        let fresh = cases(&mut repo);
        assert!(fresh[0].0.contains("src/rare.py") && fresh[0].0.contains(".github/ci.yml") && !fresh[0].0.contains("node_modules"), "{}", fresh[0].0);
        let q = crate::instant::Query { pattern: Pattern { text: "needle_token".into(), ..Pattern::default() }, ..Default::default() };
        let narrowed = grep_files(&repo.ix, &q, &crate::files::repository_files(&repo.root)).expect("the text index narrows a rare word");
        let crate::instant::Paths::List { files: read, .. } = narrowed.paths else { panic!("a list") };
        // the hidden files are not in the text index: they are read directly
        assert_eq!(read, [".github/ci.yml", ".gitignore", "data.bin", "lib/other.rs", "src/rare.py"]);
        // a new file, an edit, an edit that keeps size and time, a removal and a rename since the last build
        put("src/added.py", "x = needle_token\n");
        put("src/m01.py", "def fn_1():\n    return needle_token\n");
        // only where a write moves the status change time: Windows has none to see it by
        if cfg!(unix) {
            let t = std::fs::metadata(root.join("src/m02.py")).unwrap().modified().unwrap();
            let old = std::fs::read(root.join("src/m02.py")).unwrap().len();
            put("src/m02.py", &format!("{:<w$}\n", "needle_token", w = old - 1));
            std::fs::File::options().write(true).open(root.join("src/m02.py")).unwrap().set_modified(t).unwrap();
        }
        std::fs::remove_file(root.join("src/m03.py")).unwrap();
        std::fs::rename(root.join("src/m04.py"), root.join("src/m44.py")).unwrap();
        let stale = cases(&mut repo);
        assert!(stale[0].0.contains("src/added.py") && stale[0].0.contains("src/m01.py"), "{}", stale[0].0);
        assert_ne!(fresh, stale);
        std::fs::remove_dir_all(textindex::dir_of(&root)).unwrap();
        assert_eq!(cases(&mut repo), stale, "without a text index the walk answers");
        assert!(!textindex::exists(&root), "and no text index is built");
        drop(repo);
        let _ = std::fs::remove_dir_all(&root);
    }
}

//! Tokenization shared by indexing and querying.
//!
//! Everything is lowercase, identifier-aware (camelCase / snake_case are split) and stemmed with the
//! Snowball English stemmer, so `refreshTokens`, `refresh_token` and "refreshing tokens" all meet at
//! `refresh`, `token`. Compound identifiers also emit one joined token (`sendrequest`).

use std::cell::RefCell;
use std::collections::{HashMap, HashSet};
use std::sync::LazyLock;

use regex::Regex;
use rust_stemmers::{Algorithm, Stemmer};
use unicode_normalization::UnicodeNormalization;

const ENGLISH: &str = "a an the of to in on at by for with from as and or nor but so if then than that this
these those it its is are was were be been being am do does did done has have had having not no
yes can could should would will shall may might must i we you he she they them his her our your
their my me us about into onto over under up down out off also very just only more most such
there here when where which who whom whose why how what whatever any all each both either some
other another same own too via per etc eg ie e g";
const CODE: &str = "self cls this super none null nil true false def class import from return pass lambda
yield async await elif else try except finally raise with assert break continue global nonlocal
del var let const function new void typeof undefined public private protected static final
fn func pub mut impl struct enum trait use mod crate self_ int str bool float";
const QUESTION: &str = "find show give get where which implemented implement implementation handled
handle handles handling happens happen code codebase file files function functions method
methods class classes defined define used uses using use look looking search want need
please tell list";

pub static INDEX_STOP: LazyLock<HashSet<&'static str>> = LazyLock::new(|| ENGLISH.split_whitespace().chain(CODE.split_whitespace()).collect());
pub static QUERY_STOP: LazyLock<HashSet<&'static str>> = LazyLock::new(|| {
    let mut s: HashSet<&'static str> = INDEX_STOP.iter().copied().collect();
    s.extend(QUESTION.split_whitespace());
    s
});

/// Maximum identifiers of a body that are indexed / embedded.
pub const BODY_CAP: usize = 2000;

thread_local! {
    static STEMMER: Stemmer = Stemmer::create(Algorithm::English);
    static STEM_CACHE: RefCell<HashMap<String, String>> = RefCell::new(HashMap::new());
    static IDENT_CACHE: RefCell<HashMap<String, (Vec<String>, String)>> = RefCell::new(HashMap::new());
}

/// Free this thread's word caches (an index build fills them with millions of entries).
pub fn clear_caches() {
    STEM_CACHE.with(|c| drop(c.take()));
    IDENT_CACHE.with(|c| drop(c.take()));
}

/// Entries in this thread's word caches.
pub fn cache_len() -> usize {
    STEM_CACHE.with(|c| c.borrow().len()) + IDENT_CACHE.with(|c| c.borrow().len())
}

pub fn stem(w: &str) -> String {
    if let Some(s) = STEM_CACHE.with(|c| c.borrow().get(w).cloned()) {
        return s;
    }
    let s = STEMMER.with(|st| st.stem(w).into_owned());
    STEM_CACHE.with(|c| {
        let mut c = c.borrow_mut();
        if c.len() < 2_000_000 {
            c.insert(w.to_string(), s.clone());
        }
    });
    s
}

/// Words of a text. An all-ASCII text gives `[A-Za-z_][A-Za-z0-9_]*` (like the Python regex). Any
/// other text gives maximal runs of letters, marks, decimal digits and `_` of every script; a run
/// that is all ASCII loses its leading digits, so ASCII words come out as they always did.
pub struct Words<'a> {
    bytes: &'a [u8],
    pos: usize,
    runs: Option<regex::Matches<'static, 'a>>,
}

static RUN: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"[\p{L}\p{M}\p{Nd}_]+").unwrap());

impl<'a> Words<'a> {
    pub fn new(text: &'a str) -> Self {
        let runs = if text.is_ascii() { None } else { Some(RUN.find_iter(text)) };
        Words { bytes: text.as_bytes(), pos: 0, runs }
    }
}

fn is_word_start(b: u8) -> bool {
    b.is_ascii_alphabetic() || b == b'_'
}

fn is_word_char(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

impl<'a> Iterator for Words<'a> {
    type Item = &'a str;

    fn next(&mut self) -> Option<&'a str> {
        if let Some(runs) = &mut self.runs {
            for m in runs.by_ref() {
                let w = m.as_str();
                if !w.is_ascii() {
                    return Some(w);
                }
                let w = w.trim_start_matches(|c: char| c.is_ascii_digit());
                if !w.is_empty() {
                    return Some(w);
                }
            }
            return None;
        }
        let b = self.bytes;
        while self.pos < b.len() && !is_word_start(b[self.pos]) {
            self.pos += 1;
        }
        if self.pos >= b.len() {
            return None;
        }
        let start = self.pos;
        while self.pos < b.len() && is_word_char(b[self.pos]) {
            self.pos += 1;
        }
        // ASCII boundaries are always char boundaries
        Some(unsafe { std::str::from_utf8_unchecked(&b[start..self.pos]) })
    }
}

/// Scripts written without spaces between words: Han, Hiragana, Katakana, and Thai, Lao,
/// Tibetan, Myanmar, Khmer, the Tai scripts, Balinese and Javanese.
fn unspaced(c: char) -> bool {
    matches!(c as u32, 0x0E00..=0x109F | 0x1780..=0x17FF | 0x1950..=0x19DF | 0x1A20..=0x1AAF | 0x1B00..=0x1B7F | 0xA980..=0xA9FF | 0xAA60..=0xAADF | 0x3005..=0x3007 | 0x3040..=0x30FF | 0x31F0..=0x31FF | 0x3400..=0x4DBF | 0x4E00..=0x9FFF | 0xF900..=0xFAFF | 0xFF66..=0xFF9F | 0x20000..=0x323AF)
}

/// Traditional Han character -> simplified form, from Unihan `kSimplifiedVariant` (tools/gen_han_fold.py).
static HAN_FOLD: LazyLock<HashMap<char, char>> = LazyLock::new(|| {
    let pairs: Vec<char> = include_str!("../data/han_fold.txt").lines().filter(|l| !l.starts_with('#')).flat_map(str::chars).collect();
    pairs.as_chunks::<2>().0.iter().map(|&[t, s]| (t, s)).collect()
});

/// Lowercase with the final sigma folded, so a word compares the same in any case.
fn fold(s: &str) -> String {
    s.to_lowercase().replace('ς', "σ")
}

/// Tokens of a word that is not all ASCII: NFC first; runs of unspaced scripts have traditional
/// Han folded to simplified and give overlapping character bigrams (a lone character itself),
/// other `_`-separated parts are one folded token each, and an ASCII part goes through the
/// identifier rules (split, stemmed).
pub fn unicode_tokens(word: &str, out: &mut Vec<String>) {
    let w: Vec<char> = word.nfc().collect();
    let mut i = 0;
    while i < w.len() {
        let u = unspaced(w[i]);
        let mut j = i + 1;
        while j < w.len() && unspaced(w[j]) == u {
            j += 1;
        }
        let seg = &w[i..j];
        if !u {
            let seg: String = seg.iter().collect();
            for part in seg.split('_').filter(|p| !p.is_empty()) {
                if part.is_ascii() {
                    out.extend(ident_tokens(part).0);
                } else {
                    out.push(fold(part));
                }
            }
        } else {
            let seg: Vec<char> = seg.iter().map(|c| HAN_FOLD.get(c).copied().unwrap_or(*c)).collect();
            if seg.len() == 1 {
                out.push(seg[0].to_string());
            } else {
                out.extend(seg.windows(2).map(|p| p.iter().collect::<String>()));
            }
        }
        i = j;
    }
}

/// `parseHTTPResponse_v2` -> ["parse", "http", "response", "v"] (lowercase, unstemmed). This is the
/// Python regex `[A-Z]+(?=[A-Z][a-z])|[A-Z]?[a-z]+|[A-Z]+` applied to every `_`-separated part.
pub fn raw_subwords(ident: &str) -> Vec<String> {
    let mut out = Vec::new();
    for part in ident.split('_') {
        if part.is_empty() {
            continue;
        }
        let b = part.as_bytes();
        let n = b.len();
        let mut i = 0;
        while i < n {
            let c = b[i];
            if c.is_ascii_uppercase() {
                // alternative 1: a run of capitals followed by Capital+lowercase (greedy, backtracking)
                let mut run = i;
                while run < n && b[run].is_ascii_uppercase() {
                    run += 1;
                }
                let mut matched = None;
                let mut l = run - i;
                while l >= 1 {
                    let j = i + l;
                    if j + 1 < n && b[j].is_ascii_uppercase() && b[j + 1].is_ascii_lowercase() {
                        matched = Some(l);
                        break;
                    }
                    l -= 1;
                }
                if let Some(l) = matched {
                    out.push(part[i..i + l].to_ascii_lowercase());
                    i += l;
                    continue;
                }
                // alternative 2: one capital + lowercase run
                if i + 1 < n && b[i + 1].is_ascii_lowercase() {
                    let mut j = i + 1;
                    while j < n && b[j].is_ascii_lowercase() {
                        j += 1;
                    }
                    out.push(part[i..j].to_ascii_lowercase());
                    i = j;
                    continue;
                }
                // alternative 3: the whole run of capitals
                out.push(part[i..run].to_ascii_lowercase());
                i = run;
            } else if c.is_ascii_lowercase() {
                let mut j = i + 1;
                while j < n && b[j].is_ascii_lowercase() {
                    j += 1;
                }
                out.push(part[i..j].to_string());
                i = j;
            } else {
                i += 1; // digits and anything else are skipped
            }
        }
    }
    out
}

/// -> (stemmed subwords without stopwords, joined whole token or "").
pub fn ident_tokens(ident: &str) -> (Vec<String>, String) {
    if let Some(hit) = IDENT_CACHE.with(|c| c.borrow().get(ident).cloned()) {
        return hit;
    }
    let subs = raw_subwords(ident);
    let toks: Vec<String> = subs.iter().filter(|w| w.len() > 1 && !INDEX_STOP.contains(w.as_str())).map(|w| stem(w)).collect();
    let whole = if subs.len() > 1 && !toks.is_empty() { subs.concat() } else { String::new() };
    let hit = (toks, whole);
    IDENT_CACHE.with(|c| {
        let mut c = c.borrow_mut();
        if c.len() < 2_000_000 {
            c.insert(ident.to_string(), hit.clone());
        }
    });
    hit
}

/// -> (stemmed subwords, joined whole identifiers) of a text; `cap` limits the number of words read.
pub fn tokenize2(text: &str, cap: Option<usize>) -> (Vec<String>, Vec<String>) {
    let mut subs = Vec::new();
    let mut wholes = Vec::new();
    let mut n = 0;
    for w in Words::new(text) {
        if w.is_ascii() {
            let (t, whole) = ident_tokens(w);
            subs.extend(t);
            if !whole.is_empty() {
                wholes.push(whole);
            }
        } else {
            unicode_tokens(w, &mut subs);
        }
        n += 1;
        if let Some(c) = cap {
            if n >= c {
                break;
            }
        }
    }
    (subs, wholes)
}

/// Case- and underscore-insensitive key in NFC: `send_request`, `sendRequest` -> `sendrequest`.
pub fn name_key(name: &str) -> String {
    if name.is_ascii() {
        return name.chars().filter(|c| *c != '_').map(|c| c.to_ascii_lowercase()).collect();
    }
    fold(&name.nfc().filter(|c| *c != '_').collect::<String>())
}

const TEST_PARTS: &[&str] = &["test", "tests", "testing", "__tests__", "spec", "specs", "e2e", "fixtures", "mocks"];

pub fn is_test_path(path: &str) -> bool {
    let path = path.replace('\\', "/");
    let low = path.to_lowercase();
    let parts: Vec<&str> = low.split('/').collect();
    let base = parts[parts.len() - 1];
    let (stem, ext) = base.rsplit_once('.').unwrap_or((base, ""));
    // a C# test project is a directory `MyApp.Tests`; with the capital, `MyApp.Latest` is none
    let dirs = path.rsplit_once('/').map_or("", |(d, _)| d);
    let project = dirs.split('/').any(|d| d.ends_with(".Tests") || d.ends_with(".Test"));
    // `button.test.jsx`, `card.spec.ts`: a JavaScript or TypeScript test beside its code
    let script = matches!(ext, "js" | "jsx" | "mjs" | "cjs" | "ts" | "tsx" | "mts" | "cts") && (stem.ends_with(".test") || stem.ends_with(".spec"));
    // `parser_test.rs`, `parser_spec.rb`, `config_test.cc`
    let suffixed = !ext.is_empty() && (stem.ends_with("_test") || stem.ends_with("_spec"));
    // JUnit and its kin name a test class `FooTest` or `FooTests`: with the capital, `Contest.java`
    // is none. The name as written: lower case can have another length (`İ`, the Kelvin sign).
    let written = path.rsplit('/').next().unwrap_or(&path);
    let name = written.rsplit_once('.').map_or(written, |(n, _)| n);
    let class = matches!(ext, "java" | "kt" | "cs" | "swift" | "php") && (name.ends_with("Test") || name.ends_with("Tests"));
    parts[..parts.len() - 1].iter().any(|p| TEST_PARTS.contains(p))
        || project
        || base.starts_with("test_")
        || script
        || suffixed
        || class
        || matches!(base, "conftest.py" | "tests.py")
}

// --- query analysis -------------------------------------------------------------------------

/// Unique stemmed content terms of a query (question words and stopwords removed), in order.
pub fn query_terms(query: &str) -> Vec<String> {
    let mut seen = Vec::new();
    let mut set = HashSet::new();
    for w in Words::new(query) {
        if !w.is_ascii() {
            let mut toks = Vec::new();
            unicode_tokens(w, &mut toks);
            seen.extend(toks.into_iter().filter(|t| set.insert(t.clone())));
            continue;
        }
        for s in raw_subwords(w) {
            if s.len() > 1 && !QUERY_STOP.contains(s.as_str()) {
                let st = stem(&s);
                if set.insert(st.clone()) {
                    seen.push(st);
                }
            }
        }
    }
    seen
}

/// The longest prefix of `s` of at most `n` bytes that ends on a char boundary.
pub fn prefix_bytes(s: &str, n: usize) -> &str {
    if s.len() <= n {
        return s;
    }
    let mut i = n;
    while i > 0 && !s.is_char_boundary(i) {
        i -= 1;
    }
    &s[..i]
}

/// Joined tokens for identifier-like words of the query (`send_request` -> `sendrequest`).
pub fn query_wholes(query: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut set = HashSet::new();
    for w in Words::new(query).filter(|w| w.is_ascii()) {
        let subs = raw_subwords(w);
        if subs.len() > 1 && (w.contains('_') || w.bytes().skip(1).any(|c| c.is_ascii_uppercase())) {
            let j = subs.concat();
            if set.insert(j.clone()) {
                out.push(j);
            }
        }
    }
    out
}

static QUOTED: LazyLock<Regex> = LazyLock::new(|| Regex::new(r#""([^"]+)"|'([^']+)'|`([^`]+)`"#).unwrap());
static QUOTED_ANY: LazyLock<Regex> = LazyLock::new(|| Regex::new(r#""[^"]*"|'[^']*'|`[^`]*`"#).unwrap());
static LIT_WORD: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"[A-Za-z_][\w.]*[\w]").unwrap());

/// Python's `str.isupper()`: at least one cased character and no lowercase ones.
fn py_isupper(s: &str) -> bool {
    let mut cased = false;
    for c in s.chars() {
        if c.is_lowercase() {
            return false;
        }
        if c.is_uppercase() {
            cased = true;
        }
    }
    cased
}

/// Pieces of the query that look like exact code strings: quoted strings and identifier-ish words
/// (snake_case, camelCase, dotted, CONSTANTS).
pub fn literal_candidates(query: &str) -> Vec<String> {
    let mut lits: Vec<String> = Vec::new();
    for m in QUOTED.captures_iter(query) {
        for i in 1..=3 {
            if let Some(g) = m.get(i) {
                lits.push(g.as_str().to_string());
                break;
            }
        }
    }
    let stripped = QUOTED_ANY.replace_all(query, " ");
    for m in LIT_WORD.find_iter(&stripped) {
        let w = m.as_str();
        let tail_upper = w.chars().skip(1).any(|c| c.is_uppercase());
        let any_lower = w.chars().any(|c| c.is_lowercase());
        if w.contains('_') || w.contains('.') || (tail_upper && any_lower) || (py_isupper(w) && w.chars().count() > 2) {
            lits.push(w.to_string());
        }
    }
    let mut seen = HashSet::new();
    lits.retain(|l| seen.insert(l.clone()));
    lits
}

/// Lines as grep-class tools number them: split at `\n`, a `\r` before it dropped, no empty
/// last line for a trailing newline. Form feeds, lone `\r` and Unicode separators are text, so a
/// chunk's line numbers agree with Engine A's and tree-sitter's.
pub fn split_lines(s: &str) -> Vec<&str> {
    s.lines().collect()
}

/// Lowercase words of a query, for snippet highlighting (agent.query_words: len > 2).
pub fn query_words(q: &str) -> Vec<String> {
    Words::new(q).filter(|w| w.chars().count() > 2).map(|w| w.to_lowercase()).collect()
}

