//! Engine B text index: trigram postings over exactly the files Engine A's default walk searches,
//! so `grep --index` reads only the files that can contain a match. Every candidate file is still
//! searched by Engine A's matcher, so the output equals Engine A's output on the indexed snapshot.
//!
//! Layout under `.scrutate/text/`: `manifest.json` names the live segments; a segment directory
//! holds `keys.npy` (sorted u32 trigrams), `ptr.npy` (u64 offsets into `post.bin`), `post.bin`
//! (per document holding the trigram: its number, delta + LEB128, then two mask bytes, a bit for
//! the low three bits of each byte that follows the trigram and a bit for each position of the
//! trigram modulo 8), `docs.npy` (size, mtime, flags and status change time per document),
//! `paths.bin` + `poff.npy` (paths), and `live-<generation>.bin` (which documents are current).
//! Segments are immutable; an update writes new segments and new liveness files, then swaps the
//! manifest.

use std::fs::File;
use std::io::{BufWriter, Write};
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use std::time::Instant;

use anyhow::{anyhow, bail, Context, Result};
use memmap2::Mmap;
use rayon::prelude::*;
use regex_syntax::hir::{Class, Hir, HirKind};

use crate::instant::{self, Files, Mode, Query};
use crate::npy::{self, Npy};

pub const FORMAT: u32 = 3;
/// Numbers per document in `docs.npy`: size, mtime, flags, status change time.
const COLS: usize = 4;
const MAX_SEGMENTS: usize = 4;
/// Postings held in memory before a batch is written as a segment (about 200 MB at the peak).
const BATCH_POSTINGS: usize = 16 << 20;
const MAX_SET: usize = 64;
const MAX_CLASS: u32 = 16;
/// The file has a NUL byte. Line-mode search stops at the first NUL, so trigrams cover only the
/// bytes before it; multi-line search may read the whole file, so such files are always searched.
pub const BINARY: i64 = 1;
/// UTF-16 (Engine A transcodes it) or unreadable when indexed: always searched, Engine A decides.
pub const ALWAYS: i64 = 2;
/// Unreadable when indexed: read again by the next update.
pub const RETRY: i64 = 4;

// ------------------------------------------------------------------------- query extraction
/// A necessary condition on a file's trigrams for the pattern to match somewhere in it.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub enum Q {
    All,
    Tri(u32),
    /// a folded string of 4 bytes or more: its trigrams, at positions that can line up and each
    /// followed by a byte that fits the string's next byte
    Seq(Vec<u8>),
    And(Vec<Q>),
    Or(Vec<Q>),
}

fn and(qs: Vec<Q>) -> Q {
    let mut out = Vec::new();
    for q in qs {
        match q {
            Q::All => {}
            Q::And(v) => out.extend(v),
            q => out.push(q),
        }
    }
    out.sort();
    out.dedup();
    match out.len() {
        0 => Q::All,
        1 => out.pop().unwrap_or(Q::All),
        _ => Q::And(out),
    }
}

fn or(qs: Vec<Q>) -> Q {
    let mut out = Vec::new();
    for q in qs {
        match q {
            Q::All => return Q::All,
            Q::Or(v) => out.extend(v),
            q => out.push(q),
        }
    }
    out.sort();
    out.dedup();
    match out.len() {
        0 => Q::All,
        1 => out.pop().unwrap_or(Q::All),
        _ => Q::Or(out),
    }
}

/// The index folds ASCII case, so queries are built from folded strings.
fn fold(s: &[u8]) -> Vec<u8> {
    s.to_ascii_lowercase()
}

fn string_query(s: &[u8]) -> Q {
    match s.len() {
        0..=2 => Q::All,
        3 => Q::Tri(key(s[0], s[1], s[2])),
        _ => Q::Seq(s.to_vec()),
    }
}

/// Whether a file whose masks for the consecutive trigrams of the folded string `s` are
/// `mask_of(i)` can hold `s`: every trigram present, one position modulo 8 lining all of them up,
/// and each followed by a byte with the low bits of the next byte of `s`.
fn seq_fits(s: &[u8], mask_of: impl Fn(usize) -> Option<u16>) -> bool {
    let mut lined_up = 0xFFu8;
    for i in 0..s.len().saturating_sub(2) {
        let Some(m) = mask_of(i) else { return false };
        let (next, at) = ((m >> 8) as u8, m as u8);
        lined_up &= at.rotate_right((i % 8) as u32);
        if s.get(i + 3).is_some_and(|&b| next & (1 << (b & 7)) == 0) {
            return false;
        }
    }
    lined_up != 0
}

/// Whether `q` accepts a file whose sorted trigram masks are `masks` (as `trigram_masks` gives
/// them): the condition the index evaluates, on one text.
pub fn holds(q: &Q, masks: &[(u32, u16)]) -> bool {
    let find = |t: u32| masks.binary_search_by_key(&t, |m| m.0).ok().map(|i| masks[i].1);
    match q {
        Q::All => true,
        Q::Tri(t) => find(*t).is_some(),
        Q::Seq(s) => seq_fits(s, |i| find(key(s[i], s[i + 1], s[i + 2]))),
        Q::And(v) => v.iter().all(|q| holds(q, masks)),
        Q::Or(v) => v.iter().any(|q| holds(q, masks)),
    }
}

fn set_query(set: &[Vec<u8>]) -> Q {
    or(set.iter().map(|s| string_query(s)).collect())
}

fn key(a: u8, b: u8, c: u8) -> u32 {
    (a.to_ascii_lowercase() as u32) << 16 | (b.to_ascii_lowercase() as u32) << 8 | c.to_ascii_lowercase() as u32
}

/// What is known about the strings a sub-pattern matches: all of them (`exact`, folded, small
/// sets only) or a condition every match satisfies.
struct Info {
    exact: Option<Vec<Vec<u8>>>,
    q: Q,
}

impl Info {
    fn query(&self) -> Q {
        match &self.exact {
            Some(s) => set_query(s),
            None => self.q.clone(),
        }
    }
}

fn exact(mut v: Vec<Vec<u8>>) -> Info {
    v.sort();
    v.dedup();
    Info { exact: Some(v), q: Q::All }
}

fn inexact(q: Q) -> Info {
    Info { exact: None, q }
}

fn cross(a: &[Vec<u8>], b: &[Vec<u8>]) -> Option<Vec<Vec<u8>>> {
    if a.len() * b.len() > MAX_SET {
        return None;
    }
    let mut out = Vec::with_capacity(a.len() * b.len());
    for x in a {
        for y in b {
            let mut s = x.clone();
            s.extend_from_slice(y);
            out.push(s);
        }
    }
    out.sort();
    out.dedup();
    Some(out)
}

fn class_strings(c: &Class) -> Option<Vec<Vec<u8>>> {
    let mut out = Vec::new();
    match c {
        Class::Unicode(u) => {
            let n: u32 = u.ranges().iter().map(|r| r.end() as u32 - r.start() as u32 + 1).sum();
            if n > MAX_CLASS {
                return None;
            }
            for r in u.ranges() {
                for cp in r.start() as u32..=r.end() as u32 {
                    if let Some(ch) = char::from_u32(cp) {
                        out.push(fold(ch.encode_utf8(&mut [0u8; 4]).as_bytes()));
                    }
                }
            }
        }
        Class::Bytes(b) => {
            let n: u32 = b.ranges().iter().map(|r| r.end() as u32 - r.start() as u32 + 1).sum();
            if n > MAX_CLASS {
                return None;
            }
            for r in b.ranges() {
                for x in r.start()..=r.end() {
                    out.push(vec![x.to_ascii_lowercase()]);
                }
            }
        }
    }
    Some(out)
}

fn analyze(h: &Hir) -> Info {
    match h.kind() {
        HirKind::Empty | HirKind::Look(_) => exact(vec![vec![]]),
        HirKind::Literal(l) => exact(vec![fold(&l.0)]),
        HirKind::Class(c) => match class_strings(c) {
            Some(v) if !v.is_empty() => exact(v),
            _ => inexact(Q::All),
        },
        HirKind::Capture(c) => analyze(&c.sub),
        HirKind::Repetition(r) => {
            let sub = analyze(&r.sub);
            if r.min == 0 {
                if r.max == Some(1) {
                    if let Some(mut e) = sub.exact {
                        e.push(Vec::new());
                        if e.len() <= MAX_SET {
                            return exact(e);
                        }
                    }
                }
                return inexact(Q::All);
            }
            if let (Some(e), Some(max)) = (&sub.exact, r.max) {
                if max == r.min && r.min <= 4 {
                    let mut acc = vec![Vec::new()];
                    for _ in 0..r.min {
                        match cross(&acc, e) {
                            Some(x) => acc = x,
                            None => return inexact(sub.query()),
                        }
                    }
                    return exact(acc);
                }
            }
            // every match contains at least one match of the repeated part
            inexact(sub.query())
        }
        HirKind::Concat(cs) => {
            let mut run: Vec<Vec<u8>> = vec![Vec::new()];
            let mut qs = Vec::new();
            let mut all_exact = true;
            for c in cs {
                let i = analyze(c);
                match i.exact {
                    Some(e) => match cross(&run, &e) {
                        Some(x) => run = x,
                        None => {
                            all_exact = false;
                            qs.push(set_query(&run));
                            run = e;
                        }
                    },
                    None => {
                        all_exact = false;
                        qs.push(set_query(&run));
                        qs.push(i.q);
                        run = vec![Vec::new()];
                    }
                }
            }
            if all_exact {
                exact(run)
            } else {
                qs.push(set_query(&run));
                inexact(and(qs))
            }
        }
        HirKind::Alternation(cs) => {
            let infos: Vec<Info> = cs.iter().map(analyze).collect();
            if infos.iter().all(|i| i.exact.is_some()) {
                let u: Vec<Vec<u8>> = infos.iter().flat_map(|i| i.exact.clone().unwrap_or_default()).collect();
                if u.len() <= MAX_SET {
                    return exact(u);
                }
            }
            inexact(or(infos.iter().map(Info::query).collect()))
        }
    }
}

/// The trigram condition for Engine A's query (`Pattern::translate`, as `instant::build_matcher`
/// uses it). Inverted searches can match any file.
pub fn query_for(o: &Query) -> Result<Q> {
    if o.invert {
        return Ok(Q::All);
    }
    let t = o.pattern.translate();
    match o.pattern.mode {
        // k edits leave one of k+1 pieces verbatim (the fuzzy matcher's own prefilter)
        Mode::Fuzzy { max_edits } => {
            // the pieces the matcher itself looks for, so the index never rejects a file it matches
            let pieces = instant::fuzzy_pieces(&t.pattern, max_edits, t.insensitive).unwrap_or_default();
            if pieces.is_empty() || pieces.iter().any(|p| p.len() < 3) {
                return Ok(Q::All);
            }
            return Ok(or(pieces.iter().map(|p| string_query(p)).collect()));
        }
        Mode::Literal | Mode::Identifier | Mode::Regex => {}
        // PCRE2 syntax differs from this parser's in places: no condition, so no file is missed
        Mode::Pcre2 => return Ok(Q::All),
        Mode::FuzzyRegex { .. } => return Ok(Q::All),
    }
    let hir = regex_syntax::ParserBuilder::new()
        .case_insensitive(t.insensitive)
        .multi_line(true)
        .utf8(false)
        .build()
        .parse(&t.pattern)
        .with_context(|| format!("invalid pattern {:?}", o.pattern.text))?;
    Ok(analyze(&hir).query())
}

// ------------------------------------------------------------------------- trigram extraction
/// An open-addressing table from trigram to masks, reused by each thread across files.
struct MaskTable {
    keys: Vec<u32>,
    masks: Vec<u16>,
    used: Vec<u32>,
}

const EMPTY: u32 = u32::MAX; // trigram keys use 24 bits

thread_local! {
    static TABLE: std::cell::RefCell<MaskTable> = std::cell::RefCell::new(MaskTable { keys: vec![EMPTY; 1 << 12], masks: vec![0; 1 << 12], used: Vec::new() });
}

impl MaskTable {
    fn add(&mut self, k: u32, m: u16) {
        if self.used.len() * 2 >= self.keys.len() {
            self.grow();
        }
        let mask = self.keys.len() - 1;
        let mut i = (k.wrapping_mul(0x9E37_79B1) >> 7) as usize & mask;
        loop {
            if self.keys[i] == k {
                self.masks[i] |= m;
                return;
            }
            if self.keys[i] == EMPTY {
                self.keys[i] = k;
                self.masks[i] = m;
                self.used.push(i as u32);
                return;
            }
            i = (i + 1) & mask;
        }
    }

    fn grow(&mut self) {
        let old: Vec<(u32, u16)> = self.used.iter().map(|&i| (self.keys[i as usize], self.masks[i as usize])).collect();
        let n = self.keys.len() * 2;
        self.keys = vec![EMPTY; n];
        self.masks = vec![0; n];
        self.used.clear();
        for (k, m) in old {
            self.add(k, m);
        }
    }

    /// The entries, sorted by trigram; leaves the table empty.
    fn take(&mut self) -> Vec<(u32, u16)> {
        let mut out: Vec<(u32, u16)> = self.used.iter().map(|&i| (self.keys[i as usize], self.masks[i as usize])).collect();
        for &i in &self.used {
            self.keys[i as usize] = EMPTY;
        }
        self.used.clear();
        out.sort_unstable_by_key(|e| e.0);
        out
    }
}

/// Distinct folded trigrams of `bytes`, sorted, each with its masks: next-byte bits in the high
/// byte (`1 << (next & 7)`, folded), position bits in the low byte (`1 << (start % 8)`).
pub fn trigram_masks(bytes: &[u8]) -> Vec<(u32, u16)> {
    TABLE.with(|t| {
        let t = &mut *t.borrow_mut();
        t.feed(bytes, 0, true);
        t.take()
    })
}

impl MaskTable {
    /// The trigrams that start in `bytes`, a piece of a text that begins `base` bytes into it.
    /// Unless the piece is the `last`, the three bytes at its end start no trigram here: the
    /// next piece begins with them.
    fn feed(&mut self, bytes: &[u8], base: usize, last: bool) {
        if bytes.len() < 3 {
            return;
        }
        let starts = if last { bytes.len() - 2 } else { bytes.len() - 3 };
        let mut k = (bytes[0].to_ascii_lowercase() as u32) << 8 | bytes[1].to_ascii_lowercase() as u32;
        for j in 0..starts {
            k = ((k << 8) | bytes[j + 2].to_ascii_lowercase() as u32) & 0xFF_FFFF;
            let next = bytes.get(j + 3).map_or(0, |&b| 1u16 << ((b.to_ascii_lowercase() & 7) + 8));
            self.add(k, next | 1 << ((base + j) & 7));
        }
    }
}

/// What a file's bytes say about it before its trigrams: `Some(flags)` for one that is searched
/// directly (UTF-16 with a byte-order mark, which Engine A transcodes).
fn direct(head: &[u8]) -> Option<i64> {
    (head.starts_with(&[0xFF, 0xFE]) || head.starts_with(&[0xFE, 0xFF])).then_some(ALWAYS)
}

/// The flags and trigram masks of what `src` holds, read `piece` bytes at a time and up to its
/// first NUL byte: the same as `trigram_masks` of the whole text, without holding it.
fn stream_masks(mut src: impl std::io::Read, piece: usize) -> std::io::Result<(i64, Vec<(u32, u16)>)> {
    let mut buf = vec![0u8; piece.max(1) + 3];
    let (mut held, mut base, mut first) = (0usize, 0usize, true);
    TABLE.with(|t| {
        let t = &mut *t.borrow_mut();
        let mut flags = 0;
        let run = (|| loop {
            let mut len = held;
            while len < buf.len() {
                match src.read(&mut buf[len..]) {
                    Ok(0) => break,
                    Ok(n) => len += n,
                    Err(e) if e.kind() == std::io::ErrorKind::Interrupted => {}
                    Err(e) => return Err(e),
                }
            }
            if std::mem::take(&mut first) {
                if let Some(flags) = direct(&buf[..len]) {
                    return Ok(Some(flags));
                }
            }
            let nul = buf[..len].iter().position(|&b| b == 0);
            let last = nul.is_some() || len < buf.len();
            t.feed(&buf[..nul.unwrap_or(len)], base, last);
            if last {
                flags = if nul.is_some() { BINARY } else { 0 };
                return Ok(None);
            }
            base += len - 3;
            buf.copy_within(len - 3..len, 0);
            held = 3;
        })();
        // the table is emptied whatever happened, so the next file starts clean
        let tris = t.take();
        Ok(match run? {
            Some(direct) => (direct, Vec::new()),
            None => (flags, tris),
        })
    })
}

struct DocIn {
    rel: String,
    size: u64,
    mtime: i64,
    ctime: i64,
    flags: i64,
    tris: Vec<(u32, u16)>,
}

/// A file larger than this is read in pieces: mapping it would end the process when another
/// one shortens the file under the read.
const WHOLE: u64 = 64 << 20;

fn read_doc(root: &Path, rel: String, size: u64, mtime: i64, ctime: i64) -> DocIn {
    let path = root.join(&rel);
    let read = if size > WHOLE {
        File::open(&path).and_then(|f| stream_masks(f, 1 << 20))
    } else {
        std::fs::read(&path).map(|bytes| match direct(&bytes) {
            Some(flags) => (flags, Vec::new()),
            None => match bytes.iter().position(|&b| b == 0) {
                Some(i) => (BINARY, trigram_masks(&bytes[..i])),
                None => (0, trigram_masks(&bytes)),
            },
        })
    };
    match read {
        Ok((flags, tris)) => DocIn { rel, size, mtime, ctime, flags, tris },
        Err(_) => DocIn { rel, size, mtime, ctime, flags: ALWAYS | RETRY, tris: Vec::new() },
    }
}

// ------------------------------------------------------------------------- segments
fn varint(out: &mut Vec<u8>, mut v: u64) {
    while v >= 0x80 {
        out.push((v as u8) | 0x80);
        v >>= 7;
    }
    out.push(v as u8);
}

/// Decode one posting list (document numbers below `ndocs`, strictly increasing, each with its
/// masks).
fn decode_into(bytes: &[u8], ndocs: usize, mut each: impl FnMut(usize, u16)) -> Result<()> {
    let mut i = 0;
    let mut prev = 0u64;
    let mut first = true;
    while i < bytes.len() {
        let mut v = 0u64;
        let mut shift = 0;
        loop {
            let b = *bytes.get(i).ok_or_else(|| anyhow!("truncated posting list"))?;
            i += 1;
            v |= ((b & 0x7f) as u64) << shift;
            if b & 0x80 == 0 {
                break;
            }
            shift += 7;
            if shift > 42 {
                bail!("posting value too long");
            }
        }
        let doc = if first {
            first = false;
            v
        } else {
            if v == 0 {
                bail!("posting list not increasing");
            }
            prev + v
        };
        if doc as usize >= ndocs {
            bail!("posting {doc} outside the segment ({ndocs} documents)");
        }
        let m = bytes.get(i..i + 2).ok_or_else(|| anyhow!("truncated posting masks"))?;
        i += 2;
        each(doc as usize, u16::from(m[0]) << 8 | u16::from(m[1]));
        prev = doc;
    }
    Ok(())
}

fn map_file(path: &Path) -> Result<Option<Mmap>> {
    let f = File::open(path).with_context(|| format!("open {}", path.display()))?;
    if f.metadata()?.len() == 0 {
        return Ok(None);
    }
    Ok(Some(unsafe { Mmap::map(&f) }.with_context(|| format!("mmap {}", path.display()))?))
}

struct Segment {
    name: String,
    keys: Npy,
    ptr: Npy,
    post: Option<Mmap>,
    docs: Npy,
    poff: Npy,
    paths: Option<Mmap>,
    live: Vec<u8>,
    ndocs: usize,
}

fn bytes(m: &Option<Mmap>) -> &[u8] {
    m.as_ref().map(|m| &m[..]).unwrap_or(&[])
}

impl Segment {
    fn open(dir: &Path, name: &str, live: &str) -> Result<Segment> {
        let d = dir.join(name);
        let keys = Npy::open(&d.join("keys.npy"))?;
        let ptr = Npy::open(&d.join("ptr.npy"))?;
        let docs = Npy::open(&d.join("docs.npy"))?;
        let poff = Npy::open(&d.join("poff.npy"))?;
        let post = map_file(&d.join("post.bin"))?;
        let paths = map_file(&d.join("paths.bin"))?;
        let live = std::fs::read(d.join(live)).with_context(|| format!("read {}/{live}", d.display()))?;
        let ndocs = docs.len() / COLS;
        let s = Segment { name: name.to_string(), keys, ptr, post, docs, poff, paths, live, ndocs };
        s.validate(false).with_context(|| format!("text index segment {name}"))?;
        Ok(s)
    }

    fn keys(&self) -> &[u32] {
        self.keys.view().unwrap_or(&[])
    }
    fn ptr(&self) -> &[u64] {
        self.ptr.view().unwrap_or(&[])
    }
    fn docs(&self) -> &[i64] {
        self.docs.view().unwrap_or(&[])
    }
    fn poff(&self) -> &[u64] {
        self.poff.view().unwrap_or(&[])
    }

    /// Structural checks (cheap, on every open); `deep` also checks every key and posting.
    fn validate(&self, deep: bool) -> Result<()> {
        let keys: &[u32] = self.keys.view()?;
        let ptr: &[u64] = self.ptr.view()?;
        let docs: &[i64] = self.docs.view()?;
        let poff: &[u64] = self.poff.view()?;
        let post = bytes(&self.post);
        if !docs.len().is_multiple_of(COLS) || ptr.len() != keys.len() + 1 || poff.len() != self.ndocs + 1 {
            bail!("array lengths disagree");
        }
        if ptr[0] != 0 || ptr[keys.len()] as usize != post.len() || poff[0] != 0 || poff[self.ndocs] as usize != bytes(&self.paths).len() {
            bail!("offsets do not cover the data");
        }
        if self.live.len() != self.ndocs.div_ceil(8) {
            bail!("liveness bitmap has the wrong size");
        }
        if deep {
            if keys.windows(2).any(|w| w[0] >= w[1]) || ptr.windows(2).any(|w| w[0] > w[1]) || poff.windows(2).any(|w| w[0] > w[1]) {
                bail!("keys or offsets out of order");
            }
            for i in 0..keys.len() {
                decode_into(&post[ptr[i] as usize..ptr[i + 1] as usize], self.ndocs, |_, _| {})?;
            }
            for d in 0..self.ndocs {
                std::str::from_utf8(self.path_bytes(d)).context("path is not UTF-8")?;
            }
        }
        Ok(())
    }

    fn path_bytes(&self, d: usize) -> &[u8] {
        let poff = self.poff();
        bytes(&self.paths).get(poff[d] as usize..poff[d + 1] as usize).unwrap_or(&[])
    }
    fn path(&self, d: usize) -> &str {
        std::str::from_utf8(self.path_bytes(d)).unwrap_or("")
    }
    fn is_live(&self, d: usize) -> bool {
        self.live[d / 8] & (1 << (d % 8)) != 0
    }
    fn flags(&self, d: usize) -> i64 {
        self.docs()[d * COLS + 2]
    }

    fn posting(&self, t: u32) -> Option<&[u8]> {
        let i = self.keys().binary_search(&t).ok()?;
        let p = self.ptr();
        bytes(&self.post).get(p[i] as usize..p[i + 1] as usize)
    }

    fn eval(&self, q: &Q) -> Result<Option<Vec<u64>>> {
        let words = self.ndocs.div_ceil(64);
        Ok(match q {
            Q::All => None,
            Q::Tri(t) => {
                let mut bits = vec![0u64; words];
                if let Some(p) = self.posting(*t) {
                    decode_into(p, self.ndocs, |d, _| bits[d / 64] |= 1 << (d % 64))?;
                }
                Some(bits)
            }
            Q::Seq(s) => {
                let keys: Vec<u32> = s.windows(3).map(|w| key(w[0], w[1], w[2])).collect();
                // rarest trigrams first, so the documents still in play shrink fastest
                let mut order: Vec<usize> = (0..keys.len()).collect();
                order.sort_by_key(|&i| self.posting(keys[i]).map(|p| p.len()).unwrap_or(0));
                let mut alive: Option<Vec<u64>> = None;
                let mut lined_up = vec![0xFFu8; self.ndocs];
                for i in order {
                    let mut seen = vec![0u64; words];
                    let need = s.get(i + 3).map(|&b| 1u8 << (b & 7));
                    if let Some(p) = self.posting(keys[i]) {
                        decode_into(p, self.ndocs, |d, m| {
                            if alive.as_ref().is_some_and(|a| a[d / 64] & (1 << (d % 64)) == 0) {
                                return;
                            }
                            lined_up[d] &= (m as u8).rotate_right((i % 8) as u32);
                            if need.is_none_or(|n| (m >> 8) as u8 & n != 0) && lined_up[d] != 0 {
                                seen[d / 64] |= 1 << (d % 64);
                            }
                        })?;
                    }
                    let empty = seen.iter().all(|&w| w == 0);
                    alive = Some(seen);
                    if empty {
                        break;
                    }
                }
                alive
            }
            Q::And(qs) => {
                // rarest trigrams first: the intersection shrinks fastest and can stop early
                let mut order: Vec<&Q> = qs.iter().collect();
                order.sort_by_key(|q| match q {
                    Q::Tri(t) => self.posting(*t).map(|p| p.len()).unwrap_or(0),
                    Q::Seq(s) => s.windows(3).map(|w| self.posting(key(w[0], w[1], w[2])).map(|p| p.len()).unwrap_or(0)).min().unwrap_or(0),
                    _ => usize::MAX,
                });
                let mut acc: Option<Vec<u64>> = None;
                for q in order {
                    if let Some(b) = self.eval(q)? {
                        match &mut acc {
                            None => acc = Some(b),
                            Some(a) => a.iter_mut().zip(&b).for_each(|(x, y)| *x &= y),
                        }
                        if acc.as_ref().map(|a| a.iter().all(|&w| w == 0)).unwrap_or(false) {
                            break;
                        }
                    }
                }
                acc
            }
            Q::Or(qs) => {
                let mut acc = vec![0u64; words];
                for q in qs {
                    match self.eval(q)? {
                        None => return Ok(None),
                        Some(b) => acc.iter_mut().zip(&b).for_each(|(x, y)| *x |= y),
                    }
                }
                Some(acc)
            }
        })
    }
}

fn all_live(n: usize) -> Vec<u8> {
    let mut v = vec![0xFFu8; n.div_ceil(8)];
    if !n.is_multiple_of(8) {
        if let Some(last) = v.last_mut() {
            *last = (1u8 << (n % 8)) - 1;
        }
    }
    v
}

/// Append a posting list: increasing document numbers with their masks.
fn encode_postings(out: &mut Vec<u8>, list: &[(u32, u16)]) {
    let mut prev = 0u32;
    for (j, &(d, m)) in list.iter().enumerate() {
        varint(out, if j == 0 { d as u64 } else { (d - prev) as u64 });
        out.extend_from_slice(&m.to_be_bytes());
        prev = d;
    }
}

/// Write one segment from documents in order (document `i` of the segment is `docs[i]`).
fn write_segment(dir: &Path, docs: &[DocIn]) -> Result<()> {
    std::fs::create_dir_all(dir)?;
    let mut count = vec![0u32; 1 << 24];
    for d in docs {
        for &(t, _) in &d.tris {
            count[t as usize] += 1;
        }
    }
    let mut keys = Vec::new();
    let mut start = vec![0u32; 1 << 24];
    let mut total = 0u32;
    for t in 0..(1usize << 24) {
        if count[t] > 0 {
            keys.push(t as u32);
            start[t] = total;
            total += count[t];
        }
    }
    let mut post = vec![(0u32, 0u16); total as usize];
    let mut cur = start.clone();
    for (i, d) in docs.iter().enumerate() {
        for &(t, m) in &d.tris {
            post[cur[t as usize] as usize] = (i as u32, m);
            cur[t as usize] += 1;
        }
    }
    drop(cur);
    let mut ptr = Vec::with_capacity(keys.len() + 1);
    let mut enc = Vec::with_capacity(post.len() * 3 + post.len() / 4);
    for &t in &keys {
        ptr.push(enc.len() as u64);
        let (s, n) = (start[t as usize] as usize, count[t as usize] as usize);
        encode_postings(&mut enc, &post[s..s + n]);
    }
    ptr.push(enc.len() as u64);
    std::fs::write(dir.join("post.bin"), &enc)?;
    npy::save(&dir.join("keys.npy"), &keys, &[keys.len()])?;
    npy::save(&dir.join("ptr.npy"), &ptr, &[ptr.len()])?;
    write_docs(dir, docs.iter().map(|d| (d.rel.as_str(), d.size, d.mtime, d.flags, d.ctime)))
}

fn write_docs<'a>(dir: &Path, docs: impl Iterator<Item = (&'a str, u64, i64, i64, i64)>) -> Result<()> {
    let mut meta: Vec<i64> = Vec::new();
    let mut paths: Vec<u8> = Vec::new();
    let mut poff: Vec<u64> = vec![0];
    for (rel, size, mtime, flags, ctime) in docs {
        meta.extend([size as i64, mtime, flags, ctime]);
        paths.extend_from_slice(rel.as_bytes());
        poff.push(paths.len() as u64);
    }
    let n = poff.len() - 1;
    std::fs::write(dir.join("paths.bin"), &paths)?;
    npy::save(&dir.join("poff.npy"), &poff, &[poff.len()])?;
    npy::save(&dir.join("docs.npy"), &meta, &[n, COLS])?;
    Ok(())
}

/// Merge the live documents of `segs` into one segment at `dir`, streaming key by key.
fn merge_segments(dir: &Path, segs: &[&Segment]) -> Result<()> {
    std::fs::create_dir_all(dir)?;
    let mut remap: Vec<Vec<u32>> = Vec::new();
    let mut next = 0u32;
    for s in segs {
        remap.push(
            (0..s.ndocs)
                .map(|d| {
                    if s.is_live(d) {
                        next += 1;
                        next - 1
                    } else {
                        u32::MAX
                    }
                })
                .collect(),
        );
    }
    write_docs(
        dir,
        segs.iter().flat_map(|s| {
            let docs = s.docs();
            (0..s.ndocs).filter(|&d| s.is_live(d)).map(move |d| (s.path(d), docs[d * COLS] as u64, docs[d * COLS + 1], docs[d * COLS + 2], docs[d * COLS + 3]))
        }),
    )?;
    let mut w = BufWriter::with_capacity(1 << 20, File::create(dir.join("post.bin"))?);
    let mut keys = Vec::new();
    let mut ptr = vec![0u64];
    let mut cur = vec![0usize; segs.len()];
    let mut buf = Vec::new();
    let mut ids = Vec::new();
    let mut written = 0u64;
    loop {
        let mut min = None;
        for (i, s) in segs.iter().enumerate() {
            if let Some(&k) = s.keys().get(cur[i]) {
                min = Some(min.map_or(k, |m: u32| m.min(k)));
            }
        }
        let Some(k) = min else { break };
        ids.clear();
        for (i, s) in segs.iter().enumerate() {
            if s.keys().get(cur[i]) == Some(&k) {
                let p = s.ptr();
                let post = &bytes(&s.post)[p[cur[i]] as usize..p[cur[i] + 1] as usize];
                decode_into(post, s.ndocs, |d, m| {
                    if remap[i][d] != u32::MAX {
                        ids.push((remap[i][d], m));
                    }
                })?;
                cur[i] += 1;
            }
        }
        if ids.is_empty() {
            continue;
        }
        buf.clear();
        encode_postings(&mut buf, &ids);
        w.write_all(&buf)?;
        written += buf.len() as u64;
        keys.push(k);
        ptr.push(written);
    }
    w.flush()?;
    npy::save(&dir.join("keys.npy"), &keys, &[keys.len()])?;
    npy::save(&dir.join("ptr.npy"), &ptr, &[ptr.len()])?;
    Ok(())
}

// ------------------------------------------------------------------------- the index
#[derive(Debug, Default, Clone, serde::Serialize)]
pub struct TextStats {
    pub files: usize,
    pub files_changed: usize,
    pub files_removed: usize,
    pub segments: usize,
    pub bytes: u64,
    pub seconds: f64,
}

#[derive(serde::Serialize, serde::Deserialize, Default, Clone)]
struct Manifest {
    format: u32,
    generation: u64,
    segments: Vec<SegRef>,
}

#[derive(serde::Serialize, serde::Deserialize, Clone)]
struct SegRef {
    name: String,
    live: String,
}

pub fn dir_of(root: &Path) -> PathBuf {
    root.join(".scrutate").join("text")
}

/// Whether `root` has a text index (built, of any format).
pub fn exists(root: &Path) -> bool {
    dir_of(root).join("manifest.json").exists()
}

/// A text index whose files are not what an update wrote: an update met it and stopped, so the
/// caller can build the index again (`stores`).
#[derive(Debug)]
pub struct Damaged(pub anyhow::Error);

impl std::fmt::Display for Damaged {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{:#}", self.0)
    }
}

impl std::error::Error for Damaged {}

fn read_manifest(dir: &Path) -> Result<Option<Manifest>> {
    let p = dir.join("manifest.json");
    match std::fs::read(&p) {
        Ok(b) => {
            let m: Manifest = serde_json::from_slice(&b)
                .with_context(|| format!("{} is not a text index manifest: `scrutate index --text` rebuilds the text index", p.display()))?;
            if m.format > FORMAT {
                bail!(
                    "text index built by a newer scrutate (format {}, this version has {FORMAT}): this version cannot read it; use the newer scrutate, or `scrutate index --text --force` to rebuild it with this one",
                    m.format
                );
            }
            if m.format != FORMAT {
                return Ok(None); // an older format: rebuilt by the next update
            }
            Ok(Some(m))
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(e) => Err(e).with_context(|| format!("read {}", p.display())),
    }
}

pub struct TextIndex {
    pub root: PathBuf,
    segs: Vec<Segment>,
}

impl TextIndex {
    /// The current snapshot, or None when no text index has been built. A concurrent update may
    /// delete a segment between reading the manifest and opening it: retry with the new manifest.
    pub fn open(root: &Path) -> Result<Option<TextIndex>> {
        let dir = dir_of(root);
        let mut last = None;
        for _ in 0..5 {
            let Some(m) = read_manifest(&dir)? else { return Ok(None) };
            match m.segments.iter().map(|s| Segment::open(&dir, &s.name, &s.live)).collect::<Result<Vec<_>>>() {
                Ok(segs) => return Ok(Some(TextIndex { root: root.to_path_buf(), segs })),
                Err(e) => last = Some(e),
            }
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
        Err(last.unwrap_or_else(|| anyhow!("text index unreadable")).context("text index is damaged; rebuild it with `scrutate index --text --force`"))
    }

    pub fn files(&self) -> usize {
        self.segs.iter().map(|s| (0..s.ndocs).filter(|&d| s.is_live(d)).count()).sum()
    }

    pub fn segments(&self) -> usize {
        self.segs.len()
    }

    /// Paths (relative to the root) of the live files that can match `q`. Binary files are included
    /// for multi-line searches (which do not stop at a NUL byte); unreadable and UTF-16 files always.
    pub fn candidates(&self, q: &Q, multiline: bool) -> Result<Vec<String>> {
        let mut out = Vec::new();
        for s in &self.segs {
            let bits = s.eval(q).with_context(|| format!("text index segment {} is damaged; rebuild it with `scrutate index --text --force`", s.name))?;
            for d in 0..s.ndocs {
                if !s.is_live(d) {
                    continue;
                }
                let f = s.flags(d);
                let hit = bits.as_ref().map(|b| b[d / 64] & (1 << (d % 64)) != 0).unwrap_or(true);
                if hit || f & ALWAYS != 0 || (multiline && f & BINARY != 0) {
                    out.push(s.path(d).to_string());
                }
            }
        }
        Ok(out)
    }

    /// Of `files` (paths from the root, each with its `stat` now when the caller has it), the ones
    /// a search for `q` must read: each one this index holds as it is now that can match, and each
    /// one it does not hold as it is now (new, changed since, left out, unreadable when indexed).
    pub fn to_read<'a>(&self, q: &Q, multiline: bool, files: impl Iterator<Item = (&'a str, Option<crate::index::Stat>)>) -> Result<Vec<&'a str>> {
        let mut held: std::collections::HashMap<&str, (bool, &[i64])> = std::collections::HashMap::new();
        for s in &self.segs {
            let bits = s.eval(q).with_context(|| format!("text index segment {} is damaged; rebuild it with `scrutate index --text --force`", s.name))?;
            for d in (0..s.ndocs).filter(|&d| s.is_live(d)) {
                let f = s.flags(d);
                let hit = bits.as_ref().is_none_or(|b| b[d / 64] & (1 << (d % 64)) != 0) || f & ALWAYS != 0 || (multiline && f & BINARY != 0);
                // a path held twice is read
                held.entry(s.path(d)).and_modify(|e| e.0 = true).or_insert((hit, &s.docs()[d * COLS..(d + 1) * COLS]));
            }
        }
        Ok(files
            .filter(|&(p, stat)| match held.get(p) {
                None => true,
                Some(&(hit, m)) => {
                    let stat = stat.or_else(|| std::fs::symlink_metadata(self.root.join(p)).ok().map(|m| crate::index::Stat::of(&m)));
                    let now = stat.is_some_and(|s| m[0] == s.size && m[1] == s.mtime && m[2] & RETRY == 0 && m[3] == s.ctime);
                    hit || !now
                }
            })
            .map(|(p, _)| p)
            .collect())
    }

    /// Deep validation of every segment (`scrutate check`).
    pub fn check(&self) -> Vec<String> {
        self.segs.iter().filter_map(|s| s.validate(true).err().map(|e| format!("text index segment {}: {e:#}", s.name))).collect()
    }

    pub fn disk_bytes(root: &Path) -> u64 {
        fn walk(p: &Path) -> u64 {
            std::fs::read_dir(p)
                .map(|rd| rd.flatten().map(|e| if e.path().is_dir() { walk(&e.path()) } else { e.metadata().map(|m| m.len()).unwrap_or(0) }).sum())
                .unwrap_or(0)
        }
        walk(&dir_of(root))
    }
}

/// Size, mtime and status change time: an edit that keeps the first two moves the third.
fn stamp(md: &std::fs::Metadata) -> (u64, i64, i64) {
    let st = crate::index::Stat::of(md);
    (md.len(), st.mtime, st.ctime)
}

/// The files Engine A's default search visits, relative to `root`, with size, mtime and status
/// change time.
pub(crate) fn walk(root: &Path) -> Result<Vec<(String, u64, i64, i64)>> {
    let roots = [root.to_path_buf()];
    let walker = instant::build_walker(&roots, &Files::default())?;
    let out = Mutex::new(Vec::new());
    walker.run(|| {
        let (out, roots) = (&out, &roots);
        Box::new(move |entry| {
            if let Ok(e) = entry {
                if e.file_type().map(|t| t.is_file()).unwrap_or(false) {
                    let rel = instant::relative(e.path(), roots);
                    let (size, mtime, ctime) = e.metadata().map(|m| stamp(&m)).unwrap_or((0, 0, 0));
                    if let Ok(mut v) = out.lock() {
                        v.push((rel, size, mtime, ctime));
                    }
                }
            }
            ignore::WalkState::Continue
        })
    });
    let mut v = out.into_inner().map_err(|_| anyhow!("walker panicked"))?;
    v.sort();
    Ok(v)
}

/// What the walk of `walk` yields under `start` (a directory that walk of the root enters, whose
/// ignore files above it apply), `depth` levels down: the directories, and the files.
pub(crate) fn walk_entries(start: &Path, depth: Option<usize>) -> (Vec<PathBuf>, Vec<PathBuf>) {
    let o = Files { max_depth: depth, threads: if depth.is_some() { 1 } else { 0 }, ..Files::default() };
    let Ok(walker) = instant::build_walker(&[start.to_path_buf()], &o) else { return Default::default() };
    let out = Mutex::new((Vec::new(), Vec::new()));
    walker.run(|| {
        let out = &out;
        Box::new(move |entry| {
            if let Ok(e) = entry {
                let (dir, file) = e.file_type().map_or((false, false), |t| (t.is_dir(), t.is_file()));
                if let (true, Ok(mut v)) = (dir || file, out.lock()) {
                    if dir {
                        v.0.push(e.into_path())
                    } else {
                        v.1.push(e.into_path())
                    }
                }
            }
            ignore::WalkState::Continue
        })
    });
    out.into_inner().unwrap_or_default()
}

fn next_segment_number(dir: &Path) -> Result<u64> {
    Ok(std::fs::read_dir(dir)?
        .flatten()
        .filter_map(|e| e.file_name().to_str().and_then(|n| n.strip_prefix('s')).and_then(|n| n.parse::<u64>().ok()))
        .max()
        .unwrap_or(0)
        + 1)
}

/// Wait for the update lock. Polls `try_lock`: SMB mounts answer a blocking lock request with
/// EAGAIN instead of waiting, so a blocking `lock()` fails there when another update runs.
fn lock_exclusive(f: &File) -> Result<()> {
    let t0 = Instant::now();
    loop {
        match f.try_lock() {
            Ok(()) => return Ok(()),
            Err(std::fs::TryLockError::WouldBlock) => {}
            Err(std::fs::TryLockError::Error(e)) if e.kind() == std::io::ErrorKind::WouldBlock => {}
            Err(std::fs::TryLockError::Error(e)) => return Err(anyhow::Error::new(e).context("lock the text index")),
        }
        if t0.elapsed() > std::time::Duration::from_secs(600) {
            bail!("another process has held the text index lock for 10 minutes");
        }
        std::thread::sleep(std::time::Duration::from_millis(20));
    }
}

/// Bring the text index of `root` up to date: unchanged files (same size, mtime and status change
/// time) are kept, changed and new files are read into new segments, removed files are marked
/// dead, and the segments are merged when there are too many or too many dead documents.
pub fn update(root: &Path, force: bool, progress: bool) -> Result<TextStats> {
    update_with(root, force, progress, None, None)
}

/// `update` with the files a look at the tree found (`files::look` with the text index's walk),
/// instead of a walk.
pub fn update_found(root: &Path, force: bool, progress: bool, found: &[crate::files::Found]) -> Result<TextStats> {
    update_with(root, force, progress, None, Some(found))
}

/// `update` of just these files (relative to `root`; each one a file the walk lists, or gone),
/// without a walk of the tree. With no usable index yet it is a full `update`.
pub fn update_paths(root: &Path, paths: &[String]) -> Result<TextStats> {
    update_with(root, false, false, Some(paths), None)
}

fn update_with(root: &Path, force: bool, progress: bool, only: Option<&[String]>, found: Option<&[crate::files::Found]>) -> Result<TextStats> {
    let t0 = Instant::now();
    crate::files::index_dir(root)?;
    let dir = dir_of(root);
    std::fs::create_dir_all(&dir).with_context(|| format!("create {}", dir.display()))?;
    crate::index::write_gitignore(&root.join(".scrutate"))?;
    let lock = File::options().create(true).truncate(false).write(true).open(dir.join("lock"))?;
    lock_exclusive(&lock)?;
    let old = match read_manifest(&dir) {
        _ if force => None,
        // a manifest a crash cut short is damage, as a damaged segment is; one of a newer scrutate is refused
        Err(e) if e.downcast_ref::<serde_json::Error>().is_some() => return Err(Damaged(e).into()),
        m => m?,
    };
    let mut segs: Vec<Segment> = match &old {
        Some(m) => m.segments.iter().map(|s| Segment::open(&dir, &s.name, &s.live)).collect::<Result<_>>().map_err(Damaged)?,
        None => Vec::new(),
    };
    // a new index needs every file
    let only = only.filter(|_| old.is_some());
    let generation = old.as_ref().map(|m| m.generation).unwrap_or(0) + 1;
    let live_name = format!("live-{generation:08}.bin");
    let files = match (only, found) {
        (None, None) => walk(root)?,
        // a stat the look could not take is recorded as the walk records it
        (None, Some(found)) => {
            found.iter().filter(|f| f.text).map(|f| f.stat.map_or((f.path.clone(), 0, 0, 0), |s| (f.path.clone(), s.size as u64, s.mtime, s.ctime))).collect()
        }
        (Some(paths), _) => {
            let mut v: Vec<(String, u64, i64, i64)> = paths
                .iter()
                .filter_map(|p| {
                    let m = std::fs::symlink_metadata(root.join(p)).ok().filter(|m| m.is_file())?;
                    let (size, mtime, ctime) = stamp(&m);
                    Some((p.clone(), size, mtime, ctime))
                })
                .collect();
            v.sort();
            v.dedup();
            v
        }
    };
    let named: Option<std::collections::HashSet<&str>> = only.map(|p| p.iter().map(String::as_str).collect());
    let mut known: std::collections::HashMap<String, (usize, usize)> = std::collections::HashMap::new();
    for (i, s) in segs.iter().enumerate() {
        for d in 0..s.ndocs {
            if s.is_live(d) && named.as_ref().is_none_or(|n| n.contains(s.path(d))) {
                known.insert(s.path(d).to_string(), (i, d));
            }
        }
    }
    let mut changed: Vec<(String, u64, i64, i64)> = Vec::new();
    for (rel, size, mtime, ctime) in &files {
        match known.remove(rel) {
            Some((i, d)) => {
                let m = &segs[i].docs()[d * COLS..(d + 1) * COLS];
                if m[0] as u64 == *size && m[1] == *mtime && m[2] & RETRY == 0 && m[3] == *ctime {
                    continue;
                }
                segs[i].live[d / 8] &= !(1 << (d % 8));
                changed.push((rel.clone(), *size, *mtime, *ctime));
            }
            None => changed.push((rel.clone(), *size, *mtime, *ctime)),
        }
    }
    // what is left in `known` is no longer on disk
    let removed = known.len();
    for (_, (i, d)) in known {
        segs[i].live[d / 8] &= !(1 << (d % 8));
    }
    let mut next_seg = next_segment_number(&dir)?;
    let mut batch: Vec<DocIn> = Vec::new();
    let mut batch_postings = 0usize;
    let total = changed.len();
    let mut done = 0usize;
    let mut flush = |batch: &mut Vec<DocIn>, segs: &mut Vec<Segment>| -> Result<()> {
        if batch.is_empty() {
            return Ok(());
        }
        let name = format!("s{next_seg:08}");
        next_seg += 1;
        write_segment(&dir.join(&name), batch)?;
        std::fs::write(dir.join(&name).join(&live_name), all_live(batch.len()))?;
        segs.push(Segment::open(&dir, &name, &live_name)?);
        batch.clear();
        Ok(())
    };
    for chunk in changed.chunks(1024) {
        let docs: Vec<DocIn> = chunk.par_iter().map(|(rel, size, mtime, ctime)| read_doc(root, rel.clone(), *size, *mtime, *ctime)).collect();
        for d in docs {
            batch_postings += d.tris.len();
            batch.push(d);
            if batch_postings >= BATCH_POSTINGS {
                flush(&mut batch, &mut segs)?;
                batch_postings = 0;
            }
        }
        done += chunk.len();
        if progress {
            eprint!("\r[scrutate] text index: {done}/{total} files");
        }
    }
    flush(&mut batch, &mut segs)?;
    if progress && total > 0 {
        eprintln!();
    }
    let live_docs: usize = segs.iter().map(|s| (0..s.ndocs).filter(|&d| s.is_live(d)).count()).sum();
    let all_docs: usize = segs.iter().map(|s| s.ndocs).sum();
    let many_dead = all_docs > 0 && (all_docs - live_docs) * 10 > all_docs * 3;
    if many_dead || segs.len() > MAX_SEGMENTS {
        // too many segments alone: the largest stays as it is, so the small ones a watch adds
        // do not write the whole index again every few updates
        let kept = (!many_dead).then(|| {
            let largest = (0..segs.len()).max_by_key(|&i| segs[i].ndocs).unwrap_or(0);
            segs.remove(largest)
        });
        // the merge slices the posting data with the stored offsets
        segs.iter().try_for_each(|s| s.validate(true)).map_err(Damaged)?;
        let merged_live: usize = segs.iter().map(|s| (0..s.ndocs).filter(|&d| s.is_live(d)).count()).sum();
        let name = format!("s{:08}", next_segment_number(&dir)?);
        merge_segments(&dir.join(&name), &segs.iter().collect::<Vec<_>>())?;
        std::fs::write(dir.join(&name).join(&live_name), all_live(merged_live))?;
        segs = kept.into_iter().chain([Segment::open(&dir, &name, &live_name)?]).collect();
    }
    // liveness of the segments kept: a new file per generation, so a reader of the old manifest
    // keeps a consistent view until it reopens. Written also when a file of that name is there:
    // an update that stopped before its manifest left one, with the liveness of that run
    for s in &segs {
        let p = dir.join(&s.name).join(&live_name);
        let tmp = p.with_extension("tmp");
        crate::index::write_new(&tmp, &s.live)?;
        std::fs::rename(&tmp, &p)?;
    }
    let m = Manifest { format: FORMAT, generation, segments: segs.iter().map(|s| SegRef { name: s.name.clone(), live: live_name.clone() }).collect() };
    let tmp = dir.join("manifest.json.tmp");
    crate::index::write_new(&tmp, &serde_json::to_vec(&m)?)?;
    std::fs::rename(&tmp, dir.join("manifest.json"))?;
    let names: Vec<String> = segs.iter().map(|s| s.name.clone()).collect();
    let nsegs = segs.len();
    drop(segs);
    gc(&dir, &names, &live_name);
    Ok(TextStats {
        files: live_docs,
        files_changed: total,
        files_removed: removed,
        segments: nsegs,
        bytes: TextIndex::disk_bytes(root),
        seconds: t0.elapsed().as_secs_f64(),
    })
}

/// Remove segment directories and liveness files the manifest no longer names. Errors are ignored
/// (a file still mapped on Windows is removed by a later update).
fn gc(dir: &Path, keep: &[String], live: &str) {
    let Ok(rd) = std::fs::read_dir(dir) else { return };
    for e in rd.flatten() {
        let name = e.file_name().to_string_lossy().into_owned();
        if !e.path().is_dir() {
            continue;
        }
        if !keep.contains(&name) {
            let _ = std::fs::remove_dir_all(e.path());
            continue;
        }
        if let Ok(files) = std::fs::read_dir(e.path()) {
            for f in files.flatten() {
                let n = f.file_name().to_string_lossy().into_owned();
                if n.starts_with("live-") && n != live {
                    let _ = std::fs::remove_file(f.path());
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::instant::{Case, Pattern};

    fn q(pat: &str, mode: Mode, case: Case) -> Q {
        query_for(&Query { pattern: Pattern { text: pat.to_string(), mode, case, ..Pattern::default() }, ..Query::default() }).unwrap()
    }

    fn trigrams(text: &[u8]) -> Vec<(u32, u16)> {
        trigram_masks(text)
    }

    #[test]
    fn literal_needs_all_its_trigrams() {
        let x = q("kernel", Mode::Literal, Case::Sensitive);
        assert!(holds(&x, &trigrams(b"the KERNEL thread")));
        assert!(!holds(&x, &trigrams(b"the kern el")));
        assert_eq!(q("ab", Mode::Literal, Case::Sensitive), Q::All);
        // every trigram of "kernel" is there, but not one after the other
        assert!(!holds(&x, &trigrams(b"kerne nel")));
        assert!(!holds(&x, &trigrams(b"ker xern yrne znel")));
        assert!(holds(&x, &trigrams(b"ker xern yrne znel kernel")));
    }

    #[test]
    fn a_text_read_in_pieces_has_the_masks_of_the_whole_text() {
        // bytes from a small generator, with runs that repeat so trigrams recur at many offsets
        let mut x = 0x2545_F491_4F6C_DD1Du64;
        let mut text: Vec<u8> = (0..5000)
            .map(|_| {
                x ^= x << 13;
                x ^= x >> 7;
                x ^= x << 17;
                b"abcdeABCDE_ \n"[(x % 13) as usize]
            })
            .collect();
        for len in [0, 1, 2, 3, 4, 5, 7, 8, 9, 64, 1000, 5000] {
            for piece in [1, 2, 3, 4, 5, 7, 8, 63, 64, 65, 4096, 10_000] {
                let got = stream_masks(&text[..len], piece).unwrap();
                assert_eq!(got, (0, trigram_masks(&text[..len])), "length {len}, pieces of {piece}");
            }
        }
        // the text ends at the first NUL byte, wherever a piece ends
        for at in [0, 1, 2, 3, 4, 62, 63, 64, 65, 66, 67, 2500, 4999] {
            text[at] = 0;
            for piece in [1, 3, 64, 4096] {
                assert_eq!(stream_masks(&text[..], piece).unwrap(), (BINARY, trigram_masks(&text[..at])), "NUL at {at}, pieces of {piece}");
            }
            text[at] = b'a';
        }
        // a UTF-16 byte-order mark is seen in the first piece, and a failed read leaves nothing behind
        assert_eq!(stream_masks(&b"\xFF\xFEa\0b\0"[..], 1).unwrap(), (ALWAYS, Vec::new()));
        struct Fails(usize);
        impl std::io::Read for Fails {
            fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
                if self.0 == 0 {
                    return Err(std::io::Error::other("gone"));
                }
                self.0 -= 1;
                buf[0] = b'q';
                Ok(1)
            }
        }
        assert!(stream_masks(Fails(40), 8).is_err());
        assert_eq!(trigram_masks(b"abc").len(), 1);
    }

    #[test]
    fn masks_match_a_scan_of_the_text() {
        let text = b"Kernel_thread(kernel) kernels";
        for (k, m) in trigram_masks(text) {
            let (mut next, mut at) = (0u8, 0u8);
            for j in 0..text.len() - 2 {
                if key(text[j], text[j + 1], text[j + 2]) == k {
                    at |= 1 << (j % 8);
                    if let Some(&b) = text.get(j + 3) {
                        next |= 1 << (b.to_ascii_lowercase() & 7);
                    }
                }
            }
            assert_eq!(m, u16::from(next) << 8 | u16::from(at), "{k:06x}");
        }
        let mut x = 0x9E37_79B9_7F4A_7C15u64;
        let big: Vec<u8> = (0..200_000)
            .map(|_| {
                x ^= x << 13;
                x ^= x >> 7;
                x ^= x << 17;
                x as u8
            })
            .collect();
        let m = trigram_masks(&big);
        assert!(m.windows(2).all(|w| w[0].0 < w[1].0) && m.len() > 10_000);
    }

    #[test]
    fn alternation_and_classes() {
        let x = q("foo(bar|baz)qux", Mode::Regex, Case::Sensitive);
        assert!(holds(&x, &trigrams(b"xx foobazqux")));
        assert!(!holds(&x, &trigrams(b"foo qux bar")));
        assert_eq!(q("a.*b", Mode::Regex, Case::Sensitive), Q::All);
        let y = q(r"err(or)?_code", Mode::Regex, Case::Sensitive);
        assert!(holds(&y, &trigrams(b"err_code")) && holds(&y, &trigrams(b"error_code")));
    }

    #[test]
    fn unicode_case_folding_is_covered() {
        // (?i)k also matches the Kelvin sign; the condition must accept a file that only has that
        let x = q("kernel", Mode::Literal, Case::Insensitive);
        assert!(holds(&x, &trigrams("\u{212A}ernel".as_bytes())));
        assert!(holds(&x, &trigrams(b"KeRnEl")));
        let y = q("été", Mode::Literal, Case::Insensitive);
        assert!(holds(&y, &trigrams("ÉTÉ".as_bytes())));
    }

    #[test]
    fn identifier_and_fuzzy() {
        let x = q("refreshToken", Mode::Identifier, Case::Sensitive);
        for s in ["refresh_token", "REFRESH-TOKEN", "RefreshToken"] {
            assert!(holds(&x, &trigrams(s.as_bytes())), "{s}");
        }
        let f = q("tokenizer", Mode::Fuzzy { max_edits: 1 }, Case::Sensitive);
        assert!(holds(&f, &trigrams(b"tokXnizer")));
    }

    #[test]
    fn segments_evaluate_conditions_as_holds_does() {
        let mut state = 0x2545_F491_4F6C_DD1Du64;
        let mut rnd = |n: usize| {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            (state % n as u64) as usize
        };
        let words = ["kernel", "thread", "ker", "nel", "rne", "ern", "Kernel_", "_thread", " ", "\n", "xyz", "pm_resume", "PM_", "RESUME", "é", "aaaa", "aa"];
        let texts: Vec<Vec<u8>> = (0..300).map(|_| (0..rnd(40)).map(|_| words[rnd(words.len())]).collect::<String>().into_bytes()).collect();
        let tmp = std::env::temp_dir().join(format!("scrutate-seg-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&tmp);
        let doc = |i: usize, t: &[u8]| DocIn { rel: format!("f{i}"), size: t.len() as u64, mtime: 0, ctime: 0, flags: 0, tris: trigram_masks(t) };
        let (a, b) = texts.split_at(170);
        write_segment(&tmp.join("a"), &a.iter().enumerate().map(|(i, t)| doc(i, t)).collect::<Vec<_>>()).unwrap();
        write_segment(&tmp.join("b"), &b.iter().enumerate().map(|(i, t)| doc(i, t)).collect::<Vec<_>>()).unwrap();
        std::fs::write(tmp.join("a/live"), all_live(a.len())).unwrap();
        std::fs::write(tmp.join("b/live"), all_live(b.len())).unwrap();
        let (sa, sb) = (Segment::open(&tmp, "a", "live").unwrap(), Segment::open(&tmp, "b", "live").unwrap());
        merge_segments(&tmp.join("m"), &[&sa, &sb]).unwrap();
        std::fs::write(tmp.join("m/live"), all_live(texts.len())).unwrap();
        let sm = Segment::open(&tmp, "m", "live").unwrap();
        sm.validate(true).unwrap();
        let pats = ["kernel", "kernel_thread", "pm_resume", "ker(nel|xyz)", "thread", "aaaaa", "nel thr", "é xyz", r"_\w+_resume"];
        for pat in pats {
            for case in [Case::Sensitive, Case::Insensitive] {
                let cond = q(pat, Mode::Regex, case);
                for (seg, docs) in [(&sa, a), (&sb, b), (&sm, &texts[..])] {
                    let bits = seg.eval(&cond).unwrap();
                    for (d, t) in docs.iter().enumerate() {
                        let got = bits.as_ref().is_none_or(|b| b[d / 64] & (1 << (d % 64)) != 0);
                        assert_eq!(got, holds(&cond, &trigram_masks(t)), "{pat} {case:?} doc {d} {:?}", String::from_utf8_lossy(t));
                    }
                }
            }
        }
        let _ = std::fs::remove_dir_all(&tmp);
    }

    #[test]
    fn property_condition_never_rejects_a_matching_text() {
        // xorshift: deterministic and dependency-free
        let mut state = 0x9E37_79B9_7F4A_7C15u64;
        let mut rnd = |n: usize| {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            (state % n as u64) as usize
        };
        let atoms = ["ab", "cd", "x", "(ab|cde)", "[a-c]", "k", "s", "é", ".", "\\w", "y?", "(cd)+", "z{2}", "A", "(?:kx|sy)", "[^a]"];
        let alphabet = ["a", "b", "c", "d", "e", "x", "y", "z", "k", "K", "\u{212A}", "s", "ſ", "é", "É", "A", " "];
        for _ in 0..4000 {
            let n = 1 + rnd(5);
            let pat: String = (0..n).map(|_| atoms[rnd(atoms.len())]).collect();
            let case = if rnd(2) == 0 { Case::Insensitive } else { Case::Sensitive };
            let cond = q(&pat, Mode::Regex, case);
            let re = regex::RegexBuilder::new(&pat).case_insensitive(case == Case::Insensitive).build().unwrap();
            for _ in 0..40 {
                let m = rnd(14);
                let text: String = (0..m).map(|_| alphabet[rnd(alphabet.len())]).collect();
                if re.is_match(&text) {
                    assert!(holds(&cond, &trigrams(text.as_bytes())), "pattern {pat:?} ({case:?}) matches {text:?} but the condition {cond:?} rejects it");
                }
            }
        }
    }

    #[test]
    fn condition_never_rejects_a_text_engine_a_matches() {
        use grep_matcher::Matcher;
        let mut state = 0x2545_F491_4F6C_DD1Du64;
        let mut rnd = |n: usize| {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            (state % n as u64) as usize
        };
        let words = [
            "kernel",
            "Kernel",
            "KERNEL",
            "_thread",
            "thread",
            "ker",
            "nel",
            " ",
            "\n",
            "pm_resume",
            "PM_RESUME",
            "refresh_token",
            "RefreshToken",
            "\u{212A}ernel",
            "été",
            "ÉTÉ",
            "tokXnizer",
            "x",
        ];
        let texts: Vec<String> = (0..400).map(|_| (0..rnd(12)).map(|_| words[rnd(words.len())]).collect()).collect();
        let pats = [
            "kernel",
            "Kernel",
            "KERNEL_thread",
            "pm_resume",
            "refreshToken",
            "ker(nel|xyz)",
            r"\bthread\b",
            "été",
            "ÉTÉ",
            "^pm_",
            "nel$",
            r"nel\nker",
            "tokenizer",
            "a.b",
            "el thr",
        ];
        let modes = [Mode::Regex, Mode::Literal, Mode::Identifier, Mode::Fuzzy { max_edits: 1 }, Mode::Pcre2, Mode::FuzzyRegex { max_edits: 1 }];
        let mut matched = 0;
        for pat in pats {
            for mode in modes {
                for case in [Case::Sensitive, Case::Insensitive, Case::Smart] {
                    for (word, multiline) in [(false, false), (true, false), (false, true)] {
                        let o = Query { pattern: Pattern { text: pat.to_string(), mode, case, word, multiline, ..Pattern::default() }, ..Query::default() };
                        let Ok(m) = instant::build_matcher(&o.pattern) else { continue };
                        let cond = query_for(&o).unwrap();
                        let is_match = |h: &str| match &m {
                            instant::AnyMatcher::Literal(m) => m.is_match(h.as_bytes()).unwrap(),
                            instant::AnyMatcher::Regex(m) => m.is_match(h.as_bytes()).unwrap(),
                            instant::AnyMatcher::Fuzzy(m) => m.is_match(h.as_bytes()).unwrap(),
                            instant::AnyMatcher::Pcre2(m) => m.is_match(h.as_bytes()).unwrap(),
                            instant::AnyMatcher::FuzzyRegex(m) => m.is_match(h.as_bytes()).unwrap(),
                        };
                        for text in &texts {
                            let hit = if multiline { is_match(text) } else { text.split('\n').any(&is_match) };
                            if hit {
                                matched += 1;
                                assert!(
                                    holds(&cond, &trigrams(text.as_bytes())),
                                    "{pat:?} {mode:?} {case:?} word={word} multiline={multiline} matches {text:?} but {cond:?} rejects it"
                                );
                            }
                        }
                    }
                }
            }
        }
        assert!(matched > 1000, "only {matched} matches");
    }

    #[test]
    fn an_update_of_named_files_leaves_the_others_alone() {
        let root = std::env::temp_dir().join(format!("scrutate_text_paths_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).unwrap();
        for name in ["a.txt", "b.txt", "c.txt"] {
            std::fs::write(root.join(name), "one\n").unwrap();
        }
        let root = std::fs::canonicalize(&root).unwrap();
        assert_eq!(update(&root, false, false).unwrap().files, 3);
        std::fs::write(root.join("a.txt"), "two two\n").unwrap();
        std::fs::write(root.join("b.txt"), "two two\n").unwrap();
        std::fs::remove_file(root.join("c.txt")).unwrap();
        std::fs::write(root.join("d.txt"), "three\n").unwrap();
        let st = update_paths(&root, &["a.txt".into(), "c.txt".into(), "d.txt".into(), "never.txt".into()]).unwrap();
        assert_eq!((st.files, st.files_changed, st.files_removed), (3, 2, 1));
        let ix = TextIndex::open(&root).unwrap().unwrap();
        let two = query_for(&Query { pattern: Pattern { text: "two two".into(), ..Pattern::default() }, ..Query::default() }).unwrap();
        assert_eq!(ix.candidates(&two, false).unwrap(), ["a.txt"], "b.txt was not named");
        drop(ix);
        assert_eq!(update(&root, false, false).unwrap().files_changed, 1);
        std::fs::remove_dir_all(&root).unwrap();
    }
}

//! Per-file results of `tsquery`, so files whose content did not change are not parsed again.
//!
//! One file per (scrutate version, language, query text, searched paths from the root) under
//! `.scrutate/tsquery/`, mapping a file's content hash and name (`key`) to that file's captures
//! (paths are filled in on use). The content hash is the one the code index records, so a file
//! whose stat the code index says is current is not read at all on a hit. A complete run keeps
//! only the entries it used, so a file holds the current tree's results; the files themselves are
//! evicted least recently used first once together they exceed `MAX_BYTES`. Files are replaced by
//! rename, so a reader or a crash never sees half of one; anything unreadable counts as empty.

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::time::SystemTime;

use anyhow::{bail, Result};
use blake2::digest::{Update, VariableOutput};
use blake2::Blake2bVar;

use crate::intel::Capture;

/// Total size of `.scrutate/tsquery/`; the least recently used query files go first beyond it.
pub const MAX_BYTES: u64 = 128 << 20;
const MAGIC: &[u8] = b"scrutate-tsquery-cache 1\n";

pub type Key = [u8; 16];

pub fn hash(parts: &[&[u8]]) -> Key {
    let mut h = Blake2bVar::new(16).expect("blake2b-128");
    for p in parts {
        h.update(&(p.len() as u64).to_le_bytes());
        h.update(p);
    }
    let mut out = [0u8; 16];
    h.finalize_variable(&mut out).expect("blake2b finalize");
    out
}

/// The key of one file's captures: the content hash the code index records for such bytes, and
/// the file name, which with the content decides the file's language.
pub fn key(content_hash: &str, path: &str) -> Key {
    let name = path.rsplit('/').next().unwrap_or(path).to_lowercase();
    hash(&[content_hash.as_bytes(), name.as_bytes()])
}

pub struct Cache {
    dir: PathBuf,
    path: PathBuf,
    header: Vec<u8>,
    pub entries: HashMap<Key, Vec<Capture>>,
}

fn hex(k: &Key) -> String {
    k.iter().map(|b| format!("{b:02x}")).collect()
}

impl Cache {
    /// The cache of one query under `root/.scrutate/`, empty when there is none or it is unreadable.
    /// The searched paths (`scopes`, from the root, so that a copy of the tree at another place
    /// finds the same file) are part of the name, so runs over different subtrees do not evict
    /// each other's entries.
    pub fn open(root: &Path, lang: &str, query: &str, scopes: &[String]) -> Cache {
        let dir = root.join(".scrutate").join("tsquery");
        let paths = scopes;
        let mut header = MAGIC.to_vec();
        for s in [crate::VERSION, lang, query, &paths.join("\n")] {
            header.extend((s.len() as u32).to_le_bytes());
            header.extend(s.as_bytes());
        }
        let path = dir.join(format!("{}.bin", hex(&hash(&[&header]))));
        let entries = crate::files::read_regular(&path, MAX_BYTES).and_then(|b| decode(&b, &header).ok()).unwrap_or_default();
        Cache { dir, path, header, entries }
    }

    /// Replace the stored entries with `entries`, then evict old query files. Errors are ignored by
    /// callers: the cache only saves time.
    pub fn store(&self, entries: &HashMap<Key, Vec<Capture>>) -> Result<()> {
        let mut out = self.header.clone();
        let mut keys: Vec<&Key> = entries.keys().collect();
        keys.sort();
        out.extend((keys.len() as u64).to_le_bytes());
        for k in keys {
            let caps = &entries[k];
            out.extend(k);
            out.extend((caps.len() as u32).to_le_bytes());
            for c in caps {
                out.extend(c.line.to_le_bytes());
                out.extend(c.column.to_le_bytes());
                for s in [&c.capture, &c.kind, &c.text] {
                    out.extend((s.len() as u32).to_le_bytes());
                    out.extend(s.as_bytes());
                }
            }
            if out.len() as u64 > MAX_BYTES {
                bail!("too large to cache");
            }
        }
        let scrutate = self.dir.parent().unwrap_or(&self.dir);
        crate::files::index_dir(scrutate.parent().unwrap_or(scrutate))?;
        std::fs::create_dir_all(&self.dir)?;
        crate::index::write_gitignore(scrutate)?;
        let nanos = SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).map(|d| d.as_nanos()).unwrap_or(0);
        let tmp = self.dir.join(format!(".tmp-{}-{nanos}", std::process::id()));
        crate::index::write_new(&tmp, &out)?;
        if let Err(e) = std::fs::rename(&tmp, &self.path) {
            let _ = std::fs::remove_file(&tmp);
            return Err(e.into());
        }
        self.evict();
        Ok(())
    }

    /// Mark this query as just used without rewriting it.
    pub fn touch(&self) {
        if let Ok(f) = std::fs::File::options().write(true).open(&self.path) {
            let _ = f.set_modified(SystemTime::now());
        }
    }

    fn evict(&self) {
        let Ok(rd) = std::fs::read_dir(&self.dir) else { return };
        let mut files: Vec<(SystemTime, u64, PathBuf)> = rd
            .flatten()
            .filter_map(|e| {
                let md = e.metadata().ok()?;
                Some((md.modified().unwrap_or(SystemTime::UNIX_EPOCH), md.len(), e.path()))
            })
            .collect();
        files.sort_by_key(|f| std::cmp::Reverse(f.0));
        let mut total = 0u64;
        for (_, len, p) in files {
            total += len;
            if total > MAX_BYTES && p != self.path {
                let _ = std::fs::remove_file(&p);
            }
        }
    }
}

fn decode(b: &[u8], header: &[u8]) -> Result<HashMap<Key, Vec<Capture>>> {
    let mut r = Reader { b, pos: 0 };
    if r.take(header.len())? != header {
        bail!("another query or version");
    }
    let n = r.u64()?;
    let mut out = HashMap::new();
    for _ in 0..n {
        let k: Key = r.take(16)?.try_into()?;
        let ncaps = r.u32()?;
        let mut caps = Vec::new();
        for _ in 0..ncaps {
            let line = r.u64()? as i64;
            let column = r.u64()? as i64;
            let capture = r.string()?;
            let kind = r.string()?;
            let text = r.string()?;
            caps.push(Capture { path: String::new(), line, column, capture, kind, text });
        }
        out.insert(k, caps);
    }
    if r.pos != b.len() {
        bail!("trailing bytes");
    }
    Ok(out)
}

struct Reader<'a> {
    b: &'a [u8],
    pos: usize,
}

impl<'a> Reader<'a> {
    fn take(&mut self, n: usize) -> Result<&'a [u8]> {
        let Some(s) = self.b.get(self.pos..self.pos.saturating_add(n)) else { bail!("truncated") };
        self.pos += n;
        Ok(s)
    }
    fn u32(&mut self) -> Result<u32> {
        Ok(u32::from_le_bytes(self.take(4)?.try_into()?))
    }
    fn u64(&mut self) -> Result<u64> {
        Ok(u64::from_le_bytes(self.take(8)?.try_into()?))
    }
    fn string(&mut self) -> Result<String> {
        let n = self.u32()? as usize;
        Ok(String::from_utf8(self.take(n)?.to_vec())?)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trip_and_damage() {
        let root = std::env::temp_dir().join(format!("scrutate_tscache_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).unwrap();
        let c = Cache::open(&root, "c", "(identifier) @i", &[]);
        assert!(c.entries.is_empty());
        let cap = Capture { path: String::new(), line: 3, column: 7, capture: "i".into(), kind: "identifier".into(), text: "kmalloc".into() };
        let entries = HashMap::from([(hash(&[b"a"]), vec![cap.clone(), cap]), (hash(&[b"b"]), vec![])]);
        c.store(&entries).unwrap();
        let again = Cache::open(&root, "c", "(identifier) @i", &[]);
        assert_eq!(again.entries.len(), 2);
        assert_eq!(again.entries[&hash(&[b"a"])][1].text, "kmalloc");
        assert!(Cache::open(&root, "c", "(identifier) @other", &[]).entries.is_empty(), "keyed by the query text");
        let bytes = std::fs::read(&c.path).unwrap();
        std::fs::write(&c.path, &bytes[..bytes.len() - 3]).unwrap();
        assert!(Cache::open(&root, "c", "(identifier) @i", &[]).entries.is_empty(), "a damaged file reads as empty");
        std::fs::remove_dir_all(&root).unwrap();
    }
}

//! `scrutate watch` and `serve --watch`: keep the index fresh from filesystem events. Bursts of
//! events are debounced, and each burst runs an incremental update (which takes the indexes' write
//! locks, so a crash mid-update is harmless). The indexes' own walks decide what a burst holds: a
//! burst that names files lists their directories with those walks and updates the files listed.
//! One that touches a directory or a rule file, loses events, or comes while a directory has no
//! watch or the last walk is old walks the tree and updates everything.

#[cfg_attr(target_os = "macos", allow(unused_imports))]
use std::collections::{BTreeSet, HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
#[cfg(not(target_os = "macos"))]
use std::sync::mpsc::{self, RecvTimeoutError};
use std::time::{Duration, Instant};

#[cfg(not(target_os = "macos"))]
use anyhow::bail;
use anyhow::{Context, Result};
#[cfg_attr(target_os = "macos", allow(unused_imports))]
use notify::{event::ModifyKind, Event, EventKind};
#[cfg(not(target_os = "macos"))]
use notify::{RecursiveMode, Watcher};

#[cfg_attr(target_os = "macos", allow(unused_imports))]
use crate::files::{CodeWalk, INDEX_DIR};
use crate::stores::{Changes, Named};

/// A burst of events ends after this much quiet.
pub const DEBOUNCE: Duration = Duration::from_millis(200);
/// A burst that never goes quiet is still flushed this often.
#[cfg(not(target_os = "macos"))]
const MAX_WAIT: Duration = Duration::from_secs(2);
/// A burst walks the tree once the last walk is this old: no event reports a directory made while
/// its parent's watch was being set, or events the OS or notify dropped without saying so.
#[cfg_attr(target_os = "macos", allow(dead_code))]
const WALK_EVERY: Duration = Duration::from_secs(30);

fn has_text_index(root: &Path) -> bool {
    crate::textindex::exists(root)
}

/// Under the root, and not the root itself, the index directory or `.git`.
#[cfg_attr(target_os = "macos", allow(dead_code))]
fn inside(root: &Path, p: &Path) -> bool {
    p.strip_prefix(root).ok().and_then(|r| r.components().next()).is_some_and(|c| c.as_os_str() != INDEX_DIR && c.as_os_str() != ".git")
}

/// git's `info/exclude` for the repository holding `root`. A linked worktree's `.git` is a file
/// naming its git directory, whose `commondir` names the main repository's, as the walk reads it.
#[cfg_attr(target_os = "macos", allow(dead_code))]
fn git_exclude(root: &Path) -> Option<PathBuf> {
    let top = root.ancestors().find(|a| a.join(".git").exists())?;
    let git = top.join(".git");
    let dir = if git.is_dir() {
        git
    } else {
        let text = std::fs::read_to_string(&git).ok()?;
        let gitdir = top.join(text.trim().strip_prefix("gitdir:")?.trim());
        match std::fs::read_to_string(gitdir.join("commondir")) {
            Ok(c) => gitdir.join(c.trim()),
            Err(_) => gitdir,
        }
    };
    Some(std::fs::canonicalize(dir).ok()?.join("info").join("exclude"))
}

/// The rule files the walks read that are not ignore files inside the tree: those of each
/// directory above the root (`.gitignore` only up to the repository top), git's exclude file of
/// the repository and of each one in `dirs`, and git's global excludes file.
#[cfg_attr(target_os = "macos", allow(dead_code))]
fn outer_rules<'a>(root: &Path, dirs: impl Iterator<Item = &'a PathBuf>) -> HashSet<PathBuf> {
    let top = root.ancestors().find(|a| a.join(".git").exists());
    let mut rules = HashSet::new();
    for a in root.ancestors().skip(1) {
        rules.extend([a.join(".ignore"), a.join(crate::instant::RGIGNORE)]);
        if top.is_some_and(|t| a.starts_with(t)) {
            rules.insert(a.join(".gitignore"));
        }
    }
    rules.extend(git_exclude(root));
    rules.extend(dirs.filter(|d| *d != root && d.join(".git").exists()).filter_map(|d| git_exclude(d)));
    // the walks apply the global file inside a repository only
    if top.is_some() {
        // as an event names it: its directory resolved, and no entry when that does not exist
        let named = |p: PathBuf| Some(std::fs::canonicalize(p.parent()?).ok()?.join(p.file_name()?));
        rules.extend(ignore::gitignore::gitconfig_excludes_path().and_then(named));
        // and the configuration files that say where it is
        let var = |k: &str| std::env::var_os(k).filter(|v| !v.is_empty()).map(PathBuf::from);
        let home = var(if cfg!(windows) { "USERPROFILE" } else { "HOME" });
        let config = match var("GIT_CONFIG_GLOBAL") {
            Some(file) => vec![file],
            None => {
                let xdg = var("XDG_CONFIG_HOME").or_else(|| home.as_ref().map(|h| h.join(".config")));
                home.iter().map(|h| h.join(".gitconfig")).chain(xdg.map(|x| x.join("git").join("config"))).collect()
            }
        };
        rules.extend(config.into_iter().filter_map(named));
    }
    rules
}

/// What the last walk of the tree found.
#[cfg_attr(target_os = "macos", allow(dead_code))]
struct Walked {
    /// the directories each index's walk enters; none for the text index when there is none
    code: HashSet<PathBuf>,
    text: HashSet<PathBuf>,
    text_index: bool,
    /// `outer_rules`
    rules: HashSet<PathBuf>,
    at: Instant,
    /// directories the walks enter that got no watch
    unwatched: usize,
    /// directories that hold only rule files and got no watch
    #[cfg_attr(not(target_os = "linux"), allow(dead_code))]
    unwatched_rules: usize,
}

#[cfg_attr(target_os = "macos", allow(dead_code))]
impl Walked {
    fn new(root: &Path, code: &CodeWalk) -> Walked {
        let text_index = has_text_index(root);
        let code: HashSet<PathBuf> =
            code.builder(root).build().flatten().filter(|e| e.file_type().is_some_and(|t| t.is_dir())).map(|e| e.into_path()).collect();
        let text: HashSet<PathBuf> = if text_index { crate::textindex::walk_entries(root, None).0.into_iter().collect() } else { HashSet::new() };
        let rules = outer_rules(root, code.union(&text));
        Walked { code, text, text_index, rules, at: Instant::now(), unwatched: 0, unwatched_rules: 0 }
    }

    fn holds(&self, dir: &Path) -> bool {
        self.code.contains(dir) || self.text.contains(dir)
    }

    /// The directories of `rules` that no walk enters.
    fn rule_dirs(&self) -> HashSet<PathBuf> {
        self.rules.iter().filter_map(|r| r.parent()).filter(|d| !self.holds(d) && d.is_dir()).map(Path::to_path_buf).collect()
    }

    /// Every directory either walk enters, and those of `rule_dirs`.
    fn watched(&self) -> HashSet<PathBuf> {
        let mut all: HashSet<PathBuf> = self.code.union(&self.text).cloned().collect();
        all.extend(self.rule_dirs());
        all
    }

    /// Whether a burst walks the tree whatever it names.
    fn due(&self, root: &Path) -> bool {
        // a change in a directory without a watch sends no event
        self.unwatched > 0 || self.at.elapsed() >= WALK_EVERY || self.text_index != has_text_index(root)
    }

    /// Whether `path` holds rules for what is indexed: an ignore file in the tree, one of `rules`,
    /// or a `.scrutate.toml`.
    fn sets_rules(&self, root: &Path, path: &Path) -> bool {
        self.rules.contains(path)
            || inside(root, path)
                && path.file_name().is_some_and(|n| [".gitignore", ".ignore", crate::instant::RGIGNORE, ".scrutate.toml"].iter().any(|r| n == *r))
    }
}

/// One directory as each index's walk lists it.
#[derive(Default)]
#[cfg_attr(target_os = "macos", allow(dead_code))]
struct Listing {
    dirs: HashSet<PathBuf>,
    code: HashSet<PathBuf>,
    text: HashSet<PathBuf>,
}

#[cfg_attr(target_os = "macos", allow(dead_code))]
impl Listing {
    fn of(dir: &Path, code: &CodeWalk, walked: &Walked) -> Listing {
        let mut l = Listing::default();
        if walked.code.contains(dir) {
            for e in code.builder(dir).max_depth(Some(1)).build().flatten().filter(|e| e.depth() == 1) {
                if e.file_type().is_some_and(|t| t.is_dir()) {
                    l.dirs.insert(e.into_path());
                } else if code.keeps(&e).is_some() {
                    l.code.insert(e.into_path());
                }
            }
        }
        if walked.text.contains(dir) {
            let (dirs, files) = crate::textindex::walk_entries(dir, Some(1));
            l.dirs.extend(dirs.into_iter().filter(|d| d != dir));
            l.text.extend(files);
        }
        l
    }
}

/// What the events of one burst ask for.
#[derive(Default)]
#[cfg_attr(target_os = "macos", allow(dead_code))]
struct Burst {
    /// a rule file or lost events: walk the tree and update everything
    full: bool,
    /// changed paths under the root
    paths: BTreeSet<PathBuf>,
    /// those of them created, removed or renamed
    moved: HashSet<PathBuf>,
}

#[cfg_attr(target_os = "macos", allow(dead_code))]
impl Burst {
    /// Take one event in; -> whether it names anything that may matter.
    fn note(&mut self, root: &Path, walked: &Walked, ev: &notify::Result<Event>) -> bool {
        let e = match ev {
            // the watch limit or a lost queue: the walk and the full update recover
            Err(e) => {
                eprintln!("[scrutate] file watcher: {e}");
                self.full = true;
                return true;
            }
            // inotify's queue overflowed (IN_Q_OVERFLOW): events were lost
            Ok(e) if e.need_rescan() => {
                self.full = true;
                return true;
            }
            // reads (the update's own included) are not changes
            Ok(Event { kind: EventKind::Access(_), .. }) => return false,
            Ok(e) => e,
        };
        let moved = !matches!(e.kind, EventKind::Modify(ModifyKind::Data(_) | ModifyKind::Metadata(_) | ModifyKind::Any));
        let mut wanted = false;
        for p in &e.paths {
            if walked.sets_rules(root, p) {
                self.full = true;
                wanted = true;
            } else if inside(root, p) {
                if moved {
                    self.moved.insert(p.clone());
                }
                self.paths.insert(p.clone());
                wanted = true;
            }
        }
        wanted
    }

    /// The burst's files for each index, as the walks list their directories; None when a
    /// directory the walks enter came, went or was replaced, so the tree must be walked.
    fn files(&self, root: &Path, code: &CodeWalk, walked: &Walked) -> Option<Named> {
        let mut listed: HashMap<&Path, Listing> = HashMap::new();
        let mut out = Named::default();
        for p in &self.paths {
            let Some(parent) = p.parent() else { continue };
            let md = std::fs::symlink_metadata(p).ok();
            let is_dir = md.as_ref().is_some_and(|m| m.is_dir());
            if walked.holds(p) {
                // a directory's own write time (Windows reports one per entry added or removed):
                // the entry has an event of its own
                if is_dir && !self.moved.contains(p) {
                    continue;
                }
                return None;
            }
            if !walked.holds(parent) {
                continue;
            }
            let l = listed.entry(parent).or_insert_with(|| Listing::of(parent, code, walked));
            if is_dir {
                if l.dirs.contains(p) {
                    return None;
                }
                continue;
            }
            let Ok(rel) = p.strip_prefix(root) else { continue };
            let rel = rel.components().map(|c| c.as_os_str().to_string_lossy().into_owned()).collect::<Vec<_>>().join("/");
            let gone = !md.is_some_and(|m| m.is_file());
            if gone || l.code.contains(p) {
                out.code.push(rel.clone());
            }
            if gone || l.text.contains(p) {
                out.text.push(rel);
            }
        }
        Some(out)
    }
}

fn root_present(root: &Path) -> Result<()> {
    if !root.is_dir() {
        anyhow::bail!("{} is gone: the watched directory was removed or moved", root.display());
    }
    Ok(())
}

/// The order watches are set in: the root first (the watch ends without it), then shallow
/// directories before deep ones and by path, so at the watch limit a tree keeps the same watches.
#[cfg_attr(not(target_os = "linux"), allow(dead_code))]
fn watch_order(root: &Path, dirs: &HashSet<PathBuf>) -> Vec<PathBuf> {
    let mut v: Vec<PathBuf> = dirs.iter().filter(|d| *d != root).cloned().collect();
    v.sort_by_cached_key(|d| (d.components().count(), d.clone()));
    v.insert(0, root.to_path_buf());
    v
}

/// Linux: walk the tree and set one non-recursive inotify watch per directory the walks enter, so
/// ignored trees cost no watches; new directories get a watch and ones that left lose theirs. Only
/// an error on `root` itself is returned.
#[cfg(target_os = "linux")]
fn sync_watches(watcher: &mut impl Watcher, root: &Path, code: &CodeWalk, old: Option<&Walked>) -> Result<Walked> {
    let mut now = Walked::new(root, code);
    let dirs = now.watched();
    if let Some(old) = old {
        // removals first: a directory moved inside the tree has one inotify watch under both names
        for gone in old.watched().difference(&dirs) {
            let _ = watcher.unwatch(gone);
        }
    }
    // notify drops the watches of moved and deleted directories itself, and a lost queue or the
    // limit may have dropped others, so every directory is watched again (inotify merges repeats)
    // directories that only hold rule files come last, so at the watch limit they lose first
    let rule_dirs = now.rule_dirs();
    let tree: HashSet<PathBuf> = dirs.difference(&rule_dirs).cloned().collect();
    let mut order = watch_order(root, &tree);
    let mut rules_order: Vec<PathBuf> = rule_dirs.into_iter().collect();
    rules_order.sort();
    let tree_dirs = order.len();
    order.extend(rules_order);
    watcher.watch(root, RecursiveMode::NonRecursive).with_context(|| format!("watch {}", root.display()))?;
    let (mut first, mut first_rules) = (None, None);
    for (i, d) in order.iter().enumerate().skip(1) {
        if let Err(e) = watcher.watch(d, RecursiveMode::NonRecursive) {
            if i < tree_dirs {
                now.unwatched += 1;
                first.get_or_insert(e);
            } else {
                // not counted in `unwatched`: such a directory would make every burst walk
                now.unwatched_rules += 1;
                first_rules.get_or_insert(e);
            }
        }
    }
    if let Some(e) = first.filter(|_| old.is_none_or(|o| o.unwatched != now.unwatched)) {
        eprintln!(
            "[scrutate] could not watch {} of {} directories ({e}); while any is unwatched, every change to an indexed file walks the tree, so a change in one of them is indexed with the next change elsewhere",
            now.unwatched, tree_dirs
        );
    }
    if let Some(e) = first_rules.filter(|_| old.is_none_or(|o| o.unwatched_rules != now.unwatched_rules)) {
        eprintln!(
            "[scrutate] could not watch {} of {} directories that only hold ignore rules ({e}); a change to those rules applies with the next walk of the tree",
            now.unwatched_rules,
            order.len() - tree_dirs
        );
    }
    Ok(now)
}

/// Windows: one recursive watch on the root (`ReadDirectoryChangesW`), plus one non-recursive watch
/// per directory outside the root that holds rule files the walks read. The walk only records the
/// directories.
#[cfg(all(not(target_os = "linux"), not(target_os = "macos")))]
fn sync_watches(watcher: &mut impl Watcher, root: &Path, code: &CodeWalk, old: Option<&Walked>) -> Result<Walked> {
    let now = Walked::new(root, code);
    if old.is_none() {
        watcher.watch(root, RecursiveMode::Recursive).with_context(|| format!("watch {}", root.display()))?;
    }
    let before = old.map(Walked::watched).unwrap_or_default();
    for d in now.watched().iter().filter(|d| !d.starts_with(root) && !before.contains(*d)) {
        let _ = watcher.watch(d, RecursiveMode::NonRecursive);
    }
    Ok(now)
}

/// `SCRUTATE_WATCH_DEBUG`: one line on stderr per burst, saying what it costs.
#[cfg(not(target_os = "macos"))]
fn debug() -> bool {
    std::env::var_os("SCRUTATE_WATCH_DEBUG").is_some_and(|v| !v.is_empty())
}

/// Watch `root` until `stop` is set. Once the watch is in place `on_change` runs, then `on_ready`;
/// after that `on_change` runs once per debounced burst that changes what an index holds, with the
/// burst's change set: the files it names when it does not walk the tree. An error from the first
/// `on_change`, or the root going away, ends the watch; later update errors are reported.
#[cfg(not(target_os = "macos"))]
pub fn run(root: &Path, stop: &AtomicBool, on_ready: impl FnOnce(), mut on_change: impl FnMut(&Changes) -> Result<()>) -> Result<()> {
    let root = std::fs::canonicalize(root).with_context(|| format!("watch {}", root.display()))?;
    let (tx, rx) = mpsc::channel();
    let mut watcher = notify::recommended_watcher(tx).context("start the file watcher")?;
    let code = CodeWalk::new(&root);
    let mut walked = sync_watches(&mut watcher, &root, &code, None)?;
    on_change(&Changes::All)?;
    on_ready();
    let debug = debug();
    while !stop.load(Ordering::Relaxed) {
        root_present(&root)?;
        let ev = match rx.recv_timeout(Duration::from_millis(250)) {
            Ok(ev) => ev,
            Err(RecvTimeoutError::Timeout) => continue,
            Err(RecvTimeoutError::Disconnected) => bail!("the file watcher stopped"),
        };
        let mut burst = Burst::default();
        if !burst.note(&root, &walked, &ev) {
            continue;
        }
        let t0 = Instant::now();
        while t0.elapsed() < MAX_WAIT {
            match rx.recv_timeout(DEBOUNCE) {
                Ok(ev) => {
                    burst.note(&root, &walked, &ev);
                }
                Err(_) => break,
            }
        }
        root_present(&root)?;
        let files = if burst.full { None } else { burst.files(&root, &code, &walked) };
        if files.as_ref().is_some_and(|f| f.code.is_empty() && f.text.is_empty()) {
            continue;
        }
        let named = files.filter(|_| !walked.due(&root));
        if named.is_none() {
            walked = sync_watches(&mut watcher, &root, &code, Some(&walked))?;
        }
        if debug {
            eprintln!("[scrutate] burst: {} paths, full walk: {}", burst.paths.len(), if named.is_none() { "yes" } else { "no" });
        }
        if let Err(e) = on_change(&named.map_or(Changes::All, Changes::Named)) {
            eprintln!("[scrutate] update failed: {e:#}");
        }
    }
    Ok(())
}

/// macOS: the FSEvents backend would link CoreServices into every scrutate command (about 1 ms of
/// start-up and 4 MB), and a poller that compares whole-second modification times misses quick
/// edits. So the index's own incremental check runs on a timer: it compares sizes and nanosecond
/// times, and the pause grows with what a check costs (about a tenth of the time at most).
#[cfg(target_os = "macos")]
pub fn run(root: &Path, stop: &AtomicBool, on_ready: impl FnOnce(), mut on_change: impl FnMut(&Changes) -> Result<()>) -> Result<()> {
    let root = std::fs::canonicalize(root).with_context(|| format!("watch {}", root.display()))?;
    on_change(&Changes::All)?;
    on_ready();
    let mut pause = Duration::from_secs(1);
    while !stop.load(Ordering::Relaxed) {
        let t0 = Instant::now();
        while t0.elapsed() < pause && !stop.load(Ordering::Relaxed) {
            std::thread::sleep(Duration::from_millis(100));
        }
        if stop.load(Ordering::Relaxed) {
            break;
        }
        root_present(&root)?;
        let t1 = Instant::now();
        if let Err(e) = on_change(&Changes::All) {
            eprintln!("[scrutate] update failed: {e:#}");
        }
        pause = (t1.elapsed() * 10).clamp(Duration::from_secs(1), Duration::from_secs(30));
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use notify::event::{CreateKind, DataChange, ModifyKind, RemoveKind, RenameMode};

    /// A repository with a text index (its manifest is enough for the walks).
    fn tree(name: &str) -> PathBuf {
        let root = std::env::temp_dir().join(format!("scrutate_burst_{name}_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        for d in [".git/info", "src/deep", "gone_dir", ".scrutate/text"] {
            std::fs::create_dir_all(root.join(d)).unwrap();
        }
        std::fs::write(root.join(".scrutate/text/manifest.json"), "{}").unwrap();
        std::fs::write(root.join(".gitignore"), "*.tmp\ngen/\n").unwrap();
        std::fs::write(root.join("src/a.py"), "x\n").unwrap();
        std::fs::canonicalize(&root).unwrap()
    }

    fn ev(kind: EventKind, paths: &[&Path]) -> notify::Result<Event> {
        let mut e = Event::new(kind);
        for p in paths {
            e = e.add_path(p.to_path_buf());
        }
        Ok(e)
    }

    /// The walk of the tree as it is now, then these events; -> the burst's files, None when it
    /// walks the tree. `change` runs between the walk and the events.
    fn burst(root: &Path, change: impl FnOnce(), events: &[notify::Result<Event>]) -> Option<Named> {
        let code = CodeWalk::new(root);
        let walked = Walked::new(root, &code);
        change();
        let mut b = Burst::default();
        for e in events {
            b.note(root, &walked, e);
        }
        if b.full {
            return None;
        }
        b.files(root, &code, &walked)
    }

    fn both(paths: &[&str]) -> Option<Named> {
        let v: Vec<String> = paths.iter().map(|p| p.to_string()).collect();
        Some(Named { code: v.clone(), text: v })
    }

    #[test]
    fn a_burst_of_file_events_names_its_files() {
        let root = tree("files");
        let modify = EventKind::Modify(ModifyKind::Data(DataChange::Any));
        let a = root.join("src/a.py");
        assert_eq!(burst(&root, || (), &[ev(modify, &[&a])]), both(&["src/a.py"]));
        // Windows names no kind of entry: the path is looked at
        let created = root.join("src/deep/b.py");
        let write = || std::fs::write(&created, "y\n").unwrap();
        assert_eq!(burst(&root, write, &[ev(EventKind::Create(CreateKind::Any), &[&created])]), both(&["src/deep/b.py"]));
        let tmp = root.join("src/.a.py.swp");
        let rename = EventKind::Modify(ModifyKind::Name(RenameMode::Both));
        assert_eq!(burst(&root, || (), &[ev(rename, &[&tmp, &a])]), both(&["src/.a.py.swp", "src/a.py"]));
        let removed = root.join("src/old.py");
        assert_eq!(burst(&root, || (), &[ev(EventKind::Remove(RemoveKind::Any), &[&removed])]), both(&["src/old.py"]));
        // ignored files, the index's own files, reads and files in directories no walk enters
        // name nothing
        std::fs::write(root.join("src/x.tmp"), "x\n").unwrap();
        std::fs::create_dir_all(root.join("gen")).unwrap();
        std::fs::write(root.join("gen/g.py"), "x\n").unwrap();
        std::fs::create_dir_all(root.join("src/new.tmp")).unwrap();
        for e in [
            ev(modify, &[&root.join("src/x.tmp")]),
            ev(modify, &[&root.join("gen/g.py")]),
            ev(EventKind::Access(notify::event::AccessKind::Any), &[&a]),
            ev(modify, &[&root.join(".scrutate/index.db")]),
            ev(modify, &[&root.join(".git/index")]),
            // Windows: the write time of a directory an entry was added to
            ev(EventKind::Modify(ModifyKind::Any), &[&root.join("src")]),
            // a new directory the walks do not enter
            ev(EventKind::Create(CreateKind::Folder), &[&root.join("src/new.tmp")]),
        ] {
            assert_eq!(burst(&root, || (), &[e]), Some(Named::default()));
        }
        std::fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn directories_rules_and_lost_events_walk_the_tree() {
        let modify = EventKind::Modify(ModifyKind::Any);
        type Change = fn(&Path);
        let cases: [(&str, Change, EventKind, &str); 12] = [
            (
                "a directory moved away and another made in its place",
                |r| std::fs::rename(r.join("src/deep"), r.join("src/deeper")).and_then(|_| std::fs::create_dir(r.join("src/deep"))).unwrap(),
                EventKind::Create(CreateKind::Folder),
                "src/deep",
            ),
            ("a new directory (inotify)", |r| std::fs::create_dir(r.join("src/x")).unwrap(), EventKind::Create(CreateKind::Folder), "src/x"),
            ("a new directory (Windows)", |r| std::fs::create_dir(r.join("src/y")).unwrap(), EventKind::Create(CreateKind::Any), "src/y"),
            ("a removed directory the walk found", |r| std::fs::remove_dir(r.join("gone_dir")).unwrap(), EventKind::Remove(RemoveKind::Any), "gone_dir"),
            (
                "a directory renamed away",
                |r| std::fs::rename(r.join("src/deep"), r.join("src/deeper")).unwrap(),
                EventKind::Modify(ModifyKind::Name(RenameMode::From)),
                "src/deep",
            ),
            (
                "a directory replaced by a file",
                |r| std::fs::remove_dir(r.join("gone_dir")).and_then(|_| std::fs::write(r.join("gone_dir"), "x")).unwrap(),
                modify,
                "gone_dir",
            ),
            ("an ignore file", |_| (), modify, "src/.ignore"),
            ("a .gitignore", |_| (), modify, ".gitignore"),
            ("git's exclude", |_| (), modify, ".git/info/exclude"),
            ("the configuration file", |_| (), modify, ".scrutate.toml"),
            ("a ripgrep ignore file", |_| (), modify, ".rgignore"),
            ("a removed .gitignore", |_| (), EventKind::Remove(RemoveKind::File), "src/deep/.gitignore"),
        ];
        for (what, change, kind, rel) in cases {
            let root = tree("full");
            let a = root.join("src/a.py");
            assert_eq!(burst(&root, || change(&root), &[ev(modify, &[&a]), ev(kind, &[&root.join(rel)])]), None, "{what}");
            std::fs::remove_dir_all(&root).unwrap();
        }
        let root = tree("lost");
        let a = root.join("src/a.py");
        for (what, e) in
            [("a lost queue", Ok(Event::new(EventKind::Other).set_flag(notify::event::Flag::Rescan))), ("a watcher error", Err(notify::Error::generic("test")))]
        {
            assert_eq!(burst(&root, || (), &[ev(modify, &[&a]), e]), None, "{what}");
        }
        std::fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn each_index_gets_the_files_its_walk_lists() {
        let root = tree("split");
        let names = ["src/a.py", "src/.hidden.py", "src/gone.py", "src/a.tmp", "src/img.png"];
        for name in names {
            std::fs::write(root.join(name), "x\n").unwrap();
        }
        std::fs::create_dir_all(root.join("node_modules/m")).unwrap();
        std::fs::write(root.join("node_modules/m/i.js"), "x\n").unwrap();
        let modify = EventKind::Modify(ModifyKind::Any);
        let gone = || std::fs::remove_file(root.join("src/gone.py")).unwrap();
        let mut events: Vec<_> = names.iter().map(|n| ev(modify, &[&root.join(n)])).collect();
        events.push(ev(modify, &[&root.join("node_modules/m/i.js")]));
        let f = burst(&root, gone, &events).unwrap();
        assert_eq!(f.code, ["src/.hidden.py", "src/a.py", "src/gone.py"]);
        assert_eq!(f.text, ["node_modules/m/i.js", "src/a.py", "src/gone.py", "src/img.png"]);
        std::fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn the_rules_of_a_nested_repository_decide_a_burst() {
        let root = tree("nested");
        std::fs::create_dir_all(root.join("vendor/lib/.git")).unwrap();
        std::fs::create_dir_all(root.join("vendor/lib/out")).unwrap();
        std::fs::write(root.join(".gitignore"), "*.gen.py\nout/\n").unwrap();
        std::fs::write(root.join("vendor/lib/x.gen.py"), "x\n").unwrap();
        std::fs::write(root.join("vendor/lib/out/o.py"), "x\n").unwrap();
        std::fs::write(root.join("src/y.gen.py"), "x\n").unwrap();
        let modify = EventKind::Modify(ModifyKind::Any);
        let events: Vec<_> = ["vendor/lib/x.gen.py", "vendor/lib/out/o.py", "src/y.gen.py"].iter().map(|n| ev(modify, &[&root.join(n)])).collect();
        assert_eq!(burst(&root, || (), &events), both(&["vendor/lib/out/o.py", "vendor/lib/x.gen.py"]));
        let code = CodeWalk::new(&root);
        let walked = Walked::new(&root, &code);
        assert!(walked.code.contains(&root.join("vendor/lib/out")) && walked.text.contains(&root.join("vendor/lib/out")));
        std::fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn a_linked_worktree_watches_the_exclude_file_of_its_main_repository() {
        let base = tree("wt");
        let main = base.join("main_repo/.git");
        std::fs::create_dir_all(main.join("info")).unwrap();
        std::fs::create_dir_all(main.join("worktrees/wt")).unwrap();
        std::fs::write(main.join("worktrees/wt/commondir"), "../..\n").unwrap();
        let wt = base.join("wt");
        std::fs::create_dir_all(&wt).unwrap();
        std::fs::write(wt.join(".git"), format!("gitdir: {}\n", main.join("worktrees/wt").display())).unwrap();
        assert_eq!(git_exclude(&wt), Some(main.join("info/exclude")));
        assert_eq!(git_exclude(&base.join("src")), Some(base.join(".git/info/exclude")));
        let walked = Walked::new(&wt, &CodeWalk::new(&wt));
        assert!(walked.watched().contains(&main.join("info")));
        assert!(walked.sets_rules(&wt, &main.join("info/exclude")));
        std::fs::remove_dir_all(&base).unwrap();
    }

    #[test]
    fn a_burst_walks_while_a_directory_has_no_watch_and_once_the_last_walk_is_old() {
        let root = tree("due");
        let mut w = Walked::new(&root, &CodeWalk::new(&root));
        assert!(!w.due(&root));
        w.unwatched = 1;
        assert!(w.due(&root), "a directory without a watch");
        w.unwatched = 0;
        if let Some(old) = Instant::now().checked_sub(WALK_EVERY) {
            w.at = old;
            assert!(w.due(&root), "an old walk");
            w.at = Instant::now();
        }
        std::fs::remove_file(root.join(".scrutate/text/manifest.json")).unwrap();
        assert!(w.due(&root), "the text index went away");
        std::fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn watches_are_set_root_first_then_shallow_directories_by_path() {
        let root = PathBuf::from("/r");
        let dirs: HashSet<PathBuf> = ["/r/b/c", "/r/a/z/y", "/r", "/r/b", "/r/a", "/r/a/z", "/r/c/a"].iter().map(PathBuf::from).collect();
        let order: Vec<String> = watch_order(&root, &dirs).iter().map(|p| p.display().to_string()).collect();
        assert_eq!(order, ["/r", "/r/a", "/r/b", "/r/a/z", "/r/b/c", "/r/c/a", "/r/a/z/y"]);
    }
}

//! The artifact store: content seen before, under any path, in this checkout or in the main
//! checkout of a linked git work tree, is not parsed again, and the index made from it equals a
//! fresh build of the same tree, row for row.

use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use scrutate::index::Index;
use scrutate::models::ModelSet;
use scrutate::search::Searcher;

struct Tmp(PathBuf);

impl Tmp {
    fn new(name: &str) -> Tmp {
        let p = std::env::temp_dir().join(format!("scrutate_artifacts_{}_{}", name, std::process::id()));
        let _ = fs::remove_dir_all(&p);
        fs::create_dir_all(&p).unwrap();
        Tmp(fs::canonicalize(&p).unwrap())
    }
}

impl Drop for Tmp {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn put(root: &Path, rel: &str, text: &str) {
    let p = root.join(rel);
    fs::create_dir_all(p.parent().unwrap()).unwrap();
    fs::write(p, text).unwrap();
}

fn py(i: usize) -> String {
    format!("import os\n\nclass Holder{i}:\n    def run_{i}(self, x):\n        return helper_{i}(x) + {i}\n\n\ndef helper_{i}(x):\n    \"\"\"Add one to x.\"\"\"\n    return os.path.join(str(x), 'v{i}')\n")
}

fn rs(i: usize) -> String {
    format!("pub fn parse_{i}(s: &str) -> usize {{\n    tokens_{i}(s).len()\n}}\n\nfn tokens_{i}(s: &str) -> Vec<&str> {{\n    s.split(' ').collect()\n}}\n")
}

/// Every file's chunks, call names and imports through the index's questions, without ids,
/// each chunk's field scores for words of every field (path words too) and its vector, and the
/// hits of a few ranked searches: what must equal between two indexes of one tree. A hit's score
/// is left out: the duplicate features tell copies apart by id, and an updated index holds other
/// ids than a fresh one, as it always did.
fn dump(ix: Index) -> String {
    let mut out = String::new();
    let mut ix = ix;
    let report = ix.check(true).unwrap();
    assert!(report.ok(), "{:?}", report.problems);
    let mut files = ix.files().unwrap();
    files.sort();
    let words = scrutate::search::QueryInfo::parse("helper join path parse tokens holder run split collect add one src lib other copy tests m0 r2 renamed");
    let keys = scrutate::search::lex_keys(&words);
    for f in &files {
        for c in ix.outline(f).unwrap() {
            let calls = ix.callees_of(c.id).unwrap();
            out += &format!(
                "{f} {} {} {} {}-{} test={} doc={} body={} tok={} calls={calls:?}\n{}\n",
                c.kind, c.name, c.qualname, c.start, c.end, c.is_test, c.ndoc, c.nbody, c.name_tok, c.text
            );
            if c.kind != "constant" {
                let lex = ix.lex().unwrap();
                let scores = lex.field_scores(&keys, &[c.id]).unwrap();
                let vec = lex.vec_of(c.id).unwrap().map(|(a, b)| a.iter().chain(&b).map(|x| format!("{x:.5}")).collect::<Vec<_>>().join(","));
                out += &format!("  scores {:?} vector {vec:?}\n", scores[0]);
            }
        }
        out += &format!("{f} imports {:?}\n", ix.imports_of(f).unwrap());
    }
    let mut s = Searcher::new(ix);
    for q in ["helper join path", "parse tokens", "Holder run", "split collect", "add one"] {
        let mut hits: Vec<String> = s.search(q, 1000, false).unwrap().iter().map(|h| format!("{q}: {} {}\n", h.path, h.start)).collect();
        hits.sort();
        out += &hits.concat();
    }
    out
}

/// Two dumps are equal; else the lines only one of them has.
#[track_caller]
fn same(a: &str, b: &str) {
    if a != b {
        let (la, lb): (Vec<&str>, Vec<&str>) = (a.lines().collect(), b.lines().collect());
        let only = |x: &[&str], y: &[&str]| x.iter().filter(|l| !y.contains(l)).take(8).map(|l| l.to_string()).collect::<Vec<_>>();
        panic!("dumps differ\nonly the first: {:#?}\nonly the second: {:#?}", only(&la, &lb), only(&lb, &la));
    }
}

/// A fresh index of a copy of `root`, dumped.
fn fresh(root: &Path, models: Arc<ModelSet>) -> String {
    let copy = PathBuf::from(format!("{}_fresh", root.display()));
    let _ = fs::remove_dir_all(&copy);
    copy_tree(root, &copy);
    let _ = fs::remove_dir_all(copy.join(".scrutate"));
    let _ = fs::remove_dir_all(copy.join(".git"));
    let mut ix = Index::open(&copy, models).unwrap();
    ix.update(false).unwrap();
    let d = dump(ix);
    fs::remove_dir_all(&copy).unwrap();
    d
}

fn copy_tree(from: &Path, to: &Path) {
    fs::create_dir_all(to).unwrap();
    for e in fs::read_dir(from).unwrap().flatten() {
        let dest = to.join(e.file_name());
        if e.file_type().unwrap().is_dir() {
            copy_tree(&e.path(), &dest);
        } else {
            fs::copy(e.path(), dest).unwrap();
        }
    }
}

fn open(root: &Path, models: &Arc<ModelSet>) -> Index {
    Index::open(root, Arc::clone(models)).unwrap()
}

#[test]
fn renamed_moved_and_copied_files_are_not_parsed_again_and_the_index_equals_a_fresh_build() {
    for models in [ModelSet::none(), ModelSet::from_env()] {
        let t = Tmp::new(if models.semantic_enabled() { "rename_model" } else { "rename" });
        for i in 0..6 {
            put(&t.0, &format!("src/m{i}.py"), &py(i));
            put(&t.0, &format!("lib/r{i}.rs"), &rs(i));
        }
        let mut ix = open(&t.0, &models);
        ix.update(false).unwrap();
        assert_eq!(ix.parsed, 12);
        // moved to another directory, renamed within one, copied, two contents swapped, and moved
        // into a test directory, which changes the flag; a file under another name is parsed, since
        // the module chunk and the windows take their name from it
        fs::create_dir_all(t.0.join("other")).unwrap();
        fs::rename(t.0.join("src/m0.py"), t.0.join("other/m0.py")).unwrap();
        fs::rename(t.0.join("src/m1.py"), t.0.join("src/renamed.py")).unwrap();
        put(&t.0, "copy/m2.py", &py(2));
        put(&t.0, "lib/r0.rs", &rs(1));
        put(&t.0, "lib/r1.rs", &rs(0));
        fs::create_dir_all(t.0.join("tests")).unwrap();
        fs::rename(t.0.join("lib/r2.rs"), t.0.join("tests/r2.rs")).unwrap();
        ix.update(false).unwrap();
        assert_eq!(ix.parsed, 15, "only the files under another name are parsed: renamed.py and the swapped r0.rs, r1.rs");
        same(&dump(ix), &fresh(&t.0, Arc::clone(&models)));
    }
}

#[test]
fn a_branch_switch_and_back_parses_only_what_the_store_never_held() {
    let t = Tmp::new("switch");
    let models = ModelSet::none();
    for i in 0..8 {
        put(&t.0, &format!("m{i}.py"), &py(i));
    }
    let mut ix = open(&t.0, &models);
    ix.update(false).unwrap();
    let main = dump(open(&t.0, &models));
    // the other branch: three files edited, one deleted, one added
    for i in 0..3 {
        put(&t.0, &format!("m{i}.py"), &py(100 + i));
    }
    fs::remove_file(t.0.join("m7.py")).unwrap();
    put(&t.0, "new.py", &py(200));
    ix.update(false).unwrap();
    assert_eq!(ix.parsed, 8 + 4);
    let branch = dump(open(&t.0, &models));
    same(&branch, &fresh(&t.0, Arc::clone(&models)));
    // back: the old contents come from the store
    for i in 0..3 {
        put(&t.0, &format!("m{i}.py"), &py(i));
    }
    put(&t.0, "m7.py", &py(7));
    fs::remove_file(t.0.join("new.py")).unwrap();
    ix.update(false).unwrap();
    assert_eq!(ix.parsed, 12, "the switch back parses nothing");
