    assert_eq!((code, sorted_lines(&out)), (0, vec!["./game/level.gd".to_string(), "./game/player.gd".into(), "./game/scoring.gd".into()]), "{out}");
    let (code, out, _) = r.run(&["grep", "--type", "py", "-l", "clamp_health", "."]);
