    let mut child = Command::new(BIN).arg("serve").current_dir(&deep).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().unwrap();
    let mut stdin = child.stdin.take().unwrap();
    for m in [
