    r.write("a.txt", b"def get_value(x):\ndef set_valu(y):\ndef fetch_all():\n");
    let (code, out, _) = r.run(&["grep", "--fuzzy-regex=1", "(get|set)_value", "a.txt"]);
    assert_eq!((code, out.as_str()), (0, "1:def get_value(x):\n2:def set_valu(y):\n"));
