//! `response_format: concise` on every MCP tool, run on a copy of this crate's own source: the
//! concise answer lists the locations the detailed one lists, in at most half its bytes when the
//! detailed one is over 1 KB.

use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use scrutate::session::{Every, Session};
use serde_json::{json, Value};

/// git's own configuration is the only one read: no global or system file.
const GIT_ENV: [(&str, &str); 2] = [("GIT_CONFIG_GLOBAL", "/dev/null"), ("GIT_CONFIG_NOSYSTEM", "1")];

fn copy(from: &Path, to: &Path) {
    fs::create_dir_all(to).unwrap();
    for e in fs::read_dir(from).unwrap() {
        let e = e.unwrap();
        let (src, dst) = (e.path(), to.join(e.file_name()));
        if e.file_type().unwrap().is_dir() {
            copy(&src, &dst);
        } else {
            fs::copy(&src, &dst).unwrap();
        }
    }
}

fn git(root: &Path, args: &[&str]) {
    let mut c = Command::new("git");
    c.args(["-c", "user.name=t", "-c", "user.email=t@t", "-c", "commit.gpgsign=false", "-c", "init.defaultBranch=main", "-c", "core.autocrlf=false"]);
    let out = c.args(args).current_dir(root).envs(GIT_ENV).stdin(Stdio::null()).output().unwrap();
    assert!(out.status.success(), "git {args:?}: {}", String::from_utf8_lossy(&out.stderr));
}

/// A git repository holding this crate's `src` and `tests` at their paths in the repository, with
/// one edited function in the working tree.
fn tree() -> PathBuf {
    let root = Path::new(env!("CARGO_TARGET_TMPDIR")).join(format!("concise_{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    let here = Path::new(env!("CARGO_MANIFEST_DIR"));
    for dir in ["src", "tests"] {
        copy(&here.join(dir), &root.join("crates/scrutate").join(dir));
    }
    git(&root, &["init", "-q"]);
    git(&root, &["add", "-A"]);
    git(&root, &["commit", "-qm", "base"]);
    let fmt = root.join("crates/scrutate/src/fmt.rs");
    let text = fs::read_to_string(&fmt).unwrap().replace("let mut out = Vec::with_capacity(hits.len());", "let mut out = Vec::with_capacity(hits.len() + 0);");
    fs::write(&fmt, text).unwrap();
    fs::canonicalize(root).unwrap()
}

/// Every `path:start-end` of a text. In a concise answer a line that ends with `/` names the
/// directory of the paths after it written without one (`./` is the root), and a location without
/// a path is in the file of the location before it. A quoted one is code, not a location.
fn locations(text: &str) -> BTreeSet<String> {
    let token = regex::Regex::new(r"(?:^|[\s(])([A-Za-z0-9_./-]*):(\d+)(-\d+|:\d+)?").unwrap();
    let (mut out, mut dir, mut last) = (BTreeSet::new(), String::new(), String::new());
    for line in text.lines() {
        if line.ends_with('/') && !line.contains(' ') {
            dir = if line == "./" { String::new() } else { line.trim_end_matches('/').to_string() };
            continue;
        }
        for m in token.captures_iter(line) {
            let mut path = m[1].to_string();
            if path.is_empty() {
                path = last.clone();
            } else if let Some(p) = path.strip_prefix("./") {
                path = p.to_string();
            } else if !path.contains('/') && !dir.is_empty() {
                path = format!("{dir}/{path}");
            }
            last = path.clone();
            if let Some(end) = m.get(3).map(|e| e.as_str()).filter(|e| e.starts_with('-')) {
                out.insert(format!("{path}:{}{end}", &m[2]));
            }
        }
    }
    out
}

#[test]
fn a_concise_answer_lists_the_same_locations_in_at_most_half_the_bytes() {
    let root = tree();
    let session = Session::open(&root, Every::given(Some(0.0))).unwrap();
    session.build().unwrap();
    let settings = scrutate::mcp::Settings::new(None);
    // the location of the definition whose line starts so
    let at = |file: &str, start: &str| {
        let path = format!("crates/scrutate/src/{file}");
        let text = fs::read_to_string(root.join(&path)).unwrap();
        format!("{path}:{}", text.lines().position(|l| l.starts_with(start)).unwrap() + 1)
    };
    let calls: Vec<(&str, Value)> = vec![
        ("search_code", json!({"query": "page an answer within a byte budget"})),
        ("search_code", json!({"query": "resolve a call to its definition", "k": 30})),
        ("grep_code", json!({"pattern": "fn text"})),
        ("grep_code", json!({"pattern": "max_bytes", "mode": "identifier"})),
        ("find_symbol", json!({"name": "run"})),
        ("callers", json!({"name": "shown"})),
        ("callees", json!({"name": at("ops.rs", "pub fn run(")})),
        ("callees", json!({"name": at("cli.rs", "pub fn run(")})),
        ("call_path", json!({"from": at("mcp.rs", "pub fn call_tool("), "to": "read_range"})),
        ("repo_map", json!({})),
        ("read_code", json!({"path": "crates/scrutate/src/ops.rs"})),
        ("read_code", json!({"symbol": "Parts.render"})),
        ("read_code", json!({"symbol": "Answer"})),
        ("outline", json!({"path": "crates/scrutate/src/ops.rs"})),
        ("dependencies", json!({"path": "crates/scrutate/src/cli.rs"})),
        ("dependents", json!({"target": "crates/scrutate/src/fmt.rs"})),
        ("references", json!({"name": "hit_blocks"})),
        ("references", json!({"name": "Answer", "textual": true})),
        ("similar_code", json!({"target": at("ops.rs", "pub fn stop_line("), "k": 50})),
        ("duplicates", json!({"threshold": 0.6, "limit": 200, "min_tokens": 15})),
        ("structural_search", json!({"lang": "rust", "query": "(function_item name: (identifier) @f)"})),
        ("impact", json!({})),
        ("find_files", json!({"query": "rs", "limit": 200})),
        ("dead_code", json!({})),
        ("reindex", json!({})),
    ];
    let mut tools = BTreeSet::new();
    let mut failed = Vec::new();
    eprintln!("{:<18} {:>8} {:>8} {:>6} {:>6}", "tool", "detailed", "concise", "ratio", "places");
    for (tool, args) in &calls {
        let call = |form: &str| {
            let mut args = args.clone();
            args["response_format"] = json!(form);
            let c = scrutate::mcp::call_tool(&session, tool, &args, &settings, &Default::default());
            assert!(!c.is_error, "{tool} {args}: {}", c.text);
            c.text
        };
        let (detailed, concise) = (call("detailed"), call("concise"));
        let (d, c) = (locations(&detailed), locations(&concise));
        eprintln!("{tool:<18} {:>8} {:>8} {:>6.2} {:>6}", detailed.len(), concise.len(), concise.len() as f64 / detailed.len() as f64, d.len());
        if d != c {
            failed.push(format!("{tool} {args}: locations differ: {:?} / {:?}", d.difference(&c).collect::<Vec<_>>(), c.difference(&d).collect::<Vec<_>>()));
        }
        if detailed.len() > 1024 && concise.len() * 2 > detailed.len() {
            failed.push(format!("{tool} {args}: {} bytes concise for {} detailed", concise.len(), detailed.len()));
        }
        tools.insert(*tool);
    }
    assert_eq!(tools.len(), 19, "every tool is called");
    assert!(failed.is_empty(), "{failed:#?}");
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn concise_paths_name_their_directory_once_and_a_bad_form_is_refused() {
    let root = Path::new(env!("CARGO_TARGET_TMPDIR")).join(format!("concise_small_{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(root.join("pkg/sub")).unwrap();
    // a root of its own, not the work tree above it
    fs::create_dir_all(root.join(".git")).unwrap();
    fs::write(root.join("pkg/a.py"), "def make_point():\n    return 1\n\n\ndef make_line():\n    return make_point()\n").unwrap();
    fs::write(root.join("pkg/sub/b.py"), "from pkg.a import make_point\n\n\ndef make_box():\n    return make_point()\n").unwrap();
    fs::write(root.join("top.py"), "from pkg.a import make_point\n\n\ndef make_top():\n    return make_point()\n").unwrap();
    let root = fs::canonicalize(&root).unwrap();
    let session = Session::open(&root, Every::given(Some(0.0))).unwrap();
    session.build().unwrap();
    let settings = scrutate::mcp::Settings::new(None);
    let call = |tool: &str, args: Value| scrutate::mcp::call_tool(&session, tool, &args, &settings, &Default::default());
    let c = call("callers", json!({"name": "make_point", "response_format": "concise"}));
    assert_eq!(c.text, "pkg/\na.py:5-6 make_line\npkg/sub/\nb.py:4-5 make_box\n./\ntop.py:4-5 make_top", "{}", c.text);
    let d = call("callers", json!({"name": "make_point"}));
    assert_eq!(locations(&c.text), locations(&d.text));
    assert_eq!(c.structured, d.structured, "the JSON is the detailed one in both forms");
    // a location in the file of the one before it leaves out the path
    let c = call("outline", json!({"path": "pkg/a.py", "response_format": "concise"}));
    assert_eq!(c.text, "1 make_point\n5 make_line");
    let c = call("find_symbol", json!({"name": "make_line", "response_format": "concise"}));
    assert_eq!(c.text, "pkg/\na.py:5-6 make_line");
    for bad in [json!("short"), json!(1)] {
        let c = call("find_symbol", json!({"name": "make_line", "response_format": bad}));
        assert!(c.is_error && c.text == "error: response_format must be \"detailed\" or \"concise\"", "{}", c.text);
    }
    // the same items on each page, so an offset means the same in both forms
    for offset in [0, 1, 2] {
        let page = |form: &str| call("callers", json!({"name": "make_point", "response_format": form, "max_bytes": 1000, "offset": offset})).text;
        assert_eq!(locations(&page("detailed")), locations(&page("concise")), "offset {offset}");
    }
    let _ = fs::remove_dir_all(&root);
}

//! A `[[language]]` table in a repository's `.scrutate.toml` or in the user's configuration file
//! adds a language: its files get symbols, outlines, ranked hits and a `--type`, `languages`
//! lists it, a change of the table reparses its files, and a bad table is one error with its line.

use std::fs;
use std::path::PathBuf;
use std::process::{Command, Stdio};

const BIN: &str = env!("CARGO_BIN_EXE_scrutate");

const TABLE: &str = r#"[[language]]
name = "mylang"
extensions = ["myl"]
line_comment = "--"
block_comment = ["{-", "-}"]
definitions = [
  { kind = "function", pattern = '^\s*fn\s+([A-Za-z_][A-Za-z0-9_]*)' },
  { kind = "class", pattern = '^\s*type\s+([A-Za-z_][A-Za-z0-9_]*)' },
]
"#;

const SOURCE: &str = "-- Shapes and their areas.\n\n-- The area of a circle of radius r.\nfn circle_area(r)\n  pi * r * r\nend\n\ntype Rectangle\n  width\n  height\nend\n\n{- Doubles a number. -}\nfn double(x)\n  x * 2\nend\n";

/// A repository with its own `.git`, and a scratch home, under the build's temporary directory.
struct Tree {
    base: PathBuf,
    root: PathBuf,
}

impl Tree {
    fn new(name: &str) -> Tree {
        let base = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(format!("custom_lang_{name}_{}", std::process::id()));
        let _ = fs::remove_dir_all(&base);
        let root = base.join("repo");
        fs::create_dir_all(root.join(".git")).unwrap();
        fs::create_dir_all(base.join("home/.config")).unwrap();
        let t = Tree { root: fs::canonicalize(&root).unwrap(), base: fs::canonicalize(&base).unwrap() };
        t.write("shapes.myl", SOURCE);
        t.write("other.py", "def circle_area_py(r):\n    return 3 * r * r\n");
        t
    }

    fn write(&self, rel: &str, text: &str) {
        let p = self.root.join(rel);
        fs::create_dir_all(p.parent().unwrap()).unwrap();
        fs::write(p, text).unwrap();
    }

    fn run(&self, args: &[&str]) -> (i32, String, String) {
        let home = self.base.join("home");
        let mut c = Command::new(BIN);
        c.args(args).current_dir(&self.root).stdin(Stdio::null()).env_remove("SCRUTATE_CONFIG").env_remove("SCRUTATE_ROOT");
        c.env("HOME", &home).env("XDG_CONFIG_HOME", home.join(".config")).env("XDG_STATE_HOME", home.join("state")).env("XDG_DATA_HOME", home.join("data"));
        c.env("SCRUTATE_SEMANTIC", "none");
        let out = c.output().expect("run scrutate");
        (out.status.code().unwrap_or(-1), String::from_utf8_lossy(&out.stdout).into_owned(), String::from_utf8_lossy(&out.stderr).into_owned())
    }

    fn json(&self, args: &[&str]) -> serde_json::Value {
        let (code, out, err) = self.run(args);
        assert_eq!(code, 0, "{args:?}: {out}{err}");
        serde_json::from_str(&out).unwrap_or_else(|e| panic!("{args:?}: {e}: {out}"))
    }
}

impl Drop for Tree {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.base);
    }
}

#[test]
fn a_language_from_the_repository_s_table_is_indexed_searched_and_listed() {
    let t = Tree::new("indexed");
    t.write(".scrutate.toml", TABLE);
    let (code, out, err) = t.run(&["symbol", "circle_area"]);
    assert_eq!(code, 0, "{out}{err}");
    assert!(out.contains("shapes.myl:4-6") && out.contains("function"), "{out}");
    let (_, out, _) = t.run(&["symbol", "Rectangle"]);
    assert!(out.contains("shapes.myl:8-11") && out.contains("class"), "{out}");
    let (code, out, err) = t.run(&["outline", "shapes.myl"]);
    assert_eq!(code, 0, "{out}{err}");
    for want in ["circle_area", "Rectangle", "double"] {
        assert!(out.contains(want), "outline lists {want}: {out}");
    }
    // the comment above a definition is its documentation: a ranked search finds it by those words
    let (code, out, err) = t.run(&["search", "doubles a number"]);
    assert_eq!(code, 0, "{out}{err}");
    assert!(out.lines().next().is_some_and(|l| l.contains("shapes.myl:14")), "{out}");
    let (_, out, _) = t.run(&["search", "area of a circle"]);
    assert!(out.lines().next().is_some_and(|l| l.contains("shapes.myl:4")), "{out}");

    let (code, out, err) = t.run(&["grep", "--type", "mylang", "-l", "circle_area", "."]);
    assert_eq!((code, out.trim()), (0, "./shapes.myl"), "{err}");
    let (_, out, _) = t.run(&["grep", "--type-list", "."]);
    assert!(out.lines().any(|l| l.starts_with("mylang") && l.contains("*.myl")), "{out}");

    let (code, out, _) = t.run(&["languages"]);
    assert_eq!(code, 0);
    let line = out.lines().find(|l| l.starts_with("mylang")).unwrap_or_else(|| panic!("{out}"));
    assert!(line.contains(".myl") && line.contains("custom: .scrutate.toml"), "{line}");
    let v = t.json(&["languages", "--json"]);
    let me = v.as_array().unwrap().iter().find(|l| l["id"] == "mylang").expect("mylang in languages --json");
    assert_eq!(me["tier"], "custom");
    assert_eq!(me["source"], ".scrutate.toml");
    assert_eq!(me["extensions"], serde_json::json!([".myl"]));
    assert_eq!(me["definition_kinds"], serde_json::json!(["class", "function"]));
    // other languages are parsed as before
    let (_, out, _) = t.run(&["symbol", "circle_area_py"]);
    assert!(out.contains("other.py:1-2"), "{out}");
}

#[test]
fn a_change_of_the_table_reparses_the_files_of_its_language() {
    let t = Tree::new("change");
    t.write(".scrutate.toml", TABLE);
    let (_, out, _) = t.run(&["symbol", "double"]);
    assert!(out.contains("shapes.myl:14-16"), "{out}");
    t.write(".scrutate.toml", &TABLE.replace(r"^\s*fn\s+", r"^\s*fn\s+d"));
    let (_, out, _) = t.run(&["symbol", "ouble"]);
    assert!(out.contains("shapes.myl:14-16"), "the new pattern names it `ouble`: {out}");
    let (_, out, _) = t.run(&["symbol", "circle_area"]);
    assert!(!out.contains("shapes.myl"), "the new pattern does not match circle_area: {out}");
    // without the table the file is read by the keyword heuristics again
    fs::remove_file(t.root.join(".scrutate.toml")).unwrap();
    let (_, out, _) = t.run(&["symbol", "double"]);
    assert!(out.contains("shapes.myl:14"), "{out}");
    let (_, out, _) = t.run(&["languages"]);
    assert!(!out.contains("mylang"), "{out}");
}

#[test]
fn the_user_s_configuration_file_adds_a_language_too() {
    let t = Tree::new("user");
    let dir = t.base.join("home/.config/scrutate");
    fs::create_dir_all(&dir).unwrap();
    fs::write(dir.join("config.toml"), TABLE).unwrap();
    let (_, out, _) = t.run(&["symbol", "Rectangle"]);
    assert!(out.contains("shapes.myl:8-11"), "{out}");
    let (_, out, _) = t.run(&["languages"]);
    let line = out.lines().find(|l| l.starts_with("mylang")).unwrap_or_else(|| panic!("{out}"));
    assert!(line.contains("custom: ") && line.contains("config.toml"), "{line}");
    // the same name in the repository's file as well is one error naming that file
    t.write(".scrutate.toml", TABLE);
    let (code, _, err) = t.run(&["languages"]);
    assert_eq!(code, 2, "{err}");
    assert!(err.contains("config.toml:2:") && err.contains("mylang"), "{err}");
}

/// The one error a bad table gives: exit 2, one line, the file and the line named.
fn one_error(t: &Tree, toml: &str, line: usize, words: &str) {
    t.write(".scrutate.toml", toml);
    for args in [&["symbol", "circle_area"][..], &["languages"], &["grep", "--type", "mylang", "x", "."]] {
        let (code, out, err) = t.run(args);
        assert_eq!(code, 2, "{args:?} {toml}: {out}{err}");
        let lines: Vec<&str> = err.lines().collect();
        assert_eq!(lines.len(), 1, "one line: {err}");
        assert!(lines[0].contains(&format!(".scrutate.toml:{line}:")), "names the line {line}: {err}");
        assert!(lines[0].contains(words), "says {words:?}: {err}");
    }
}

#[test]
fn a_bad_table_is_one_error_that_names_the_file_and_the_line() {
    let t = Tree::new("errors");
    one_error(&t, &TABLE.replace("name = \"mylang\"", "name = \"mylang"), 2, "");
    one_error(&t, &TABLE.replace(r"([A-Za-z_][A-Za-z0-9_]*)' },", r"([A-Za-z_' },"), 7, "does not compile");
    one_error(&t, &TABLE.replace(r"^\s*type\s+([A-Za-z_][A-Za-z0-9_]*)", r"^\s*type\s+[A-Za-z_]+"), 8, "group");
    one_error(&t, &TABLE.replace("line_comment", "line_coment"), 4, "line_coment");
    one_error(&t, &TABLE.replace("\"mylang\"", "\"python\""), 2, "built-in");
    one_error(&t, &TABLE.replace("[\"myl\"]", "[\"myl\", \"rs\"]"), 3, "rust");
    one_error(&t, &TABLE.replace("kind = \"class\"", "kind = \"widget\""), 8, "widget");
    one_error(&t, &TABLE.replace("name = \"mylang\"", "name = \"my lang\""), 2, "letters");
}

#[test]
fn a_repository_s_table_cannot_name_a_file_or_reach_outside_the_repository() {
    let t = Tree::new("outside");
    let outside = t.base.join("outside.toml");
    fs::write(&outside, TABLE).unwrap();
    // a key that would read another file is no key of the table
    let include = format!("{}include = {:?}\n", TABLE, outside.display().to_string());
    one_error(&t, &include, 10, "include");
    let path_key = TABLE.replace("name = \"mylang\"", &format!("name = \"mylang\"\npath = {:?}", outside.display().to_string()));
    one_error(&t, &path_key, 3, "path");
    // a link out of the repository is not read as the repository's table
    fs::remove_file(t.root.join(".scrutate.toml")).unwrap();
    #[cfg(unix)]
    {
        std::os::unix::fs::symlink(&outside, t.root.join(".scrutate.toml")).unwrap();
        let (code, out, err) = t.run(&["languages"]);
        assert_eq!(code, 0, "{err}");
        assert!(!out.contains("mylang"), "{out}");
    }
}

//! `scrutate dead` and the `dead_code` tool: definitions nothing in the repository uses, entry
//! points left out, and the ones the resolver cannot decide kept apart with the reason.

use std::fs;
use std::io::Write;
use std::path::PathBuf;
use std::process::{Command, Stdio};

use serde_json::Value;

const BIN: &str = env!("CARGO_BIN_EXE_scrutate");

struct Repo {
    root: PathBuf,
}

impl Repo {
    fn new(name: &str, files: &[(&str, &str)]) -> Repo {
        let root = std::env::temp_dir().join(format!("scrutate_dead_{}_{}", name, std::process::id()));
        let _ = fs::remove_dir_all(&root);
        for (rel, body) in files {
            let p = root.join(rel);
            fs::create_dir_all(p.parent().unwrap()).unwrap();
            fs::write(&p, body).unwrap();
        }
        Repo { root }
    }

    fn run(&self, args: &[&str]) -> (i32, String) {
        let out = Command::new(BIN).arg("--root").arg(&self.root).args(args).stdin(Stdio::null()).output().unwrap();
        (out.status.code().unwrap_or(-1), String::from_utf8_lossy(&out.stdout).into_owned())
    }

    fn json(&self, args: &[&str]) -> Value {
        let (_, out) = self.run(&[args, &["--json"]].concat());
        serde_json::from_str(&out).unwrap_or_else(|e| panic!("{e}: {out}"))
    }
}

impl Drop for Repo {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.root);
    }
}

const APP_PY: &str = r#"import sys


def helper():
    return 1


def unused_private():
    return 2


def caller():
    return helper()


@app.route("/x")
def handler():
    return 3


def by_name():
    return 4


def dispatch(obj):
    return getattr(obj, "by_name")()


def only_in_a_comment():
    return 5


def recursive_alone(n):
    return recursive_alone(n - 1)


def main():
    # only_in_a_comment is kept for later
    caller()
    dispatch(sys)


if __name__ == "__main__":
    main()
"#;

const TEST_PY: &str = "from app import caller\n\n\ndef test_caller():\n    assert caller() == 1\n";

const WEB_JS: &str = "export function shown() { return 1 }\nfunction hidden() { return 2 }\nmodule.exports = { other }\nfunction other() {}\nconst handlers = { onSave() { return 3 } }\nregister(handlers)\n";

const LIB_RS: &str = r#"use std::fmt;

pub fn api() -> u32 {
    used_inside()
}

fn used_inside() -> u32 {
    1
}

fn private_dead() -> u32 {
    2
}

#[no_mangle]
pub extern "C" fn ffi_entry() {}

struct Shown;

impl fmt::Display for Shown {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "x")
    }
}

pub fn show() -> String {
    Shown.to_string()
}
"#;

const MAIN_GO: &str = "package main\n\nfunc init() {}\n\nfunc main() {\n\tused()\n}\n\nfunc used() {}\n\nfunc unusedGo() {}\n";

const LIB_GO: &str = "package lib\n\nfunc Exported() int {\n\treturn 1\n}\n\nfunc unexported() int {\n\treturn 2\n}\n";

fn fixture(name: &str) -> Repo {
    Repo::new(
        name,
        &[
            ("app.py", APP_PY),
            ("tests/test_app.py", TEST_PY),
            ("web.js", WEB_JS),
            ("Cargo.toml", "[package]\nname = \"fx\"\nversion = \"0.1.0\"\n"),
            ("src/lib.rs", LIB_RS),
            ("main.go", MAIN_GO),
            ("Makefile", "build:\n\tcargo build\n"),
            ("lib/lib.go", LIB_GO),
        ],
    )
}

fn names(v: &Value, group: &str) -> Vec<String> {
    let mut out: Vec<String> = v["result"][group]
        .as_array()
        .unwrap_or_else(|| panic!("{v}"))
        .iter()
        .map(|d| format!("{} {}", d["path"].as_str().unwrap(), d["qualname"].as_str().unwrap()))
        .collect();
    out.sort();
    out
}

#[test]
fn dead_lists_what_nothing_uses_and_keeps_entry_points_and_undecided_uses_apart() {
    let r = fixture("fixture");
    let v = r.json(&["dead"]);
    assert_eq!(
        names(&v, "dead"),
        ["app.py recursive_alone", "app.py unused_private", "lib/lib.go unexported", "main.go unusedGo", "src/lib.rs private_dead", "web.js hidden"],
        "{v:#}"
    );
    let undecided = names(&v, "undecided");
    assert!(undecided.contains(&"app.py by_name".to_string()), "a name used only through getattr is undecided: {v:#}");
    assert!(undecided.contains(&"app.py only_in_a_comment".to_string()), "{v:#}");
    assert!(undecided.iter().any(|u| u.ends_with("onSave")), "a method of an object literal may be called by its key: {v:#}");
    for u in v["result"]["undecided"].as_array().unwrap() {
        assert!(!u["reason"].as_str().unwrap_or("").is_empty(), "every undecided one says why: {u}");
    }
    // used, entry points, tests and exports are in neither group
    for left_out in [
        "helper",
        "caller",
        "handler",
        "main",
        "dispatch",
        "test_caller",
        "shown",
        "other",
        "api",
        "used_inside",
        "ffi_entry",
        "Shown.fmt",
        "init",
        "used",
        "Exported",
        "Shown",
        "build",
    ] {
        for group in ["dead", "undecided"] {
            assert!(!names(&v, group).iter().any(|n| n.ends_with(&format!(" {left_out}"))), "{left_out} is not {group}: {v:#}");
        }
    }
    let d = &v["result"]["dead"][0];
    assert_eq!((d["path"].as_str(), d["start"].as_i64(), d["end"].as_i64(), d["kind"].as_str()), (Some("app.py"), Some(8), Some(9), Some("function")));
    assert_eq!((d["id"].as_str(), d["name"].as_str()), (Some("app.py:8-9"), Some("unused_private")));

    let (code, text) = r.run(&["dead"]);
    assert_eq!(code, 0);
    assert!(text.lines().any(|l| l == "app.py:8-9  [function] unused_private"), "{text}");
    assert!(text.lines().any(|l| l.starts_with("app.py:21-22  [function] by_name  (undecided: ")), "{text}");
    assert!(text.trim_end().ends_with("(6 dead, 3 undecided)"), "{text}");

    // PATH keeps the definitions under one directory; the uses are still looked for everywhere
    assert_eq!(names(&r.json(&["dead", "lib"]), "dead"), ["lib/lib.go unexported"]);
    assert_eq!(names(&r.json(&["dead", "src/lib.rs"]), "dead"), ["src/lib.rs private_dead"]);
    let (code, _) = r.run(&["dead", "no/such/dir"]);
    assert_eq!(code, 2);

    // the same answer the second time, from the kept answers or not
    assert_eq!(r.json(&["dead"]), v);
}

