fn a_text_index_of_a_newer_format_is_refused_and_left_as_it_is() {
    let t = Tmp::new("newer_text");
    fs::write(t.0.join("a.py"), "def alpha():\n    return 1\n").unwrap();
    assert_eq!(run(&t.0, &["index", "--text"]).0, 0);
