fn a_relative_import_that_climbs_above_the_root_names_no_file() {
    let r = Repo::new(
        "above_root",
        &[
            ("lib.js", "export function h() { return 1 }\n"),
            ("src/a.js", "import { h } from '../../lib';\nh();\n"),
            ("src/c.js", "import { h } from '../lib';\nh();\n"),
            ("helper.py", "def go():\n    return 1\n"),
