    assert_eq!(r.ok("find_symbol", json!({"name": "::make"})), r.ok("find_symbol", json!({"name": "make"})));
    for (tool, key) in [("read_code", "symbol"), ("callers", "name"), ("callees", "name"), ("similar_code", "target")] {
