    if cfg!(unix) {
        assert!(r.ok("read_code", json!({"symbol": "a::b.py:1-2"})).contains("in_odd_file"));
        assert!(r.ok("find_symbol", json!({"name": "a::b.py:1"})).contains("a::b.py:1-2"));
    }
}

