#[test]
fn deeply_nested_lisp_and_html_parse_in_linear_time() {
    for (path, head) in [("a.lisp", "(defun f () "), ("a.scm", "(define (f) ")] {
        let make = |n: usize| format!("{head}{}{})", "(g ".repeat(n), ")".repeat(n));
