fn the_model_signature_is_a_hash_of_the_model_file() {
    use blake2::digest::{Update, VariableOutput};
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../models/semantic.npz");
    let bytes = std::fs::read(&path).unwrap();
