//! Property-based tests (proptest): invariants that must hold for *any* input, not just the
//! examples in the unit tests.

use grep_matcher::Matcher;
use proptest::prelude::*;
use scrutate::instant::{ident_parts, identifier_regex, FuzzyMatcher};
use scrutate::npy::{save, Npy};
use scrutate::parse::parse_source;
use scrutate::text::{name_key, prefix_bytes, query_terms, tokenize2};

proptest! {
    #![proptest_config(ProptestConfig { cases: 300, .. ProptestConfig::default() })]

    /// A byte prefix never splits a character and is the longest one that fits.
    #[test]
    fn prefix_bytes_is_valid_and_maximal(s in "\\PC{0,64}", n in 0usize..80) {
        let p = prefix_bytes(&s, n);
        prop_assert!(p.len() <= n || s.len() <= n);
        prop_assert!(s.starts_with(p));
        prop_assert!(s.is_char_boundary(p.len()));
        if p.len() < s.len() {
            // the next character would not fit
            let next = s[p.len()..].chars().next().unwrap();
            prop_assert!(p.len() + next.len_utf8() > n);
        }
    }

    /// Tokenization never panics and only yields non-empty lowercase tokens without spaces; an
    /// ASCII token is lowercase letters and digits.
    #[test]
    fn tokenize_total_and_normalised(s in "\\PC{0,200}", cap in proptest::option::of(1usize..300)) {
        let (stems, words) = tokenize2(&s, cap);
        for t in stems.iter().chain(words.iter()) {
            prop_assert!(!t.is_empty() && !t.contains(char::is_whitespace) && t.to_lowercase() == *t, "token {t:?}");
            if t.is_ascii() {
                prop_assert!(t.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit()), "token {t:?}");
            }
        }
        let _ = query_terms(&s);
        let k = name_key(&s);
        prop_assert!(k == k.to_lowercase() && !k.contains('_'));
    }

    /// name_key is a normal form: applying it twice changes nothing, and casing / separators do not matter.
    #[test]
    fn name_key_is_idempotent_and_case_insensitive(s in "[A-Za-z_][A-Za-z0-9_]{0,30}") {
        let k = name_key(&s);
        prop_assert_eq!(name_key(&k), k.clone());
        prop_assert_eq!(name_key(&s.to_uppercase()), k.clone());
        prop_assert_eq!(name_key(&s.replace('_', "")), k);
    }

    /// Identifier parts lose nothing but separators and casing, and the regex they build matches
    /// the snake_case, camelCase and SCREAMING_CASE spellings of the same identifier.
    #[test]
    fn identifier_regex_matches_all_casings(parts in proptest::collection::vec("[a-z][a-z0-9]{1,6}", 1..5)) {
        // parts have at least two characters: a run of single capitals (`aAA`) is an acronym by
        // convention and cannot be told apart from three one-letter words
        let snake = parts.join("_");
        let camel: String = parts.iter().enumerate().map(|(i, p)| if i == 0 { p.clone() } else { let mut c = p.chars(); c.next().unwrap().to_uppercase().collect::<String>() + c.as_str() }).collect();
        let scream = snake.to_uppercase();
        let joined: String = ident_parts(&snake).join("").to_lowercase();
        prop_assert_eq!(joined, snake.replace('_', ""));
        for spelling in [&snake, &camel, &scream] {
            let re = regex::Regex::new(&identifier_regex(spelling)).unwrap();
            prop_assert!(re.is_match(&format!("x = {snake}(1)")), "{spelling} should match {snake}");
            prop_assert!(re.is_match(&scream), "{spelling} should match {scream}");
            prop_assert!(!re.is_match(&format!("{snake}_extra")), "{spelling} must not match a longer identifier");
        }
    }

    /// The fuzzy matcher finds a pattern after at most k random single-character edits, and
    /// finds the unedited pattern with distance 0.
    #[test]
    fn fuzzy_finds_edited_patterns(pat in "[a-z]{4,20}", k in 1u8..3, edits in proptest::collection::vec((0usize..20, 0u8..3, 0u8..26), 0..3), prefix in "[a-z ]{0,10}", suffix in "[a-z ]{0,10}") {
        prop_assume!((k as usize) < pat.len());
        let m = FuzzyMatcher::new(&pat, k, false).unwrap();
        let mut text: Vec<u8> = pat.as_bytes().to_vec();
        for (pos, kind, ch) in edits.iter().take(k as usize) {
            if text.is_empty() { break; }
            let p = pos % text.len();
            match kind {
                0 => text[p] = b'a' + ch,                 // substitute
                1 => { text.remove(p); }                  // delete
                _ => text.insert(p, b'a' + ch),           // insert
            }
        }
        let hay = format!("{prefix}{}{suffix}\n", String::from_utf8_lossy(&text));
        prop_assert!(m.find_at(hay.as_bytes(), 0).unwrap().is_some(), "pattern {pat:?} not found in {hay:?} within {k} edits");
        // the unedited pattern is always found; the reported span is the *first* approximate match
        // on the line (it may end before the exact occurrence when a nearby substring is within k
        // edits), which is what line-oriented reporting needs
        let exact = format!("{prefix}{pat}{suffix}\n");
        let hit = m.find_at(exact.as_bytes(), 0).unwrap().expect("exact occurrence found");
        prop_assert!(hit.end() < exact.len() && hit.start() < hit.end(), "{hit:?}");
    }

    /// Any source text parses into well-formed chunks for any extension: ordered 1-based ranges
    /// within the file, no panics.
    #[test]
    fn parser_yields_well_formed_chunks(src in "[ -~\\n\\t]{0,400}", ext in prop::sample::select(vec!["py", "js", "ts", "go", "rs", "java", "c", "rb", "sh", "json", "md", "txt", "zig", "hs"])) {
        let n_lines = src.split('\n').count() as i64;
        for c in parse_source(&format!("f.{ext}"), &src) {
            prop_assert!(c.start >= 1 && c.end >= c.start, "{c:?}");
            prop_assert!(c.end <= n_lines.max(1), "chunk {}-{} beyond {} lines", c.start, c.end, n_lines);
        }
    }

    /// .npy round trip for arbitrary i64 / f32 data and shapes.
    #[test]
    fn npy_roundtrip(data in proptest::collection::vec(any::<i64>(), 0..64), cols in 1usize..5) {
        let dir = std::env::temp_dir().join(format!("scrutate_prop_{}_{}", std::process::id(), data.len()));
        std::fs::create_dir_all(&dir).unwrap();
        let rows = data.len() / cols;
        let data = &data[..rows * cols];
        let p = dir.join("a.npy");
        save(&p, data, &[rows, cols]).unwrap();
        let n = Npy::open(&p).unwrap();
        prop_assert_eq!(n.shape.clone(), vec![rows, cols]);
        prop_assert_eq!(n.view::<i64>().unwrap(), data);
        prop_assert!(n.view::<f32>().is_err(), "dtype must be checked");
        let _ = std::fs::remove_dir_all(&dir);
    }
}

//! Ranking's arithmetic, pinned: on a small fixed tree, with the bundled vector model and ranker,
//! every candidate, feature and score of a few queries is the one recorded in `ranking_pins.json`.
//! A change that moves a feature in its last bit fails here, long before the quality floor of
//! `bench/quality.py` moves. Record again on purpose with `UPDATE_PINS=1 cargo test --test ranking_pins`.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

const BIN: &str = env!("CARGO_BIN_EXE_scrutate");
const PINS: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/ranking_pins.json");

// Short files, so no token is counted more than a few times in a chunk: ln of a small count is
// rounded the same by every libm, and the other arithmetic is IEEE basic operations.
const FILES: &[(&str, &str)] = &[
    (
        "shop/cart.py",
        "class Cart:\n    \"\"\"A basket of items a customer is about to buy.\"\"\"\n\n    def total_price(self, items):\n        \"\"\"Sum the prices of the items in the cart.\"\"\"\n        return sum(i.price for i in items)\n\n    def remove_item(self, item):\n        self.items.remove(item)\n\n\ndef parse_size(text):\n    \"\"\"Read a size such as 10M into bytes.\"\"\"\n    return int(text[:-1]) * 1024 * 1024\n",
    ),
    ("shop/test_cart.py", "def test_total_price():\n    assert Cart().total_price([]) == 0\n"),
    (
        "src/config.rs",
        "/// Settings read from the configuration file.\npub struct Config {\n    pub retries: u32,\n}\n\nimpl Config {\n    /// Load the settings from a TOML file on disk.\n    pub fn load(path: &str) -> Config {\n        let text = std::fs::read_to_string(path).unwrap();\n        parse(&text)\n    }\n}\n\nfn parse(text: &str) -> Config {\n    Config { retries: text.len() as u32 }\n}\n",
    ),
    (
        "net/client.go",
        "package net\n\n// Fetch downloads a page and returns its body.\nfunc Fetch(url string) (string, error) {\n\treturn get(url)\n}\n\n// Retry calls f until it succeeds or the attempts run out.\nfunc Retry(attempts int, f func() error) error {\n\treturn f()\n}\n",
    ),
    (
        "web/router.js",
        "/** Match a request path against the registered routes. */\nexport function matchRoute(routes, path) {\n  return routes.find((r) => r.path === path);\n}\n\nexport class Router {\n  add(route) {\n    this.routes.push(route);\n  }\n}\n",
    ),
];

const QUERIES: &[&str] =
    &["total price of the cart", "parse_size", "load settings from a file", "Retry", "match a route for a request path", "download a web page"];

fn tree() -> PathBuf {
    let root = std::env::temp_dir().join(format!("scrutate_pins_{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    for (rel, text) in FILES {
        let p = root.join(rel);
        fs::create_dir_all(p.parent().unwrap()).unwrap();
        fs::write(p, text).unwrap();
    }
    root
}

fn scrutate(root: &Path, args: &[&str]) -> String {
    let out = Command::new(BIN)
        .arg("--root")
        .arg(root)
        .args(args)
        .stdin(Stdio::null())
        .env_remove("SCRUTATE_SEMANTIC")
        .env_remove("SCRUTATE_RANKER")
        .output()
        .unwrap();
    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
    String::from_utf8(out.stdout).unwrap()
}

/// Per query: the hits, and each candidate with its score and features. Numbers are printed in the
/// shortest form that reads back to the same float, so equal JSON is equal bits.
fn measure(root: &Path) -> serde_json::Value {
    scrutate(root, &["index", "--no-text"]);
    // outside the tree, so the queries are not indexed
    let q = root.with_extension("jsonl");
    fs::write(&q, QUERIES.iter().map(|t| format!("{}\n", serde_json::json!({"query": t, "k": 5}))).collect::<String>()).unwrap();
    let recs: Vec<serde_json::Value> =
        scrutate(root, &["batch", "--features", q.to_str().unwrap()]).lines().map(|l| serde_json::from_str(l).unwrap()).collect();
    let _ = fs::remove_file(&q);
    let names = recs[0]["feature_names"].clone();
    let queries: Vec<serde_json::Value> = recs
        .iter()
        .map(|r| {
            let hits: Vec<_> = r["hits"].as_array().unwrap().iter().map(|h| format!("{}:{}", h["path"].as_str().unwrap(), h["start"])).collect();
            let cands: Vec<_> = r["candidates"]
                .as_array()
                .unwrap()
                .iter()
                .map(|c| serde_json::json!({"at": format!("{}:{}", c["path"].as_str().unwrap(), c["qualname"].as_str().unwrap()), "score": c["score"], "x": c["x"]}))
                .collect();
            serde_json::json!({"query": r["query"], "hits": hits, "candidates": cands})
        })
        .collect();
    serde_json::json!({"feature_names": names, "queries": queries})
}

#[test]
fn the_features_and_scores_of_a_small_fixture_are_pinned() {
    let root = tree();
    let got = measure(&root);
    let _ = fs::remove_dir_all(&root);
    if std::env::var_os("UPDATE_PINS").is_some() {
        fs::write(PINS, serde_json::to_string_pretty(&got).unwrap() + "\n").unwrap();
        return;
    }
    let want: serde_json::Value = serde_json::from_str(&fs::read_to_string(PINS).unwrap()).unwrap();
    assert_eq!(got["feature_names"], want["feature_names"], "the feature list changed: record the pins again");
    let names: Vec<&str> = want["feature_names"].as_array().unwrap().iter().map(|v| v.as_str().unwrap()).collect();
    for (g, w) in got["queries"].as_array().unwrap().iter().zip(want["queries"].as_array().unwrap()) {
        let q = &w["query"];
        let (gc, wc) = (g["candidates"].as_array().unwrap(), w["candidates"].as_array().unwrap());
        let at = |cs: &[serde_json::Value]| cs.iter().map(|c| c["at"].as_str().unwrap().to_string()).collect::<Vec<_>>();
        assert_eq!(at(gc), at(wc), "{q}: the candidates or their order changed");
        for (a, b) in gc.iter().zip(wc) {
            for (i, name) in names.iter().enumerate() {
                assert_eq!(a["x"][i], b["x"][i], "{q}: {} feature {name}", b["at"]);
            }
            assert_eq!(a["score"], b["score"], "{q}: {} score", b["at"]);
        }
        assert_eq!(g["hits"], w["hits"], "{q}: the hits changed");
    }
    assert_eq!(got["queries"].as_array().unwrap().len(), want["queries"].as_array().unwrap().len());
}

//! End-to-end tests of scope-aware `refs`: per language, a small repository with two same-named
//! definitions in different modules, and every occurrence checked against the one it must land on.

use std::collections::BTreeMap;
use std::fs;
use std::path::PathBuf;
use std::process::{Command, Stdio};

const BIN: &str = env!("CARGO_BIN_EXE_scrutate");

struct Repo {
    root: PathBuf,
}

impl Repo {
    fn new(name: &str, files: &[(&str, &str)]) -> Repo {
        let root = std::env::temp_dir().join(format!("scrutate_resolve_e2e_{}_{}", name, std::process::id()));
        let _ = fs::remove_dir_all(&root);
        for (rel, body) in files {
            let p = root.join(rel);
            fs::create_dir_all(p.parent().unwrap()).unwrap();
            fs::write(&p, body).unwrap();
        }
        let r = Repo { root };
        assert_eq!(r.run(&["index", "--no-text"]).0, 0);
        r
    }
    fn run(&self, args: &[&str]) -> (i32, String) {
        let out = Command::new(BIN).args(args).current_dir(&self.root).stdin(Stdio::null()).output().unwrap();
        (out.status.code().unwrap_or(-1), String::from_utf8_lossy(&out.stdout).into_owned())
    }
    fn json(&self, args: &[&str]) -> serde_json::Value {
        let (code, out) = self.run(args);
        assert_eq!(code, 0, "{out}");
        let v: serde_json::Value = serde_json::from_str(&out).unwrap_or_else(|e| panic!("{e}: {out}"));
        // an answer leaves in its envelope; `check` prints a report of its own
        if v["schema"] == 2 {
            v["result"].clone()
        } else {
            v
        }
    }
    /// (path, line) of every occurrence -> path of the definition it resolved to ("-" = unresolved).
    fn resolved(&self, name: &str) -> BTreeMap<(String, u64), String> {
        let v = self.json(&["refs", name, "--json"]);
        let mut m = BTreeMap::new();
        for d in v["definitions"].as_array().unwrap() {
            for r in d["references"].as_array().unwrap() {
                m.insert((r["path"].as_str().unwrap().to_string(), r["line"].as_u64().unwrap()), d["path"].as_str().unwrap().to_string());
            }
        }
        for u in v["unresolved"].as_array().unwrap() {
            m.insert((u["path"].as_str().unwrap().to_string(), u["line"].as_u64().unwrap()), "-".to_string());
        }
        m
    }
}

impl Drop for Repo {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.root);
    }
}

fn expect(want: &[(&str, u64, &str)]) -> BTreeMap<(String, u64), String> {
    want.iter().map(|(p, l, d)| ((p.to_string(), *l), d.to_string())).collect()
}

#[test]
fn python_two_areas() {
    let r = Repo::new(
        "py",
        &[
            ("shapes/circle.py", "def area(r):\n    return 3 * r * r\n"),
            ("shapes/square.py", "def area(s):\n    return s * s\n"),
            ("shapes/__init__.py", "from .circle import area\n"),
            (
                "app.py",
                "from shapes import square\nfrom shapes import area\nimport shapes.circle as c\n\n\ndef main(area_of=None):\n    a = area(1)\n    b = square.area(2)\n    d = c.area(3)\n    return a + b + d\n\n\n# area in a comment\n",
            ),
        ],
    );
    let (c, s) = ("shapes/circle.py", "shapes/square.py");
    assert_eq!(
        r.resolved("area"),
        expect(&[
            (c, 1, c),
            (s, 1, s),
            ("shapes/__init__.py", 1, c),
            ("app.py", 2, c),
            ("app.py", 7, c),
            ("app.py", 8, s),
            ("app.py", 9, c),
            ("app.py", 13, "-")
        ])
    );

    let v = r.json(&["refs", "area", "--def", "shapes/square.py", "--json"]);
    let defs = v["definitions"].as_array().unwrap();
    assert_eq!(defs.len(), 1, "{v}");
    let lines: Vec<u64> = defs[0]["references"].as_array().unwrap().iter().map(|o| o["line"].as_u64().unwrap()).collect();
    assert_eq!(lines, [8, 1], "app.py:8 and the definition itself: {v}");
    let (_, text) = r.run(&["refs", "area", "--def", "shapes/square.py:1"]);
    assert!(text.starts_with("shapes/square.py:1-2  [function] area  (2 references)"), "{text}");
    assert_eq!(r.run(&["refs", "area", "--def", "app.py"]).0, 2, "no definition there is an error");

    let v = r.json(&["refs", "area", "--textual", "--json"]);
    assert!(v["callers"].is_array() && v["references"].is_array(), "the old shape stays reachable: {v}");
}

#[test]
fn javascript_and_typescript_two_areas() {
    let r = Repo::new(
        "js",
        &[
            ("lib/a.js", "export function area() { return 1; }\n"),
            ("lib/b.js", "export function area() { return 2; }\n"),
            ("main.js", "import {area} from './lib/a.js';\nimport * as b from './lib/b';\narea();\nb.area();\n"),
            ("geo/point.ts", "export class Shape {\n  area() { return 1; }\n  twice() { return this.area() * 2; }\n}\n"),
            ("geo/box.ts", "export function area() { return 2; }\n"),
            ("geo/index.ts", "export { area } from './box';\n"),
            ("use.ts", "import { Shape } from './geo/point';\nimport { area } from './geo';\nconst s = new Shape();\narea();\ns.area();\n"),
        ],
    );
    let (a, b, p, x) = ("lib/a.js", "lib/b.js", "geo/point.ts", "geo/box.ts");
    assert_eq!(
        r.resolved("area"),
        expect(&[
            (a, 1, a),
            (b, 1, b),
            ("main.js", 1, a),
            ("main.js", 3, a),
            ("main.js", 4, b),
            (p, 2, p),
            (p, 3, p),
            (x, 1, x),
            ("geo/index.ts", 1, x),
            ("use.ts", 2, x),
            ("use.ts", 4, x),
            ("use.ts", 5, p), // `s` is built with `new Shape()`
        ])
    );
}

#[test]
fn rust_two_areas() {
    let r = Repo::new(
        "rs",
        &[
            ("Cargo.toml", "[package]\nname = \"shapes\"\nversion = \"0.1.0\"\n"),
            ("src/lib.rs", "pub mod app;\npub mod circle;\npub mod square;\npub use circle::area;\n"),
            ("src/circle.rs", "pub fn area() -> u32 {\n    1\n}\n"),
            ("src/square.rs", "pub fn area() -> u32 {\n    2\n}\n\npub fn twice() -> u32 {\n    area() * 2\n}\n"),
            (
                "src/app.rs",
                "use crate::area;\nuse crate::square;\n\npub fn run() -> u32 {\n    area()\n        + square::area()\n        + crate::circle::area()\n}\n",
            ),
        ],
    );
    let (c, s) = ("src/circle.rs", "src/square.rs");
    assert_eq!(
        r.resolved("area"),
        expect(&[
            (c, 1, c),
            (s, 1, s),
            (s, 6, s),
            ("src/lib.rs", 4, c),
            ("src/app.rs", 1, c),
            ("src/app.rs", 5, c),
            ("src/app.rs", 6, s),
            ("src/app.rs", 7, c)
        ])
    );
}

