//! `scrutate review` on git repositories made for each test: a base with a call chain, a test
//! file and a duplicate pair, and a head that edits the deepest function and adds a copy of
//! another; then the GitLab Code Quality report and the GitHub Action's comment script against a
//! stand-in `gh` that replays a recorded list of comments.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use serde_json::Value;

const BIN: &str = env!("CARGO_BIN_EXE_scrutate");

/// git's own configuration is the only one read: no global or system file.
const GIT_ENV: [(&str, &str); 2] = [("GIT_CONFIG_GLOBAL", "/dev/null"), ("GIT_CONFIG_NOSYSTEM", "1")];

struct Tree {
    root: PathBuf,
}

impl Tree {
    fn new(name: &str) -> Tree {
        let root = Path::new(env!("CARGO_TARGET_TMPDIR")).join(format!("review_{name}_{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).unwrap();
        Tree { root: fs::canonicalize(root).unwrap() }
    }

    fn write(&self, rel: &str, text: &str) {
        let p = self.root.join(rel);
        fs::create_dir_all(p.parent().unwrap()).unwrap();
        fs::write(p, text).unwrap();
    }

    fn git(&self, args: &[&str]) -> String {
        let mut c = Command::new("git");
        c.args(["-c", "user.name=t", "-c", "user.email=t@t", "-c", "commit.gpgsign=false", "-c", "init.defaultBranch=main"]).args(args).current_dir(&self.root);
        let out = c.envs(GIT_ENV).stdin(Stdio::null()).output().unwrap();
        assert!(out.status.success(), "git {args:?}: {}", String::from_utf8_lossy(&out.stderr));
        String::from_utf8_lossy(&out.stdout).trim().to_string()
    }

    fn commit(&self, message: &str) -> String {
        self.git(&["add", "-A"]);
        self.git(&["commit", "-q", "-m", message]);
        self.git(&["rev-parse", "HEAD"])
    }

    /// (exit code, standard output, standard error)
    fn run(&self, args: &[&str]) -> (i32, String, String) {
        let out = Command::new(BIN)
            .args(["--root", self.root.to_str().unwrap()])
            .args(args)
            .current_dir(&self.root)
            .envs(GIT_ENV)
            .env("SCRUTATE_SEMANTIC", "none")
            .stdin(Stdio::null())
            .output()
            .unwrap();
        (out.status.code().unwrap_or(-1), String::from_utf8_lossy(&out.stdout).into_owned(), String::from_utf8_lossy(&out.stderr).into_owned())
    }

    fn review(&self, args: &[&str]) -> String {
        let (code, out, err) = self.run(&[&["review"], args].concat());
        assert_eq!(code, 0, "review {args:?}: {out}{err}");
        out
    }
}

impl Drop for Tree {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.root);
    }
}

/// A function body long enough for `dupes` (30 body tokens), its words from `seed`.
fn long_fn(name: &str, seed: &str) -> String {
    format!(
        "def {name}(rows):\n    total = 0\n    for row in rows:\n        if row.amount > {seed}_limit and row.status == \"open\":\n            \
         total += compute_{seed}_weight(row.amount, row.discount, row.region)\n        elif row.status == \"closed\":\n            \
         total -= penalty_for_{seed}(row.region, row.amount, row.owner)\n        else:\n            total = adjust_{seed}(total, row.created, row.updated)\n    \
         return normalize_{seed}_total(total, rows, scale_factor, offset_value, rounding_mode)\n"
    )
}

/// The base commit: `top` calls `middle` calls `deepest`, one test reaches `top`, another tests
/// `spare`; `old_a` and `old_b` are already exact duplicates, `unique` has no copy.
fn base(name: &str) -> (Tree, String) {
    let t = Tree::new(name);
    t.git(&["init", "-q"]);
    t.write("lib/__init__.py", "");
    t.write("lib/core.py", "def deepest(x):\n    return x + 1\n\n\ndef spare(x):\n    return x\n");
    t.write("lib/mid.py", "from lib.core import deepest\n\n\ndef middle(x):\n    return deepest(x) * 2\n");
    t.write("lib/top.py", "from lib.mid import middle\n\n\ndef top(x):\n    return middle(x)\n");
    t.write("tests/test_top.py", "from lib.top import top\n\n\ndef test_top():\n    assert top(1) == 4\n");
    t.write("tests/test_other.py", "from lib.core import spare\n\n\ndef test_spare():\n    assert spare(1) == 1\n");
    t.write("lib/dups.py", &format!("{}\n\n{}\n\n{}", long_fn("old_a", "alpha"), long_fn("old_b", "alpha"), long_fn("unique", "beta")));
    let sha = t.commit("base");
    (t, sha)
}

/// The head: `deepest` edited, `copy_of_unique` added in a new file, `old_b` edited by one word
/// (still a duplicate of `old_a`, as in the base).
fn head(t: &Tree) -> String {
    t.write("lib/core.py", "def deepest(x):\n    return x + 2\n\n\ndef spare(x):\n    return x\n");
    t.write("lib/fresh.py", &long_fn("copy_of_unique", "beta"));
    let dups = fs::read_to_string(t.root.join("lib/dups.py")).unwrap();
    let edited = dups.replacen("rounding_mode", "rounding_style", 2);
    let (a, b) = edited.split_once("def old_b").unwrap();
    t.write("lib/dups.py", &format!("{}def old_b{}", a.replace("rounding_style", "rounding_mode"), b));
    t.commit("head")
}

#[test]
fn the_comment_names_the_changed_symbols_their_callers_the_tests_and_only_the_new_duplicate() {
    let (t, base_sha) = base("comment");
    let head_sha = head(&t);
    // the pair the base already had is a duplicate in the head too: only the new copy is new
    let (_, dupes, _) = t.run(&["dupes", "--json"]);
    assert!(dupes.contains("old_a") && dupes.contains("copy_of_unique"), "{dupes}");

    let md = t.review(&["--base", &base_sha]);
    let lines: Vec<&str> = md.lines().collect();
    assert_eq!(lines[0], "<!-- scrutate-review -->", "{md}");
    assert_eq!(lines[1], format!("**scrutate review** of `HEAD` ({}) against `{}`", &head_sha[..12], &base_sha[..12]), "{md}");
    assert!(md.contains("\n- `lib/core.py:1-2` function `deepest` (edited)\n"), "{md}");
    // `old_b` is changed, and still the duplicate of `old_a` it was in the base
    assert!(md.contains("\n- `lib/dups.py:13-22` function `old_b` (edited, no test reaches it)\n"), "{md}");
    assert!(md.contains("\n- `lib/fresh.py:1-10` function `copy_of_unique` (added, no test reaches it)\n"), "{md}");
    assert!(md.contains("\n- `lib/mid.py:4-5` function `middle` (distance 1)\n- `lib/top.py:4-5` function `top` (distance 2)\n"), "{md}");
    assert!(md.contains("#### Tests to run\n\n- `tests/test_top.py` (distance 3, through `test_top`)\n"), "{md}");
    assert!(!md.contains("test_other"), "{md}");
    let dup_section = md.split("#### New duplicates\n\n").nth(1).unwrap_or_else(|| panic!("{md}"));
    let dup_lines: Vec<&str> = dup_section.lines().take_while(|l| l.starts_with("- ")).collect();
    assert_eq!(dup_lines.len(), 1, "{md}");
    assert!(dup_lines[0].starts_with("- exact, ") && dup_lines[0].contains("`copy_of_unique`") && dup_lines[0].contains("`unique`"), "{md}");
    assert!(!dup_section.contains("old_a"), "{md}");
    assert!(lines[3].starts_with("3 changed definitions, ") && lines[3].contains("1 new duplicate"), "{md}");

    // the same on every run, an explicit head is the same report, and links point at the lines
    assert_eq!(t.review(&["--base", &base_sha]), md);
    assert_eq!(t.review(&["--base", &base_sha, "--head", &head_sha]).lines().skip(2).collect::<Vec<_>>(), lines[2..].to_vec());
    let linked = t.review(&["--base", &base_sha, "--link", "https://github.com/o/r/blob/abc/"]);
    assert!(linked.contains("- [`lib/core.py:1-2`](https://github.com/o/r/blob/abc/lib/core.py#L1-L2) function `deepest` (edited)"), "{linked}");

    // the JSON holds the same items
    let v: Value = serde_json::from_str(&t.review(&["--base", &base_sha, "--format", "json"])).unwrap();
    let r = &v["result"];
    assert_eq!(r["head_commit"], head_sha);
    assert_eq!(r["new_duplicates"].as_array().unwrap().len(), 1, "{r}");
    assert_eq!(r["untested"], serde_json::json!(["lib/dups.py:13-22", "lib/fresh.py:1-10"]));
    assert_eq!(r["tests"][0]["path"], "tests/test_top.py");
}

/// Checks a value against GitLab's Code Quality format: a list of issues, each with a
/// `description`, `check_name`, `fingerprint`, `severity` of the five GitLab knows, and a
/// `location` with a relative `path` and `lines.begin`, a line number from 1.
fn code_quality_errors(v: &Value) -> Vec<String> {
    let mut errors = Vec::new();
    let Some(issues) = v.as_array() else { return vec!["not a list".into()] };
    let mut prints = std::collections::HashSet::new();
    for (n, i) in issues.iter().enumerate() {
        let mut err = |what: &str| errors.push(format!("issue {n}: {what}: {i}"));
        for key in ["description", "check_name", "fingerprint"] {
            if !i[key].as_str().is_some_and(|s| !s.is_empty()) {
                err(&format!("{key} is not a non-empty string"));
            }
        }
        if !matches!(i["severity"].as_str(), Some("info" | "minor" | "major" | "critical" | "blocker")) {
            err("severity is not one of info, minor, major, critical, blocker");
        }
        match i["location"]["path"].as_str() {
            Some(p) if !p.is_empty() && !p.starts_with('/') && !p.contains('\\') => {}
            _ => err("location.path is not a relative path"),
        }
        if !i["location"]["lines"]["begin"].as_u64().is_some_and(|l| l >= 1) {
            err("location.lines.begin is not a line number");
        }
        if !prints.insert(i["fingerprint"].as_str().unwrap_or_default().to_string()) {
            err("fingerprint is not unique");
        }
    }
    errors
}

#[test]
fn the_gitlab_report_is_code_quality_json_with_the_new_duplicate_and_the_untested_change() {
    let (t, base_sha) = base("gitlab");
    head(&t);
    let out = t.review(&["--base", &base_sha, "--format", "gitlab"]);
    let v: Value = serde_json::from_str(&out).unwrap();
    assert_eq!(code_quality_errors(&v), Vec::<String>::new());
    let issues: Vec<(&str, &str, &str, u64)> = v
        .as_array()
        .unwrap()
        .iter()
        .map(|i| {
            (
                i["check_name"].as_str().unwrap(),
                i["severity"].as_str().unwrap(),
                i["location"]["path"].as_str().unwrap(),
                i["location"]["lines"]["begin"].as_u64().unwrap(),
            )
        })
        .collect();
    assert_eq!(
        issues,
        [
            ("scrutate-duplicate", "minor", "lib/fresh.py", 1),
            ("scrutate-untested-change", "info", "lib/dups.py", 13),
            ("scrutate-untested-change", "info", "lib/fresh.py", 1)
        ],
        "{out}"
    );
    assert!(v[0]["description"].as_str().unwrap().contains("unique at lib/dups.py:"), "{out}");
    // the fingerprints stay when the lines move, so GitLab matches the issue across pushes
    t.write("lib/fresh.py", &format!("\n\n{}", long_fn("copy_of_unique", "beta")));
    t.commit("moved");
    let moved: Value = serde_json::from_str(&t.review(&["--base", &base_sha, "--format", "gitlab"])).unwrap();
    assert_eq!(moved[0]["fingerprint"], v[0]["fingerprint"]);
    assert_eq!(moved[0]["location"]["lines"]["begin"], 3);
    // the checker refuses what GitLab refuses
    assert!(!code_quality_errors(
        &serde_json::json!([{"description": "x", "check_name": "c", "fingerprint": "f", "severity": "bad", "location": {"path": "/a", "lines": {"begin": 0}}}])
    )
    .is_empty());
}

#[test]
fn no_change_is_a_report_that_says_so_and_a_bad_revision_is_an_error() {
    let (t, base_sha) = base("empty");
    let (code, out, _) = t.run(&["review", "--base", &base_sha]);
    assert_eq!(code, 1);
    assert!(out.starts_with("<!-- scrutate-review -->\n") && out.contains("No changed definitions and no new duplicates."), "{out}");
    let (code, out, _) = t.run(&["review", "--base", &base_sha, "--format", "gitlab"]);
    assert_eq!((code, out.trim()), (1, "[]"));
    let (code, _, err) = t.run(&["review", "--base=--output=x"]);
    assert_eq!(code, 2);
    assert!(err.contains("not a revision: --output=x"), "{err}");
    let (code, _, err) = t.run(&["review", "--base", &base_sha, "--head=--output=x"]);
    assert_eq!(code, 2);
    assert!(err.contains("not a revision: --output=x"), "{err}");
    let (code, _, err) = t.run(&["review", "--base", &base_sha, "--head", "nope"]);
    assert_eq!(code, 2);
    assert!(err.contains("not a revision of this repository: nope"), "{err}");
    assert!(!t.root.join("x").exists());
}

#[test]
fn a_moved_duplicate_stays_out_and_a_third_copy_of_a_pair_is_new() {
    let (t, base_sha) = base("moved");
    // `old_b` moves to another file unchanged: the pair is the base's, by its body text
    let dups = fs::read_to_string(t.root.join("lib/dups.py")).unwrap();
    let old_b = long_fn("old_b", "alpha");
    t.write("lib/dups.py", &dups.replacen(&old_b, "", 1));
    t.write("lib/moved.py", &old_b);
    t.commit("moved");
    let md = t.review(&["--base", &base_sha]);
    assert!(!md.contains("#### New duplicates"), "{md}");
    // a third copy of the pair makes a group the base did not have
    t.write("lib/third.py", &long_fn("old_c", "alpha"));
    t.commit("third");
    let md = t.review(&["--base", &base_sha]);
    let dup = md.split("#### New duplicates\n\n").nth(1).unwrap_or_else(|| panic!("{md}"));
    assert!(dup.starts_with("- exact, ") && dup.contains("`old_a`") && dup.contains("`old_b`") && dup.contains("`old_c`"), "{md}");
}

/// The GitHub Action's comment script, run with a stand-in `gh` that logs its arguments, prints
/// the recorded comments for a list call and keeps the body it was given.
#[cfg(unix)]
mod comment_script {
    use super::*;
    use std::os::unix::fs::PermissionsExt;

    const SCRIPT: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../.github/actions/scrutate/comment.sh");
    const FAKE_GH: &str = "#!/bin/sh\nprintf '%s\\n' \"$*\" >> \"$FAKE_LOG\"\n[ -z \"$FAKE_FAIL\" ] || exit 1\ncase \"$*\" in\n  *--paginate*) cat \"$FAKE_COMMENTS\" ;;\n  \"api user -q .login\") [ -n \"$FAKE_LOGIN\" ] || exit 1; echo \"$FAKE_LOGIN\" ;;\n  *) for a; do case $a in body=@*) cp \"${a#body=@}\" \"$FAKE_BODY\" ;; esac; done; echo '{}' ;;\nesac\n";

    struct Run {
        code: i32,
        out: String,
        log: String,
        body: String,
    }

    fn run(t: &Tree, comments: &str, env: &[(&str, &str)]) -> Run {
        let dir = t.root.join(".fake");
        fs::create_dir_all(&dir).unwrap();
        let gh = dir.join("gh");
        fs::write(&gh, FAKE_GH).unwrap();
        fs::set_permissions(&gh, fs::Permissions::from_mode(0o755)).unwrap();
        fs::write(dir.join("comments.json"), comments).unwrap();
        let _ = fs::remove_file(dir.join("log"));
        let _ = fs::remove_file(dir.join("body"));
        let bin_dir = Path::new(BIN).parent().unwrap();
        let path = format!("{}:{}:{}", dir.display(), bin_dir.display(), std::env::var("PATH").unwrap_or_default());
        let out = Command::new("bash")
            .arg(SCRIPT)
            .current_dir(&t.root)
            .envs(GIT_ENV)
            .env("PATH", path)
            .env("SCRUTATE_SEMANTIC", "none")
            .env("FAKE_LOG", dir.join("log"))
            .env("FAKE_COMMENTS", dir.join("comments.json"))
            .env("FAKE_BODY", dir.join("body"))
            .env("FAKE_FAIL", "")
            .env("RUNNER_TEMP", &dir)
            .env("REPO", "o/r")
            .env("SERVER_URL", "https://github.com")
            .envs(env.iter().copied())
            .stdin(Stdio::null())
            .output()
            .unwrap();
        Run {
            code: out.status.code().unwrap_or(-1),
            out: String::from_utf8_lossy(&out.stdout).into_owned(),
            log: fs::read_to_string(dir.join("log")).unwrap_or_default(),
            body: fs::read_to_string(dir.join("body")).unwrap_or_default(),
        }
    }

    fn comment(id: u64, kind: &str, body: &str) -> Value {
        serde_json::json!({"id": id, "user": {"type": kind, "login": if kind == "Bot" { "github-actions[bot]" } else { "someone" }}, "body": body})
    }

    #[test]
    fn the_comment_is_posted_once_then_edited_in_place() {
        let (t, base_sha) = base("script");
        head(&t);
        // .fake is no part of the repository
        t.write(".gitignore", ".fake/\n");
        t.commit("ignore");
        let pr = [("PR_NUMBER", "5"), ("BASE_SHA", base_sha.as_str())];

        // no earlier comment: one is posted on the pull request
        let first = run(&t, "[]", &pr);
        assert_eq!(first.code, 0, "{}", first.out);
        let calls: Vec<&str> = first.log.lines().collect();
        assert_eq!(
            calls,
            [
                "api --paginate repos/o/r/issues/5/comments?per_page=100",
                &format!("api -X POST repos/o/r/issues/5/comments -F body=@{}", t.root.join(".fake/scrutate-review.md").display())
            ]
        );
        assert!(first.body.starts_with("<!-- scrutate-review -->\n") && first.body.contains("`copy_of_unique`"), "{}", first.body);
        assert!(first.body.contains("](https://github.com/o/r/blob/"), "{}", first.body);

        // the bot's comment with the marker is edited, on the second page too; a person's comment
        // that quotes the marker and a bot's comment without it are left alone
        let pages = format!(
            "{}\n{}",
            Value::Array(vec![comment(3, "User", "<!-- scrutate-review -->\nquoted"), comment(4, "Bot", "another bot")]),
            Value::Array(vec![comment(7, "Bot", &first.body), comment(9, "Bot", "<!-- scrutate-review -->\nlater")])
        );
        let second = run(&t, &pages, &pr);
        assert_eq!(second.code, 0, "{}", second.out);
        assert_eq!(
            second.log.lines().nth(1).unwrap(),
            format!("api -X PATCH repos/o/r/issues/comments/7 -F body=@{}", t.root.join(".fake/scrutate-review.md").display())
        );
        assert_eq!(second.log.lines().count(), 2);
        assert!(second.out.contains("edited comment 7"), "{}", second.out);
    }

    #[test]
    fn with_a_persons_token_the_comment_of_that_person_is_edited() {
        let (t, base_sha) = base("scriptuser");
        head(&t);
        t.write(".gitignore", ".fake/\n");
        t.commit("ignore");
        let theirs = serde_json::json!({"id": 11, "user": {"type": "User", "login": "the-owner"}, "body": "<!-- scrutate-review -->\nearlier"});
        let other = serde_json::json!({"id": 12, "user": {"type": "User", "login": "someone"}, "body": "<!-- scrutate-review -->\nquoted"});
        let comments = Value::Array(vec![other, theirs]).to_string();
        let pr = [("PR_NUMBER", "5"), ("BASE_SHA", base_sha.as_str()), ("FAKE_LOGIN", "the-owner")];
        let run1 = run(&t, &comments, &pr);
        assert_eq!(run1.code, 0, "{}", run1.out);
        assert!(run1.log.contains("api -X PATCH repos/o/r/issues/comments/11"), "{}", run1.log);
        // GITHUB_TOKEN cannot ask who it is: a person's comment is never taken for the bot's
        let run2 = run(&t, &comments, &[("PR_NUMBER", "5"), ("BASE_SHA", base_sha.as_str()), ("FAKE_LOGIN", "")]);
        assert_eq!(run2.code, 0, "{}", run2.out);
        assert!(run2.log.contains("api -X POST repos/o/r/issues/5/comments"), "{}", run2.log);
    }

    #[test]
    fn a_failure_is_a_warning_and_no_input_reaches_a_shell() {
        let (t, base_sha) = base("scriptfail");
        // gh fails: a warning, exit 0
        let failed = run(&t, "[]", &[("PR_NUMBER", "5"), ("BASE_SHA", &base_sha), ("FAKE_FAIL", "1")]);
        assert_eq!(failed.code, 0);
        assert!(failed.out.contains("::warning::scrutate review comment: cannot list"), "{}", failed.out);
        // not a pull request: nothing runs
        let none = run(&t, "[]", &[("PR_NUMBER", ""), ("BASE_SHA", &base_sha)]);
        assert_eq!((none.code, none.log.as_str()), (0, ""));
        assert!(none.out.contains("not a pull request"), "{}", none.out);
        // values that would run a command in a shell are refused before anything runs
        let marker = t.root.join("ran");
        let evil = format!("$(touch {})", marker.display());
        let cases = [
            [("PR_NUMBER", evil.as_str()), ("BASE_SHA", base_sha.as_str()), ("REPO", "o/r")],
            [("PR_NUMBER", "5"), ("BASE_SHA", evil.as_str()), ("REPO", "o/r")],
            [("PR_NUMBER", "5"), ("BASE_SHA", base_sha.as_str()), ("REPO", evil.as_str())],
        ];
        for env in cases {
            let r = run(&t, "[]", &env);
            assert_eq!((r.code, r.log.as_str()), (0, ""), "{}", r.out);
            assert!(r.out.contains("::warning::"), "{}", r.out);
        }
        assert!(!marker.exists());
        // a base commit the checkout does not have
        let missing = run(&t, "[]", &[("PR_NUMBER", "5"), ("BASE_SHA", &"1".repeat(40))]);
        assert!(missing.out.contains("fetch-depth: 0") && missing.log.is_empty(), "{}", missing.out);
    }
}

//! `scrutate tsquery --rewrite` on trees made for each test: the diff it prints, the files it
//! writes, a second run, overlapping matches, text that does not parse, a file edited between the
//! read and the write, and what the index answers afterwards.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

const BIN: &str = env!("CARGO_BIN_EXE_scrutate");

const PRINT: &str = r#"(call function: (identifier) @f (#eq? @f "print") arguments: (argument_list) @args) @match"#;

struct Tree {
    root: PathBuf,
}

impl Tree {
    fn new(name: &str) -> Tree {
        let root = Path::new(env!("CARGO_TARGET_TMPDIR")).join(format!("rewrite_{name}_{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        // its own repository, so the work tree above lends it no ignore file
        fs::create_dir_all(root.join(".git")).unwrap();
        Tree { root: fs::canonicalize(root).unwrap() }
    }

    fn write(&self, rel: &str, text: &str) {
        let p = self.root.join(rel);
        fs::create_dir_all(p.parent().unwrap()).unwrap();
        fs::write(p, text).unwrap();
    }

    fn read(&self, rel: &str) -> String {
        fs::read_to_string(self.root.join(rel)).unwrap()
    }

    /// (exit code, standard output, standard error)
    fn run(&self, args: &[&str]) -> (i32, String, String) {
        let state = self.root.with_extension("state");
        let out = Command::new(BIN)
            .args(["--root", self.root.to_str().unwrap()])
            .args(args)
            .current_dir(&self.root)
            .env("SCRUTATE_SEMANTIC", "none")
            .env("XDG_STATE_HOME", &state)
            .stdin(Stdio::null())
            .output()
            .unwrap();
        (out.status.code().unwrap_or(-1), String::from_utf8_lossy(&out.stdout).into_owned(), String::from_utf8_lossy(&out.stderr).into_owned())
    }

    /// The names in the tree, temporary files included.
    fn names(&self) -> Vec<String> {
        let mut v: Vec<String> = fs::read_dir(&self.root).unwrap().flatten().map(|e| e.file_name().to_string_lossy().into_owned()).collect();
        v.sort();
        v
    }
}

impl Drop for Tree {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.root);
        let _ = fs::remove_dir_all(self.root.with_extension("state"));
    }
}

#[test]
fn print_becomes_log_as_a_diff_then_written_then_nothing_is_left_to_change() {
    let t = Tree::new("print");
    let before = "import os\n\n\ndef main(x, y):\n    print(x)\n    value = 1\n    print(\"a\", y)\n    return value\n";
    t.write("a.py", before);
    t.write("b.py", "def other():\n    return 2\n");
    let rw = ["tsquery", "python", PRINT, "--rewrite", "log$args"];
    let names = t.names();

    let (code, out, err) = t.run(&rw);
    assert_eq!(code, 0, "{err}");
    assert_eq!(
        out,
        "--- a.py\n+++ a.py\n@@ -2,7 +2,7 @@\n \n \n def main(x, y):\n-    print(x)\n+    log(x)\n     value = 1\n-    print(\"a\", y)\n+    log(\"a\", y)\n     return value\n"
    );
    assert_eq!(t.read("a.py"), before, "the diff mode writes nothing");
    assert_eq!(t.names(), names);

    let (code, out, err) = t.run(&[&rw[..], &["--write"]].concat());
    assert_eq!((code, out.as_str(), err.as_str()), (0, "a.py: 2 replaced\n", ""));
    assert_eq!(t.read("a.py"), "import os\n\n\ndef main(x, y):\n    log(x)\n    value = 1\n    log(\"a\", y)\n    return value\n");
    assert_eq!(t.read("b.py"), "def other():\n    return 2\n");
    assert_eq!(t.names(), names, "no temporary file is left");

    for args in [&rw[..], &[&rw[..], &["--write"]].concat()] {
        assert_eq!(t.run(args), (1, String::new(), String::new()), "a second run finds nothing to change");
    }
}

#[test]
fn far_apart_changes_are_hunks_of_their_own_and_line_ends_stay_as_they_were() {
    let t = Tree::new("hunks");
    let mut lines: Vec<String> = (0..12).map(|i| format!("x{i} = {i}")).collect();
    lines[0] = "print(a)".into();
    lines[11] = "print(b)".into();
    t.write("a.py", &format!("{}\r\n{}", lines[..2].join("\r\n"), lines[2..].join("\n")));
    let (code, out, _) = t.run(&["tsquery", "python", PRINT, "--rewrite", "log$args"]);
    assert_eq!(code, 0);
    assert_eq!(
        out,
        "--- a.py\n+++ a.py\n@@ -1,4 +1,4 @@\n-print(a)\r\n+log(a)\r\n x1 = 1\r\n x2 = 2\n x3 = 3\n\
         @@ -9,4 +9,4 @@\n x8 = 8\n x9 = 9\n x10 = 10\n-print(b)\n\\ No newline at end of file\n+log(b)\n\\ No newline at end of file\n"
    );
    assert_eq!(t.run(&["tsquery", "python", PRINT, "--rewrite", "log$args", "--write"]).0, 0);
    assert_eq!(t.read("a.py"), format!("log(a)\r\nx1 = 1\r\n{}", lines[2..].join("\n").replace("print(b)", "log(b)")));
}

#[test]
fn a_javascript_call_is_rewritten_with_a_braced_capture_before_a_letter() {
    let t = Tree::new("js");
    t.write("app.js", "const r = fs.read(path, 'utf8');\nfs.read(other);\nconsole.log(r);\n");
    let q = r#"(call_expression function: (member_expression object: (identifier) @o (#eq? @o "fs") property: (property_identifier) @p) arguments: (arguments) @a) @match"#;
    let (code, out, err) = t.run(&["tsquery", "javascript", q, "--rewrite", "$o.${p}Async$a", "--write"]);
    assert_eq!((code, out.as_str(), err.as_str()), (0, "app.js: 2 replaced\n", ""));
    assert_eq!(t.read("app.js"), "const r = fs.readAsync(path, 'utf8');\nfs.readAsync(other);\nconsole.log(r);\n");
    // `$$` is a dollar
    let (code, _, err) = t.run(&["tsquery", "javascript", "((identifier) @i (#eq? @i \"r\"))", "--rewrite", "$$r", "--write"]);
    assert_eq!(code, 0, "{err}");
    assert_eq!(t.read("app.js"), "const $r = fs.readAsync(path, 'utf8');\nfs.readAsync(other);\nconsole.log($r);\n");
}

#[test]
fn without_match_the_widest_capture_is_replaced() {
    let t = Tree::new("widest");
    t.write("a.py", "print(x)\n");
    let q = r#"(call function: (identifier) @f (#eq? @f "print") arguments: (argument_list) @args) @call"#;
    assert_eq!(t.run(&["tsquery", "python", q, "--rewrite", "log$args", "--write"]).0, 0);
    assert_eq!(t.read("a.py"), "log(x)\n");
}

#[test]
fn of_two_overlapping_matches_the_outer_one_is_rewritten_and_the_inner_one_reported() {
    let t = Tree::new("overlap");
    t.write("a.py", "print(print(x))\n");
    let (code, out, err) = t.run(&["tsquery", "python", PRINT, "--rewrite", "log$args", "--write"]);
    assert_eq!((code, out.as_str()), (0, "a.py: 1 replaced\n"));
    assert_eq!(err, "scrutate: warning: a.py:1:7: inside the match at 1:1, not rewritten\n");
    // the inner capture's text is the original's
    assert_eq!(t.read("a.py"), "log(print(x))\n");
}

#[test]
fn a_file_that_does_not_parse_where_it_would_change_is_left_alone() {
    let t = Tree::new("broken");
    t.write("bad.py", "print(1 +)\n");
    t.write("good.py", "print(x)\n");
    let (code, out, err) = t.run(&["tsquery", "python", PRINT, "--rewrite", "log$args", "--write"]);
    assert_eq!((code, out.as_str()), (2, "good.py: 1 replaced\n"));
    assert_eq!(err, "scrutate: warning: bad.py: a match holds text that does not parse, left alone\n");
    assert_eq!(t.read("bad.py"), "print(1 +)\n");
    // a template whose output does not parse changes nothing
    t.write("good.py", "print(x)\n");
    let (code, out, err) = t.run(&["tsquery", "python", PRINT, "--rewrite", "log($args", "--write"]);
    assert_eq!((code, out.as_str()), (2, ""));
    assert!(err.contains("good.py: the rewritten text does not parse, left alone"), "{err}");
    assert_eq!(t.read("good.py"), "print(x)\n");
}

#[test]
fn a_file_edited_between_the_read_and_the_write_is_left_alone_and_reported() {
    let t = Tree::new("race");
    t.write("a.py", "print(x)\n");
    t.write("b.py", "print(y)\n");
    let plan = scrutate::rewrite::plan("python", PRINT, "log$args", std::slice::from_ref(&t.root), &t.root).unwrap();
    assert_eq!(plan.files.len(), 2);
    t.write("a.py", "print(z)\n");
    let left = plan.write();
    assert_eq!(left.len(), 2);
    assert!(left[0].as_deref().is_some_and(|w| w.ends_with("a.py: changed since it was read, left alone")), "{left:?}");
    assert_eq!(left[1], None);
    assert_eq!(t.read("a.py"), "print(z)\n");
    assert_eq!(t.read("b.py"), "log(y)\n");
    assert!(!t.names().iter().any(|n| n.ends_with(".tmp")), "{:?}", t.names());
}

#[test]
fn the_index_answers_with_the_new_text_after_a_write() {
    let t = Tree::new("index");
    t.write("a.py", "def old_name():\n    return 1\n\n\ndef caller():\n    return old_name()\n");
    assert_eq!(t.run(&["index"]).0, 0);
    assert!(t.run(&["symbol", "old_name"]).1.contains("a.py"));
    let q = r#"((identifier) @match (#eq? @match "old_name"))"#;
    let (code, out, err) = t.run(&["tsquery", "python", q, "--rewrite", "new_name", "--write"]);
    assert_eq!((code, out.as_str(), err.as_str()), (0, "a.py: 2 replaced\n", ""));
    let (code, out, _) = t.run(&["symbol", "new_name"]);
    assert_eq!(code, 0);
    assert!(out.contains("a.py:1"), "{out}");
    assert_eq!(t.run(&["symbol", "old_name"]).0, 1);
    for grep in [&["grep", "-F", "new_name", "."][..], &["grep", "--index", "--update", "-F", "new_name"]] {
        let (code, out, err) = t.run(grep);
        assert_eq!(code, 0, "{grep:?} {err}");
        assert_eq!(out.lines().count(), 2, "{grep:?} {out}");
    }
    assert_eq!(t.run(&["grep", "--index", "--update", "-F", "old_name"]).0, 1);
}

#[test]
fn a_bad_template_is_an_error_and_the_options_are_checked() {
    let t = Tree::new("errors");
    t.write("a.py", "print(x)\n");
    for (template, says) in [("log($nope)", "the query has no @nope"), ("cost$", "write $$ for a dollar"), ("${args", "without its }")] {
        let (code, _, err) = t.run(&["tsquery", "python", PRINT, "--rewrite", template]);
        assert_eq!(code, 2);
        assert!(err.contains(says), "{template}: {err}");
    }
    assert_eq!(t.run(&["tsquery", "python", PRINT, "--write"]).0, 2, "--write needs --rewrite");
    assert_eq!(t.run(&["tsquery", "python", PRINT, "--rewrite", "x", "--json"]).0, 2);
    assert_eq!(t.run(&["tsquery", "python", PRINT, "--rewrite", "x", "--offset", "1"]).0, 2);
    // a size limit, as SCRUTATE_MAX_BYTES may set for every command, does not cut the diff
    let (code, out, _) = t.run(&["--max-bytes", "10", "tsquery", "python", PRINT, "--rewrite", "log$args"]);
    assert_eq!((code, out.as_str()), (0, "--- a.py\n+++ a.py\n@@ -1,1 +1,1 @@\n-print(x)\n+log(x)\n"));
    assert_eq!(t.read("a.py"), "print(x)\n");
}

#[cfg(unix)]
#[test]
fn a_link_out_of_the_root_is_never_written_and_permissions_are_kept() {
    use std::os::unix::fs::PermissionsExt;
    let t = Tree::new("link");
    let outside = Tree::new("link_outside");
    outside.write("o.py", "print(secret)\n");
    std::os::unix::fs::symlink(outside.root.join("o.py"), t.root.join("o.py")).unwrap();
    t.write("a.py", "print(x)\n");
    fs::set_permissions(t.root.join("a.py"), fs::Permissions::from_mode(0o640)).unwrap();
    let (code, out, err) = t.run(&["tsquery", "python", PRINT, ".", "o.py", "--rewrite", "log$args", "--write"]);
    assert_eq!((code, out.as_str()), (2, "a.py: 1 replaced\n"), "{err}");
    assert!(err.contains("o.py: outside the root, left alone"), "{err}");
    assert_eq!(outside.read("o.py"), "print(secret)\n");
    assert_eq!(fs::metadata(t.root.join("a.py")).unwrap().permissions().mode() & 0o777, 0o640);
}

//! Section-12 reliability tests: hostile inputs, filesystem oddities, index corruption, concurrent
//! writers and incremental updates. Every test builds a throw-away repository under a temp dir.
//! Nothing here may panic; wrong answers fail assertions.

use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::AtomicBool;
use std::sync::Arc;

use scrutate::index::Index;
use scrutate::instant::{self, Files, Mode, Output, Pattern, Query, Record};
use scrutate::parse::parse_source;

struct Repo {
    root: PathBuf,
}

impl Repo {
    fn new(name: &str) -> Repo {
        let root = std::env::temp_dir().join(format!("scrutate_rob_{}_{}", name, std::process::id()));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).unwrap();
        Repo { root }
    }
    fn write(&self, rel: &str, bytes: &[u8]) -> PathBuf {
        let p = self.root.join(rel);
        fs::create_dir_all(p.parent().unwrap()).unwrap();
        fs::write(&p, bytes).unwrap();
        p
    }
    fn index(&self) -> Index {
        // no semantic model: these tests are about robustness, not ranking
        Index::open(&self.root, scrutate::models::ModelSet::none()).expect("open index")
    }
}

impl Drop for Repo {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.root);
    }
}

fn query(pattern: &str, mode: Mode) -> Query {
    Query { pattern: Pattern { text: pattern.to_string(), mode, ..Pattern::default() }, ..Query::default() }
}

fn grep(root: &Path, pattern: &str, mode: Mode) -> (Vec<instant::Line>, instant::Stats) {
    let mut hits = Vec::new();
    let mut sink = |r: Record| {
        if let Record::Match(h) = r {
            hits.push(h)
        }
    };
    let st = instant::search(&query(pattern, mode), &Files::walk(vec![root.to_path_buf()]), Arc::default(), Output::Records(&mut sink)).expect("search");
    (hits, st)
}

fn count_chunks(ix: &Index) -> i64 {
    ix.stats().unwrap()["chunks"].as_i64().unwrap()
}

// ------------------------------------------------------------------------- encodings and text shapes

#[test]
fn hostile_text_shapes_never_panic() {
    let r = Repo::new("shapes");
    // invalid UTF-8 inside a Python file (lossy-decoded, still indexed)
    r.write("bad_utf8.py", b"def ok():\n    return '\xff\xfe\xfa'\n");
    // UTF-8 BOM, CRLF, CR-only, no trailing newline, empty, whitespace-only
    r.write("bom.py", "\u{feff}def bom_func():\n    pass\n".as_bytes());
    r.write("crlf.py", b"def crlf_func():\r\n    return 1\r\n");
    r.write("cr.py", b"def cr_func():\r    return 1\r");
    r.write("nonl.py", b"def nonl_func():\n    return 1");
    r.write("empty.py", b"");
    r.write("blank.py", b"\n\n   \n\t\n");
    // UTF-16 with BOM (binary-looking because of NUL bytes: must be skipped, not crash)
    let mut u16le = vec![0xff, 0xfe];
    for u in "def utf16():\n    pass\n".encode_utf16() {
        u16le.extend_from_slice(&u.to_le_bytes());
    }
    r.write("utf16.py", &u16le);
    // multibyte characters everywhere, including right at the 4000-byte sniff boundary
    let mut m = String::from("# ");
    while m.len() < 3999 {
        m.push('н');
    }
    m.push_str("\n@interface Foo\n@end\n");
    r.write("boundary.m", m.as_bytes());
    r.write("emoji.py", "def 😀smile():\n    return '🌍'\n\nclass Ωmega:\n    def ñ(self): pass\n".as_bytes());
    // one very long line (5 MB) and many short lines
    let long = format!("x = \"{}\"\n", "a".repeat(5_000_000));
    r.write("longline.py", long.as_bytes()); // > MAX_FILE_BYTES: skipped by Engine B, searched by Engine A
    let short: String = (0..200_000).map(|i| format!("v{i} = {i}\n")).collect();
    r.write("manylines.py", short.as_bytes()); // ~2.5 MB: also skipped by Engine B
                                               // deep nesting in several grammars
    r.write("deep.py", format!("x = {}1{}\n", "[".repeat(5000), "]".repeat(5000)).as_bytes());
    r.write("deep.json", format!("{}1{}", "[".repeat(20000), "]".repeat(20000)).as_bytes());
    r.write("deep.js", format!("let x = {}1{};\n", "(".repeat(5000), ")".repeat(5000)).as_bytes());
    // NUL byte early: binary
    r.write("binary.py", b"def nope():\n\x00\x00\x00 binary\n");
    // NUL byte late (after the 4 KB sniff window): must still not break anything
    let mut late = b"def late_nul():\n    pass\n".to_vec();
    late.extend(std::iter::repeat_n(b'#', 5000));
    late.push(0);
    r.write("late_nul.py", &late);
    // extension case and no extension
    r.write("UPPER.PY", b"def upper_case_ext():\n    pass\n");
    r.write("Makefile", b"build:\n\tcargo build\n");
    r.write("noext", b"plain words here\n");
    r.write(".hidden.py", b"def hidden_dot_file():\n    pass\n");
    // long file name (255 bytes) and spaces / unicode in names
    r.write(&format!("{}.py", "n".repeat(251)), b"def long_name_file():\n    pass\n");
    r.write("dir with spaces/file ñame.py", b"def spaced():\n    pass\n");

    let mut ix = r.index();
    let st = ix.update(true).expect("update");
    assert!(st.files_total >= 20, "{st:?}");
    let s = ix.stats().unwrap();
    assert!(s["files_skipped"].as_i64().unwrap() >= 3, "utf16, binary and oversize files are skipped: {s}");

    // every well-formed definition is found
    let names = symbol_names(&ix);
    for want in ["ok", "bom_func", "crlf_func", "nonl_func", "upper_case_ext", "hidden_dot_file", "long_name_file", "spaced", "late_nul", "Ωmega"] {
        assert!(names.iter().any(|n| n == want), "missing symbol {want}; have {names:?}");
    }
    assert!(!names.iter().any(|n| n == "nope"), "binary file must not be indexed");

    // Engine A: searches the same tree without the index, including the oversize files
    let (hits, st) = grep(&r.root, "def ", Mode::Literal);
    assert!(st.errors == 0, "{st:?}");
    assert!(hits.iter().any(|h| h.path.ends_with("longline.py")) || !hits.is_empty());
    let (hits, _) = grep(&r.root, "v199999 = 199999", Mode::Literal);
    assert_eq!(hits.len(), 1, "manylines.py is searchable by Engine A");
    let (hits, _) = grep(&r.root, "aaaaaaaaaa", Mode::Literal);
    assert!(hits.iter().any(|h| h.path.ends_with("longline.py")), "5 MB line is searchable");
    let (hits, _) = grep(&r.root, "😀smile", Mode::Literal);
    assert_eq!(hits.len(), 1);
    let (hits, _) = grep(&r.root, "crlf_func", Mode::Literal);
    assert_eq!(hits.len(), 1);
    assert!(!hits[0].text.ends_with('\r'), "CR stripped from reported line text: {:?}", hits[0].text);
}

#[test]
fn parser_fuzz_smoke() {
    // random byte soup and random token soup through every tier of the parser
    let mut seed = 0x9E3779B97F4A7C15u64;
    let mut next = || {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        seed
    };
    let exts = ["py", "js", "ts", "go", "rs", "java", "c", "cpp", "rb", "php", "sh", "kt", "swift", "lua", "hs", "json", "yaml", "toml", "md", "zig", "ex"];
    let toks = [
        "def ",
        "fn ",
        "class ",
        "{",
        "}",
        "(",
        ")",
        "[",
        "]",
        "\n",
        "    ",
        "\"",
        "'",
        "x",
        "y1",
        "=",
        "->",
        "::",
        ".",
        "#",
        "//",
        "/*",
        "*/",
        "\u{1F600}",
        "é",
        "\t",
        "\\",
        "@",
        "import ",
        "<",
        ">",
    ];
    for i in 0..400 {
        let ext = exts[(next() % exts.len() as u64) as usize];
        let n = (next() % 400) as usize;
        let src: String = if i % 2 == 0 {
            (0..n).map(|_| toks[(next() % toks.len() as u64) as usize]).collect()
        } else {
            let bytes: Vec<u8> = (0..n).map(|_| (next() & 0xff) as u8).collect();
            String::from_utf8_lossy(&bytes).into_owned()
        };
        let chunks = parse_source(&format!("f{i}.{ext}"), &src);
        for c in &chunks {
            assert!(c.start >= 1 && c.end >= c.start, "bad range in {ext}: {c:?}");
        }
    }
}

