// ------------------------------------------------------------------------- incremental updates

#[test]
fn incremental_updates_track_edits_renames_and_deletes() {
    let r = Repo::new("incr");
    r.write("a.py", b"def alpha():\n    pass\n");
    r.write("b.py", b"def beta():\n    pass\n");
    let mut ix = r.index();
    ix.update(true).unwrap();
    let n0 = count_chunks(&ix);
    // no change: nothing re-indexed
    let st = ix.update(false).unwrap();
    assert_eq!(st.files_changed, 0);
    // touch without content change: nothing re-indexed (content hash)
    let t = filetime_now_plus(5);
    set_mtime(&r.root.join("a.py"), t);
    let st = ix.update(false).unwrap();
    assert_eq!(st.files_changed, 0, "mtime-only change must not re-index");
    // edit: one file re-indexed, old chunks gone
    r.write("a.py", b"def alpha2():\n    pass\n\ndef alpha3():\n    pass\n");
    set_mtime(&r.root.join("a.py"), filetime_now_plus(10));
    let st = ix.update(false).unwrap();
    assert_eq!(st.files_changed, 1);
    let names = symbol_names(&ix);
    assert!(names.contains(&"alpha2".to_string()) && names.contains(&"alpha3".to_string()) && !names.contains(&"alpha".to_string()), "{names:?}");
    // rename: old path removed, new path added
    fs::rename(r.root.join("b.py"), r.root.join("c.py")).unwrap();
    let st = ix.update(false).unwrap();
    assert_eq!(st.files_removed, 1);
    assert_eq!(st.files_changed, 1);
    let paths = ix.files().unwrap();
    assert!(paths.contains(&"c.py".to_string()) && !paths.contains(&"b.py".to_string()), "{paths:?}");
    // delete: chunks removed
    fs::remove_file(r.root.join("c.py")).unwrap();
    let st = ix.update(false).unwrap();
    assert_eq!(st.files_removed, 1);
    let paths = ix.files().unwrap();
    assert_eq!(paths, vec!["a.py".to_string()]);
    assert!(count_chunks(&ix) <= n0);
    // the live segment statistics agree with the database after all that
    let lex_n = ix.lex().unwrap().n_alive;
    assert_eq!(lex_n as i64, count_chunks(&ix));
}

fn symbol_names(ix: &Index) -> Vec<String> {
    ix.files().unwrap().iter().flat_map(|p| ix.outline(p).unwrap()).map(|r| r.name).collect()
}

fn filetime_now_plus(secs: u64) -> std::time::SystemTime {
    std::time::SystemTime::now() + std::time::Duration::from_secs(secs)
}

fn set_mtime(p: &Path, t: std::time::SystemTime) {
    let f = fs::OpenOptions::new().write(true).open(p).unwrap();
    f.set_modified(t).unwrap();
}

// ------------------------------------------------------------------------- corruption and recovery

#[test]
fn corrupted_index_is_detected_and_rebuilt() {
    let r = Repo::new("corrupt");
    for i in 0..30 {
        r.write(&format!("m{i}.py"), format!("def func_{i}():\n    return {i}\n").as_bytes());
    }
    {
        let mut ix = r.index();
        ix.update(true).unwrap();
        assert_eq!(symbol_names(&ix).len(), 30);
    }
    let dir = r.root.join(".scrutate");
    // 1. a segment file truncated to half
    let seg = fs::read_dir(dir.join("seg")).unwrap().next().unwrap().unwrap().path();
    let ids = seg.join("ids.npy");
    let bytes = fs::read(&ids).unwrap();
    fs::write(&ids, &bytes[..bytes.len() / 2]).unwrap();
    {
        let names = recover_and_names(&r.root);
        assert_eq!(names.len(), 30, "rebuilt after truncated segment");
    }
    // 2. a segment directory deleted entirely
    fs::remove_dir_all(&seg).ok();
    {
        let names = recover_and_names(&r.root);
        assert_eq!(names.len(), 30, "rebuilt after missing segment");
    }
    // 3. garbage written over the database header
    let db = dir.join("index.db");
    let mut bytes = fs::read(&db).unwrap();
    for b in bytes.iter_mut().take(200) {
        *b = 0x55;
    }
    fs::write(&db, &bytes).unwrap();
    let _ = fs::remove_file(dir.join("index.db-wal"));
    let _ = fs::remove_file(dir.join("index.db-shm"));
    {
        let names = recover_and_names(&r.root);
        assert_eq!(names.len(), 30, "rebuilt after corrupted database header");
    }
    // 4. database replaced by a non-database file
    fs::write(&db, b"this is not a database at all").unwrap();
    let _ = fs::remove_file(dir.join("index.db-wal"));
    {
        let names = recover_and_names(&r.root);
        assert_eq!(names.len(), 30, "rebuilt after bogus database file");
    }
    // 5. a corrupted vector/posting file with a valid header but garbage content
    let seg = fs::read_dir(dir.join("seg")).unwrap().next().unwrap().unwrap().path();
    let ptr0 = seg.join("ptr0.npy");
    let mut bytes = fs::read(&ptr0).unwrap();
    let n = bytes.len();
    for b in bytes.iter_mut().skip(n.saturating_sub(64)) {
        *b = 0xff;
    }
    fs::write(&ptr0, &bytes).unwrap();
    {
        let names = recover_and_names(&r.root);
        assert_eq!(names.len(), 30, "rebuilt or survived garbage postings");
    }
}

/// Open the repository as a front end does and read the segments (which validates them): damage
/// either meets is rebuilt from the sources.
fn recover_and_names(root: &Path) -> Vec<String> {
    let mut repo = scrutate::Repo::open(root).unwrap();
    repo.update(false).unwrap();
    let n = repo.recovering(|s| Ok(s.ix.lex()?.n_alive)).expect("store opens after recovery");
    assert!(n > 0);
    symbol_names(&repo.ix)
}

// ------------------------------------------------------------------------- concurrency

#[test]
fn concurrent_indexers_and_readers_do_not_corrupt() {
    let r = Repo::new("concurrent");
    for i in 0..40 {
        r.write(&format!("pkg/m{i}.py"), format!("def func_{i}(x):\n    return x + {i}\n").as_bytes());
    }
    let root = r.root.clone();
    let writers: Vec<_> = (0..3)
        .map(|w| {
            let root = root.clone();
            std::thread::spawn(move || {
                let mut ix = Index::open(&root, scrutate::models::ModelSet::none()).unwrap();
                for round in 0..3 {
                    fs::write(root.join(format!("pkg/w{w}.py")), format!("def writer_{w}_{round}():\n    pass\n")).unwrap();
                    ix.update(false).unwrap();
                }
            })
        })
        .collect();
    let readers: Vec<_> = (0..2)
        .map(|_| {
            let root = root.clone();
            std::thread::spawn(move || {
                let mut ix = Index::open(&root, scrutate::models::ModelSet::none()).unwrap();
                for _ in 0..20 {
                    let _ = ix.refresh(0.0).unwrap();
                    let n = ix.lex().unwrap().n_alive as i64;
                    assert!(n >= 0);
                }
            })
        })
        .collect();
    for t in writers.into_iter().chain(readers) {
        t.join().expect("thread");
    }
    let mut ix = r.index();
    ix.update(false).unwrap();
    let names = symbol_names(&ix);
    for w in 0..3 {
        assert!(names.contains(&format!("writer_{w}_2")), "final content of writer {w}: {names:?}");
        assert!(!names.contains(&format!("writer_{w}_0")), "stale chunk survived: {names:?}");
    }
    assert_eq!(ix.lex().unwrap().n_alive as i64, count_chunks(&ix));
    assert!(ix.check(false).unwrap().database_ok);
}

// ------------------------------------------------------------------------- Engine A resource limits

#[test]
fn regex_limits_and_errors_are_clean() {
    let r = Repo::new("regex");
    r.write("a.txt", format!("{}\n", "a".repeat(10_000)).as_bytes());
    // pathological patterns are linear here (no backtracking); must finish quickly
    let t = std::time::Instant::now();
    let (hits, st) = grep(&r.root, "(a*)*b", Mode::Regex);
    assert!(hits.is_empty() && st.errors == 0 && t.elapsed().as_secs() < 5);
    let (hits, _) = grep(&r.root, "(a|aa)+$", Mode::Regex);
    assert_eq!(hits.len(), 1);
    // an oversized regex is rejected with an error, not a crash or a hang
    let f = Files::walk(vec![r.root.clone()]);
    let mut sink = |_h: Record| {};
    let res = instant::search(&query("(a{1000}){1000}", Mode::Regex), &f, Arc::default(), Output::Records(&mut sink));
    assert!(res.is_err(), "regex over the size limit must be an error");
    // invalid regex: error
    let res = instant::search(&query("(unclosed", Mode::Regex), &f, Arc::default(), Output::Records(&mut sink));
    assert!(res.is_err());
    // fuzzy limits
    assert!(instant::FuzzyMatcher::new("", 1, false).is_err());
    assert!(instant::FuzzyMatcher::new("ab", 2, false).is_err());
    assert!(instant::FuzzyMatcher::new(&"x".repeat(instant::FUZZY_MAX + 1), 1, false).is_err());
    assert!(instant::FuzzyMatcher::new(&"x".repeat(instant::FUZZY_MAX), 1, false).is_ok());
    // cancellation flag stops a search
    let big: String = (0..300_000).map(|i| format!("line {i} needle\n")).collect();
    r.write("big.txt", big.as_bytes());
    let cancel = Arc::new(AtomicBool::new(false));
    let c2 = Arc::clone(&cancel);
    let mut n = 0u64;
    let mut sink = |_h: Record| {
        n += 1;
        if n == 10 {
            c2.store(true, std::sync::atomic::Ordering::Relaxed);
        }
    };
    let st = instant::search(&query("needle", Mode::Literal), &f, cancel, Output::Records(&mut sink)).unwrap();
    assert!(st.cancelled);
    assert!(n < 300_000, "stopped early after cancellation: {n}");
    // a search that stops at max_results stops itself: the caller's flag, shared with other work
    // of one call, stays as the caller left it
    let cancel = Arc::new(AtomicBool::new(false));
    for first_in_path_order in [false, true] {
        let q = Query { max_results: Some(5), first_in_path_order, ..query("needle", Mode::Literal) };
        let st = instant::search(&q, &f, Arc::clone(&cancel), Output::Records(&mut |_| {})).unwrap();
        assert!(st.cancelled && st.matches == 5, "{st:?}");
        assert!(!cancel.load(std::sync::atomic::Ordering::Relaxed), "first_in_path_order={first_in_path_order}");
    }
}

//! The count of big searches across processes, through the binary: what a stopped, killed or
//! blocked search does to it, and one check that searches started together share the threads and
//! take them back. Which searches are counted and what share each takes are tested with supplied
//! readings beside the thread rules (`instant::policy`). Searches of this user elsewhere on the
//! machine change the count, so the checks compare counts rather than expect fixed ones.
#![cfg(target_os = "macos")]

use std::io::{BufRead, BufReader};
use std::os::unix::process::CommandExt;
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::mpsc::{channel, Receiver};
use std::sync::{Mutex, OnceLock};
use std::time::Duration;

const BIN: &str = env!("CARGO_BIN_EXE_scrutate");

/// One test at a time: each one counts the searches the others start.
static ONE: Mutex<()> = Mutex::new(());

/// 4,000 files of 16 KB in 40 directories: a walk long enough to stop in the middle. Each file has
/// two lines with `needle`: 1,000 files (when a walk is counted) print about 48 KB, less than the
/// output buffer and a pipe hold, and 4,000 files 192 KB, more.
fn tree() -> &'static Path {
    static T: OnceLock<PathBuf> = OnceLock::new();
    T.get_or_init(|| {
        // kept between runs, only read: 64 MB is too much to write for every run
        let done = std::env::temp_dir().join("scrutate_running_tree_1");
        if done.is_dir() {
            return done;
        }
        let root = std::env::temp_dir().join(format!("scrutate_running_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let body = "needle\n".repeat(2) + &"a line of text, long enough to make the file take some time\n".repeat(270);
        for d in 0..40 {
            let dir = root.join(format!("d{d}"));
            std::fs::create_dir_all(&dir).unwrap();
            for f in 0..100 {
                std::fs::write(dir.join(format!("f{f}.txt")), &body).unwrap();
            }
        }
        // whole or not there: a run stopped while writing leaves only its own directory
        if std::fs::rename(&root, &done).is_err() {
            let _ = std::fs::remove_dir_all(&root);
        }
        done
    })
}

struct Search {
    child: Child,
    /// (searches running, threads) per debug line
    lines: Receiver<(usize, usize)>,
}

impl Search {
    fn start(args: &[&str], out: Stdio) -> Search {
        let mut child = Command::new(BIN)
            .arg("grep")
            .args(args)
            .arg(".")
            .current_dir(tree())
            .env("SCRUTATE_GREP_DEBUG", "1")
            .env_remove("SCRUTATE_THREADS")
            // a group of its own, as a shell gives a job: in a group with no parent outside it
            // the system drops SIGTSTP
            .process_group(0)
            .stdin(Stdio::null())
            .stdout(out)
            .stderr(Stdio::piped())
            .spawn()
            .unwrap();
        let err = child.stderr.take().unwrap();
        let (tx, lines) = channel();
        std::thread::spawn(move || {
            for line in BufReader::new(err).lines().map_while(Result::ok) {
                if let Some(rest) = line.strip_prefix("[scrutate] searches running: ") {
                    let (k, t) = rest.split_once(", threads: ").unwrap();
                    let _ = tx.send((k.parse().unwrap_or(0), t.parse().unwrap()));
                }
            }
        });
        Search { child, lines }
    }

    fn next(&self) -> (usize, usize) {
        self.lines.recv_timeout(Duration::from_secs(60)).expect("a debug line")
    }

    fn signal(&self, sig: &str) {
        assert!(self.try_signal(sig));
    }

    /// `false` when the search has ended. Sent with kill(2) at once: a shell started to send it
    /// takes long enough on a fast machine for the search to end before it arrives.
    fn try_signal(&self, sig: &str) -> bool {
        extern "C" {
            fn kill(pid: i32, sig: i32) -> i32;
        }
        // macOS numbers
        let n = match sig {
            "-KILL" => 9,
            "-STOP" => 17,
            "-TSTP" => 18,
            "-CONT" => 19,
            _ => panic!("no number for {sig}"),
        };
        // SAFETY: plain integers; the pid is our child's, not yet waited for
        unsafe { kill(self.child.id() as i32, n) == 0 }
    }

    fn finish(mut self) -> Vec<(usize, usize)> {
        self.child.wait().unwrap();
        self.lines.iter().collect()
    }
}

/// The count a big search sees when it starts, and the threads it takes then.
fn probe() -> (usize, usize) {
    let s = Search::start(&["-F", "nothing-matches-this"], Stdio::null());
    let first = s.next();
    s.finish();
    first
}

fn lock() -> std::sync::MutexGuard<'static, ()> {
    tree();
    ONE.lock().unwrap_or_else(|p| p.into_inner())
}

#[test]
fn a_stopped_search_is_counted_and_a_killed_one_is_not() {
    let _one = lock();
    let a = Search::start(&["-F", "nothing-matches-this"], Stdio::null());
    a.next();
    a.signal("-STOP");
    held(&a, "the first search");
    let mut ok = false;
    // another search of this user may start or end between the two probes: try again
    for _ in 0..5 {
        let (with, _) = probe();
        let b = Search::start(&["-F", "nothing-matches-this"], Stdio::null());
        b.next();
        b.signal("-STOP");
        held(&b, "the second search");
        let (more, _) = probe();
        b.signal("-KILL");
        b.finish();
        let (after, _) = probe();
        if more == with + 1 && after == with {
            ok = true;
            break;
        }
    }
    a.signal("-KILL");
    a.finish();
    assert!(ok, "a stopped search added 1 to the count and its kill took it back");
}

/// What a process sent a stop did within 10 s (a loaded machine can take seconds to run a stop
/// handler): it showed the stopped state, or it had ended. A process that ended and was not yet
/// waited for still accepts the signal, so a `kill` that succeeds does not say it runs.
#[derive(Debug, PartialEq)]
enum Stop {
    Stopped,
    Ended,
    Neither,
}

fn stop_seen(pid: u32) -> Stop {
    let start = std::time::Instant::now();
    while start.elapsed() < Duration::from_secs(10) {
        let out = Command::new("ps").args(["-o", "state=", "-p", &pid.to_string()]).output().unwrap();
        let state = String::from_utf8_lossy(&out.stdout);
        if state.contains('T') {
            return Stop::Stopped;
        }
        if state.trim().is_empty() || state.contains('Z') {
            return Stop::Ended;
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    Stop::Neither
}

/// Panics with what was seen unless the search is stopped: one that ended before the stop came
/// says so, with the machine's semaphores, so a fast or unusual machine reads as such.
fn held(s: &Search, what: &str) {
    let seen = stop_seen(s.child.id());
    if seen != Stop::Stopped {
        let ipcs = Command::new("ipcs").arg("-s").output().map(|o| String::from_utf8_lossy(&o.stdout).into_owned()).unwrap_or_default();
        panic!("{what}: the search shows {seen:?}, not stopped; its count lines so far: {:?}; ipcs -s:\n{ipcs}", s.lines.try_iter().collect::<Vec<_>>());
    }
}

#[test]
fn a_search_stopped_from_its_terminal_leaves_the_count_and_joins_again() {
    let _one = lock();
    let mut seen = Vec::new();
    // another search of this user may start or end between the probes: try again
    for _ in 0..5 {
        let (alone, _) = probe();
        let a = Search::start(&["-F", "nothing-matches-this"], Stdio::null());
        let first = a.next();
        // what Ctrl-Z sends
        a.signal("-TSTP");
        held(&a, "SIGTSTP stops the search");
        let (while_stopped, _) = probe();
        // a second search held while it is counted (SIGSTOP cannot be caught): the first one then
        // sees one search more than at its start, but only if it joins the count again
        let b = Search::start(&["-F", "nothing-matches-this"], Stdio::null());
        b.next();
        b.signal("-STOP");
        a.signal("-CONT");
        let mut joined = false;
        while let Ok((n, _)) = a.lines.recv_timeout(Duration::from_secs(60)) {
            if n == first.0 + 1 {
                joined = true;
                break;
            }
        }
        // killed after a stop and a continue: nothing of it may stay in the count
        a.try_signal("-KILL");
        a.finish();
        b.signal("-KILL");
        b.finish();
        let (after, _) = probe();
        seen.push((alone, while_stopped, joined, after));
        if while_stopped == alone && joined && after == alone {
            return;
        }
    }
    panic!("(alone, stopped with Ctrl-Z, joined again, after both were killed): {seen:?}");
}

#[test]
fn a_search_stopped_and_continued_prints_what_it_would_have() {
    let _one = lock();
    let run = |stop: bool| {
        let file = std::env::temp_dir().join(format!("scrutate_running_out_{}_{stop}", std::process::id()));
        let a = Search::start(&["-F", "needle"], Stdio::from(std::fs::File::create(&file).unwrap()));
        let mut stops = 0;
        if stop {
            a.next();
            while stops < 3 && a.try_signal("-TSTP") {
                match stop_seen(a.child.id()) {
                    Stop::Stopped => {}
                    // it finished between the last continue and this stop
                    Stop::Ended => break,
                    Stop::Neither => panic!("the search neither stopped nor ended"),
                }
                a.signal("-CONT");
                stops += 1;
            }
            assert!(stops > 0, "the search ended before it could be stopped");
        }
        let mut a = a;
        assert!(a.child.wait().unwrap().success());
        let mut lines: Vec<String> = std::fs::read_to_string(&file).unwrap().lines().map(str::to_owned).collect();
        let _ = std::fs::remove_file(&file);
        lines.sort();
        lines
    };
    let whole = run(false);
    assert_eq!(whole.len(), 8000);
    assert!(run(true) == whole, "the output of a search stopped three times differs");
}

#[test]
fn searches_started_together_share_and_take_back_the_threads() {
    let _one = lock();
    let (alone, full) = probe();
    let a = Search::start(&["-F", "nothing-matches-this"], Stdio::null());
    let first = a.next();
    // stopped right after it counted itself: the next one starts before it looks again
    a.signal("-STOP");
    held(&a, "the first search");
    let b = Search::start(&["-F", "nothing-matches-this"], Stdio::null());
    let (k, t) = b.next();
    assert!(k > first.0, "{k} searches seen after {first:?}");
    b.signal("-STOP");
    a.signal("-CONT");
    let seen = a.finish();
    assert!(seen.iter().any(|&(n, threads)| n > first.0 && threads < full), "the first search saw the second and took fewer threads: {seen:?}");
    b.signal("-CONT");
    let seen = b.finish();
    // with the first one ended, the second takes its threads back
    if k == alone + 1 && full > 1 {
        assert!(seen.iter().any(|&(n, threads)| n < k && threads > t), "{seen:?} after ({k}, {t})");
    }
}

#[test]
fn a_search_blocked_on_its_output_gives_way() {
    let _one = lock();
    let (alone, full) = probe();
    // nobody reads this pipe: the search fills it and waits
    let a = Search::start(&["-F", "needle"], Stdio::piped());
    a.next();
    let mut seen = Vec::new();
    for _ in 0..100 {
        let p = probe();
        seen.push(p);
        if p == (alone, full) {
            break;
        }
        std::thread::sleep(Duration::from_millis(50));
    }
    let mut a = a;
    assert!(a.child.try_wait().unwrap().is_none(), "the blocked search went on");
    assert_eq!(seen.last(), Some(&(alone, full)), "probes while the first search waited on its reader: {seen:?}");
    a.child.kill().unwrap();
    a.finish();
}

//! Every language sample must yield exactly the symbols recorded in tests/samples/expected.json.
//! Run with UPDATE_EXPECTED=1 to re-record after an intentional rule change (review the diff!).

use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

use scrutate::parse::parse_source;

#[test]
fn samples_yield_the_recorded_symbols() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/samples");
    let expected_path = dir.join("expected.json");
    let mut got: BTreeMap<String, Vec<(String, String)>> = BTreeMap::new();
    for entry in fs::read_dir(&dir).unwrap() {
        let p = entry.unwrap().path();
        let name = p.file_name().unwrap().to_string_lossy().into_owned();
        if name == "expected.json" {
            continue;
        }
        let src = fs::read_to_string(&p).unwrap();
        let chunks = parse_source(&name, &src);
        got.insert(name, chunks.iter().map(|c| (c.kind.to_string(), c.qualname.clone())).collect());
    }
    if std::env::var("UPDATE_EXPECTED").is_ok() {
        fs::write(&expected_path, serde_json::to_string_pretty(&got).unwrap()).unwrap();
        return;
    }
    let expected: BTreeMap<String, Vec<(String, String)>> =
        serde_json::from_str(&fs::read_to_string(&expected_path).expect("expected.json (run with UPDATE_EXPECTED=1 once)")).unwrap();
    let mut failures = Vec::new();
    for (name, chunks) in &got {
        match expected.get(name) {
            Some(e) if e == chunks => {}
            Some(e) => failures.push(format!("{name}: expected {e:?}\n   got {chunks:?}")),
            None => failures.push(format!("{name}: no expectation recorded")),
        }
    }
    for name in expected.keys() {
        if !got.contains_key(name) {
            failures.push(format!("{name}: sample missing"));
        }
    }
    assert!(failures.is_empty(), "symbol regressions:\n{}", failures.join("\n"));
    assert!(got.len() >= 60, "fewer samples than expected: {}", got.len());
}

/// `languages --json` must name every kind the index gives a language's sample.
#[test]
fn the_registry_names_every_kind_a_sample_yields() {
    let mut missing = Vec::new();
    for sub in ["tests/samples", "tests/samples_extra"] {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join(sub);
        for entry in fs::read_dir(&dir).unwrap() {
            let p = entry.unwrap().path();
            let name = p.file_name().unwrap().to_string_lossy().into_owned();
            let Ok(src) = fs::read_to_string(&p) else { continue };
            let Some(spec) = scrutate::parse::spec_for(&name, &src) else { continue };
            let known = scrutate::langs::definition_kinds(spec);
            for c in parse_source(&name, &src) {
                if !matches!(c.kind, "module" | "window") && !known.contains(&c.kind) {
                    missing.push(format!("{}: {} ({name})", spec.id, c.kind));
                }
            }
        }
    }
    missing.sort();
    missing.dedup();
    assert!(missing.is_empty(), "kinds the registry does not name:\n{}", missing.join("\n"));
}

