    second.stop();
    assert_eq!(r.through(&["symbol", "helper"], &[]).1, "[scrutate] session: answered by the session");
    first.stop();
    assert!(!r.socket().exists(), "the server that made the socket removes it at its exit");
    assert_eq!(r.through(&["symbol", "helper"], &[]).1, "");
}

