/// The output of `argv`, or `None` when it did not finish within `limit`.
fn run_for(c: &mut Command, limit: Duration) -> Option<String> {
    let mut child = c.stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().ok()?;
    let start = Instant::now();
    loop {
        if child.try_wait().ok()?.is_some() {
            let mut out = String::new();
            child.stdout.take()?.read_to_string(&mut out).ok()?;
            let mut err = String::new();
            child.stderr.take()?.read_to_string(&mut err).ok()?;
            return Some(out + &err);
        }
        if start.elapsed() > limit {
            let _ = child.kill();
            let _ = child.wait();
            return None;
        }
        std::thread::sleep(Duration::from_millis(100));
    }
}

/// The installed program `name`, by the PATH of the tests, with its directory as PATH (a Node
/// program finds `node` there).
fn installed(name: &str) -> Option<(String, String)> {
    let env_name = format!("SCRUTATE_TEST_{}", name.to_uppercase().replace('-', "_"));
    let found = std::env::var_os(&env_name)
        .map(PathBuf::from)
        .filter(|p| p.is_file())
        .or_else(|| std::env::split_paths(&std::env::var_os("PATH")?).map(|d| d.join(name)).find(|p| p.is_file()));
    match found {
        Some(p) => {
            let dir = p.parent().unwrap().to_str().unwrap().to_string();
            let node = std::env::split_paths(&std::env::var_os("PATH").unwrap_or_default()).find(|d| d.join("node").is_file());
            let node = node.map(|d| format!("{}:", d.display())).unwrap_or_default();
            Some((p.to_str().unwrap().to_string(), format!("{dir}:{node}/usr/bin:/bin")))
        }
        None => {
            eprintln!("skipped: {name} is not installed (or set {env_name})");
            None
        }
    }
}

#[test]
fn each_installed_agent_lists_the_server() {
    let s = Scratch::new("listing");
    let limit = Duration::from_secs(90);
    if let Some((claude, path)) = installed("claude") {
        let (code, out, err) = s.setup_in(&s.repo, &["claude"], &path);
        assert_eq!(code, 0, "{err}");
        assert!(out.contains("claude mcp add-json scrutate"), "setup runs claude's own command: {out}");
        let listed = run_for(s.command(&claude, &path).args(["mcp", "list"]), limit).expect("claude mcp list finishes");
        assert!(listed.lines().any(|l| l.starts_with("scrutate:") && l.contains("Connected")), "{listed}");
        let (code, _, err) = s.setup_in(&s.repo, &["claude"], &path);
        assert_eq!(code, 0, "{err}");
        let (code, _, err) = s.setup_in(&s.repo, &["claude", "--uninstall"], &path);
        assert_eq!(code, 0, "{err}");
        let listed = run_for(s.command(&claude, &path).args(["mcp", "list"]), limit).unwrap();
        assert!(!listed.contains("scrutate:"), "{listed}");
    }
    if let Some((codex, path)) = installed("codex") {
        assert_eq!(s.setup(&["codex"]).0, 0);
        let listed = run_for(s.command(&codex, &path).args(["mcp", "list"]), limit).expect("codex mcp list finishes");
        assert!(listed.lines().any(|l| l.starts_with("scrutate") && l.contains(&bin()) && l.contains("enabled")), "{listed}");
    }
    if let Some((cursor, path)) = installed("cursor-agent") {
        assert_eq!(s.setup(&["cursor"]).0, 0);
        let listed = run_for(s.command(&cursor, &path).args(["mcp", "list"]), limit).expect("cursor-agent mcp list finishes");
        assert!(listed.lines().any(|l| l.contains("scrutate") && l.contains("ready")), "{listed}");
    }
    if let Some((opencode, path)) = installed("opencode") {
        assert_eq!(s.setup(&["opencode"]).0, 0);
        // opencode 2 lists through a background service, which answers before it has read the
        // configuration for a moment after it starts
        let mut listed = run_for(s.command(&opencode, &path).args(["mcp", "list"]), limit);
        for _ in 0..10 {
            if !listed.as_deref().is_some_and(|l| l.contains("No MCP servers configured")) {
                break;
            }
            std::thread::sleep(Duration::from_secs(1));
            listed = run_for(s.command(&opencode, &path).args(["mcp", "list"]), limit);
        }
        let _ = run_for(s.command(&opencode, &path).args(["service", "stop"]), Duration::from_secs(20));
        let listed = listed.expect("opencode mcp list finishes");
        assert!(listed.contains("scrutate") && listed.contains("connected"), "{listed}");
    }
    if let Some((gemini, path)) = installed("gemini") {
        assert_eq!(s.setup(&["gemini"]).0, 0);
        // trust is the user's to give: the test gives it for its scratch folder
        s.write(&s.home.join(".gemini/trustedFolders.json"), &format!("{{\"{}\": \"TRUST_FOLDER\"}}", s.repo.display()));
        let listed = run_for(s.command(&gemini, &path).args(["mcp", "list"]), limit).expect("gemini mcp list finishes");
        assert!(listed.contains("scrutate") && listed.contains("Connected"), "{listed}");
    }
}

//! The order of `find_symbol` answers: the name as typed before its case-folded namesakes, types
//! before functions, test files last within each, a definition before its prototype.

use std::fs;
use std::path::PathBuf;

struct Repo {
    root: PathBuf,
    s: scrutate::search::Searcher,
}

impl Repo {
    fn new(name: &str, files: &[(String, String)]) -> Repo {
        let root = std::env::temp_dir().join(format!("scrutate_symorder_{name}_{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        for (rel, body) in files {
            let p = root.join(rel);
            fs::create_dir_all(p.parent().unwrap()).unwrap();
            fs::write(&p, body).unwrap();
        }
        let root = fs::canonicalize(&root).unwrap();
        let s = scrutate::open_updated(&root, true).unwrap().0.into_searcher();
        Repo { root, s }
    }

    /// (kind, qualname, path) of each answer
    fn symbol(&self, name: &str, limit: usize) -> Vec<(String, String, String)> {
        self.s.find_symbol(name, limit).unwrap().into_iter().map(|h| (h.kind, h.qualname, h.path)).collect()
    }
}

impl Drop for Repo {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.root);
    }
}

fn file(rel: &str, body: &str) -> (String, String) {
    (rel.to_string(), body.to_string())
}

#[test]
fn the_name_as_typed_comes_before_thirty_case_folded_namesakes() {
    let mut files: Vec<(String, String)> = (0..30).map(|i| file(&format!("src/m{i:02}.rs"), "pub fn error() -> u8 { 1 }\n")).collect();
    files.push(file("src/zz.rs", "pub struct Error { pub code: u8 }\n"));
    let r = Repo::new("thirty", &files);
    let got = r.symbol("Error", 20);
    assert_eq!(got.len(), 20);
    assert_eq!(got[0], ("struct".into(), "Error".into(), "src/zz.rs".into()), "{got:?}");
    assert!(got[1..].iter().all(|(k, q, _)| k == "function" && q == "error"), "{got:?}");
    // the folded lookup still finds the other spelling, after the exact one
    let lower = r.symbol("error", 40);
    assert_eq!(lower.len(), 31);
    assert!(lower[..30].iter().all(|(_, q, _)| q == "error"), "{lower:?}");
    assert_eq!(lower[30].1, "Error");
}

#[test]
fn a_constant_comes_before_a_method_whose_name_differs_in_case() {
    let java = "public class Config {\n    public static final int MAX = 5;\n    public int max() { return MAX; }\n}\n";
    let r = Repo::new("max", &[file("Config.java", java)]);
    let kinds = |n: &str| r.symbol(n, 20).into_iter().map(|(k, q, _)| (k, q)).collect::<Vec<_>>();
    let want = vec![("constant".to_string(), "Config.MAX".to_string()), ("method".to_string(), "Config.max".to_string())];
    assert_eq!(kinds("MAX"), want);
    assert_eq!(kinds("Config.MAX"), want);
    assert_eq!(kinds("max"), want.into_iter().rev().collect::<Vec<_>>());
}

#[test]
fn a_struct_comes_before_a_function_of_the_same_name() {
    let r = Repo::new("stat", &[file("a.c", "int stat(const char *p) { return 0; }\n"), file("b.c", "struct stat { int size; };\n")]);
    let got = r.symbol("stat", 20);
    assert_eq!(got.iter().map(|(k, _, p)| (k.as_str(), p.as_str())).collect::<Vec<_>>(), vec![("struct", "b.c"), ("function", "a.c")]);
}

#[test]
fn test_files_come_last_within_the_exact_and_the_folded_answers() {
    let r = Repo::new(
        "tests",
        &[file("tests/t.rs", "pub struct Error;\npub fn error() {}\n"), file("src/a.rs", "pub fn error() {}\n"), file("src/b.rs", "pub enum Error { A }\n")],
    );
    let got: Vec<(String, String)> = r.symbol("Error", 20).into_iter().map(|(_, q, p)| (q, p)).collect();
    let want = [("Error", "src/b.rs"), ("Error", "tests/t.rs"), ("error", "src/a.rs"), ("error", "tests/t.rs")];
    assert_eq!(got, want.map(|(q, p)| (q.to_string(), p.to_string())));
}

#[test]
fn a_definition_comes_before_its_prototype() {
    let r = Repo::new("proto", &[file("a.h", "int add(int a, int b);\n"), file("b.c", "int add(int a, int b) { int total = a + b; return total; }\n")]);
    let got = r.symbol("add", 20);
    assert_eq!(got.iter().map(|(_, _, p)| p.as_str()).collect::<Vec<_>>(), vec!["b.c", "a.h"]);
}

//! The text index across updates that go wrong or come often: a manifest cut short, a liveness
//! file left by a failed update, and many small updates beside one large segment.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

const BIN: &str = env!("CARGO_BIN_EXE_scrutate");

struct Tmp(PathBuf);

impl Tmp {
    fn new(name: &str) -> Tmp {
        let p = std::env::temp_dir().join(format!("scrutate_text_index_{}_{}", name, std::process::id()));
        let _ = fs::remove_dir_all(&p);
        fs::create_dir_all(&p).unwrap();
        Tmp(fs::canonicalize(&p).unwrap())
    }
}

impl Drop for Tmp {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

/// (exit code, stdout, stderr)
fn run(root: &Path, args: &[&str]) -> (i32, String, String) {
    let out = Command::new(BIN).arg("--root").arg(root).args(args).stdin(Stdio::null()).output().unwrap();
    (out.status.code().unwrap_or(-1), String::from_utf8_lossy(&out.stdout).into_owned(), String::from_utf8_lossy(&out.stderr).into_owned())
}

fn segments(root: &Path) -> Vec<String> {
    let m: serde_json::Value = serde_json::from_slice(&fs::read(root.join(".scrutate/text/manifest.json")).unwrap()).unwrap();
    m["segments"].as_array().unwrap().iter().map(|s| s["name"].as_str().unwrap().to_string()).collect()
}

/// The lines `grep --index -c` prints, sorted.
fn counts(root: &Path, pattern: &str) -> Vec<String> {
    let (code, out, err) = run(root, &["grep", "--index", "-c", pattern]);
    assert!(code == 0 || code == 1, "{err}");
    let mut lines: Vec<String> = out.lines().map(str::to_string).collect();
    lines.sort();
    lines
}

#[test]
fn a_manifest_cut_short_is_rebuilt_by_the_next_update() {
    let t = Tmp::new("manifest");
    fs::write(t.0.join("a.py"), "def alpha():\n    return 1\n").unwrap();
    assert_eq!(run(&t.0, &["index", "--text"]).0, 0);
    let manifest = t.0.join(".scrutate/text/manifest.json");
    for cut in ["", "{\"format\":"] {
        fs::write(&manifest, cut).unwrap();
        // a search cannot write the index: it says what to run
        let (code, _, err) = run(&t.0, &["grep", "--index", "alpha"]);
        assert_eq!(code, 2, "{err}");
        assert!(err.contains("index --text"), "{err}");
        let (code, _, err) = run(&t.0, &["index", "--text"]);
        assert_eq!(code, 0, "{err}");
        assert!(err.contains("damaged") && err.contains("rebuilding"), "{err}");
        assert_eq!(counts(&t.0, "alpha"), ["a.py:1"]);
    }
}

#[test]
fn a_liveness_file_left_by_a_failed_update_is_written_again() {
    let t = Tmp::new("live");
    fs::write(t.0.join("a.py"), "def alpha():\n    return 1\n").unwrap();
    fs::write(t.0.join("b.py"), "def beta():\n    return alpha()\n").unwrap();
    // enough other documents that one dead one starts no merge
    for i in 0..10 {
        fs::write(t.0.join(format!("other{i}.txt")), format!("nothing {i}\n")).unwrap();
    }
    assert_eq!(run(&t.0, &["index", "--text"]).0, 0);
    let seg = t.0.join(".scrutate/text").join(&segments(&t.0)[0]);
    // what an update that stopped before its manifest leaves: the next generation's liveness
    // file, with every document of the segment still live
    fs::copy(seg.join("live-00000001.bin"), seg.join("live-00000002.bin")).unwrap();
    fs::write(t.0.join("a.py"), "def alpha():\n    return 22\n").unwrap();
    assert_eq!(run(&t.0, &["index", "--text"]).0, 0);
    assert_eq!(segments(&t.0).len(), 2);
    assert_eq!(counts(&t.0, "alpha"), ["a.py:1", "b.py:1"]);
    let (_, out, _) = run(&t.0, &["grep", "--index", "return"]);
    let mut lines: Vec<&str> = out.lines().collect();
    lines.sort();
    assert_eq!(lines, ["a.py:2:    return 22", "b.py:2:    return alpha()"]);
}

#[test]
fn small_updates_do_not_write_the_large_segment_again() {
    let t = Tmp::new("merge");
    for i in 0..60 {
        fs::write(t.0.join(format!("f{i:02}.py")), format!("def fn_{i}():\n    return {i}\n")).unwrap();
    }
    assert_eq!(run(&t.0, &["index", "--text"]).0, 0);
    let first = segments(&t.0);
    assert_eq!(first.len(), 1);
    for round in 0..9 {
        fs::write(t.0.join(format!("f{round:02}.py")), format!("def fn_{round}():\n    return {round} + {round}\n# round {round}\n")).unwrap();
        assert_eq!(run(&t.0, &["index", "--text"]).0, 0);
        let now = segments(&t.0);
        assert!(now.contains(&first[0]), "round {round}: the segment of the first build is gone: {now:?}");
        assert!(now.len() <= 5, "round {round}: {now:?}");
    }
    // every file is found once, the changed ones in their new text
    assert_eq!(counts(&t.0, "def fn_").len(), 60);
    assert_eq!(counts(&t.0, "# round").len(), 9);
    // when most documents of the large segment are dead, everything is merged into one
    for i in 0..40 {
        fs::write(t.0.join(format!("f{i:02}.py")), format!("def fn_{i}():\n    return 0\n# again {i}\n")).unwrap();
    }
    assert_eq!(run(&t.0, &["index", "--text"]).0, 0);
    let now = segments(&t.0);
    assert!(!now.contains(&first[0]) && now.len() == 1, "{now:?}");
    assert_eq!(counts(&t.0, "def fn_").len(), 60);
    assert_eq!(counts(&t.0, "# again").len(), 40);
}

/// Overwrite the element `back` places before the end of a little-endian `.npy` array of 4- or
/// 8-byte elements.
fn patch_npy(path: &Path, back: usize, value: i64) {
    let mut b = fs::read(path).unwrap();
    let len_size = if b[6] == 1 { 2 } else { 4 };
    let hlen = b[8..8 + len_size].iter().rev().fold(0usize, |a, &x| a * 256 + x as usize);
    let data = 8 + len_size + hlen;
    let header = String::from_utf8_lossy(&b[..data]).into_owned();
    let w = if header.contains("<i8") || header.contains("<u8") { 8 } else { 4 };
    let i = (b.len() - data) / w - back;
    b[data + i * w..data + (i + 1) * w].copy_from_slice(&value.to_le_bytes()[..w]);
    fs::write(path, b).unwrap();
}

#[test]
fn a_posting_pointer_past_the_data_is_rebuilt_by_the_merge_of_the_next_update() {
    let t = Tmp::new("bad_ptr");
    fs::write(t.0.join("a.txt"), "hello world\n").unwrap();
    fs::write(t.0.join("b.txt"), "other words\n").unwrap();
    assert_eq!(run(&t.0, &["index", "--text"]).0, 0);
    let seg = t.0.join(".scrutate/text").join(&segments(&t.0)[0]);
    let post = fs::metadata(seg.join("post.bin")).unwrap().len();
    // the start of the last posting list past the end of the data
    patch_npy(&seg.join("ptr.npy"), 2, post as i64 + 1000);
    // one of three documents dead: the update merges the segments
    fs::write(t.0.join("a.txt"), "hello again\n").unwrap();
    let (code, _, err) = run(&t.0, &["index", "--text"]);
    assert!(!err.contains("internal error"), "{err}");
    assert_eq!(code, 0, "{err}");
    assert_eq!(counts(&t.0, "hello"), ["a.txt:1"]);
    assert_eq!(counts(&t.0, "words"), ["b.txt:1"]);
}

// the write moves the change time, which no one can set back; Windows has none to compare
#[cfg(unix)]
#[test]
fn an_edit_that_keeps_size_and_mtime_is_seen() {
    let t = Tmp::new("samestat");
    let f = t.0.join("a.txt");
    fs::write(&f, "hello world\n").unwrap();
    let mtime = fs::metadata(&f).unwrap().modified().unwrap();
    assert_eq!(run(&t.0, &["index", "--text"]).0, 0);
    fs::write(&f, "jello world\n").unwrap();
    fs::File::options().write(true).open(&f).unwrap().set_modified(mtime).unwrap();
    let (code, out, err) = run(&t.0, &["grep", "--index", "--update", "jello"]);
    assert_eq!((code, out.as_str()), (0, "a.txt:1:jello world\n"), "{err}");
}

fn set_format(root: &Path, format: u64) {
    let p = root.join(".scrutate/text/manifest.json");
    let mut m: serde_json::Value = serde_json::from_slice(&fs::read(&p).unwrap()).unwrap();
    m["format"] = format.into();
    fs::write(&p, serde_json::to_vec(&m).unwrap()).unwrap();
}

#[test]
fn an_index_of_the_previous_format_is_rebuilt_by_the_next_update_and_a_newer_one_is_refused() {
    let t = Tmp::new("format");
    fs::write(t.0.join("a.txt"), "hello world\n").unwrap();
    assert_eq!(run(&t.0, &["index", "--text"]).0, 0);
    set_format(&t.0, 2);
    // a search cannot write the index: it says what to run
    let (code, _, err) = run(&t.0, &["grep", "--index", "hello"]);
    assert_eq!(code, 2, "{err}");
    assert!(err.contains("index --text"), "{err}");
    let (code, out, err) = run(&t.0, &["index", "--text"]);
    assert_eq!(code, 0, "{err}");
    assert!(out.contains("1 changed"), "{out}{err}");
    assert_eq!(counts(&t.0, "hello"), ["a.txt:1"]);
    set_format(&t.0, 2);
    let (code, out, err) = run(&t.0, &["grep", "--index", "--update", "hello"]);
    assert_eq!((code, out.as_str()), (0, "a.txt:1:hello world\n"), "{err}");
    set_format(&t.0, 4);
    for args in [&["grep", "--index", "hello"][..], &["index", "--text"]] {
        let (code, _, err) = run(&t.0, args);
        assert_eq!(code, 2, "{args:?}: {err}");
        assert!(err.contains("newer scrutate"), "{args:?}: {err}");
    }
}

/// `batch` with the lines of `ops`, as an MCP client asks; the query file lies outside the tree.
fn batch(root: &Path, name: &str, ops: &str) -> (i32, String, String) {
    let q = std::env::temp_dir().join(format!("scrutate_text_index_q_{name}_{}.jsonl", std::process::id()));
    fs::write(&q, ops).unwrap();
    let r = run(root, &["batch", q.to_str().unwrap()]);
    let _ = fs::remove_file(&q);
    r
}

#[test]
fn a_reindex_brings_the_text_index_up_to_date_too() {
    let t = Tmp::new("reindex");
    fs::write(t.0.join("a.py"), "def one():\n    return 1\n").unwrap();
    assert_eq!(run(&t.0, &["index"]).0, 0);
    fs::write(t.0.join("b.py"), "zzqtoken = 1\n").unwrap();
    let (code, out, err) = batch(&t.0, "reindex", "{\"op\": \"reindex\"}\n");
    assert_eq!(code, 0, "{out}{err}");
    let (code, out, err) = run(&t.0, &["grep", "--index", "-n", "zzqtoken"]);
    assert_eq!((code, out.as_str()), (0, "b.py:1:zzqtoken = 1\n"), "{err}");
}

#[test]
fn a_reindex_keeps_no_text_index_where_there_is_none_and_rebuilds_a_damaged_one() {
    let t = Tmp::new("reindex_keep");
    fs::write(t.0.join("a.py"), "def alpha():\n    return 1\n").unwrap();
    assert_eq!(run(&t.0, &["index", "--no-text"]).0, 0);
    assert_eq!(batch(&t.0, "keep_none", "{\"op\": \"reindex\"}\n").0, 0);
    assert!(!t.0.join(".scrutate/text").exists(), "a reindex made a text index");
    assert_eq!(run(&t.0, &["index", "--text"]).0, 0);
    fs::write(t.0.join(".scrutate/text/manifest.json"), "").unwrap();
    let (code, _, err) = batch(&t.0, "keep_damaged", "{\"op\": \"reindex\"}\n");
    assert_eq!(code, 0, "{err}");
    assert!(err.contains("text index damaged") && err.contains("rebuilding"), "{err}");
    assert_eq!(counts(&t.0, "alpha"), ["a.py:1"]);
}

//! What the training scripts read from the binary: `batch --features` (the ranker's rows) and the
//! hidden `views` command (the vector model's chunks, view tokens and query terms).

use std::fs;
use std::path::PathBuf;
use std::process::{Command, Stdio};

const BIN: &str = env!("CARGO_BIN_EXE_scrutate");

fn tree(name: &str, files: &[(&str, &str)]) -> PathBuf {
    let root = std::env::temp_dir().join(format!("scrutate_training_{}_{}", name, std::process::id()));
    let _ = fs::remove_dir_all(&root);
    for (rel, text) in files {
        let p = root.join(rel);
        fs::create_dir_all(p.parent().unwrap()).unwrap();
        fs::write(p, text).unwrap();
    }
    root
}

fn run(root: &PathBuf, args: &[&str]) -> Vec<serde_json::Value> {
    let out = Command::new(BIN).arg("--root").arg(root).args(args).stdin(Stdio::null()).env("SCRUTATE_SEMANTIC", "none").output().unwrap();
    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
    String::from_utf8(out.stdout).unwrap().lines().map(|l| serde_json::from_str(l).unwrap()).collect()
}

const SHOP: &str = "class Order:\n    def total(self):\n        \"\"\"Sum of the lines.\"\"\"\n        return 1\n\n\ndef total_price():\n    return 2\n";

#[test]
fn batch_features_name_every_feature_once_per_query() {
    let root = tree("features", &[("shop.py", SHOP)]);
    let q = root.join("q.jsonl");
    fs::write(&q, "{\"query\": \"total\", \"k\": 3}\n").unwrap();
    let rec = &run(&root, &["batch", "--features", q.to_str().unwrap()])[0];
    let names: Vec<&str> = rec["feature_names"].as_array().unwrap().iter().map(|v| v.as_str().unwrap()).collect();
    assert_eq!(names, scrutate::search::FEATURES);
    let cands = rec["candidates"].as_array().unwrap();
    let total = cands.iter().find(|c| c["qualname"] == "Order.total").expect("Order.total is a candidate");
    assert_eq!((total["name"].as_str(), total["kind"].as_str()), (Some("total"), Some("method")));
    let x = total["x"].as_array().unwrap();
    assert_eq!(x.len(), names.len());
    let at = |n: &str| x[names.iter().position(|f| *f == n).unwrap()].as_f64().unwrap();
    assert_eq!((at("exact_name"), at("k_method"), at("has_doc")), (1.0, 1.0, 1.0));
    for key in ["exact_ids", "lex_ids", "sem_ids"] {
        assert!(rec[key].is_array(), "{key}: {rec}");
    }
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn views_print_the_chunks_of_a_file_and_the_terms_of_a_query() {
    let root = tree("views", &[("src/shop.py", SHOP)]);
    let q = root.join("q.jsonl");
    let file = root.join("src/shop.py");
    let req = serde_json::json!({"file": file, "path": "shop.py"});
    fs::write(&q, format!("{req}\n{{\"query\": \"sum the order lines\"}}\n{{\"file\": \"missing.py\", \"path\": \"missing.py\"}}\n")).unwrap();
    let recs = run(&root, &["views", q.to_str().unwrap()]);
    assert_eq!(recs.len(), 3);
    assert_eq!(recs[0]["path"], "shop.py");
    let total = recs[0]["chunks"].as_array().unwrap().iter().find(|c| c["qualname"] == "Order.total").expect("Order.total");
    assert_eq!(total["kind"], "method");
    assert_eq!(total["doc"], "Sum of the lines.");
    assert_eq!(total["views"]["name"], serde_json::json!(scrutate::text::tokenize2("total", None).0));
    assert_eq!(total["views"]["qual"], serde_json::json!(scrutate::text::tokenize2("Order", None).0));
    assert_eq!(recs[1]["terms"], serde_json::json!(scrutate::text::query_terms("sum the order lines")));
    assert!(recs[2]["error"].is_string() && recs[2].get("chunks").is_none(), "{}", recs[2]);
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn views_read_given_text_and_print_a_files_language_test_flag_subwords_and_stop_list() {
    let root = tree("views_text", &[("keep.txt", "")]);
    let q = root.join("q.jsonl");
    let reqs = [
        serde_json::json!({"text": "/// Adds two numbers.\npub fn add(a: i64, b: i64) -> i64 {\n    a + b\n}\n", "path": "src/math_test.rs"}),
        serde_json::json!({"text": "export function total() { return 1; }\n", "path": "lib/shop.ts"}),
        serde_json::json!({"split": "parseHTTPResponse_v2"}),
        serde_json::json!({"stopwords": true}),
    ];
    fs::write(&q, reqs.iter().map(|r| format!("{r}\n")).collect::<String>()).unwrap();
    let recs = run(&root, &["views", q.to_str().unwrap()]);
    assert_eq!((recs[0]["lang"].as_str(), recs[0]["test"].as_bool()), (Some("rust"), Some(true)));
    let add = recs[0]["chunks"].as_array().unwrap().iter().find(|c| c["name"] == "add").expect("add");
    assert_eq!((add["kind"].as_str(), add["start"].as_u64(), add["doc"].as_str()), (Some("function"), Some(2), Some("Adds two numbers.")));
    assert_eq!((recs[1]["lang"].as_str(), recs[1]["test"].as_bool()), (Some("typescript"), Some(false)));
    assert_eq!(recs[2]["subwords"], serde_json::json!(scrutate::text::raw_subwords("parseHTTPResponse_v2")));
    let stop: Vec<&str> = recs[3]["stopwords"].as_array().unwrap().iter().map(|v| v.as_str().unwrap()).collect();
    assert!(stop.windows(2).all(|w| w[0] < w[1]), "sorted, each once");
    assert_eq!(stop.len(), scrutate::text::QUERY_STOP.len());
    assert!(stop.iter().all(|w| scrutate::text::QUERY_STOP.contains(w)));
    let _ = fs::remove_dir_all(&root);
}

//! Text that is not Latin script: search by words of every script, names compared in NFC, and
//! definitions with very long names.

use std::fs;
use std::path::PathBuf;
use std::process::{Command, Stdio};

use scrutate::text::{name_key, query_terms, tokenize2};

const BIN: &str = env!("CARGO_BIN_EXE_scrutate");

struct Repo {
    root: PathBuf,
}

impl Repo {
    fn new(name: &str, files: &[(&str, String)]) -> Repo {
        let root = std::env::temp_dir().join(format!("scrutate_unicode_{}_{}", name, std::process::id()));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).unwrap();
        for (rel, text) in files {
            fs::write(root.join(rel), text).unwrap();
        }
        let r = Repo { root };
        let (code, _, err) = r.run(&["index", "--no-text"]);
        assert_eq!(code, 0, "{err}");
        r
    }
    fn run(&self, args: &[&str]) -> (i32, String, String) {
        let out = Command::new(BIN).args(args).current_dir(&self.root).stdin(Stdio::null()).output().expect("run scrutate");
        (out.status.code().unwrap_or(-1), String::from_utf8_lossy(&out.stdout).into_owned(), String::from_utf8_lossy(&out.stderr).into_owned())
    }
    fn top(&self, cmd: &str, q: &str) -> String {
        let (code, out, err) = self.run(&[cmd, q]);
        // 1 is "no results"
        assert!(code == 0 || code == 1, "{cmd} {q}: {err}");
        out
    }
}

impl Drop for Repo {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.root);
    }
}

const SCRIPTS: &str = r#"def calc_total(items):
    """计算订单总价，包括税费和运费。"""
    return 1


def 関数():
    """注文の合計金額を計算する"""
    return 2


def выручка():
    """Вычисляет общую выручку за период"""
    return 3


def korean_total():
    """주문 총액을 계산합니다"""
    return 4


def arabic_total():
    """يحسب إجمالي الطلب"""
    return 5


def parse_config(path):
    """Read the configuration file."""
    return path
"#;

#[test]
fn queries_in_every_script_find_the_function() {
    let r = Repo::new("scripts", &[("m.py", SCRIPTS.to_string())]);
    let cases = [
        ("计算订单总价", "calc_total"),
        ("订单", "calc_total"),
        ("関数", "関数"),
        ("注文の合計金額", "関数"),
        ("合計", "関数"),
        ("выручка", "выручка"),
        ("общую выручку", "выручка"),
        ("Вычисляет", "выручка"),
        ("주문 총액", "korean_total"),
        ("계산합니다", "korean_total"),
        ("إجمالي الطلب", "arabic_total"),
    ];
    let mut missed = Vec::new();
    for (q, want) in cases {
        let out = r.top("search", q);
        let first = out.lines().next().unwrap_or("");
        if !first.ends_with(&format!("] {want}")) {
            missed.push(format!("{q} -> {first:?}"));
        }
    }
    assert!(missed.is_empty(), "{missed:#?}");
    assert!(r.top("search", "read configuration file").lines().next().unwrap().ends_with("] parse_config"));
}

#[test]
fn ascii_tokens_are_unchanged() {
    let (s, w) = tokenize2("def parseHTTPResponse_v2(self): 2fa refreshing tokens", None);
    assert_eq!(s, vec!["pars", "http", "respons", "v", "fa", "refresh", "token"].into_iter().filter(|t| *t != "v").collect::<Vec<_>>());
    assert_eq!(w, vec!["parsehttpresponsev"]);
    assert_eq!(query_terms("where is the oauth token refreshed?"), vec!["oauth", "token", "refresh"]);
}

#[test]
fn unspaced_scripts_are_bigrams_and_spaced_scripts_are_words() {
    assert_eq!(tokenize2("订单总价", None).0, vec!["订单", "单总", "总价"]);
    assert_eq!(tokenize2("税", None).0, vec!["税"]);
    assert_eq!(tokenize2("Вычисляет ОБЩУЮ", None).0, vec!["вычисляет", "общую"]);
    // an ASCII part of a mixed word is stemmed like any ASCII word; the rest is not
    assert_eq!(tokenize2("parsing_выручки", None).0, vec!["pars", "выручки"]);
    // Unihan gives the Japanese 関 a simplified form too (U+2CBA6)
    assert_eq!(tokenize2("x関数y", None).0, vec!["\u{2CBA6}数"]);
    assert_eq!(query_terms("合計 合計"), vec!["合计"]);
    // Thai, Lao, Myanmar, Khmer, Javanese: no spaces between words either
    for run in ["ภาษาไทย", "ພາສາລາວ", "မြန်မာစာ", "ភាសាខ្មែរ", "ꦧꦱꦗꦮ"] {
        let chars: Vec<char> = run.chars().collect();
        let pairs: Vec<String> = chars.windows(2).map(|p| p.iter().collect()).collect();
        assert_eq!(tokenize2(run, None).0, pairs, "{run}");
    }
    // Tibetan marks its syllables: the tsheg between them ends a run
    assert_eq!(tokenize2("བོད་སྐད", None).0, vec!["བོ", "ོད", "སྐ", "ྐད"]);
}

